\centerline{\large\bf 2023A\raisebox{0.3\totalheight}{\includegraphics[scale=0.40,angle=-90]{fignew/aumic2-map23a.ps}}\vspace{1mm}}
\centerline{\large\bf 2023B\raisebox{0.3\totalheight}{\includegraphics[scale=0.40,angle=-90]{fignew/aumic2-map23b.ps}}\vspace{1mm}}
\centerline{\large\bf 2024A\raisebox{0.3\totalheight}{\includegraphics[scale=0.40,angle=-90]{fignew/aumic2-map24a.ps}}\vspace{1mm}}
