\ket{a_0} &  \gate{X} & \targ{}  &  \\
\ket{q_0} & \gate{X}&  \ctrl{-1} &\\
\ket{q_1} &  \gate{I}        &     & \\
\ket{q_2} &  \gate{I}        & \octrl{-2}  &  
\end{quantikz} 
    \caption{Circuit for $\Um_l$ corresponding to the term $\Am_l = \Sm \otimes \Id \otimes \Sp\Sm$}
    \label{fig: U_eg}
