\textbf{Semi-analytical Approach:} 
Consider a linear system of ordinary differential equations (ODEs),
\begin{equation*}
\frac{d\uv}{dt} = \Am^\prime\uv+\bv^\prime,
\end{equation*}
where, $\uv(t)\in \Rr^{n_x}, t\in[0,T]$, $T\in \Rr$ is the period of integration, $\Am^\prime\in \Rr^{n_x\times n_x}$ is the system matrix, $\uv(0)=\uv_0$ is the initial condition, and $\bv^\prime\in \Rr^{n_x}$ is a constant forcing term. Using explicit Euler time discretization with step size $\Delta t$, the above ODEs can be expressed as a system of difference equations 
\begin{equation*}
\uv_{k+1} =(\Id_{n_x}+\Delta t\Am^\prime)\uv_k+\Delta t\bv^\prime, k=1,\cdots,n_t-1,
\end{equation*}
where $\uv_k=\uv((k-1)\Delta t)$ with $\Delta t=T/(n_t-1)$. The above system can be represented as an extended system of linear equations,
\begin{equation*}
\Am \uv = \bv,
\end{equation*}
where,
\begin{align}\label{eq: full_coeffod}
    \uv &= \begin{bmatrix} 
\uv_1^T & \uv_2^T & \dots & \uv^T_{n_t}
\end{bmatrix}^T \nonumber\\
\bv &= \begin{bmatrix}
\uv_0^T & \Delta t(\bv^\prime)^T & \dots & \Delta t (\bv^\prime)^T
\end{bmatrix}^T \nonumber\\
\Am &= \begin{bmatrix*}[r]
\Id_{n_x} & & & 0\\
-\Id_{n_x} & \Id_{n_x} & & \\
& \ddots & \ddots & \\
0 & & -\Id_{n_x} & \Id_{n_x}
\end{bmatrix*}- \Delta t \begin{bmatrix*}[r]
0 & & & 0\\
\Am^\prime & 0 & & \\
& \ddots & \ddots & \\
0 & & \Am^\prime & 0
\end{bmatrix*} \notag\\
&= \Am_1 - \Delta t \Am_2.
\end{align}

For simplicity assume $n_x= 2^s$ and $n_t = 2^t$. Then $\Am_1$ corresponds to $s+t$ qubits and can be written as,
\begin{align*}
 \Am_1 \coloneqq \Am_1^{(s+t)} &= \begin{bmatrix}
 \Am_1^{(s+t-1)} & 0 \\
 \Dm_1^{(s+t-1)} & \Am_1^{(s+t-1)}
 \end{bmatrix}, \\
\Dm_1^{(s+t-1)} &= \begin{bmatrix}
0 & \dots & -\Id_{n_x} \\
\vdots & \ddots & \vdots \\
0 & \dots & 0
\end{bmatrix}\\ &= \underbrace{\Sp \otimes \dots \otimes \Sp}_{t-1 \text{ times}} \otimes \Id_{n_x}.
\end{align*} 
The expression for $\Dm_1^{(s+t-1)}$ is obtained using the numerical approach. Then,
\begin{align*}
\Am_1^{(s+t)} &= \Id_2 \otimes \Am_1^{(s+t-1)} + \Sm \otimes \Dm_1^{(s+t-1)}, \\
\Am_1^{(s+1)} &= \begin{bmatrix*}[r]
\Id_{n_x} & 0\\
-\Id_{n_x} & \Id_{n_x}
\end{bmatrix*} = \Id_2 \otimes \Id_{n_x} - \Sm \otimes \Id_{n_x}. 
\end{align*}
With this recursive relation, $\Am_1$ can be written using $\log n_t + 1$ terms. To obtain decomposition of $\Am_2$, we equivalently write it as, 
\begin{align}
\Am_2=\tilde{\Id}\otimes \Am^\prime,
\end{align}
where,
\begin{align*}
\tilde{\Id}=\begin{bmatrix*}[r]
0 & & & 0\\
1 & 0 & & \\
& \ddots & \ddots & \\
0 & & 1 & 0
\end{bmatrix*}\in \Rr^{n_t\times n_t}.
\end{align*}
Applying a similar recursive procedure to $\tilde{\Id}$ as for $\Am_1$ above, we can express it as,
\begin{align*}
\tilde{\Id} \coloneqq \tilde{\Id}^{(t)} &= \begin{bmatrix}
 \tilde{\Id}^{(t-1)} & 0 \\
 \tilde{\Dm}^{(t-1)} & \tilde{\Id}^{(t-1)}
 \end{bmatrix}, \\
\tilde{\Dm}^{(t-1)} &= \begin{bmatrix}
0 & \dots & 1\\
\vdots & \ddots & \vdots \\
0 & \dots & 0
\end{bmatrix}\\ &= \underbrace{\Sp \otimes \dots \otimes \Sp}_{t-1 \text{ times}}.
\end{align*} 
Then,
\begin{align*}
\tilde{\Id}^{(t)} &= \Id_2 \otimes \tilde{\Id}^{(t-1)} + \Sm \otimes \tilde{\Dm}^{(t-1)}, \quad \tilde{\Id}^{(1)} = \Sm. 
\end{align*}
Finally, depending on the exact structure of $\Am'$, we can similarly apply a semi-analytical or numerical approach to compute its decomposition. Combining it with the decomposition of $\Am_1$ and $\tilde{\Id}$ as derived above, we  obtain the complete decomposition of $\Am$ with $L \leq (1+\text{nnz}(\Am'))(\log n_t + 1)$.

