\begin{algorithm}[t]
\caption{Point Cloud Correspondence Generation}
\label{alg:correspondence}

\KwIn{$\mathcal{P}_1, \mathcal{P}_2$: point clouds; $\mathcal{M}_1, \mathcal{M}_2$: convex maps; $\mathcal{T}$: primitive transforms; $\mathcal{C}$: centers; $d_{\max} = 0.005$: max distance threshold}
\KwOut{$\mathcal{R}$: correspondence map; $\mathcal{W}$: confidence map}

\SetKwFunction{FApplyTransform}{ApplyTransform}
\SetKwProg{Fn}{Function}{:}{}

\BlankLine
\Fn{\FApplyTransform{$\mathbf{p}$, $\mathbf{c}$, $\mathbf{T}$}}{
    $\mathbf{p}' \gets \mathbf{p} - \mathbf{c}$ \tcp*{Center the point}

    \If{$\mathbf{T}$ contains translation}{
        $\mathbf{p}' \gets \mathbf{p}' - \mathbf{T}_{\text{trans}}$\;
    }

    \If{$\mathbf{T}$ contains rotation angle $\theta$}{
        $c, s \gets \cos(-\theta), \sin(-\theta)$\;
        $x', z' \gets x' \cdot c - z' \cdot s, x' \cdot s + z' \cdot c$ \tcp*{Y-axis rotation}
    }

    \If{$\mathbf{T}$ contains scaling factor $scale$}{
        $\mathbf{p}' \gets \mathbf{p}' / scale$\;
    }

    \Return $\mathbf{p}' + \mathbf{c}$\;
}

\BlankLine
$\mathcal{R} \gets \mathbf{0}_{H \times W \times 2}$ \tcp*{Initialize correspondence map}
$\mathcal{W} \gets \mathbf{0}_{H \times W}$ \tcp*{Initialize confidence map}

\BlankLine
\For{$p \in \text{unique}(\mathcal{M}_1)$}{
    \If{$p < 0$ \textbf{or} $p \geq |\mathcal{C}|$ \textbf{or} $p \notin \mathcal{M}_1$ \textbf{or} $p \notin \mathcal{M}_2$}{
        \textbf{continue}\;
    }

    \BlankLine
    $\mathcal{I}_1 \gets \{(y,x) : \mathcal{M}_1[y,x] = p\}$ \tcp*{Pixel indices for primitive $p$ in map 1}
    $\mathcal{I}_2 \gets \{(y,x) : \mathcal{M}_2[y,x] = p\}$ \tcp*{Pixel indices for primitive $p$ in map 2}

    $\mathcal{Q}_1 \gets \{\mathcal{P}_1[y,x] : (y,x) \in \mathcal{I}_1\}$ \tcp*{3D points for primitive $p$}

    \BlankLine
    \For{$(y_2, x_2) \in \mathcal{I}_2$}{
        $\mathbf{q} \gets \mathcal{P}_2[y_2, x_2]$ \tcp*{Query point from second cloud}

        \If{$p \in \mathcal{T}$}{
            $\mathbf{q} \gets \FApplyTransform(\mathbf{q}, \mathcal{C}[p], \mathcal{T}[p])$ \tcp*{Apply transformation}
        }

        \BlankLine
        $\mathbf{d} \gets \|\mathcal{Q}_1 - \mathbf{q}\|_2$ \tcp*{Compute distances to all points}
        $i^* \gets \arg\min_i \mathbf{d}[i]$ \tcp*{Find nearest neighbor}
        $d_{\min} \gets \mathbf{d}[i^*]$\;

        \If{$d_{\min} \leq d_{\max}$}{
            $(y_1^*, x_1^*) \gets \mathcal{I}_1[i^*]$ \tcp*{Get corresponding pixel coordinates}
            $\mathcal{R}[y_2, x_2] \gets [x_1^*, y_1^*]$\;
            $\mathcal{W}[y_2, x_2] \gets 1 - \min(d_{\min} / d_{\max}, 1)$ \tcp*{Confidence score}
        }
    }
}

\BlankLine
\Return $\mathcal{R}, \mathcal{W}$\;

\end{algorithm}

\newpage

\begin{algorithm}[t]
\caption{Hint Generation from Correspondence Maps}
\label{alg:hint_generation}

\KwIn{$\mathbf{I}_{\text{src}} \in \mathbb{R}^{C \times H_s \times W_s}$: source image; $\mathcal{R} \in \mathbb{R}^{H_r \times W_r \times 2}$: correspondence map; $\mathcal{W} \in \mathbb{R}^{H_r \times W_r}$: confidence map; $\mathcal{M}_{\text{hit}} \in \{0,1\}^{H_r \times W_r}$: hit mask}
\KwOut{$\mathcal{H} \in \mathbb{R}^{C \times H_s \times W_s}$: generated hint image}

\SetKwFunction{FBilinear}{BilinearSample}
\SetKwProg{Fn}{Function}{:}{}

\BlankLine
\Fn{\FBilinear{$\mathbf{I}$, $y$, $x$}}{
    $C, H, W \gets \text{shape}(\mathbf{I})$\;
    $x \gets \text{clip}(x, 0, W - 1.001)$, $y \gets \text{clip}(y, 0, H - 1.001)$\;

    \BlankLine
    $x_0, y_0 \gets \lfloor x \rfloor, \lfloor y \rfloor$ \tcp*{Floor coordinates}
    $x_1, y_1 \gets \min(x_0 + 1, W-1), \min(y_0 + 1, H-1)$\;

    $w_x, w_y \gets x - x_0, y - y_0$ \tcp*{Interpolation weights}

    \BlankLine
    $\mathbf{v}_{\text{top}} \gets \mathbf{I}[:, y_0, x_0] \cdot (1 - w_x) + \mathbf{I}[:, y_0, x_1] \cdot w_x$\;
    $\mathbf{v}_{\text{bot}} \gets \mathbf{I}[:, y_1, x_0] \cdot (1 - w_x) + \mathbf{I}[:, y_1, x_1] \cdot w_x$\;

    \Return $\mathbf{v}_{\text{top}} \cdot (1 - w_y) + \mathbf{v}_{\text{bot}} \cdot w_y$\;
}

\BlankLine
$\lambda_h \gets H_s / H_r$, $\lambda_w \gets W_s / W_r$ \tcp*{Scale factors}
$\mathcal{H} \gets \mathbf{0}_{C \times H_s \times W_s}$ \tcp*{Initialize hint image}

\BlankLine
\For{$y \in [0, H_r)$}{
    \For{$x \in [0, W_r)$}{
        \If{$\mathcal{M}_{\text{hit}}[y, x] = 1$}{
            \textbf{continue} \tcp*{Skip hit pixels}
        }

        \BlankLine
        $(x_c, y_c) \gets \mathcal{R}[y, x]$ \tcp*{Get correspondence}
        $w \gets \mathcal{W}[y, x]$ \tcp*{Get confidence}

        \If{$w < 0.1$}{
            \textbf{continue} \tcp*{Skip low-confidence correspondences}
        }

        \BlankLine
        $y_{\text{src}} \gets y_c \cdot \lambda_h$, $x_{\text{src}} \gets x_c \cdot \lambda_w$ \tcp*{Scale to source resolution}

        $y_{\text{start}} \gets \lfloor y \cdot \lambda_h \rfloor$, $y_{\text{end}} \gets \lfloor (y+1) \cdot \lambda_h \rfloor$\;
        $x_{\text{start}} \gets \lfloor x \cdot \lambda_w \rfloor$, $x_{\text{end}} \gets \lfloor (x+1) \cdot \lambda_w \rfloor$\;

        \BlankLine
        \For{$y_s \in [y_{\text{start}}, y_{\text{end}})$}{
            \For{$x_s \in [x_{\text{start}}, x_{\text{end}})$}{
                \If{$y_s \notin [0, H_s)$ \textbf{or} $x_s \notin [0, W_s)$}{
                    \textbf{continue} \tcp*{Boundary check}
                }

                \BlankLine
                $\alpha_y \gets \frac{y_s - y_{\text{start}}}{\max(y_{\text{end}} - y_{\text{start}}, 1)}$ \tcp*{Normalized offset}
                $\alpha_x \gets \frac{x_s - x_{\text{start}}}{\max(x_{\text{end}} - x_{\text{start}}, 1)}$\;

                $y_{\text{sample}} \gets y_{\text{src}} + \alpha_y \cdot \lambda_h$\;
                $x_{\text{sample}} \gets x_{\text{src}} + \alpha_x \cdot \lambda_w$\;

                $\mathcal{H}[:, y_s, x_s] \gets \FBilinear(\mathbf{I}_{\text{src}}, y_{\text{sample}}, x_{\text{sample}})$\;
            }
        }
    }
}

\BlankLine
\Return $\mathcal{H}$\;

\end{algorithm}



