\section{Semiflows on finite topological spaces}\label{section:semiflows}

We begin by proving the existence of non-trivial semiflows through an illustrative example. This example will subsequently highlight properties relevant to semiflows within this context.
\begin{ex}\label{Ex:notrivial} Let $X:=\{A,B,C,D,E,F \}$ with $A>B,C,D,E,F$; $B>D,E,F$; $C>D,E,F$, and $D>E,F$. Define $\varphi:\mathbb{R}_0^+\times X\rightarrow X$ by 

\begin{align*}
\varphi(t,x)&:=x \ \ \ \textnormal{if } t=0,\\
\varphi(t,x)&:= \begin{cases} D & \ \ \ \textnormal{if }x> D \  \textnormal{and }t\in (0,\infty), \\
x & \ \ \ \textnormal{if }x\leq  D \  \textnormal{and }t\in (0,\infty).
\end{cases}
\end{align*}
It is an easy exercise to prove that $\varphi$ is a semiflow. Moreover, $\varphi$ is a non-trivial semiflow because $\varphi_t\neq \text{id}$ for every $t\in \mathbb{R}^+$. We present in Figure \ref{fig:no_trivial} the Hasse diagram of $X$, along with a schematic representation of $\varphi$.
\begin{figure}[h!!!]
\centering
\includegraphics[scale=1]{semilfow_non_trivial_example.pdf}
\caption{Hasse diagram of $X$ and schematic representation of the semiflow $\varphi$ from Example \ref{Ex:notrivial}.}\label{fig:no_trivial}
\end{figure}

\end{ex}

\begin{thm}\label{thm:trivial_minimal} Let $X$ be a minimal finite topological space. If $\varphi:\mathbb{R}_0^+\times X \rightarrow X$ is a semiflow, then $\varphi$ is trivial.
\end{thm}
\begin{proof}
We argue by contradiction. Suppose that there exists a non-trivial semiflow $\varphi:\mathbb{R}_0^+\times X \rightarrow X$. This implies that there exist $x\in X$ and $t\in \mathbb{R}^+$ such that $\varphi(t,x)\neq x$. Moreover, the continuous map $\varphi_t:X\rightarrow X$ is homotopic to the identity map $\text{id}:X\rightarrow X$ because $\varphi_{|[0,t]}:[0,t]\times X\rightarrow X$ provides a homotopy between $\text{id}$ and $\varphi_t$. However, by Theorem \ref{thm:minimal_homotopica_identidad_es_identidad}, we obtain that $\text{id}=\varphi_t$, which entails the contradiction.
\end{proof}

Theorem \ref{thm:trivial_minimal} proves that we only have non-trivial dynamical systems within this framework unless the space $X$ contains beat points. For instance, in Example \ref{Ex:notrivial}, the points $B,C, E$ and $F$ are beat points, allowing us to define a non-trivial semiflow.  In the following sequence of lemmas, we state and narrow down the possibilities for semiflows.

\begin{lem}\label{lem:trivial_extiende_identidad_fuera_cero} Let $X$ be a finite topological space and let $\varphi:\mathbb{R}_0^+\times X\rightarrow X$ be a semiflow. If there exists $\epsilon>0$ such that $\varphi_t$ is the identity map for every $t\in [0,\epsilon)$, then $\varphi$ is trivial.
\end{lem}
\begin{proof}
Let $s\in \mathbb{R}_0^+$. Then $s=\sum_{i=1}^n {s_i}$, where $s_i\in (0,\epsilon)$ for every $i=1,...,n$. Consequently, by ii) in Definition \ref{def:dynamical_system}, for every $x\in X$, we obtain
$$\varphi_s(x)=\varphi_{s_n}\circ \cdots\circ \varphi_{s_2}\circ \varphi_{s_1}(x)=x, $$
and this shows that $\varphi$ is trivial.
\end{proof}

Observe that this lemma is in concordance with the definition of $\varphi$ from Example \ref{Ex:notrivial}.

\begin{lem}\label{lem:cadenas} Let $X$ be a finite topological space and let $\varphi:\mathbb{R}_0^+\times X\rightarrow X$ be a semiflow. If $s,t\in \mathbb{R}_0^+$ are such that $s<t$, then $\varphi_t\leq \varphi_s$. 
\end{lem}
\begin{proof}
The map $\varphi$ is continuous at $(0,x)$ and $(s,x)$ for every $x\in X$, which gives that there exist $\epsilon>0$ and $\delta>0$  satisfying that $\varphi([0,\epsilon)\times U_x)\subseteq U_{x}$ and $\varphi(I\times U_x)\subseteq U_{\varphi_s(x)}$ where $I=\mathbb{R}_0^+\cap (s-\delta,s+\delta)$. We can express $t$ as follows $t=\sum_{i=1}^n s_i+s_{n+1}$, where $s_i\in (0,\epsilon)$ and $s_{n+1}\in I$ for every $i=1,...,n$. By ii) in Definition \ref{def:dynamical_system}, we obtain
$$\varphi_t(x)=\varphi_{s_{n+1}}\circ \varphi_{s_n} \circ  \cdots \circ \varphi_{s_2}\circ \varphi_{s_1}(x).$$
It is evident that $y=\varphi_{s_n} \circ  \cdots \circ \varphi_{s_2}\circ \varphi_{s_1}(x)\in U_x$. Consequently, $\varphi_{t}(x)=\varphi_{s_{n+1}}(y)\in U_{\varphi_{s}(x)}$.
\end{proof}
As an immediate consequence of this result, we can obtain the following lemma.
\begin{lem}\label{lem:varios resultados} Let $X$ be a finite topological space and let $\varphi:\mathbb{R}_0^+\times X\rightarrow X$ be a semiflow. Then
\begin{enumerate}
\item $\textnormal{id}\geq  \varphi_t$ for every $t\in \mathbb{R}_0^+$.
\item $\varphi(t,x)\in U_x$ for every $t\in \mathbb{R}_0^+$ and $x\in X$.
\item $\varphi(t,y)=y$ for all $t\in \mathbb{R}_0^+$ and every  $y\in X$ with $ht(y)=0$.
\end{enumerate}

\end{lem}















