\caption{Description of the non-trivial semiflows defined on the space $X$ from Example \ref{Ex:notrivial}.}\label{fig:todos_semiflujos}
\end{figure}

\section{Counting semiflows}\label{sec_counting_semiflows}

Given any finite topological space $X$, we define $S_F(X)$ as the number of distinct semiflows that can be defined on $X$. As a direct consequence of the results from Section \ref{section:semiflows}, we may derive the following theorem.

\begin{thm} Let $X$ be a finite topological space. Then $D(X)=\emptyset$ if and only if $S_F(X)=1$.  
\end{thm}

We now study relations between the number of down beat points of a finite topological space $X$ and the number $S_F(X)$.

\begin{prop}\label{prop_cota_down_beat_point} Let $X$ be a finite topological space. Then $S_F(X)\geq 2^{|D(X)|}$.
\end{prop}
\begin{proof}
Set $D(x)=\{x_1,...,x_n\}$ such that $ht(x_i)\geq ht(x_j)$ for every $1\leq i<j\leq n$. For each down beat point $x_i\in D(X)$, we denote by $\overline{x}_i$ the maximum of $U_{x_i}\setminus \{x_i\}$. Consider $r_i(x_i):=\overline{x}_i$ and $r_{i_{|X\setminus \{ x_i\}}}:=\textnormal{id}:X\setminus \{ x_i\}\rightarrow X\setminus \{ x_i\}$. We can obtain $2^n$ distinct semiflows by combining the retractions $r_i$ defined above. We prove the last assertion. Let $I=(a_1,...,a_n)\in \{0,1 \}^n$ and set $X^I_i:=X\setminus \{ x_j\in D(X)|j\leq i$ and $a_j=1\}$. For each $1\leq i \leq n$, define $r_{a_i}:X^I_{i-1}\rightarrow X^I_i$ by $r_{a_i}:=\textnormal{id}$ if $a_i=0$ and $r_{a_i}(x):=r_{i_{|X^I_{i-1}}}(x)$ if $a_i=1$, where $X_0^I=X$. Consider $r_I:X\rightarrow X^I_n$ defined by $r_I(x):=r_{a_n}\circ r_{a_{n-1}}\circ \cdots \circ r_{a_2}\circ r_{a_1}(x)$. We verify that $r_I$ is a strong deformation retraction. By the construction, it is clear that $r_{I}\circ i=\textnormal{id}_{X^I_n}$, where $i:X^I_n\rightarrow X$ is the inclusion, and also that $i\circ r_I\leq \textnormal{id}_X$. Given $I,J\in \{0,1\}^n$, it is evident that $r_I=r_J$ if and only if $I=J$. Hence, there are $2^n$ distinct strong deformation retractions of the form $r_I$. To conclude, we have that $\varphi^I :\mathbb{R}_0^+\times X\rightarrow X$, defined by $\varphi^I(0,x):=x$ with $x\in X$ and $\varphi^I(t,x):=r_I(x)$ for every $t>0$ and $x\in X$, is a semiflow.
\end{proof}




\begin{thm}\label{thm_realizacion_todos_los_enteros_positivos} For every positive integer number $n\geq 2$ there exists a finite topological space $X$ such that $D(X)=1$ and $S_F(X)=n$. 
\end{thm}
\begin{proof}
Consider the finite topological space $X_n:=\{\overline{x}_0, x_0, x_1^+,\overline{x}_1,x_1,x_2^+,\overline{x}_2,x_2,...,x_n^+,\overline{x}_n,x_n \}$ given by $\overline{x}_i<x_{j},\overline{x}_j$; $x_i<x_j$ and $x_i^+<x_j,\overline{x}_j$ for every $i<j$, where $n$ is a non-negative integer number (see the Hasse diagram of $X_3$ in Figure \ref{fig:todos_numeros_realizados}). It is evident that $X_n$  has only one down beat point, $D(X_n)=\{ x_0\}$. Moreover, it is simple to deduce that $\{x_0,x_1,...,x_n \}$ are the only points that are down beat points of $X$ after removing down beat points. Consider the retractions $r_i:X_n\rightarrow X_n$ defined by $r_i(x_j):=\overline{x}_j$ for all $0\leq j\leq i$ and $r_i(x):=x$ otherwise, where $i\leq n$. The non-trivial semiflows on $X$ are given by $r_i$. Thus, $S_F(X_{n})=n+2$. 
\end{proof}

