\begin{prop}\label{prop_cota_inferior_potential_down_beat_point_anticadena} Let $X$ be a finite topological space and let $A$ be the maximal antichain of potential down beat points of $X$ such that $U_a\cap U_b=\emptyset$ for every $a,b\in A$ with $a\neq b$. Then $S_F(X)\geq 2^{|A|}$.
\end{prop}
\begin{proof}
By the proof of Theorem \ref{thm:los_flujos_mueven_potenciales_beat_points} and the hypothesis, for each potential down beat point $a$ of $A$ there exists a non-trivial semiflow $\varphi^a$ such that $\varphi^a(t,a)\neq a$ for every $t>0$ and $\varphi^a(t,x)=x$ for every $t\geq 0 $ and $x\in X\setminus \{ U_a\}$. For every $a\in A$, set $r_a:=\varphi^a(1,x):X\rightarrow X$. By repeating the same arguments from the proof of Proposition \ref{prop_cota_down_beat_point} for the retractions $r_a$, we can obtain the desired result.
\end{proof}

\begin{prop}\label{prop_si_potential_se_mueve_un_down_tambien} Let $X$ be a finite topological space and $x\in X $. If $x$ is not a down beat point and $\varphi$ is a non-trivial semiflow defined on $X$ such that $\varphi(t,x)\neq x$ for every $t>0$, then there exists a down beat point $y<x$ such that $\varphi(y,t)\neq y$ for every $t>0$.
\end{prop}
\begin{proof}
Let $r:X\rightarrow X$ be the retraction that defines $\varphi$. There exist $y_1,y_1'\in X$ such that $y_1\prec x$ and $y_1'\prec x$ with $y_1\not \sim y_1'$, and $r(x)\leq y_1$ because $x$ is not a down beat point. By the continuity of $r$, we deduce that $r(y_1')\neq y_1'$. By Theorem \ref{thm:los_flujos_mueven_potenciales_beat_points}, $y_1'$ is a potential down beat point.  If $y_1'$ is a down beat point, then we can conclude. Suppose that $y_1'$ is not a down beat point. Then we can repeat the previous argument to obtain a potential down beat point $y_2'$ and discuss whether is a down beat point or not. By finiteness, there exists a down beat point $y_n'$ such that $y_n'<y_{n-1}'<\cdots< y_1'<x$ and $r(y_n')\neq y_n'$.
\end{proof}

This result is also illustrated in Figure \ref{fig:todos_semiflujos}. The semiflows that move the only potential down beat point of $X$, which is $A$, also move $B$, $C$ or both $B$ and $C$ at the same time. Furthermore, this example proves that there are semiflows  that can move a potential down beat point $x\in X$ and fix a down beat point in $U_x$.


\begin{prop}\label{number_height_1} Let $X$ be a finite topological space such that every potential down beat point $x\in X$ has height $1$ and let $n$ be the number of potential down beat points of $X$. Then $ S_F(X)=2^n$.
\end{prop}
\begin{proof}
By hypothesis, $x$ is a potential down beat point if and only if $x$ is a down beat point. For each down beat point $x$, there is a unique semiflow $\varphi$ such that $\varphi(t,x)\neq x$ for every $t>0$ and $\varphi(t,y)=y$ otherwise. By combining these semiflows we can obtain every semiflow defined on $X$. Specifically, we have $2^n$ distinct semiflows. 
\end{proof}


