\subsection{Variational AutoEncoders} 
\acfp{VAE} \citep{kingma2014auto, rezende2014stochastic} are deep generative models that model data through a two-step process: sampling a latent variable $\bm{z}$ (with dimension smaller than $\mathcal{X}$) from a prior $p(\bm{z})$, followed by sampling $\bm{x}$ through a distribution $p_{\theta}(\bm{x}|\bm{z})$, resulting in a generative model $\bm{x} \sim p_\theta(\bm{x})$.
The latter of these steps is performed by a neural network, known as the \emph{decoder}, with parameters $\theta$.
The decoder outputs the parameters of the conditional distribution $p_{\theta}(\bm{x}|\bm{z})$, for instance the mean and variance of a normal distribution, or class probabilities for a categorical distribution.
In order to train a VAE, we require the posterior $p_{\theta}(\bm{z}|\bm{x})$. 
However, as this is intractable, we use a neural network \emph{encoder} with parameters $\phi$ to approximate it through amortised inference: $q_\phi(\bm{z}|\bm{x}) = \mathcal{N}(\bm{\mu}(\bm{x}),\bm{\sigma^2}(\bm{z})I)$, where $\phi$ parameterises $\bm{\mu}(\cdot)$ and $\bm{\sigma^2}(\cdot)$.
The encoder and decoder are trained jointly through a minibatch-friendly lower bound to the marginal likelihood of the data.

% \acp{VAE} have demonstrated success in their ability to encode high-dimensional data in lower-dimensional spaces across many data modalities: key to their success is an assumption that the data will lie on a low-dimensional highly-structured manifold which can be represented with the dimensionality of the latent space $\mathcal{Z}$.
% For instance, biologically relevant molecules will comprise a small fraction of all possible molecules as they must satisfy a large number of structural and physicochemical constraints.

\section{The Pitfalls of Latent Space BO}

In what follows, we assume that we have access to a pre-trained \ac{VAE} with a $d$-dimensional latent space $\mathcal{Z}=\mathds{R}^d$, resulting in a decoding distribution $p_{\theta}(\textbf{x}|\textbf{z})$, and imply a data distribution $p_{\theta}(\bm x)$.

\subsection{Latent Space BO}
\acf{LSBO} \citep{gomez2018automatic} can be viewed as standard \ac{BO} conducted over an alternative search space --- the latent space $\mathcal{Z}$ of a \ac{VAE} --- and using a different surrogate model, one modelling the mapping $g:\mathcal{Z}\rightarrow\mathds{R}$ from latent codes to objective function values with a surrogate $\tilde{g}$. At the $n^{\textrm{th}}$ optimisation step, \ac{LSBO} proceeds analogously to standard BO. For example, under the PI acquisition function, \ac{LSBO} selects a new latent code $\bm z_n$ with highest utility
\begin{align}
\bm z_n\leftarrow\textcolor{black}{\argmax_{\bm z\in\mathcal{Z}}}\;\mathds{P}(\textcolor{black}{\tilde{g}(}\bm z\textcolor{blue}{)} > f^* | D^{\mathcal{Z}}_{n-1}),
\nonumber
\end{align}
where the surrogate $\tilde{g}$ is trained on the dataset $D^{\mathcal{Z}}_{n-1}= \{(\bm z_i, y_i)\}_{i=1}^{n-1}$ of latent code-evaluation pairs.
The result $z_n$ is then decoded and the resulting structure is evaluated on the objective function (see Algorithm \ref{alg:lsbo}).
%Here, $\tilde{g}$ is our probabilistic estimate of the mapping between latent codes and the objective function given the dataset $D^{\mathcal{Z}}_{n-1}= \{(\bm z_i, y_i)\}_{i=1}^n$ of already collected latent-evaluation pairs, and $g_{n-1}^*=\max y_i$ is the current best observation. 

\begin{algorithm}[tb]
   \caption{\label{alg:lsbo}Latent Space Bayesian Optimisation}
\begin{algorithmic}
   \STATE {\bfseries Input:} budget $N$, init size $N_{\textrm{init}}$, search bounds $\delta$
   \STATE Clip search space $\mathcal{Z}_{\delta}\leftarrow[-\delta,\delta]^d\subset\mathcal{Z}$
   \FOR{$n\in\{1,..,N\}$}
   \IF[initial design]{$n<N_{\textrm{init}}$}
   \STATE $\bm z_n \sim \textrm{SpaceFillingDesign}(\mathcal{Z}_{\delta})$ 
   \ELSE[sequential optimisation]
   \STATE $\bm z_n\leftarrow\argmax_{\bm z\in\mathcal{Z}_{\delta}}\;\alpha(\bm z; D_{n-1}^{\mathcal{Z}})$ \COMMENT{e.g. Eq. (\ref{eq:PI})}
   \ENDIF
   \STATE Decode chosen latent $\bm{x}_n\sim p_{\theta}(\bm x|\bm z_n)$
   \STATE Evaluate new molecular structure $y_n\leftarrow f(\bm{x}_n)$
    \STATE Update dataset $D^{\mathcal{Z}}_n\leftarrow D^{\mathcal{Z}}_{n-1} \bigcup \{(\bm z_n,y_n)\}$
    \STATE Fit latent space GP on $D^{\mathcal{Z}}_n$
   \ENDFOR
    \STATE \textbf{return} Believed optimum across $\{\bm{z}_1,..,\bm{z}_n\}$
\end{algorithmic}
\end{algorithm}

