\section{COWBOYS' sampler details}
\label{appendix:sampling}

We now provide full details for our PCN MCMC sampler \citep{cotter2013mcmc} as Algorithms \ref{alg:COWBOYS_SAMPLE} and \ref{alg:PCN} which we use to get a set of samples from COWBOYS sampling objective (\ref{eq:cowboys_z}). Note that we keep track of the latent value that decoded to give the best structure so far $\bm z_{best}$ and use this to start our chains. We also employ an adaptive choice of PCN's scale parameter $\beta$ following \citet{andrieu2008tutorial}. Often, especially early in the optimisation before the region satisfying likely to satisfy $f(\bm x)>f^*$ narrows, our PCN sampler can return a larger number of samples than our desired batch size. In this case, we select the $B$ samples that achieve the highest expected utility under greedy maximisation of the batch Expected Improvement (qEI) acquisition function provided in \texttt{BoTorch} \citep{balandat2020botorch}. If very large batches are required, then a subset could be chosen using Thompson  following \citet{vakili2021scalable}. Although this subset selection strategy breaks MCMC’s detailed balance, it ensures that we return a diverse, high-value subset of samples to COWBOYS -- samples that are likely to be approximate anyway due to relatively small number of MCMC iterations and lack of burn-in phase. Note that in practical implementations, our PCN (Algorithm \ref{alg:PCN}) is trivially parallelised by running all chains present in the outer loop at once. 


\begin{algorithm}[]
   \caption{\label{alg:COWBOYS_SAMPLE}COWBOYS' MCMC Sampler}
\begin{algorithmic}
   \STATE {\bfseries Input:} Batch size $B$, number chains $C$, number steps $S$, threshold $f^*$, starting latent code$\bm z_{best}$
    \STATE $Z_{samples}\leftarrow \textrm{PCN}(C, S, f^*, \bm z_{best})$ \COMMENT{Algorithm \ref{alg:PCN}}
    \WHILE[Keep sampling if needed]{$|Z_{samples}| < B$}
    \STATE $Z_{samples}\leftarrow Z_{samples}\bigcup\textrm{PCN}(C, S, f^*, \bm z_{best})$ \COMMENT{Algorithm \ref{alg:PCN} again}
    \ENDWHILE
    \IF{$|Z_{samples}|>B$}
    \STATE $Z_{samples} \leftarrow \argmax_{\substack{Z\subseteq Z_{samples} \\  : |Z|=B}} \textrm{qEI}(Z)$ \COMMENT{choose $B$ best according to batch utility}
    \ENDIF
    \STATE \textbf{return}   $Z_{chosen}$ 
\end{algorithmic}
\end{algorithm}


\begin{algorithm}[]
   \caption{\label{alg:PCN}PCN}
\begin{algorithmic}
   \STATE {\bfseries Input:} number chains $C$, number steps $S$, best score so far $f^*$, starting latent code$\bm z_{best}$
   \STATE $Z_{samples}\leftarrow \emptyset$
   \FOR{$c\in\{1,..,C\}$}
    \STATE $\beta\leftarrow 0.1$  \COMMENT{Initialise step size}
   \STATE $\bm z_{\textrm{current}}\leftarrow \bm z_{\textrm{best}}$ \COMMENT{Initialise new chain at best so far}
   \FOR[Do MCMC step]{$n\in\{1,..,S\}$}
    \STATE  $\bm z_{\textrm{proposal}}\sim\mathcal{N}_d(\sqrt{1-\beta^2}\bm z_{\textrm{current}}, \beta^2I_{d}) $\COMMENT{Sample from PCN proposal density}
    \STATE  $\alpha \leftarrow \min\left(1, \frac{p\bigl(g_{\theta,\bm z_{\textrm{proposal}}} > f^* \mid D^{\mathcal{X}}_n\bigr)\times p(\bm z_{\textrm{proposal}})}{p\bigl(g_{\theta,\bm z_{\textrm{current}}} > f^* \mid D^{\mathcal{X}}_n\bigr)\times p(\bm z_{\textrm{current}})}\right)$\COMMENT{Calculate acceptance probability using prior and likelihood from (\ref{eq:decomp})}
    \STATE $u \sim U[0,1]$
    \IF[Stochastic acceptance step]{$\alpha > u$}
        \STATE $\bm z_{\textrm{current}}\leftarrow\bm z_{\textrm{proposal}}$ 
        \STATE $Z_{samples}\cup\{z_{\textrm{current}}\}$ \COMMENT{Store sample}
    \ENDIF
    \STATE $\beta\leftarrow\beta + 0.1 (\alpha -0.243)$ \COMMENT{Adaptive MCMC update}
   \ENDFOR
   \ENDFOR
    \STATE \textbf{return} $Z_{samples}$ \COMMENT{return all accepted samples}
\end{algorithmic}
\end{algorithm}


