\label{Shadow2.7} If $T$ is a tree and $D$ is any $PDD$-set, then every support vertex of $T$ is included in $D$ with a its neighbour or $D$ may contains at least two
neigbours of the support vertices with their neighbours.
\end{observation}

\begin{theorem}
\cite{HenningPDD}\label{special} For paired disjunctive domination number of some special graphs:
\begin{itemize}
 \item[i)]  $\gamma _{pr}^{d}(C_{n})=2\left\lceil 
	\frac{n}{5}\right\rceil$ with $n\geq 3,$ \\

\item[ii)]  $\gamma _{pr}^{d}(P_{n})=2\left\lceil \frac{n+1}{5}%
	\right\rceil$ with $n\geq 2,$
    \item[iii)]  $\gamma _{pr}^{d}(K_{n})= \gamma _{pr}^{d}(K_{m,n})=2$ with $n\geq 2$.
\end{itemize}
\end{theorem}

