\section{Results about Special Graph Structures}
In this section, we investigate the paired disjunctive domination parameter in middle graphs of several special graph classes.

\begin{theorem}\label{n-1dereceli}
    Let $G$ be a graph on $n$ vertices and without isolated vertices. Suppose the maximum degree in $G$ satisfies $\Delta(G)=n-1$, then $$\gamma_{pr}^d(M(G))=2.$$
    \end{theorem}
\begin{proof}
Let the vertex set of $G$ be $V(G)=\{v_1,v_2,...,v_n\}$, and assume that the vertex with degree $n-1$ is $v_1$. Consider the middle graph $M(G)$ and select two subdivision vertices, $v_{12},v_{13}$. Since these two vertices are adjacent, they satisfy the paired property. Moreover, all vertices $M(G)$, except for those adjacent to $v_{12}$ and $v_{13}$, are at most two distances away from these two vertices. Thus, the set $\{v_{12},v_{13}\}$ forms a paired disjunctive domination set (PDD-set) in $M(G)$, which implies that $\gamma_{pr}^d(M(G))\leq 2$. Furthermore, by Theorem \ref{buyuk2}, it is known that the paired disjunctive domination number is at least 2. That is, $\gamma_{pr}^d(M(G))\geq 2$. Consequently, we conclude that $\gamma_{pr}^d(M(G))=2.$
\end{proof}
\begin{corollary}
Let $G\simeq H$ where $H\in \{K_n,K_{1,n},W_{1,n}\}$. Then, as a consequence of theorem \ref{n-1dereceli}, we have
$$\gamma_{pr}^d(M(H))=2.$$
\end{corollary}
\begin{theorem}
    Let $K_{m,n}$ be complete bipartite graph with $m+n$ vertices. Then $$\gamma_{pr}^d(M(K_{m,n}))=2.$$ 
\end{theorem}
\begin{proof}
    It is known that the paired disjunctive domination number is at least 2. Therefore, $\gamma_{pr}^d(M(K_{m,n}))\geq 2$. Let us denote the vertices of the complete bipartite graph \(K_{m,n}\) as $
V_1 = \{v_1, v_2, \ldots,v_m,v_{m+1},\ldots, v_{m+n}\}.
$
In constructing the middle graph, consider any two subdivision vertices adjacent to vertex \(v_1\), and define the set
$
S = \{v_{1i}, v_{1j}\},
$
where \(i, j \in \{m+1, m+2, \ldots, m+n\}\). In this case, since all other vertices are within distance 2 of these two vertices, and \(v_{1i}\) and \(v_{1j}\) are also adjacent to each other, the set \(S\) forms a paired disjunctive dominating set for the graph \(M(K_{m,n})\). Thus, we obtain
$
\gamma_{pr}^d(M(K_{m,n})) \leq 2,
$
which completes the proof.
\end{proof}
\begin{theorem}
    Let $C_n$ be the cycle. Then $$\gamma_{pr}^d(M(C_n))=2\lceil\frac{n}{4}\rceil.$$
\end{theorem}
\begin{proof}
    Let us denote the vertex set of the middle graph $M(C_n)$ as the union of two disjoint subsets 
\[
V_1 = \{v_i \mid 1 \leq i \leq n,\, v_i \in V(C_n)\}, \quad V_2 = \{u_j \mid 1 \leq j \leq n,\, u_j \in SD\},
\]
that is, $V(M(C_n)) = V_1 \cup V_2$. We first construct an upper bound for $\gamma_{pr}^d(M(C_n))$. Define the set 

\begin{align*} D =\begin{cases} \{u_j \mid 1 \leq j \leq n,\ j \equiv 1 \text{ or} 2\pmod{4}\}, n\not\equiv 1(mod 4)\\
\{u_j \mid 1 \leq j \leq n,\ j \equiv 1 \text{ or} 2\pmod{4}\}\cup \{u_n,v_n\}, n\equiv 1(mod 4).
\end{cases}
\end{align*}
and then $S = D$.

Since every vertex in $M(C_n)$ is either in $S$ or disjunctively dominated by a vertex in $S$, and since the subgraph induced by $S$ contains a perfect matching, it follows that $S$ is a paired disjunctive dominating set (PDD-set) of $M(C_n)$ for all cases of $n$ modulo 4. 
Furthermore, we have $|S| = |D| = 2\left\lceil \frac{n}{4} \right\rceil$. Hence,


\begin{equation}\label{cycleust}
    \gamma_{pr}^d(M(C_n)) \leq |S| = 2\left\lceil \frac{n}{4} \right\rceil.
\end{equation}
Now, we establish a lower bound for $\gamma_{pr}^d(M(C_n))$. Let $D'$ be a $\gamma_{pr}^d$-set of $M(C_n)$. Consider the matching in subgraph $M(C_n)[D']$ given by 
\[
M = \{u_{i_1}u_{i_1+1}, u_{i_2}u_{i_2+1}, \dots, u_{i_r}u_{i_r+1}\},
\]
where $1 \leq i_1 < i_1+1 < i_2 < i_2+1 < \dots < i_r < i_r+1 \leq n$. 

Notice that between any two consecutive matched pairs $u_{i_k}u_{i_k+1}$ and $u_{i_{k+1}}u_{i_{k+1}+1}$, there are at most two vertices of $M(C_n)$ that are not in $D'$ for any $k \in \{1, \dots, r\}$. Therefore, we obtain
\[ n \leq 2r + 2r = 4r, \]
which implies that \begin{equation}\label{cyclealt}
    |M| = 2r \geq 2\left\lceil \frac{n}{4} \right\rceil.
\end{equation}
Combining the upper bound (\ref{cycleust}) and lower bound (\ref{cyclealt}), we conclude that $\gamma_{pr}^d(M(C_n)) = 2\left\lceil \frac{n}{4} \right\rceil. 
$
\end{proof}
\begin{theorem}
    Let $P_n$ be the path with $n$ vertices. Then $$\gamma_{pr}^d(M(P_n))=\begin{cases}
        2\lceil\frac{n-1}{4}\rceil, &n\equiv2,3 \pmod{4}\\
         2\lceil\frac{n-1}{4}\rceil+2, &\text{otherwise.}
    \end{cases}$$
\end{theorem}
    \begin{proof}
Let us denote the vertex set of the middle graph $M(P_n)$ as the union of two disjoint subsets: \[ V_1 = \{v_i \mid 1 \leq i \leq n,\, v_i \in V(P_n)\}, \quad V_2 = \{u_j \mid 1 \leq j \leq n-1,\, u_j \in SD\}. \], that is, $V(M(P_n)) = V_1 \cup V_2$. We first construct an upper bound for $\gamma_{pr}^d(M(P_n))$. Define the set 
\[D = \{u_j \mid 1 \leq j \leq n-1,\ j \equiv 1,2\pmod{4}\}.
\]

Now, consider the following cases:
\begin{itemize}
 \item If $n \equiv 0,1 \pmod{4}$, let $S = D \cup \{u_{n-1}, v_n\}$.
\item  If $n \equiv 2 \pmod{4}$, let $S = D \cup \{v_n\}$.
 \item If $n \equiv 3 \pmod{4}$, then $S = D$.
 \end{itemize}

In all cases, $S$ forms a paired disjunctive dominating set (PDD-set) in $M(P_n)$. Furthermore, we observe that If $n \equiv 2,3 \pmod{4}$, then $|S| = |D| = 2\left\lceil \frac{n-1}{4} \right\rceil$. Otherwise, $|S| = |D| + 2 = 2\left\lceil \frac{n-1}{4} \right\rceil + 2$. Thus, we obtain the following upper bound:
\begin{equation}\label{pathust}
    \gamma_{pr}^d(M(P_n)) \leq |S| = 
\begin{cases}
2\left\lceil \frac{n-1}{4} \right\rceil, & \text{if } n \equiv 2,3 \pmod{4}, \\
2\left\lceil \frac{n-1}{4} \right\rceil + 2, & \text{otherwise}.
\end{cases}
\end{equation}


Now we construct a lower bound for $\gamma_{pr}^d(M(P_n))$. Let $D'$ be a minimum PDD-set in $M(P_n)$. Consider the induced subgraph $M(P_n)[D']$ and let $M = \{u_{i_1}u_{i_1+1}, u_{i_2}u_{i_2+1}, \dots, u_{i_r}u_{i_r+1}\}$ be the matching in $M(P_n)[D']$, where 
\[1 \leq i_1 < i_1 + 1 < i_2 < i_2 + 1 < \dots < i_r < i_r + 1 \leq n-1.
\]

Two cases arise:
\begin{itemize}
\item Case 1: If $n \equiv 2,3 \pmod{4}$.

Note that between any two consecutive matched pairs $u_{i_k}u_{i_k+1}$ and $u_{i_{k+1}}u_{i_{k+1}+1}$, there are at most two vertices in $M(P_n)$ that are not in $D'$, for each $k \in \{1,\dots,r\}$. Hence, we obtain 
$n - 1 \leq 2r+2r=4r$ and therefore \begin{equation}\label{pathalt1}
    |M| = 2r \geq 2\left\lceil \frac{n-1}{4} \right\rceil.
\end{equation} 

\item Case 2: If $n \equiv 0,1 \pmod{4}$.

In this case, let $N = M \cup \{v_n, u_{n-1}\}$. By Case 1, we know that $|M| = 2r$, and therefore \begin{equation}\label{pathalt2}
    |N| = 2r + 2 \geq 2\left\lceil \frac{n-1}{4} \right\rceil + 2.
\end{equation}
\end{itemize}
Combining the lower bounds obtained in both cases (\ref{pathalt1}) and (\ref{pathalt2}) with the previously established upper bounds (\ref{pathust}), we conclude that 
$\gamma_{pr}^d(M(P_n))=
\begin{cases}
2\left\lceil \frac{n-1}{4} \right\rceil, & \text{if } n \equiv 2,3 \pmod{4}, \\
2\left\lceil \frac{n-1}{4} \right\rceil + 2, & \text{otherwise}.
\end{cases}   
$
\end{proof}

\begin{theorem}
Let $F_n$ be the friendship graph with $n\geq 2$. Then $$\gamma_{pr}^d(M(F_n))=2.$$
\end{theorem}
    \begin{proof}
    Let the vertices and edges of friendship graph be labeled by $V(F_n)= \{v_i \mid 1 \leq i \leq 2n+1\}$ and  $E(F_n)=\{v_1v_i|i\in \{2,...2n+1\}\}\cup \{v_iv_{i+1}|i=2k \text{ and } k=\{1,2,...,n\}\}$.
Let $M(F_n)$ be the middle graph of the friendship graph $F_n$. Let the vertex set of $M(F_n)$ be $V(M(F_n)) = V_1 \cup V_2$, where 
\[
V_1 = V(F_n), \quad V_2 = \{u_j \mid 1 \leq j \leq 3n,\ u_j \in \text{SD}\}.
\]
Let the central vertex, which is common to all $n$ triangles in $F_n$, be denoted by $v_1$.

From Theorem \ref{buyuk2}, we know that for any graph $G$, it holds that $\gamma_{pr}^d(G) \geq 2$. Therefore, 
\begin{equation}
    \label{friendshipalt}
    \gamma_{pr}^d(M(F_n)) \geq 2.
\end{equation}

Now, consider the set $S = \{v_1, u_i\}$, where $d_{M(F_n)}(v_1, u_i) = 1$. By construction, this set $S$ forms a paired disjunctive dominating set (PDD-set) in $M(F_n)$, since every vertex is either in $S$ or disjunctively dominated by a vertex in $S$, and the induced subgraph $M(F_n)[S]$ contains a perfect matching. Hence, we obtain
\begin{equation}
    \label{friendshipust}
    \gamma_{pr}^d(M(F_n)) \leq 2.
\end{equation}
From (\ref{friendshipalt}) and (\ref{friendshipust}), proof is completed.
\end{proof}
\begin{theorem}
    Let $D_{n,m}$ be the double star graph. Then $$\gamma_{pr}^d(M(D_{n,m}))=4.$$
\end{theorem}
    \begin{proof}
    Let the vertices and edges of double star graph be labeled by $V(D(n,m))=\{v_s|1\leq s\leq n\} \cup \{v_t| n+1\leq t\leq m\} \cup \{v_{n+m+1}, v_{n+m+2}\}$ and $E(D_{n,m})=\{v_{n+m+1}v_{n+m+2},v_sv_{n+m+1},v_tv_{n+m+2}\}$. Let $M(D_{n,m})$ denote the middle graph of the double star graph $D_{n,m}$. Let the vertex set of $M(D_{n,m})$ be partitioned as $V(M(D_{n,m})) = V_1 \cup V_2$, where 
\[
V_1 = \{v_i \mid 1 \leq i \leq n+m+2,\ v_i \in V(D_{n,m})\},  V_2 = \{u_j \mid 1 \leq j \leq n+m+1,\ u_j \in \text{SD}\}.
\]

We know from Theorem~\ref{buyuk2} that $\gamma_{pr}^d(G) \geq 2$ for any graph $G$. Thus, $\gamma_{pr}^d(M(D_{n,m})) \geq 2$. 
        To complete the proof, we now show that no set of two vertices can form a PDD-set in $M(D_{n,m})$, and therefore $\gamma_{pr}^d(M(D_{n,m})) \geq 4$.

Assume, for contradiction, that there exists a paired disjunctive dominating set $S'$ of $M(D_{n,m})$ with $|S'| = 2$. Since $S'$ must induce a perfect matching and ensure that every vertex in $M(D_{n,m})$ is either in $S'$ or disjunctively dominated by a vertex in $S'$, the only possibility is that $S'$ consists of two adjacent vertices. That is, $S' = \{x, y\}$ such that $d_{M(D_{n,m})}(x, y) = 1$.

However, due to the structure of the double star graph, the vertices $x$ and $y$ together can disjunctively dominate at most a localized region of the graph either within a single star component or among a small subset of adjacent vertices. This is insufficient to cover the entire graph, especially when $n, m \geq 1$, since the graph contains at least $n + m + 3$ vertices in total. Thus, not all vertices are disjunctively dominated by $S'$, and $S'$ cannot be a PDD-set. Hence, no set of two vertices can form a PDD-set in $M(D_{n,m})$, implying
\[
\gamma_{pr}^d(M(D_{n,m})) \geq 4.
\]
In the case of $M(D_{n,m})$, we construct a specific set of four vertices that forms a PDD-set and achieves this bound. Let the two central vertices of the stars in $D_{n,m}$ be denoted by $v_a$ and $v_b$, and let $u_a$ and $u_b$ be two edge-subdivision vertices adjacent to $v_a$ and $v_b$ respectively in $M(D_{n,m})$. Consider the set
$
S = \{v_a, u_a, v_b, u_b\}.
$ By construction, every vertex in $M(D_{n,m})$ is either in $S$ or disjunctively dominated by a vertex in $S$, and the subgraph induced by $S$ contains a perfect matching. Therefore, $S$ is a paired disjunctive dominating set of $M(D_{n,m})$, and we have
\[
\gamma_{pr}^d(M(D_{n,m})) \leq 4.
\]
Therefore, we conclude that
$\gamma_{pr}^d(M(D_{n,m})) = 4.$
    \end{proof}

