\section{Main Results}
In this section, we present general results on the paired disjunctive domination of middle graphs. In particular, we establish lower and upper bounds for trees and general graphs, and provide exact value related to the join operation.
\begin{lemma}\label{Lemma1}
Let $G$ be a connected graph with $n\geq 5$ vertices and $S$ be a paired disjunctive dominating set of $M(G).$ Then there exist $S^{\prime }\subset %
\mathcal{M}$ a paired disjunctive dominating set of $M(G)$ with $\left\vert
S^{\prime }\right\vert \leq \left\vert S\right\vert .$
\end{lemma}
\begin{proof}
    If \( S \subset \mathcal{M} \), then the result is satisfied by choosing \( S' = S \). Otherwise, the set \( S \) also contains vertices from \( V(G) \). In this case, let us select a vertex \( v \in S \cap V(G) \). If all vertices \( e_{iv} \in \mathcal{M} \) (or \( e_{vi} \)) adjacent to \( v \) are in \( S \), then two cases arise:\\
Case 1: If the vertex \( v \) does not contribute to the paired property of the set \( S \), then we take \( S_{1} = S - \{v\} \).\\
Case 2: If the vertex \( v \) contributes to the paired property of the set \( S \), then there are two subcases:
\begin{itemize}
\item If all vertices \( e_{iv} \in \mathcal{M} \) adjacent to \( v \) are in \( S \), then we select a vertex \( e_{mn} \in \mathcal{M} \setminus S \) from the set \( N_{2}(e_{iv}, M(G)) \), and take \( S_{1} = (S \cup \{e_{mn}\}) \setminus \{v\} \).
\item If not all adjacent \( e_{iv} \in \mathcal{M} \) are in \( S \), suppose \( e_{iv} \in M \setminus S \). In this case, we take \( S_{1} = (S \cup \{e_{iv}\}) \setminus \{v\} \).
\end{itemize}
This process terminates in a finite number of steps, and eventually, a set \( S^{'} \) consisting only of vertices in \( \mathcal{M} \) is obtained. Furthermore, in each step, \( S^{'} \) remains a paired disjunctive dominating set. Therefore, \( S^{'} \) is a paired disjunctive dominating set of \( M(G) \). Therefore, we construct $|S^{'}|\leq|S|$.
\end{proof}

\begin{lemma}
Let $G$ be a connected graph with $n\geq 5$ vertices. Let $v\in V(G)$ be a vertex that is distinct from a
support vertex. Then,%
\[
\gamma _{pr}^{d}(M(G-v))\leq \gamma _{pr}^{d}(M(G))\leq \gamma
_{pr}^{d}(M(G-v))+2.
\]
\end{lemma}
\begin{proof}
    (i) First, let us show that $\gamma_{pr}^{d}(M(G))\leq\gamma_{pr}^{d}(M(G-v))+2$. Let \( S \) be a $PDD-set$ of the graph \( M(G - v) \). In this case, for every \( w \in N_{\leq2}(v, G) \), we must have either \( w \in S \) or \( e_{iw} \in \mathcal{M} \), which implies that \( e_{iw} \in S \). As a result, for some \( w_1, w_2 \in N_G(v) \), the set \( S \cup \{ e_{w_1v}, e_{vw_2} \} \) is a $PDD-set$ for \( M(G) \). Thus, we obtain the conclusion 
    \[\gamma_{pr}^{d}(M(G))\leq\gamma_{pr}^{d}(M(G-v))+2.\]
(ii) Now, let us show that $\gamma_{pr}^{d}(M(G-v))\leq\gamma_{pr}^{d}(M(G))$. Let $S$ be a $\gamma_{pr}^{d}-set$ of $M(G)$. From Lemma \ref{Lemma1}, we assume that $S \subseteq \mathcal{M}$. Let us consider the set 
\[S_{v} = N_{\leq2}(v, M(G)) \cap S. )\] Since $S$ is a $\gamma_{pr}^{d}-set$, it is easy to see that \( |S_v| \geq 1 \). Let the neighbors and the vertices at distance $2$ from vertex $v$ in the graph $G$ be denoted by \( w \in N_G(v) \) and \( t \in N_2(v, G) \), respectively. Assume that \( |S_v| = k \), where \( k \geq 1 \), and the vertices in \( S_v \) are of the form \( e_{wv} \) or \( e_{tw} \). Based on these types of vertices, two cases arise:\\
Case 1: If \( e_{wv} \in S \), then the set \[ S_{1} = (S - e_{wv}) \cup \{w\} \] is a $PDD-set$ for the graph \( M(G - v) \).\\
Case 2: If \( e_{tw} \in S_v \), then the set \( S_{1} = (S - e_{tw}) \cup \{t\} \) is a $PDD-set$ for the graph \( M(G - v) \).
For each vertex in $S_{v}$, the corresponding operation described above is applied depending on which of the two cases it falls under, resulting in a $PDD-set$ \( S_k \) for the graph \( M(G - v) \). It is easy to verify that \( |S_k|= |S| \). Hence, it follows that $\gamma_{pr}^{d}(M(G-v))\leq\gamma_{pr}^{d}(M(G)).$ 
\end{proof}

\begin{theorem}
Let $G$ be any graph of order $n.$ Then 
\[
2\leq \gamma _{pr}^{d}(M(G))\leq \gamma _{pr}^{d}(M(P_{n}).
\]
\end{theorem}
\begin{proof}
Let \( G \subseteq K_n \). By adding the necessary edges to the graph \( G \), we can obtain a graph isomorphic to \( K_n \). Therefore, \( M(G) \) becomes a subgraph of \( M(K_n) \). Since any paired disjunctive domination set $(PDD-set)$ of \( M(G) \) is also a $PDD-set$ of \( M(K_n) \), it follows that
\[
\gamma_{pr}^{d}(M(G)) \geq \gamma_{pr}^{d}(M(K_n))=2.
\]
This provides the left-hand side of the inequality stated in Theorem \ref{special}(iii).

Let $G$ be a spanning tree, and let $S$ be a \( \gamma_{pr}^{d} \)-set of $M(G)$. By Lemma \ref{Lemma1}, we may assume that \( S \subseteq \mathcal{M} \). The most vulnerable structure is the path graph considering the number of connections. This implies
\[
|S| \leq \gamma_{pr}^{d}(M(P_n)).
\]
Since \( S \) is a \( \gamma_{pr}^{d} \)-set of \( M(G) \), it follows that
\[
\gamma_{pr}^{d}(M(G)) \leq \gamma_{pr}^{d}(M(P_n)).
\]
Thus, the desired inequality is obtained.
\end{proof}

\begin{theorem}
\label{tree}Let $T$ be a tree graph, which is not a star. Let $%
SSV=\{v_{i}:1\leq i\leq k\}$ be the strong support vertices of the tree $T.$
For any $u,w\in leaf(T)$, under the conditions that $N_{G}(u)\cap
N_{G}(w)=\emptyset $ and $d_{G}(u,w)>3,$ it follows that%
\[
\gamma _{pd}^{d}(M(T))\geq 2k+2(\left\vert leaf(T)\right\vert
-\sum\limits_{i=1}^{k}(\deg (v_{i})-1)).
\]
\end{theorem}
\begin{proof}
Let the set of leaves of the tree \( T \) be denoted by \( \text{leaf}(T) \). The set \( \text{leaf}(T) \) contains strong support vertices. Let us denote these vertices by the set\\ 
\[ \text{SSV} = \{v_1, \dots, v_k\}. \]In this case, the number of support vertices in the graph is given by  
\[
|\text{leaf}(T)| - \sum_{i=1}^{k}(\deg(v_i) - 1).
\]

The vertices labeled as \( e_{iv_j} \), where \( i = 1, \dots, \deg_T(v_j) \) in \( M(T) \) corresponding to the edges incident to each vertex \( v_j \), for \( j = 1, \dots, k \), form a complete graph with $deg_G(v_j)$ vertices.
Let \( S \) be a PDD-set of \( M(T) \). Then, by Theorem \ref{special}(iii), it is easy to observe that \( |S| \geq 2k \).

If the graph contains a support vertex, then by Observation \ref{Shadow2.7}, the set \( S \) must include at least one support vertex. Moreover, to maintain the paired property, the neighbors of these support vertices must also be included in \( S \). Hence, the following inequality is obtained
$\gamma _{pd}^{d}(M(T))\geq 2k+2(\left\vert leaf(T)\right\vert
-\sum\limits_{i=1}^{k}(\deg (v_{i})-1)).
$
\end{proof}
\begin{corollary}
Let $T$ be a tree, distinct from a star graph, and containing no support vertices. Then 
\[
\gamma _{pd}^{d}(M(T))\geq 2k.
\]
\end{corollary}

\begin{corollary}
Let $T$ be a tree without support vertices, then 
\[
\gamma _{pd}^{d}(M(T))\geq 2(\left\vert leaf(T)\right\vert .
\]
\end{corollary}

\begin{remark}
If $diam(T)=4$, then equality holds for the corollaries above.
\end{remark}

\begin{theorem}Let $G$ and $H$ be two graphs and $G+H$ be join of them. Then 
\[
\gamma _{pd}^{d}(M(G+H))= 2.
\]


\end{theorem}
\begin{proof}
Let vertex set of $M(G+H)$ is $V(M(G+H))=V(G)+V(H)\cup \mathcal{M}$ where $\mathcal{M}$ is subdivision vertices of $G+H$, where $V(G)  = \{v_{i}:1\leq i\leq n_1\}$, $V(H)=\{u_{j}:1\leq j\leq n_2\}$, and $\mathcal{M} =\{e_{v_{i}u_{j}},e_{v_{i}v_{t}},e_{u_{_{j}}u_{p}}:i,t=1,...,n_1,i\neq t,j,p=1,...,n_2,j\neq p\}$.


Let $S$ be a $PDD-set$ of $M(G+H)$. From Theorem \ref{buyuk2}, it is known that \( |S| \geq 2 \). Suppose $S = \{ e_{v_{i}u_{j}},e_{v_{i}u_{p}}\}$ (or similarly $ S = \{e_{v_{i}u_{j}},e_{v_{t}u_{j}} \} $. In this case, all vertices of \( V(M(G+H)) \) would be disjunctively dominated. Since the vertices in \( S \) are adjacent, the set also satisfies the paired property. Thus, \( |S| \leq 2 \). From the lower and upper bounds, it follows that \( |S| = 2 \).
\end{proof}

