                        \subsection{Two-dimensional Wasserstein-1 metric matrix}\label{sec:2 dim wass mat}
Before proving the next result, we recall some properties about the Kronecker product of two matrices $A\in \mathbb{R}^{n\times n}$ and $B\in \mathbb{R}^{m\times m}$:
                                          \begin{enumerate}
\item [(R1)] $\|A \otimes B\|=\|A\|\|B\|.$
\item [(R2)] $\sigma(A \otimes B)=\{\alpha_i \beta_j:i=1,2,\dots,n,j=1,2,\dots,m, \alpha_i \in \sigma(A),\beta_j \in \sigma(B) \}$ (see Theorem 5.4-1, \cite{gustafson1997}).
\item [(R3)] If $A$ is a normal matrix, then $W(A \otimes B)=\text{Co}(W(A)W(B)),$ where $\text{Co}(S)$ is the convex hull of the set $S$ (see Theorem 5.4-3, \cite{gustafson1997}).
\item [(R4)] If $A$ and $B$ are invertible, then $(A \otimes B)^{-1}=A^{-1}\otimes B^{-1}.$ 
\item [(R5)] $(A\otimes B)^{\circ -1} =A^{\circ -1}\otimes B^{\circ -1}$ for any square $A$ and $B$ with non zero entries. 
\end{enumerate}
In 2024, Bai \cite{bai2024} found an upper bound for the $1$ and $\infty$-norms of the two-dimensional Wasserstein-$1$ metric matrices (see Theorem \ref{thm:wass two dim norm bounds}(ii)). In 2025, Bai \cite{bai2025} also found an upper bound for the condition number of a two-dimensional Wasserstein-$1$ metric matrix (see Theorem \ref{thm:wass two dim norm bounds}(iv)). In our next main result, we refine these upper bounds with some other results. 
                                                  \begin{theorem}
For the two dimensional Wasserstein-$1$ metric matrix $Q\in \mathbb{R}^{nm \times nm}$, the following are true: 
                                          \begin{enumerate}[(i)]
         \item If $\lambda_1,\lambda_2\leq \frac{1}{3}$, then for any eigenvalue $\alpha$ of $Q$, $0<\alpha< 4.$  
         \item For any eigenvalue $\alpha$ of $Q$, $0<\alpha\leq(1+2~\|L_{[1]}\|_2\cos ({\frac{\pi}{n+1}}))(1+2~\|L_{[2]}\|_2\cos ({\frac{\pi}{m+1}})).$  
         \item $\rho(Q)  \geq (1+\lambda_1)(1+\lambda_2).$
         \item $W(Q)\subset (0,\;\frac{(1+\lambda_1)(1+\lambda_2)(1-\lambda_1^{n-1})(1-\lambda_2^{n-1})}{(1-\lambda_1)(1-\lambda_2)}]
         .$
         \item $\frac{1}{(1+\lambda_1)^2(1+\lambda_2)^2}\leq \|Q\|_1= \|Q\|_{\infty}\leq (1+\frac{2 \lambda_1 (1-\lambda_1^{n-1})}{(1-\lambda_1)})(1+\frac{2 \lambda_2 (1-\lambda_2^{n-1})}{(1-\lambda_2)}).$
         \item $\frac{1}{(1+\lambda_1)^2(1+\lambda_2)^2}\leq \|Q\|_2\leq m_1m_2,$
         where $m_k=\min \{1+2\|L_{[k]}\|_2, \frac{3-\lambda_k}{1-\lambda_k},\frac{2(1+\lambda_k)(1-\lambda_k^{n-1})}{(1-\lambda_k)}\}, k=1,2.$
         \item $\|Q^{-1}\|_1=\|Q^{-1}\|_{\infty}\geq \frac{(1-\lambda_1)(1-\lambda_2)}{(1+\lambda_1)(1+\lambda_2)(1-\lambda_1^n)^2(1-\lambda_2^n)^2}.$
         \item $\frac{(1-\lambda_1)(1-\lambda_2)}{(1+\lambda_1)(1+\lambda_2)}\leq \|Q^{-1}\|_2\leq \frac{(1+\lambda_1)(1+\lambda_2)}{(1-\lambda_1)(1-\lambda_2)}.$
         \item $\frac{(1-\lambda_1)(1-\lambda_2)}{(1+\lambda_1)^3(1+\lambda_2)^3(1-\lambda_1^n)^2(1-\lambda_2^n)^2}\leq \kappa_1(Q)=\kappa_{\infty}(Q)\leq \frac{(1+\lambda_1)(1+\lambda_2)(1-\lambda_1+2\lambda_1(1-\lambda_1^{n-1}))(1-\lambda_2+2\lambda_2(1-\lambda_2^{n-1}))}{(1-\lambda_1)^2(1-\lambda_2)^2}.$
         \item $\frac{(1-\lambda_1)(1-\lambda_2)}{(1+\lambda_1)^3(1+\lambda_2)^3}\leq \kappa_2(Q)\leq m_1m_2\cdot\frac{(1+\lambda_1)(1+\lambda_2)}{(1-\lambda_1)(1-\lambda_2)}.$
     \end{enumerate}    
     \end{theorem}
                                           \begin{proof}
                                            \begin{enumerate}[(i)]
\item Let $\alpha \in \sigma(Q).$ Then, 
$\alpha=\beta_2\beta_1,$ for some
$\beta_1\in \sigma(Q_{[1]})$ and  $\beta_2\in \sigma(Q_{[2]}).$ Therefore, using  Theorem \ref{thm:one dim wass}(i) for $\beta_1$ and $\beta_2$, we have 
$0<\alpha< 4.$
\item Similar to (1), using Theorem \ref{thm:one dim wass}(ii), we can prove it.
\item From the above result (R2) of Kronecker product, we can get 
$$\rho(Q)=\rho(Q_{[2]}\otimes Q_{[1]})=\rho(Q_{[2]})\rho(Q_{[1]}).$$ 
Using Theorem \ref{thm:one dim wass}(iii), we have $\rho(Q)  \geq (1+\lambda_1)(1+\lambda_2).$
\item Since $Q_{[2]}$  is symmetric, $Q_{[2]}$ is normal. Therefore, we have 
$$W(Q)=\text{Co}(W(Q_{[2]})W(Q_{[1]}))$$
using the result (R3) of Kronecker product.
From Theorem \ref{thm:one dim wass}(iv), we have \\
$W(Q_{[1]})\subset (0,\;\frac{(1+\lambda_1)(1-\lambda_1^{n-1})}{1-\lambda_1}]$ and $W(Q_{[2]})\subset (0,\;\frac{(1+\lambda_2)(1-\lambda_2^{n-1})}{1-\lambda_2}].$ So,
                                              \begin{align*}
    \text{Co}(W(Q_{[2]})W(Q_{[1]}))&\subset \text{Co}\Big((0,\;\frac{(1+\lambda_1)(1-\lambda_1^{n-1})}{1-\lambda_1}]\cdot (0,\;\frac{(1+\lambda_2)(1-\lambda_2^{n-1})}{1-\lambda_2}]\Big)\\
   &= (0,\;\frac{(1+\lambda_1)(1+\lambda_2)(1-\lambda_1^{n-1})(1-\lambda_2^{n-1})}{(1-\lambda_1)(1-\lambda_2)}]. 
\end{align*}  
Thus,
$W(Q)\subset (0,\;\frac{(1+\lambda_1)(1+\lambda_2)(1-\lambda_1^{n-1})(1-\lambda_2^{n-1})}{(1-\lambda_1)(1-\lambda_2)}].$
\item Using the result (R1) for $\infty$-norm and Theorem \ref{thm:one dim wass}(v), we can get the desired result.
\item Using the result (R1) for $2$-norm and Theorem \ref{thm:one dim wass}(vi), we can get the desired result. 
\item Using (R4), we get
$$\|Q^{-1}\|_1
=\|Q_{[2]}^{-1}\|_1 \|Q_{[1]}^{-1}\|_1.$$
Now, using Theorem \ref{thm:one dim wass}(vii), we have the result.
\item Similar to (vii).\\
In the similar fashion, we can prove (ix) and (x).
\end{enumerate}  
\end{proof}
                                       \begin{remark}
Similar to the one-dimensional case, it can be observed that the upper bounds in the above inequalities (v) and (ix) sharpen the upper bounds provided in (ii) and (iv) part of Theorem \ref{thm:wass two dim norm bounds}, respectively.  
\end{remark}
                                            \begin{remark}
    Using the result (R1) and Theorem \ref{thm:had norm wass}, the following can be shown that for a two-dimensional Wasserstein-$1$ metric matrix $Q$.
    \begin{enumerate}[(i)]
        \item $\|Q\|_2\leq mn;$
        \item $det(Q)=(1-\lambda_1^2)^{m(n-1)}(1-\lambda_2^2)^{n(m-1)}.$
    \end{enumerate}
\end{remark}
\begin{remark}
Using the result (R5) and Theorem \ref{thm:hadamard inv norm bound} the following can be proved for a two-dimensional Wasserstein-$1$ metric matrix $Q$.
\begin{enumerate}[(i)]
    \item $\|Q^{\circ -1}\|_1=\|Q^{\circ -1}\|_{\infty}=\frac{1}{\lambda_1^{n-1}\lambda_2^{m-1}}\Big(\frac{1-\lambda_1^n}{1-\lambda_1}\Big)\Big(\frac{1-\lambda_2^m}{1-\lambda_2}\Big);$
\item $\|Q^{\circ -1}\|_2\leq \frac{1}{\lambda_1^{2(n-1)}\lambda_2^{2(m-1)}}\Big(\frac{1-\lambda_1^{2n}}{1-\lambda_1^2}\Big)\Big(\frac{1-\lambda_2^{2m}}{1-\lambda_2^2}\Big).$
\end{enumerate}
\end{remark}
