\section{Proof of Theorem \ref{thm:unknown-post}} \label{sec:thm1}

There are two change detectors to consider: the GLR and GSR tests. For each test, there are two parts to prove: the false alarm probability $\Pr_{\infty} \lp \tau \leq T \rp$ and the late detection probability $\Pr_{\nu} \lp \tau \geq \nu + d \rp$. To prove these probability upper bounds, we first express the statistic using the empirical mean of the observations, so that we can exploit the sub-Gaussianity of the samples and apply concentration inequalities in manner similar to the approach in \cite{besson2022efficient, kaufmann2021mixture}.

We first prove the result for the GLR test in \eqref{def:GLR-unknown-post}: Let $\hat{\mu}_{m:n}$ be the empirical mean of the stochastic observations $\lbp X_{m}, \dots, X_{n} \rbp$. Recall that $f_{\mu}$ is the Gaussian density with mean $\mu$ and variance $\sigma^{2}$. To represent the GLR statistic in \eqref{eq:GLR_statistics-unknown-post} in terms of the empirical mean of the observations, we use the following lemma:

\begin{lemma}\label{lem:GLR-kl-unknown-post}
For any $\mu \in \mbb{R}$ and $k, n \in \lbp 1, \dots, T \rbp$ where $k \leq n$,
%
\begin{align}
    \log \lp \frac{\sup_{\mu' \in \mbb{R}}\prod_{i = k}^{n} f_{\mu'} \lp X_{i} \rp}{\prod_{i = k}^{n} f_{\mu} \lp X_{i} \rp} \rp = \lp n - k + 1 \rp \mathrm{kl}\lp\hat{\mu}_{k:n};\mu\rp.\label{eq:GLR-kl}
\end{align}
%
where $\mathrm{kl} \lp x; y \rp \coloneqq \frac{\lp x - y \rp^{2}}{2 \sigma^{2}}$ is the KL divergence between two Gaussian distributions with common variance $\sigma^{2}$ and different mean $x$ and $y$, respectively.
\end{lemma}

\begin{proof}

For any $\mu \in \mbb{R}$ and $k, n \in \lbp 1, \dots, T \rbp$ where $k \leq n$, we can show that
%
\begin{align}
\begin{aligned}
    &\log \lp \frac{\sup_{\mu' \in \mbb{R}}\prod_{i = k}^{n} f_{\mu'} \lp X_{i} \rp}{\prod_{i = k}^{n} f_{\mu} \lp X_{i} \rp} \rp \\
    &=\log \lp \frac{\frac{1}{\lp 2 \pi \sigma^{2} \rp^{n/2}} \exp \lp - \frac{1}{2\sigma^{2}} \inf_{\mu' \in \mbb{R}} \sum_{i = k}^{n} \lp X_{i} - \mu' \rp^{2} \rp}{\frac{1}{\lp 2 \pi \sigma^{2} \rp^{n/2}} \exp \lp - \frac{1}{2\sigma^{2}} \sum_{i = k}^{n} \lp X_{i} - \mu' \rp^{2} \rp} \rp \\
    &\overset{(a)}{=} \log \lp \frac{\frac{1}{\lp 2 \pi \sigma^{2} \rp^{n/2}} \exp \lp - \frac{1}{2 \sigma^{2}} \sum_{i = k}^{n} \lp X_{i} - \hat{\mu}_{k : n} \rp^{2} \rp}{\frac{1}{\lp 2 \pi \sigma^{2} \rp^{n/2}} \exp \lp - \frac{1}{2\sigma^{2}} \sum_{i = k}^{n} \lp X_{i} - \mu \rp^{2} \rp} \rp \\
    &= \frac{1}{2\sigma^{2}} \sum_{i = k}^{n} \lb \lp X_{i} - \mu \rp^{2} - \lp X_{i} - \hat{\mu}_{k:n} \rp^{2} \rb \\
    &= \frac{1}{2\sigma^{2}} \lb \lp n - k + 1 \rp \mu^{2} - 2 \mu \sum_{i = k}^{n} X_{i} - \lp n - k + 1 \rp \hat{\mu}^{2}_{k:n} + 2 \hat{\mu}_{k:n} \sum_{i = k}^{n} X_{i}  \rb \\
    &= \frac{n - k + 1}{2\sigma^{2}} \lp \mu - \hat{\mu}_{k:n} \rp^{2} \\
    &= \lp n - k + 1 \rp \mrm{kl} \lp \hat{\mu}_{k:n}; \mu \rp
\end{aligned}
\end{align}
%
where step $(a)$ is owing to the fact that $\sum_{i = k}^{n} \lp X_{i} - \mu' \rp^{2}$ is minimized when $\mu' = \hat{\mu}_{k:n}$.
\end{proof}

For upper bounding the false alarm probability of the GLR test in \eqref{def:GLR-unknown-post}, we use the following lemma as our concentration inequality:

\begin{lemma} \label{lem:mix_martin}
Let $\lp X_{n}\rp_{n=1}^{\infty}$ be an i.i.d. $\sigma^{2}$-sub-Gaussian sequence with mean $\mu$, then for all $\delta\in\lp0,1\rp$,
%
\textup{\begin{align}
    &\Pr_{\infty}\lp\exists\,n\in\mbb{N}:n\mrm{kl}\lp\hat{\mu}_{1:n},\mu\rp-3\log\lp1+\log\lp n\rp\rp>\frac{5}{4}\log\lp\frac{1}{\delta}\rp+\frac{11}{2}\rp\leq\delta.\label{eq:mix_mart}
\end{align}}
%
\end{lemma}

\begin{proof} [Proof of Lemma \ref{lem:mix_martin}]
Let $Y\lp n\rp\coloneqq n \mrm{kl}\lp\hat{\mu}_{1:n},\mu\rp-3\log\lp1+\log\lp n\rp\rp$. To prove this lemma, we associate the random process $\{Y \lp n \rp\}$ with a supermartingale, so that we can apply Ville's inequality. To this end, we use the following lemma derived in \cite{kaufmann2021mixture} to construct the associated supermartingale. 
%
\begin{lemma}[Lemma 13 from \cite{kaufmann2021mixture}]
Let $c\coloneqq\frac{5}{4}\log\lp\frac{\pi^{2}/3}{\lp\log\lp5/4\rp\rp^{2}}\rp$. For any $x > 0$, there exists a nonnegative (mixture) martingale $Z\lp t\rp$ such that $Z\lp 0 \rp=1$ and for any $x>0$ and $n\in\mbb{N}$,
%
\begin{equation}
    \lbp Y\lp n\rp-c\geq x\rbp\subseteq\lbp Z\lp n\rp\geq e^{\frac{4x}{5}}\rbp\label{eq:mix_martin_include-1}.
\end{equation}
%
\end{lemma}
%
Continuing with the proof of Lemma~\ref{lem:mix_martin}, for any $\lambda>0$ and $z>1$, we have:
%
\begin{align}\nonumber
    \lbp e^{\lambda\lb Y\lp n\rp-11/2\rb}\geq z\rbp&\overset{(a)}{\subseteq}\lbp e^{\lambda\lb Y\lp n\rp-c\rb}\geq z\rbp  \\\nonumber
    &=\lbp Y\lp n\rp - c\geq \frac{\log\lp z\rp}{\lambda}\rbp\\\nonumber
    &\overset{(b)}{\subseteq}\lbp Z\lp n\rp\geq e^{\frac{4\log\lp z\rp}{5\lambda}}\rbp\\\nonumber
    &=\lbp Z\lp n\rp\geq z^{\frac{4}{5\lambda}}\rbp\\
    &=\lbp\lp Z\lp n\rp\rp^{5\lambda/4}\geq z\rbp\label{eq:mix_martin_include-2}
\end{align}
%
where step $(a)$ is owing to the fact that $\frac{11}{2} \geq c$, and step $(b)$ is due to \eqref{eq:mix_martin_include-1}. When $\lambda\leq\frac{4}{5}$, because $g \lp x \rp = x^{5\lambda/4}$ is a concave function, $\lp Z\lp n\rp\rp^{5\lambda/4}$ is a supermartingale.
Hence, for any $\lambda\in\lp0,\frac{4}{5}\rb$, and $y > 11/2$, we have the following inequality:
%
\begin{align}\nonumber
    \Pr_{\infty}\lp\exists\,n\in\mbb{N}:Y\lp n\rp>y\rp&=\Pr_{\infty}\lp\cup_{n=1}^{\infty}\lbp Y\lp n\rp>y\rbp\rp\\\nonumber
    &=\Pr_{\infty}\lp\cup_{n=1}^{\infty}\lbp e^{\lambda Y\lp n\rp}>e^{\lambda y}\rbp\rp\\\nonumber
    &=\Pr_{\infty}\lp\cup_{n=1}^{\infty}\lbp e^{\lambda\lb Y\lp n\rp - 11/2\rb}>e^{\lambda\lp y - 11/2 \rp}\rbp\rp\\\nonumber
    &\overset{(a)}{\leq}\Pr_{\infty}\lp\cup_{n=1}^{\infty}\lbp\lp Z\lp n\rp\rp^{5\lambda/4}>e^{\lambda \lp y - 11/2 \rp}\rbp\rp\\\nonumber
    &=\Pr_{\infty}\lp\exists\,n\in\mbb{N}:\lp Z\lp n\rp\rp^{5\lambda/4}>e^{\lambda\lp y-11/2\rp}\rp\\\nonumber
    &=\Pr_{\infty}\lp \sup_{n \in \mbb{N}} \lp Z\lp n\rp\rp^{5\lambda/4}>e^{\lambda\lp y-11/2\rp}\rp\\
    &\overset{(b)}{\leq}e^{-\lambda\lp y-11/2 \rp}\label{eq:Ville}
\end{align}
%
where step $(a)$ is due to \eqref{eq:mix_martin_include-2} and step $(b)$ comes from Ville's inequality \cite{ville1939etude}. By minimizing \eqref{eq:Ville} over $\lambda\in\lp0,\frac{4}{5}\rb$, we obtain
%
\begin{align}
    \Pr_{\infty}\lp\exists\,n\in\mbb{N}:Y\lp n\rp>y\rp&\leq e^{-\frac{4}{5}\lp y-11/2 \rp}\label{eq:Minimize}.
\end{align}
%
Then, by letting $\delta=e^{-\frac{4}{5}\lp y-11/2 \rp}$, we can see that for any $\delta\in\lp0,1\rp$,
%
\begin{align}
    \Pr_{\infty}\lp\exists\,n\in\mbb{N}:Y\lp n\rp>\frac{5}{4}\log\lp\frac{1}{\delta}\rp + \frac{11}{2} \rp&\leq\delta\label{eq:lemma-end}.
\end{align}
%
\end{proof}

Continuing with the proof of the upper bound on the false alarm probability, for any $T\in\mbb{N}$, we can upper bound the false alarm probability as follows:
\begin{align}
    &\Pr_{\infty} \lp \tau_{\mrm{GLR}} \leq T \rp \nonumber\\
    &\leq \Pr_{\infty} \lp \tau_{\mrm{GLR}} < \infty \rp \nonumber\\
    &=\Pr_{\infty}\lp\exists\,n\in\mbb{N}: G_{n} > \beta_{\mrm{GLR}} \lp n,\delta_{\mathrm{F}}\rp\rp \nonumber\\
    &\overset{(a)}{=}\Pr_{\infty}\lp\exists\, n \in\mbb{N}:\sup_{1 \leq k \leq n} \lp n - k + 1 \rp \mathrm{kl} \lp \hat{\mu}_{k:n}; \mu_{0} \rp > \beta_{\mrm{GLR}} \lp n, \delta_{\mathrm{F}} \rp \rp \nonumber\\
    &=\Pr_{\infty}\bigg(\exists\,k,r\in\mbb{N}: r\mathrm{kl}\lp\hat{\mu}_{k:k+r-1};\mu_{0}\rp>3\log\lp1+\log\lp k+r-1\rp\rp \nonumber\\
    &\quad\quad\quad+\frac{5}{4}\log\lp\frac{3\lp k+r-1\rp^{3/2}}{\delta_{\mathrm{F}}}\rp+\frac{11}{2}\bigg) \nonumber\\
    &\overset{(b)}{\leq}\sum_{k=1}^{\infty}\Pr_{\infty}\bigg(\exists\,r\in\mbb{N}: r\mathrm{kl}\lp\hat{\mu}_{k:k+r-1};\mu_{0}\rp>3\log\lp1+\log\lp k+r-1\rp\rp \nonumber\\
    &\quad\quad\quad\quad\quad+\frac{5}{4}\log\lp\frac{3\lp k+r-1\rp^{3/2}}{\delta_{\mathrm{F}}}\rp+\frac{11}{2}\bigg) \nonumber\\
    &\overset{(c)}{\leq}\sum_{k=1}^{\infty}\Pr_{\infty}\bigg(\exists\,r\in\mbb{N}: r\mathrm{kl}\lp\hat{\mu}_{k:k+r-1};\mu_{0}\rp-3\log\lp1+\log\lp r\rp\rp \nonumber\\
    &\quad\quad\quad\quad\quad>\frac{5}{4}\log\lp\frac{3k^{3/2}}{\delta_{\mathrm{F}}}\rp+\frac{11}{2}\bigg) \nonumber\\
    &\overset{(d)}{\leq}\sum_{k=1}^{\infty}\frac{\delta_{\mathrm{F}}}{3k^{3/2}} \nonumber \\
    &\leq\delta_{\mathrm{F}}\label{eq:FA_GLR_post_unknown}.
\end{align}
In step $(a)$, we apply Lemma \ref{lem:GLR-kl-unknown-post} to represent $G_{n}$ with the empricial mean of the observations. Step $(b)$ is due to the union bound, and step $(c)$ results from the fact that $\log$ is an increasing function. In step $(d)$, we exploit the concentration inequality in Lemma \ref{lem:mix_martin}.

Next, we prove the detection delay performance of the GLR test in \eqref{def:GLR-unknown-post}: Recall the definition of $d$ in \eqref{eq:latency-unknown-post} and $\Delta = \lba \mu_{0} - \mu_{1} \rba$. For any $\nu \in \lbp 1, \dots, T - d \rbp$, we have
%
\begin{align}
    &\Pr_{\nu} \lp \tau_{\mrm{GLR}} \geq \nu + d \rp \nonumber\\
    &=\Pr_{\nu}\lp \forall\,n \in \lbp 1, \dots, \nu + d - 1 \rbp: G_{n} \leq \beta_{\mrm{GLR}} \lp n,\delta_{\mathrm{F}}\rp\rp \nonumber\\
    &\overset{(a)}{=} \Pr_{\nu}\lp \forall\,n \in \lbp 1, \dots, \nu + d - 1 \rbp: \sup_{1 \leq k \leq n}\lp n - k + 1 \rp \mathrm{kl} \lp \hat{\mu}_{k:n};\mu_{0}\rp \leq \beta_{\mrm{GLR}} \lp n,\delta_{\mathrm{F}}\rp\rp \nonumber\\
    &\overset{(b)}{\leq} \Pr_{\nu} \lbp \sup_{1 \leq k \leq \nu + d - 1} \lp \nu + d - k \rp \mathrm{kl} \lp \hat{\mu}_{k:\nu + d - 1}; \mu_{0} \rp \leq \beta_{\mrm{GLR}} \lp \nu + d - 1, \delta_{\mathrm{F}} \rp \rbp \nonumber\\
    &\overset{(c)}{\leq} \Pr_{\nu} \lbp d\mathrm{kl} \lp \hat{\mu}_{\nu: \nu + d - 1}; \mu_{0} \rp \leq \beta_{\mrm{GLR}} \lp \nu + d - 1, \delta_{\mathrm{F}} \rp \rbp \nonumber\\
    &\overset{(d)}{\leq} \Pr_{\nu} \lbp d \mathrm{kl} \lp \hat{\mu}_{\nu: \nu + d - 1}; \mu_{0} \rp \leq \beta_{\mrm{GLR}} \lp T, \delta_{\mrm{F}} \rp \rbp \nonumber\\
    &=\Pr_{\nu}\lbp\lba\hat{\mu}_{\nu:\nu + d - 1}-\mu_{0}\rba\leq\sqrt{\frac{2\sigma^{2}}{d} \beta_{\mrm{GLR}}\lp T,\delta_{\mathrm{F}}\rp}\rbp \nonumber\\
    &\overset{(e)}{\leq} \Pr_{\nu} \lbp \lba \hat{\mu}_{\nu: \nu + d - 1} - \mu_{1} \rba \geq \Delta - \sqrt{\frac{2 \sigma^{2}}{d} \beta_{\mrm{GLR}} \lp T, \delta_{\mathrm{F}} \rp} \rbp \label{eq:proof_Latency_GLR_post_unknown_1}
\end{align}
%
where step $(a)$ results from Lemma \ref{lem:GLR-kl-unknown-post}, and step $(b)$ is due to the fact that $\lbp \nu + d - 1 \rbp \subseteq \lbp 1, \dots, \nu + d - 1 \rbp$. In step $(c)$, we exploit the definition of supremum. In step $(d)$, we apply the fact that $\beta_{\mrm{GLR}}$ is increasing with the time step $n$. Step $(e)$ stems directly from triangle inequality. Next, by plugging in the definition of $d$ in \eqref{eq:latency-unknown-post}, we have
%
\begin{align}
    &\Pr_{\nu}\lp \tau_{\mrm{GLR}} \geq \nu + d \rp \nonumber\\
    &\overset{(a)}{\leq} \Pr_{\nu} \lbp \lba \hat{\mu}_{\nu: \nu + d - 1} - \mu_{1} \rba \geq \sqrt{\frac{2 \sigma^{2}}{d} \log \lp \frac{2}{\delta_{\mathrm{D}}} \rp} \rbp \nonumber\\
    &=\Pr_{\nu}\lbp\hat{\mu}_{\nu:\nu+d-1}-\mu_{1}\geq\sqrt{\frac{2\sigma^{2}}{d}\log\lp\frac{2}{\delta_{\mathrm{D}}}\rp}\rbp \nonumber\\
    &\quad+\Pr_{\nu}\lbp\hat{\mu}_{\nu:\nu+d-1}-\mu_{1}\geq\sqrt{\frac{2\sigma^{2}}{d}\log\lp\frac{2}{\delta_{\mathrm{D}}}\rp}\rbp \nonumber\\
    &\overset{(b)}{\leq}2\exp\lp-\frac{d}{2\sigma^{2}}\lp\sqrt{\frac{2\sigma^{2}}{d}\log\lp\frac{2}{\delta_{\mathrm{D}}}\rp}\rp^{2}\rp \nonumber\\
    &=\delta_{\mathrm{D}}\label{eq:proof_Latency_GLR_post_unknown_2}
\end{align}
%
where step $(a)$ stems from \eqref{eq:latency-unknown-post}. In step $(b)$, we exploit the $\sigma^{2}$-sub-Gaussianity of the post-change distribution by applying the Chernoff bound.

Now we focus on the GSR test in \eqref{def:GSR-unknown-post}. We first prove the upper bound on the false alarm probability of the GSR test using that of the GLR test in \eqref{def:GLR-unknown-post} as follows: Recall the definition of $W_{n}$ in \eqref{def:GSR-unknown-post} and $\beta_{\mrm{GSR}}$ in \eqref{def:GSR-unknown-post-thres}. For any $T \in \mbb{N}$,
%
\begin{align}
    &\Pr_{\infty} \lp \tau_{\mrm{GSR}} \leq T \rp \nonumber\\
    &=\Pr_{\infty} \lp \exists n \leq T: \log W_{n} \geq \beta_{\mrm{GSR}} \lp n, \delta_{\mrm{F}} \rp \rp \nonumber\\
    &=\Pr_{\infty} \lp \exists n \leq T: \sum_{k = 1}^{n}  \frac{\sup_{\mu\in\mbb{R}}\prod_{i=k}^{n}f_{\mu}(X_i)}{\prod_{i=k}^{n}f_{\mu_{0}}(X_i)} \geq n \exp \lp \beta_{\mrm{GLR}} \lp n, \delta_{\mrm{F}} \rp \rp \rp \nonumber\\
    &=\Pr_{\infty} \lp \exists n \leq T: \frac{1}{n} \sum_{k = 1}^{n}  \frac{\sup_{\mu\in\mbb{R}}\prod_{i=k}^{n}f_{\mu}(X_i)}{\prod_{i=k}^{n}f_{\mu_{0}}(X_i)} \geq \exp \lp \beta_{\mrm{GLR}} \lp n, \delta_{\mrm{F}} \rp \rp \rp \nonumber\\
    &\overset{(a)}{\leq} \Pr_{\infty} \lp \exists n \leq T: \sup_{1 \leq k \leq n}  \frac{\sup_{\mu\in\mbb{R}}\prod_{i=k}^{n}f_{\mu}(X_i)}{\prod_{i=k}^{n}f_{\mu_{0}}(X_i)} \geq \exp \lp \beta_{\mrm{GLR}} \lp n, \delta_{\mrm{F}} \rp \rp \rp \nonumber\\
    &= \Pr_{\infty} \lp \exists n \leq T: \sup_{1 \leq k \leq n} \log \lp \frac{\sup_{\mu\in\mbb{R}}\prod_{i=k}^{n}f_{\mu}(X_i)}{\prod_{i=k}^{n}f_{\mu_{0}}(X_i)} \rp \geq  \beta_{\mrm{GLR}} \lp n, \delta_{\mrm{F}} \rp \rp \nonumber\\
    &= \Pr_{\infty} \lp \exists n \leq T: G_{n} \geq  \beta_{\mrm{GLR}} \lp n, \delta_{\mrm{F}} \rp \rp \nonumber\\
    &= \Pr_{\infty} \lp \tau_{\mrm{GSR}} \leq T \rp \nonumber\\
    &\overset{(b)}{\leq} \delta_{\mrm{F}}.\label{eq:proof_FA_GSR_post_unknown}
\end{align}
%
In step $(a)$, we use the fact that for a set of real numbers, their mean is smaller than their supremum. In step $(b)$, we apply \eqref{eq:FA_GLR_post_unknown}.

Next, we prove the detection delay performance of the GSR test in \eqref{def:GSR-unknown-post}: Recall the definition of $d$ in \eqref{eq:latency-unknown-post} and $\Delta = \lba \mu_{0} - \mu_{1} \rba$. For any $\nu \in \lbp 1, \dots, T - d \rbp$, we have
%
\begin{align}
    &\Pr_{\nu} \lp \tau_{\mrm{GSR}} \geq \nu + d \rp \nonumber\\
    &=\Pr_{\nu}\lp \forall\,n \in \lbp 1, \dots, \nu + d - 1 \rbp: \log W_{n} \leq \beta_{\mrm{GSR}} \lp n,\delta_{\mathrm{F}}\rp\rp \nonumber\\
    &=\Pr_{\nu}\lp \forall\,n \in \lbp 1, \dots, \nu + d - 1 \rbp: \log \lp \sum_{k = 1}^{n}  \frac{\sup_{\mu\in\mbb{R}}\prod_{i=k}^{n}f_{\mu}(X_i)}{\prod_{i=k}^{n}f_{\mu_{0}}(X_i)} \rp \leq \beta_{\mrm{GSR}} \lp n,\delta_{\mathrm{F}}\rp\rp \nonumber\\
    &\overset{(a)}{\leq} \Pr_{\nu} \lbp \log \lp \sum_{k = 1}^{\nu + d - 1} \frac{\sup_{\mu \in \mbb{R}} \prod_{i = k}^{\nu + d - 1} f_{\mu}(X_i)}{\prod_{i = k}^{\nu + d - 1}f_{\mu_{0}}(X_i)} \rp \leq \beta_{\mrm{GSR}} \lp \nu + d - 1,\delta_{\mathrm{F}} \rp \rbp \nonumber\\
    &\leq \Pr_{\nu} \lbp \log \lp \frac{\sup_{\mu \in \mbb{R}} \prod_{i = \nu}^{\nu + d - 1} f_{\mu}(X_i)}{\prod_{i = \nu}^{\nu + d - 1}f_{\mu_{0}}(X_i)} \rp \leq \beta_{\mrm{GSR}} \lp \nu + d - 1,\delta_{\mathrm{F}} \rp \rbp \nonumber\\
    &\overset{(b)}{=} \Pr_{\nu} \lbp d\mathrm{kl} \lp \hat{\mu}_{\nu: \nu + d - 1}; \mu_{0} \rp \leq \beta_{\mrm{GSR}} \lp \nu + d - 1, \delta_{\mathrm{F}} \rp \rbp \nonumber\\
    &\overset{(c)}{\leq} \Pr_{\nu} \lbp d \mathrm{kl} \lp \hat{\mu}_{\nu: \nu + d - 1}; \mu_{0} \rp \leq \beta_{\mrm{GSR}} \lp T, \delta_{\mrm{F}} \rp \rbp \nonumber\\
    &=\Pr_{\nu}\lbp\lba\hat{\mu}_{\nu:\nu + d - 1}-\mu_{0}\rba\leq\sqrt{\frac{2\sigma^{2}}{d} \beta_{\mrm{GSR}}\lp T,\delta_{\mathrm{F}}\rp}\rbp \nonumber\\
    &\overset{(d)}{\leq} \Pr_{\nu} \lbp \lba \hat{\mu}_{\nu: \nu + d - 1} - \mu_{1} \rba \geq \Delta - \sqrt{\frac{2 \sigma^{2}}{d} \beta_{\mrm{GSR}} \lp T, \delta_{\mathrm{F}} \rp} \rbp \label{eq:proof_Latency_GSR_post_unknown}
\end{align}
%
where step $(a)$ stems from the fact that $\lbp \nu + d - 1 \rbp \subseteq \lbp 1, \dots, \nu + d - 1 \rbp$, and step $(b)$ is due to Lemma \ref{lem:GLR-kl-unknown-post}. In step $(c)$, we apply the fact that $\beta_{\mrm{GSR}}$ is increasing with the time step $n$. Step $(d)$ stems directly from triangle inequality. Following the same steps in \eqref{eq:proof_Latency_GLR_post_unknown_2}, we can prove that $\Pr_{\nu} \lp \tau_{\mrm{GSR}} \geq \nu + d \rp \leq \delta_{\mrm{D}}$.

\section{Proof of Theorem \ref{thm:pre-post-unknown}} \label{sec:thm2}

Similar to Theorem \ref{thm:unknown-post}, there are two tests to consider in Theorem \ref{thm:pre-post-unknown}: the GLR test in \eqref{def:GLR-unknown-pre-post} and GSR test in \eqref{def:GSR-unknown-pre-post}. For each test, there are two parts to prove: the false alarm constraint $\Pr_{\infty} \lp \tau \leq T \rp$ and the detection delay performance $\Pr_{\nu} \lp \tau \geq \nu + d \rp$. To prove these two inequalities for the GLR test, we first associate the GLR statistic with the empirical mean of the sub-Gaussian observations, so that we can exploit the sub-Gaussianity to apply the concentration inequality in Lemma \ref{lem:mix_martin}.

Recall that $\hat{\mu}_{m:n}$ is the empirical mean of samples $\lbp X_{m},\dots,X_{n}\rbp$ for any $m \leq n \in \mbb{N}$, and that $f_{\mu}$ is the density of a Gaussian random variable with mean $\mu$ and variance $\sigma^{2}$. We use the following lemma to represent the GLR statistic in \eqref{eq:GLR_statistics_pre-post-unknown} using the empirical mean of the observations. 

\begin{lemma}\label{lem:GLR-kl-unknown-pre-post}
For any $n\in\mbb{N}$ and any $k\in\lbp1,\dots,n\rbp$, we have:
%
\textup{\begin{align}
    &\log\lp\frac{\sup_{\mu_{0}'\in\mbb{R}}\prod_{i=1}^{k}f_{\mu_{0}'}\lp X_{i}\rp\sup_{\mu_{1}'\in\mbb{R}}\prod_{i=k+1}^{n}f_{\mu_{1}'}\lp X_{i}\rp}{\sup_{\mu\in\mbb{R}}\prod_{i=1}^{n}f_{\mu}\lp X_{i}\rp}\rp=k\mrm{kl}\lp\hat{\mu}_{1:k};\hat{\mu}_{1:n}\rp+\lp n-k\rp\mrm{kl}\lp\hat{\mu}_{k+1:n};\hat{\mu}_{1:n}\rp\label{eq:lr-kl}
\end{align}}
%
where \textup{$\mrm{kl}\lp x;y\rp\coloneqq\frac{(x-y)^{2}}{2\sigma^{2}}$} is the KL-divergence between two Gaussian distributions with common variance $\sigma^{2}$ and different means $x,y\in\mbb{R}$.
\end{lemma}

\begin{proof} [Proof of Lemma \ref{lem:GLR-kl-unknown-pre-post}]
We can show that for any $n\in\mbb{N}$ and any $s\in\lbp1,\dots,n\rbp$,
%
\begin{align}\nonumber
    &\log\lp\frac{\sup_{\theta_{0}\in\mbb{R}}\prod_{i=1}^{s}f_{\theta_{0}}\lp X_{i}\rp\sup_{\theta_{1}\in\mbb{R}}\prod_{i=s+1}^{n}f_{\theta_{1}}\lp X_{i}\rp}{\sup_{\theta\in\mbb{R}}\prod_{i=1}^{n}f_{\theta}\lp X_{i}\rp}\rp\\\nonumber
    &=\log\lp\frac{\sup_{\theta_{0}\in\mbb{R}}\prod_{i=1}^{s}\frac{1}{\sqrt{2\pi\sigma^{2}}}\exp\lp-\frac{\lp X_{i}-\theta_{0}\sigma^{2}\rp^{2}}{2\sigma^{2}}\rp\sup_{\theta_{1}\in\mbb{R}}\prod_{i=s+1}^{n}\frac{1}{\sqrt{2\pi\sigma^{2}}}\exp\lp-\frac{\lp X_{i}-\theta_{1}\sigma^{2}\rp^{2}}{2\sigma^{2}}\rp}{\sup_{\theta\in\mbb{R}}\prod_{i=1}^{n}\frac{1}{\sqrt{2\pi\sigma^{2}}}\exp\lp-\frac{\lp X_{i}-\theta\sigma^{2}\rp^{2}}{2\sigma^{2}}\rp}\rp\\\nonumber
    &=\log\lp\frac{\exp\lp-\inf_{\theta_{0}\in\mbb{R}}\sum_{i=1}^{s}\frac{\lp X_{i}-\theta_{0}\sigma^{2}\rp^{2}}{2\sigma^{2}}\rp\exp\lp-\inf_{\theta_{1}\in\mbb{R}}\sum_{i=s+1}^{n}\frac{\lp X_{i}-\theta_{1}\sigma^{2}\rp^{2}}{2\sigma^{2}}\rp}{\exp\lp-\inf_{\theta\in\mbb{R}}\sum_{i=1}^{n}\frac{\lp X_{i}-\theta\sigma^{2}\rp^{2}}{2\sigma^{2}}\rp}\rp\\\nonumber
    &\overset{(a)}{=}\log\lp\frac{\exp\lp-\sum_{i=1}^{s}\frac{\lp X_{i}-\hat{\mu}_{1:s}\rp^{2}}{2\sigma^{2}}\rp\exp\lp-\sum_{i=s+1}^{n}\frac{\lp X_{i}-\hat{\mu}_{s+1:n}\rp^{2}}{2\sigma^{2}}\rp}{\exp\lp-\sum_{i=1}^{n}\frac{\lp X_{i}-\hat{\mu}_{1:n}\rp^{2}}{2\sigma^{2}}\rp}\rp\\\nonumber
    &=\log\lp\frac{\exp\lp-\sum_{i=1}^{s}\frac{X_{i}^{2}-2X_{i}\hat{\mu}_{1:s}+\hat{\mu}_{1:s}^{2}}{2\sigma^{2}}\rp\exp\lp-\sum_{i=s+1}^{n}\frac{X_{i}^{2}-2X_{i}\hat{\mu}_{s+1:n}+\hat{\mu}_{s+1:n}^{2}}{2\sigma^{2}}\rp}{\exp\lp-\sum_{i=1}^{n}\frac{X_{i}^{2}-2X_{i}\hat{\mu}_{1:n}+\hat{\mu}_{1:n}^{2}}{2\sigma^{2}}\rp}\rp\\\nonumber
    &=\sum_{i=1}^{s}\frac{2X_{i}\hat{\mu}_{1:s}-\hat{\mu}_{1:s}^{2}}{2\sigma^{2}}+\sum_{i=s+1}^{n}\frac{2X_{i}\hat{\mu}_{s+1:n}-\hat{\mu}_{s+1:n}^{2}}{2\sigma^{2}}-\sum_{i=1}^{n}\frac{2X_{i}\hat{\mu}_{1:n}-\hat{\mu}_{1:n}^{2}}{2\sigma^{2}}\\\nonumber
    &=s\frac{\hat{\mu}_{1:s}^{2}}{2\sigma^{2}}+\lp n-s\rp\frac{\hat{\mu}_{s+1:n}^{2}}{2\sigma^{2}}-n\frac{\hat{\mu}_{1:n}^{2}}{2\sigma^{2}}\\\nonumber
    &=s\frac{\hat{\mu}_{1:s}^{2}}{2\sigma^{2}}+\lp n-s\rp\frac{\hat{\mu}_{s+1:n}^{2}}{2\sigma^{2}}+s\frac{\hat{\mu}_{1:n}^{2}}{2\sigma^{2}}+\lp n-s\rp\frac{\hat{\mu}_{1:n}^{2}}{2\sigma^{2}}-2\frac{s\hat{\mu}_{1:s}\hat{\mu}_{1:n}}{2\sigma^{2}}-2\frac{\lp n-s\rp\hat{\mu}_{s+1:n}\hat{\mu}_{1:n}}{2\sigma^{2}}\\\nonumber
    &=s\frac{\lp\hat{\mu}_{1:s}-\hat{\mu}_{1:n}\rp^{2}}{2\sigma^{2}}+\lp n-s\rp\frac{\lp\hat{\mu}_{s+1:n}-\hat{\mu}_{1:n}\rp^{2}}{2\sigma^{2}}\\
    &=s\mrm{kl}\lp\hat{\mu}_{1:s};\hat{\mu}_{1:n}\rp+\lp n-s\rp\mrm{kl}\lp\hat{\mu}_{s+1:n};\hat{\mu}_{1:n}\rp\label{eq:lem1_proof}
\end{align}
%
where step $(a)$ follows from the fact that $\sum_{i=t}^{t'}\lp X_{i}-a\rp^{2}$ is minimized when $a=\hat{\mu}_{t:t'}$.
\end{proof}

Recall that $\mu_{0}$ is the pre-change mean of the sample sequence $\lp X_{i} \rp_{i = 1}^{\infty}$. By Lemmas \ref{lem:mix_martin} and \ref{lem:GLR-kl-unknown-pre-post}, for any $T \in \mbb{N}$,
%
\begin{align}\nonumber
    &\Pr_{\infty}\lp \tilde{\tau}_{\mrm{GLR}} \leq T\rp\\\nonumber
    &\leq \Pr_{\infty}\lp \tilde{\tau}_{\mrm{GLR}}<\infty\rp\\\nonumber
    &=\Pr_{\infty}\lp\exists\,n\in\mbb{N}:\;\sup_{1\leq k\leq n}\log\lp\frac{\sup_{\mu_{0}'\in\mbb{R}}\prod_{i=1}^{k}f_{\mu_{0}'}\lp X_{i}\rp\sup_{\mu_{1}'\in\mbb{R}}\prod_{i=k+1}^{n}f_{\mu_{1}'}\lp X_{i}\rp}{\sup_{\mu\in\mbb{R}}\prod_{i=1}^{n}f_{\mu}\lp X_{i}\rp}\rp\geq \tilde{\beta}_{\mrm{GLR}} \lp n,\delta_{\mrm{F}}\rp\rp\\\nonumber
    &\overset{(a)}{=}\Pr_{\infty}\lp\exists\,n\in\mbb{N}:\;\sup_{1\leq k\leq n}k\mrm{kl}\lp\hat{\mu}_{1:k},\hat{\mu}_{1:n}\rp+\lp n-k\rp\mrm{kl}\lp\hat{\mu}_{k+1:n},\hat{\mu}_{1:n}\rp\geq\tilde{\beta}_{\mrm{GLR}} \lp n,\delta_{\mrm{F}}\rp\rp\\\nonumber
    &=\Pr_{\infty}\left(\exists\,k\leq n\in\mathbb{N}:k\mrm{kl}(\hat{\mu}_{1:k},\hat{\mu}_{1:n})+(n-k)\mrm{kl}(\hat{\mu}_{k+1:n},\hat{\mu}_{1:n})> \tilde{\beta}_{\mrm{GLR}} \lp n,\delta_{\mrm{F}}\rp\right)\\\nonumber
    &\overset{(b)}{=}\Pr_{\infty}\left(\exists\,k\leq n\in\mbb{N}:\inf_{\mu}k\mrm{kl}(\hat{\mu}_{1:k},\mu)+(n-k)\mrm{kl}(\hat{\mu}_{k+1:n},\mu)> \tilde{\beta}_{\mrm{GLR}}(n,\delta_{\mrm{F}})\right)\\\nonumber
    &\leq\Pr_{\infty}\left(\exists\,k\leq n\in\mathbb{N}:k\mrm{kl}(\hat{\mu}_{1:k},\mu_{0})+(n-k)\mrm{kl}(\hat{\mu}_{k+1:n},\mu_{0})> \tilde{\beta}_{\mrm{GLR}}(n,\delta_{\mrm{F}})\right)\\\nonumber
    &=\Pr_{\infty}\Bigg(\exists\,k,r\in\mathbb{N}:\\\nonumber
    &\quad\quad\quad\quad s\mrm{kl}(\hat{\mu}_{1:k},\mu_{0})+r\mrm{kl}(\hat{\mu}_{k+1:k+r},\mu_{0})>6\log(1+\log(k+r))+\frac{5}{2}\log\lp\frac{4\lp k+r\rp^{\frac{3}{2}}}{\delta_{\mrm{F}}}\rp+11\Bigg)\\\nonumber
    &\overset{(c)}{\leq}\Pr_{\infty}\Bigg(\exists\,k,r\in\mathbb{N}:\lbp k\mrm{kl}(\hat{\mu}_{1:k},\mu_{0})>3\log(1+\log(k+r))+\frac{5}{4}\log\lp\frac{4\lp k+r\rp^{3/2}}{\delta_{\mrm{F}}}\rp+\frac{11}{2}\rbp\cup\\\nonumber
    &\quad\quad\quad\Bigg\{ r\mrm{kl}(\hat{\mu}_{k+1:k+r},\mu_{0}) > 3\log(1+\log(k+r)) +\frac{5}{4}\log\lp\frac{4\lp k+r\rp^{3/2}}{\delta_{\mrm{F}}}\rp+\frac{11}{2} \Bigg\} \Bigg)\\\nonumber
    &=\Pr_{\infty}\Bigg(\Bigg\{\exists\,k,r\in\mathbb{N}:k\mrm{kl}(\hat{\mu}_{1:k},\mu_{0})>3\log(1+\log(k+r))+\frac{5}{4}\log\lp\frac{4\lp k+r\rp^{3/2}}{\delta_{\mrm{F}}}\rp+\frac{11}{2}\Bigg\}\cup\\\nonumber
    &\quad\quad\quad\Bigg\{\exists\,k,r\in\mathbb{N}:r\mrm{kl}(\hat{\mu}_{k+1:k+r},\mu_{0})>3\log(1+\log(k+r))+\frac{5}{4}\log\lp\frac{4\lp k+r\rp^{3/2}}{\delta_{\mrm{F}}}\rp+\frac{11}{2}\Bigg\}\Bigg)\\\nonumber
    &\overset{(d)}{\leq}\Pr_{\infty}\bigg(\left\{\exists\,k\in\mathbb{N}:k\mrm{kl}(\hat{\mu}_{1:k},\mu_{0})>3\log(1+\log(k))+\frac{5}{4}\log\lp\frac{4}{\delta_{\mrm{F}}}\rp+\frac{11}{2}\right\}\cup\\\nonumber
    &\quad\quad\quad\;\bigg\{\exists\,k,r\in\mathbb{N}:r\mrm{kl}(\hat{\mu}_{k+1:k+r},\mu_{0})>3\log(1+\log(r))+\frac{5}{4}\log\lp\frac{4k^{3/2}}{\delta_{\mrm{F}}}\rp+\frac{11}{2}\bigg\}\bigg) \\\nonumber
    &\overset{(e)}{\leq}\Pr_{\infty}\left(\exists\,k\in\mathbb{N}:k\mrm{kl}(\hat{\mu}_{1:k},\mu_{0})>3\log(1+\log(k))+\frac{5}{4}\log\lp\frac{4}{\delta_{\mrm{F}}}\rp+\frac{11}{2}\right)+\\\nonumber
    &\quad\;\Pr_{\infty}\left(\exists\,k,r\in\mathbb{N}:r\mrm{kl}(\hat{\mu}_{k+1:k+r},\mu_{0})>3\log(1+\log(r))+\frac{5}{4}\log\lp\frac{4k^{3/2}}{\delta_{\mrm{F}}}\rp+\frac{11}{2}\right)\\\nonumber
    &=\Pr_{\infty}\left(\exists\,k\in\mathbb{N}:k\mrm{kl}(\hat{\mu}_{1:k},\mu_{0})-3\log(1+\log(k))>\frac{5}{4}\log\lp\frac{4}{\delta_{\mrm{F}}}\rp+\frac{11}{2}\right)+\\\nonumber
    &\quad\;\Pr_{\infty}\bigg(\bigcup_{k=1}^{\infty}\bigg\{\exists\,r\in\mbb{N}:r\mrm{kl}(\hat{\mu}_{k+1:k+r},\mu_{0})-3\log(1+\log(r))>\frac{5}{4}\log\lp\frac{4k^{3/2}}{\delta_{\mrm{F}}}\rp + \frac{11}{2}\bigg\}\bigg)\\\nonumber
    &\overset{(f)}{\leq}\Pr_{\infty}\left(\exists\,k\in\mathbb{N}:k\mrm{kl}(\hat{\mu}_{1:k},\mu_{0})-3\log(1+\log(k))>\frac{5}{4}\log\lp\frac{4}{\delta_{\mrm{F}}}\rp+\frac{11}{2}\right)+\\\nonumber
    &\quad\;\sum_{k=1}^{\infty}\Pr_{\infty}\bigg(\exists\,r\in\mbb{N}:r\mrm{kl}(\hat{\mu}_{k+1:k+r},\mu_{0})-3\log(1+\log(r))>\frac{5}{4}\log\lp\frac{4k^{3/2}}{\delta_{\mrm{F}}}\rp+\frac{11}{2}\bigg)\\\nonumber
    &\overset{(g)}{\leq}\frac{\delta_{\mrm{F}}}{4}+\sum_{k=1}^{\infty}\frac{\delta_{\mrm{F}}}{4k^{3/2}}\\
    &\leq\delta_{\mrm{F}}\label{eq:Prop_2_proof}
\end{align}
%
where step $(a)$ is due to Lemma \ref{lem:GLR-kl-unknown-pre-post} and step $(b)$ is owing to the fact that $\inf_{\mu} k \lp \hat{\mu}_{1:k} - \mu \rp^{2} + \lp n - k \rp \lp \hat{\mu}_{k + 1 : n} - \mu \rp^{2} = k \lp \hat{\mu}_{1:k} - \hat{\mu}_{1:n} \rp^{2} + \lp n - k \rp \lp \hat{\mu}_{k + 1 : n} - \hat{\mu}_{1:n} \rp^{2}$. Step $(c)$ is due to the fact that $x+y>2a$ implies $x>a$ or $y>a$. Step $(d)$ stems from the fact that $\beta\lp n,\delta\rp$ is increasing with $n$. Steps $(e)$ and $(f)$ are owing to the union bound. By Lemma \ref{lem:mix_martin}, we obtain step $(g)$. This completes the proof of the false alarm constraint in Theorem \ref{thm:pre-post-unknown}.

We now move on to proving the detection delay performance $\Pr_{\nu} \lp \tilde{\tau}_{\mrm{GLR}} \geq \nu + d \rp$ in Theorem \ref{thm:pre-post-unknown}. To this end, we use the following lemma borrowed from \cite{besson2022efficient} as our concentration inequality:

\begin{lemma}[Lemma 10 in \cite{besson2022efficient}] \label{lem:sub_Gaussian_diff}
    Let $\hat{\mu}_{i,s}$ be the empirical mean of $s$ i.i.d. $\sigma^{2}$-sub-Gaussian samples with mean $\mu_{i}$, $i\in\lbp0,1\rbp$. Then, $\forall\,s,r\in\mbb{N}$, we have

    \begin{equation}
        \Pr\lp\frac{sr}{s+r}\lp\lp\hat{\mu}_{0,s}-\hat{\mu}_{1,r}\rp-\lp\mu_{0}-\mu_{1}\rp\rp^{2}>u\rp\leq2\exp\lp-\frac{u}{2\sigma^{2}}\rp.
    \end{equation}
\end{lemma}

Continuing with the proof of the latency, for convenience in notation,  using Lemma \ref{lem:GLR-kl-unknown-pre-post}, we can show that for any $T\in\mbb{N},\;\delta_{\mrm{D}},\delta_{\mrm{F}}\in\lp0,1\rp,\;\Delta>0$, $m>\frac{8\sigma^{2}}{\Delta^{2}}\tilde{\beta}_{\mrm{GLR}}\lp T,\delta_{\mrm{F}}\rp$, and $\nu\in\lbp m+1,\dots,T-d\rbp$, we have
%
\begin{align}\nonumber
    &\Pr_{\nu}\lp \tilde{\tau}_{\mrm{GLR}}\geq\nu+d\rp\\\nonumber
    &=\Pr_{\nu}\bigg(\forall\,n\in\lbp1,\dots,\nu+d-1\rbp:\;\sup_{1\leq k\leq n}\log\lp\frac{\sup_{\mu_{0}'\in\mbb{R}}\prod_{i=1}^{k}f_{\mu_{0}'}\lp X_{i}\rp\sup_{\mu_{1}'\in\mbb{R}}\prod_{i=k+1}^{n}f_{\mu_{1}'}\lp X_{i}\rp}{\sup_{\mu\in\mbb{R}}\prod_{i=1}^{n}f_{\mu}\lp X_{i}\rp}\rp\\\nonumber
    &\quad\quad\quad<\tilde{\beta}_{\mrm{GLR}}\lp n,\delta_{\mrm{F}}\rp\bigg)\\\nonumber
    &\overset{(a)}{=}\Pr_{\nu}\lp\forall\,n\in\lbp1,\dots,\nu+d-1\rbp:\;\sup_{1\leq k\leq n}k\mrm{kl}\lp\hat{\mu}_{1:k},\hat{\mu}_{1:n}\rp+\lp n-k\rp\mrm{kl}\lp\hat{\mu}_{k+1:n},\hat{\mu}_{1:n}\rp<\tilde{\beta}_{\mrm{GLR}}\lp n,\delta_{\mrm{F}}\rp\rp\\\nonumber
    &\overset{(b)}{\leq}\Pr\bigg(\sup_{1\leq k\leq \nu+d-1} k\mrm{kl}\lp\hat{\mu}_{1:k},\hat{\mu}_{1:\nu+d-1}\rp+ \lp\nu+d-1-k\rp\mrm{kl}\lp\hat{\mu}_{k+1:\nu+d-1},\hat{\mu}_{1:\nu+d-1}\rp\\\nonumber
    &\quad\quad\quad<\tilde{\beta}_{\mrm{GLR}} \lp \nu+d-1,\delta_{\mrm{F}}\rp\bigg)\\\nonumber
    &\leq \Pr_{\nu}\lp\lp\nu-1\rp\mrm{kl}\lp\hat{\mu}_{1:\nu-1},\hat{\mu}_{1:\nu+d-1}\rp+d\mrm{kl}\lp\hat{\mu}_{\nu:\nu+d-1},\hat{\mu}_{1:\nu+d-1}\rp<\tilde{\beta}_{\mrm{GLR}}\lp\nu+d-1,\delta_{\mrm{F}}\rp\rp\\\nonumber
    &=\Pr_{\nu}\Bigg(\frac{\nu-1}{2\sigma^{2}}\lp\hat{\mu}_{1:\nu-1}-\frac{\lp\nu-1\rp\hat{\mu}_{1:\nu-1}+d\hat{\mu}_{\nu:\nu+d-1}}{\nu+d-1}\rp^{2}\\\nonumber
    &\quad\quad\quad+\frac{d}{2\sigma^{2}}\lp\hat{\mu}_{\nu:\nu+d-1}-\frac{\lp\nu-1\rp\hat{\mu}_{1:\nu-1}+d\hat{\mu}_{\nu:\nu+d-1}}{\nu+d-1}\rp^{2}<\tilde{\beta}_{\mrm{GLR}}\lp\nu+d-1,\delta_{\mrm{F}}\rp\Bigg)\\
    &=\Pr_{\nu}\lp\frac{\lp\nu-1\rp d}{2\sigma^{2}\lp\nu+d-1\rp}\lp\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rp^{2}<\tilde{\beta}_{\mrm{GLR}}\lp\nu+d-1,\delta_{\mrm{F}}\rp\rp\label{eq:glr-ld-1}
\end{align}
%
where step $(a)$ comes from Lemma \ref{lem:GLR-kl-unknown-pre-post} and step $(b)$ results from $\lbp\nu+d-1\rbp\subseteq\lbp1,\dots,\nu+d-1\rbp$. 

Recall that $\mu_{0}$ and $\mu_{1}$ are the pre- and post-change means, and that the definition of $d$ is given in \eqref{eq:d}. For applying Lemma \ref{lem:sub_Gaussian_diff}, we need to convert $\lp\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rp^{2}$ in the last line of \eqref{eq:glr-ld-1} into $\lp\lp\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rp-\lp\mu_{0}-\mu_{1}\rp\rp^{2}$. To this end, we show that for any $\nu\in\lbp m+1,\dots,T-d\rbp$,   $\lbp\frac{\lp\nu-1\rp d}{2\sigma^{2}\lp\nu+d-1\rp}\lp\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rp^{2}<\tilde{\beta}_{\mrm{GLR}}\lp\nu+d-1,\delta_{\mrm{F}}\rp\rbp$ implies  $\lbp\frac{\lp\nu-1\rp d}{2\sigma^{2}\lp\nu+d-1\rp}\lp\lp\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rp-\lp\mu_{0}-\mu_{1}\rp\rp^{2}\geq\tilde{\beta}_{\mrm{GLR}}\lp\nu+d-1,\delta_{\mrm{F}}\rp\rbp$ with the choice of $m$ in \eqref{eq:m} and $d$ in \eqref{eq:d}. Let $\beta = \tilde{\beta}_{\mrm{GLR}}$ for notational convenience. We can show this implication as follows:
%
\begin{align}\nonumber
    &\lbp\frac{\lp\nu-1\rp d}{2\sigma^{2}\lp\nu+d-1\rp}\lp\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rp^{2}<\beta\lp\nu+d-1,\delta_{\mrm{F}}\rp\rbp\\\nonumber
    &\quad\cap\lbp\frac{\lp\nu-1\rp d}{2\sigma^{2}\lp\nu+d-1\rp}\lp\lp\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rp-\lp\mu_{0}-\mu_{1}\rp\rp^{2}<\beta\lp\nu+d-1,\delta_{\mrm{F}}\rp\rbp\\\nonumber
    &=\lbp\lba\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rba<\lp\frac{2\sigma^{2}\lp\nu+d-1\rp}{\lp\nu-1\rp d}\beta\lp\nu+d-1,\delta_{\mrm{F}}\rp\rp^{\frac{1}{2}}\rbp\\\nonumber
    &\quad\cap\lbp\lba\lp\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rp-\lp\mu_{0}-\mu_{1}\rp\rba<\lp\frac{2\sigma^{2}\lp\nu+d-1\rp}{\lp\nu-1\rp d}\beta\lp\nu+d-1,\delta_{\mrm{F}}\rp\rp^{\frac{1}{2}}\rbp\\\nonumber
    &\overset{(a)}{\subseteq}\lbp\lba\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rba<\lp\frac{2\sigma^{2}\lp\nu+d-1\rp}{\lp\nu-1\rp d}\beta\lp\nu+d-1,\delta_{\mrm{F}}\rp\rp^{\frac{1}{2}}\rbp\\\nonumber
    &\quad\cap\lbp\lba\mu_{0}-\mu_{1}\rba-\lba\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rba<\lp\frac{2\sigma^{2}\lp\nu+d-1\rp}{\lp\nu-1\rp d}\beta\lp\nu+d-1,\delta_{\mrm{F}}\rp\rp^{\frac{1}{2}}\rbp\\\nonumber
    &=\lbp\lba\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rba<\lp\frac{2\sigma^{2}\lp\nu+d-1\rp}{\lp\nu-1\rp d}\beta\lp\nu+d-1,\delta_{\mrm{F}}\rp\rp^{\frac{1}{2}}\rbp\\\nonumber
    &\quad\cap\lbp\lba\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rba>\Delta-\lp\frac{2\sigma^{2}\lp\nu+d-1\rp}{\lp\nu-1\rp d}\beta\lp\nu+d-1,\delta_{\mrm{F}}\rp\rp^{\frac{1}{2}}\rbp\\\nonumber
    &\subseteq\lbp\Delta<2\lp\frac{2\sigma^{2}\lp\nu+d-1\rp}{\lp\nu-1\rp d}\beta\lp\nu+d-1,\delta_{\mrm{F}}\rp\rp^{\frac{1}{2}}\rbp\\\nonumber
    &=\lbp\Delta^{2}<8\sigma^{2}\lp\frac{1}{\nu-1}+\frac{1}{d}\rp\beta\lp\nu+d-1,\delta_{\mrm{F}}\rp\rbp\\\nonumber
    &\overset{(b)}{\subseteq}\lbp\Delta^{2}<8\sigma^{2}\lp\frac{1}{m}+\frac{1}{d}\rp\beta\lp T,\delta_{\mrm{F}}\rp\rbp\\\nonumber
    &=\lbp\lp\frac{\Delta^{2}}{8\sigma^{2}\beta\lp T,\delta_{\mrm{F}}\rp}-\frac{1}{m}\rp^{-1}>d\rbp\\\nonumber
    &=\lbp \frac{8\sigma^{2}m\beta\lp T,\delta_{\mrm{F}}\rp}{\Delta^{2}m-8\sigma^{2}\beta\lp T,\delta_{\mrm{F}}\rp}>\lce\max\lbp\frac{8\sigma^{2}m\beta\lp T,\delta_{\mrm{F}}\rp}{\Delta^{2}m-8\sigma^{2}\beta\lp T,\delta_{\mrm{F}}\rp},\frac{\delta_{\mrm{F}}^{2/3}}{2^{16/15}\delta_{\mrm{D}}^{4/15}}-m\rbp\rce\rbp\\
    &=\emptyset\label{eq:implication_delay}
\end{align}
%
where step $(a)$ is due to triangle inequality and step $(b)$ is due to the fact that $\nu\geq m+1$ and $\nu\leq T-d$. Hence, the late detection probability can be bounded using Lemma \ref{lem:sub_Gaussian_diff} and we obtain that for any $\nu\in\lbp m+1,\dots,T-d\rbp$
%
\begin{align}\nonumber
    &\Pr_{\nu}\lp\tilde{\tau}_{\mrm{GLR}}\geq\nu+d\rp\\\nonumber
    &\leq\Pr_{\nu}\lp\frac{\lp\nu-1\rp d}{2\sigma^{2}\lp\nu+d-1\rp}\lp\lp\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rp-\lp\mu_{0}-\mu_{1}\rp\rp^{2}\geq\tilde{\beta}_{\mrm{GLR}}\lp\nu+d-1,\delta_{\mrm{F}}\rp\rp\\\nonumber
    &\overset{(a)}{\leq}\Pr_{\nu}\lp\frac{\lp\nu-1\rp d}{2\sigma^{2}\lp\nu+d-1\rp}\lp\lp\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rp-\lp\mu_{0}-\mu_{1}\rp\rp^{2}\geq\tilde{\beta}_{\mrm{GLR}}\lp m+d,\delta_{\mrm{F}}\rp\rp\\\nonumber
    &\overset{(b)}{\leq}\Pr_{\nu}\lp\frac{\lp\nu-1\rp d}{2\sigma^{2}\lp\nu+d-1\rp}\lp\lp\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rp-\lp\mu_{0}-\mu_{1}\rp\rp^{2}\geq\frac{5}{2}\log\lp\frac{4\lp m+d\rp^{3/2}}{\delta_{\mrm{F}}}\rp\rp\\\nonumber
    &=\Pr_{\nu}\lp\frac{\lp\nu-1\rp d}{\nu+d-1}\lp\lp\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rp-\lp\mu_{0}-\mu_{1}\rp\rp^{2}\geq2\sigma^{2}\log\lp\frac{32\lp m+d \rp^{15/4}}{\delta_{\mrm{F}}^{5/2}}\rp\rp\\\nonumber
    &\overset{(c)}{\leq}\frac{\delta_{\mrm{F}}^{5/2}}{16\lp m+d\rp^{15/4}}\\\nonumber
    &\leq\frac{\delta_{\mrm{F}}^{5/2}}{16\lp\delta_{\mrm{F}}^{5/2}2^{-16/15}\delta^{-4/15}_{\mrm{D}}\rp^{15/4}}\\
    &=\delta_{\mrm{D}}
\end{align}
%
where step $(a)$ is due to the fact that $\beta\lp n,\delta_{\mrm{F}}\rp$ is increasing with $n$, whereas step $(b)$ is owing to the fact that $\tilde{\beta}_{\mrm{GLR}} \lp n,\delta_{\mrm{F}}\rp\geq\frac{5}{2}\log\lp4n^{3/2}/\delta_{\mrm{F}}\rp$. Step $(c)$ comes from Lemma \ref{lem:sub_Gaussian_diff}.

Next, we prove the results for the GSR test: To prove the upper bound on false alarm probability, we use our results for the false alarm probability of the GLR test \eqref{eq:Prop_2_proof}. Similarly, the proof for the upper bound on the late detection probability $\Pr_{\nu} \lp \tilde{\tau}_{\mrm{GSR}} \geq \nu + d \rp$ uses the concentration inequality in Lemma \ref{lem:sub_Gaussian_diff}, and the steps are analogous to those used in the proof for $\Pr_{\nu} \lp \tilde{\tau}_{\mrm{GLR}} \geq \nu + d \rp \leq \delta_{\mrm{D}}$. 

We first prove $\Pr_{\infty}\lp\tilde{\tau}_{\mrm{GSR}} \leq T \rp$ using \eqref{eq:Prop_2_proof} as follows:
%
\begin{align}\nonumber
    &\Pr_{\infty}\lp\tilde{\tau}_{\mrm{GSR}} \leq T \rp\\\nonumber
    &=\Pr_{\infty}\lp\exists\,n\in\lbp 1, \dots, T \rbp:\;\log \tilde{W}_{n}\geq\tilde{\beta}_{\mrm{GLR}}\lp n,\delta_{\mrm{F}}\rp + \log n \rp\\\nonumber
    &=\Pr_{\infty}\Bigg(\exists\,n\in\lbp 1, \dots, T \rbp:\\\nonumber
    &\quad\quad\quad\;\sum_{k=1}^{n}\frac{\sup_{\mu_{0}'\in\mbb{R}}\prod_{i=1}^{k}f_{\mu_{0}'}\lp X_{i}\rp\sup_{\mu_{1}'\in\mbb{R}}\prod_{i=k+1}^{n}f_{\mu_{1}'}\lp X_{i}\rp}{\sup_{\mu\in\mbb{R}}\prod_{i=1}^{n}f_{\mu}\lp X_{i}\rp}\geq n\exp\lp\tilde{\beta}_{\mrm{GLR}}\lp n,\delta_{\mrm{F}}\rp\rp\Bigg)\\\nonumber
    &=\Pr_{\infty}\bigg(\exists\,n\in\lbp 1, \dots, T \rbp:\\\nonumber
    &\quad\quad\quad\;\frac{1}{n}\sum_{k=1}^{n}\frac{\sup_{\mu_{0}'\in\mbb{R}}\prod_{i=1}^{k}f_{\mu_{0}'}\lp X_{i}\rp\sup_{\mu_{1}'\in\mbb{R}}\prod_{i=k+1}^{n}f_{\mu_{1}'}\lp X_{i}\rp}{\sup_{\mu\in\mbb{R}}\prod_{i=1}^{n}f_{\mu}\lp X_{i}\rp}\geq\exp\lp\tilde{\beta}_{\mrm{GLR}}\lp n,\delta_{\mrm{F}}\rp\rp\bigg)\\\nonumber
    &\overset{(a)}{\leq}\Pr_{\infty}\bigg(\exists\,n\in\lbp 1, \dots, T \rbp:\\\nonumber
    &\quad\quad\quad\;\sup_{1\leq k\leq n}\frac{\sup_{\mu_{0}'\in\mbb{R}}\prod_{i=1}^{k}f_{\mu_{0}'}\lp X_{i}\rp\sup_{\mu_{1}'\in\mbb{R}}\prod_{i=k+1}^{n}f_{\mu_{1}'}\lp X_{i}\rp}{\sup_{\mu\in\mbb{R}}\prod_{i=1}^{n}f_{\mu}\lp X_{i}\rp}\geq\exp\lp\tilde{\beta}_{\mrm{GLR}}\lp n,\delta_{\mrm{F}}\rp\rp\bigg)\\\nonumber
    &=\Pr_{\infty}\bigg(\exists\,n\in\lbp 1, \dots, T \rbp:\\\nonumber
    &\quad\quad\quad\;\sup_{1\leq k\leq n}\log\lp\frac{\sup_{\mu_{0}'\in\mbb{R}}\prod_{i=1}^{k}f_{\mu_{0}'}\lp X_{i}\rp\sup_{\mu_{1}'\in\mbb{R}}\prod_{i=k+1}^{n}f_{\mu_{1}'}\lp X_{i}\rp}{\sup_{\mu\in\mbb{R}}\prod_{i=1}^{n}f_{\mu}\lp X_{i}\rp}\rp\geq\tilde{\beta}_{\mrm{GLR}}\lp n,\delta_{\mrm{F}}\rp\bigg)\\\nonumber
    &=\Pr_{\infty}\lp\exists\,n\in\lbp 1, \dots, T \rbp:\; \tilde{G}_{n}\geq\tilde{\beta}_{\mrm{GLR}}\lp n,\delta_{\mrm{F}}\rp\rp\\\nonumber
    &=\Pr_{\infty}\lp \tilde{\tau}_{\mrm{GLR}} \leq T \rp\\
    &\overset{(b)}{\leq}\delta_{\mrm{F}}\label{eq:gsr-fa-1}
\end{align}
%
where step $(a)$ results from the fact that $\sup_{1\leq i\leq n}x_{i}\leq a$ implies $\sum_{i=1}^{n}x_{i}\leq na$, whereas $(b)$ stems from \eqref{eq:Prop_2_proof}. 

Next, we prove the upper bound on the late detection probability $\Pr_{\nu}\lp\tilde{\tau}_{\mrm{GSR}}\geq\nu+d\rp$: For any $T\in\mbb{N},\;\,\delta_{\mrm{D}},\delta_{\mrm{F}}\in\lp0,1\rp,\;\Delta>0$, $m>\frac{8\sigma^{2}}{\Delta^{2}}\tilde{\beta}_{\mrm{GSR}}\lp T,\delta_{\mrm{F}}\rp$, and $\nu\in\lbp m+1,\dots,T-d\rbp$, we have
%
\begin{align}\nonumber
    &\Pr_{\nu}\lp\tilde{\tau}_{\mrm{GSR}}\geq\nu+d\rp\\\nonumber
    &=\Pr_{\nu}\lp\forall\,n<\nu+ d:\;\log \tilde{W}_{n}<\tilde{\beta}_{\mrm{GSR}}\lp n,\delta_{\mrm{F}}\rp \rp\\\nonumber
    &=\Pr_{\nu}\lp\forall\,n<\nu+ d:\;\log\lp\sum_{k=1}^{n}\frac{\sup_{\mu_{0}'\in\mbb{R}}\prod_{i=1}^{k}f_{\mu_{0}'}\lp X_{i}\rp\sup_{\mu_{1}'\in\mbb{R}}\prod_{i=k+1}^{n}f_{\mu_{1}'}\lp X_{i}\rp}{\sup_{\mu\in\mbb{R}}\prod_{i=1}^{n}f_{\mu}\lp X_{i}\rp}\rp<\tilde{\beta}_{\mrm{GSR}}\lp n,\delta_{\mrm{F}}\rp\rp\\\nonumber
    &\overset{(a)}{=}\Pr_{\nu}\Bigg(\forall\,n\in\lbp1,\dots,\nu+ d-1\rbp:\;\log\lp\sum_{k=1}^{n}\exp\lp k\mrm{kl}\lp\hat{\mu}_{1:k},\hat{\mu}_{1:n}\rp+\lp n-k\rp\mrm{kl}\lp\hat{\mu}_{k+1:n},\hat{\mu}_{1:n}\rp\rp\rp\\\nonumber
    &\quad\quad\quad<\tilde{\beta}_{\mrm{GSR}}\lp n,\delta_{\mrm{F}}\rp\Bigg)\\\nonumber
    &\overset{(b)}{\leq}\Pr_{\nu}\Bigg(\log\lp\sum_{k=1}^{\nu+ d - 1} \exp\lp k\mrm{kl}\lp\hat{\mu}_{1:k},\hat{\mu}_{1: \nu + d - 1} \rp + \lp \nu + d - 1 - k\rp\mrm{kl}\lp\hat{\mu}_{k+1:\nu+ d-1},\hat{\mu}_{1:\nu+ d-1}\rp\rp\rp \\\nonumber
    &\quad\quad\quad<\tilde{\beta}_{\mrm{GSR}}\lp \nu + d - 1, \delta_{\mrm{F}}\rp\Bigg)\\\nonumber
    &\leq\Pr_{\nu}\lp\lp\nu-1\rp\mrm{kl}\lp\hat{\mu}_{1:\nu-1},\hat{\mu}_{1:\nu+ d-1}\rp+ d\mrm{kl}\lp\hat{\mu}_{\nu:\nu+ d-1},\hat{\mu}_{1:\nu+ d-1}\rp<\tilde{\beta}_{\mrm{GSR}}\lp\nu+ d-1,\delta_{\mrm{F}}\rp\rp\\\nonumber
    &=\Pr_{\nu}\Bigg(\frac{\nu-1}{2\sigma^{2}}\lp\hat{\mu}_{1:\nu-1}-\frac{\lp\nu-1\rp\hat{\mu}_{1:\nu-1}+ d\hat{\mu}_{\nu:\nu+ d-1}}{\nu+ d-1}\rp^{2}\\\nonumber
    &\quad\quad\quad+\frac{ d}{2\sigma^{2}}\lp\hat{\mu}_{\nu:\nu+ d-1}-\frac{\lp\nu-1\rp\hat{\mu}_{1:\nu-1}+ d\hat{\mu}_{\nu:\nu+ d-1}}{\nu+ d-1}\rp^{2}<\tilde{\beta}_{\mrm{GSR}}\lp\nu+ d-1,\delta_{\mrm{F}}\rp\Bigg)\\
    &=\Pr_{\nu}\lp\frac{\lp\nu-1\rp d}{2\sigma^{2}\lp\nu+ d-1\rp}\lp\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+ d-1}\rp^{2}<\tilde{\beta}_{\mrm{GSR}}\lp\nu+ d-1,\delta_{\mrm{F}}\rp\rp\label{eq:gsr-ld-1}
\end{align}
%
where step $(a)$ stems from Lemma \ref{lem:GLR-kl-unknown-pre-post} and step $(b)$ results from $\lbp\nu+ d-1\rbp\subseteq\lbp1,\dots,\nu+ d-1\rbp$.  Recall that $\mu_{0}$ and $\mu_{1}$ are the pre- and post-change means, and that the definition of $d$ is given in \eqref{eq:d}. In order to apply Lemma \ref{lem:sub_Gaussian_diff}, we need to convert $\lp\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rp^{2}$ in the last line of \eqref{eq:gsr-ld-1} into $\lp\lp\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rp-\lp\mu_{0}-\mu_{1}\rp\rp^{2}$. Following the same steps in \eqref{eq:implication_delay} with $\beta = \tilde{\beta}_{\mrm{GSR}}$, we can show that the event $\lbp\frac{\lp\nu-1\rp d}{2\sigma^{2}\lp\nu+d-1\rp}\lp\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rp^{2}<\tilde{\beta}_{\mrm{GSR}}\lp \nu+d-1,\delta_{\mrm{F}}\rp\rbp$ implies the event $\lbp\frac{\lp\nu-1\rp d}{2\sigma^{2}\lp\nu+d-1\rp}\lp\lp\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rp-\lp\mu_{0}-\mu_{1}\rp\rp^{2}\geq\tilde{\beta}_{\mrm{GSR}}\lp \nu+d-1,\delta_{\mrm{F}}\rp\rbp$ for any $\nu\in\lbp m+1,\dots,T-d\rbp$ with the choices of $m$ and $d$ in \eqref{eq:m} and \eqref{eq:d}, respectively. 
Then, for any $\nu\in\lbp m+1,\dots,T-d\rbp$,
%
\begin{align}\nonumber
    &\Pr_{\nu}\lp\tilde{\tau}_{\mrm{GSR}}\geq\nu+d\rp\\\nonumber
    &\leq\Pr_{\nu}\lp\frac{\lp\nu-1\rp d}{2\sigma^{2}\lp\nu+d-1\rp}\lp\lp\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rp-\lp\mu_{0}-\mu_{1}\rp\rp^{2}\geq\tilde{\beta}_{\mrm{GSR}}\lp\nu+d-1,\delta_{\mrm{F}}\rp\rp\\\nonumber
    &\overset{(a)}{\leq}\Pr_{\nu}\lp\frac{\lp\nu-1\rp d}{2\sigma^{2}\lp\nu+d-1\rp}\lp\lp\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rp-\lp\mu_{0}-\mu_{1}\rp\rp^{2}\geq\tilde{\beta}_{\mrm{GSR}}\lp m+d,\delta_{\mrm{F}}\rp\rp\\\nonumber
    &\overset{(b)}{\leq}\Pr_{\nu}\lp\frac{\lp\nu-1\rp d}{2\sigma^{2}\lp\nu+d-1\rp}\lp\lp\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rp-\lp\mu_{0}-\mu_{1}\rp\rp^{2}\geq\frac{5}{2}\log\lp\frac{4\lp m+d\rp^{3/2}}{\delta_{\mrm{F}}}\rp\rp\\\nonumber
    &=\Pr_{\nu}\lp\frac{\lp\nu-1\rp d}{\nu+d-1}\lp\lp\hat{\mu}_{1:\nu-1}-\hat{\mu}_{\nu:\nu+d-1}\rp-\lp\mu_{0}-\mu_{1}\rp\rp^{2}\geq2\sigma^{2}\log\lp\frac{2^{5}\lp m+d \rp^{15/4}}{\delta_{\mrm{F}}^{5/2}}\rp\rp\\\nonumber
    &\overset{(c)}{\leq}\frac{\delta_{\mrm{F}}^{5/2}}{16\lp m+d\rp^{15/4}}\\\nonumber
    &\leq\frac{\delta_{\mrm{F}}^{5/2}}{16\lp\delta_{\mrm{F}}^{5/2}2^{-16/15}\delta^{-4/15}_{\mrm{D}}\rp^{15/4}}\\
    &=\delta_{\mrm{D}}
\end{align}
%
where step $(a)$ is due to the fact that $\tilde{\beta}_{\mrm{GSR}}\lp n,\delta_{\mrm{F}}\rp$ is increasing with $n$, whereas step $(b)$ is owing to the fact that $\tilde{\beta}_{\mrm{GSR}}\lp n,\delta_{\mrm{F}}\rp\geq\frac{5}{2}\log\lp4n^{3/2}/\delta_{\mrm{F}}\rp$. Step $(c)$ comes from Lemma \ref{lem:sub_Gaussian_diff}. 

