\begin{corollary}\label{Cor: The other higher powers of T to thetaf in one line}
Let $f:X \to Y$ be a $p$-carrable morphism. Then for all $m \in \N$ there are isomorphisms $C$ and $\tilde{C}$ for which
\[
\tilde{C}_m \circ T^m\theta_f \circ C_m = \theta_{T^{m}f}.
\]
%\bigjs{You might have to double check your indices, I think this should be $m$ on both sides and not $m$ and $m+1$. For example see Prop \ref{Proposition: Tangent of thetaf}}
\end{corollary}
\begin{proof}
Observe that for all $k, \ell \in \N$, applying Corollary \ref{Cor: The combinatorial swicheroo fo rhigher power s of T on thetaf} and using the fact that $c_{T^kX} = (c \ast T^k)_X$ is an involution gives
\begin{align*}
T^{\ell}(\theta_{T^{k+1}f}) &= T^{\ell}\left(\tilde{c}_k \circ T\theta_{T^{k}f} \circ (c \ast T^k)_X\right) = T^{\ell}(\tilde{c}_k) \circ T^{\ell+1}(\theta_{T^{k}f}) \circ T^{\ell}(c \ast T^k)_X \\
&= T^{\ell}(\tilde{c}_k) \circ T^{\ell+1}(\theta_{T^kf}) \circ (T^{\ell} \ast c \ast T^k)_X.
\end{align*}
Consequently, for any $0 \leq k \leq m$,
\[
T^k(\theta_{T^{m+1-k}f}) = T^k\tilde{c}_{m-k} \circ T^{k+1}(\theta_{T^{m-k}f}) \circ (T^k \ast c \ast T^{m-k})_X.
\]
Proceeding recursively in $m$ and terminating when $m = 0$ allows us to deduce that
\begin{align*}
\theta_{T^{m}f} &= \tilde{c}_m \circ T\theta_{T^mf} \circ (c \ast T^m)_X = \tilde{c}_m \circ T\tilde{c}_{m-1} \circ T^2\theta_{T^{m-1}f} \circ (T \ast c \ast T^{m-1})_X \circ (c \ast T^m)_X = \\
&= \tilde{c}_m \circ T\tilde{c}_{m-1} \circ \cdots T^m\tilde{c}_0 \circ T^{m}\theta_f \circ (T^m \ast c)_X \circ (T^{m-1} \ast c \ast T)_X \circ \cdots \circ (c \ast T^m)_X.
\end{align*}
Setting $\tilde{C} := \tilde{c}_m \circ \cdots \circ T^m\tilde{c}_0$ and $C := (T^m \ast c)_X \circ \cdots \circ (c \ast T^m)_X$ thus gives that
\[
\theta_{T^{m}f} = \tilde{C} \circ T^{m}\theta_f \circ C
\]
as desired. 
\end{proof}

We now study how the horizontal descents interact with pullbacks. In particular, given a $p$-carrable morphism $f:X \to Z$ and a map $g:Y \to Z$ which admits a pullback
\[
\begin{tikzcd}
X \times_Z Y \ar[r]{}{\pr_1} \ar[d, swap]{}{\pr_0} & Y \ar[d]{}{g} \\
X \ar[r, swap]{}{f} & Z
\end{tikzcd}
\]
which is preserved by the tangent functor $T$, if the map $\pr_1:X \times_Z Y \to Y$ is also $p$-carrable then we will study how we can write $\theta_{\pr_1}:T(X \times_Z Y) \to \pr_1^{\ast}(TY)$ in terms of $\theta_f:TX \to f^{\ast}(TX)$.

\begin{proposition}\label{Prop: How thetaf pulls back}
Let $f:X \to Z$ be a $p$-carrable morphism and $g: Y \to Z$, for which the pullback 
\[
\begin{tikzcd}
X \times_Z Y \ar[r]{}{\pr_1} \ar[d, swap]{}{\pr_0} & Y \ar[d]{}{g} \\
X \ar[r, swap]{}{f} & Z
\end{tikzcd}
\]
exists and is preserved by the tangent functor $T$. If $\pr_1$ is $p$-carrable, then there is a morphism $\hat{\pi}:\pr_1^{\ast}(TY) \to f^{\ast}(TZ)$ which makes
\[
\begin{tikzcd}
\pr_1^{\ast}(TY) \ar[r]{}{\pi_1} \ar[d, swap]{}{\hat{\pi}} & TY \ar[d]{}{Tg} \\
f^{\ast}(TZ) \ar[r,swap]{}{\pr_1} & TZ
\end{tikzcd}
\]
into a pullback square and the following equality holds:
\[
\theta_{\pr_1} = \rho \circ (\theta_f \times \id_{TY}) \circ \varphi.
\]
where $\rho:f^{\ast}(TZ) \times_{TZ} TY \to \pr_1^{\ast}(TZ)$ and $\varphi:T(X \times_Y Z) \to TX \times_{TY} TZ$ are the unique induced isomorphisms. 
\end{proposition}
\begin{proof}
The final statement of the proposition is completely formal, so it suffices to first construct the morphism $\hat{\pi}:\pr_1^{\ast}(TY) \to f^{\ast}(TZ)$ and then prove that the square 
\[
\begin{tikzcd}
\pr_1^{\ast}(TY) \ar[r]{}{\pi_1} \ar[d, swap]{}{\hat{\pi}} & TY \ar[d]{}{Tg} \\
f^{\ast}(TZ) \ar[r,swap]{}{\pr_1} & TZ
\end{tikzcd}
\]
is a pullback. To construct $\hat{\pi}$, we note first that the diagram
\[
\begin{tikzcd}
\pr_1^{\ast}(TY) \ar[d, swap]{}{\pr_0} \ar[r]{}{\pr_1} & TY \ar[d]{}{Tg} \\
X \times_Z Y \ar[d, swap]{}{\pr_0} & TZ \ar[d]{}{p_Z} \\
X \ar[r, swap]{}{f} & Z
\end{tikzcd}
\]
commutes, making $(\pr_1^{\ast}(TY), \pr_0\circ \pr_0, Tg \circ \pr_1)$ into a cone over $X \xrightarrow{f} Z \xleftarrow{p} TZ$. As such, we define $\hat{\pi}:\pr_1^{\ast}(TY) \to f^{\ast}(TZ)$ as the induced unique cone map, that is $\hat{\pi} = \langle \pr_0 \circ \pr_0, Tg \circ \pr_1\rangle$. Now assume that we have a commuting diagram:
\[
\begin{tikzcd}
W \ar[r]{}{\alpha} \ar[d, swap]{}{\beta} & TY \ar[d]{}{Tg} \\
f^{\ast}(TZ) \ar[r, swap]{}{\pr_1} & TZ
\end{tikzcd}
\]
Since 
\[
f \circ \pr_0 \circ \beta = p_Z \circ \pr_1 \circ \beta = p_Z \circ Tg \circ \alpha = g \circ p_Y \circ \alpha
\]
we get a unique morphism $\gamma:W \to X \times_Z Y$ making the diagram
\[
\begin{tikzcd}
W \ar[drr, bend left = 20]{}{p_Y \circ \alpha} \ar[ddr, swap, bend right = 20]{}{\pr_0 \circ \beta} \ar[dr, dashed]{}{\exists!\,\gamma} \\
 & X \times_Z Y \ar[r]{}{\pr_1} \ar[d, swap]{}{\pr_0} & Y \ar[d]{}{g} \\
 & X \ar[r, swap]{}{f} & Z
\end{tikzcd}
\]
commute. But then since
\[
\begin{tikzcd}
W \ar[r]{}{\alpha} \ar[d, swap]{}{\gamma} & TY \ar[d]{}{p_Y} \\
X \times_Z Y \ar[r, swap]{}{\pr_1} & Y
\end{tikzcd}
\]
commutes, we get a unique morphism $\delta$ making the diagram
\[
\begin{tikzcd}
W \ar[drr, bend left = 20]{}{\alpha} \ar[ddr, swap, bend right = 20]{}{\gamma} \ar[dr]{}{\delta} \\
 &\pr_1^{\ast}(TY) \ar[r]{}{\pr_1} \ar[d, swap]{}{\pr_0} & TY \ar[d]{}{p_Y} \\
 & X \times_Z Y \ar[r, swap]{}{\pr_1} & Z
\end{tikzcd}
\]
commute. We now show that $\delta$ makes the following diagram commute:
\[
\begin{tikzcd}
W \ar[drr, bend left = 20]{}{\alpha} \ar[ddr, swap, bend right = 20]{}{\beta} \ar[dr, dashed]{}{\exists!\,\delta} \\
 &\pr_1^{\ast}(TY) \ar[r]{}{\pr_1} \ar[d, swap]{}{\pr_0} & TY \ar[d]{}{Tg} \\
 & f^{\ast}(TZ) \ar[r, swap]{}{\pr_1} & TZ
\end{tikzcd}
\]
Since we already know that $\alpha = \pr_1 \circ \delta$, it suffices to prove the identity regarding $\beta$. Then we compute that
\begin{align*}
\hat{\pi} \circ \delta =\left\langle \pr_0\circ \pr_0, Tg \circ \pr_1 \right\rangle \circ \delta = \left\langle \pr_0 \circ \pr_0 \circ \delta, Tg \circ \pr_1 \circ \delta\right\rangle = \left\langle \pr_0 \circ \gamma, Tg \circ \alpha \right\rangle = \langle \pr_0 \circ \beta, \pr_1 \circ \beta\rangle = \beta.
\end{align*}
Thus the diagram commutes. It is also routine to check that $\delta$ is the unique such cone map, as it was constructed stage-by-stage from other unique cone morphisms. Thus the diagram
\[
\begin{tikzcd}
\pr_1^{\ast}(TY) \ar[r]{}{\pi_1} \ar[d, swap]{}{\hat{\pi}} & TY \ar[d]{}{Tg} \\
f^{\ast}(TZ) \ar[r,swap]{}{\pr_1} & TZ
\end{tikzcd}
\]
is a pullback and hence completes the proof of the proposition.
\end{proof}

\section{The Relative Cotangent Sequence}

One of the most important conceptual and technical tools in both differential geometry and algebraic geometry is the relative cotangent sequence. In algebraic geometry, for a morphism $f:X \to Y$ of schemes there is an exact sequence
\[
\begin{tikzcd}
f^{\ast}\Kah{Y}{S} \ar[r] & \Kah{X}{S} \ar[r] & \Kah{X}{Y} \ar[r] & 0
\end{tikzcd}
\]
of quasi-coherent sheaves on $X$. One important application of this sequence is that it can be used to probe for when $f$ is formally unramified (this occurs if and only if $\Kah{X}{Y} \cong 0$). On the other hand, by passing through the opposite equivalence $\DBun(X) \simeq \QCoh(X)^{\op}$, we find that the relative cotangent sequence reflects to give a sequence of differential bundles
\[
\begin{tikzcd}
X \ar[r] & \underline{\Spec}_X\left(\underline{\Sym}_{\Ocal_X}\left(\Kah{X}{Y}\right)\right) \ar[r] & T_{X/S} \ar[r]{}{\theta_f} & X \times_Y T_{Y/S} \ar[equals, r] & f^{\ast}T_{Y/S}
\end{tikzcd}
\]
where the map to the last bundle $T_{Y/S} \times_X Y$ follows from the following chain of isomorphisms
\[
\underline{\Spec}_X\left(\underline{\Sym}_{\Ocal_X}\left(f^{\ast}\Kah{Y}{S}\right)\right) \cong \underline{\Spec}_{X}\left(f^{\ast}\underline{\Sym}_{\Ocal_Y}\left(\Kah{Y}{S}\right)\right) \cong X \times_Y \underline{\Spec}_{Y}\left(\underline{\Sym}_{\Ocal_Y}\left(\Kah{Y}{S}\right)\right) = f^{\ast}(T_{Y/S}).
\]
In differential geometry, for any map $f:X \to Y$ of smooth manifolds, we can always study the sub-bundle $T_{X/Y}$ of $TX$ defined as $T_{X/Y} := \left\lbrace \left(x, \overrightarrow{v}\right) \in TX \; : \; D[f](x) \cdot \overrightarrow{v} = \overrightarrow{0}\right\rbrace$. This ``vertical bundle'' not only gives a relative tangent bundle of $X$ over $Y$ as an object of $\SMan_{/Y}$, but it also provides an exact sequence
\[
\begin{tikzcd}
X \ar[r] & T_{X/Y} \ar[r] & TX \ar[r]{}{\theta_f} & f^{\ast}(TY)
\end{tikzcd}
\]
in the Abelian category $\mathbf{Vec}(X) \simeq \DBun(X).$

In both the algebraic geometry and differential geometry settings, we see that once we are able to produce a ``relative tangent bundle'' $T_{X/Y}$ (this is the bundle $\underline{\Spec}_X(\underline{\Sym}_{\Ocal_X}(\Kah{X}{Y}))$ in the algebraic-geometric setting) we are able to produce a sequence which shows that this bundle $T_{X/Y}$ acts as a kernel to the horizontal descent $\theta_f:TX \to f^{\ast}(TY)$. In this section we prove that this is no accident and show that this hold in a general tangent category. Indeed, we will show that provided a map $f:X \to Y$ is both $p$-carrable \emph{and} $0$-carrable (Definition \ref{Defn: Zero Carrable}), then not only does the bundle $T_{X/Y}$ exist, but it \emph{also} is a kernel to $\theta_f$ in the sense that $T_{X/Y}$ is the limit of the following cospan in $\DBun(X)$:
\[
TX \xrightarrow{\theta_f} f^{\ast}(TY) \xleftarrow{\gnab_{f^{\ast}TY}} X
\]

We also show that this structure provides the framework for defining morphisms we call $T$-unramified, which are the tangent-categorical analogue of a map $f:X \to Y$ whose tangent $Tf$ has trivial kernel, i.e., no tangent vectors ``ramify'' through $Tf$ by mapping both to zero. While we are primarily focused on the general theory of such maps in this section, they become especially important in Section \ref{Section: TImmersions} when we introduce the tangent-categorical extension of immersions: $T$-immersions. There we will prove that in a Rosick{\'y} tangent category, a map $f$ is $T$-unramified if and only if it is a $T$-immersion (Theorem \ref{Thm: Rosckiy Timmersion iff Tunramified}). 

\subsection{Zero Carrable Morphisms}
In this section we examine the morphisms $f:X \to Y$ for which there is a pullback
\[
\begin{tikzcd}
T_{X/Y} \ar[r]{}{\pr_1} \ar[d, swap]{}{\pr_0} & Y \ar[d]{}{0_Y} \\
TX \ar[r, swap]{}{Tf} & TY
\end{tikzcd}
\]
which is preserved by all powers of $T$. These morphisms are intimately related to formally unramified morphisms in algebraic geometry and to the vertical bundle of the tangent bundle in differential geometry. They also allow us to produce a new tangent functor on the slice category $\Cscr_{/X}$ which is \emph{not} necessarily isomorphic to tangent functor on $\Cscr$ ``restricted'' to the slice category $\Cscr_{/X}$. We will see later in this section that these mutual overlaps allow us to define a differential bundle analogue of the relative cotangent sequence
\[
\begin{tikzcd}
f^{\ast}(\Kah{Y}{S}) \ar[r] & \Kah{X}{S} \ar[r] & \Kah{X}{Y} \ar[r] & 0
\end{tikzcd}
\]
of algebraic geometry in an arbitrary tangent category whenever $f:X \to Y$ is also $p$-carrable.

\begin{definition}\label{Defn: Zero Carrable}
Let $f:X \to Y$ be a morphism in a tangent category $(\Cscr,\Tbb)$. We say that $f$ is \emph{$0$-carrable} if the pullback
\[
\begin{tikzcd}
T_{X/Y} \ar[r]{}{\pi_1} \ar[d, swap]{}{\pi_0} & Y \ar[d]{}{0_Y} \\
TX \ar[r, swap]{}{Tf} & TY
\end{tikzcd}
\]
exists and is preserved by $T^m$ for all $m \in \mathbb{N}$. We call $T_{X/Y}$ the \emph{relative tangent bundle of $X$ over $Y$}.
\end{definition}

By \cite[Proposition 2.4]{GeoffJSDiffBunComAlg} and \cite[Pages 4 -- 5]{Rosicky}, if every map in the slice category $\Cscr_{/Y}$ is $0$-carrable, then the relative tangent bundle $T_{X/Y}$ give a tangent bundle functor $T_{(-)/Y}:\Cscr_{/Y} \to \Cscr_{/Y}$ which makes $\Cscr_{/Y}$ into a tangent category. These tangent structures are generally different from those which appear on the slice categories in \cite[Proposition 2.5]{GeoffRobinDiffStruct}, as those are given by just restricting the global tangent structure to the slice category. Instead, these give a relative version which aligns with the tangent structures used on $\mathbf{CAlg}_{R}^{\op}$ and $\Sch_{/S}$ in algebraic geometry (as opposed to asserting that the only tangents you work with there are induced by the global K{\"a}hler differentials $\Kah{(-)}{\mathbb{Z}})$.

Let us now see how the vertical tangent bundles $T_{X/Y}$ are incarnated in our four main tangent categories of interest. It is worth observing that we can, in complete generality, only say that the vertical bundles exist whenever our tangent category of interest $\Cscr$ admits all pullbacks and that the tangent bundle functor preserves pullback\footnote{The minimal assumptsion, of course, are that every map is $0$-carrable.}. As such, when we consider $\SMan$ we also give a short argument as to \emph{why} the vertical tangent bundles exist.

\begin{example}\label{Example: Relative tangent bundle in CAlg}
Let $R$ be a commuutative rig. Because $\CAlg{R}$ is complete and that the tangent bundle functor preserves limits, we find that for every map $f:A \to B$ of commutative $R$-algebras, the pullback
\[
\begin{tikzcd}
A[\epsilon] \times_{B[\epsilon]} B \ar[r]{}{\pi_1} \ar[d, swap]{}{\pi_0} & B \ar[d]{}{0_B} \\
A[\epsilon] \ar[r, swap]{}{f[\epsilon]} & B[\epsilon]
\end{tikzcd}
\]
always exists and so every morphism is $0$-carrable. A quick computation allows us to describe the relative tangent bundle explicitly as: 
\[
T_{A/B} \cong \lbrace (a+x\epsilon, b) \in A[\epsilon] \times B \; | \; f(a)+f(x)\epsilon = b\rbrace \cong \lbrace (a + x\epsilon, f(a)) \; | \; x \in \operatorname{Ker}(f) \rbrace \cong A \ltimes \operatorname{Ker}(f).
\]
That is, $T_{A/B}$ is isomorphic to the infinitesimal extension of $A$ by the module $\operatorname{Ker}(f)$.
\end{example}
\begin{example}\label{Example: Relative Tangent Bundle in CAlgop}
Let $R$ be a commutative rig. In $\CAlg{R}^{\op}$, for any map $f^{\op}:B \to A$ in $\CAlg{R}^{\op}$ we compute that the relative tangent bundle is given by:
\begin{prooftree}
    \AxiomC{$f^{\op}:B \to A$ in $\CAlg{R}^{\op}$}
    \UnaryInfC{$f:A \to B$ in $\CAlg{R}$}
    \UnaryInfC{The $B$-module of relative K{\"a}hler differentials $\Kah{B}{A}$ exists}
    \UnaryInfC{Relative tangent bundle $T_{B/A} \cong \Sym_B(\Kah{B}{A})$}
\end{prooftree}
In particular, every map in $\CAlg{R}^{\op}$ is $0$-carrable because $\CAlg{R}^{\op}$ is complete and the tangent bundle functor preserves limits.
\end{example}
\begin{example}\label{Example: Relative tangent bundle in Sch}
Let $S$ be a base scheme. Because $\Sch_{/S}$ is finitely complete and the tangent bundle functor preserves limits, every map $f:X \to Y$ is $0$-carrable. In this case we also compute that from the relative cotangent sequence
\[
\begin{tikzcd}
f^{\ast}(\Kah{Y}{S}) \ar[r] & \Kah{X}{S} \ar[r] & \Kah{X}{Y} \ar[r] & 0
\end{tikzcd}
\]
in $\QCoh(X)$, the relative tangent bundle in $\Sch_{/S}$ is $T_{X/Y}\cong\underline{\Spec}_X(\underline{\Sym}_{\Ocal_X}(\Kah{X}{Y}))$.
\end{example}
\begin{example}\label{Example: Relative Tangent bundle in SMan}
In $\SMan$ we claim that every map $f:X \to Y$ is $0$-carrable despite the fact that $\SMan$ is not finitely complete. To see this let
\[
T_{X/Y} := \left\lbrace \left(x,\overrightarrow{v}\,\right) \; : \; x \in X, \overrightarrow{v}\,\in T_xX.\,D[f](x)\cdot\overrightarrow{v}=\overrightarrow{0}  \right\rbrace
\]
be the smooth submanifold of $TX$ generated stalkwise by the kernel of the linear maps\footnote{Because the linear maps $D[f](x):T_xX \to T_{f(x)}Y$ are all necessarily smooth maps of vector spaces, their kernels are closed linear subspaces of $T_xX$ and so the product space $\lbrace x \rbrace \times \operatorname{Ker}D[f](x)$ is a closed linear subspace of $\lbrace x \rbrace \times T_xX$. These closed linear subspaces may be patched locally as in $X$ because the transition maps in the atlas defining $X$ are smooth and hence assemble to give a (not-necessarily of full rank) smooth submanifold of $TX$.} $D[f](x)$. The maps $\pi_0:T_{X/Y} \to TX$ and  $\pi_1:T_{X/Y} \to Y$ are then defined by taking $\pi_0$ to be the (smooth) submanifold inclusion and $\pi_1$ to be given by $\pi_1(x,\overrightarrow{v}\,) := f(x)$. The diagram
\[
\begin{tikzcd}
T_{X/Y} \ar[r]{}{\pi_1} \ar[d, swap]{}{\pi_0} & Y \ar[d]{}{0_Y} \\
TX \ar[r, swap]{}{Tf} & TY
\end{tikzcd}
\]
then commutes precisely because each tangent vector $(x,\overrightarrow{v}\,)$ in $T_{X/Y}$ has been chosen so that the vector $\overrightarrow{v}$ lies in the kernel of $D[f](x)$. To see that it is a pullback assume that $M$ is a smooth manifold with maps $g:M \to Y$ and $h:M \to TX$ for which
\[
\begin{tikzcd}
M \ar[r]{}{g} \ar[d, swap]{}{h} & Y \ar[d]{}{0_Y} \\
TX \ar[r, swap]{}{Tf} & TY
\end{tikzcd}
\]
commutes. Now observe that for all $m \in M$ we can write 
\[
h(m) = \left(h_0(m), \overrightarrow{h_1^{h_0(m)}(m)}\right)
\]
where $h_0 = \pr_0 \circ h$ and where $h_1^{h_0(-)}(-)$ is the map which assigns to each $m$ the tangent vector component associated to $h(m)$ anchored at $h_0(m)$. We claim that this factors through $T_{X/Y}$; because $\pi_0$ is monic (it is injective on the level of underlying sets), it suffices to provide such a factorization because it is consequently always unique if it exists. From the fact that $0_Y \circ g = Tf \circ h$ we see that for all $m \in M$ we have
\[
\left(g(m), \overrightarrow{0}\,\right) = (0_Y \circ g)(m) = (Tf \circ h)(m) = \left( f\big(h_0(m)\big), D[f]\bigg(f\big(h_0(m)\big)\bigg)\overrightarrow{h_1^{h_0(m)}\big(m\big)}\,\right).
\]
This informs us simultaneously that $g(m) = (f \circ h_0)(m)$ for all $m \in M$ and also that for all $m \in M$,
\[
D[f]\bigg(f\big(h_0(m)\big)\bigg)\overrightarrow{h_1^{h_0(m)}\big(m\big)} = \overrightarrow{0}
\]
in $T_{f(h_0(m))}Y$. Thus every tangent vector $h_1^{h_0(m)}(m)$ lies in the kernel of $D[f]\big(f(h_0(m))\big)$ and so $h$ factors through the inclusion of $T_{X/Y}$ into $TX$. This implies that the diagram
\[
\begin{tikzcd}
M \ar[ddr, swap, bend right = 20]{}{h} \ar[dr, dashed]{}{\exists!\,h} \ar[drr, bend left = 20]{}{g} \\
& T_{X/Y} \ar[r]{}{\pi_1} \ar[d, swap]{}{\pi_0} & Y \ar[d]{}{0_Y} \\
& TX \ar[r, swap]{}{Tf} & TY
\end{tikzcd}
\]
commutes. Lastly, it is not difficult to see that the tangent bundle functor preserves this pullback, and so this gives us that $f$ is $0$-carrable.
\end{example}

As a prelude towards defining unramified morphisms in tangent categories, we now argue that whenever $f:X \to Y$ is $0$-carrable, the unique map $X \to T_{X/Y}$ is monic. So if $f: X \to Y$ is $0$-carrable, let $0_{X/Y}: X \to T_{X/Y}$ be the unique map which makes the following diagram commute:
\[
\begin{tikzcd}
X \ar[drr, bend left =20]{}{f} \ar[ddr, bend right = 20, swap]{}{0_X} \ar[dr, dashed]{}{\exists!0_{X/Y}} \\
 & T_{X/Y} \ar[r]{}{\pi_1} \ar[d, swap]{}{\pi_0} & Y \ar[d]{}{0_Y} \\
 & TX \ar[r, swap]{}{Tf} & TY
\end{tikzcd}
\]

% the naturality square
% \[
% \begin{tikzcd}
% X \ar[r]{}{f} \ar[d, swap]{}{0_X} & Y \ar[d]{}{0_Y} \\
% TX \ar[r, swap]{}{Tf} & TY
% \end{tikzcd}
% \]
% is always a prepullback, i.e., the unique map $X \to T_{X/Y}$ is monic.


\begin{lemma}\label{Lemma: Unique map from X to relative Tangent Bundle}
For any $0$-carrable map $f:X \to Y$ in a tangent category $(\Cscr,\Tbb)$, the unique map $0_{X/Y}:X \to T_{X/Y}$ is monic. 
%In particular, the naturality square for $0$ at $f$ is a prepullback in $\Cscr$.
\end{lemma}
\begin{proof} Since $0_Y$ is monic, so is $\pi_0$. Since $0_X$ is also monic and $0_X = 0_Y \circ 0_{X/Y}$, it is immediate that $0_{X/Y}$ is monic as well. 
%The claim that there is at most one lift between cones is immediate by the fact that $0_{X/Y}$ is monic.
\end{proof}

Before moving on, it is worth discussing some of the structure maps that the relative tangent bundle $T_{X/Y}$ carries, in particular its differential bundle structure. So for any object $f:X \to Y$, the projection $p_{X/Y}:T_{X/Y} \to X$ is defined via
\[
\begin{tikzcd}
T_{X/Y} \ar[r]{}{\pi_0} \ar[dr, swap]{}{p_{X/Y}} & TX \ar[d]{}{p_X} \\
 & X
\end{tikzcd}
\]
which induces a differential bundle 
\[
p_{X/Y} = \left(
\begin{tikzcd}
T_{X/Y} \ar[d]{}{p_{X/Y}} \\
X
\end{tikzcd}, \begin{tikzcd}
X \ar[d]{}{0_{X/Y}} \\
T_{X/Y}
\end{tikzcd}, \begin{tikzcd}
(T_{X/Y})_2\ar[d]{}{\operatorname{add}_{X/Y}} \\
T_{X/Y}
\end{tikzcd}, \begin{tikzcd}
T_{X/Y} \ar[d]{}{\lambda_{X/Y}} \\
T(T_{X/Y})
\end{tikzcd}
\right)
\]
over $X$ in $\Cscr$. The addition $\operatorname{add}_{X/Y}$ is relatively straightforward to define by pulling back against two copies of the projection $\pi_0:T_{X/Y} \to TX$ and using the addition on $T_2X$. To define the lift $\lambda_{X/Y}$, by assumption of being $0$-carrable, the diagram
\[
\begin{tikzcd}
T(T_{X/Y}) \ar[r]{}{T\pi_1} \ar[d, swap]{}{T\pi_0} & TY \ar[d]{}{(T \ast 0)_Y} \\
T^2X \ar[r, swap]{}{T^2f} & T^2Y
\end{tikzcd}
\]
is a pullback square. But then we induce the commuting cube
\begin{equation}\label{Eqn: Diagram defining relative lift}
\begin{tikzcd}
 & T_{X/Y} \ar[dl, swap, dashed]{}{\exists!\lambda_{X/Y}} \ar[dd, near start]{}{\pi_0} \ar[rr]{}{\pi_1} & & Y \ar[dl]{}{0_Y} \ar[dd]{}{0_Y} \\
T(T_{X/Y}) \ar[rr, near start, crossing over]{}{T\pi_1} & & TY \\
& TX \ar[dl, swap]{}{\ell_X} \ar[rr, near start]{}{Tf} & & TY \ar[dl]{}{\ell_Y} \\
T^2X \ar[rr, swap]{}{T^2f} & & T^2Y
\ar[from = 2-3, to = 4-3, crossing over, near start]{}{(T \ast 0)_Y}
\ar[from = 2-1, to = 4-1, crossing over, swap]{}{T\pi_0}
\end{tikzcd}
\end{equation}
with $\lambda_{X/Y}$ given by the universal property carried by $T(T_{X/Y})$. We also have a flip $c_{X/Y}$ on the relative tangent structure, which we obtain by following roughly the same process as defining the lift $\ell_{X/Y}$. Once again we observe that upon applying $T$ to the diagram exhibiting the universal property of $T_{X/Y}$ and appending the naturality square for $c_Y$ we obtain the commuting diagram:
\[
\begin{tikzcd}
T(T_{X/Y}) \ar[r]{}{T\pi_1} \ar[d, swap]{}{T\pi_0} & TY \ar[d]{}{(T \ast 0)_Y} \ar[r, equals] & T^2Y \ar[d]{}{(0 \ast T)_Y} \\
T^2X \ar[r, swap]{}{T^2f} & T^2Y \ar[r, swap]{}{c_Y} & T^2Y
\end{tikzcd}
\]
Note that both squares are pullback squares, so the overall diagram is a pullback square and hence
\[
\begin{tikzcd}
T(T_{X/Y}) \ar[r]{}{T\pi_1} \ar[d, swap]{}{T\pi_0} & TY \ar[d]{}{(0 \ast T)_Y} \\
T^2X \ar[r, swap]{}{c_Y \circ T^2f} & T^2Y
\end{tikzcd}
\]
is a pullback. This implies that in particular, as $c_Y \circ T^2f \cong T^2f$ in the sense that they differ by an application of $c$, there is a pullback square:
\[
\begin{tikzcd}
T^2_{X/Y} \ar[r]{}{\pi_1} \ar[d, swap]{}{\pi_0} & TY \ar[d]{}{(0 \ast T)_Y} \\
T^2X \ar[r, swap]{}{T^2f} & T^2Y
\end{tikzcd}
\]
in $\Cscr$. This incidentally shows that $Tf$ is $0$-carrable. Moreover, this also shows that there is a unique map $c_{X/Y}$ which renders the diagram
\[
\begin{tikzcd}
 & T^2_{X/Y} \ar[rr]{}{\pi_1} \ar[dd, near end]{}{\pi_0} & & TY \ar[dd]{}{(0 \ast T)_Y} \\
T(T_{X/Y})  \ar[dd, swap]{}{T\pi_0} \ar[ur, dashed]{}{\exists!\,c_{X/Y}} \ar[rr, crossing over, near start]{}{T\pi_1} & & TY \ar[ur, equals]   \\
 & T^2X \ar[rr, swap, near start]{}{T^2f} & & T^2Y \\
T^2X \ar[ur]{}{c_X} \ar[rr, swap]{}{T^2f} & & T^2Y \ar[ur, swap]{}{c_Y}
\ar[from = 2-3, to = 4-3, crossing over, near start]{}{(T \ast 0)_Y}
\end{tikzcd}
\]
commutative. Putting these observations together allows us not only to deduce that: 
%$Tf$ is $0$-carrable whenever $f$ is $0$-carrable, but also that $T(T_{X/Y})$ may be used as a model for the pullback of $T^2f$ against $(0 \ast T)_Y$.

\begin{proposition} In a tangent category $(\Cscr,\Tbb)$, if $f:X \to Y$ is $0$-carrable then $Tf$ is $0$-carrable. Furthermore, $T(T_{X/Y})$ may be used as a model for the pullback of $T^2f$ against $(0 \ast T)_Y$.
\end{proposition}

Putting this together with the fact that tangent functors reflect limits by \ref{Cor: Tangent functor reflects limits}, we obtain the following characterization.
\begin{corollary}
In a tangent category $(\Cscr,\Tbb)$, then a map $f$ is $0$-carrable if and only if $Tf$ is $0$-carrable.
\end{corollary}

\subsection{The Relative Cotangent Sequence}
We now prove the most important result in this section. The theorem below is somewhat innocuous, as on one hand it simply shows that it is not a coincidence that in each of Examples \ref{Example: Relative tangent bundle in CAlg}, \ref{Example: Relative Tangent Bundle in CAlgop}, \ref{Example: Relative tangent bundle in Sch}, and \ref{Example: Relative Tangent bundle in SMan} $T_{X/Y}$ had the flavour of a kernel of the horizontal descent $\theta_f$ (in fact, in Example \ref{Example: Relative Tangent bundle in SMan} we literally defined $T_{X/Y}$ as the kernel of $\theta_f$ in $\DBun(X)$). However, on the other hand what is remarkable about the following result is that it gives us a way of phrasing the relative cotangent sequence in tangent-categorical terms, allowing us to study said cotangent sequence in any tangent category. 

\begin{theorem}\label{Thm: ZeroCarrable makes relative bundle a kernel in DBun}
Let $f:X \to Y$ be a $0$-carrable and $p$-carrable morphism in a tangent category $(\Cscr,\Tbb)$. Then the map $\pi_0:T_{X/Y} \to TX$ makes the diagram
\[
\begin{tikzcd}
T_{X/Y} \ar[r]{}{\pi_0} & TX \ar[rr, shift left = 1]{}{\theta_f} \ar[rr, shift right = 1, swap]{}{f^{\ast}(0_Y) \circ p_X} & & f^{\ast}(TY)
\end{tikzcd}
\]
into an equalizer diagram in $\DBun(X)$.
\end{theorem}
\begin{proof}
We first check that $\pi_0$ does indeed equalize $\theta_f$ and $f^{\ast}(0_Y) \circ p_X$. To see this note that since $f^{\ast}(TY)$ is a pullback, it suffices to show that $\pr_0 \circ \theta_f \circ \pi_0 = \pr_0 \circ f^{\ast}(0_Y) \circ p_X \circ \pi_0$ and $\pr_1 \circ \theta_f \circ \pi_0 = \pr_1 \circ f^{\ast}(0_Y) \circ p_X \circ \pi_0$. To do so, first observe that $\pi_0:T_{X/Y} \to TX$ is a linear morphism of differential bundles, which implies that the diagrams
\[
\begin{tikzcd}
T_{X/Y} \ar[r]{}{\pi_0} \ar[dr, swap]{}{\pi_0 \circ p_X} & TX \ar[r]{}{\theta_f} \ar[d]{}[description]{p_X} & f^{\ast}(TY) \ar[dl]{}{\pr_0} \\
 & X
\end{tikzcd}\quad
\begin{tikzcd}
T_{X/Y} \ar[r]{}{\pi_0} & TX \ar[r]{}{\theta_f} & f^{\ast}(TY) \\
 & X \ar[ul]{}{0_{X/Y}} \ar[u]{}[description]{0_X} \ar[ur, swap]{}{f^{\ast}(0_Y)}
\end{tikzcd}
\]
commute. The diagram involving only projections implies that $\pr_0 \circ \theta_f \circ \pi_0 = p_X \circ \pi_0$ while the fact that the differential bundle $f^{\ast}(TY)$ has projection $\pr_0$ and zero $f^{\ast}(0_Y)$ implies that $\pr_0 \circ f^{\ast}(0_Y) \circ p_X \circ \pi_0 = p_X \circ \pi_0$. So $\pr_0 \circ \theta_f \circ \pi_0 = \pr_0 \circ f^{\ast}(0_Y) \circ p_X \circ \pi_0$. In a similar vein, we also get that $\pr_1 \circ \theta_f \circ \pi_0 = Tf \circ \pi_0 = 0_Y \circ \pi_1$ and
\[
\pr_1 \circ f^{\ast}(0_Y) \circ p_X \circ \pi_0 = 0_Y \circ f \circ p_X \circ \pi_0 = 0_Y \circ p_Y \circ Tf \circ \pi_0 = 0_Y \circ p_Y \circ 0_Y \circ \pi_1 = 0_Y \circ \pi_1.
\]
Thus $\pr_1 \circ \theta_f \circ \pi_0 = \pr_1 \circ f^{\ast}(0_Y) \circ p_X \circ \pi_0$. Therefore, by the universal property of $f^{\ast}(TY)$, it follows that $\theta_f \circ \pi_0 = f^{\ast}(0_Y) \circ p_X \circ \pi_0$ and so $\pi_0$ equalizes $\theta_f$ and $f^{\ast}(0_Y) \circ p_X$.

To see that $\pi_0:T_{X/Y} \to TX$ is the equalizer claimed, let $q: Z \to X$ be a differential bundle, and let $k: q \to p_X$ be a a linear differential bundle morphism which equalizes $\theta_f$ and $f^{\ast}(0_Y) \circ p_X$, so $k: Z \to TX$. Using that $k$ commutes with bundle projections, we have that 
\begin{align*}
Tf \circ k &= \pi_1 \circ \theta_f \circ k = \pi_1 \circ f^{\ast}(0_Y) \circ p_X \circ k = \pi_1 \circ f^{\ast}(0_Y) \circ q = 0_Y \circ f \circ q
\end{align*}
This gives a unique map $\rho: Z \to T_{X/Y}$ which makes the following diagram commute: 
\[
\begin{tikzcd}
Z \ar[drr, bend left = 20]{}{k} \ar[dr, dashed]{}{\exists!\rho} \ar[ddr, swap, bend right = 20]{}{f \circ q} \\
 & T_{X/Y} \ar[d, swap]{}{\pi_1} \ar[r]{}{\pi_0} & TX \ar[d]{}{Tf} \\
 & Y \ar[r, swap]{}{0_Y} & TY
\end{tikzcd}
\]

We now need to verify that $\rho$ is a linear differential bundle morphism. To see this we first note that the cell factoring $k$ shows that the diagram
\[
\begin{tikzcd}
Z \ar[r]{}{\rho} \ar[rr, bend left = 30]{}{k} \ar[d, swap]{}{q}  & T_{X/Y} \ar[r]{}{\pi_0} & TX \ar[d]{}{p_X} \\
X \ar[rr, equals] & & X
\end{tikzcd}
\]
commutes. However, the upper edge of the rectangle satisfies $q = p_X \circ k = p_X \circ \pi_0 \circ \rho = p_{X/Y} \circ \rho$ so $(\rho, \id_X)$ is a bundle map. To see that it is linear it suffices to prove that the diagram
\[
\begin{tikzcd}
Z \ar[d, swap]{}{\lambda} \ar[r]{}{\rho} & T_{X/Y} \ar[d]{}{\lambda_{X/Y}} \\
TZ \ar[r, swap]{}{T\rho} & T(T_{X/Y})
\end{tikzcd}
\]
commutes; for the construction of $\lambda_{X/Y}$, see Diagram \ref{Eqn: Diagram defining relative lift}. However, as $T^2X \xleftarrow{T\pi_0} T(T_{X/Y}) \xrightarrow{T\pi_1} TY$ is the pullback of $T^2X \xrightarrow{T^2f} T^2Y \xleftarrow{(T \ast 0)_Y} TY$, it carries the universal property that $T\rho$ is the unique map which renders the diagram
\[
\begin{tikzcd}
TZ \ar[drr, bend left = 20]{}{Tk} \ar[dr, dashed]{}{\exists!T\rho} \ar[ddr, swap, bend right = 20]{}{Tf \circ Tq} \\
 & T(T_{X/Y}) \ar[d, swap]{}{T\pi_1} \ar[r]{}{T\pi_0} & T^2X \ar[d]{}{T^2f} \\
 & TY \ar[r, swap]{}{(T \ast 0)_Y} & T^2Y
\end{tikzcd}
\]
commutative. Note also that the diagram
\[
\begin{tikzcd}
Z \ar[rr]{}{Tf \circ Tq \circ \lambda} \ar[d, swap]{}{Tk \circ \lambda} & & TY \ar[d]{}{(T \ast 0)_Y} \\
T^2X \ar[rr, swap]{}{T^2f} & & T^2Y 
\end{tikzcd}
\]
commutes with the outer edges composing into a way to witness $Z$ as a cone over $T^2X \xrightarrow{T^2f} T^2Y \xleftarrow{(T \ast 0)_Y} TY$. As such, if we can prove now that both $T\rho \circ \lambda$ and $\lambda_{X/Y} \circ \rho$ factor the diagram above through $T(T_{X/Y})$, we will be finished with verifying the linearity of $(\rho,\id_X)$ by way of the universal property of the pullback.  

We first show that $T\rho \circ \lambda$ factors the above square through $T(T_{X/Y})$. To this end we compute now that
\[
T\pi_0 \circ T\rho \circ \lambda  = T(\pi_0 \circ \rho) \circ \lambda = Tk \circ \lambda
\]
while
\[
T\pi_1 \circ T\rho \circ \lambda = T(\pi_1 \circ \rho) \circ \lambda = T(f \circ q) \circ \lambda = Tf \circ Tq \circ \lambda.
\]
Thus the diagram
\[
\begin{tikzcd}
Z \ar[dr]{}{T\rho \circ \lambda} \ar[drr, bend left = 20]{}{Tq \circ Tf \circ \lambda} \ar[ddr, swap, bend right = 20]{}{Tk \circ \lambda} \\
 & T(T_{X/Y}) \ar[r]{}{T\pi_1} \ar[d, swap]{}{T\pi_0} & TY \ar[d]{}{(T \ast 0)_{Y}} \\
 & T^2X \ar[r, swap]{}{T^2f} & T^2Y
\end{tikzcd}
\]
commutes. Next we show that $T^2f \circ Tk \circ \lambda = (T \ast 0)_Y \circ Tf \circ Tq \circ \lambda$ factors through $\lambda_{X/Y} \circ \rho$. To this end we first compute that
\[
T\pi_0 \circ \lambda_{X/Y} \circ \rho = \ell_X \circ \pi_0 \circ \rho = \ell_X \circ k = Tk \circ \lambda
\]
by the linearity of $k$. Similarly,
\begin{align*}
T\pi_1 \circ \lambda_{X/Y} \circ \rho &= 0_Y \circ \pi_1 \circ \rho = 0_Y \circ f \circ q = q \circ 0_X \circ Tf = Tf \circ Tq \circ \lambda;
\end{align*}
note that the last identity, namely $q \circ 0_X = Tq \circ \lambda$, used that $(\lambda, 0_X)$ is a morphism of additive bundles in $\Cscr$. However, this also proves that the diagram
\[
\begin{tikzcd}
Z \ar[dr]{}{\lambda_{X/Y} \circ \rho} \ar[drr, bend left = 20]{}{Tq \circ Tf \circ \lambda} \ar[ddr, swap, bend right = 20]{}{Tk \circ \lambda} \\
 & T(T_{X/Y}) \ar[r]{}{T\pi_1} \ar[d, swap]{}{T\pi_0} & TY \ar[d]{}{(T \ast 0)_{Y}} \\
 & T^2X \ar[r, swap]{}{T^2f} & T^2Y
\end{tikzcd}
\]
commutes. However, as $T(T_{X/Y})$ is a limiting cone, this in turn implies that $T\rho \circ \lambda = \lambda_{X/Y} \circ \rho$. So we get that $(\rho,\id_X)$ is a linear morphism of differential bundles.

Lastly, since $\pi_0: T_{X/Y} \to TX$ is monic (since recall it is the pullback against the monic $0_Y$), we know that  $\rho$ is the unique linear differential bundle morphism which renders the diagram
\[
\begin{tikzcd}
T_{X/Y} \ar[r]{}{\pi_0} & TX \ar[r, shift left = 1]{}{\theta_f} \ar[r, shift right = 1, swap]{}{f^{\ast}(0_Y) \circ p_X} & f^{\ast}(TY) \\
Z \ar[ur, swap]{}{k} \ar[u, dashed]{}{\exists\,\rho}
\end{tikzcd}
\]
commutative. As such, we finally conclude that $T_{X/Y} \xrightarrow{\pi_0} TX$ is the equalizer of $\theta_f$ and $f^{\ast}(0_Y) \circ p_X$ in $\DBun(X)$ as desired. 
\end{proof}

\begin{definition}\label{Defn: Relative Cotangent Sequence}
Let $f:X \to Y$ be a $0$-carrable and $p$-carrable morphism in a tangent category $(\Cscr,\Tbb)$. The \emph{relative cotangent sequence for $f$} is the diagram
\[
\begin{tikzcd}
X \ar[r]{}{0_{X/Y}} & T_{X/Y} \ar[r]{}{\pi_0} & TX \ar[r]{}{\theta_f} & f^{\ast}(TY)
\end{tikzcd}
\]
\end{definition}

As products in $\DBun(X)$ are biproducts by Proposition \ref{Prop: STructure of DBun} and $\DBun(X)$ is $\mathbf{CMon}$-enriched, this is the differential bundle analogue of an exact sequence. In particular, because the trivial differential bundle over $X$ (i.e. the identity $\id_X$) is the zero object in $\DBun(X)$, the diagram
\[
\begin{tikzcd}
X \ar[r] & T_{X/Y} \ar[r]{}{\pi_0} & TX \ar[r]{}{\theta_f} & f^{\ast}(TY)
\end{tikzcd}
\]
is exact in the sense that it exhibits $T_{X/Y}$ as the kernel of $\theta_f$ as, by Theorem \ref{Thm: ZeroCarrable makes relative bundle a kernel in DBun}, $T_{X/Y} \cong \operatorname{Ker}(\theta_f)$ in $\DBun(X)$. It also recovers the relative cotangent sequence of schemes in the following sense.

\begin{example}\label{EXample: Relative Cotangent Sequence for Schemes}
For a morphism of schemes $f:X \to Y$, the relative cotangent sequence for $f$ in $\DBun(X)$ (in the sense of Definition \ref{Defn: Relative Cotangent Sequence}) is determined by applying the relative spectrum $\underline{\Spec}_X$ of the relative symmetric algebra functor $\underline{\Sym}_{\Ocal_X}$ to the cotangent sequence:
\[
\begin{tikzcd}
f^{\ast}\Kah{Y}{S} \ar[r] & \Kah{X}{S} \ar[r] & \Kah{X}{Y} \ar[r] & 0
\end{tikzcd}
\]
Because the functor $\underline{\Spec}_{X} \circ \underline{\Sym}_{\Ocal_X}:\QCoh(X)^{\op} \to \DBun(X)$ is an equivalence of categories by \cite[Theorem 4.28]{GeoffJSDiffBunComAlg} we see that the relative cotangent sequence of \cite{EGA44} coincides with the relative cotangent sequence of Definition \ref{Defn: Relative Cotangent Sequence}.
\end{example}

\begin{example}\label{Example: Relative Cotangent Sequence for SMan}
In $\SMan$, for any smooth morphism $f:X \to Y$, the relative cotangent sequence of $f$ is the sequence
\[
\begin{tikzcd}
X \ar[r] & T_{X/Y} \ar[r] & TX \ar[rr]{}{\langle p_X, Tf \rangle} & & f^{\ast}(TY)
\end{tikzcd}
\]
in $\DBun(X)$. Along stalks $x \in X$ the sequence above induces the exact sequence
\[
\begin{tikzcd}
0 \ar[r] & \operatorname{Ker}\big(D[f](x)\big) \ar[r]{}{\operatorname{incl}} & T_xX \ar[rr]{}{D[f](x)} & & T_{f(x)}Y
\end{tikzcd}
\]
of real vector spaces.
\end{example}



\subsection{Unramified Morphisms}
There is a special situation which is worth our focus. We have seen in Lemma \ref{Lemma: Unique map from X to relative Tangent Bundle} that there is always a monic $0_{X/Y}:X \to T_{X/Y}$ which serves as the zero section for the relative tangent bundle of $X$ over $Y$. A natural question is then to ask when the map $0_{X/Y}$ is an isomorphism. In the case of $\Sch_{/S}$ this is equivalent to asking $\underline{\Spec}_X\left(\underline{\Sym}_{\Ocal_X}(0)\right) \cong X \cong T_{X/Y} = \underline{\Spec}_{X}\left(\underline{\Sym}_{\Ocal_X}\left(\Kah{X}{Y}\right)\right)$, which happens if and only if $\Kah{X}{Y} \cong 0$ (and similarly for $\CAlg{R}^{\op}$ for a commutative rig $R$). In the case of $\SMan,$ this is equivalent to asking that the diagram
\[
\begin{tikzcd}
X \ar[r]{}{f} \ar[d, swap]{}{0_X} & Y \ar[d]{}{0_Y} \\
TX \ar[r, swap]{}{Tf} & TY
\end{tikzcd}
\]
is a pullback. By making use of Example \ref{Example: Relative Tangent bundle in SMan} this amounts to asking that for all $x \in X$, $\operatorname{Ker}\big(D[f](x)\big) \cong 0.$ In turn, this indicates that there is no ramificiation within the map $f$ in the sense that nonzero tangent vectors get sent to zero through $Tf$. We make this a formal definition and briefly study these maps below.

\begin{definition}\label{Defn: TUnramified Morphisms}
In a tangent category $(\Cscr,\Tbb)$, a morphism $f:X \to Y$is \emph{$T$-unramified} if the diagram
\[
\begin{tikzcd}
    X \ar[r]{}{f} \ar[d, swap]{}{0_X} & Y \ar[d]{}{0_Y} \\
    TX \ar[r, swap]{}{Tf} & TY
\end{tikzcd}
\]
is a pullback square which is preserved by $T^m$ for all $m \in \N$.
\end{definition}

Immediate from the definition is the following result which characterizes $T$-unramified morphisms as the $0$-carrable maps which have trivial relative tangent bundle.
\begin{lemma}
In a tangent category $(\Cscr,\Tbb)$, any $T$-unramified morphism is $0$-carrable and $T_{X/Y} \cong X$. 
\end{lemma}
\begin{proof}
Because the naturality square of $0$ is a pullback, this says that $f$ is $0$-carrable and $T_{X/Y} \cong X$.
\end{proof}

As mentioned above, we will see in Theorem \ref{Thm: Rosckiy Timmersion iff Tunramified} that for a Roscisk{\'y} tangent category, the converse of the above lemma is true. So in a Roscisk{\'y} tangent category, being $T$-unramified is equivalent to being $0$-carrable. For now, this allows us to mention what are the $T$-unramified morphisms in our main examples. 

\begin{example}\label{Example: Tunramified in SMan}
In $\SMan$ a $T$-unramified morphism is an immersion. This can be seen from Theorem \ref{Thm: Rosckiy Timmersion iff Tunramified} below and the fact that $\SMan$ is a Rosick{\'y} tangent category.
\end{example}

\begin{example}\label{Example: Tunramified in CAlgR}
Let $R$ be a commutative rig. In $\CAlg{R}$ a map $f:A \to B$ is $T$-unramified if and only if $\operatorname{Ker}(f) = 0$. To see this recall from Example \ref{Example: Relative tangent bundle in CAlg} that given a map $f:A \to B$ the relative tangent bundle $T_{A/B} \cong A \ltimes \operatorname{Ker}(f)$ with natural map $0_{B/A}:A \to A \ltimes \operatorname{Ker}(f)$ given by $a \mapsto (a,0)$. This map is an isomorphism if and only if $\operatorname{Ker}(f) = \lbrace a \; | \; f(a) = 0\rbrace = 0$.
\end{example}

\begin{example}\label{Example: Tunramified in CAlgRop}
Let $R$ be a commutative rig. Then in $\CAlg{R}^{\op}$, the $T$-unramified morphisms correspond precisely to the $R$-algebra morphism $f: A \to B$ which are formally unramified, that is, those for which $\Kah{B}{A} \cong 0$ \cite[D{\'e}finition 19.10.2 \& Proposition 20.7.4]{EGA04}. This follows from the opposite equivalence $\DBun(B) \simeq \Mod{B}^{\op}$ for all commutative $R$-algebras $A$ and the fact that the relative tangent bundle $T_{B/A}$ of $f^{\op}:B \to A$ is represented by the rig $\Sym_{B}(\Kah{B}{A})$.
\end{example}

\begin{example}\label{Example: Tunramified in Sch}
Let $S$ be a scheme. In $\Sch_{/S}$, the $T$-unramified morphisms are precisely the scheme morphisms $f: X \to Y$ which are formally unramified, i.e., those for which $\Kah{X}{Y} \cong 0$. This follows from Theorem \ref{Thm: Rosckiy Timmersion iff Tunramified} below and the fact that $\Sch_{/S}$ is a Roscisk{\'y} tangent category. 
\end{example}

\begin{example}\label{Example: Tunramified in CDC} In a CDC, a map $f: X \to Y$ is $T$-unramified if and only if the diagram
\[
\begin{tikzcd}
X \ar[d, swap]{}{\iota_0} \ar[r] & 0 \ar[d]{}{\gnab_Y} \\
X \times X \ar[r, swap]{}{D[f]} & Y
\end{tikzcd}
\]
is a pullback square, where $0$ is the terminal object and $\gnab_Y: 0 \to Y$ is the zero map (since recall homsets in a CDC are commutative monoids). This follows from translating between the tangent bundle functor $T$ to the differential combinator $D$. In particular, if $f$ is linear (that is, if $D[f] = f \circ \pi_1$) then $f$ is $T$-unramified if and only if the diagram
\[
\begin{tikzcd}
0 \ar[r, equals] \ar[d, swap]{}{\gnab_X} & 0 \ar[d]{}{\gnab_Y} \\
X \ar[r, swap]{}{f} & Y
\end{tikzcd}
\]
is a pullback square, or in other words, if $\operatorname{Ker}(f) \cong 0$. 
\end{example}

We conclude this section by showing that $T$-unramified maps compose, are stable under application of $T$, and are also stable under pullback.

\begin{proposition}\label{Prop: Compositions of zero carrable}
Let $f:X \to Y$ and $g:Y \to Z$ be morphisms in a tangent category $(\Cscr,\Tbb)$. Then:
 \begin{enumerate}[{\em (i)}]
    \item If $g:Y \to Z$ is $T$-unramified then $f$ is $0$-carrable if and only if $g \circ f$ is $0$-carrable. In this case, $T_{X/Y} \cong T_{X/Z}$.
    \item If $g:Y \to Z$ is $T$-unramified then $g \circ f$ is $T$-unramified if and only if $f$ is $T$-unramified.
\end{enumerate}
\end{proposition}
\begin{proof}
We first prove $(i)$. $\implies:$ Assume that $f$ is $0$-carrable and consider the diagram:
\[
\begin{tikzcd}
T_{X/Y} \ar[r]{}{\pr_1} \ar[d, swap]{}{\pr_0} & Y \ar[r]{}{g} \ar[d]{}{0_Y} & Z \ar[d]{}{0_Z} \\
TX \ar[r, swap]{}{Tf} & TY \ar[r, swap]{}{Tg} & TZ
\end{tikzcd}
\]
Since $f$ is $0$-carrable and $g$ is $T$-unramified, both squares are pullbacks preserves by all $T^m$. Applying the Pullback Lemma implies that the outer square is a pullback, and clearly also preserved by all $T^m$. Hence that $T_{X/Y} \cong T_{X/Z}$, and thus $g \circ f$ is $0$-carrable.

$\impliedby:$ Assume that $g \circ f$ is $0$-carrable and consider the diagram:
\[
\begin{tikzcd}
T_{X/Z} \ar[r]{}{\pr_1} \ar[d, swap]{}{\pr_0} & Z \ar[d]{}{0_Z} \\
TX \ar[r, swap]{}{Tg \circ Tf} & TZ
\end{tikzcd}
\]
Because $T_{X/Z}$ is the equalizer of $Tg \circ Tf$ and the map
\[
0_Z \circ p_Z \circ Tg \circ Tf = Tg \circ 0_Y \circ p_Y \circ Tf = Tg \circ Tf \circ 0_X \circ p_X,
\]
\cite[Pages 4, 5]{Rosicky} and because $Y \cong T_{Y/Z}$ is the equalizer of $Tg$ and $0_Z \circ p_Z \circ Tg = Tg \circ 0_Y \circ p_Y$ also by \cite[Pages 4, 5]{Rosicky}, the diagram above admits a factorization:
\[
\begin{tikzcd}
T_{X/Z} \ar[rrr]{}{\pr_1} \ar[dd, swap]{}{\pr_0} \ar[drr, swap]{}{f \circ p_{X/Y}} & & & Z \ar[dd]{}{0_Z} \\
 & & Y \ar[ur, swap]{}{g} \\
TX \ar[drr, swap]{}{Tf} \ar[rrr,  near start]{}{Tg \circ Tf} & & & TZ \\
 & & TY \ar[ur, swap]{}{Tg} 
 \ar[from = 2-3, to = 4-3, crossing over, near start]{}{0_Y}
\end{tikzcd}
\]
However, as the back face of the triangular prism is a pullback and the rightmost square is a pullback, we may apply the Pullback Lemma to deduce that the leftmost square is a pullback as well, which is moreover also preserved by all $T^m$. This shows exactly that $f$ is $0$-carrable.

To prove $(ii)$ we can either defer to $(i)$ as a special case or give a more specialized proof by noting that in the diagram
\[
\begin{tikzcd}
X \ar[r]{}{f} \ar[d, swap]{}{0_X} & Y \ar[d]{}{0_Y} \ar[r]{}{g} & Z \ar[d]{}{0_Z} \\
TX \ar[r, swap]{}{Tf} & TY \ar[r, swap]{}{Tg} & TZ
\end{tikzcd}
\]
with the rightmost square a pullback, the total square is a pullback if and only if the leftmost square is a pullback.
\end{proof}

\begin{lemma}\label{Lemma: Tm preserves unramified}
In a tangent category $(\Cscr,\Tbb)$, if $f:X \to Y$ is $T$-unramified, then $T^mf$ is $T$-unramified for all $m \in \mathbb{N}$.
\end{lemma}
\begin{proof}
This is immediate from the definition, as being $T$-unramified asks that $T^m$ preserve the $0$-naturality square pullback for all $m \in \N$. Because $(T^m \ast 0) \cong (0 \ast T^m)$ for all $m \in \N$, the lemma follows.
\end{proof}

\begin{proposition}\label{Prop: Tunramified pullback stable}
In a tangent category $(\Cscr,\Tbb)$, assume that $f:X \to Y$ is $T$-unramified and that
\[
\begin{tikzcd}
W \ar[r]{}{\pi_1} \ar[d, swap]{}{\pi_0} & Z \ar[d]{}{g} \\
X \ar[r, swap]{}{f} & Y
\end{tikzcd}
\]
is a pullback which is preserved by $T$. Then $\pi_1$ is $T$-unramified as well.
\end{proposition}
\begin{proof}
Because $T$-unramified maps are preserved by $T^m$ for all $m \in \N$, for $m = 1$ we obtain the pullback square
\[
\begin{tikzcd}
TW \ar[r]{}{T\pi_1} \ar[d, swap]{}{T\pi_0} & TZ \ar[d]{}{Tg} \\
TX \ar[r, swap]{}{Tf} & TY
\end{tikzcd}
\]
which fits into a commuting cube:
\[
\begin{tikzcd}
 & TW \ar[rr]{}{T\pi_1} \ar[dd, swap, near start]{}{T\pi_0} & & TZ \ar[dd]{}{Tg} \\
W \ar[ur]{}{0_W} \ar[dd, swap]{}{\pi_0} & & Z \ar[ur, swap]{}{0_Z} \\
 & TX \ar[rr, swap, near start]{}{Tf} & & TY \\
X \ar[ur]{}{0_X} \ar[rr, swap]{}{f} & & Y \ar[ur, swap]{}{0_Y}
\ar[from = 2-1, to = 2-3, crossing over, near end]{}{\pi_1}
\ar[from = 2-3, to = 4-3, crossing over, near start]{}{g}
\end{tikzcd}
\]
The commutativity of the cube implies that the diagram
\[
\begin{tikzcd}
W \ar[r]{}{0_W} \ar[d, swap]{}{\pi_1} & TW \ar[r]{}{T\pi_0} \ar[d]{}{T\pi_1} & TX \ar[d]{}{Tf} \\
Z \ar[r, swap]{}{f} & TZ \ar[r, swap]{}{Tg} & TY
\end{tikzcd}
\]
commutes with right-most square a pullback by assumption of $T$ preserving the given pullback with apex $W$. The Pullback Lemma thus tells us that the left-most square is a pullback square if and only if the total square is a pullback. However, using the commutativity of the cube we see that the rectangle above is equivalent to the diagram:
\[
\begin{tikzcd}
W \ar[r]{}{\pi_0} \ar[d, swap]{}{\pi_1} & X \ar[r]{}{0_X} \ar[d]{}{f} & TX \ar[d]{}{Tf} \\
Z \ar[r, swap]{}{g} & Y \ar[r, swap]{}{0_Y} & TY
\end{tikzcd}
\]
The leftmost square above is a pullback by assumption and the rightmost square is a pullback by virtue of $f$ being $T$-unramified. Thus by the Pullback Lemma the total square is a pullback; winding this back shows that
\[
\begin{tikzcd}
W \ar[r]{}{0_W} \ar[d, swap]{}{\pi_1} & TW \ar[d]{}{T\pi_1} \\
Z \ar[r, swap]{}{0_Z} & TZ
\end{tikzcd}
\]
is a pullback as well. It is easy to see that this will also be preserved by all $T^m$ as well. Hence, $\pi_1$ is $T$-unramified.
\end{proof}

\section{Tangent Monics}

In this section we study what we call $T$-monic morphisms. These are the monics in a tangent category whose image under all iterations of the tangent bundle functor are again monic. They have been briefly studied in the recent paper \cite[Definition 3.39]{GeoffMarcelloTSubmersionPaper} where they were used there to study display monic $T$-{\'e}tale maps (which were in turn used as a tangent-categorical analogue of open local diffeomorphisms in a tangent category). We use them here as technical tools for both studying the various morphisms defined in this paper and also as a way to characterize $T$-{\'e}tale maps and monic $T$-{\'e}tale maps later in terms of the horizontal descent $\theta_f$ (Propositions \ref{Prop: Classify of Tetales} and \ref{Prop: Classify of monic Tetales} below).

\begin{definition}\label{Defn: TMonic maps}[{\cite[Definition 3.39]{GeoffMarcelloTSubmersionPaper}}]
In a tangent category $(\Cscr,\Tbb)$, we say that a morphism $f: X \to Y$ is \emph{$T$-monic} if $T^mf:T^mX \to T^mY$ is monic for all $m \in \N$.
\end{definition}
Note that by convention $T^0(f) = = f$, so being $T$-monic implies that $f$ is a monic which is preserved by all powers of $T$. We now present a characterization of the $T$-monics in our main examples.

\begin{example}\label{Example: T monics for SMan}
In $\SMan$, the $T$-monic morphisms are precisely the monic immersions, i.e., the embeddings. A clean proof of this may be given via Proposition \ref{Cor: f monic and thetaf monic iff Tmonic} below.
\end{example}

\begin{example}\label{Example: T monics for calg}
Let $R$ be a commutative rig. Then in $\CAlg{R}$ the $T$-monics are precisely the monomorphisms. This can be seen by observing that the tangent bundle functor $T(A) := A[\epsilon]$ preserves limits, so it in particular preserves all monics. By appealing to Corollary \ref{Cor: Tangent functor reflects limits} we see that $T^mf$ for $m \geq 1$ is monic if and only if $f$ is monic.
\end{example}

\begin{example}\label{Example: T monics for affine schemes}
Let $R$ be a commutative rig. Then in $\CAlg{R}^{\op}$ the $T$-monics are precisely the monomorphisms as well. This can be seen from much the same way as the example prior. 
\end{example}

\begin{example}\label{Example: T monics for Sch}
In $\Sch_{/S}$ the $T$-monic morphisms are precisely the monomorphisms. While we can once again use the same argument as in the previous example, an alternative proof of this may be given as an immediate consequence of Proposition \ref{Cor: f monic and thetaf monic iff Tmonic} below.
\end{example}

\begin{example}\label{Example: T monics for CDC}
Let $\Cscr$ be a CDC. Then $f:X \to Y$ is $T$-monic if and only if $D^n[f]$ is monic for all $m \in \mathbb{N}$, that is, $f$ is $T$-monic if and only if all of its higher-derivatives are monic. In particular, when $f$ is linear, then $f$ $T$-monic if and only if $f$ is monic. 
\end{example}


\begin{example} Here is an example which shows, concretely, that not all monics in a tangent category are $T$-monics. Consider the CDC $\mathbf{Euc}$. Then the monic $x^3:\R \to \R$ is \emph{not} a $T$-monic since its derivative $D[x^3]:\R \times \R \to \R$ is $D[x^3](p,v) = \left(3x^2|_{x=p}\right)\overrightarrow{v} = 3p^2\overrightarrow{v}$ for all $(p,v) \in \R \times \R$. In particular, if $p = 0$ then $D[x^3](0,v) = D[x^3](0,w)$ for all $v, w \in \R$ and so $D[x^3]$ is not monic. So $x^3$ is monic but not $T$-monic. 
\end{example}

We now record that in any tangent category, the vertical lift and the canonical flip are $T$-monic.

\begin{proposition}\label{Prop: Vertical Lift is TMonic}
In a tangent category $(\Cscr,\Tbb)$, 
 \begin{enumerate}[{\em (i)}]
    \item The vertical lift $\ell_X:TX \to T^2X$ is $T$-monic for every object $X$.
    \item The canonical flip $c_X:T^2X \to T^2X$ is a $T$-monic for every object $X$.
\end{enumerate}
\end{proposition}
\begin{proof}
For the vertical lift, by \cite[Lemma 2.13]{GeoffRobinDiffStruct}, the universality of the vertical lift implies that $\ell$ is the equalizer
\[
\begin{tikzcd}
TX \ar[r]{}{\ell_X} & T^2X \ar[rrr, bend right = 30, swap]{}{(T \ast p)_X} \ar[rrr,bend left = 30]{}{(p \ast T)_X} \ar[r]{}{(p \ast T)_X} & TX \ar[r]{}{p_X} & X \ar[r]{}{0_X} & TX
\end{tikzcd}
\]
Additionally, all powers $T^m$ of the tangent functor $T$ preserve said equalizer. Putting this all together implies that $\ell_X$ is $T$ monic. On the other hand, for the canonical flip, this is immediate from $c_X$ being an isomorphism.
\end{proof}

We immediately get that $T$-monic morphisms compose, are stable under application of the tangent functor, and are stable under pullbacks which are preserved by the tangent functor. 

\begin{proposition}\label{Prop: T monics compose and are stable under T preserved pullbacks}
Let $f:X \to Y$ and $g:Y \to Z$ be $T$-monic maps in a tangent category $(\Cscr,\Tbb)$ and assume also that we have a pullback square
\[
\begin{tikzcd}
X \times_Y W \ar[r]{}{\pr_0} \ar[d, swap]{}{\pr_1} & X \ar[d]{}{f} \\
W \ar[r, swap]{}{h} & Y
\end{tikzcd}
\]
which is preserved by $T^m$ for all $m \in \N$. Then:
\begin{enumerate}[{\em (i)}] 
    \item The composite $g \circ f:X \to Z$ is $T$-monic.
    \item For all $m \in \N$, $T^mf$ is $T$-monic.
    \item The map $\pr_1:X \times_Y W \to W$ is $T$-monic.
\end{enumerate}
\end{proposition}
\begin{proof}
Claim $(i)$ is immediate from the observations that $T^m(g \circ f) = T^m(g) \circ T^m(f)$ for all $m \in \N$ and that monics compose. Claim $(ii)$ is immediate from the fact that for all $k, m \in \N$ if $T^{m}f$ is monic then $T^{m+k}f = T^k(T^mf)$ is monic. For Claim $(iii)$, note that upon fixing an $m \in \N$, applying the functor $T^m$ to the given pullback diagram, and using that $T^m$ preserves this pullback gives rise to the pullback square:
\[
\begin{tikzcd}
T^m(X \times_Y W) \ar[rr]{}{T^m\pr_0} \ar[d, swap]{}{T^m\pr_1} & & T^mX \ar[d]{}{T^mf} \\
T^mW \ar[rr, swap]{}{T^mh} & & T^mY
\end{tikzcd}
\]
Since $T^mf$ is monic and monics are stable under pullback, we see that $T^m\pr_1$ is monic.
\end{proof}

We now show that for any $0$-carrable morphism the unique map $0_{X/Y}:X \to T_{X/Y}$ is $T$-monic.

\begin{lemma}\label{Lemma: 0carrable is Tmonic}
In a tangent category $(\Cscr,\Tbb)$, for any $0$-carrable morphism $f:X \to Y$, $0_{X/Y}$ is $T$-monic.
\end{lemma}
\begin{proof}
For $m = 0$, $T^m0_{X/Y} = 0_{X/Y}$ is monic by Lemma \ref{Lemma: Unique map from X to relative Tangent Bundle}. For $m = 1$ observe that because $T$ preserves the pullback defining $T_{X/Y}$, the diagram
\[
\begin{tikzcd}
T(T_{X/Y}) \ar[r]{}{T\pi_1} \ar[d, swap]{}{T\pi_0} & TY \ar[d]{}{(T \ast 0)_Y} \\
T^2X \ar[r, swap]{}{T^2f} & T^2Y
\end{tikzcd}
\]
is a pullback. Thus $T\pi_0$ is monic after recognizing that $T \ast 0$ is monic because $0$ is a section and hence an absolute equalizer. Using the commuting diagram
\[
\begin{tikzcd}
 & T(T_{X/Y}) \ar[dr]{}{T\pi_0} \\
TX \ar[rr, swap]{}{(T \ast 0)_X} \ar[ur]{}{T0_{X/Y}} & & T^2X
\end{tikzcd}
\]
allows us to deduce that that $(T \ast 0)_X = T\pi_0 \circ T0_{X/Y}$. Because  $T \ast 0$ is monic by virtue of being a section, the post-composition of $T0_{X/Y}$ with the monic $T\pi_0$ is itself a monic. For $m \geq 2$ a routine induction on $m$ using the same arguments as for the case $m = 1$ gives that $T^m0_{X/Y}$ is monic.
\end{proof}

We now show that a $p$-carrable map is a $T$-monic if it is monic and that the horizontal descent is $T$-monic.

\begin{proposition}\label{Cor: f monic and thetaf monic iff Tmonic}
Let $f:X \to Y$ be a $p$-carrable map in a tangent category $(\Cscr,\Tbb)$. Then $f$ is $T$-monic if and only if $f$ is monic and $\theta_f$ is $T$-monic.
\end{proposition}
\begin{proof} For the $\implies$ direction, since $f$ is $p$-carrable, then for all $m \in \N$ we have pullback diagrams
\[
\begin{tikzcd}
T^{m+1}X \ar[drr, bend left = 20]{}{T^{m+1}f} \ar[ddr, swap, bend right = 20]{}{(T^m \ast p)_X} \ar[dr, dashed]{}{\exists!T^m\theta_f} \\
 & T^m(f^{\ast}TY) \ar[r]{}{T^m\pi_1} \ar[d, swap]{}{T^m\pi_0} & T^{m+1}Y \ar[d]{}{(T^m \ast p)_Y} \\
 & T^mX \ar[r, swap]{}{T^mf} & T^mY
\end{tikzcd}
\]
induced by applying $T^m$ to the pullback diagram defining $f^{\ast}(TY)$. In each case, since $T^mf$ is monic for all $m \in \N$, $T^m\pi_0$ is monic. Using also that $T^{m+1}f$ is monic for all $m \in \N$ allows us to deduce that $T^m\theta_f$ is monic for all $m \in \N$ as well because $T^{m+1}f = T^mf \circ T^m\theta_f$. 

For the $\impliedby$ direction, in order to prove that $f$ is $T$-monic, we must show that $T^m(f)$ is monic for all $m \in \N$. We show this by induction on $m$. For the base case $m = 0$ we note that $T^0(f) = \id(f) = f$ is monic by assumption. When $m = 1$ we note that since $Tf = \pr_1 \circ \theta_f$, $Tf$ is monic precisely because $\theta_f$ and $\pr_1$ are both monic since $\theta_f$ is by assumption and $\pr_1$ because it is the pullback of $p_Y:TY \to Y$ against the monic $f:X \to Y$. We now proceed with the induction on $m$. Let $m \in \N$ be given with $m \geq 1$ and assume that $T^m(f)$ is monic. We will show that $T^{m+1}(f)$ is monic. Now since we have a pullback
\[
\begin{tikzcd}
T^m(f)^{\ast}(T^{m+1}(Y)) \ar[r]{}{\pr_1} \ar[d, swap]{}{\pr_0} & T(T^m(Y)) \ar[d]{}{(p \ast T^m)_Y} \\
T^m(X) \ar[r, swap]{}{T^m(f)} & T^m(Y)
\end{tikzcd}
\]
Then $\pr_1$ is monic by the Inductive Hypothesis on $T^m(f)$. Additionally, applying Proposition \ref{Proposition: Tangent of thetaf} to $T^{m-1}f$ and expanding out the induced algebraic equations shows that there are isomorphisms $\tilde{c}_m:T(T^{m-1}(f)^{\ast}(T^mY)) \to T^m(f)^{\ast}(T^{m+1}Y)$ and $\hat{c}_m:T^{m+1}X \to T^{m+1}X$ which make the equation $\tilde{c}_m \circ T^m\theta_{f} = \theta_{T^mf} \circ \hat{c}_m$ hold. But as $\tilde{c}_m$ and $\hat{c}_m$ are isomorphisms and $T^m\theta_f$ is monic, $\theta_{T^mf}$ is monic. This then gives rise to the commuting diagram
\[
\begin{tikzcd}
T^{m+1}X \ar[drr, bend left = 20]{}{T^{m+1}f} \ar[dr, dashed]{}{\exists!\theta_{T^mf}} \ar[ddr, swap, bend right = 20]{}{(p \ast T^m)} \\
 & T^{m}(f)^{\ast}(T^{m+1}(Y)) \ar[d, swap]{}{\pr_0} \ar[r]{}{\pr_1} & T^{m+1}Y \ar[d]{}{(p \ast T^m)_Y} \\
 & T^mX \ar[r, swap]{}{T^mf} & TY
\end{tikzcd}
\]
and hence allows us to deduce that $T^{m+1}(f)$ is monic. 
\end{proof}

\begin{corollary}
In a tangent category $(\Cscr,\Tbb)$, if $f:X \to Y$ is $p$-carrable and $T$-monic, then $T^m\theta_f$ and $\theta_{T^mf}$ are $T$-monic for all $m \in \N$.
\end{corollary}
\begin{proof} By Proposition \ref{Cor: f monic and thetaf monic iff Tmonic}, $\theta_f$ is $T$-monic. By Proposition \ref{Prop: T monics compose and are stable under T preserved pullbacks}.(ii), we get that $T^m\theta_f$ is also $T$-monic. Again by Proposition \ref{Prop: T monics compose and are stable under T preserved pullbacks}.(ii), we get that $T^m f$ is $T$-monic, hence by Proposition \ref{Cor: f monic and thetaf monic iff Tmonic}, $\theta_{T^mf}$ is $T$-monic. 
\end{proof}

\section{Tangent-Immersions}\label{Section: TImmersions}
In this section we introduce $T$-immersions, which are a class of morphisms in a tangent category which structurally describe what it means to be an immersion in terms of tangent categorical data. While we will generically focus on maps which are $p$-carrable, we will give the definition for general tangent categories before specializing. We will also examine how $T$-immersions relate to $T$-unramified and $0$-carrable morphisms later on in this section. 

\subsection{Prepullbacks and Immersions}

In order to define $T$-immersions, let us recall first what it means to be a prepullback in a category. So in a category $\Cscr$, a commuting square
\[
\begin{tikzcd}
X \ar[r]{}{f} \ar[d, swap]{}{g} & Y \ar[d]{}{h} \\
Z \ar[r, swap]{}{k} & W
\end{tikzcd}
\]
is a \emph{prepullback in $\Cscr$} if for any commutative diagram 
\[
\begin{tikzcd}
V \ar[r]{}{s} \ar[d, swap]{}{t} & Y \ar[d]{}{h} \\
Z \ar[r, swap]{}{k} & W
\end{tikzcd}
\]
there is at most one map which makes the following diagram commute: 
\[
\begin{tikzcd}
V \ar[drr, bend left = 20]{}{s} \ar[ddr, swap, bend right = 20]{}{t} \ar[dr, dashed]{}{\exists\leq 1} \\
& X \ar[r]{}{f} \ar[d, swap]{}{g} & Y \ar[d]{}{h} \\
& Z \ar[r, swap]{}{k} & W
\end{tikzcd}
\]
A $T$-immersion will be a map in a tangent category such that the projection naturality square is a prepullback. 


\begin{definition}\label{Defn: Timmersion}
In a tangent category $(\Cscr,\Tbb)$, a map $f:X \to Y$ is a \emph{$T$-immersion} if the naturality square
\[
\begin{tikzcd}
TX \ar[d, swap]{}{p_X} \ar[r]{}{Tf} & TY \ar[d]{}{p_Y} \\
X \ar[r, swap]{}{f} & Y
\end{tikzcd}
\]
is a prepullback which is preserved by $T^m$ for all $m \in \N$.
\end{definition}

We now show that $T$-immersions are stable under composition and pullbacks which are preserved by the tangent bundle functor. To go about this, however, we need to provide a folkloric structural lemma for the sake of completeness. While we cannot and do not claim originality of the result\footnote{We have been unable to find it directly stated in the literature, but the second author learned it from Robin Cockett and according to R.\@ Cockett it is a well-known structural result.}, it is a useful technical tool which we will require.

\begin{lemma}[Folklore]\label{Lemma: The prepullback stacking lemma}
Consider commutative diagrams with squares numbered as below:
\[
\begin{tikzcd}
X \ar[r, ""{name = UL}]{}{k} \ar[d, swap]{}{f} & Y \ar[d]{}{g} \ar[r, ""{name = UR}]{}{\ell} & Z \ar[d]{}{h} \\
W \ar[r, swap, ""{name = DL}]{}{k^{\prime}} & V \ar[r, swap, ""{name = DR}]{}{\ell^{\prime}} & U
\ar[from = UL, to = DL, symbol = {\rotatebox[origin=c]{90}{$(1)$}}]
\ar[from = UR, to = DR, symbol = {\rotatebox[origin=c]{90}{$(2)$}}]
\end{tikzcd}
\qquad
\begin{tikzcd}
X \ar[r, ""{name = U}]{}{\ell \circ k} \ar[d, swap]{}{f} & Z \ar[d]{}{h} \\
W \ar[r, swap, ""{name = D}]{}{\ell^{\prime} \circ k^{\prime}} & U
\ar[from = U, to = D, symbol = {\rotatebox[origin=c]{90}{$(3)$}}]
\end{tikzcd}
\]
Then:
\begin{enumerate}[{\em (i)}]
    \item If Square $(3)$ is a prepullback then Square $(1)$ is a prepullback as well.
    \item If Square $(1)$ is a prepullback and Square $(2)$ is a prepullback then Square $(3)$ is a prepullback.
\end{enumerate}
In particular, if Square $(2)$ is a pullback then Square $(1)$ is a prepullback if and only if Square $(3)$ is a prepullback.
\end{lemma}
\begin{proof}
We first prove Statement $(i)$. Assume that Square $(3)$ is a prepullback and that we have a commuting diagram of the form:
\[
\begin{tikzcd}
P \ar[dr, shift left = 1]{}{\alpha} \ar[dr, shift right = 1, swap]{}{\beta} \ar[drr, bend left =20]{}{s} \ar[ddr, swap, bend right = 20]{}{t} & \\
& X \ar[r]{}{k} \ar[d, swap]{}{f} & Y \ar[d]{}{g} \\
& W \ar[r, swap]{}{k^{\prime}} & V
\end{tikzcd}
\]
Because then the diagram
\[
\begin{tikzcd}
P \ar[dr, shift left = 1]{}{\alpha} \ar[dr, shift right = 1, swap]{}{\beta} \ar[drr, bend left =20]{}{\ell \circ s} \ar[ddr, swap, bend right = 20]{}{t} \\
& X \ar[r, ""{name = U}]{}{\ell \circ k} \ar[d, swap]{}{f} & Z \ar[d]{}{h} \\
& W \ar[r, swap, ""{name = D}]{}{\ell^{\prime} \circ k^{\prime}} & U
\end{tikzcd}
\]
commutes, using that Square $(3)$ is a prepullback implies that $\alpha = \beta$ and so proves that Square $(1)$ is a prepullback.

We now prove Statement $(ii)$. Assume that Squares $(1)$ and $(2)$ are prepullbacks and that we have a commuting diagram of the form:
\[
\begin{tikzcd}
P \ar[dr, shift left = 1]{}{\alpha} \ar[dr, shift right = 1, swap]{}{\beta} \ar[drr, bend left =20]{}{s} \ar[ddr, swap, bend right = 20]{}{t} \\
& X \ar[r, ""{name = U}]{}{\ell \circ k} \ar[d, swap]{}{f} & Z \ar[d]{}{h} \\
& W \ar[r, swap, ""{name = D}]{}{\ell^{\prime} \circ k^{\prime}} & U
\end{tikzcd}
\]
Now $g \circ k = k^{\prime} \circ f$ and $f \circ \alpha = t = f \circ \beta$, the following diagram commutes: 
\[
\begin{tikzcd}
P \ar[dr, shift left = 1]{}{k \circ \alpha} \ar[dr, shift right = 1, swap]{}{k \circ \beta}  \ar[drr, bend left =20]{}{s} \ar[ddr, swap, bend right = 40]{}{k^{\prime} \circ t} \\
& Y \ar[r, ""{name = U}]{}{\ell} \ar[d, swap]{}{g} & Z \ar[d]{}{h} \\
& V \ar[r, swap, ""{name = D}]{}{\ell^{\prime}} & U
\end{tikzcd}
\]
Then using that Square $(2)$ is a prepullback, we get that $k \circ \alpha = k \circ \beta$. This then implies that the diagram
\[
\begin{tikzcd}
P \ar[dr, shift left = 1]{}{\alpha} \ar[dr, shift right = 1, swap]{}{\beta} \ar[drr, bend left =20]{}{k \circ \alpha} \ar[ddr, swap, bend right = 20]{}{t} \\
& X \ar[r, ""{name = U}]{}{k} \ar[d, swap]{}{f} & Y \ar[d]{}{g} \\
& W \ar[r, swap, ""{name = D}]{}{k^{\prime}} & V
\end{tikzcd}
\]
commutes as well. Using that Square $(1)$ is a prepullback gives that $\alpha = \beta$ and hence that Square $(3)$ is a prepullback as well.
\end{proof}

\begin{proposition}\label{Prop: Immersions comp and Tm stable}
In a tangent category $(\Cscr,\Tbb)$, if $f:X \to Y$ and $g:Y \to Z$ are $T$-immersions then:
\begin{enumerate}[{\em (i)}]
    \item The composite $g \circ f:X \to Z$ is a $T$-immersion.
    \item The map $T^mf$ is a $T$-immersion for all $m \in \N$.
    \item If the following pullback exists 
\[
\begin{tikzcd}
W \ar[r]{}{\pi_1} \ar[d, swap]{}{\pi_0} & Z \ar[d]{}{g} \\
X \ar[r, swap]{}{f} & Y
\end{tikzcd}
\]
and is preserved by $T^m$ for all $m \in \N$, then $\pi_1$ is a $T$-immersion as well.
\end{enumerate}
\end{proposition}
\begin{proof}
Statement $(i)$ follows from an immediate application of Lemma \ref{Lemma: The prepullback stacking lemma}.(i). Statement $(ii)$ holds because by assumption all powers of the tangent functor preserve the given prepullback. For statement $(iii)$, consider the commuting diagram:
\[
\begin{tikzcd}
TW \ar[r]{}{p_W} \ar[d, swap]{}{T\pi_1} & W \ar[d]{}{\pi_1} \ar[r]{}{\pi_0} & X \ar[d]{}{f} \\
TZ \ar[r, swap]{}{p_Z} & Z \ar[r, swap]{}{g} & Y
\end{tikzcd}
\]
Because the rightmost square is a pullback by assumption, by Lemma \ref{Lemma: The prepullback stacking lemma} it suffices to prove the whole rectangle is a prepullback in order to conclude that the leftmost square is a prepullback. To this end observe also that the commuting rectangle above is equal to the commuting rectangle
\[
\begin{tikzcd}
TW \ar[r]{}{T\pi_0} \ar[d, swap]{}{T\pi_1} & TX \ar[r]{}{p_X} \ar[d]{}{Tf} & X \ar[d]{}{f} \\
TZ \ar[r, swap]{}{Tg} & TY \ar[r, swap]{}{p_Y} & Y
\end{tikzcd}
\]
we see that is suffices to prove that this last rectangle is a prepullback. To this end assume that we have a commuting diagram:
\[
\begin{tikzcd}
V \ar[drr, bend left = 20]{}{t} \ar[ddr, swap, bend right = 20]{}{s} \ar[dr, shift left = 1]{}{\alpha} \ar[dr, shift right = 1, swap]{}{\beta} \\
 & TW \ar[r]{}{T\pi_1} \ar[d]{}{p_X \circ T\pi_0} & TZ \ar[d]{}{p_Y \circ Tg} \\
 & X \ar[r, swap]{}{f} & Y
\end{tikzcd}
\]
Because $TW$ is a pulback with projections $T\pi_0$ and $T\pi_1$, to prove that $\alpha = \beta$ it suffices to prove that $T\pi_1 \circ \alpha = T\pi_1 \circ \beta$ and $T\pi_0 \circ \alpha = T\pi_0 \circ \beta$. The first of these identities can be read off the diagram directly as
\[
T\pi_1 \circ \alpha = t = T\pi_1 \circ \beta.
\]
For the other identity, consider that the computations
\begin{align*}
& Tf \circ T\pi_0 \circ \alpha = Tg \circ T\pi_1 \circ \alpha = Tg \circ t = Tg \circ T\pi_1 \circ \beta = Tf \circ T\pi_0 \circ \beta
\end{align*}
and
\begin{align*}
& p_X \circ T\pi_0 \circ \alpha = s = p_X \circ T\pi_0 \circ \beta
\end{align*}
imply that the diagram
\[
\begin{tikzcd}
V \ar[drr, bend left = 20]{}{Tg \circ t} \ar[ddr, swap, bend right = 60]{}{s} \ar[dr, shift left = 1]{}{T\pi_0 \circ \alpha} \ar[dr, shift right = 1, swap]{}{T\pi_0 \circ \beta} \\
 & TX \ar[r]{}{Tf} \ar[d, swap]{}{p_X} & TY \ar[d]{}{p_Y} \\
 & X \ar[r, swap]{}{f} & Y
\end{tikzcd}
\]
commutes. Using that $f$ is a $T$-immersion gives that $T\pi_0 \circ \alpha = T\pi_0 \circ \beta$ and so allows us to deduce that $\alpha = \beta$. So that the naturality square for $\pi_1$ is a prepullback. Running this same argument for arbitrary $m \in \N$ gives that $\pi_1$ is a $T$-immersion.
\end{proof}

When given a $p$-carrable morphism it is significantly simpler to check if is a $T$-immersion since we now show this is the case precisely when its horizontal descent morphism is $T$-monic. 

\begin{lemma}\label{Lemma: Timmersion if and only if thetaf monic}
In a tangent category $(\Cscr,\Tbb)$, if $f:X \to Y$ is $p$-carrable, then $f$ is a $T$-immersion if and only if $\theta_f:TX \to f^{\ast}(TY)$ is $T$-monic.
\end{lemma}
\begin{proof}
$\implies:$ Assume that $f$ is a $T$-immersion and that there are maps $g$ and $h$ rendering the diagram
\[
\begin{tikzcd}
Z \ar[r, shift left = 1]{}{g} \ar[r, shift right = 1, swap]{}{h} & TX \ar[r]{}{\theta_f} & f^{\ast}(TY)
\end{tikzcd}
\]
commutative. Then $p_X \circ g = \pi_0 \circ \theta_f \circ g = \pi_1 \circ \theta_f \circ g = Tf \circ g$, $p_X \circ h = Tf \circ h$, and both $g$ and $h$ make the diagram
\[
\begin{tikzcd}
Z \ar[drr, bend left = 20]{}{} \ar[ddr, swap, bend right = 20]{}{} \ar[dr, shift left = 0.5]{}{g} \ar[dr, shift right = 0.5, swap]{}{h} \\
 & TX \ar[r]{}{Tf} \ar[d, swap]{}{p_X} & TY \ar[d]{}{p_Y} \\
 & X \ar[r, swap]{}{f} & Y
\end{tikzcd}
\]
commute. But since the naturality square for $p$ is a prepullback we have that $g = h$ and so that $\theta_f$ is monic. Finally, using that all powers $T^m$ preserve the given prepullback and running the same argument for $T^m\theta_f$ shows that $\theta_f$ is $T$-monic.

$\impliedby:$ If $\theta_f$ is $T$-monic then it is immediate that for all $m \in \N$ the naturality square for $(T^m \ast p)$ at $T^mf$ has at most one map by virtue of $T^m\theta_f$ being monic.
\end{proof}

We now present the examples of $T$-immersions in our main examples. 

\begin{example}\label{Example: TImmersions in SMan}
In $\SMan$, a morphism $f:X \to Y$ is a $T$-immersion if and only if it is an immersion of smooth manifolds. Recall from Example \ref{Example: What  is thetaf in SMan} that $\theta_f:TX \to f^{\ast}(TY)$ is given by $\theta_f\left(x,\overrightarrow{v}\right) = \left(x,D[f](x)\cdot \overrightarrow{v}\right).$ Moreover, since $p_Y:TY \to Y$ is a submersion, we have that $f^{\ast}(TY) \cong X \times_{Y} TY \cong \coprod_{x \in X} T_{f(x)}Y$. Thus we see that $\theta_f$ is monic if and only if for all $x \in X$, the map $T_xf:T_xX \to T_{f(x)}Y$ is injective. However, this is the case if and only if $f$ is an immersion.
\end{example}

\begin{example}\label{Example: TImmersions in CAlgR}
Let $R$ be a commutative rig. In $\mathbf{CAlg}_R$ the $T$-immersions are precisely the injective morphisms of $R$-algebras. To see this note the diagram
\[
\begin{tikzcd}
A[\epsilon] \ar[dr, dashed]{}{\theta_f} \ar[drr, bend left = 20]{}{f[\epsilon]} \ar[ddr, swap, bend right = 20]{}{p_A} \\
 & f^{\ast}(B[\epsilon]) \ar[r]{}{\pi_1} \ar[d, swap]{}{\pi_0} & B[\epsilon] \ar[d]{}{p_B}  \\
 & A \ar[r, swap]{}{f} & B
\end{tikzcd}
\]
has $f^{\ast}(B[\epsilon]) \cong A \ltimes B$. Under the isomorphism $A \ltimes B \cong \left\lbrace (a, b\epsilon) \; | \; a \in A, b \in B \right\rbrace$, we see that $\theta_f:A[\epsilon] \to f^{\ast}(B[\epsilon])$ takes the form $\theta_f(a+x\epsilon) = (a,f(x)).$ Thus we see immediately that $\theta_f$ is monic if and only if $f$ is monic.
\end{example}

\begin{example}\label{Example: Timmersions in CAlgop}
Let $R$ be a commutative ring. In $\mathbf{CAlg}_R^{\op}$ the $T$-immersions are precisely the formally unramified morphisms of $R$-algebras, which recall are $R$-algebra morphisms $f: A \to B$ such that $\Kah{B}{A} \cong 0$ \cite[D{\'e}finition 19.10.2 \& Proposition 20.7.4]{EGA04}. To see this, consider that the map $\Spec f:\Spec B \to \Spec A$ induces corresponding structure map $\theta_{f}:T_{B/R} \to f^{\ast}(T_{A/R})$ given by $\theta_f = \Spec(\Sym_B(v))$ for $v$ the map in the relative cotangent exact sequence:
\[
\begin{tikzcd}
\Kah{A}{R} \otimes_A B \ar[r]{}{v} & \Kah{B}{R} \ar[r] & \Kah{B}{A} \ar[r] & 0
\end{tikzcd}
\]
Now, since $\DBun(B)^{\op} \simeq \Mod{B}$ by \cite{GeoffJSDiffBunComAlg}, we see that $\Spec(\Sym_B(v))$ is monic if and only if $v$ is an epimorphism of $B$-modules. However, as the relative cotangent sequence is exact, $v$ is an epimorphism if and only if $0 \cong \operatorname{Coker}(v) \cong \Kah{B}{A}$.
\end{example}


\begin{example}\label{Example: Timmersions in Schemes}
The above example extends to the full category of schemes $\Sch_{S}$ for arbitrary base schemes $S$. Indeed, in $\Sch_{/S}$, the morphisms for which $\theta_f$ is monic are precisely the formally unramified morphisms of $S$-schemes. Recall from \cite[Proposition 17.2.1]{EGA44} that a morphism of schemes $f:X \to Y$ is formally unramified if and only if the sheaf of relative K{\"a}hler differentials satisfies $\Kah{X}{Y} \cong 0$. Recall also from the relative cotangent sequence for K{\"a}hler differentials of schemes that there is an exact sequence of quasi-coherent sheaves on $X$
\[
\Kah{Y}{S} \otimes_{\Ocal_Y} \Ocal_X \to \Kah{X}{S}  \to \Kah{X}{Y} \to 0
\]
so $\Kah{X}{Y}$ is the cokernel of the map $\Kah{Y}{S} \otimes_{\Ocal_Y} \Ocal_X \to \Kah{X}{S}$ in $\QCoh(X)$. We now use the equivalence $\QCoh(X) \simeq \DBun(X)^{\op}$ of \cite{GeoffJSDiffBunComAlg} to observe that the equivalences
\begin{prooftree}
    \AxiomC{$\Kah{X}{Y} \cong 0$ in $\QCoh(X)$}
    \UnaryInfC{$T_{X/Y} \cong 0$ in $\DBun(X)$}
\end{prooftree}
and
\begin{prooftree}
    \AxiomC{Exact Sequence $\Kah{Y}{S} \otimes_{\Ocal_Y} \Ocal_X \to \Kah{X}{S} \to \Kah{X}{Y} \to 0$ in $\QCoh(X)$}
    \UnaryInfC{Exact Sequence $X \to T_{X/Y} \to T_{X/S} \to T_{Y/S} \times_Y X$ in $\DBun(X)$}
\end{prooftree}
combine to allow us to deduce
\begin{prooftree}
    \AxiomC{Exact Sequence $X \to T_{X/Y} \to T_{X/S} \to T_{Y/S} \times_Y X$ in $\DBun(X)$}
    \UnaryInfC{Exact Sequence $X = X \to T_{X/S} \to T_{Y/S} \times_Y X$ in $\DBun(X)$}
    \UnaryInfC{$\theta_f:T_{X/S} \to T_{Y/S} \times_Y X$ a kernel in $\DBun(X)$}
    \UnaryInfC{$\theta_f$ monic in $\DBun(X)$, as $\DBun(X) \simeq \QCoh(X)^{\op}$ is Abelian}
\end{prooftree}
\end{example}

\begin{example}\label{Example: Immersions in CDC} In a CDC, as $\theta_f = \langle \pi_0, D[f]\rangle$ it follows that $\theta_f$ is $T$-monic if and only if $D[f]$ is $T$-monic. Therefore, by Lemma \ref{Lemma: Timmersion if and only if thetaf monic}, $f$ is a $T$-immersion if and only if $D^n[f]$ is monic for every $n \in \mathbb{N}$. In particular, if $f$ is linear then $f$ is a $T$-immersion if and only if $f$ is monic.
\end{example}

\subsection{Immersions and Unramification}
We now show that $T$-immersions are $T$-unramified morphisms in any tangent category, meaning that being a $T$-immersion forces a complete lack of ramification in the map $f$. 

\begin{proposition}\label{Prop: Immersion Unramified}
In a tangent category $(\Cscr,\Tbb)$, if $f:X \to Y$ is a $T$-immersion then $f$ is also $T$-unramified.
\end{proposition}

\begin{proof}
Assume that we have a cone
\[
\begin{tikzcd}
C \ar[r]{}{\beta} \ar[d, swap]{}{\alpha} & Y \ar[d]{}{0_Y} \\
TX \ar[r, swap]{}{Tf} & TY
\end{tikzcd}
\]
and note that if we can show that $(C,\alpha,\beta)$ factors through $(X,0_X,f)$ then because $0_X$ is a section (and hence monic), it will follow immediately that $(X,0_X,f)$ is the terminal cone over $TX \xrightarrow{Tf} TY \xleftarrow{0_Y} Y$. To this end we compute that
\[
f \circ p_X \circ \alpha = p_Y \circ Tf \circ \alpha = p_Y  \circ 0_Y \circ \beta = \beta
\]
so the diagram
\[
\begin{tikzcd}
C \ar[r]{}{0_Y \circ \beta} \ar[d, swap]{}{p_X \circ \alpha} & TY \ar[d]{}{p_Y} \\
X \ar[r, swap]{}{f} & Y
\end{tikzcd}
\]
commutes. But now consider the diagram:
\[
\begin{tikzcd}
 & C \ar[ddr, bend left = 60]{}{0_Y \circ \beta} \ar[ddl, swap, bend right = 60]{}{p_X \circ \alpha} \ar[d, shift left = 0.5]{}{\alpha} \ar[d, shift right = 0.5, swap]{}{0_X \circ p_X \circ \alpha}  \\
 & TX \ar[dr]{}{Tf} \ar[dl, swap]{}{p_X} \\
X \ar[dr, swap]{}{f} & & TY \ar[dl]{}{p_Y} \\
 & Y
\end{tikzcd}
\]
To see it commutes, we compute that:
\begin{align*}
 T(f) \circ \alpha &= 0_Y \circ \beta, \\
 p_X \circ \alpha &= p_X \circ 0_X \circ p_X \circ \alpha, \\
 T(f) \circ 0_X \circ p_X \circ \alpha &= 0_Y \circ f \circ p_X \circ \alpha = 0_Y \circ p_Y \circ 0_Y \circ \beta = 0_Y \circ \beta.
\end{align*}
As such $(C, p_X \circ \alpha, 0_Y \circ \beta)$ is a cone over $X \xrightarrow{f} Y \xleftarrow{p_Y} TY$ with cone maps $\alpha, 0_X \circ p_X \circ \alpha:C \to TX$. Because the naturality square for $p$ at $f$ is a prepullback, $\alpha = 0_X \circ p_X \circ \alpha$ and so the diagram
\[
\begin{tikzcd}
C \ar[drr, bend left = 20]{}{\beta} \ar[ddr, swap, bend right = 20]{}{p_X \circ \alpha} \ar[dr, dashed]{}{p_X \circ \alpha} \\
 & X \ar[r]{}{f} \ar[d, swap]{}{0_X} & Y \ar[d]{}{0_Y} \\
 & TX \ar[r, swap]{}{Tf} & TY
\end{tikzcd}
\]
commutes. Finally that all powers $T^m$ preserve these pullbacks follows mutatis mutandis by recognizing that since $T^m$ preserves the prepullback giving the $T$-immersive structure on $f$, we can argue as above after applying $T^m$ to the zero naturality square.
\end{proof}


We can use Theorem \ref{Thm: ZeroCarrable makes relative bundle a kernel in DBun} above to show that when each $\DBun(X)$ is enriched in the category $\mathbf{Ab}$ of Abelian groups, then $\theta_f$ is monic if and only if $T_{X/Y} \cong 0$. This gives an alternative way to characterize $T$-immersions in $p$-carrable Rosick{\'y} tangent categories as exactly the $T$-unramified maps. To prove this we recall the following well-known characterization of maps with trivial kernels coinciding with monics in $\mathbf{Ab}$-enriched categories with zero objects. We present a sketch of the lemma for the sake of completeness.

\begin{lemma}\label{Lemma: The homological algebra characcterization of trivial kernels in additive categories}
Let $\Ascr$ be a $\mathbf{Ab}$-enriched category with a zero object. The following are equivalent for a morphism $f:X \to Y$:
\begin{enumerate}[{\em (i)}]
    \item The map $f$ is monic.
    \item For any map $g:Z \to X$, $f \circ g = 0$ if and only if $g = 0$.
    \item The equalizer $\operatorname{Eq}(f,0_{XY}:X \to Y)$ satisfies $\operatorname{Eq}(f,0_{XY}) \cong 0$.
\end{enumerate}
\end{lemma}
\begin{proof} For $(i) \implies (ii)$: If $f$ is monic then the equation $f \circ 0 = 0 = f \circ g$ implies that $g = 0$. For $(ii) \implies (iii)$: if there is a map making
\[
\begin{tikzcd}
Z \ar[r]{}{g} & X \ar[r, shift left = 1]{}{f} \ar[r, shift right = 1, swap]{}{0_{XY}} & Y
\end{tikzcd}
\]
commute if and only if $g$ is the zero map, then such a $g$ uniquely factors through the diagram:
\[
\begin{tikzcd}
Z \ar[rr]{}{g} \ar[dr, swap]{}{\bang_Z} & & X \\
 & 0 \ar[ur, swap]{}{\gnab_X}
\end{tikzcd}
\]
Thus $\operatorname{Eq}(f,0_{XY}) \cong 0$. Lastly for $(iii) \implies (i)$: assume for some $g, h:Z \to X$ that the diagram
\[
\begin{tikzcd}
Z \ar[r, shift left = 1]{}{g} \ar[r, swap, shift right = 1]{}{h} & X \ar[r]{}{f} & Y
\end{tikzcd}
\]
and note that we have that $f \circ g = f \circ h$. Then $f \circ (g-h) = f \circ g - f \circ h = 0$ and so $g - h$ must factor through $\operatorname{Eq}(f,0_{XY})$. However, as $\operatorname{Eq}(f,0) \cong 0$ this implies that $g-h = 0_{ZX}$ and so that $g = h$.
\end{proof}

\begin{theorem}\label{Thm: Rosckiy Timmersion iff Tunramified}
In a Rosick{\'y} tangent category $(\Cscr,\Tbb)$, if $f: X \to Y$ is $p$-carrable, then $f:X \to Y$ is a $T$-immersion if and only if $f$ is $T$-unramified.
\end{theorem}
\begin{proof}
Because $(\Cscr,\Tbb)$ is a Rosick{\'y} tangent category, for every object $X \in \Cscr_0$ the category $\DBun(X)$ has a zero object and is $\mathbf{Ab}$-enriched. From here the theorem follows by combining Theorem \ref{Thm: ZeroCarrable makes relative bundle a kernel in DBun} and Lemma \ref{Lemma: The homological algebra characcterization of trivial kernels in additive categories}.
\end{proof}

While every $T$-immersion is $T$-unramified, the converse is not necessarily true in an arbitrary tangent category. By Theorem \ref{Thm: Rosckiy Timmersion iff Tunramified} this distinction may be detected only by non-Rosick{\'y} tangent categories. We conclude this section with an example of a tangent category that has a $T$-unramified map that is not a $T$-immersion. 

\begin{example} $\mathbf{CMon}$ is a CDC where every map is linear, so $D[f](x,y) = f(y)$. As such, per the explanation in Example \ref{Example: T monics for CDC}, $f:M \to N$ is a $T$-immersion if and only if $f$ is monic, which in $\mathbf{CMon}$ means that $f$ is injective. On the other hand, by Example \ref{Example: Tunramified in CDC}, $f$ is $T$-unramified if and only if $\operatorname{Ker}(f) \cong 0$. So to give an example of a $T$-unramified map that is not a $T$-immersion, we need to give an example of a monoid morphism whose kernel is zero but that is not injective. So consider the addition on the natural numbers $\operatorname{add}_{\N}:\N \oplus \N \to \N$. Note $\operatorname{Ker}(\operatorname{add}_{\N})=0$; however $\operatorname{add}_{\N}$ is not injective since, for example, $\operatorname{add}_{\N}(2,3) = 2+3 = 5 = 3+2 = \operatorname{add}_{\N}(3,2).$ Thus $\operatorname{add}_{\N}$ is $T$-unramified but not a $T$-immersion. 
\end{example}


\section{Tangent-Submersions}

We now study the dual property of a map being an immersion, that is, being a submersion. Submersions are a very important class of maps in both differential geometry and tangent category theory because they 
satisfy many remarkable and useful properties. For instance, geometrically the submersions in $\SMan$ encapsulate exactly the smooth morphism $f:X \to Y$ which meet \emph{all} maps $g$ in the maximal sieve $\SMan(-,Y)$ transversely. Categorically, the submersions in $\SMan$ are precisely the $T$-display morphisms\footnote{Those maps which admit pullbacks against arbitarary morphismas and for which those pullbacks are preserved by all powers of the tangent functor.} in the sense of \cite[Theorem 2.31]{GeoffMarcelloTSubmersionPaper}. Finally, in an application of categorical reasoning to differential geometry, defining what it means to be a Lie groupoid also requires the use of surjective submersions: a Lie groupoid is a groupoid $\Gbb$ internal to $\SMan$ for which the source and target maps are surjective submersions.

Alternatively to working in differential geometry, we will see below in algebraic contexts that meeting arbitrary maps in maximally transverse ways is much more subtle than the concept initially indicates. In $\CAlg{R}$ for a commutative rig $R$ we will find that $f:A \to B$ is a submersion precisely when it is surjective with a linear section. Additionally, when given a commutative rig $R$ and a map $f:A \to B$ in $\CAlg{R}$, in $\CAlg{R}^{\op}$ we will see that $f$ is  a submersion precisely when $\Kah{B}{R}$ is a split extension of $\Kah{B}{A}$ by $\Kah{A}{R} \otimes_A B$ in $\Mod{B}$. When $R$ is a commutative ring, this is related to studying when the map $f$ is formally smooth relative to $R$. What is common to all perspectives, however, is that submersions arise from weak pullbacks in each respective tangent category.

\subsection{Weak Pullbacks and Submersions}

In the general case we study submersions following the paths laid down by \cite{BenVectorBundles}, \cite{JonathanThesis}, and \cite{GeoffMarcelloTSubmersionPaper}: submersions are maps for which the projection naturality square is a weak pullback which is preserved by all powers of the tangent bundle functor. To this end we will proceed by first recalling what it means to be a weak pullback. In a category $\Cscr$, a square 
\[
\begin{tikzcd}
X \ar[r]{}{f} \ar[d, swap]{}{g} & Y \ar[d]{}{h} \\
Z \ar[r, swap]{}{k} & W
\end{tikzcd}
\]
is a \emph{weak pullback in $\Cscr$} if for any diagram 
\[
\begin{tikzcd}
V \ar[r]{}{s} \ar[d, swap]{}{t} & Y \ar[d]{}{h} \\
Z \ar[r, swap]{}{k} & W
\end{tikzcd}
\]
there is at least one map such that the following diagram commutes: 
\[
\begin{tikzcd}
V \ar[drr, bend left = 20]{}{s} \ar[ddr, swap, bend right = 20]{}{t} \ar[dr, dashed]{}{\exists\geq 1} \\
& X \ar[r]{}{f} \ar[d, swap]{}{g} & Y \ar[d]{}{h} \\
& Z \ar[r, swap]{}{k} & W
\end{tikzcd}
\]

\begin{definition}[{\cite[Definition 9]{BenVectorBundles}}]\label{Defn: TSubmersions}
In a tangent category $(\Cscr,\Tbb)$, a map $f:X \to Y$ is a $T$-submersion if the naturality square
\[
\begin{tikzcd}
TX \ar[r]{}{Tf} \ar[d, swap]{}{p_X} & TY \ar[d]{}{p_Y} \\
X \ar[r, swap]{}{f} & Y
\end{tikzcd}
\]
is a weak pullback which is preserved by $T^m$ for all $m \in \N$.
\end{definition}

In order to prove some key facts about $T$-submersions, we will need the following folklorish result about weak pullbacks, which we prove for completeness sake. 

\begin{lemma}[Folklore]\label{Lemma: Folklore for weak pullbacks}
Consider commutative diagrams with squares numbered as below:
\[
\begin{tikzcd}
X \ar[r, ""{name = UL}]{}{k} \ar[d, swap]{}{f} & Y \ar[d]{}{g} \ar[r, ""{name = UR}]{}{\ell} & Z \ar[d]{}{h} \\
W \ar[r, swap, ""{name = DL}]{}{k^{\prime}} & V \ar[r, swap, ""{name = DR}]{}{\ell^{\prime}} & U
\ar[from = UL, to = DL, symbol = {\rotatebox[origin=c]{90}{$(1)$}}]
\ar[from = UR, to = DR, symbol = {\rotatebox[origin=c]{90}{$(2)$}}]
\end{tikzcd}
\qquad
\begin{tikzcd}
X \ar[r, ""{name = U}]{}{\ell \circ k} \ar[d, swap]{}{f} & Z \ar[d]{}{h} \\
W \ar[r, swap, ""{name = D}]{}{\ell^{\prime} \circ k^{\prime}} & U
\ar[from = U, to = D, symbol = {\rotatebox[origin=c]{90}{$(3)$}}]
\end{tikzcd}
\]
Then:
\begin{enumerate}[{\em (i)}]
    \item If Squares $(1)$ and $(2)$ are weak pullbacks then so too is Square $(3)$.
    \item If Square $(3)$ is a weak pullback and if Square $(2)$ is a prepullback then Square $(1)$ is a weak pullback.
\end{enumerate}
In particular, if Square $(2)$ is a pullback then Square $(1)$ is a weak pullback if and only if Square $(3)$ is a weak pullback.
\end{lemma}
\begin{proof}
Note that the final statement of the lemma follows by combining both $(i)$ and $(ii)$ together with the fact that pullbacks are both weak pullbacks and prepullbacks. As such, it suffices to prove $(i)$ and $(ii)$ to prove the lemma. We first prove $(i)$. Assume that we have a commuting diagram
\[
\begin{tikzcd}
P \ar[r]{}{s} \ar[d, swap]{}{t} & Z \ar[d]{}{h} \\
W \ar[r, swap]{}{\ell^{\prime} \circ k^{\prime}} & U
\end{tikzcd}
\]
and note that this implies that in particular we obtain a commuting diagram with a lift $\lambda$
\[
\begin{tikzcd}
V \ar[drr, bend left = 20]{}{s} \ar[ddr, swap, bend right = 20]{}{k^{\prime} \circ t} \ar[dr]{}{\lambda} \\
& Y \ar[r]{}{\ell} \ar[d, swap]{}{g} & Z \ar[d]{}{h} \\
& V \ar[r, swap]{}{\ell^{\prime}} & U
\end{tikzcd}
\]
by virtue of Square $(2)$ being a weak pullback. But then since $g \circ \lambda = k^{\prime} \circ t$, the fact that Square $(1)$ is a weak pullback allows us to produce a map $\rho:P \to X$ through which $\lambda$ and $t$ are factored by $k$ and $f$, respectively. A straightforward check shows that $\rho$ renders the entire diagram
\[
\begin{tikzcd}
P \ar[d, swap]{}{\rho} \ar[dd, bend right = 40, swap]{}{t} \ar[dr]{}{\lambda} \ar[drr, bend left = 20]{}{s} \\
X \ar[r]{}{k} \ar[d, swap]{}{f} & Y \ar[d]{}{g} \ar[r]{}{\ell} & Z \ar[d]{}{h} \\
W \ar[r, swap]{}{k^{\prime}} & V \ar[r, swap]{}{\ell^{\prime}} & U
\end{tikzcd}
\]
commutative. Because the outer edges exactly compose to the initial cone above Square $(3)$, this shows that Squre $(3)$ is a weak pullback.

Now for $(ii)$, assume that we have a commuting diagram
\[
\begin{tikzcd}
P \ar[r]{}{s} \ar[d, swap]{}{t} & Y \ar[d]{}{g} \\
W \ar[r, swap]{}{k^{\prime}} & V
\end{tikzcd}
\]
and note that by post-composing this with Square $(2)$ we get a commuting diagram
\[
\begin{tikzcd}
P \ar[drr, bend left = 20]{}{\ell \circ s} \ar[ddr, swap, bend right = 20]{}{t} \ar[dr, dashed]{}{\exists\,\lambda} & & \\
 & X \ar[r]{}{\ell \circ k} \ar[d, swap]{}{f} & Z \ar[d]{}{h} \\
 & W \ar[r, swap]{}{\ell^{\prime} \circ k^{\prime}} & U
\end{tikzcd}
\]
where $\lambda$ exists precisely because Square $(3)$ is a weak pullback. Since $f \circ \lambda = t$, we also have that $g \circ k \circ \lambda = k^{\prime} \circ f \circ \lambda = k^{\prime} \circ t$. Similarly, by the assumption $g \circ s = k^{\prime} \circ t$, we see that the diagram
\[
\begin{tikzcd}
P \ar[drr, bend left = 20]{}{\ell \circ s} \ar[ddr, swap, bend right = 20]{}{t} \ar[dr, shift left = 1]{}{k \circ \lambda} \ar[dr, swap, shift right = 1]{}{s}& & \\
 & Y \ar[r]{}{\ell} \ar[d, swap]{}{g} & Z \ar[d]{}{h} \\
 & v \ar[r, swap]{}{\ell^{\prime}} & U
\end{tikzcd}
\]
commutes with both presented lifts $s$ and $k \circ \lambda$. However, because Square $(2)$ is a  prepullback, we must have that $k \circ \lambda = s$ and so that the diagram
\[
\begin{tikzcd}
P \ar[drr, bend left = 20]{}{s} \ar[ddr, swap, bend right = 20]{}{t} \ar[dr]{}{\lambda} & & \\
 & X \ar[r]{}{k} \ar[d, swap]{}{f} & Y \ar[d]{}{g} \\
 & W \ar[r, swap]{}{k^{\prime}} & V
\end{tikzcd}
\]
commutes. Thus Square $(1)$ is a weak pullback.
\end{proof}

\begin{proposition}\label{Prop: Tsubmersions and stability properties}
In a tangent category $(\Cscr,\Tbb)$, let $f:X \to Y$ be a $T$-submersion. Then:
\begin{enumerate}[{\em (i)}] 
    \item If $g:Y \to Z$ is a $T$-sumbersion then $g \circ f:X \to Z$ is a $T$-submersion.
    \item If $m \in \N$ then $T^mf$ is a $T$-submersion.
    \item Assume $g:Z \to Y$ is an arbitrary map for which the pullback
    \[
    \begin{tikzcd}
    W \ar[r]{}{\pi_1} \ar[d, swap]{}{\pi_0} & Z \ar[d]{}{g} \\
    X \ar[r, swap]{}{f} & Y
    \end{tikzcd}
    \]
    exists and is preserved by $T^m$ for all $m \in \N$. Then $\pi_1$ is a $T$-submersion.
\end{enumerate}
\end{proposition}
\begin{proof} Starting with $(i)$, note that for all $m \in \N$ in the diagram
\[
\begin{tikzcd}
T^{m+1}X \ar[rr]{}{T^{m+1}f} \ar[d, swap]{}{(T^m \ast p)_X} & & T^{m+1}Y \ar[rr]{}{T^{m+1}g} \ar[d]{}{(T^m \ast p)_Y} & & T^{m+1}Z \ar[d]{}{(T^m \ast p)_Z} \\
T^mX \ar[rr, swap]{}{T^mf} & & T^mY \ar[rr,  swap]{}{T^mg} & & T^mZ
\end{tikzcd}
\]
appealing to Lemma \ref{Lemma: Folklore for weak pullbacks}.(i) gives the result because both the left-and-right-handed squares are weak pullbacks by assumption. For $(ii)$, observe that this is immediate (but tedious to verify) from the fact that each functor $T^m$ preserves the weak pullbacks defining what it means to be a $T$-submersion, using that we get various natural isomorphisms $T^{m+k} \ast p \cong T^{k} \ast \left(T^m \ast p\right) \cong T^k \ast \left(p \ast T^m\right)$ for all $k \in \N$ by appropriately whiskering the powers of the tangent functors by various (whiskered) canonical flips, and using that being a weak pullback is stable under isomorphism. For $(iii)$, consider that by the final statement of Lemma \ref{Lemma: Folklore for weak pullbacks}, in the diagram
\[
\begin{tikzcd}
TW \ar[r, ""{name = UL}]{}{p_W} \ar[d, swap]{}{T\pi_1} & W \ar[d]{}{\pi_1} \ar[r, ""{name = UR}]{}{\pi_0} & X \ar[d]{}{f} \\
TZ \ar[r, swap, ""{name = DL}]{}{p_Z} & Z \ar[r, swap, ""{name = DR}]{}{g} & Y
\ar[from = UL, to = DL, symbol = {\rotatebox[origin=c]{90}{$(1)$}}]
\end{tikzcd}
\]
Square $(1)$ is a weak pullback if and only if the total square is a weak pullback. However, as the total square is equal to the commuting diagram
\[
\begin{tikzcd}
TW \ar[r]{}{T\pi_0} \ar[d, swap]{}{T\pi_1} & TX \ar[r]{}{p_X} \ar[d]{}{Tf} & X \ar[d]{}{f} \\
TZ \ar[r, swap]{}{Tg} & TY \ar[r, swap]{}{p_Y} & Y
\end{tikzcd}
\]
it suffices to prove that this rectangle is a weak pullback. To this end assume we have a commuting square
\[
\begin{tikzcd}
U \ar[r]{}{s} \ar[d, swap]{}{t} & TZ \ar[d]{}{p_Y \circ Tg} \\
X \ar[r, swap]{}{f} & Y
\end{tikzcd}
\]
and note that by reorganizing our composition we get a commuting diagram
\[
\begin{tikzcd}
U \ar[drr, bend left = 20]{}{Tg \circ s} \ar[ddr, swap, bend right = 20]{}{t} \ar[dr, dashed]{}{\exists\,\gamma} \\
 & TX \ar[r]{}{Tf} \ar[d, swap]{}{p_X} & TY \ar[d]{}{p_Y} \\
 & X \ar[r, swap]{}{f} & Y
\end{tikzcd}
\]
with the existence of $\gamma$ justified by the fact that the naturality square of $p$ at $f$ is a weak pullback. But then because $TW$ is a pullback of $Tf$ against $Tg$, we see that there is a unique morphism $\theta:U \to TW$ rendering the diagram
\[
\begin{tikzcd}
U \ar[drr, bend left = 20]{}{s} \ar[ddr, swap, bend right = 20]{}{\gamma} \ar[dr, dashed]{}{\exists!\theta} \\
 & TW \ar[r]{}{T\pi_1} \ar[d, swap]{}{T\pi_0} & TZ \ar[d]{}{Tg} \\
 & TX \ar[r, swap]{}{Tf} & TY
\end{tikzcd}
\]
commutative. This then implies that the diagram
\[
\begin{tikzcd}
U \ar[drr, bend left = 20]{}{s} \ar[ddr, swap, bend right = 20]{}{t} \ar[dr, dashed]{}{\exists\,\theta} \\
 & TW \ar[r]{}{T\pi_1} \ar[d]{}{p_X \circ T\pi_0} & TZ \ar[d]{}{p_Y \circ Tg} \\
 & X \ar[r, swap]{}{f} & Y
\end{tikzcd}
\]
commutes and so that the whole diagram is a weak pullback. Appealing again to the final statement of Lemma \ref{Lemma: Folklore for weak pullbacks} we get that the square
\[
\begin{tikzcd}
TW \ar[r]{}{T\pi_1} \ar[d, swap]{}{p_W} & TZ \ar[d]{}{p_Z} \\
W \ar[r, swap]{}{\pi_1} & Z
\end{tikzcd}
\]
is a weak pullback. Running this same argument for all $m \in \N$ and using that the powers of the tangent functor $T^m$ preserve every structure weak pullback and pullback in sight allows us to conclude that $\pi_1$ is a $T$-submersion.
\end{proof}

As we can see in Definition \ref{Defn: TSubmersions} above, $T$-submersions are defined in more general situations than when the horizontal descent $\theta_f$ is necessarily defined. This is not an issue in practice because conventional practice favours working with display $T$-submersions, such as in \cite[Proposition 2]{BenVectorBundles} and \cite[Proposition 2.28]{GeoffMarcelloTSubmersionPaper} for instance. In order to relate $T$-submersions to the horizontal descent $\theta_f$, we need to assume that the map $f:X \to Y$ is $p$-carrable. In this situation we find that a map is a $T$-submersion if and only if its horizontal descent admits a section. 

\begin{proposition}\label{Prop: The lifting property characterization of TSmooth}
In a tangent category $(\Cscr,\Tbb)$, if $f: X \to Y$ is $p$-carrable morphism, then $f$ is a $T$-submersion if and only if $\theta_f$ admits a section.
\end{proposition}
\begin{proof}
$\implies$: Assume that $f$ is a $T$-submersion. Because the pullback projections from $f^{\ast}(TY)$ form a cone over the cospan $X \xrightarrow{f} Y \xleftarrow{p_Y} TY$, there is a map $s$ making the diagram
\[
\begin{tikzcd}
f^{\ast}(TY) \ar[dr, dashed]{}{\exists\,s} \ar[drr, bend left = 20]{}{\pr_1} \ar[ddr, swap, bend right = 20]{}{\pr_0} & & \\
 & TX \ar[r]{}{Tf} \ar[d, swap]{}{p_X} & TY \ar[d]{}{p_Y} \\
 & X \ar[r, swap]{}{f} & Y
\end{tikzcd}
\]
commute. Because $s$ is a cone morphism and $f^{\ast}(TY)$ is the terminal object in the category of cones, $\theta_f \circ s = \id$. So $\theta_f$ admits a section as desired. 

$\impliedby:$ Assume that $s:f^{\ast}(TY) \to TX$ is a section of $\theta_f$, i.e., $s$ is a map making
\[
\begin{tikzcd}
f^{\ast}(TY) \ar[dr, equals] \ar[r]{}{s} & TX \ar[d]{}{\theta_f} \\
 & f^{\ast}(TY)
\end{tikzcd}
\]
commute. Then to see that the naturality square for $p$ is a weak pullback define $t:Z \to TX$ by the formula $t := s \circ \gamma$. To see this defines a morphism of cones, consider that since we have the commuting diagrams
\[
\begin{tikzcd}
Z \ar[dr]{}{\gamma} \ar[drr, bend left = 20]{}{g} \ar[ddr, bend right = 20, swap]{}{h} \\
 & f^{\ast}(TY) \ar[r]{}{\pr_1} \ar[d, swap]{}{\pr_0} & TY \ar[d]{}{p_Y} \\
 & X \ar[r, swap]{}{f} & Y
\end{tikzcd}\quad
\begin{tikzcd}
TX \ar[dr]{}{\theta_f} \ar[drr, bend left = 20]{}{Tf} \ar[ddr, bend right = 20, swap]{}{p_X} \\
 & f^{\ast}(TY) \ar[r]{}{\pr_1} \ar[d, swap]{}{\pr_0} & TY \ar[d]{}{p_Y} \\
 & X \ar[r, swap]{}{f} & Y
\end{tikzcd}
\]
then
\[
p_X \circ t = p_X \circ s \circ \gamma = p_X \circ s \circ \gamma = \pr_0 \circ \gamma = h
\]
and
\[
Tf \circ t = Tf \circ s \circ \gamma = \pr_1 \circ \theta_f \circ s \circ \gamma = \pr_1 \circ \gamma = g,
\]
so $t$ is indeed a cone morphism. Finally we compute that
\[
\theta_f \circ t = \theta_f \circ s \circ \gamma = \gamma,
\]
so there is indeed a factorization of $\gamma$ through $TX$. In particular, this shows that the naturality square for $p$ at $f$ is a weak pullback. We now verify that for arbitrary $m \in \N$, the naturality square
\[
\begin{tikzcd}
    T^{m+1}X \ar[r]{}{T^{m+1}f} \ar[d, swap]{}{(T^{m} \ast p)_X} & T^{m+1}Y \ar[d]{}{(T^m \ast p)_Y} \\
    T^mX \ar[r, swap]{}{T^mf} & T^mY
\end{tikzcd}
\]
is a weak pullback. However, because this is given by applying $T^m$ to the naturality square for $f$ at $p$ and because $T^m$ preserves the pullback $f^{\ast}(TY)$, $T^m(s)$ is a section for $T^m(\theta_f)$ because split idempotents are absolute  coequalizers. Appealing to Corollary \ref{Cor: The other higher powers of T to thetaf in one line} and writing $\theta_{T^mf} = \tilde{C}_m \circ T^m\theta_f \circ C_m$, defining $s_{T^ms} := C_m^{-1} \circ T^ms \circ \tilde{C}_m^{-1}$ gives that
\[
\theta_{T^mf} \circ s_{T^mf} = \tilde{C}_m \circ T^m\theta_f \circ C_m \circ C_m^{-1} \circ T^ms \circ \tilde{C}_m^{-1} = \tilde{C}_m \circ T^m(\theta_f \circ s) \circ \tilde{C}_m^{-1} = \tilde{C}_m \circ \tilde{C}_m^{-1} = \id.
\]
Thus each such square is a weak pullback.
\end{proof}

We now present $T$-submersions in our main examples. Note that because classifying $T$-submersions in affine schemes is quite involved and subtle, it will involve a nontrivial digression from the abstract development of $T$-submersions, and thus have seperated this out into its own subsection below.

\begin{example}\label{Example: TSubmersion in SMan}
In $\SMan$, the $T$-submersions are precisely the submersions in the usual sense (when we have access to the Axiom of Choice). To see this, note that since $\theta_f$ is linear as a morphism of differential bundles, $\theta_f$ is stalkwise a linear map of vector spaces. Observe also that $\theta_f$ is stalkwise epimorphic in the category of $\R$-vector spaces and so stalkwise given by surjections of vector spaces. Finally, from the fact that the Abelian category $\mathbb{R}\mathbf{Vect}$ is semisimple (under the Axiom of Choice) and every epimorphism of real vector spaces splits, we can stalkwise define a linear section $s_x:T_{f(x)}Y \to T_xX$ of $\theta_{f,x}$ for all $x \in X$. Recall from Example \ref{Example: What  is thetaf in SMan} that $\theta_f\left(x,\overrightarrow{v}\right) = \left(x,D[f](x)\cdot \overrightarrow{v}\right)$ for all tangent vectors $(x,\overrightarrow{v})$. We can then lift the sections $s_x$ to a map $\tilde{s}:X \times_Y TY \to TX$ by noting that since $p_Y:TY \to Y$ is a submersion, the pullback $f^{\ast}(TY)$ is calculated by $X \times_Y TY = \left\lbrace \left(x, \left(y,\overrightarrow{w}\right)\right) \in X \times TY \; | \; y = f(x) \right\rbrace \cong \coprod_{x \in X} T_{f(x)}Y$. Since each map $s_x:T_{f(x)}Y \to T_xX$ is monic and each pair $(y,\overrightarrow{w})$ arising as the $TY$-coordinate in $X \times_Y TY$ has the property that $y = f(x)$ for some $x$, we get $\tilde{s}$ as the unique map fitting into the coproduct diagram:
\[
\begin{tikzcd}
X \times_{Y} TY \ar[r]{}{\tilde{s}} & TX \\
T_{f(x)}Y \ar[u] \ar[ur, swap]{}{s_{x}}
\end{tikzcd}
\]
That this is a section is immediate to verify and that it is linear follows from the fact that each stalk $s_x$ is linear.
\end{example}

\begin{example}\label{Example: Tsubmersion in CAlgR}
Let $R$ be a commutative rig. In $\CAlg{R}$ the $T$-submersions are precisely the surjections $f:A \to B$ with a linear section. To see this recall that given the naturality square
\[
\begin{tikzcd}
A[\epsilon] \ar[d, swap]{}{p_A} \ar[r]{}{f[\epsilon]} & B [\epsilon] \ar[d]{}{p_B} \\
A \ar[r, swap]{}{f} & B
\end{tikzcd}
\]
the pullback $A \times_B B[\epsilon] \cong A \ltimes B$ with the map $\theta_f:A[\epsilon] \to A \ltimes B$ given by $\theta_f(a+x\epsilon) = (a,f(x))$. Now observe that any map $\sigma:A \ltimes B \to A[\epsilon]$ takes the form $\sigma(r,s) = \sigma_0(r,s) + \sigma_1(r,s)\epsilon$ for some maps $\sigma_0, \sigma_1:A \ltimes B \to A$. Thus if there is a $\sigma$ rendering the diagram
\[
\begin{tikzcd}
A \ltimes B \ar[r]{}{\sigma} \ar[dr, equals] & A[\epsilon] \ar[d]{}{\theta_f} \\
 & A \ltimes B
\end{tikzcd}
\]
commutative then we have that $\id_{A \ltimes B} = \theta_f \circ \sigma$. This allows us to deduce:
\begin{prooftree}
    \AxiomC{$\id_{A \ltimes B} = \theta_f \circ \sigma$}
    \UnaryInfC{$\forall\,(a,b) \in A \ltimes B.\,(a,b) = \theta_f(\sigma_0(a,b)+\sigma_1(a,b)\epsilon) = (\sigma_0(a,b),f(\sigma_1(a,b)))$}
    \UnaryInfC{$a = \sigma_0(a,b)$ and $b = f(\sigma_1(a,b))$.}
\end{prooftree}
Thus it must be the case that for every $b$ there is an $x \in A$ (namely $x = \sigma_1(a,b)$) for which $f(x) = b$. This implies in particular that $f$ is surjective. We now show that $\sigma_1$ must be a derivation. Note that since $\sigma$ is a rig morphism, we deduce:
\begin{prooftree}
 \AxiomC{$\forall\,(a,b), (x,y) \in A \ltimes B.\, \sigma(a,b) + \sigma(x,y)  = \sigma((a,b) + (x,y)) = \sigma(a+x, b+y)$}
 \UnaryInfC{$\sigma_0(a+x, b+y) = \sigma_0(a,b) + \sigma_0(x,y)$ and $\sigma_1(a,b) + \sigma_1(x,y) = \sigma_1(a+x, b+y)$}
\end{prooftree}
Thus $\sigma_1((a,b)+(x,y)) = \sigma_1(a,b) + \sigma_1(x,y)$ and in particular $\sigma_1(0,0) = 0$, showing that is additive. Additionally because $\sigma$ is a rig morphism we deduce:
\begin{prooftree}
 \AxiomC{$\forall\,(a,b), (x,y) \in A \ltimes B.\, \sigma(a,b)\sigma(x,y)  = \sigma((a,b)(x,y))$}
 \UnaryInfC{$(\sigma_0(a,b)+\sigma_1(a,b)\epsilon)(\sigma_0(x,y)+\sigma_1(x,y)\epsilon)) = \sigma(ax,f(a)y + bf(x))$}
 \UnaryInfC{$\sigma_0(a,b)\sigma_1(x,y) +\sigma_1(a,b)\sigma_0(x,y) = \sigma_1(ax,f(a)y+bf(x))$}
\end{prooftree}
Finally, because rig morphisms preserve multiplicative units, we also deduce:
\begin{prooftree}
    \AxiomC{$\sigma(1,0) = 1_{A[\epsilon]}$}
    \UnaryInfC{$1 + 0 \epsilon = \sigma(1,0) = \sigma_0(1,0) + \sigma_1(1,0)\epsilon$}
    \UnaryInfC{$\sigma_1(1,0) = 0$}
\end{prooftree}
This in particular shows that $\sigma_1:A \ltimes B \to A$ is a derivation. Furthermore, consider the map $s:B \to A$ defined via the composition
\[
\begin{tikzcd}
B \ar[rr]{}{b \mapsto (0,b)} \ar[rr, swap]{}{\operatorname{incl}} \ar[drr, swap]{}{s} & & A \ltimes B \ar[d]{}{\sigma_1} \\
 & & A
\end{tikzcd}
\]
of $A$-modules; note that the map $b \mapsto (0,b)$ is a map of $A$-modules because for all $a \in A$ and for all $b \in B$
\[
a \bullet (0,b) = (a,0)(0,b) = (a\cdot 0, f(a)b + 0^2) = (0,a\bullet b).
\]
We compute that for all $b \in B$ on one hand
\begin{align*}
(\theta_f \circ s)(b) = \big(\theta_f \circ \sigma\big)(\operatorname{incl}(b)) = \operatorname{incl}(b) = (0,b)
\end{align*}
while on the other hand
\begin{align*}
(\theta_f \circ s)(b) = \theta_f\big(\sigma(\operatorname{incl}(b))\big) = \theta_f\big(\sigma_1(0,b)\epsilon\big) = \theta_f\big(0+\sigma_1(0,b)\epsilon\big) =  \bigg(0,f\big(\sigma_1(0,b)\big)\bigg) = \bigg(0,f\big(s(b)\big)\bigg).
\end{align*}
Thus we conclude, by comparing $B$-coordinates, that $f(s(b)) = b$ and so that $s:B \to A$ is a linear section of $A$.
\end{example}


\begin{example}\label{Example: TSubmersion CDC}
In a CDC, for a map $f: X \to Y$, because $\theta_f = \langle \pi_0, D[f]\rangle$, we get that any section $s:f^{\ast}(TY) \to TX$ has the form:
\[
\begin{tikzcd}
X \times Y \ar[drr, equals] \ar[rr]{}{\langle s_0, s_1 \rangle} & & X \times X \ar[d]{}{\langle \pi_0, D[f]\rangle} \\
& & X \times Y
\end{tikzcd}
\]
This tells us immediately that $s_0 = \id_X$. It also tells us that $D[f] \circ s_1 = \id_Y$ and so shows that it is necessary and sufficient for $D[f]$ to be a retract. In particular, if $f$ is linear and hence $\theta_f = \id_X \times f$, then $f$ is a $T$-submersion if and only if $f$ is a retract.
\end{example}

\subsection{Submersions in Algebraic Geometry}\label{Subsection: TSubmersions in Algebraic Geometry}
In order to classify the $T$-submersions in the categories $\CAlg{R}^{\op}$ (and more generally in $\Sch_{/S}$ for a base scheme $S$) we need to recall what it means for a morphism $f:A \to B$ of commutative rings to be formally smooth. We also need to recall a weaker and less-well-known notion of formal smoothness which commutative rings can satisfy developed in \cite{EGA04}. This is a notion which defines when a commutative algebra morphism $g:A \to B$ is formally smooth relative to a base ring $R$; it is a relatively weak definition and, despite the way the term ``relative to $(-)$'' is used in all of EGA and SGA, \emph{not} the same thing as $g:A \to B$ being formally smooth in $\CAlg{R}$.

\begin{definition}[{\cite[D{\'e}finition 19.3.1]{EGA04}}]\label{Defn: Formally Smooth}
Lef $f:A \to B$ be a morphism of commutative rings. We say that $f$ is \emph{formally smooth} if $f$ satisfies the weak left lifting property against nilpotent ideal quotient maps. That is, given any commutative square
\[
\begin{tikzcd}
A \ar[r]{}{\alpha} \ar[d, swap]{}{f} & C \ar[d]{}{\pi_{I}} \\
B \ar[r, swap]{}{\beta} & \frac{C}{I}
\end{tikzcd}
\]
with $I \trianglelefteq C$ a nilpotent ideal, there exists a ring map $\ell:B \to C$ making the diagram
\[
\begin{tikzcd}
A \ar[r]{}{\alpha} \ar[d, swap]{}{f} & C \ar[d]{}{\pi_{I}} \\
B \ar[ur, dashed]{}{\ell} \ar[r, swap]{}{\beta} & \frac{C}{I}
\end{tikzcd}
\]
commute. If instead the diagrams and lifts above occur in the category $\CAlg{R}$ for a commutative ring $R$, then $f$ is \emph{a formally smooth map of $R$-algebras}.
\end{definition}
An important way to view formally smooth maps is in terms of their characterization by K{\"a}hler differentials via the Jacobian Criterion for Formal Smoothness. This allows one to use the splitting of the relative conormal sequence to detect formal smoothness  --- it says that a map is formally smooth if and only if the map is formally nonsingular in the sense that locally/for a choice of local coordinates the Jacobian determinants of the transformation is invertible.

\begin{theorem}[Jacobian Criterion for Formal Smoothness; {\cite[Th{\'e}or{\`e}me 22.6.1]{EGA04}, \cite[Proposition 16.12]{Eisenbud}, \cite[Proposition 10.138.8]{stacks-project}}]\label{Thm: }
Let $f:A \to B$ be a morphism of commutative rings and let $h:A \to P$ be a formally smooth $A$-algebra with a surjection $p:P \to B$ making the diagram
\[
\begin{tikzcd}
 & P \ar[dr]{}{p} \\
A \ar[rr, swap]{}{f} \ar[ur]{}{h} & & B
\end{tikzcd}
\]
commute. Then $f:A \to B$ is formally smooth (in $\CAlg{R})$ if and only if the exact sequence
\[
\begin{tikzcd}
\frac{\operatorname{Ker}(p)}{\operatorname{Ker}(p)^2} \ar[r] & \Kah{P}{A} \otimes_{P} B \ar[r] & \Kah{B}{A} \ar[r] & 0
\end{tikzcd}
\]
is split exact in $\Mod{B}$.
\end{theorem}

As we will see below, formally smooth maps relative to a base $R$ are distinct in that they are characterized not by the splitting of the conormal sequence but instead by the splitting of the cotangent sequence.

\begin{definition}[{\cite[D{\'e}finition 19.9.1]{EGA04}}]\label{Defn: Formally Smooth relative to R}
Let $R \xrightarrow{f} A \xrightarrow{g} B$ be maps of commutative rings. We say that $g:A \to B$ is a \emph{formally smooth $A$-algebra relative to $R$} if and only if for any commutative diagram
\[
\begin{tikzcd}
A \ar[r]{}{\alpha} \ar[d, swap]{}{f} & C \ar[d]{}{\pi_{I}} \\
B \ar[r, swap]{}{\beta} & \frac{C}{I}
\end{tikzcd}
\]
in $\CAlg{A}$, if there is a lift $\ell_R$ making the diagram
\[
\begin{tikzcd}
R \ar[r]{}{\alpha \circ f} \ar[d, swap]{}{g \circ f} & C \ar[d]{}{\pi_{I}} \\
B \ar[r, swap]{}{\beta} \ar[ur, dashed]{}{\ell_R} & \frac{C}{I}
\end{tikzcd}
\]
commute in $\CAlg{R}$ then there is a lift $\ell_A$ making the diagram
\[
\begin{tikzcd}
A \ar[r]{}{\alpha} \ar[d, swap]{}{f} & C \ar[d]{}{\pi_{I}} \\
B \ar[r, swap]{}{\beta} \ar[ur, dashed]{}{\ell_A} & \frac{C}{I}
\end{tikzcd}
\]
commute.
\end{definition}
The way to view formally smooth maps relative to a base is in terms of their characterization by way of the cotangent sequence. However, we will use this below to give a cautionary example showing that formally smooth morphisms relative to a base $R$ need \emph{not} be formally smooth morphisms (even in $\CAlg{R}$). It is true, however, that formally smooth maps are formally smooth relative to $R$: this follows from a straightforward check directly from definitions by reusing any given lift $\ell$ provided by the formally smooth map.
\begin{theorem}[{\cite[Th{\'e}or{\`e}me 20.5.7.ii]{EGA04}}]\label{Thm: EGA 0 4 20 5 7}
Let $R \xrightarrow{f} A \xrightarrow{g} B$ be maps of commutative rings. The map $g:A \to B$ is formally smooth relative to $R$ if and only if the relative cotangent sequence
\[
\begin{tikzcd}
\Kah{A}{R} \otimes_A B \ar[r] & \Kah{B}{R} \ar[r] & \Kah{B}{A} \ar[r] & 0
\end{tikzcd}
\]
is split exact.
\end{theorem}
\begin{example}\label{Example: Classification of TSubmersions in CAlgRop}
Let $R$ be a commutative ring. By virtue of the equivalence $\DBun(\Spec R) \simeq \Mod{R}^{\op}$ asserted by \cite{GeoffJSDiffBunComAlg}, we deduce the following chains of equivalences:
\begin{prooftree}
    \AxiomC{$\theta_f:T_{B/R} \to f^{\ast}(T_{A/R})$ has a section in $\DBun(\Spec B)$}
    \UnaryInfC{$\theta_f:\Spec(\Sym_{B}(\Kah{B}{R})) \to \Spec(\Sym_A(\Kah{A}{R})) \times_{A} \Spec B$ has a section in $\DBun(\Spec B)$}
    \UnaryInfC{$\theta_f:\Spec(\Sym_{B}(\Kah{B}{R})) \to \Spec(\Sym_B(\Kah{A}{R} \otimes_{A} B))$ has a section in $\DBun(\Spec B)$}
    \UnaryInfC{$\Kah{A}{R} \otimes_A B \to \Kah{B}{R}$ admits a retract in $\Mod{B}$}
    \UnaryInfC{$0 \to \Kah{A}{R} \otimes_A B \to \Kah{B}{R} \to \Kah{A}{B} \to 0$ is split exact in $\Mod{B}$}
\end{prooftree}
As such, invoking \cite[Th{\'e}or{\`e}me 20.5.7.ii]{EGA04} gives that $g:A \to B$ is formally smooth relative to $R$ if and only if $\Spec g:\Spec B \to \Spec A$ is a $T$-submersion in $\mathbf{AffSch}_{/R} \simeq \CAlg{R}^{\op}$.
\end{example}

\begin{example}\label{Example: Nonexample of formally smooth}
It is unfortunately not the case that $T$-submersions in $\mathbf{CAlg}_{R}^{\op}$ coincide with formally smooth morphisms of rings. To see an explicit example of this, note that for any commutative ring $R$, $\Kah{R}{R} \cong 0$ so $\Sym_{R}(\Kah{R}{R}) \cong R$ and $T_{R/R} \cong R$. In particular, for any commutative $R$-algebra $A$, the diagram
\[
\begin{tikzcd}
\Spec A \ar[r]{}{!_A} \ar[d, equals] & T_{R/R} \ar[d] \\
\Spec A \ar[r, swap]{}{!_A} & \Spec R
\end{tikzcd}
\]
is a pullback diagram. But then $!_A$ is always a $T$-submersion because the natural map $\theta_{!_A} = p_A:T_{A/R} \to \Spec A$ is a retract with linear section $0_A:\Spec A \to T_{A/R}$. As such, in particular, any non-smooth $R$-algebra $A$ is a $T$-submersion over $R$. For a very explicit example, set $R =  \Fbb_2$ and $A = \Fbb_2[x]/(x^2)$ with the evident algebra map. Then because a morphism of rings is smooth if and only if it is formally smooth and finitely presented, it suffices to check that $\Fbb_2[x]/(x^2)$ is not a formally smooth $\Fbb_2$-algebra. However, as
\[
\operatorname{Jac}\left(\frac{\Fbb_2[x]}{(x^2)}\right) = \det\begin{pmatrix}
\frac{\mathrm{d}(x^2)}{\mathrm{d} x}
\end{pmatrix} = \det(0) = 0
\]
the algebra $\Fbb_2[x]/(x^2)$ is not smooth because it violates the Jacobian Criterion.
\end{example}

Due to some technical difficulties which may be avoided by Proposition \ref{Prop: Linear sections from nonlinear sections with adjoints and units}, we defer computing the $T$-submersions in $\Sch_{/S}$ until Example \ref{Example: Submersions in Schemes} below. 

\begin{example}
If $R$ is a commutative rig instead of a commutative ring, it is still true from \cite{GeoffJSDiffBunComAlg} and Corollary \ref{Cor: Schemes and affine rig schemes are linearly submersive} below\footnote{The referenced corollary here allows us to show that in $\CAlg{R}^{\op}$, $\theta_f:TX \to f^{\ast}(TY)$ admits a section in $\Cscr_{/X}$ if and only if it admits a section in $\DBun(X)$. Note that it does not say that every section is linear, but instead that every section has a linear companion.} and the equivalence of categories $\DBun(A)^{\op} \simeq \Mod{A}$ (for all commutative $R$-algebras $A$) that for a map $f:B \to A$ in $\CAlg{R}^{\op}$, $\theta_f:T_{B/R} \to f^{\ast}(T_{A/R})$ admits a section if and only if the map of $B$-modules $\Kah{A}{R} \otimes_A B \to \Kah{B}{R}$ admits a retract $r:\Kah{B}{R} \to \Kah{A}{R} \otimes_A B$ in the category $\Mod{B}$.
\end{example}

\subsection{Linear Submersions}
Part of the reason that we have spent a great deal of time defining and studying the structure of $p$-carrable morphisms in this paper is that the horizontal descent $\theta_f:TX \to f^{\ast}(TY)$ allows us to use differntial bundles as a geometric tool with which to study how close or how far $f$ is from being a categorical local diffeomorphism. We have seen already that when studying $p$-carrable morphisms which are also $T$-submersions, we have access to a section/retraction pair
\[
\begin{tikzcd}
f^{\ast}(TY) \ar[r]{}{s} \ar[dr, equals] & TX \ar[d]{}{\theta_f} \\
 & f^{\ast}(TY)
\end{tikzcd}
\]
However, there is one major structural question which underlies $p$-carrable $T$-submersions at every corner: how linear is the section $s:f^{\ast}(TY) \to TX$? Certainly $s$ is a bundle map, as since
\[
\begin{tikzcd}
f^{\ast}(TY) \ar[r]{}{s} \ar[dr, equals] & TX \ar[d]{}{\theta_f} \\
 & f^{\ast}(TY)
\end{tikzcd}
\]
the diagram
\[
\begin{tikzcd}
 & TX \ar[dd, near start]{}{p_X} \ar[dr]{}{\theta_f} \\
f^{\ast}(TY) \ar[dr, swap]{}{\pi_0} \ar[ur]{}{s} \ar[rr, equals, crossing over] & & f^{\ast}(TY) \ar[dl]{}{\pi_0} \\
 & X
\end{tikzcd}
\]
also commutes. However, it need not be the case that $s$ itself is directly linear. What we instead ask is the following general question: ``given a $p$-carrable $T$-submersion $f:X \to Y$, if we have corresponding section $s$ to $\theta_f$, can we build a \emph{linear} section of $\theta_f$ out of $s$?'' We will present some partial answers to this question below and indicate that, for the case of Rosick{\'y} tangent categories and for the opposite categories of commutative algebras $\CAlg{R}^{\op}$ over a commutative rig $R$, it is the case that we can find a ``linearization'' or ``linear component'' of $s$, of sorts.

The first cases we consider for building linear versions of given sections are those which mirror the local algebraic structure that the symmetric algebra $\Sym_{X}$ and underlying module $\operatorname{Und}_{X}$ induce, via the opposite equivalences $\DBun(\Spec A)^{\op} \simeq \Mod{A}$ of \cite{GeoffJSDiffBunComAlg}, on the corresponding differential bundle categories $\Sym_{X}^{\op}:\DBun(X)^{\op} \to \CAlg{X}^{\op}$ and $\operatorname{Und}_{X}^{\op}:\CAlg{X}^{\op} \to \DBun(X)^{\op}$. The point here is that there are three key ingredients to this situation:
\begin{enumerate}[{\em (i)}] 
    \item In $\CAlg{R}^{\op}$, every map is $p$-carrable.
    \item In $\CAlg{R}^{\op}$, $\Sym_{A}$ (the functor whose opposite forgets the differential bundle over $A$ structure) is left adjoint to the underlying module functor $\operatorname{Und}_A$ (the functor whose opposite takes a sliced object and promotes it to a differential bundle).
    \item The unit of adjunction $M \to \operatorname{Und}_A(\Sym_A(M))$ is a pointwise split monic in $\Mod{A}$, i.e., the left adjoint $\Sym_A$ is faithful.
\end{enumerate}
Abstracting these appropriately and taking opposites where indicated allows us to produce the following situation in which we know we can produce linear sections out of general sections.
\begin{proposition}\label{Prop: Linear sections from nonlinear sections with adjoints and units}
In a tangent category $(\Cscr,\Tbb)$, let $f: X \to Y$ be a map such that: 
\begin{enumerate}[{\em (i)}] 
    \item The forgetful functor $\operatorname{Forget}_X:\DBun(X) \to \Cscr_{/X}$ has a left adjoint $F_X:\Cscr_{/X} \to \DBun(X)$.
    \item The counit of adjunction $\epsilon$ for $F_X \dashv \operatorname{Forget}_X$ is a pointwise split epimorphism.
    \item The map $f:X \to Y$ is $p$-carrable.
\end{enumerate}
Then for any section of $\theta_f$, $s: f^{\ast}(TY) \to TX$, there admits a linear section $s_f$ of $\theta_f$ (so a section in $\DBun(X)$). In particular, if $f$ is a $T$-submersion then there exists a linear section of $\theta_f$ witnessing that $f$ is a $T$-submersion.
\end{proposition}
\begin{proof}
Begin by observing that since $\theta_f$ is a linear morphism of differential bundles over $X$, we can rewrite the diagram expressing that $s$ is a section $s$ as:
\[
\begin{tikzcd}
\operatorname{Forget}_X(f^{\ast}(TY)) \ar[r]{}{s} \ar[dr, equals] & \operatorname{Forget}_X(TX) \ar[d]{}{\operatorname{Forget}_X(\theta_f)} \\
 & \operatorname{Forget}_X(f^{\ast}(TY))
\end{tikzcd}
\]
Now apply the left adjoint $F_X$ to the diagram above to produce the commuting diagram:
\[
\begin{tikzcd}
F_X\left(\operatorname{Forget}_X(f^{\ast}(TY))\right) \ar[drr, equals] \ar[rr]{}{F_X(s)} & & F_X\left(\operatorname{Forget}_X(TX)\right) \ar[d]{}{F_X(\operatorname{Forget}_X(\theta_f)} \\
 & & F_X\left(\operatorname{Forget}_X(f^{\ast}(TY)\right)
\end{tikzcd}
\]
Let $\sigma_{f^{\ast}(TY)}:f^{\ast}(TY) \to F_X(\operatorname{Forget}_X(f^{\ast}(TY)))$ denote a given splitting of the counit
\[
\begin{tikzcd}
f^{\ast}(TY) \ar[rr]{}{\sigma_{f^{\ast}(TY)}} \ar[drr, equals] & & F_X\left(\operatorname{Forget}_X\big(f^{\ast}(TY)\big)\right) \ar[d]{}{\epsilon_{f^{\ast}(TY)}} \\
 & & f^{\ast}(TY)
\end{tikzcd}
\]
and define the linear map of differential bundles $s_f$ via the composition:
\[
\begin{tikzcd}
f^{\ast}(TY) \ar[d, swap]{}{s_f} \ar[rr]{}{\sigma_{f^{\ast}(TY)}} & & F_X(\operatorname{Forget}_X(f^{\ast}(TY))) \ar[d]{}{F_X(s)} \\
TX & & F_X(\operatorname{Forget}_X(TX)) \ar[ll]{}{\epsilon_{TX}}
\end{tikzcd}
\]
We then compute that
\begin{align*}
\theta_f \circ s_f &= \theta_f \circ \epsilon_{TX} \circ F_X(s) \circ \sigma_{f^{\ast}(TY)} = \epsilon_{f^{\ast}(TY)} \circ F_X\left(\operatorname{Forget}_X(\theta_f)\right) \circ F_X(s) \circ \sigma_{f^{\ast}(TY)} = \epsilon_{f^{\ast}(TY)} \circ \sigma_{f^{\ast}(TY)} \\
&= \id_{f^{\ast}(TY)} 
\end{align*}
so $s_f$ is indeed a section to $\theta_f$. Moreover, $s_f$ is linear exactly because it is defined as a composite of maps in $\DBun(X)$. The final claim of the proposition is immediate once we know that all powers $T^m$ preserve the weak pullback which makes $f$ a $T$-submersion.
\end{proof}
\begin{corollary}\label{Cor: Section Submersion: thetaf section iff linear section for adjoints}
In a tangent category $(\Cscr,\Tbb)$, let $f: X \to Y$ be a $p$-carrable map such that: 
\begin{enumerate}[{\em (i)}] 
    \item The forgetful functor $\operatorname{Forget}_X:\DBun(X) \to \Cscr_{/X}$ has a left adjoint $F_X:\Cscr_{/X} \to \DBun(X)$.
    \item The counit of adjunction $\epsilon$ for $F_X \dashv \operatorname{Forget}_X$ is a pointwise split epimorphism.
\end{enumerate}
Then the horizontal descent map $\theta_f:TX \to f^{\ast}(TY)$ admits a section if and only if it admits a \emph{linear} section.
\end{corollary}

We now show that both our tangent categories of affine schemes and schemes satisfy the conditions of the corollary. 

\begin{corollary}\label{Cor: Schemes and affine rig schemes are linearly submersive}
The categories $\CAlg{R}^{\op}$ (for a commutative rig $R$) and $\Sch_{/S}$ (for a base scheme $S$) have the property that for any map $f:X \to Y$, the horizontal descent $\theta_f:TX \to f^{\ast}(TY)$ admits a section if and only if it admits a linear section.
\end{corollary}
\begin{proof}
In both cases the functor $\operatorname{Forget}_X:\DBun(X) \to \Cscr_{/X}$ arises either as 
\[
\operatorname{Forget}_X \cong \underline{\Spec}_X(\underline{\Sym}_{\Ocal_X}(-)):\QCoh(X)^{\op} \to \Sch_{/X}
\]
in the case of an $S$-scheme $X$ or as
\[
\operatorname{Forget}_X \cong \Sym_{X}^{\op}(-):\Mod{X}^{\op} \to \CAlg{X}^{\op} = (\CAlg{R}^{\op})_{/X}.
\]
when $X$ is an object of $\CAlg{R}^{\op}$. In both cases the functors
\[
\Sym_X:\Mod{X} \to \CAlg{X}, \qquad \underline{\Sym}_{\Ocal_X}:\QCoh(X) \to \QCoh(X,\CAlg{\Ocal_X})
\]
are left adjoints whose unit $\eta$ is pointwise split. Taking the opposite of the rig-theoretic case or the relative spectrum of the scheme-theoretic case implies that $\operatorname{Forget}_X$ is a right adjoint with a pointwise split counit in all cases.
\end{proof}
\begin{example}\label{Example: Submersions in Schemes}
Let $S$ be a base scheme. Then in $\Sch_{/S}$ a map $f:X \to Y$ is a $T$-submersion if and only if the relative cotangent sequence
\[
\begin{tikzcd}
f^{\ast}\Kah{Y}{S} \ar[r]{}{v_f} & \Kah{X}{S} \ar[r] & \Kah{X}{Y} \ar[r] & 0
\end{tikzcd}
\]
is split exact in $\QCoh(X)$. This follows from the fact that $(\underline{\Spec}_X \circ \underline{\Sym}_{\Ocal_X})(v_f) = \theta_f$ and by Corollary \ref{Cor: Schemes and affine rig schemes are linearly submersive}, $\theta_f$ admits a section if and only if $v_f$ admits a section in $\QCoh(X)^{\op}$.
\end{example}

We now show that in a Rosick{\'y} tangent category, we can build linear sections from any section of the horizontal descent of a $p$-carrable map. We will need to do this in two steps: first we will show that in a Rosick{\'y} tangent category if $s:f^{\ast}(TY) \to TX$ is a section of the horizontal descent $\theta_f$, the map $s - s \circ f^{\ast}(0_Y) \circ \pi_0:f^{\ast}(TY) \to TX$ is a section  of $\theta_f$ which preserves the zero sections of the bundle map. Second we will have to show that if we have a zero-preserving section $s:f^{\ast}(TY) \to TX$ of the horizontal descent $\theta_f$ then there is a corresponding linear section $s_f$ of $\theta_f$.

\begin{lemma}\label{Lemma: From section to zero pres section}
Let $f:X \to Y$ be a $p$-carrable map in a Rosick{\'y} tangent category $(\Cscr,\Tbb)$. Then if $s:f^{\ast}(TY) \to TX$ is a section of the horizontal descent $\theta_f$, the map $s - s \circ f^{\ast}(0_Y) \circ \pi_0$ is a section of $\theta_f$ which preserves the zero section of $f^{\ast}(TY)$ and $TX$.
\end{lemma}
\begin{proof}
Begin by observing that by assumption the diagram
\[
\begin{tikzcd}
 & TX \ar[dd, near start]{}{p_X} \ar[dr]{}{\theta_f} \\
f^{\ast}(TY) \ar[dr, swap]{}{\pi_0} \ar[rr, equals] \ar[ur]{}{s} & & f^{\ast}(TY) \ar[dl]{}{\pi_0} \\
 & X
\end{tikzcd}
\]
commutes and so $s$ is a map in the slice category $\Cscr_{/X}$. We also compute that in $\Cscr_{/X}$
\[
p_X \circ (s - s \circ f^{\ast}(0_Y) \circ \pi_0) = p_X \circ s - p_X \circ s \circ f^{\ast}(0_Y) \circ \pi_0 = \pi_0 - \pi_0 \circ f^{\ast} \circ \pi_0 = \pi_0 - \pi_0 = \pi_0
\]
where the last equality holds because $\pi_0:f^{\ast}(TY) \to X$ is the map from $f^{\ast}(TY)$ to the terminal object in $\Cscr_{/X}$. We also compute that
\[
(s - s \circ f^{\ast}(0_Y) \circ \pi_0) \circ f^{\ast}(0_Y) = s\circ f^{\ast}(0_Y) - s \circ f^{\ast}(0_Y) \circ \pi_0 \circ f^{\ast}(0_Y) = s \circ f^{\ast}(0_Y) - s \circ f^{\ast}(0_Y) = 0_X
\]
which shows that the diagram
\[
\begin{tikzcd}
f^{\ast}(TY) \ar[rr]{}{s - s \circ f^{\ast}(0_Y) \circ \pi_0} & & TX \\
 & X \ar[ur, swap]{}{0_X} \ar[ul]{}{f^{\ast}(0_Y)}
\end{tikzcd}
\]
commutes. Note that the last equality uses the fact that $0_X$ is the unit of the bundle structure on $TX$ and the fact that the difference of the maps $\alpha - \alpha$ of morphisms $\alpha:X \to TX$ has the property that
\[
\begin{tikzcd}
X \ar[r, swap, shift right = 1]{}{\alpha - \alpha} \ar[r, shift left = 1]{}{0_X} & TX
\end{tikzcd}
\]
commutes. Finally we also compute that
\[
\theta_f \circ (s - s \circ f^{\ast}(0_Y) \circ \pi_0) = \theta_f \circ s - \theta_f \circ s \circ f^{\ast}(0_Y) \circ \pi_0 = \id - \theta_f \circ 0_X \circ \pi_0 = \id - f^{\ast}(0_Y) \circ \pi_0 = \id
\]
because $f^{\ast}(0_Y) \circ \pi_0:f^{\ast}(TY) \to f^{\ast}(TY)$ is the zero map on $f^{\ast}(TY)$. Thus $s - s \circ f^{\ast}(0_Y) \circ \pi_0$ is a section to the horizontal descent $\theta_f$ which preserves the zero section $f^{\ast}(0_Y)$ of $f^{\ast}(TY)$.
\end{proof}

\begin{proposition}\label{Prop: Rosicky tan cats all admit linear sections once the section preserves the zero}
Let $f:X \to Y$ be a $p$-carrable map in a Rosick{\'y} tangent category $(\Cscr,\Tbb)$. Suppose that the horizontal descent $\theta_f:TX \to f^{\ast}(TY)$ admits a section $s:f^{\ast}(TY) \to TX$ which preserves the zero section, i.e., $s \circ f^{\ast}(0_Y) = 0_X$. Then there exists a linear section $s_f:f^{\ast}(TY) \to TX$ of $\theta_f$.
\end{proposition}
\begin{proof}
We construct the section $s_f$ as follows. Recall that from the universal property of the vertical lift, we get that
\[
\begin{tikzcd}
TX \ar[r]{}{\ell_X} & T^2X \ar[rrr, bend right = 30, swap]{}{(T \ast p)_X} \ar[rrr,bend left = 30]{}{(p \ast T)_X} \ar[r]{}{(p \ast T)_X} & TX \ar[r]{}{p_X} & X \ar[r]{}{0_X} & TX
\end{tikzcd}
\]
is an equalizer diagram. We will use this universal property to show that we can induced a unique section $s_f$ from $f^{\ast}(TY) \to TX$ which equalizes the three listed maps. To this end we must first prove that
\[
\begin{tikzcd}
f^{\ast}(TY) \ar[rr]{}{Ts \circ \lambda} & & T^2X \ar[rrr, bend right = 30, swap]{}{(T \ast p)_X} \ar[rrr,bend left = 30]{}{(p \ast T)_X} \ar[r]{}{(p \ast T)_X} & TX \ar[r]{}{p_X} & X \ar[r]{}{0_X} & TX
\end{tikzcd}
\]
commutes where $\lambda = f^{\ast}(\ell_Y)$ is the lift of the differential bundle structure on $f^{\ast}(TY)$ over $X$. We first compute that by virtue of $\lambda = f^{\ast}(\ell_Y)$,
\[
(T \ast p)_X \circ Ts \circ \lambda = T(p_X \circ s) \circ \lambda = T\pi_0 \circ \lambda = 0_X \circ \pi_0
\]
and
\[
0_X \circ p_X \circ (T \ast p)_X \circ Ts \circ \lambda = 0_X \circ p_X \circ 0_X \circ \pi_0 = (0 \ast T)_X \circ \pi_0
\]
Finally, because $s \circ f^{\ast}(0_Y) = 0_X$, we also get that
\[
(p \ast T)_X \circ Ts \circ \lambda = s \circ p_X \circ \lambda = s \circ f^{\ast}(0_Y) \circ \pi_0 = 0_X \circ \pi_0.
\]
Applying the universal property of the equalizer  gives rise to a unique map $s_f$ rendering the diagram
\[
\begin{tikzcd}
TX \ar[r]{}{\ell_X} & T^2X \ar[rrr, bend right = 30, swap]{}{(T \ast p)_X} \ar[rrr,bend left = 30]{}{(p \ast T)_X} \ar[r]{}{(p \ast T)_X} & TX \ar[r]{}{p_X} & X \ar[r]{}{0_X} & TX \\
f^{\ast}(TY) \ar[u, dashed]{}{\exists! s_f} \ar[r, swap]{}{\lambda} & T(f^{\ast}(TY)) \ar[u, swap]{}{Ts}
\end{tikzcd}
\]
We will prove that $s_f$ is the section we desire.

Let us first prove that $s_f$ is a linear bundle morphism. First by construction we have the following commuting diagram:
\[
\begin{tikzcd}
f^{\ast}(TY) \ar[d, swap]{}{s_f} \ar[r]{}{\lambda} & T(f^{\ast}(TY)) \ar[d]{}{Ts} \ar[r]{}{p_{f^{\ast}(TY)}} & f^{\ast}(TY) \ar[d]{}{s} \\
TX \ar[r, swap]{}{\ell_X} & T^2X \ar[r, swap]{}{(p \ast T)_X} & TX
\end{tikzcd}
\]
We additionally have a commuting diagram
\[
\begin{tikzcd}
X \ar[d, equals] \ar[dr]{}{0_X} \ar[r]{}{f^{\ast}(0_Y)} & f^{\ast}(TY) \ar[d]{}{s} \\
X & TX \ar[l]{}{p_X}
\end{tikzcd}
\]
because $s \circ f^{\ast}(0_Y) = 0_X$. We also compute on one hand that $p_X = p_X \circ (p \ast T)_X \circ \ell_X$ and that $f^{\ast}(0_Y) \circ \pi_0 = p_{f^{\ast}(TY)} \circ \lambda$. Putting these together gives
\begin{align*}
p_X \circ s_f &= p_X \circ (p \ast T)_X \circ \ell_X \circ s_f = p_X \circ (p \ast T)_X \circ Ts \circ \lambda = p_X \circ s \circ p_{f^{\ast}(TY)} \circ \lambda \\
&= p_X \circ s \circ f^{\ast}(0_Y) \circ \pi_0 = p_X \circ 0_X \circ \pi_0 = \pi_0.
\end{align*}
Thus the diagram
\[
\begin{tikzcd}
f^{\ast}(TY) \ar[rr]{}{s_f} \ar[dr, swap]{}{\pi_0} & & TX \ar[dl]{}{p_X} \\
 & X
\end{tikzcd}
\]
commutes and so $s_f$ is a bundle map. To see that it is a linear bundle map we note that $\ell_X$ is $T$-monic by Proposition \ref{Prop: Vertical Lift is TMonic} and so, in particular, $T\ell_X = (T \ast \ell)_X$ is monic. We use this to deduce that
\begin{align*}
T\ell_X \circ Ts_f \circ \lambda &= T^2s \circ T\lambda \circ \lambda = T^2s \circ \ell_{f^{\ast}(TY)} \circ \lambda = (\ell \ast T)_X \circ Ts \circ \lambda = (\ell \ast T)_X \circ \ell_X \circ s_f \\
&= T\ell_X \circ \ell_X \circ s_f.
\end{align*}
Using that $T\ell_X$ is monic gives that $\ell_X \circ s_f = Ts_f \circ \lambda$ and hence that $s_f$ is a linear bundle map.

We now prove that $s_f$ is a section of $\theta_f$. To see this note that since $f^{\ast}(TY)$ is a pullback, it suffices to prove that $\pi_0 \circ \theta_f \circ s_f = \pi_0$ and that $\pi_1 \circ \theta_f \circ s_f = \pi_1$. For the first equation we derive that
\[
\pi_0 \circ \theta_f \circ s_f = p_X \circ s_f = \pi_0
\]
because $s_f$ is a linear bundle map. For the second note that $\pi_1 \circ \theta_f \circ s_f = Tf \circ s_f$ and that $\ell_Y \circ Tf \circ s_f = s_f \circ \ell_X \circ T^2f$. Since $\lambda:f^{\ast}(TY) \to T(f^{\ast}(TY))$ has the form $\lambda = \langle 0_X \circ \pi_0, \ell_Y \circ \pi\rangle$ by \cite[Bottom of Page 12]{GeoffRobinBundle}, the diagram
\[
\begin{tikzcd}
f^{\ast}(TY) \ar[r]{}{\pi_1} \ar[d, swap]{}{\lambda} & TY \ar[d]{}{\ell_Y} \\
T(f^{\ast}(TY)) \ar[r, swap]{}{T\pi_1} & T^2Y
\end{tikzcd}
\]
commutes. This allows us to deduce that on one hand $\ell_Y \circ \pi_1 = T\pi_1 \circ \lambda$ while on the other hand, since $Tf \circ s = \pi_1$ by virtue of $s$ being a section to $\theta_f$,
\begin{align*}
\ell_Y \circ \pi_1 \circ \theta_f \circ s_f &= \ell_Y \circ Tf \circ s_f = T^2f \circ \ell_X \circ s_f = T^2f \circ Ts \circ \lambda = T(Tf \circ s) \circ \lambda = T\pi_1 \circ \lambda.
\end{align*}
Thus $\ell_Y \circ \pi_1 \circ \theta_f \circ s_f = T\pi_1 \circ \lambda = \ell_1 \circ \pi_1$ and so, once again by $\ell_Y$ being $T$-monic by Proposition \ref{Prop: Vertical Lift is TMonic}, we have that $\pi_1 \circ \theta_f \circ s_f = \pi_1$. This in turn allows us to deduce that $\theta_f \circ s_f = \id_{f^{\ast}TY}$ and so proves that $s_f$ is a linear section of $\theta_f$.
\end{proof}

Putting these results together we can deduce the following: in a Rosick{\'y} tangent category every $p$-carrable $T$-submersion admits a \emph{linear} section of the horizontal descent, not just a nonlinear section.

\begin{corollary}\label{Cor: For a Rosicky tan cat T submersion on p carrable if and only if linear section to descent}
Let $(\Cscr,\Tbb)$ be a Rosick{\'y} tangent category and let $f:X \to Y$ be a $p$-carrable morphism. Then the horizontal descent $\theta_f:TX \to f^{\ast}(TY)$ admits a section in $\Cscr_{/X}$ if and only if it admits a section in $\DBun(X)$. In particular, $f$ is a $T$-submersion if and only if $\theta_f$ is a retract in $\DBun(X)$.
\end{corollary}
\begin{proof}
For the $\implies$ direction, assume that $\theta_f$ admits a section $s:f^{\ast}(TY) \to TX$ in $\Cscr_{/X}$. Then applying Lemma \ref{Lemma: From section to zero pres section} shows that there is a section $\hat{s}:f^{\ast}(TY) \to TX$ in $\Cscr_{/X}$ which preserves the zero section $f^{\ast}(0_Y)$ in the sense that $\hat{s} \circ f^{\ast}(0_Y) = 0_X$. Finally applying Proposition \ref{Prop: Rosicky tan cats all admit linear sections once the section preserves the zero} gives that there is a linear section $s_f$ of $\theta_f$, i.e., a section $s_f$ to $\theta_f$ in $\DBun(X)$. For the $\impliedby$ direction, this is immediate because linear sections are, in particular, sections upon forgetting from $\DBun(X)$ to $\Cscr_{/X}$. The final claim of the corollary follows from an immediate application of Proposition \ref{Prop: The lifting property characterization of TSmooth}. 
\end{proof}

\begin{corollary}\label{Cor: SMan has linear sections}
Each of the tangent categories $\SMan, \CAlg{R}$, $\CAlg{R}^{\op}$, and $\Sch_{/S}$ for $R$ a commutative ring have the property that $f:X \to Y$ is a $T$-submersion if and only if $\theta_f$ admits a linear section.
\end{corollary}
\begin{proof}
Each of the above tangent categories are Rosick{\'y}, so simply apply Corollary \ref{Cor: For a Rosicky tan cat T submersion on p carrable if and only if linear section to descent} in each case.
\end{proof}

