\section{Derivation of the macroscopic action}
\label{app:rkft_derivation}
In order to bring the interacting part of the microscopic action~\eqref{eq:S_I_doublet} into the form of a kinetic term for the macroscopic fields, we can introduce a field doublet $\phi = (\B, f)^\transp$ and write it as quadratic term,
\[
\im S_\I[\phi] &= \frac{1}{2}\int\dd X_1\,\dd X_2 \, \phi(X_1)^\transp\,\sigma(X_1,X_2)\,\phi(X_2)\\
&\equiv \frac{1}{2} \phi^\transp\, \sigma\, \phi,
\]
with the matrix
\[
\sigma(X_1,X_2) \coloneq \begin{pmatrix}
    0 & \identity \\
    \identity & 0
\end{pmatrix}(X_1,X_2),
\]
where $\identity(X_1,X_2)\coloneq\dirac(X_1-X_2)$.
%
Having expressed the action $S_\I$ in terms of macroscopic fields, there are two ways of introducing path integrals over the latter into the partition function:
%
\begin{enumerate}
    \item Multiplying the integrand by unity \cite{Lilow2019},
    \[
    1 &= \int\DD\psi_f\, \dirac[\psi_f-f]\\
    &= \int\DD\psi_f\,\DD\psi_\B\, \e^{\im \psi_\B\cdot(\psi_f-f)},
    \]
    where the Dirac distribution ensures that $\psi_f$ equals the Klimontovich phase-space density $f$. In particular, $\psi_f$ will obey the same statistics as $f$.
    \item Performing a Hubbard-Stratonovich transformation \cite{Daus2024},
    \[
    \e^{\frac{1}{2} \phi^\transp\,\sigma\,\phi} \propto \int\DD\psi \exp(-\frac{1}{2}\psi^\transp\,\sigma^{-1}\,\psi + \psi^\transp\phi).
    \]
    Essentially, this is a Gaussian integral with source term over a newly introduced doublet field $\psi = (\psi_f, \psi_\B)^\transp$. The Hubbard-Stratonovich transformation is a widely used technique in many-body theory and particle physics. It allows the reformulation of a theory of particles interacting through two-body potentials in terms of a collective field that independent particles couple to.
\end{enumerate}
These two options are exactly equivalent\footnote{The original papers only differ in their convention as to whether to absorb $\im$ into $\B$ or not.}. The theory is now formulated in terms of the macroscopic fields of interest. In particular, it is a field theory in the doublet $\psi$, which contains $f$, of which $\rho$, $\vPi$ etc.~are momentum moments.
The full partition function takes the form
\[\label{eq:Z_mac_1}
\Z = \int\DD\psi \exp(-\frac{1}{2}\psi^\transp\,\sigma^{-1}\,\psi + \ln \Z^\free[\psi]).
\]
$\Z^\free[\psi]$ denotes the free generating functional with the macroscopic doublet $\psi$ acting as a source, i.\,e.\ $\Z^\free[\psi]$ is obtained from $\Z^\free$ via $\im S_0 \to \im S_0 + \psi\cdot\phi$.
The Schwinger functional $W^\free[\psi] = \ln\Z^\free[\psi]$ appearing in \eqref{eq:Z_mac_1} thus generates cumulants of the free theory, e.\,g.
\[\label{eq:GrB_def}
G_{f\B}^\free(X_1,X_2)
= \frac{\delta^2 W^\free[\psi]}{\delta\psi_\B(X_1)\,\delta\psi_f(X_2)} \Bigg\rvert_{\psi=0}.
\]
Indeed, it contains \emph{all possible} free $f$- and $\B-$field cumulants and lends itself to a cumulant expansion\footnote{Note that pure $\B$-field cumulants vanish \cite{Fabis2018}.}
\begin{multline}
    W^\free[\psi] = G_{f}^\free\cdot\psi_\B + \psi_\B\cdot G_{f\B}^\free \cdot\psi_f \\
    + \frac{1}{2} \psi_\B\cdot G_{f f}^\free \cdot\psi_\B + \mathcal{O}(\psi^3).
\end{multline}
In Appendix~\ref{app:free_cumulants}, we show how to explicitly compute them.
Collecting all quadratic terms, i.\,e.~all free two-point cumulants, in an inverse propagator $\Delta^{-1}$ and introducing a source doublet $J$, the generating functional of the full theory reads
\[
    \Z[J] = \int\DD\psi \exp(-\frac{1}{2}\psi^\transp\,\Delta^{-1}\,\psi + S_\V[\psi] + J\cdot\psi),
\]
where the vertex part of the action, $S_\V$, contains all remaining free cumulants of $f$ and $\B$.

\section{Free cumulants}
\label{app:free_cumulants}
Given an initial $n$-point phase-space cumulant $G_{f\dots f}^\ini$, the corresponding freely evolved cumulant is simply obtained by means of~\eqref{eq:Z_micro}, where the classical trajectory is replaced by the free motion, i.\,e.
\begin{multline}
    G_{f\dots f}^\free(\vec{q}_1,\vec{p}_1,t_1,\dots,\vec{q}_n,\vec{p}_n,t_n) \\
    = G_{f\dots f}^\ini\qty(\vec{q}_1-t_1\frac{\vec{p}_1}{m},\vec{p}_1,\dots,\vec{q}_n-t_n\frac{\vec{p}_n}{m},\vec{p}_n).
\end{multline}
It is often easier to work in Fourier space, especially in homogeneous systems. In that case, the above translates to\footnote{In the case of the time coordinate we use for the cosmological application (see \ref{app:time_and_potential}), replace $\vec{l}_i + t_i\frac{\vec{k}_i}{m} \mapsto \gpp(\eta_i)\,\vec{l}_i+\gqp(\eta_i)\frac{\vec{k}_i}{m}$.}
\begin{multline}
    G_{f\dots f}^\free(\vec{k}_1,\vec{l}_1,t_1,\dots,\vec{k}_n,\vec{l}_n,t_n) \\
    = G_{f\dots f}^\ini\qty(\vec{k}_1,\vec{l}_1+t_1\frac{\vec{k}_1}{m},\dots,\vec{k}_n,\vec{l}_n+t_n\frac{\vec{k}_n}{m}).
\end{multline}
Using the definition of the response field~\eqref{eq:response_field}, mixed $f$- and $\B$-field cumulants can be obtained from the above~\cite{Fabis2018}.
\begin{widetext}
    \noindent
    In particular, we get
    \[
    G_{f\B\dots\B}^\free(\vec{k}_1,\vec{l}_1,t_1,\dots,\vec{k}_n,\vec{l}_n,t_n) = (2\pi)^3 \dirac\qty(\sum_{i=1}^{n} \vec{k}_i) \prod_{i=2}^{n} \qty[(2\pi)^3\dirac(\vec{l}_i)\,v(\vec{k}_i,t_i)\,\vec{k}_i \cdot \vec{L}_n(t_i)] \mathcal{G}_{f}^\ini(\vec{L}_n(0)),
    \]
    in a homogeneous system, where $G_f^\ini(\vec{k},\vec{l}) = (2\pi)^3\dirac(\vec{k})\,\mathcal{G}_{f}^\ini(\vec{l})$. We defined
    \[
    \vec{L}_n(t) = \sum_{j=1}^{n} \qty(\vec{l}_j + (t_j-t)\frac{\vec{k}_j}{m})\Theta(t_j-t).
    \]
    Similar expressions can be derived for an arbitrary number of $f$-legs.
    Cumulants of the observables defined in~\eqref{eq:momentum_moments} can be derived by taking momentum moments of the phase-space cumulants. In Fourier space, this translates to $\vec{p}\to-\im\nabla_{l}$ and $\int\dd[3]{p}\to\int\dd[3]{l}\dirac(\vec{l})$, i.\,e.~taking the appropriate number of $\vec{l}$-derivatives and setting $\vec{l}=0$.
\end{widetext}

\section{Computing the resummed propagator}
\label{app:macro_details}
In Section~\ref{sec:macro_pt}, we introduced the macroscopic formulation of the path-integral approach to classical Hamiltonian $N$-particle systems originally developed in~\cite{Lilow2019}. For completeness, we show how to explicitly compute the resummed propagator in this appendix, following the original work.

Inserting the ansatz~\eqref{eq:Neumann_series},
\[
    \Delta_{f\B}(X_1,X_2) &= \sum_{n=0}^{\infty} \qty[G_{f\B}^\free]^n (X_1,X_2)\\
    &= \identity(X_1,X_2) + \sum_{n=1}^{\infty} \qty[G_{f\B}^\free]^n (X_1,X_2)\\
    &= \identity(X_1,X_2) + \widetilde{\Delta}_{f\B}(X_1,X_2),
\]
into the definition~\eqref{eq:def_resummed_propagator} of the resummed propagator and multiplying both sides with $(\identity-G_{f\B}^\free)$ yields the self-consistency equation
\[
    \widetilde{\Delta}_{f\B}(X_1,X_2) ={}& G_{f\B}^\free(X_1,X_2) \\
    &+ \int\dd X G_{f\B}^\free(X_1,X)\,\widetilde{\Delta}_{f\B}(X,X_2).
\]
Since the interaction potential and, by extension, the $\B$-field are assumed to be independent of momentum, the internal momentum integration can be carried out easily, replacing $G_{f\B}^\free$ with $G_{\rho\B}^\free$ in the integrand. If, in addition, our system is statistically homogeneous, the spatial integration will be a convolution. In Fourier space $\widetilde{\Delta}_{f\B}$ then has the form
\begin{multline}
    \widetilde{\Delta}_{f\B}(\vec{k}_1,\vec{l}_1,t_1,\vec{k}_2,\vec{l}_2,t_2) \\= (2\pi)^6\dirac(\vec{k}_1+\vec{k}_2)\dirac(\vec{l}_2)\,\widetilde{\Delta}_{f\B}(\vec{k}_1,\vec{l}_1,t_1,t_2).
\end{multline}
We are thus left with the one-dimensional Volterra integral equation
\[
    \widetilde{\Delta}_{\rho\B}(\vec{k},t_1,t_2) ={}& G_{\rho\B}^\free(\vec{k},t_1,t_2) \\
    &+ \int\dd t\,G_{\rho\B}^\free(\vec{k},t_1,t)\,\widetilde{\Delta}_{\rho\B}(\vec{k},t,t_2),
\]
after also integrating out the external momentum.
If the time-dependence of $G_{f\B}^\free$ is only on $\Delta t = t_1-t_2$, this equation again becomes a convolution and can be solved using Laplace transforms \cite{Lilow2019},
\[\label{eq:Laplace_solution}
    \widetilde{\Delta}_{\rho\B}(\vec{k},\Delta t) = \mathcal{L}^{-1}_s\qty[\frac{\mathcal{L}_{\Delta t}[G_{\rho\B}^\free(\vec{k},\Delta t)](s)}{1-\mathcal{L}_{\Delta t}[G_{\rho\B}^\free(\vec{k},\Delta t)](s)}](\Delta t).
\]
In general, however, it needs to be solved numerically by discretizing time and solving the resulting matrix equation.

\section{Interaction potential and time coordinate for cosmic structure formation}
\label{app:time_and_potential}

As in most approaches to cosmic structure formation, be it numerical or analytical, we restrict ourselves to the sub-horizon, slow-motion, weak-field regime of General Relativity, where perturbative approximations are applicable (see e.\,g.~\cite{Mukhanov1992} for a review). In standard cosmology, the background metric is homogeneous and isotropic, with cosmic structure inducing small perturbations. The latter can be decomposed into scalar, vector and tensor contributions, which evolve independently at linear order in relativistic perturbation theory. In order to describe the system in terms of an interaction potential and make use of the formalism described in section \ref{sec:theory}, it is thus sufficient to restrict to scalar perturbations.
In conformal Newtonian gauge and units where $c=1$, the perturbed line element reads
\[
    \dd s^2 &= g_{\mu\nu}\,\dd x^\mu\,\dd x^\nu\\
    &= a^2\qty(-(1+2\Psi)\,\dd \tau^2 + (1-2\Phi)\,\delta_{ij}\,\dd x^i\,\dd x^j),
\]
with the Kronecker delta $\delta_{ij}$ and using Einstein's summation convention. The scalar perturbations $\Psi$ and $\Phi$ depend on spacetime, and the scale factor $a$ on time. At the background level, Einstein's field equations yield the Friedmann equations governing the evolution of $a$. Restricting ourselves to cold dark matter, i.\,e.~ignoring relativistic matter contributions, the linear order field equations yield $\Psi = \Phi$ and
\[
    \laplace\Phi - 3\,\H\,(\partial_\tau\Phi+\H\Phi) = 4\pi G a^2 \bar\rho_m\delta,
\]
with the mean mass density $\bar{\rho}_m$, the density contrast~$\delta$ and the conformal Hubble parameter $\H = \partial_\tau a/a$. On sub-horizon scales, the second term on the left-hand side is typically neglected, resulting in a Poisson-type equation,
\[
    \laplace \Phi = 4\pi G a^2 \bar{\rho}_m\delta. %= \frac{3}{2} \Om \H_0^2\,a^{-1} \delta,
\]
%where we have chosen the normalization $a=1$ today, $\H_0 = \H(a=1)$, and $\Om$ denotes the present-day energy-density parameter.
A point particle moving through spacetime will extremize its proper time. Consequently, its action reads
\[
    S = \int \dd\tau\,a(\tau) \qty[\frac{m}{2}\qty(\pdv{\vec{q}}{\tau})^2 - m\Phi - mc^2]
\]
in the non-relativistic limit and comoving coordinates~$\vec{q}$ with respect to the background. It can be useful to choose a different time coordinate. In superconformal time \cite{Shandarin1981}, $\dd t_\mathrm{s} = \dd\tau/a$, with the corresponding momenta $\vec{p}_\mathrm{s} = \partial_{t_\mathrm{s}} \vec{q}$, for example, the kinetic term of the Lagrangian has the same form as that of a particle moving in a flat spacetime. The time dependence of the background is then fully absorbed into the potential. Alternatively, one might want to remove the time dependence of the potential altogether. While this is impossible for a general cosmology, it can be achieved in good approximation for late time cosmologies using the well-known time variable \cite{Nusser1998}
\[
    \eta \coloneq \ln \frac{D_+}{D_+^\ini},
\]
where $D_+$ denotes the linear growth factor. Defining the (non-canonical) momentum
\[
    \vec{p} \coloneq m \dv{\vec{q}}{\eta},
\]
the Hamiltonian equations yield \cite{Lilow2019}
\[
    \dv{\vec{p}}{\eta} = -m\nabla\tilde{\Phi} + \qty(1-\frac{3}{2}\frac{\Om}{f^2}) \vec{p}
    \approx -m\nabla\tilde{\Phi} - \frac{\vec{p}}{2},
\]
with the matter density parameter $\Om$ and 
\[
    f \coloneq \dv{\ln D_+}{\ln a}.
\]
In the last step, we have used the approximation $\Om/f^2 \approx 1$, which has been demonstrated to hold very well for late-time cosmologies \cite{Scoccimarro1998}. Note that this approximation is not necessary, it merely simplifies analytical calculations. The rescaled potential fulfils the Poisson equation
\[
    m\laplace\tilde{\Phi} = \frac{3}{2}\frac{\Om}{f^2} \delta \approx \frac{3}{2} \delta.
\]
The solution for a point particle yields the potential energy $v = m\tilde\Phi$ given in~\eqref{eq:point_source_potential}.
Ignoring the potential, the solution \eqref{eq:free_trajectories} of the free equations of motion is replaced by
\[
        \vec{q}^\free(\eta)  = \vec{q}^\ini + \gqp(\eta)\,\vec{p}^\ini \qq{and} \vec{p}^\free(\eta) = \gpp(\eta)\,\vec{p}^\ini,
\]
with the free propagators~\cite{Fabis2015}
\[
    \gqp(\eta_1-\eta_2) &= 2\qty(1-\e^{-\frac{1}{2}(\eta_1-\eta_2)}) \Theta(\eta_1-\eta_2), \\
    \gpp(\eta_1-\eta_2) &= \e^{-\frac{1}{2}(\eta_1-\eta_2)} \Theta(\eta_1-\eta_2).
\]

\section{Initial conditions}
In this appendix, we give details on the sampling of an initial $N$-particle phase-space density for the two approaches presented in Sections~\ref{sec:old_ICs} and \ref{sec:new_ICs}, respectively.

\subsection{Gaussian initial conditions in the density and velocity fields}
\label{app:old_ICs}
For the initial conditions presented in~\ref{sec:old_ICs}, the Poisson sampling of an initial $N$-particle phase-space density was presented in~\cite{Fabis2015,Bartelmann2016}. We summarize the key steps in the following.

Consider some realization $\varphi = (\delta^\ini, \vec{v}^\ini)^\transp$ of the density and velocity fields drawn from the ensemble characterized by these statistics. We want to sample particles from the ensemble in such a way that their statistics recover those of $\varphi$ in the limit of large $N$. The probability of finding a particle at $\vec{q}_j$ should hence be proportional to the density~$\rho = \bar{\rho}(1+\delta)$ at that position. For any given $\vec{q}_j$, the associated momentum is given by $m\vec{v}^\ini(\vec{q}_j)$. Therefore, the probability of finding the particle at $\vec{q}_j$ with momentum~$\vec{p}_j$ is
\[
    P(\vec{q}_j,\vec{p}_j \mid \varphi(\vec{q}_j)) = \frac{1}{V} \qty(1+\delta^\ini(\vec{q}_j)) \, \dirac\qty(\vec{p}_j-m\vec{v}^\ini(\vec{q}_j)).
\]
The normalization was chosen by first restricting to a finite volume $V$.
We independently draw $N$ particles in a Poisson-sampling process. Using the notation introduced in~\eqref{eq:bundle_notation}, the conditional probability for the whole ensemble reads
\[\label{eq:P_conditional}
    P(\bm{x}^\ini \mid \bm{\varphi}) = \prod_{j=1}^N P\qty(x_j^\ini \mid \varphi_j=\varphi\qty(\vec{q}_j^\ini)).
\]
In the end, we will take the limit $N, V \to \infty$ at constant $\bar{\rho} = N/V = \bar{\rho}_m/m$.
The initial $N$-particle phase-space probability density $\varrho_N(\bm{x}^\ini) = P(\bm{x}^\ini)$ is thus
\[\label{eq:P_ini}
    \varrho_N(\bm{x}^\ini) &= \int \dd\bm{\varphi}\,P(\bm{x}^\ini \mid \bm{\varphi})\,P(\bm{\varphi})
\]
with 
\[
    P(\bm{\varphi}) = \frac{1}{\sqrt{\det 2\pi \mathbf{C}}} \exp(-\frac{1}{2}\bm{\varphi}^\transp \mathbf{C}^{-1}\,\bm{\varphi}),
\]
where the covariance $\mathbf{C}$ is given by
\[
    \mathbf{C} = \sum_{j,k=1}^{N} \mat{C}\qty(\vec{q}_j^\ini,\vec{q}_k^\ini) \otimes (e_j\otimes e_k).
\]
The integrals in~\eqref{eq:P_ini} can be solved by expressing $P(\bm{\varphi})$ in terms of its Fourier transform, i.\,e.~the characteristic function
\[
    \mathcal{F}[P(\bm{\varphi})](\bm{s}) = \exp(\frac{1}{2}\bm{s}^\transp\mathbf{C}\bm{s}),
\]
resulting in an expression of the form
\begin{multline}
    \varrho_N(\bm{x}^\ini) = \frac{V^{-N}}{\sqrt{\det 2\pi m^2\, \mathbf{C}_{\bm{v\otimes v}}}}\, \mathcal{C}(-\im\bm{\nabla}_{\bm{p}^\ini})\\\times\exp(-\frac{1}{2 m^2} {\bm{p}^\ini}^\transp \mathbf{C}_{\bm{v\otimes v}}^{-1}\,\bm{p}^\ini),
\end{multline}
with some polynomial $\mathcal{C}$. For more details, refer to the appendix of~\cite{Bartelmann2016}.

\subsection{Gaussian initial conditions in the phase-space density}
\label{app:new_ICs}
Given a Gaussian distribution for the phase-space density $f$, characterized by its cumulants $\mu_{f}$ and $C_{ff}$, the initial conditions of a corresponding particle ensemble can be obtained by Poisson-sampling the phase-space distribution directly,
\[
    P(x_i \mid f^\ini] = \frac{1}{N}\,f^\ini(x_i).
\]
\begin{widetext}
    The resulting $N$-particle phase-space density is
    \[
        \varrho_N(\bm{x}^\ini) &= \int\DD f^\ini\,\prod_{i=1}^{N}\,\bigg[P(x_i \mid f^\ini]\bigg]\,P[f^\ini]\\
        &= \frac{1}{N^N}\sum_{\sigma\in S_N}\sum_{k=0}^{\lfloor N/2 \rfloor} \prod_{i=1}^{2k-1}\qty[\frac{1}{2}\, C_{ff}(x_{\sigma(i)},x_{\sigma(i+1)})] \frac{1}{(2k-1)!}\prod_{j=2k+1}^{N} \mu_f(x_{\sigma(j)}),
    \]
    by Wick's theorem, where $P[f^\ini]$ is the Gaussian probability functional of $f^\ini$ and $S_N$ denotes the permutation group of $\{1,\dots,N\}$.
