\begin{abstract}
    Let $F$ be a non-archimedean local field with odd residual characteristic, and let $H$ be a maximal torus of $\GL_2(F)$. In this paper, we will classify the irreducible $H$-distinguished representations of $\GL_2(F)$ by using Casselman's criteria for $p$-adic symmetric spaces developed by Kato-Takano.
\end{abstract}

\section{Introduction}

Let $F$ be a non-archimedean local field with odd residual characteristic. Let $\bf G$ be a connected reductive group over $F$ with an $F$-involution $\sigma$, and $\bf H$ be the subgroup of all $\sigma$-fixed points of $\bf G$. For any $F$-subgroup $\bf R$ of $\bf G$, the group ${\bf R}(F)$ of $F$-points of $\bf R$ is denoted by $R$.

An admissible representation $(\pi,V)$ of $G$ is said to be $H$-distinguished if there exists a nonzero $H$-invariant linear form on $V$. In \cite{MR2428854}, Kato and Takano defined the $H$-matrix coefficient of an $H$-distinguished representation $(\pi,V)$ as follows: Let $v\in V$ and $\lambda \in \Hom_H(\pi,{\bf 1})$. The $H$-matrix coefficient $\varphi_{\lambda,v}$  is a function on symmetric space $G/H$ defined by
\begin{equation*}
	\varphi_{\lambda,v}(g)=\langle \lambda,\pi(g^{-1})v \rangle
\end{equation*}
for $g\in G$. Furthermore, the $H$-relatively cuspidal, square integrable and tempered representations were defined by Kato, Takano and Takeda (\cite{MR2428854, MR2566307, MR3889766}) as follows.

\begin{dfn} Let $(\pi,V)$ be an $H$-distinguished representation of $G$, and $Z_G$ be the center of $G$.
    \begin{enumerate}[leftmargin=*]
	    \item A representation $(\pi,V)$ is called $H$-relatively cuspidal if the $H$-matrix coefficients $\varphi_{\lambda,v}$ are compactly supported modulo $Z_GH$ for all $v\in V$ and $\lambda\in\Hom_H(\pi,{\bf 1})$.
    \end{enumerate}

    \noindent Assume $(\pi,V)$ admits a unitary central character.
    \begin{enumerate}[leftmargin=*, start=2]
	    \item A representation $(\pi,V)$ is called $H$-relatively square integrable if the $H$-matrix coefficients $\varphi_{\lambda,v}$ are square integrable modulo $Z_GH$ for all $v\in V$ and $\lambda\in\Hom_H(\pi,{\bf 1})$.

        \item A representation $(\pi,V)$ is called $H$-relatively tempered if the $H$-matrix coefficients $\varphi_{\lambda,v}$ are in $L^{2+\varepsilon}(G/Z_GH)$ for all $\varepsilon >0$, $v\in V$ and $\lambda\in\Hom_H(\pi,{\bf 1})$.
    \end{enumerate}
\end{dfn}

In this paper, we classify the irreducible $H$-distinguished representations of $G$ in the case ${\bf G} =\GL_2$ and $\sigma$ is a nontrivial inner involution of ${\bf G}$. Note that in this case, ${\bf H}$ is $G$-conjugate to
\begin{equation*}
	\left\{
	\begin{pmatrix}
		a & b \\ \tau b & a
	\end{pmatrix}
	\bigg |\ a^2-\tau b^2\neq 0\right\} \quad \text{for some}\ \tau\in F^{\times},
\end{equation*}
so that ${\bf H}$ is a maximal torus of ${\bf G}$. It is well known that the criterion proved by Waldspurger and Tunnell characterizes an infinite-dimensional irreducible admissible representation as being $H$-distinguished. We state the main results of this paper.

\begin{thm}\label{thm:classification_in_the_split_case} Let ${\bf G}$ be $\GL_2$, ${\bf H}$ be a maximal $F$-split torus of $G$, and $(\pi,V)$ be an irreducible $H$-distinguished representation of $G$.
\begin{enumerate}[leftmargin=*]
	\item A representation $(\pi,V)$ is $H$-relatively cuspidal if and only if it is either a supercuspidal or the untwisted Steinberg representation.

	\item A representation $(\pi,V)$ is $H$-relatively square integrable if and only if it is square integrable.

	\item A representation $(\pi,V)$ is $H$-relatively tempered if and only if it is tempered.
\end{enumerate}
\end{thm}

\begin{thm}\label{thm:classification_in_the_non-split_case} Let ${\bf G}$ be $\GL_2$, ${\bf H}$ be a maximal non $F$-split torus of $G$, and $(\pi,V)$ be an irreducible $H$-distinguished representation of $G$.
    \begin{enumerate}[leftmargin=*]
	    \item A representation $(\pi,V)$ is $H$-relatively cuspidal if and only if it is supercuspidal.

	    \item A representation $(\pi,V)$ is $H$-relatively square integrable if and only if it is square integrable.

	    \item A representation $(\pi,V)$ is $H$-relatively tempered if and only if it is tempered.
    \end{enumerate}
\end{thm}

The structure of this paper is as follows: In Section \ref{sec:structure_of_G}, we will recall some facts about $\sigma$-split parabolic subgroups and the real parts of characters. In section \ref{sec:H-dist_rep}, we will recall some classes of $H$-distinguished representations and theorems that characterize them. In section \ref{sec:induction_from_split_parabolic_subgp}, we will consider induced representations from split parabolic subgroups. In section \ref{sec:rep_GL_2}, we will recall the representation theory of $\GL_2(F)$. In Sections \ref{sec:main_result_in_the_split} and \ref{sec:main_result_in_the_non-split}, we will prove our main result.

