\section{Chernoff's method}

In \cite{C52} bounds on the tails of a set of Bernoulli
trials are discussed in the form of Theorem 1.
Theorem~1 of \cite{C52} is restated below as
%Theorem~\ref{chthm1} after some relevant definitions.
after some relevant definitions.
One can extract a variety of bounds out of Theorem~\ref{chthm1}. 
Such bounds can lead to  a sequence of lemmas such as
Lemma~\ref{lem1},
Lemma~\ref{lem2},
Lemma~\ref{lem3}, and
Lemma~\ref{lem4} for the right tails,
and
Lemma~\ref{lem5}, and
Lemma~\ref{lem6}, and
Lemma~\ref{lem7} for the left tails,
and their associated corollaries along with
some obvious concentration bounds 
(left and right tail bounds).

\begin{dfn}
Let $X_i$, $i=1, \ldots , n$ be  independent random 
variables identical in distribution to   
random variable $X$ whose moment generating function 
is $M_X (t) = E( e^{tX} )$,
and its cumulative distribution function is 
$F_X (x) = P( X \leq x)$.
Let  $E(X)=p=\mu$ and  define
$S_n = \sum_{i=1}^{n} X_i$ and $E(S_n) = n E(X)=n \mu$,
and
\[
m ( r ) = \inf E( e^{t(X-r) } ) 
   = \inf e^{-rt} M_X (t) 
   = \inf e^{-rt} E( e^{tX} )
.
\]
The infimum is with respect to the $t$'s values.
$M_X (t)$ attains a minimum value $m(0)$.
\end{dfn}
\noindent
Skipping some other details, the $t$ value for
the minimum is finite unless $P(X>0)=0$ or $P(X<0)=0$
and then $m(0)=P(X=0)$.
If $P( X \leq 0 ) > 0$ and
   $P( X \geq 0 ) > 0$ then $m(0) > 0$.
The following is Theorem 1 of Chernoff \cite{C52}

\begin{thm}[Chernoff \cite{C52}]
\label{chthm1}
If $E(X) < \infty$ and $r \geq E(X)$ then
\begin{equation}
\label{cher1}
 P( S_n \geq nr ) \leq (m(r))^n .
\end{equation}
If $E(X) > - \infty$ and $r \leq E(X)$ then
\begin{equation}
\label{chel1}
 P( S_n \leq nr ) \leq (m(r))^n .
\end{equation}
If $0 < u < m(r)$ and $E(X)$ might not exist,
\begin{equation}
\label{chel2}
  \lim_{n \rightarrow \infty} \frac{(m(r)- u)^n}{P(S_n \leq nr)} = 0.
\end{equation}
\end{thm}
\begin{proof}
In order to prove Eq.(\ref{cher1}) we  perform the following
transformation, using in the last step Markov's inequality,
and before that the monotonically increasing function
$X \mapsto e^{tX}$. Consider a $t>0$ and the monotonically
increasing function $f(x) = e^{tx}$.
\begin{eqnarray}
 P( S_n \geq nr ) &=&    P( t S_n    \geq t nr)  \nonumber \\
                 &=&    P( e^{tS_n} \geq e^{nrt} )\nonumber  \\
                 &\leq& \frac{ E( e^{tS_n} )}{e^{nrt}} \nonumber \\
\label{chel2a}
                 &\leq& e^{-nrt} E( e^{tS_n} ) \\
\label{chel2b}
                 &=   & e^{-nrt} M_{S_n} (t) .
\label{che1}
\end{eqnarray}
We then examine $ M_{S_n} (t) = E( e^{tS_n} )$. 
Since $S_n = \sum_i X_i$, then
\begin{eqnarray}
E( e^{tS_n} ) &=& E( e^{t \sum_{i} X_i } ) \nonumber \\
              &=& E( \prod_{i} e^{t  X_i } ) \nonumber \\
              &=&    \prod_{i} E( e^{t  X_i } ) \nonumber \\
              &=&    \prod_{i} M_{X_i} (t) \nonumber \\
              &=&     \left(   M_{X} (t) \right)^n .
\label{che2}
\end{eqnarray}
From Eq.~(\ref{che1}) by way of Eq.~(\ref{che2}) we obtain
the following.
\begin{eqnarray}
 P( S_n \geq nr ) 
    &\leq& e^{-nrt} E( e^{tS_n} )  \nonumber \\
    &\leq& e^{-nrt} \left(   M_{X} (t) \right)^n \nonumber \\
    & = & \left( e^{-rt}   M_{X} (t) \right)^n \nonumber \\
    & = & \inf_{t>0} \left( e^{-rt}   M_{X} (t) \right)^n \nonumber \\
    & = & \inf_{t>0} \left( m(r)  \right)^n .
\label{che3}
\end{eqnarray}
This completes the proof of Eq.(\ref{cher1}).
$ $ \\ $ $
The proof of Eq.(\ref{chel1}) is similar. Consider a $t < 0$ now.
\begin{eqnarray}
 P( S_n \leq nr ) &=&    P( t S_n    \geq t nr)  \nonumber \\
                 &=&    P( e^{tS_n} \geq e^{nrt} )\nonumber  \\
                 &\leq& \frac{ E( e^{tS_n} )}{e^{nrt}} \nonumber \\
                 &\leq& e^{-nrt} E( e^{tS_n} ) \nonumber \\
                 &=   & e^{-nrt} M_{S_n} (t) .
\label{che4}
\end{eqnarray}
The rest is identical to the previous case.
\end{proof}


In most of the discussion to follow we will assume
that $X_i$ and $X$ follow a Bernoulli distribution i.e.
$X_i \sim b(p)$ and $X \sim b(p)$ and thus $E(X_i ) = E(X)=p$,
where $0 < p < 1$. 
Then, $S_n \sim B(n,p)$.
Therefore we have the following.
\[
 M_X (t) = E( e^{tX} ) =  e^t \cdot p + 1 \cdot (1-p) 
         = 1 + p( e^t -1 ) \leq e^{pe^t -p}.
\]
The last part is because for all $x$, we have $e^x \geq 1+x$.

\begin{dfn}[Kullback-Leibler]
The Kullback-Leibler divergence $D_{KL}$ or just simply $D$
is defined as follows for two distributions of $n$ elements
$P= \cup_i \{ p_i \} $ , $p_i \geq 0$,
$Q= \cup_i \{ q_i \} $ , $q_i \geq 0$, 
$i=1, \ldots , n$ 
such that $\sum_i p_i = \sum_i q_i =1$.
\begin{equation}
\label{kldiv}
D_{KL} (P || Q ) = D( P || Q) = \sum_i p_i \ln{\frac{p_i}{q_i}}.
\end{equation}
\end{dfn}


\section{Derived right tails}


We derive the first Chernoff bound for a Binomial r.v.
$S_n$ which is the sum of $n$ Bernoulli random variables,
using Eq.(\ref{cher1}).

\begin{lem}
\label{lem1}
Let $X_i$ be independent random variables  following
the same distribution as random variable $X$, $X \sim b(p)$, 
where $0<p<1$.
Let $S_n = \sum_i X_i$.
Then, for any $r$ such that $p < r < 1$ we have the following.
\begin{equation}
\label{rche1}
 P( S_n \geq rn ) \leq \exp{( - D(r || p) n)}
                = \left[ \left( \frac{p}{r}     \right)^r
                         \left( \frac{1-p}{1-r} \right)^{1-r}
                  \right]^n .
\end{equation}
\end{lem}

Sometimes $r=p+t$ and the bound $p<r<1$ 
becomes $p<p+t <1$ or equivalently $0 < t < 1-p$. 
We report this variant in Corollary~\ref{cor2e}.

\begin{proof}(Of Eq.~(\ref{rche1}))
$ $ \\ $ $
By Eq.~(\ref{che3}) we have the following
 considering that $M_X (t) = E( e^{tX} ) 
         = 1 + p( e^t -1 ) \leq e^{pe^t -p}$.
\begin{eqnarray}
 P( S_n \geq nr ) 
   &\leq& \inf_{t>0} \left( e^{-rt}   M_{X} (t) \right)^n 
      \nonumber \\
   &\leq& \inf_{t>0} \left( e^{-rt}   (1 + p( e^t -1 )) \right)^n 
      \nonumber \\
\label{rche1a}
   &\leq& \inf_{t>0} \left( \frac{(1 + p( e^t -1 ))}{e^{rt}} \right)^n 
                \\
%   \leq \inf_{t>0} \left( e^{-rt}   e^{pe^t -p}) \right)^n 
%      \nonumber \\
%   &\leq& \inf_{t>0} \left(  \frac{e^{pe^t -p}}{e^{-rt}}) \right)^n 
%      \nonumber \\
\label{rche1b}
   &\leq& \inf_{t>0} \left(  \exp{(f(t))} \right)^n 
\end{eqnarray}
As indicated by Eq.~(\ref{rche1b}),
$f(t) = \ln{( (1 + p( e^t -1 ))} -rt$.
Consider $f^{'} (t) = pe^t / (1+p e^t -p) -r$.
Equating to zero $f^{'} (t)=0$ and solving for $t$
we obtain $e^t = (1-p)r/(p(1-r))$.
Continuing with the second derivative we find
$f^{''} (t) = p(1-p) e^t / (1+pe^t -p)^2 >0$.
Therefore $f(t)$ has a minimum for $ e^t = (1-p)r/(p(1-r))$.
We then continue with Eq.~(\ref{rche1a}) as follows.
%, noting $ 1 + p( e^t -1 ) \leq \exp{(pe^t -p)}$.
\begin{eqnarray}
 P( S_n \geq nr ) 
\label{rche1c}
   &\leq& \inf_{t>0} \left( \frac{(1 + p( e^t -1 ))}{e^{rt}} \right)^n 
%   &\leq& \inf_{t>0} \left( \frac{e^{pe^t -p}}{e^{rt}} \right)^n 
%      \nonumber \\
\end{eqnarray}
The denominator $\exp{(rt)}$ for $e^t = (1-p)r/(p(1-r))$
is as follows.
\begin{equation}
\label{rche1d}
\exp{(rt)} = \left( (1-p)r/(p(1-r)) \right)^r =
           \frac{(1-p)^r r^r}{p^r (1-r)^r}.
\end{equation}
Likewise the numerator is as follows.
\begin{equation}
\label{rche1e}
(1 + p( e^t -1 )) = \frac{(1-p)rp}{p(1-r)}+1-p = \frac{1-p}{1-r}
\end{equation}
Therefore we have the following for the quantity below.
\begin{equation}
\label{rche1f}
\frac{(1 + p( e^t -1 ))}{e^{rt}} 
= \frac{1-p}{1-r} \cdot  \frac{p^r (1-r)^r}{(1-p)^r r^r}
                = \left[ \left( \frac{p}{r}     \right)^r
                         \left( \frac{1-p}{1-r} \right)^{1-r}
                  \right]^n .
\end{equation}
The proof is completed.
\end{proof}


We generate one more bound from Eq.(\ref{cher1}).
The bound is stronger than the Corollaries to follow that bring
it into an easier to deal with form.


\begin{lem}
\label{lem2}
Let $X_i$ be independent random variables  following
the same distribution as random variable $X$, $X \sim b(p)$, 
where $0<p < 1$.
Let $S_n = \sum_i X_i$.
Then, for any $r$ such that $p < r < 1$ we have the following,
after we substiture $r=(1+\delta ) p$, $\delta > 0$.
\begin{equation}
\label{rche2}
 P( S_n \geq rn ) =
 P( S_n \geq (1+ \delta) pn ) 
   \leq            \left(  \frac{e^r \cdot p^r}{e^p \cdot r^r} \right)^n 
     =             \left(  \frac{e^{\delta }}
                                  {(1+\delta)^{(1+\delta )}} 
                     \right)^{pn} 
\end{equation}
\end{lem}
\begin{proof}
By Eq.~(\ref{che3}) we use
$M_X (t) = E( e^{tX} )   = 1 + p( e^t -1 ) \leq e^{pe^t -p}$,
to obtain the following.
\begin{eqnarray}
 P( S_n \geq nr ) 
   &\leq& \inf_{t>0} \left( e^{-rt}   (1 + p( e^t -1 )) \right)^n 
      \nonumber \\
\label{rche2a}
   &\leq& \inf_{t>0} \left( e^{-rt}   e^{pe^t -p} \right)^n 
      \\
   &\leq& \inf_{t>0} \left( \exp{( pe^t -p-rt)} \right)^n 
      \nonumber \\
\label{rche2b}
   &\leq& \inf_{t>0} \left(  \exp{(f(t))} \right)^n 
\end{eqnarray}
The second to last part is because for all $x$, we have 
$e^x \geq 1+x$.
By Eq.~(\ref{rche2a}) and Eq.~(\ref{rche2b}) we
have $f(t) =  pe^t -p-rt$. Since $f^{'} (t) = pe^t -r$,
setting $f^{'} (t) = 0$ we obtain $t = \ln{(r/p)}$.
Moreover, $f^{''}(t) = p e^t$ is equal to
$f^{''} (  \ln{(r/p)} ) =r > 0$. Therefore $f(t)$
has a minimum at $t = \ln{(r/p)}$. Substituting this
value for $t$ in Eq.(\ref{rche2b}) the following
is obtained.

%f(t) = pe^t -p -rt
%f(ln(r/p)) = p r/p - p - rln(r/p) = r -p - rlnr +rlnp
% exp(f(ln(r/p)) =  ( e^r / e^p ) (p^r / r^r ).
\begin{eqnarray}
 P( S_n \geq nr ) 
   &\leq& \inf_{t>0} \left( \exp{( pe^t -p-rt)} \right)^n 
      \nonumber \\
   &\leq&            \left(  \exp{( p (r/p) -p -r \ln{(r/p)}} \right)^n 
      \nonumber \\
   &\leq&            \left(  \frac{e^r \cdot p^r}{e^p \cdot r^r} \right)^n 
\label{rche2c}
\end{eqnarray}
Finally we substitute $r=(1 + \delta ) p$ in Eq.~(\ref{rche2c})
to obtain our result
\begin{eqnarray}
 P( S_n \geq nr ) 
   &\leq&            \left(  \frac{e^{(1+\delta )p} 
                              \cdot 
                                   p^{(1+\delta )p}}
                                  {e^p \cdot ((1+\delta)p)^{(1+\delta ) p}} 
                     \right)^n  \nonumber \\
\label{rche2d}
   &\leq&            \left(  \frac{e^{\delta }}
                                  {(1+\delta)^{(1+\delta )}} 
                     \right)^{pn} 
\end{eqnarray}
\end{proof}

