A simpler proof of Eq.~(\ref{rche1}) for binomial random
variables is found in \cite{C79} and the proof is presented below.



\begin{lem}[\cite{C79}]
\label{lem3}
Let $X_i$ be independent Bernoulli random variables  following
the same distribution as random variable
 $X$, $X \sim b(p)$, where $0<p<1$.
Let $S_n = \sum_i X_i$.
Then, for any $r$ such that $p < r < 1$ we have the following.
\begin{equation}
\label{rche3}
 P( S_n \geq rn ) \leq \exp{( - D(r || p) n)}
                = \left[ \left( \frac{p}{r}     \right)^r
                         \left( \frac{1-p}{1-r} \right)^{1-r}
                  \right]^n .
\end{equation}
\end{lem}
\begin{proof}
Let $B(n,p,k) = \sum_{i=k}^n B(n,p;i) $.
For any $x \geq 1$, we have
\begin{eqnarray}
B(n,p,k) &\leq& \sum_{i=0}^{n} {n \choose i} p^{i} (1-p)^{n-i} x^{i-k} 
         \nonumber \\
         &\leq& x^{-k} \sum_{i=0}^{n} {n \choose i} p^{i} (1-p)^{n-i} x^{i} 
         \nonumber \\
         &\leq& x^{-k} \sum_{i=0}^{n} {n \choose i} (px)^{i} (1-p)^{n-i} 
         \nonumber \\
\label{rche3a}
         &\leq& x^{-k} (1+(x-1)p)^n.
\end{eqnarray}
For $r>p$ consider $x = (1-p)r /(p(1-r))$ and substitute for the $x$
of Eq.~(\ref{rche3a}). We obtain the following.
\begin{eqnarray}
B(n,p,k) 
    &\leq& x^{-k} (1+(x-1)p)^n  \nonumber \\
    &\leq& \left( \frac{(1-p)r}{p(1-r)}\right)^{-rn} \cdot
           \left( 1+ \left( \frac{(1-p)r}{p(1-r)}-1)p\right) \right)^{n} 
\label{rche3b}
\end{eqnarray}
The result then follows.
\end{proof}

We present  an alternative Chernoff bound formulation
which follows the simple case of Hoeffding bounds, where
$a_i = a =0$ and $b_i = b =1$. Naturally it applies
to Bernoulli or binary random variables (e.g. Rademacher).
%Rademacher 2X-1.

\begin{lem}
\label{lem4}
Let $X_i$ be independent Bernoulli random variables  following
the same distribution as random variable $X$, $X \sim b(p)$,
where $0<p<1$.
Let $S_n = \sum_i X_i$.
Then, for any $r$ such that $p < r < 1$ we have the following.
\begin{equation}
\label{elem4}
 P( S_n \geq rn ) \leq 
                  \exp{\left( -2n (r-p)^2 \right) }.
\end{equation}
\end{lem}

\begin{proof}
The proof follows the steps of the proof of Theorem~\ref{chthm1}
to Eq.(\ref{chel2a}).
\begin{equation}
\label{elem4a}
 P( S_n \geq nr ) =    P( t S_n    \geq t nr) 
                  \leq \frac{ E( e^{tS_n} )}{e^{nrt}} 
                 \leq e^{-nrt} E( e^{tS_n} ) 
\end{equation}
We then proceed differently as follows.
\begin{eqnarray}
 P( S_n \geq nr ) 
   &\leq& e^{-nrt} E( e^{tS_n} )  \nonumber \\
   &\leq& e^{-nrt} e^{npt} E( e^{t( S_n -np)} )  \nonumber \\
   &\leq& e^{-nrt + npt} E(\prod_i e^{t( X_i - p)} )  \nonumber \\
\label{elem4b}
   &\leq& e^{-nrt + npt} \prod_i E( e^{t( X_i - p)} )  
\end{eqnarray}
We note that r.v. $X_i -p$ is bounded and $E(X_i -p)= E(X_i) -p =p-p=0$.
Then,  Proposition~\ref{phoef2} that is being utilized in Hoeffding
bounds can be used to show the following.
\begin{equation}
\label{elem4c}
   E( e^{t( X_i - p)} ) \leq \exp{\left( \frac{t^2}{8} \right)}.  
\end{equation}
Eq.(\ref{elem4b}) by way of Eq.(\ref{elem4c}) yields the following.
\begin{eqnarray}
 P( S_n \geq nr ) 
   &\leq& e^{-nrt + npt} \prod_i E( e^{t( X_i - p)} )  \nonumber\\
   &\leq& e^{-nrt + npt} \prod_i \exp{\left( \frac{t^2}{8} \right)} \nonumber\\
   &\leq& e^{-nrt + npt}  \exp{\left(n \frac{t^2}{8} \right)}  \nonumber\\
\label{elem4d}
   &\leq& e^{-nrt + npt + \frac{n t^2}{8} }. 
\end{eqnarray}
Consider the exponent of Eq.(\ref{elem4d}):
$f(t)= -nrt+ npt + nt^2 /8$. Its first derivative is
$f^{'} (t) = -nr+ np + t/4$. Equating it to zero and solving for
$t$ we have that
$f^{'} (t) = 0 = -nr+ np + t/4$ yields 
\begin{equation}
\label{elem4e}
t = 4(r-p) .
\end{equation}
Given that $f^{''} (t) = 1/4 > 0$, we have a minimum at
$t=4(r-p)$ for $f(t)$.
Therefore Eq.(\ref{elem4d}) by way of Eq.(\ref{elem4e})
yields the following.
\begin{eqnarray}
 P( S_n \geq nr ) 
   &\leq& e^{-nrt + npt + \frac{n t^2}{8} }  \nonumber \\
   &\leq& e^{-nr\cdot 4(r-p) + np\cdot 4(r-p) + 
           \frac{n \cdot 16(r-p)^2}{8} }  \nonumber \\
\label{elem4f}
   &\leq& e^{-2n(r-p)^2 }.
\end{eqnarray}
Eq.(\ref{elem4f}) is Eq.(\ref{elem4}) as needed.
\end{proof}

The following  corollary is more widely known
than Lemma~\ref{lem4}.

\begin{cor}
\label{cor4}
Let $X_i$ be independent Bernoulli  random variables  following
the same distribution as random variable $X$, $X \sim b(p)$,
where $0<p<1$.
Let $S_n = \sum_i X_i$.
Then, for any $r$ such that $p < r < 1$ we have the following.
\begin{equation}
\label{ecor4}
 P( S_n - E(S_n) \geq rn ) \leq 
                  \exp{\left( -2n r^2 \right) }.
\end{equation}
\end{cor}

\begin{proof}
In Lemma~\ref{lem4} substitute $r+p$ for $r$.
Then
$ P( S_n \geq (r+p) n ) = P( S_n \geq rn +pn) 
                        = P( S_n -E(S_n) \geq rn)$
and then substitute $r+p$ for $r$ in Eq.(\ref{elem4})
to obtain Eq.(\ref{ecor4}). 
\end{proof}

The following Corollary can be obtained from Lemma~\ref{lem2}.
It provides a more tangible upper bound than the generic
one of the Lemma.

\begin{cor}
\label{cor2a}
Let $X_i$ be independent random variables  following
the same distribution as random variable  $X$, $X \sim b(p)$,
where $0<p<1$.
Let $S_n = \sum_i X_i$.
Then, for any 
%$r$ such that $p < r < 1$ 
%we have the following,
%after we substiture $r=(1+\delta ) p$, 
%$\delta > 0$
$\delta > 2e-1$.
we have the following,
\begin{equation}
\label{ecor2a}
