The following Corollary is also obtained from Lemma~\ref{lem2}.
Note that $\delta > 0$ is better than the $\delta$ used in
Corollary~\ref{cor2c} that follows it.

The following inequality will be used \cite{AS}, \cite{ES}, \cite{NIST}.

\begin{lem}
\label{ineq1}
For every $ x  > -1$ and $x\neq 0$  we have the following.
\[
\frac{x}{1+x} < \ln{(1+x)}  < x.
\]
For every $x>0$ we have the following.
\[
 \ln{(x)} \leq x-1.
\]
For every $ x  < 1$ and $x\neq 0$  we have the following.
\[
x < - \ln{(1-x)} < \frac{x}{1-x} .
\]
\end{lem}


\begin{cor}
\label{cor2b}
Let $X_i$ be independent random variables  following
the same distribution as random variable $X$, $X \sim b(p)$,
where $0<p<1$.
Let $S_n = \sum_i X_i$.
%Then for any $r$ such that $p < r < 1$ we have the following,
%after we substiture $r=(1+\delta ) p$, for any $\delta > 0$.
Then, for any  $\delta > 0$ we have the following.
\begin{equation}
\label{ecor2b}
%P( S_n \geq rn ) =
 P( S_n \geq (1+ \delta) pn ) 
 \leq \exp{\left( \frac{-\delta^2}{2+\delta} \cdot pn  \right)} .
\end{equation}
\end{cor}
\begin{proof}
We would like to upper bound the bound of Eq.(\ref{rche2}) 
of  Lemma~\ref{lem2}, as follows.
\[
\frac{e^{\delta }}{(1+\delta)^{(1+\delta )}} 
\leq \exp{ ( \frac{-\delta^2}{2+\delta} )}
\]
Consider function
$f(t)$ defined as follows.
\[
f(t) = \delta - (1+ \delta ) \ln{(1+ \delta)} + \frac{\delta^2}{2+\delta }.
\]
By Lemma~\ref{ineq1}
\[
\ln{(1+ \delta)} \geq \frac{2\delta}{2+\delta }.
\]
Therefore we have the following result
\[
f(t) \leq \delta - (1+ \delta ) \ln{(1+ \delta)} + 
\frac{\delta^2}{2+\delta }
\leq \frac{\delta (2 + \delta) -(1+\delta )(2 \delta) + \delta^2}
          {2+\delta } =0
\]
The Corollary then follows.
\end{proof}

