The following
Corollary can also be obtained from Lemma~\ref{lem2}.
It is similar to the one in \cite{AV} for the binomial case.

The following inequality will be used.
\begin{lem}
\label{ineq7}
For every $ 0 \leq    \delta \leq 1$ we have the following.
\[
(1+ \delta ) \ln{(1+ \delta )} \geq   \delta + {\delta}^2 /3 .
\]
\end{lem}
\begin{proof}
For $ 0 \leq     x \leq 1$,
\begin{eqnarray*}
 \ln{(1+ x )}      &=& x -x^2 /2 + x^3 /3 - x^4 /4 + \ldots \\
(1+x) \ln{(1+ x )} &=& x -x^2 /2 + x^3 /3 - x^4 /4 + \ldots \\
                   &+& x^2 - x^3 /2 + x^4 /3 - x^5 /4 + \ldots \\
(1+x) \ln{(1+ x )} &\geq& x + x^2 /2 - x^3 /6
\end{eqnarray*}
We can then conclude since $0 \leq  x \leq 1$ that
\[
(1+x) \ln{(1+ x )} \geq x + x^2 /2 - x^3 /6  \geq x +x^2 /2 - x^2 /6
 \geq x + x^2 /3 .
\]
Set $x=\delta$ and the result follows.
\end{proof}


\begin{cor}
\label{cor2c}
Let $X_i$ be independent random variables  following
the same distribution as random variable  $X$, $X \sim b(p)$,
where $0<p<1$.
Let $S_n = \sum_i X_i$.
%Then, for any $r$ such that $p < r < 1$ we have the following,
%after we substiture $r=(1+\delta ) p$, for any $0 < \delta < 1$.
Then,  for any $\delta$ such that 
$0 < \delta < 1$ we have the following.
\begin{equation}
\label{ecor2c}
 P( S_n   \geq rn ) =
 P( S_n  \geq (1+ \delta ) pn ) 
 \leq  \exp{\left( \frac{-\delta^2}{3} \cdot pn  \right)} .
\end{equation}
\end{cor}
\begin{proof}
By Lemma~(\ref{ineq7})
we have for $0 < \delta < 1$,
$(1+\delta) \ln{(1+ \delta )}  \geq \delta + \delta^2 /3$.
This results to
\[
\frac{e^{\delta }}{(1+\delta)^{(1+\delta )}} 
\leq
\frac{e^{\delta }}{e^{\delta + \delta^2 /3}} 
\leq
e^{ - \frac{\delta^2 }{3} }.
\]
The result follows.
Note that as proved, $\delta <1$. However, we can 
improve the upper bound $\delta \leq 1$ by a more
tedious approach. We show it below.
Consider as before in Corollary~\ref{cor2b},
function $f(t)$ ($t$ substitutes for $\delta$) 
defined as follows.
\[
f(t) = t - (1+ t ) \ln{(1+ t)} + \frac{t^2}{3}.
\]
We would like to show $f(t) \geq 0$.
We first calculate its first derivative.
\[
f^{'} (t) = 2t/3 - \ln{(1+t)}.
\]
We note that $f^{'} (0) = 0$ and 
             $f^{'} (1) < 0$.
In order to study the monotonicity of
$f^{'} (t)$ we go on calculating the second derivative.
\[
f^{''} (t) = 2/3 - 1/(1+t).
\]
We note that $f^{''} (0) < 0$ for $t \leq 1/2$
and          $f^{''} (1) > 0$ for $t > 1/2$.
This means that $f^{'} (t)$ is monotonically
decreasing for $t \leq 1/2$ and given $f^{'} (0) = 0$,
negative for $t \leq 1/2$,
and monotonically increasing and since 
$f^{'} (1) < 0$ also negative for $1> t >    1/2$.
One can also separately confirm that $f(1/2) < 0 $.
Thus $f(\delta ) \leq 0$ for all $0< \delta \leq 1$.
The $\delta > 0$ is needed since $r > p$.
\end{proof}


