\section{Derived left tails}


We proceed to deriving a Lemma identical to
Lemma~\ref{lem1} for the left tails. This is 
stated next.

\begin{lem}
\label{lem5}
Let $X_i$ be independent random variables  following
the same distribution as random variable $X$, $X \sim b(p)$,
where $0<p<1$.
Let $S_n = \sum_i X_i$.
Then, for any $r$ such that $0 < r < p$ we have the following.
\begin{equation}
\label{lche4}
 P( S_n \leq rn ) \leq \exp{( - D(r || p) n)}
                = \left[ \left( \frac{p}{r}     \right)^r
                         \left( \frac{1-p}{1-r} \right)^{1-r}
                  \right]^n .
\end{equation}
\end{lem}


Sometimes $r=p-t$, and the bound $0<r<p$ 
becomes $0<p-t <p$ or equivalently $0 < t < p$. 

\begin{proof}(Of Eq.~(\ref{lche4}))
$ $ \\ $ $
{\bf Method 1.}
A simple argument works as follows: the upper bound
on the number of successes generates a corresponding
lower bound on the number of failures. Thus
for $F_i = 1 - X_i $, we have $\sum F_i = n - \sum_i X_i$
or equivalently $Y_n = n - S_n$. Therefore
\[
P( S_n \leq rn ) 
       = P( n- S_n \geq n(1-r) ) 
       = P( Y_n \geq n(1-r) )
\]
The latter bound by Lemma~\ref{lem1} is 
bounded above by Eq.(\ref{rche1}) adjusting
it with $r$ replaced by the $1-r$
of $Y_n \geq n(1-r)$ and $p$ by $1-p$ to 
account for the failures not the successes of random
variable $Y_n$. The end result is that
\[
 P( S_n \leq rn ) \leq \exp{( - D((1-r) || (1-p)) n)} .
\]
However
$ D((1-r) || (1-p)) =   D(r || p) $ and therefore
\[
 P( S_n \leq rn ) \leq \exp{( - D((1-r) || (1-p)) n)} 
 = D(r || p) .
\]
\bigskip
$ $ \\ $ $
{\bf Method 2.}
Now let us reprove it following the method
of the proof of Lemma~\ref{lem1}.
Consider $t>0$, and apply the Chernoff trick and
finally use Markov's inequality as we did earlier.
\begin{eqnarray}
 P( S_n \leq nr ) &=&    P(  t S_n   \leq  t nr)  \nonumber \\
                  &=&    P( -t S_n   \geq -t nr)  \nonumber \\
                 &=&    P( e^{-tS_n} \geq e^{-nrt} )\nonumber  \\
                 &\leq& \frac{ E( e^{tS_n} )}{e^{nrt}} \nonumber \\
                 &\leq& e^{nrt} E( e^{-tS_n} ) \nonumber \\
                 &\leq& e^{nrt} (E( e^{-Xt} ))^n 
\label{che4a}
\end{eqnarray}
We calculate
 $ E( e^{-tX} ) 
         = 1 + p( e^{-t} -1 ) \leq e^{pe^{-t} -p}$.
The rest of the calculation are similarly to the ones before
\begin{eqnarray}
 P( S_n \leq nr ) 
   &\leq& \inf_{t>0} \left( e^{rt}   (1 + p( e^{-t} -1 )) \right)^n 
      \nonumber \\
\label{che4b}
   &\leq& \inf_{t>0} \left(  \exp{(f(t))} \right)^n  .
\end{eqnarray}
As indicated by Eq.~(\ref{che4b}),
$f(t) = \ln{(1 + p( e^{-t} -1 ))} +rt$.
Consider $f^{'} (t) = -pe^{-t} / (1+p^{-t} -p) +r$.
Equating to zero $f^{'} (t)=0$ and solving for $t$
we obtain $e^{-t} = (1-p)r/(p(1-r))$.
Continuing with the second derivative we find
$f^{''} (t) = p(1-p) e^{-t} / (1+pe^{-t} -p)^2 >0$.
Therefore $f(t)$ has a minimum for $ e^{-t} = (1-p)r/(p(1-r))$.
We then continue with Eq.~(\ref{che4b}) as follows. 
%noting $ 1 + p( e^{-t} -1 ) \leq \exp{(pe^{-t} -p)}$.
\begin{eqnarray}
 P( S_n \leq nr ) 
\label{che4c}
   &\leq& \inf_{t>0} \left( e^{rt} (1 + p( e^{-t} -1 )) \right)^n 
\end{eqnarray}
The term $\exp{(rt)}$ for $e^{-t} = (1-p)r/(p(1-r))$
is as follows.
\begin{equation}
\label{che4d}
\exp{(rt)} = \frac{p^r (1-r)^r}{(1-p)^r r^r}.
\end{equation}
Likewise the other term is as follows.
\begin{equation}
\label{che4e}
(1 + p( e^{-t} -1 )) = \frac{p(1-r)-p^2 (1-r) +p(1-p)r}{p(1-r)}
 = \frac{1-p}{1-r}
\end{equation}
Therefore we have the following for the quatinty below.
\begin{equation}
\label{che4f}
e^{rt} \cdot (1 + p( e^{-t} -1 ))
= \frac{1-p}{1-r} \cdot  \frac{p^r (1-r)^r}{(1-p)^r r^r}
                = \left[ \left( \frac{p}{r}     \right)^r
                         \left( \frac{1-p}{1-r} \right)^{1-r}
                  \right]^n .
\end{equation}
\end{proof}


We generate one more bound below.


\begin{lem}
\label{lem6}
Let $X_i$ be independent random variables  following
the same distribution as random variable $X$, $X \sim b(p)$,
where $0<p<1$.
Let $S_n = \sum_i X_i$.
Then, 
for any $r$ such that $0 < r < p$ or, equivalently,
for any $\delta$ such that  $0< \delta < 1$ we have
the following.
\begin{equation}
\label{lche5}
 P( S_n \leq rn ) =
 P( S_n \leq (1- \delta) pn ) 
   \leq            \left(  \frac{e^r \cdot p^r}{e^p \cdot r^r} \right)^n 
     =             \left(  \frac{e^{-\delta }}
                                  {(1-\delta)^{(1-\delta )}} 
                     \right)^{pn} 
\end{equation}
\end{lem}
\begin{proof}
We calculated earlier
 $ E( e^{-tX} ) 
         = 1 + p( e^{-t} -1 ) \leq e^{pe^{-t} -p}$.
By way of Eq.(\ref{che4b}) we have the following.
\begin{eqnarray}
 P( S_n \leq nr ) 
   &\leq& \inf_{t>0} \left( e^{rt}   (1 + p( e^{-t} -1 )) \right)^n 
      \nonumber \\
\label{che5a}
   &\leq& \inf_{t>0} \left( \exp{( pe^{-t} -p+rt)} \right)^n 
      \\
\label{che5b}
   &\leq& \inf_{t>0} \left(  \exp{(f(t))} \right)^n 
\end{eqnarray}
By Eq.~(\ref{che5a}) and Eq.~(\ref{che5b}) we
have $f(t) =  pe^{-t} -p+rt$. Since $f^{'} (t) = r-pe^{-t}$,
setting $f^{'} (t) = 0$ we obtain $t = \ln{(p/r)}$.
Moreover, $f^{''}(t) = p e^t$ is equal to
$f^{''} (  \ln{(p/r)} ) =r > 0$. Therefore $f(t)$
has a minimum at $t = \ln{(p/r)}$. Substituting this
value for $t$ in Eq.(\ref{che5a}) the following
is obtained.

\begin{eqnarray}
 P( S_n \leq nr ) 
   &\leq& \inf_{t>0} \left( \exp{( pe^{-t} -p+rt)} \right)^n 
      \nonumber \\
   &\leq&            \left(  \exp{( p r/p -p +r \ln{(p/r)}} \right)^n 
      \nonumber \\
   &\leq&            \left(  \frac{e^r \cdot p^r}{e^p \cdot r^r} \right)^n 
\label{che5c}
\end{eqnarray}
Finally we substitute $r=(1 - \delta ) p$ in Eq.~(\ref{che5c})
to obtain Eq.(\ref{lche5}).
\begin{eqnarray}
 P( S_n \leq nr ) 
   &\leq&            \left(  \frac{e^{(1-\delta )p} 
                              \cdot 
                                   p^{(1-\delta )p}}
                                  {e^p \cdot ((1-\delta)p)^{(1-\delta ) p}} 
                     \right)^n  \nonumber \\
\label{lche5d}
   &\leq&            \left(  \frac{e^{-\delta }}
                                  {(1-\delta)^{(1-\delta )}} 
                     \right)^{pn} 
\end{eqnarray}
\end{proof}

There is a weaker but more easier to deal bound for small
$p$. This
is shown next.
It is similar to the one in \cite{AV} for the binomial case.

The following inequality will be needed.

\begin{lem}
\label{ineq6}
For every $0 \leq \delta < 1$ we have the following.
\[
(1- \delta ) \ln{(1- \delta )} \geq  - \delta + {\delta}^2 /2.
\]
\end{lem}
\begin{proof}
%For $0< x < 1$,
For $0\leq x < 1$,
\begin{eqnarray*}
 \ln{(1- x )}      &=&  -  \sum_{i=1}^{\infty} x^i / i \\
                   &=& -x -x^2 /2 - x^3 /3 - x^4 /4 - \ldots \\
(1-x) \ln{(1- x )} &=& -x -x^2 /2 - x^3 /3 - x^4 /4 - \ldots \\
                   &+& +x^2 + x^3 /2 + x^4 /3 + x^5 /4 + \ldots \\
(1-x) \ln{(1- x )} &=& -x + x^2 /2 + x^2 /6 + \ldots
\end{eqnarray*}
The missing terms in the last form of the equation are positive.
We can then conclude
\[
(1-x) \ln{(1- x )} \geq -x + x^2 /2 + x^2 /6  \geq -x + x^2 /2
\]
\end{proof}


\begin{cor}
\label{cor5a}
Let $X_i$ be independent random variables  following
the same distribution as random variable $X$, $X \sim b(p)$,
where $0<p<1$.
Let $S_n = \sum_i X_i$.
Then, for any $\delta$ such that
 $0 < \delta < 1$ we have the following.
\begin{equation}
\label{ecor5a}
% P( S_n   \leq rn ) =
 P( S_n  \leq (1- \delta ) pn ) 
 \leq  \exp{\left( \frac{-\delta^2}{2} \cdot pn  \right)} .
\end{equation}
\end{cor}
\begin{proof}

By Lemma~(\ref{ineq6})
we have for every $0 < \delta < 1$,
$(1-\delta) \ln{(1- \delta )}  \geq -\delta - \delta^2 /2$.
This results to
\[
\frac{e^{-\delta }}{(1-\delta)^{(1-\delta )}} 
\leq
\frac{e^{-\delta }}{e^{-\delta - \delta^2 /2}} 
\leq
e^{ - \frac{\delta^2 }{2} }.
\]
The result follows.
\end{proof}

