\begin{cor}
\label{cor2d}
Let $X_i$ be independent random variables  following
the same distribution as random variable $X$, $X \sim b(p)$,
where $0<p<1$.
Let $S_n = \sum_i X_i$.
Then, for any $\delta$ such that $0 < \delta <1$ we have the following,
\begin{equation}
\label{ecor2d}
% P( |S_n -np|  \geq (r-1)n ) =
 P( |S_n -np|  \geq \delta pn ) 
 \leq 2 \cdot \exp{\left( \frac{-\delta^2}{3} \cdot pn  \right)} .
\end{equation}
\end{cor}
\begin{proof}
We have the following
\[
 P( |S_n -np|  \geq \delta pn ) 
 =
 P( S_n -np  \geq   \delta pn ) 
 +
 P( S_n -np  \leq - \delta pn ) 
 =
 P( S_n   \geq  (1+ \delta ) pn ) 
 +
 P( S_n   \leq  (1- \delta ) pn ) 
\]
By Corollary~(\ref{cor2c}) we bound 
$  P( S_n   \geq  (1+ \delta ) pn )$.
By Corollary~\ref{cor5a}  we bound 
$ P( S_n  \leq (1 - \delta ) pn ) $.
Simple manipulations show
$\exp{\left( \frac{-\delta^2}{2} \right)} <
  \exp{ ( \frac{-\delta^2}{3} )}$.
The result then follows.
\end{proof}

