\section{Hoeffding's method}

We now present Theorem~1 and Theorem~2 of Hoeffding \cite{H63}.
The work \cite{H63} deals with random variables that are not
necessarily Bernoulli but are bounded e.g. $0 \leq X_i \leq 1$
or $a_i \leq X_i \leq b_i$. Theorem~1 \cite{H63}
for the case of Bernoulli trials takes the form of 
Corollary~\ref{cor2e} associated with a Chernoff bound.

That's why several times the terms Chernoff and Hoeffding 
refer to the same bound. Theorem~1 of \cite{H63} is the
strongest among the Hoeffding bounds.
The bounds are sufficient for large deviations.
Otherwise one  can use bounds available in \cite{B85}
and \cite{Feller1} \cite{Feller2}. Angluin-Valiant bounds \cite{AV} are
weaker but more useful; the latter are or may be more useful
for small $p$.

\section{Derived right tails}

Note that all random variables $X$ in the two theorems
that follow are to have finite first and second moments.
This Theorem~1 of \cite{H63} follows.
\begin{thm}
\label{hoef1}
Let $X_i$ be an independent random variable, $i=1, \ldots , n$.
Let $S_n = \sum_i X_i$, $\bar{X}=S_n /n$
and $p=E(\bar{X})$.
Then for any $h$ such that $0 < h < 1-p$ we have the following.
\begin{eqnarray}
 P( \bar{X}       -p  \geq h) )  
%   &=& P( \frac{S_n}{n} -p  \geq h) )  
%       \nonumber \\
%   &=&P( S_n  - E(S_n )  \geq hn         )  
%       \nonumber \\
%   &=& P( S_n  -pn  \geq hn         )  
%       \nonumber \\
   &=& P( S_n \geq (p+h)n ) 
       \nonumber \\
&\leq& \exp{( - D((p+h) || p) n)}
       \nonumber \\
\label{ehoef1}
     &\leq&     \left[ \left( \frac{p}{p+h}     \right)^{p+h}
                       \left( \frac{1-p}{1-p-h} \right)^{1-p-h}
               \right]^n .
\end{eqnarray}
\end{thm}

Note that if $h > 1-p$, then Eq.~(\ref{ehoef1}) remains true,
and for $h=1-p$, the right-hand side can be replaced by
the limit $ h \rightarrow 1-p$ which is $p^n$.

We provide a proof below for the Theorem following the techniques
of the Chernoff's method also attributed to Cram{\'e}r \cite{C38}.
The theorem also appears as Theorem 5.1 in \cite{McD}.

\begin{proof}
In order to prove Eq.(\ref{ehoef1}) we  perform the following
transformation, using in the last step Markov's inequality,
and before that the monotonically increasing function
$X \mapsto e^{tX}$. Consider a $t>0$ and the monotonically
increasing function $f(x) = e^{tx}$. Note that $0 < h < 1-p$
below.
\begin{eqnarray}
 P( \bar{X}       -p  \geq h) )   &=&
 P( \frac{S_n}{n} - p \geq h )  \nonumber \\
   &=& P( S_n  - E(S_n )  \geq hn         )    \nonumber \\
   &=& P( S_n  -pn  \geq hn         )    \nonumber \\
    &=&    P( S_n   \geq (p+h)n ) 
\\
%P( t S_n    \geq t nr)  \nonumber \\
    &=&    P( e^{tS_n} \geq e^{t(p+h)} )\nonumber  \\
    &\leq& \frac{ E( e^{tS_n} )}{e^{n(p+h)t}} \nonumber \\
\label{hoe1a}
    & =  & e^{-n(p+h)t} E( e^{t S_n} ) 
\end{eqnarray}
We then examine $ E( e^{tS_n} )$. 
\begin{eqnarray}
 E( e^{tS_n} ) 
     &=& E( e^{t \sum_i X_i } ) \nonumber \\
\label{hoe1b}
     &=& \prod_{i=1}^{n} E( e^{t X_i} ) 
\end{eqnarray}
By the convexity of function $f(x) = \exp{(tx)}$ we have the
following: the line segment connecting the points
$(a, f(a))$ and $(b,f(b))$ lies over $f(x)$. The equation
of the line segment is as follows.
\begin{equation}
\label{hoe1c}
y- e^{ta} = \frac{e^{tb}-e^{ta}}{b-a} (x-a).
\end{equation}
Therefore,
\begin{equation}
\label{hoe1d}
y = e^{tb} \frac{x-a}{b-a} + e^{ta} \frac{b-x}{b-a} .
\end{equation}
Because of the convexity of $f$ we also have the following.
\begin{equation}
\label{hoe1e}
e^{tx} \leq y = e^{tb} \frac{x-a}{b-a} + 
                e^{ta} \frac{b-x}{b-a} .
\end{equation}
We now consider $E(e^{tX_i})$. We have the following.
\begin{equation}
\label{hoe1f}
E(e^{t X_i}) \leq  e^{tb} \frac{E(X_i)-a}{b-a} + 
                   e^{ta} \frac{b-E(X_i)}{b-a} .
\end{equation}
Because $0\leq X_i \leq 1$,  $a=0$ and $b=1$,
Eq.(\ref{hoe1f}) can be simplified.
\begin{equation}
\label{hoe1g}
E(e^{t X_i}) \leq  e^{t} E(X_i ) + e^{0} (1-E(X_i )) 
             \leq  e^t p_i + 1 - p_i ,
\end{equation}
where $p_i = E(X_i )$.
Then we plug Eq.(\ref{hoe1g}) into Eq.(\ref{hoe1b}).
We derived the following.
\begin{eqnarray}
 E( e^{tS_n} ) 
     &=& \prod_{i=1}^{n} E( e^{t X_i }) \nonumber \\
\label{hoe1h}
     &=& \prod_{i=1}^{n} (e^t p_i + 1 - p_i )  
\end{eqnarray}
Given that geometric means are at most their arithmetic means
we have the following.
\begin{eqnarray}
\label{hoe1i}
     \left( \prod_{i=1}^{n} (e^t p_i + 1 - p_i ) \right)^{1/n}
      \leq
                     \sum_i \frac{(e^t p_i + 1 - p_i )}{n}
      \leq
                     (e^t p + 1 - p ).
\end{eqnarray}
Therefore Eq.(\ref{hoe1i}) into Eq.(\ref{hoe1h}) yields
the following.
\begin{eqnarray}
 E( e^{tS_n} ) 
     &=& \prod_{i=1}^{n} (e^t p_i + 1 - p_i )  \nonumber \\
\label{hoe1j}
     &\leq& (e^t p + 1 - p )^n  \nonumber 
\end{eqnarray}

From Eq.(\ref{hoe1a}) utilizing Eq.(\ref{hoe1j}) we finally
derive the following.
\begin{eqnarray}
 P( \frac{S_n}{n} - p \geq h ) 
    &\leq& e^{-n(p+h)t} E( e^{t S_n} )  \nonumber \\
\label{hoe1k}
    &\leq& e^{-n(p+h)t} (e^t p + 1 - p )^n  \\
    &\leq& \exp{(-n(p+h)t + n \cdot \ln{(e^t p + 1 - p )})}  
           \nonumber \\
\label{hoe1l}
    &\leq& \exp{(g(t)) } 
\end{eqnarray}

We consider the monotonicity of function $g(t)$.
\begin{eqnarray}
\label{hoe1m}
g^{'} (t ) = - (p+h)n + n p e^t / \ln{(1-p+pe^t )}. 
\end{eqnarray}
Setting $g^{'} (t ) = 0$ and solving for $t$ we have,
\begin{equation}
\label{hoe1n}
t_0 = \ln{\frac{(p+h)(1-p)}{p(1-p-h)}},
\quad\quad
e^{t_0} = \frac{(p+h)(1-p)}{p(1-p-h)}.
\end{equation}
Moreover $ (p+h)(1-p) \geq p(1-p-h)$ and thus $t_0 > 0$,
since $h < 1-p$ and thus $1-p-h >0$.
Substituting Eq.(\ref{hoe1n}) for $t$ in $g(t)$ in
Eq.(\ref{hoe1l}) the result in the form of equation
Eq.(\ref{ehoef1}) follows.
\end{proof}

Theorem~1 of \cite{H63}
includes (weaker) upper bounds of Eq.(\ref{ehoef1})
of the form $\exp{(-nh^2 k(p))}$, where
\[
 k(p) = \frac{1}{1-2p} \ln{ \frac{1-p}{p} } ,
\]
for $ 0 < p < 1/2$, and
\[
 k(p) = \frac{1}{2p(1-p)} ,
\]
for $1/2 \leq p < 1$.
The proof arguments are tedious and we refer to \cite{H63}.
Furthermore, a weaker bound  of the form
$\exp{(-2n h^2 )}$ can also be derived. This can be
established also through Theorem~2 of \cite{H63}
that is stated and proved below.




