\begin{prp}[Hoeffding \cite{H63}, Eq (4.16)]
\label{phoef2}
For a random variable $X$ such that $a \leq X \leq b$
with $E(X) = 0 $ and for any $t > 0$, we have the 
following.
\[
E [ e^{tX} ] \leq \exp{\left( \frac{t^2 (b-a)^2 }{8} \right) } .
\]
\end{prp}
\begin{proof}
The function $f(x) = \exp{(tx)}$ is a convex function.
Therefore  by Eq.(\ref{hoe1e}), we have the following.
\[
 e^{tX} \leq \frac{x-a}{b-a} e^{tb} +  \frac{b-x}{b-a} e^{ta} .
\]
Moreover, $E(X)=0$. By taking expectations on both sides we
conclude the following.
\begin{eqnarray*}
 E( e^{tX} ) &\leq& E( \frac{x-a}{b-a} e^{tb} +  \frac{b-x}{b-a} e^{ta} ) \\
             &\leq& \frac{E(x)-a}{b-a} e^{tb} +  \frac{b-E(x)}{b-a} e^{ta}\\
             &\leq& \frac{0   -a}{b-a} e^{tb} +  \frac{b-0   }{b-a} e^{ta}\\
             &\leq& \frac{-a}{b-a} e^{tb} +  \frac{b}{b-a} e^{ta}
\end{eqnarray*}
