%This is because the difference of the two sides is non-positive.
%\begin{eqnarray*}
% var(X) - E[(X-c)^2 ] &=& E[X^2] - (E[X])^2 - E[X^2 ] - c^2 + 2c E[X] \\
%                      &=&        - (E[X])^2           - c^2 + 2c E[X] \\
