%                                   \frac{(b-a)^2}{4} .
%\]
%  IGNORE ends here for the time being
Consider
\begin{eqnarray*}
\label{etx}
E( e^{tX} ) &\leq& \exp{\left( \lg{\left(
                          \frac{-a}{b-a} e^{tb} +  \frac{b}{b-a} e^{ta}
                                 \right)
                                } \right)}
              =  \exp{(\ln{(g(t))})} .
\end{eqnarray*}
The function $g(t)$ will be rewritten as
$f(t) = \ln{(g(t))}$, and furthermore
by some change of variables,
using $p=b/(b-a)$ and therefore $1-p = -a/(b-a)$, and $x=(b-a)t$.
Then we have, after renaming variables with substitution, the following.
Note that $ta = (x/(b-a)) \cdot a =(x/(b-a)) \cdot (p-1)(b-a)=x(p-1)$.
\begin{eqnarray}
\label{fofx}
f(t) &=& \ln{(g(t))} \nonumber \\
f(t) &=& \ln{\left( \frac{-a}{b-a} e^{tb} +  \frac{b}{b-a} e^{ta} 
             \right)} \nonumber \\
     &=& \ln{\left( e^{ta} \left(
                \frac{-a}{b-a} e^{t(b-a)} +  \frac{b}{b-a} 
                \right)\right)} \nonumber \\
     &=& \ln{\left( e^{ta} \left(
                (1-p)  e^{t(b-a)} +  p
                \right)\right)} \nonumber \\
     &=& \ln{\left( e^{ta} \left(
                (1-p)  e^{x} +  p
                \right) \right)}\nonumber  \\
     &=& ta + \ln{\left( (1-p)  e^{x} +  p \right) } \nonumber \\
f(x) &=& x(p-1) + \ln{\left( (1-p)  e^{x} +  p \right) } 
\end{eqnarray}
Function $f(x)$ as indicated in Eq~\ref{fofx} has the
following properties:
$f(0)=0$ and $f^\prime (0)=0$.
We point out that
\[
 f^\prime (x) = p-1 + \frac{(1-p) e^x}{p+(1-p) e^x },
\]
and
\[
 f'' (x) =
          \frac{ (1-p) e^x (p+(1-p) e^x) -(1-p)e^x (1-p)e^x
                }{
                (p+(1-p) e^x )^2
                }
         =
          \frac{ p(1-p) e^x }{ (p+(1-p) e^x )^2 }.
\]
Using Taylor's formula we obtain
\[
 f(x) = f(0) + f^\prime (0) + f^{''} (r) x^2 / 2! ,
\]
for some $r$. We are going to find the maximum of 
$f'' (x)$. We observe that $f'' (x) = A \cdot B$, where
$A+B=1$, with $A=(p)/(p+(1-p) e^x )$ and 
              $B= ((1-p) e^x )/ (p+(1-p) e^x )$.
Therefore the second derivative is maximized for $A=B=1/2$
and $f'' (x) \leq 1/4$.
This implies.
\[
 f(x) = f(0) + f^\prime (0) + f^{''} (r) x^2 / 2!  \leq
  0 + 0 + (1/4) (1/2) x^2 \leq x^2 / 8.
\]
Moving backwards, Equation~(\ref{etx}) then yields, after
recovering the original variable names,
\begin{eqnarray*}
E( e^{tX} ) &\leq& \exp{(\ln{(g(t))})}  \\
            &\leq& \exp{
                        (  x^2 / 8 )
                       } \\
            &\leq& \exp{\left(
                         (b-a) t^2 / 8
                        \right)
                       } .
\end{eqnarray*}
\end{proof}
