Theorem~2 of \cite{H63} is stated and proved below.
Whereas in Theorem~1 of \cite{H63} variables
$X_i$ were bounded in range by 0 and 1, the
bounds next are variable, in the sense  that
$a_i \leq X_i \leq b_i$.

\begin{thm}
\label{hoef2}
Let $X_i$ be an independent random variable, $i=1, \ldots , n$.
Let $S_n = \sum_i X_i$, $\bar{X}=S_n /n$, where
$a_i \leq X_i \leq b_i$
and $p=E(\bar{X})$ and $E(S_n) = np$.
Then for any $h$ such that $0< h < 1-p  $ we have the following.
\begin{eqnarray}
\label{ehoef2}
 P( \bar{X}       -p  \geq h) )  
        %&=&
       % P( \frac{S_n}{n} -p  \geq h) )  =
  %        P( S_n  - E(S_n )  \geq hn         )  \nonumber \\
   % &=& P( S_n  -pn  \geq hn         )    \nonumber \\
   = P( S_n \geq (p+h)n ) 
   \leq 
          \exp{\left( 
           \frac{-2n^2 h^2 }{\sum_{i=1}^{n} (b_i - a_i )^2 }
           \right)}.
\end{eqnarray}
\end{thm}

\begin{proof}
In order to prove Eq.(\ref{ehoef2}) we  work out similarly
to the other bound of Eq.(\ref{ehoef1}).
Consider a $t>0$ and the monotonically
increasing and convex function $f(x) = e^{tx}$. 
\begin{eqnarray}
 P( \bar{X}       -p  \geq h) )  
    &=& P( S_n  - E(S_n )  \geq hn )  \nonumber \\
%    &=& P( \frac{S_n}{n} - p \geq h ) \nonumber \\
%    &=& P( S_n   \geq (p+h)n ) \\
%P( t S_n    \geq t nr)  \nonumber \\
    &=&    P( e^{t( S_n -E(S_n))} \geq e^{thn)} )\nonumber  \\
    &\leq& \frac{ E( e^{t(S_n - E(S_n ))} )}{e^{htn}} \nonumber \\
\label{hoe2a}
    &\leq& e^{-htn} E( e^{t (S_n -E(S_n ))} )  \\
    &\leq&\inf_{h>0}  e^{-htn} E( e^{t (S_n -E(S_n ))} )  \nonumber
\end{eqnarray}
We then examine $ E( e^{t( S_n - E(S_n ))} )$. Note that $X_i$
are independent random variables for Eq.(\ref{hoe2b}) to be valid.
\begin{eqnarray}
 E( e^{t( S_n - E(S_n))} ) 
     &=& E( e^{t ( \sum_i X_i -E( \sum_i X_i )) } ) \nonumber \\
\label{hoe2b}
     &=& \prod_{i=1}^{n} E( e^{t (X_i - E(X_i ))} ) 
\end{eqnarray}
Since $E( X_i -E(X_i )) = 0$, the conditions of 
Proposition~\ref{phoef2} are satisfied.
Therefore 
\begin{equation}
\label{hoe2c}
E( e^{t (X_i -E(X_i ))} \leq 
\exp{\left( \frac{t^2 (b_i -a_i )^2 }{8} \right) } .
\end{equation}
Eq.(\ref{hoe2a}) by way of Eq.(\ref{hoe2b}) and
Eq.(\ref{hoe2c}) yields the following.
\begin{eqnarray}
 P( \bar{X}       -p  \geq h) )  
    &\leq&\inf_{h>0}  e^{-htn} 
                      E( e^{t (S_n -E(S_n ))} )  
      \nonumber \\
    &\leq&\inf_{h>0}  e^{-htn} \prod_{i=1}^{n} 
                      E( e^{t (X_i - E(X_i ))} ) 
      \nonumber \\
    &\leq&\inf_{h>0}  e^{-htn} \prod_{i=1}^{n} 
                      \exp{\left( \frac{t^2 (b_i -a_i )^2 }{8} \right) }
      \nonumber \\
\label{hoe2d}
    &\leq&\inf_{h>0}  \exp{\left(
                   -htn + t^2 \sum_{i=1}^{n} \frac{(b_i -a_i )^2 }{8}  
                           \right) } \\
\label{hoe2e}
    &\leq&\inf_{h>0}  \exp{\left( g(t)
                           \right) }
\end{eqnarray}

%HERE
Function $t(t)$ is a parabola. Its minimum is for 
\begin{equation}
\label{hoe2f}
t_0 =  \frac{4hn}{ \sum_{i=1}^{n} (b_i -a_i )^2 }
\end{equation}
Substituting $t_0$ for $t$ in Eq.(\ref{hoe2d}) yields
the following equation.
\begin{eqnarray}
 P( \bar{X}       -p  \geq h)   
    &\leq&\inf_{h>0}  \exp{\left(
                   -htn + t^2 
                          \sum_{i=1}^{n} \frac{(b_i -a_i )^2 }{8}  
                           \right) } \\
      \nonumber \\
\label{hoe2g}
    &\leq&            \exp{\left( - \frac{2h^2 n^2}
                                    {\sum_{i=1}^{n} (b_i -a_i )^2 }
                           \right)}.
\end{eqnarray}
The proof  is complete as Eq.(\ref{hoe2g}) is Eq.(\ref{ehoef2}).
\end{proof}

