% RMSD is calculated as the square root of the average squared distance between corresponding atoms in two protein structures:
% \begin{equation}
% \text{RMSD}(\mathbf{v}, \mathbf{w}) = \sqrt{ \frac{1}{n} \sum_{i=1}^{n} \| v_i - w_i \|^2 },
