  \item For each even $n$, the atoms at positions $(m,n,1)$, $(m,n,2)$, $(m,n,3)$, and $(m,n,4)$ are designated as \emph{target atoms}, marked in purple in Fig.~\ref{fig:XC_growing}. There are two control bits: the first consists of atoms at $(m,n-1,4)$ and $(m,n-1,6)$, controlling the targets at $(m,n,1)$ and $(m,n,2)$; the second consists of atoms at $(m,n+1,1)$ and $(m,n+1,5)$, controlling the targets at $(m,n,3)$ and $(m,n,4)$. The gate operation $U_{2c4t}$ is applied.

  \item For each even $n$, the atoms at $(m,n,5)$ and $(m,n,6)$ are designated as \emph{target atoms}, marked in purple in Fig.~\ref{fig:XC_growing}. There are again two control bits: the first consists of atoms at $(m,n,1)$, $(m,n,2)$, and $(m,n,3)$, controlling the target at $(m,n,5)$; the second consists of atoms at $(m,n,2)$, $(m,n,3)$, and $(m,n,4)$, controlling the target at $(m,n,6)$. The gate operation $U^H_{2c2t}$ is applied.

  \item For each odd $n$, the atoms at positions $(m,n,1)$, $(m,n,2)$, $(m,n,3)$, and $(m,n,4)$ are designated as \emph{target atoms}, marked in purple in Fig.~\ref{fig:XC_growing}. There are two sets of control bits: the first consists of atoms at $(m,n-1,4)$ and $(m,n-1,6)$, controlling the targets at $(m,n,1)$ and $(m,n,2)$; the second consists of atoms at $(m,n+1,1)$ and $(m,n+1,5)$, controlling the targets at $(m,n,3)$ and $(m,n,4)$. The gate operation $U_{2c4t}$ is applied.

  \item For each odd $n$, the atoms at $(m,n,5)$ and $(m,n,6)$ are designated as \emph{target atoms}, marked in orange in Fig.~\ref{fig:XC_growing}. There are again two control bits: the first consists of atoms at $(m,n,1)$, $(m,n,2)$, and $(m,n,3)$, controlling the target at $(m,n,5)$; the second consists of atoms at $(m,n,2)$, $(m,n,3)$, and $(m,n,4)$, controlling the target at $(m,n,6)$. The gate operation $U^H_{2c2t}$ is applied.
\end{enumerate}


