\section{Setting}

\subsection{Graphon particle system and approximating finite particle system}

For a fixed $T > 0$, we study a graphon particle system with common noise:
\begin{align}   \label{eq : graphon particle system with common noise}
    dX_u(t) &= \phi_p \bigg(X_u(t), ~ \int_0^1 G_{u, v} \mu_v(t) dv \bigg) dt + \phi_b \bigg(X_u(t), ~ \int_0^1 G_{u, v} \mu_v(t) dv \bigg) dB_u(t)
    \\
    & \qquad \qquad \qquad + \phi_w \bigg(X_u(t), ~ \int_0^1 G_{u, v} \mu_v(t) dv \bigg) dW(t), \qquad \forall \, u \in [0, 1], \qquad t \in (0, T].    \nonumber
\end{align}
Here, $\{B_u\}_{u \in [0, 1]}$ are independent $d$-dimensional Brownian motions, also independent of another $m$-dimensional Brownian motion $W$, modeling a common noise. We assume that the initial distributions $\{X_u(0)\}_{u \in [0, 1]}$ are independent $\R^d$-valued random variables, independent of $\{B_u\}_{u \in [0, 1]}$ and $W$. The measurable mapping $[0, 1] \times [0, 1] \ni (u, v) \mapsto G_{u, v} \in [0, 1]$, satisfying the symmetry $G_{u, v} = G_{v, u}$ for each $u, v \in [0, 1]$, is called a graphon, and $\mu_u(t)$ is the conditional probability distribution of $X_u(t)$ given $W$ for every $u \in [0, 1]$ and $t \in [0, T]$. Since each $\mu_u(t)$ is a probability measure, the integral $\int_0^1 G_{u, v} \mu_v(t) dv$ should be understood as a positive measure in the sense of
\begin{align*}
    \bigg(\int_0^1 G_{u, v} \mu_v(t) dv \bigg)(A) &:= \int_0^1 G_{u, v} \big(\mu_v(t)(A)\big) dv
\end{align*}
for any Borel-measurable set $A \in \mathcal{B}(\R^d)$. The functions $\phi_{\alpha}$ are defined on $\R^d \times \mathcal{M}(\R^d)$ for $\alpha = p, b, w$, where we denote $\mathcal{M}(\R^d)$ the collection of positive finite measures on $\R^d$.

The system \eqref{eq : graphon particle system with common noise} can be approximated by the finite particle system with $n$ particles:
\begin{align}   
    dX^n_i(t) = \phi_p \bigg(X^n_i(t),  ~\frac{1}{n} \sum_{j=1}^n G^n_{i, j} \delta_{X^n_j(t)} \bigg) dt 
    & + \phi_b \bigg(X^n_i(t),  ~\frac{1}{n} \sum_{j=1}^n G^n_{i, j} \delta_{X^n_j(t)} \bigg) dB_{{i/n}}(t)     \label{eq : finite particle system with common noise}
    \\
    & + \phi_w \bigg(X^n_i(t),  ~\frac{1}{n} \sum_{j=1}^n G^n_{i, j} \delta_{X^n_j(t)} \bigg) dW(t).        \nonumber
\end{align}
Here, we assume $X^n_i(0) = X_{{i/n}}(0)$, and consider for each $n \in \mathbb{N}$ a discretized graphon $G^n :[n] \times [n] \ni (i, j) \mapsto G^n_{i, j} \in [0, 1]$, which approximates the graphon $G$, with the notion $[n] := \{1, 2, \cdots, n\}$ (see Assumption \ref{ass:G_n_and_G} below). 
We can also write $G^n : [0,1] \x [0,1] \longrightarrow [0,1]$ by $(G^n)_{u,v} = G_{\lceil nu \rceil/n,\lceil nv \rceil/n}$, for $u,v \in [0,1]$.
One such example is
\begin{equation}
    G^n_{i, j} = \int_0^1 \int_0^1 G_{\frac{i + u}{n}, \frac{j + v}{n}} \, du \, dv, \qquad 
    \forall \, (i, j) \in [n] \times [n].
\end{equation}


