\subsection{Extending Wasserstein metric to positive measures}   \label{subsec: Wop}

Since we need to handle positive measures like $\int_0^1 G_{u, v}\mu_{v}(t)dv$ in the graphon particle system \eqref{eq : graphon particle system with common noise}, we introduce in this subsection a new metric on $\mathcal{M}(\R^d)$, i.e. the space of positive finite measures. Extending 2-Wasserstein metric to $\mathcal{M}_2(\R^d)$, which consists of elements in $\mathcal{M}(\R^d)$ with finite second moment, has been studied in \cite{extendingWmetric}, so we first define $\Wop_2$ on $\mathcal{M}_2(\R^d)$ and its properties without proof. In what follows, we shall use the notations for a measurable space $X$:
\begin{itemize}
    \item $m_{\mu}$ is the total mass of a measure $\mu$;
    \item $\bar{\mu} = \mu/m_{\mu}$ if $m_{\mu} > 0$ and $\delta_0$ otherwise, where $\delta_0$ denotes the Dirac measure at $0$;
    \item $M_{x_0}(\mu) := \int_X \Vert x-x_0 \Vert^2 d\mu(x)$ for some $x_0 \in X$;
    \item $T_a(x) = a(x-x_0)+x_0$ for some $a > 0$;
    \item $T_{\#}\mu$ is the pushforward of a measure $\mu$ by a measurable mapping $T$.
    \item $\mathcal{M}(X)$ is the collection of positive finite measures on $X$;
    \item $\mathcal{M}_2(X)$ is the collection of positive finite measures on $X$ with finite second order moment;
    \item $\mathcal{M}_{2,K}(X)$ is the sub-collection of $\mathcal{M}_2(X)$ satisfying $M_{x_0}(\mu) \le Km_{\mu}$ for some $K > 0$;
    \item $\mathcal{P}(X)$ is the collection of probability measures on $X$;
    \item $\mathcal{P}_2(X)$ is the collection of probability measures on $X$ with finite second order moment.
\end{itemize}

\begin{defn}    \label{Defn: WOP R^d}
    Fix an arbitrary reference point $x_0 \in \R^d$. For $\mu$ and $\nu$ in $\mathcal{M}_2(\R^d)$, the 2-Wasserstein On Positive measures ($\Wop_2$) metric is defined by
    \begin{equation}    \label{def: WOP}
        \Wop^2_2(\mu, \nu) = (m_{\mu} - m_{\nu})^2 + \Wc^2_2(T_{m_{\mu}}\#\bar{\mu}, T_{m_{\nu}}\#\bar{\nu}).
    \end{equation}
\end{defn}

\begin{lem} \label{Lem: WOP R^d}
    $\Wop_2$ on $\mathcal{M}_2(\R^d)$ has the following properties.
    \begin{enumerate} [(i)]
        \item $\Wop_2$ is a metric on $\mathcal{M}_2(\R^d)$.
        \item $\Wop^2_2(\mu, \nu) = (m_{\mu} - m_{\nu})^2 + (m_{\mu} - m_{\nu})\big( M_{x_0}(\mu) - M_{x_0}(\nu) \big) + m_{\mu}m_{\nu}\Wc^2_2(\bar{\mu}, \bar{\nu})$.
        \item For a positive constant $K>0$, the space $(\mathcal{M}_{2,K}(\R^d), \Wop_2)$ is complete.
    \end{enumerate}
\end{lem}

The proofs of the results in Lemma \ref{Lem: WOP R^d} can be found in \cite{extendingWmetric}. In the following, we describe a similar extension of the 2-Wasserstein metric to $\mathcal{M}_2(\mathcal{C}^d)$. 
Here and in what follows, we denote $\mathcal{C}^d = C([0, T], \R^d)$ the space of $\R^d$-valued continuous functions on $[0, T]$ for a fixed $T>0$, equipped with the topology of uniform convergence. For a Polish space $S$, we equip $\mathcal{P}(S)$ with the topology of weak convergence.

\begin{defn}    \label{Def: WOP C^d}
    Fix $x_0 \in \mathcal{C}^d$. For $\mu$ and $\nu$ in $\mathcal{M}_2(\mathcal{C}^d)$, the 2-Wasserstein On Positive measures ($\Wop_2$) metric is defined by
    \begin{equation}    \label{def: WOP C^d}
        \Wop^2_2(\mu, \nu) = (m_{\mu} - m_{\nu})^2 + \Wc^2_2(T_{m_{\mu}}\#\bar{\mu}, T_{m_{\nu}}\#\bar{\nu}).
    \end{equation}
\end{defn}
In particular, if $\mu, \nu \in \mathcal{P}(\mathcal{C}^d)$, then 
$
    \Wop_2(\mu, \nu) = \Wc_2(\mu, \nu),
$
thus $\Wop_2$ is a generalization of $\Wc_2$ to positive finite measures on $\Cc^d$. Checking that $\Wop_2$ is a metric is straightforward; its proof is essentially the same as that of Lemma~\ref{Lem: WOP R^d} (i) (Theorem 2 of \cite{extendingWmetric}), so we omit the proof.

For $x, y \in \mathcal{C}^d$ and $a, b \ge 0$, we have
\begin{align}
    \big\Vert a(x-x_0)&-b(y-x_0) \big\Vert^2_{*, T} = \sup_{t \in [0, T]} \Big\vert a\big(x(t)-x_0(t)\big)-b\big(y(t)-x_0(t)\big) \Big\vert^2  \label{ineq: sup t}
    \\
    & = \sup_{t \in [0, T]} \Big( a(a-b)\big(x(t)-x_0(t)\big)^2 + b(b-a)\big(y(t)-x_0(t)\big)^2 + ab\big(x(t)-y(t)\big)^2 \Big) \nonumber
    \\
    & \le a(a-b) \Vert x-x_0 \Vert^2_{*, T} + b(b-a) \Vert y-x_0 \Vert^2_{*, T} + ab \Vert x-y \Vert^2_{*, T}.   \nonumber
\end{align}
Thus, the definition \eqref{def: WOP C^d} satisfies
\begin{equation} \label{def: WOP2}
    \Wop^2_2(\mu, \nu) \le (m_{\mu} - m_{\nu})^2 + \inf_{\pi \in \Pi(\bar{\mu}, \bar{\nu})} \int c^{x_0}_{m_{\mu}, m_{\nu}}(x, y) d\pi(x, y),
\end{equation}
where
\begin{equation*}
    c^{x_0}_{a, b}(x, y) = a(a-b)\Vert x-x_0 \Vert^2_{*, T} + b(b-a)\Vert y-x_0 \Vert^2_{*, T} + ab \Vert x-y \Vert^2_{*, T}.
\end{equation*}
Since the first two terms on the right-hand side do not depend on the coupling, the inequality \eqref{def: WOP2} can be written as
\begin{equation}    \label{ineq: WOP}
    \Wop^2_2(\mu, \nu) \le (m_{\mu} - m_{\nu})^2 + (m_{\mu} - m_{\nu})\big(M_{x_0}(\mu) - M_{x_0}(\nu)\big) + m_{\mu}m_{\nu}\Wc^2_2 (\bar{\mu}, \bar{\nu}).
\end{equation}
This shows a key difference between $\Wop_2$ on $\mathcal{M}_2(\R^d)$ and $\mathcal{M}_{2}(\Cc^d)$; the equality of Lemma \ref{Lem: WOP R^d} (ii) holds for $\Wop_2$ on $\mathcal{M}_{2}(\R^d)$, whereas we only have an inequality for $\Wop_2$ on $\mathcal{M}_{2}(\Cc^d)$. However, in the particular case of $a = b$ in \eqref{ineq: sup t}, we have the identity
\begin{equation*}
    \big\Vert a(x-x_0)-a(y-x_0) \big\Vert^2_{*, T} = a^2 \Vert x-y \Vert^2_{*, T},
\end{equation*}
thus, the inequality \eqref{ineq: WOP} becomes an equality:
\begin{equation}    \label{eq: WOP}
    \Wop^2_2(\mu, \nu) = m_{\mu}^2 \Wc^2_2 (\bar{\mu}, \bar{\nu}) \qquad \text{provided that } \quad m_{\mu} = m_{\nu}.
\end{equation}

\begin{thm}
    The space $(\Mc_{2,K}(\Cc^d), \Wop_2)$ is a Polish space.
\end{thm}
\begin{proof}
    It is sufficient to prove that $(\Mc_{2,K}(\Cc^d), \Wop_2)$ is complete and separable.

    For completeness, let $\{\mu_n\}_{n \in \N}$ be a Cauchy sequence in $\Mc_{2,K}(\Cc^d)$.
    Without loss of generality, due to the completeness of $|\cdot|$ and $\Wc_2$, we assume that
    \begin{equation*}
        \lim_{n \to \infty}m_{\mu_n} = m,
        \qquad
        \lim_{n \to \infty}\Wc_2(T_{m_{\mu_n}}\#\mub_n, \lambda) = 0,
    \end{equation*}
    for some $m \ge 0$ and $\lambda \in \Pc(\Cc^d)$. For the case $m > 0$, it follows that
    \begin{align*}
        \lim_{n \to \infty}\Wop^2_2(\mu_n, mT_m^{-1}\#\lambda) 
        ~ = ~
        \lim_{n \to \infty}(m_{\mu_n} - m)^2 
        ~ + ~
        \lim_{n \to \infty}\Wc^2_2(T_{m_{\mu_n}}\#\mub_n, \lambda) 
        ~ = ~ 0,
    \end{align*}
    and for $\mu:= mT_m^{-1}\#\lambda$,
    \begin{align*}
        M_{x_0}(\mu)
        ~ & = ~
        m \int_{\Cc^d}\|T_m^{-1}(x) - x_0\|^2_{*, T} d\lambda(x)
        ~ = ~
        \frac{1}{m}\int_{\Cc^d}\|x - x_0\|^2_{*, T} d\lambda(x)
        \\ ~ & = ~
        \frac{1}{m}\lim_{n \to \infty}\int_{\Cc^d}\|x - x_0\|^2_{*, T} dT_{m_{\mu_n}}\#\mub_n(x)
        ~ = ~
        \lim_{n \to \infty}\frac{m_{\mu_n}}{m}\int_{\Cc^d}\|x - x_0\|^2_{*, T} d\mu_n(x)
        \\ ~ & = ~
        \lim_{n \to \infty}\frac{m_{\mu_n}}{m} M_{x_0}(\mu_n)
        ~ \le ~
        \lim_{n \to \infty}K\frac{m^2_{\mu_n}}{m}
        ~ = ~ Km.
    \end{align*}
    Here, the third equality uses Lemma \ref{lem : villani} below. For the case $m = 0$, it is sufficient to prove that $\lambda = \delta_{x_0}$.
    Observe that
    \begin{align*}
        \lim_{n \to \infty}\Wc^2_2(T_{m_{\mu_n}}\#\mub_n, \delta_{x_0})
        ~ & = ~
        \lim_{n \to \infty}\int_{\Cc^d}\|x - x_0\|^2_{*, T}dT_{m_{\mu_n}}\#\mub_n(x)
        \\ ~ & = ~
        \lim_{n \to \infty}m_{\mu_n}\int_{\Cc^d}\|x - x_0\|^2_{*, T} d\mu_n(x)
        ~ \le ~
        \lim_{n \to \infty} K m_{\mu_n}^2
        ~ = ~ 0,
    \end{align*}
    so $\lambda = \delta_{x_0}$ since $\Wc_2$ is a metric.

    To show the separability, let $\{\mu_n\}_{n \in \N}$ be a dense subset of $(\Pc_2(\Cc^d) \cap \Mc_{2,K}(\Cc^d), \Wc_2)$, $\{a_m\}_{m \in \N}$ be a dense subset of $\R_+$, then we claim that $\{a_m\mu_n\}_{m,n \in \N}$ is a dense subset of $\Mc_{2,K}(\Cc^d)$.

    For any $\mu \in \Mc_{2,K}(\Cc^d)$ and any $\eps > 0$, we can find some $m^*,n^*$ such that 
    \begin{align*}
        |m_\mu - a_{m^*}| \le \frac{\eps^2}{6K} \wedge \frac{\eps}{\sqrt{3}},
        \qquad
        \Wc_2(\mub,\mu_{n^*}) \le \frac{\eps}{\sqrt{3m_\mu a_{m^*}}},
    \end{align*}
    then the relationship \eqref{ineq: WOP} proves
    \begin{align*}
        \Wop_2^2(\mu,a_{m^*}\mu_{n^*})
        ~ & \le ~
        |m_\mu - a_{m^*}|^2 + |m_\mu - a_{m^*}||M_{x_0}(\mu) - M_{x_0}(a_{m^*}\mu_{n^*})|
        +
        m_\mu a_{m^*}\Wc_2^2(\mub,\mu_{n^*})
        \\ ~ & \le ~
        \frac{\eps^2}{3} 
         ~ + ~
         \frac{\eps^2}{6K} 2K
         ~ + ~
         m_\mu a_{m^*} \frac{\eps^2}{3m_\mu a_{m^*}}
        ~ = ~
        \frac{\eps^2}{3} 
         ~ + ~
         \frac{\eps^2}{3} 
         ~ + ~
         \frac{\eps^2}{3} 
         ~ = ~
         \eps^2.
    \end{align*}
\end{proof}


\subsection{Fubini extension}

The graphon particle system \eqref{eq : graphon particle system with common noise} consists of the continuum of particles $\{X_u\}_{u \in I}$, as well as Brownian motions $\{B_u\}_{u \in I}$ with $I := [0, 1]$. Since the mapping $\Omega \times I \ni (\omega, u) \mapsto B_u(\omega)$ is not jointly measurable in the usual continuum product space with Lebesgue space $(I, \mathcal{B}_I, \lambda_I)$ on the index space $I$, an application of the rich Fubini extension, originally introduced in \cite{SUN200631}, is necessary. In this subsection, we shall only provide some essential parts of the Fubini extension for a formal definition of the graphon particle system \eqref{eq : graphon particle system with common noise}, as similar graphon particle settings were developed in \cite{Aurell2022, nonlinear:graphon}.

\begin{defn}
    Consider a Polish space $S$ and two probability spaces $(\Omega, \mathcal{F}, \mathbb{P})$ and $(I, \mathcal{I}, \lambda_I)$, where $\lambda_I$ is the Lebesgue measure on $I = [0, 1]$. A process $X : \Omega \times I \to S$ is said to be \textit{essentially pairwise independent (e.p.i.)}, if for $\lambda$-a.e. $u \in I$ and $\lambda$-a.e. $v \in I$, the random variables $X_u : \omega \mapsto X_u(\omega)$ and $X_v : \omega \mapsto X_v(\omega)$ are independent. A probability space $(\Omega \times I, \mathcal{F} \boxtimes \mathcal{I}, \mathbb{P} \boxtimes \lambda_I)$, extending the usual product space $(\Omega \times I, \mathcal{F} \otimes \mathcal{I}, \mathbb{P} \otimes \lambda_I)$ is said to be a \textit{Fubini extension}, if for any $(\mathbb{P} \boxtimes \lambda_I)$-integrable function $X$ on $(\Omega \times I, \mathcal{F} \boxtimes \mathcal{I})$
    \begin{enumerate} [(i)]
        \item the two functions $X_u : \omega \mapsto X_u(\omega)$ and $X(\omega) : u \mapsto X_u(\omega)$ are integrable on $(\Omega, \mathcal{F}, \mathbb{P})$ for $\lambda$-a.e. $u \in I$ and on $(I, \mathcal{I}, \lambda_I)$ for $\mathbb{P}$-a.e. $\omega \in \Omega$, respectively;
        \item $\int_{\Omega} X_u(\omega) d\mathbb{P}$ and $\int_I X_u(\omega) d\lambda(u)$ are integrable on $(I, \mathcal{I}, \lambda_I)$ and $(\Omega, \mathcal{F}, \mathbb{P})$, respectively, with $\int_{\Omega \times I} X d(\mathbb{P} \otimes \lambda_I) = \int_I (\int_{\Omega} X_u(\omega) d\mathbb{P}) d\lambda(u) = \int_{\Omega} (\int_I X_u(\omega) d\lambda(u) ) d\mathbb{P}$.
    \end{enumerate}
\end{defn}

The following result shows the existence of the Fubini extension.

\begin{lem} [Theorem 1 of \cite{Aurell2022}]    \label{lem: Fubini extension}
    Let $S$ be a Polish space and $(\Omega, \mathcal{F}, \mathbb{P})$ be a probability space. There exist a probability space $(I, \mathcal{I}, \lambda)$ extending the Lebesgue space $(I, \mathcal{B}_I, \lambda_I)$ and a Fubini extension $(\Omega \times I, \mathcal{F} \boxtimes \mathcal{I}, \mathbb{P} \boxtimes \lambda)$ such that for any measurable mapping $\phi$ from $(I, \mathcal{I}, \lambda)$ to $\mathcal{P}(S)$, there is a $(\mathcal{F} \boxtimes \mathcal{I})$-measurable process $X: \Omega \times I \to S$ such that the random variables $X_u$ are e.p.i. and $\mathbb{P} \circ X_u^{-1} = \phi(u)$ for $u \in I$.
\end{lem}

In order to construct a space containing the continuum of (jointly measurable) Brownian motions $\{B_u\}_{u \in I}$ and initial distributions $\{X_u(0)\}_{u \in I}$ that are independent (in the sense of e.p.i.) in the graphon system, 
let $\phi : I \to \mathcal{P}(\Cc^d \times \R^d)$ be the mapping defined by $\phi(u) = w_u \otimes \rho_u(0)$ with the Wiener measure $w_u$ on $\Cc^d$ and a $\mathcal{B}_I$-measurable (thus $\mathcal{I}$-measurable) function $\rho_\cdot(0) : I \to \mathcal{P}(\R^d)$. 
Then, from Lemma \ref{lem: Fubini extension}, there exists a $(\mathcal{F} \boxtimes \mathcal{I})$-measurable process 
$Z : \Omega \times I \to \Cc^d \times \R^d$, 
defined by $Z_u(\omega) = (B_u(\omega), \zeta_u(\omega))$ 
for $u \in I$, such that $(B_u, \zeta_u)_{u \in I}$ are e.p.i. random variables 
and the law of $(B_u, \zeta_u)$ is equal to $w_u \otimes \rho_u(0)$ for every $u \in I$.

Following the notations of \cite{nonlinear:graphon}, we shall denote $L^2_{\boxtimes}(\Omega \times I, \Cc^d)$ the space of equivalent classes of $(\mathcal{F} \boxtimes \mathcal{I}, \mathcal{B}(\Cc^d))$-measurable functions that are $(\mathbb{P} \boxtimes \lambda)$-square integrable, i.e., $\phi \in L^2_{\boxtimes}(\Omega \times I, \Cc^d)$ if 
\begin{equation*}
    \E^{\boxtimes} \bigg[\sup_{0 \le t \le T} |\phi(t)|^2\bigg] := \int_{\Omega \times I} \sup_{0 \le t \le T} |\phi_u(t, \omega)|^2 \mathbb{P} \boxtimes \lambda (d\omega, du) < \infty,
\end{equation*}
and $L^2_{\lambda}(I, \R^d)$ for the Hilbert space of $\lambda$-a.e. equivalent classes of $\lambda$-measurable functions $\varphi: I \ni u \mapsto \varphi_u \in \R^d$ such that $\int_I |\varphi_u|^2 \lambda (du) < \infty$.

We now consider for $d, m, \tilde{m} \in \N$
\begin{align*}
    &\bm{\zeta} : \Omega \times I \ni (\omega, u) \mapsto \zeta_u(\omega) \in \R^d,
    \\
    &\bm{B} : \Omega \times I \ni (\omega, u) \mapsto \big(B_u(t, \omega)\big)_{t \in [0, T]} \in \Cc^m,
    \\
    &W : \Omega \ni \omega \mapsto  \big(W(t, \omega)\big)_{t \in [0, T]} \in \Cc^{\tilde{m}},
\end{align*}
and the filtration $\mathbb{F}$ generated by $\bm{\zeta}$, $\bm{B}$, and $W$. Then, the graphon particle system \eqref{eq : graphon particle system with common noise} can be formally written as a stochastic differential equation in $L^2_{\lambda}(I, \R^d)$
\begin{align}
    d\bm{X}(t) = \bm{\phi}_p \big( \bm{X}(t), (\mu_u(t))_{u \in I} \big) dt &+ \bm{\phi}_b \big( \bm{X}(t), (\mu_u(t))_{u \in I} \big) d\bm{B}(t)           \label{eq : formal graphon system}
    \\
    &+ \bm{\phi}_w \big( \bm{X}(t), (\mu_u(t))_{u \in I} \big) dW(t), \qquad t \in [0, T],      \nonumber
\end{align}
with the initial distribution $\bm{X}(0) = \bm{\zeta}$ and 
\begin{align*}
    \bm{\phi}_p &= (\phi_{p, u})_{u \in I} : L^2_{\lambda}(I, \R^d) \times \mathcal{M}(\R^d)^I \to L^2_{\lambda}(I, \R^d),
    \\
    \bm{\phi}_b &= (\phi_{b, u})_{u \in I} : L^2_{\lambda}(I, \R^d) \times \mathcal{M}(\R^d)^I \to L^2_{\lambda}(I, \R^{d \times m}),
    \\
    \bm{\phi}_w &= (\phi_{w, u})_{u \in I} : L^2_{\lambda}(I, \R^d) \times \mathcal{M}(\R^d)^I \to L^2_{\lambda}(I, \R^{d \times \tilde{m}}),
\end{align*}
where for $\bm{x} = (x_u)_{u \in I} \in L^2_{\lambda}(I, \R^d)$ and $\bm{\mu} \in \mathcal{P}_2(\R^d)^I$ the functions are defined by
\begin{align*}
    \phi_{\alpha, u} (\bm{x}, \bm{\mu}) &= \phi_{\alpha} \Big(x_u, \int_I G_{u, v} \mu_v dv \Big),
    \qquad \text{for} \quad \alpha = p, b, w, \quad \text{and} \quad \lambda-\text{a.e.} \quad u \in I.
\end{align*}

A solution to \eqref{eq : formal graphon system} is defined by an $\mathbb{F}$-progressively measurable process $\bm{X} \in L^2_{\boxtimes}(\Omega \times I, \Cc^d)$ satisfying for $u \in I$ and $(\mathbb{P} \boxtimes \lambda)$-a.e.
\begin{align*}
    X_u(t) = \zeta_u &+ \int_0^t \phi_{p, u} \big(\bm{X}(s), (\mu_u(s))_{u \in I} \big) ds + \int_0^t \phi_{b, u} \big(\bm{X}(s), (\mu_u(s))_{u \in I} \big) dB_u(s)
    \\
    &+ \int_0^t \phi_{w, u} \big(\bm{X}(s), (\mu_u(s))_{u \in I} \big) dW(s), \qquad \qquad t \in [0, T].
\end{align*}
We refer to Section 3 and Appendix A of \cite{nonlinear:graphon} for more details about the formal formulation of the graphon system.

\bigskip

\subsection{Notations and assumptions}
For any Polish space $(E,d)$, we denote by $C_b(E)$ the space of bounded continuous functions on $E$, and define $\langle f,\mu\rangle := \int_E f(x)\, \mu(dx)$ for any $f \in C_b(E)$, positive measure $\mu \in \Mc(E)$.

We first recall the graphon particle system \eqref{eq : graphon particle system with common noise} with its approximating $n$-particle system \eqref{eq : finite particle system with common noise}, and define the following measures in $\mathcal{P}(\mathcal{C}^d)$
\begin{equation}    \label{def: measures}
    \mu^n := \frac{1}{n} \sum_{i=1}^n \delta_{X^n_i}, \qquad
    \bar{\mu}^n := \frac{1}{n} \sum_{i=1}^n \delta_{X_{i/n}}, \qquad
    \mu_u := \mathcal{L}[X_u | W], \qquad
    \bar{\mu} := \int_0^1 \mu_u du,
\end{equation}
such that for each $t \in [0, T]$ we have the measures in $\mathcal{P}(\R^d)$
\begin{align*}
    \mu^n(t) := \frac{1}{n} \sum_{i=1}^n \delta_{X^n_i(t)}, \qquad 
    &\bar{\mu}^n(t) := \frac{1}{n} \sum_{i=1}^n \delta_{X_{i/n}(t)},
    \\
    \mu_u(t) := \mathcal{L}[X_u(t) | W], \qquad
    &\bar{\mu}(t) := \int_0^1 \mu_u(t) du.
\end{align*}
Note that $\mathcal{L}[X_u(t) | W] = \mathcal{L}[X_u(t) | \{W_s\}_{s \in [0,T]}] = \mathcal{L}[X_u(t) | \{W_s\}_{s \in [0,t]}]$.
Here and in what follows, the integral of measure should also be understood as a measure, as
\begin{align*}
    \bar{\mu}(A) &:= \int_0^1 \mu_u(A)du, \qquad \forall \, A \in \mathcal{B}(\Cc^d),
    \\
    \bar{\mu}(t)(A) &:= \int_0^1 \big(\mu_u(t)(A)\big) du, \qquad \forall \, A \in \mathcal{B}(\R^d).
\end{align*}


We now list the following conditions that we impose on the two systems \eqref{eq : graphon particle system with common noise} and \eqref{eq : finite particle system with common noise}.

\begin{assumption}  \label{ass:Lipschitz}
In the two systems \eqref{eq : graphon particle system with common noise} and \eqref{eq : finite particle system with common noise}, we assume that
\begin{enumerate} [(i)]
    \item the functions $\phi_{\alpha}$ for $\alpha = p, b, w$ are bounded and Lipschitz continuous, i.e., there exists some constant $L > 0$ such that for all $x_1, x_2 \in \R^d$ and $\mu_1, \mu_2 \in \mathcal{M}_{2,K}(\R^d)$,
    \begin{equation*}
        |\phi_\alpha(x_1, \mu_1) - \phi_\alpha(x_2, \mu_2)| \le L \Big(\max\{m_{\mu_1},m_{\mu_2},1\}|x_1 - x_2| + \Wop_2(\mu_1, \mu_2) \Big),
    \end{equation*}

    \item the mapping $[0, 1] \ni u \mapsto \mathcal{L}\big(X_u(0)\big) \in \mathcal{P}(\R^d)$ is measurable, and the initial distribution has uniformly bounded $(2+\eps)$ moment for some $\eps > 0$:
    \begin{equation*}
        \sup_{u \in [0, 1]} \E|X_u(0)|^{2 + \eps} < \infty.
    \end{equation*}
\end{enumerate}
\end{assumption}



Lemma \ref{lem: unique pathwise solution} provides a well-posedness of the system \eqref{eq : graphon particle system with common noise}. It can be proven by a standard fixed-point (contraction) argument, so we omit the proof. Instead, we refer to the proof of Proposition 3.1 of \cite{nonlinear:graphon}, as adding a common noise does not change much of this proof.

\begin{lem} \label{lem: unique pathwise solution}
    Under Assumption \ref{ass:Lipschitz}, there exists a unique pathwise solution $\{X_u\}_{u\in[0, 1]}$ to the graphon particle system \eqref{eq : graphon particle system with common noise} with common noise. Furthermore, $\sup_{u \in [0, 1]} \E \Vert X_u \Vert^{2+\eps}_{*, T} < \infty$ holds, and the mapping $[0, 1] \ni u \mapsto \mathcal{L}(X_u) \in \mathcal{P}_2(\mathcal{C}^d)$ is measurable.
\end{lem}

The following additional assumption is necessary when proving the $\Wc_{2}$-uniform continuity in $u$ of the conditional law $\mu_u$, defined in \eqref{def: measures} (see Lemma \ref{lem: continuity of average measure} below).

\begin{assumption}\label{ass: G Lipschitz}
    In the two systems \eqref{eq : graphon particle system with common noise} and \eqref{eq : finite particle system with common noise}, we assume that
    \begin{enumerate}[(i)]
        \item the graphon $G$ is Lipschitz continuous in the sense that for each $v \in [0,1]$ there exists some $L_v$ satisfying
        \begin{equation*}
            |G_{u_1,v} - G_{u_2,v}|
            ~ \le ~
            L_v|u_1 - u_2|,
        \end{equation*}
        and $v \longmapsto L_v$ is $L^2$-integrable, i.e.,
        $\int_{0}^{1} |L_v|^2 dv < \infty$;
        \item the mapping $u \longmapsto \mu_u(0)$ satisfies the following continuity in $\Wc_{2+\eps}$ distance for some $\eps > 0$:
        \begin{equation}    \label{initial condition}
            \E\big[\Wc^{2+\eps}_{2+\eps} \big(\mu_{u_1}(0), \mu_{u_2}(0)\big)\big] \le \kappa |u_1-u_2|^{1 + \frac{\eps}{2}}, \qquad \forall \, u_1, u_2 \in [0, 1].
        \end{equation}
    \end{enumerate}
\end{assumption}

\begin{rem}
    The value of constant $\epsilon$ in Assumptions \ref{ass:Lipschitz} and \ref{ass: G Lipschitz} can be different, but we use the same symbol for simplicity. Moreover, the assumption \eqref{initial condition} can be relaxed to $\eps=0$ in the linear case (see Appendix \ref{sec: linear case}).
\end{rem}

\begin{assumption}\label{ass:G_n_and_G}
    For the graphons $G$ and $G^n$ in the two systems \eqref{eq : graphon particle system with common noise} and \eqref{eq : finite particle system with common noise}, we assume
    \begin{align*}
        \lim_{n \to \infty}\|G- G^n\|_\square
        ~ = ~
        0,
    \end{align*}
    where the cut norm $\|\cdot\|_\square$ of a graphon is defined by 
    $$\|G\|_\square := \sup_{S,T \in \mathcal{B}(I)}\Bigg|\iint_{S \x T} G_{u,v}\,du\,dv\Bigg|.$$
    Here, $\mathcal{B}(I)$ is the set of all Borel measurable subsets of $[0, 1]$.
\end{assumption}

