\section{Results}

This section states our main results regarding the two systems \eqref{eq : graphon particle system with common noise} and \eqref{eq : finite particle system with common noise}. Their proofs will be given in the next section.

\subsection{Preliminaries}

Before we state and prove our main theorems, we provide some preliminary results in this subsection. First, we show that the conditional law $\mu_u$ has a modification that is $\Wc_2$-uniformly continuous in $u$.

\begin{defn}    \label{Def: spatial modi}
    For the family of measures $\{\mu_u\}_{u \in [0, 1]} \subset \mathcal{P}(\mathcal{C}^d)$ in \eqref{def: measures}, a family $\{\tilde{\mu}_u\}_{u \in [0, 1]} \subset \mathcal{P}(\mathcal{C}^d)$ satisfying $\P(\mu_u = \tilde{\mu}_u)=1$ for every $u \in [0, 1]$ is called \textit{spatial modification} of $\{\mu_u\}_{u \in [0, 1]}$.
\end{defn}

\begin{lem} \label{lem: continuity of average measure}
    If Assumptions \ref{ass:Lipschitz}, \ref{ass: G Lipschitz} hold true, then the family $\{\mu_u\}_{u \in [0, 1]} \subset \mathcal{P}_2(\mathcal{C}^d)$ has a spatial modification $\{\tilde{\mu}_u\}_{u \in [0, 1]}$ such that the mapping $u \longmapsto \tilde{\mu}_u$ is $\gamma$-H\"older continuous in $\Wc_2$ for $\gamma < \frac{\epsilon}{2(2+\epsilon)}$. In particular, the mapping $u \longmapsto \tilde{\mu}_u$ is uniformly continuous in $\Wc_2$.
\end{lem}

The proof of Lemma \ref{lem: continuity of average measure} can be found in Section \ref{sec: proofs}.

\begin{rem}
    Throughout this paper, thanks to Lemma \ref{lem: continuity of average measure}, we shall abuse the notation by denoting the spatially modified version $\tilde{\mu}_u$ simply as $\mu_u$, which is $\mathcal{W}_2$-uniformly continuous in $u$. 
\end{rem}

The following result provides several equivalent conditions for the $\mathcal{W}_2$-convergence of a sequence of probability measures. Since it will be used in the proofs of results in subsequent sections, we include it here for completeness.

\begin{lem}[Theorem 7.12 of \cite{villani}] \label{lem : villani}
    For a Polish space $X$, endowed with a distance $d$, let $(\nu_n)_{n \in \N}$ be a sequence of probability measures in $\mathcal{P}_2(X)$ and let $\nu \in \mathcal{P}(X)$. Then, the following statements are equivalent:
    \begin{enumerate}[(i)]
        \item $\Wc_2(\nu_n, \nu) \xlongrightarrow{n \to \infty} 0$.
        \item $\nu_n \xlongrightarrow{n \to \infty} \nu$ in weak sense, and $(\nu_n)_{n \in \N}$ satisfies the tightness condition: for some $x_0 \in X$, 
        \[
            \lim_{a \to \infty} \limsup_{n \to \infty} \int_{d(x_0, x) \ge a} d(x_0, x)^2 d\nu_n(x) = 0.
        \]
        \item $\nu_n \xlongrightarrow{n \to \infty} \nu$ in a weak sense, and there is a convergence of the moment of order $2$: for some $x_0 \in X$,
        \[
            \int d(x_0, x)^2 d\nu_n(x) \xlongrightarrow{n \to \infty} \int d(x_0, x)^2 d\nu(x).
        \]
        \item For any continuous function $\varphi$ on $X$ satisfying the condition $|\varphi(x)| \le C[1+d(x_0, x)^2]$ for some $x_0 \in X$, 
        \[
            \int \varphi \, d\nu_n \xlongrightarrow{n \to \infty} \int \varphi \, d\nu.
        \]
    \end{enumerate}
\end{lem}


\subsection{Convergence within the graphon system}
This subsection is devoted to convergence results within the graphon mean-field system \eqref{eq : graphon particle system with common noise}, where dynamics in finite particle systems are not involved. In particular, the convergences of the empirical measures $\{\frac{1}{n} \sum_{i=1}^n \delta_{X_{i/n}}\}_{n \in \N}$ in $\Wc_2$, and the weighted empirical measures $\{\frac{1}{n} \sum_{i=1}^n G^n_{j,i}\delta_{X_{i/n}}\}_{n \in \N}$ in $\Wop_2$, respectively, are established. 

By recalling the measures in $\mathcal{P}(\mathcal{C}^d)$ of \eqref{def: measures}, we shall consider joint laws $\mathcal{L} (\mu^n, \bar{\mu})$ and $\mathcal{L} (\bar{\mu}, \bar{\mu})$ on $\mathcal{P}(\mathcal{C}^d) \x \mathcal{P}(\mathcal{C}^d)$, instead of $\mathcal{L} (\bar{\mu}^n)$, $\mathcal{L} (\bar{\mu})$ on $\mathcal{P}(\mathcal{C}^d)$:
\begin{align}
    \mathcal{L} (\mu^n, \bar{\mu}) (A) &:= \P [ (\mu^n, \bar{\mu}) \in A], \qquad \forall \, A \in \mathcal{B}\big( \mathcal{P}(\mathcal{C}^d) \x \mathcal{P}(\mathcal{C}^d)\big),
    \\
    \mathcal{L} (\bar{\mu}, \bar{\mu}) (A) &:= \P [ (\bar{\mu}, \bar{\mu}) \in A], \qquad \quad \forall \, A \in \mathcal{B}\big( \mathcal{P}(\mathcal{C}^d) \x \mathcal{P}(\mathcal{C}^d)\big).
\end{align}


The following convergence \eqref{conv: W2 ppcd} will play a central role in proving subsequent results, and its proof is provided in Section \ref{sec: proofs}.

\begin{lem} \label{lem : W2 joint law conv}
    Under Assumptions \ref{ass:Lipschitz} and \ref{ass: G Lipschitz}, we have
    \begin{equation}    \label{conv: W2 ppcd}
        \lim_{n \to \infty} \W_2 \big( \Lc(\bar{\mu}^n,\bar{\mu}), \, \Lc(\bar{\mu},\bar{\mu}) \big) = 0.
    \end{equation}
\end{lem}

With the aid of Lemma \ref{lem : W2 joint law conv}, the following convergence of $\bar{\mu}^n$ to $\bar{\mu}$ can be established without difficulty. 

\begin{thm} \label{thm: bar mu_n to bar mu}
    Under Assumptions \ref{ass:Lipschitz} and \ref{ass: G Lipschitz}, we have
    \begin{equation}  \label{conv: mean W2 continuity}
        \E \Big[ \Wc^2_2( \bar{\mu}^n, \, \bar{\mu} ) \Big] \xlongrightarrow{n \to \infty} 0,
    \end{equation}
    Consequently, it follows that
    \begin{equation*}
        \Wc_2 \big( \Lc(\bar{\mu}^n), \, \Lc(\bar{\mu}) \big) \xlongrightarrow{n \to \infty} 0.
    \end{equation*}
\end{thm}


\begin{proof}
    In (i), (iv) of Lemma \ref{lem : villani}, we set
    \begin{equation*}
        X := \mathcal{P}(\mathcal{C}^d) \times \mathcal{P}(\mathcal{C}^d), \qquad \nu_n := \mathcal{L}(\bar{\mu}^n, \bar{\mu}), \qquad \nu := \mathcal{L}(\bar{\mu}, \bar{\mu}),
    \end{equation*}
    and define a continuous function $\varphi$ on $\mathcal{P}(\mathcal{C}^d) \times \mathcal{P}(\mathcal{C}^d)$
    \begin{align*}
        \varphi(\nu_1, \nu_2) := \Wc^2_2(\nu_1, \nu_2) \le 2 \Wc^2_2(\delta_0, \nu_1) +
        2 \Wc^2_2(\delta_0, \nu_2) = 2d^2 \big( (\delta_0,\delta_0), (\nu_1, \nu_2) \big)
    \end{align*}
    then, Lemma \ref{lem : W2 joint law conv} implies the result \eqref{conv: mean W2 continuity}:
    \begin{equation*}
        %\int \Wc^2_2(\mu_1,\mu_2)\Lc(\bar{\mu}^n,\bar{\mu})(d\mu_1,d\mu_2) =
        \E[\Wc^2_2(\bar{\mu}^n,\bar{\mu})] = \int \varphi \, d\nu_n \xlongrightarrow{n \to \infty} \int \varphi \, d\nu = 0.
    \end{equation*}
\end{proof}

In the following, we can approximate the graphon-weighted average of the distributions of continuum of particles with the graphon-weighted average of the empirical measures of finite particles in the graphon mean field system \eqref{eq : graphon particle system with common noise} in terms of $\Wop_2$-metric. The proof of this law of large number type result can be found in Section \ref{sec: proofs}.

\begin{thm} \label{thm: weighted mean W2 continuity}
    Under Assumptions \ref{ass:Lipschitz}, \ref{ass: G Lipschitz}, and \ref{ass:G_n_and_G},
    we have
    \begin{equation} \label{conv: weighted mean W2 continuity}
        \frac{1}{n}\sum_{i = 1}^n \E\Bigg[ \Wop^2_2\bigg(\frac{1}{n}\sum_{j = 1}^n G^n_{i,j} \delta_{X_{{j/n}}}, ~ \int_{0}^1 G_{{i/n},v}\mu_v dv\bigg)\Bigg] \xlongrightarrow{n \to \infty} 0,
    \end{equation}
\end{thm}

\begin{rem} \hspace{1pt}
\begin{enumerate}[(i)]
    \item Theorem \ref{thm: bar mu_n to bar mu} can be seen as a special case of Theorem \ref{thm: weighted mean W2 continuity}, if we simply let $G^n_{i,j} = 1$ for all $i,j \in [n]$, and $G_{u,v} = 1$ for all $u,v \in [0,1]$.
    \item To the best of our knowledge, this convergence in $\Wop_2$ is a new result, which reveals that the convergence of $\frac{1}{n}\sum_{j = 1}^n G^n_{i,j} \delta_{X_{{j/n}}}$ is actually not only in the topology of weak convergence but also in $\Wop_2$. The convergence in the topology of weak convergence can be found in Lemma 6.2 of \cite{BCW}.
\end{enumerate}
\end{rem}

\subsection{Convergence of finite particle systems to the graphon system}
All the results in this subsection state the convergence of (weighted) empirical measures in finite particle systems to the graphon system \eqref{eq : graphon particle system with common noise}, as the number of particles $n$ tends to infinity, i.e., the convergence of $\{\frac{1}{n}\sum_{j = 1}^n G^n_{i,j}\delta_{X^n_j}\}_{n \in \N}$ in $\Wop_2$, and $\{\frac{1}{n}\sum_{j = 1}^n\delta_{X^n_j}\}_{n \in \N}$ in $\Wc_2$, respectively.

We first present a similar law of large number result between the graphon system \eqref{eq : graphon particle system with common noise} and the finite particle system \eqref{eq : finite particle system with common noise}. Note that this result is stronger than Theorem 4.1 of \cite{nonlinear:graphon}, in which they only consider the convergence of the integral of empirical marginal measures, i.e., $\frac{1}{n}\sum_{i = 1}^n \E\big[\int_0^T \Wop^2_2\big(\frac{1}{n}\sum_{j = 1}^n G^n_{i,j} \delta_{X^{{n}}_j(t)}, ~ \int_{0}^1 G_{{i/n},v}\mu_v(t) dv\big)dt\big]$. We consider the convergence of the process law, which is stronger and does not require Assumption 3.1 (ii) in their paper. Its proof is given in Section \ref{sec: proofs}.

\begin{thm} \label{thm: weighted mean W2 squared}
    Under Assumptions \ref{ass:Lipschitz}, \ref{ass: G Lipschitz}, and \ref{ass:G_n_and_G}, we have
    \begin{equation}  \label{conv: weighted mean W2 squared}
        \frac{1}{n}\sum_{i = 1}^n \E\Bigg[ \Wop^2_2\bigg(\frac{1}{n}\sum_{j = 1}^n G^n_{i,j}\delta_{X^n_j}, \int_{0}^1 G_{i/n,v}\mu_vdv \bigg) \Bigg] \xlongrightarrow{n \to \infty} 0.
    \end{equation}
\end{thm}

We also provide the $\Wc_2$-convergence of the empirical measures of the $n$-particle system to those of the graphon system.

\begin{thm} \label{thm: W2 to zero}
    Under Assumptions \ref{ass:Lipschitz}, \ref{ass: G Lipschitz}, and \ref{ass:G_n_and_G}, we have
    \begin{equation}    \label{conv: mean W2 squared}
        \E \Big[ \Wc^2_2( \mu^n, \bar{\mu} ) \Big] \xlongrightarrow{n \to \infty} 0,
    \end{equation}
    and
    \begin{equation}    \label{conv: to zero}
        \frac{1}{n} \sum_{i = 1}^n \E\bigg[\sup_{t \in [0,T]} \big|X^n_i(t) - X_{i/n}(t) \big|^2 \bigg]\xlongrightarrow{n \to \infty} 0.
    \end{equation}
\end{thm}
Note that the result \eqref{conv: to zero} recovers Theorem 4.1 of \cite{nonlinear:graphon}, but we used a different argument.

\bigskip

\subsection{Convergence rates}
    The following lemma will play a central role in proving Theorem \ref{thm: convergence rates} and its proof can be found in Section \ref{sec: proofs}.

    \begin{lem} \label{lem:sampling_rate}
        Let Assumption \ref{ass:Lipschitz} holds true. Then, there exists some positive constant $C$ satisfying
        \begin{equation}\label{eq:rate_marginal}
            \sup_{t \in [0, T]} \sup_{i \in [n]} \E\Bigg[\Wop^2_2\bigg(\frac{1}{n}\sum_{j = 1}^n G^n_{i,j}\delta_{X_{{j/n}}(t)}, 
            \frac{1}{n}\sum_{j = 1}^n G^n_{i,j} \mu_{j/n}(t) \bigg)\Bigg]
            ~ \le ~ 
            CM_n,
        \end{equation}
        where the rate of convergence $M_n$ is given by
        \begin{equation*}
            M_n = 
                \begin{cases}
                    n^{-\frac{1}{2}} + n^{-\frac{\eps}{2+\eps}}, &~\mbox{if}~ d < 4, ~ \eps \neq 2, 
                    \\
                    n^{-\frac{1}{2}}\log(1 + n) + n^{-\frac{\eps}{2+\eps}}, &~\mbox{if}~ d = 4, ~ \eps \neq 2,
                    \\
                    n^{-\frac{2}{d}} + n^{-\frac{\eps}{2+\eps}}, &~\mbox{if}~ d > 4, ~ \eps \neq \frac{4 - d}{d - 2}.
                \end{cases}
        \end{equation*}
        Here, $\eps$ is the constant in Assumption \ref{ass:Lipschitz} (ii).
    \end{lem}

    \begin{rem} \hspace{1pt}
        \begin{enumerate}[(i)]
            \item The main idea and steps of the proof are almost the same as \cite{nonlinear:graphon}, which originates from Theorem 1 in \cite{FournierGuillin}, but our assumption is weaker. Here, we provide the proof for completeness.

            \item It is natural to consider the convergence rate for the process law by replacing $X_{j/n}(t)$ and $\mu_{j/n}(t)$ by $X_{j/n}$ and $\mu_{j/n}$, respectively, in \eqref{eq:rate_marginal}. The main problem is that we don't know whether \eqref{eq:child_estimate} holds true for probability measures on $\Cc^d$, which is an infinite-dimensional space.
            In the proof of \eqref{eq:child_estimate}, one key feature of $\R^d$ is that we can divide $(-1,1]^d$ naturally into $2^{d}$ disjoint parts with half diameter, due to the total boundedness of $(-1,1]^d$. However, the unit ball in $\Cc^d$ doesn't have the total boundedness.
            We refer to Sections 2.1 and 2.2 of \cite{lei} for a detailed discussion.
        \end{enumerate}
    \end{rem}

    \begin{thm} \label{thm: convergence rates}
        Let Assumptions \ref{ass:Lipschitz} and \ref{ass: G Lipschitz} hold true.
        Suppose that $G^n_{i,j} = G_{{i/n}, {j/n}}$ holds for $i, j \in [n], n \in \N$.
        Then, for some positive constant $K_{d,\eps} > 0$
        \begin{align*}
            \sup_{i \in [n]}\E\bigg[\sup_{t \in [0,T]}|X^n_i(t) - X_{{i/n}}(t)|^2\bigg]
            ~ \le ~ 
            K_{d,\eps}M_n
        \end{align*}
        holds for $M_n$ given in Lemma \ref{lem:sampling_rate}.
    \end{thm}
    \begin{rem} \hspace{1pt}
        \begin{enumerate}[(i)]
            \item Compared to the result \eqref{conv: to zero} in Theorem \ref{thm: W2 to zero}, it seems that the convergence in this theorem is stronger and at the same time with fewer assumptions. However, note that the convergence rate holds true only in the case of $G^n_{i,j} = G_{{i/n}, {j/n}}$, which is stronger than Assumption \ref{ass:G_n_and_G}.
            \item Compared to Theorem 4.2 in \cite{nonlinear:graphon}, we can drop out Assumptions 3.1 and 3.2 in their paper.
        \end{enumerate}
    \end{rem}
\bigskip

\section{Proofs} \label{sec: proofs}

\begin{proof} [Proof of Lemma \ref{lem: continuity of average measure}]
    For fixed $u_1, u_2 \in [0, 1]$, consider auxiliary processes for $i = 1, 2$:
    \begin{align*}
        \tilde{X}_{u_i}(t) = \tilde{X}_{u_i}(0) &+ \int_0^t \phi_p \bigg(\tilde{X}_{u_i}(s), ~ \int_0^1 G_{u_i, v} \mu_v(s) dv \bigg) ds
        \\
        &+ \int_0^t \phi_b \bigg(\tilde{X}_{u_i}(s), ~ \int_0^1 G_{u_i, v} \mu_v(s) dv \bigg) dB(s)
        \\
        &+ \int_0^t \phi_w \bigg(\tilde{X}_{u_i}(s), ~ \int_0^1 G_{u_i, v} \mu_v(s) dv \bigg) dW(s),
    \end{align*}
    where $B$ is a $d$-dimensional Brownian motion independent of $W$ and $\{\tilde{X}_{u_i}(0)\}_{i=1, 2}$, and the conditional initial law is given as $\mathcal{L}(\tilde{X}_{u_i}(0)|W) = \mu_{u_i}(0)$ for $i=1, 2$. Then, from Lemma \ref{lem: unique pathwise solution}, we have $\mathcal{L}(\tilde{X}_{u_i}|W) = \mu_{u_i}$ for $i=1, 2$.

    In what follows, we shall write the positive measures in $\mathcal{M}_2(\R^d)$ with their masses for $i = 1, 2$
    \begin{equation*}
        \bar{\mu}_{u_i}(s):= \int_0^1 G_{u_i, v} \mu_v(s) dv, \qquad m_{u_i} := \int_0^1 G_{u_i, v} dv \le 1.
    \end{equation*}

    Using Jensen inequality with the convexity of $x \mapsto x^{2+\eps}$, H\"older inequality, and Burkholder-Davis-Gundy inequality, we obtain
    \begin{align}
        \E \left[ \Vert \tilde{X}_{u_1}-\tilde{X}_{u_2} \Vert^{2+\eps}_{*, t} \right]
        &\le C \E \left[ \big| \tilde{X}_{u_1}(0) - \tilde{X}_{u_2}(0) \big|^{2+\eps} \right]       \nonumber
        \\
        & \quad + C \E \left[ \left( \int_0^t \Big| \phi_{p} \big(\tilde{X}_{u_1}(s), ~ \bar{\mu}_{m_1}(s) \big) - \phi_{p} \big(\tilde{X}_{u_2}(s), ~ \bar{\mu}_{m_2}(s) \big) \Big| ds \right)^{2+\eps} \right]       \nonumber
        \\
        & \quad + C \sum_{\alpha = b, w} \E \left[ \left( \int_0^t \Big| \phi_{\alpha} \big(\tilde{X}_{u_1}(s), ~ \bar{\mu}_{m_1}(s) \big) - \phi_{\alpha} \big(\tilde{X}_{u_2}(s), ~ \bar{\mu}_{m_2}(s) \big) \Big|^2 ds \right)^{\frac{2+\eps}{2}} \right]        \nonumber
        \\
        &\le C \E \left[ \big| \tilde{X}_{u_1}(0) - \tilde{X}_{u_2}(0) \big|^{2+\eps} \right]       \nonumber
        \\
        & \quad + C t^{1+\eps} \E \left[ \int_0^t \Big| \phi_{p} \big(\tilde{X}_{u_1}(s), ~ \bar{\mu}_{m_1}(s) \big) - \phi_{p} \big(\tilde{X}_{u_2}(s), ~ \bar{\mu}_{m_2}(s) \big) \Big|^{2+\eps} ds \right]       \nonumber
        \\
        & \quad + C t^{\frac{\eps}{2}} \sum_{\alpha = b, w} \E \left[ \int_0^t \Big| \phi_{\alpha} \big(\tilde{X}_{u_1}(s), ~ \bar{\mu}_{m_1}(s) \big) - \phi_{\alpha} \big(\tilde{X}_{u_2}(s), ~ \bar{\mu}_{m_2}(s) \big) \Big|^{2+\eps} ds \right]        \nonumber
        \\
        &\le C \E \left[ \big| \tilde{X}_{u_1}(0) - \tilde{X}_{u_2}(0) \big|^{2+\eps} \right]   \label{ineq: u1 u2 bound}
        \\
        & \quad + C_t \sum_{\alpha = p, b, w} \E \left[ \int_0^t \Big| \phi_{\alpha} \big(X_{u_1}(s), ~ \bar{\mu}_{m_1}(s) \big) - \phi_{\alpha} \big(X_{u_2}(s), ~ \bar{\mu}_{m_2}(s) \big) \Big|^{2+\eps} ds \right].  \nonumber
    \end{align}
    Here and in what follows, $C$ is a positive constant depending only on $\eps$, and $C_t$ is a positive constant depending on $t$ and $\eps$, but their values may change from line to line. From the Lipschitz property of $\phi_{\alpha}$ for $\alpha = p, b, w$, we have
    \begin{align}
        \Big| \phi_{\alpha} \big(\tilde{X}_{u_1}(s), ~ \bar{\mu}_{m_1}(s) \big) &- \phi_{\alpha} \big(\tilde{X}_{u_2}(s), ~ \bar{\mu}_{m_2}(s) \big) \Big|^{2+\eps} \label{ineq: 4th moment}
        \\
        & \qquad \qquad \qquad \le C \Big( \big|\tilde{X}_{u_1}(s)-\tilde{X}_{u_2}(s)\big|^{2+\eps} + \Wop_2^{2+\eps}\big(\bar{\mu}_{m_1}(s), \bar{\mu}_{m_2}(s) \big) \Big).   \nonumber
    \end{align}

    To compute the $\Wop$ term, Lemma~\ref{Lem: WOP R^d} (ii) yields the identity for any $s \in [0, T]$
    \begin{align*}
        \Wop_2^2(\bar{\mu}_{u_1}(s), \bar{\mu}_{u_2}(s))
        \le (m_{u_1} - m_{u_2})^2 &+ |m_{u_1} - m_{u_2}| \cdot \big|M_0(\bar{\mu}_{u_1}(s)) - M_0(\bar{\mu}_{u_1}(s))\big| \\
        &+ m_{u_1}m_{u_2}\Wc_2^2(\bar{\bar{\mu}}_{u_1}(s), \bar{\bar{\mu}}_{u_2}(s)). 
    \end{align*}
    For the first two terms on the right-hand side, Assumption \ref{ass: G Lipschitz} implies
    \begin{equation*}
        (m_{u_1} - m_{u_2})^2 \le |u_1-u_2|^2 \int_0^1 L^2_v dv, \qquad |m_{u_1} - m_{u_2}| \le |u_1-u_2| \int_0^1 |L_v| dv,
    \end{equation*}
    and we have
    \begin{equation*}
        \E\big| M_{0}(\bar{\mu}_{u_1}(s)) - M_{0}(\bar{\mu}_{u_2}(s)) \big| \le 2 \sup_{u \in [0, 1]} \E \Vert X_u \Vert^2_{*, T} < \infty
    \end{equation*}
    from Lemma \ref{lem: unique pathwise solution}. For the last term, we discuss two cases.
    If $m_{{u_1}}= 0$ or $m_{u_2} = 0$, then
    \begin{align}
        \E[\Wop_2^2(\bar{\mu}_{u_1}(s), \bar{\mu}_{u_2}(s))]
        &\le (m_{u_1} - m_{u_2})^2 + |m_{u_1} - m_{u_2}| \cdot \E\big|M_0(\bar{\mu}_{u_1}(s)) - M_0(\bar{\mu}_{u_1}(s))\big|  \nonumber
        \\
        &\le C|u_1-u_2|.    \label{ineq: Wop u1u2 bound0}
    \end{align}
    Otherwise, Theorem 6.15 of \cite{villani2016optimal} yields
    \begin{equation}    \label{W bar bar bound}
        \Wc_2^2(\bar{\bar{\mu}}_{u_1}(s), \bar{\bar{\mu}}_{u_2}(s)) \le 2\int_{\R^d} |x|^2 |\bar{\bar{\mu}}_{u_1}(s) - \bar{\bar{\mu}}_{u_2}(s)|(dx)
        = 2 \int_0^1 \bigg| \frac{G_{u_1, v}}{m_{u_1}} - \frac{G_{u_2, v}}{m_{u_2}} \bigg| \int_{\R^d} |x|^2 \mu_v(s)(dx)dv.
    \end{equation}
    We now derive
    \begin{align*}
        m_{{u_1}}m_{{u_2}}\bigg| \frac{G_{u_1, v}}{m_{u_1}} - \frac{G_{u_2, v}}{m_{u_2}} \bigg|
        &= m_{{u_1}}m_{{u_2}}\bigg| \frac{G_{u_1, v}}{m_{u_1}} - \frac{G_{u_2, v}}{m_{u_1}} + \frac{G_{u_2, v}}{m_{u_1}} - \frac{G_{u_2, v}}{m_{u_2}} \bigg|
        \\ & \le m_{{u_2}}|G_{u_1, v}-G_{u_2, v}| + G_{u_2, v}|m_{u_2}-m_{u_1}|
        \\
        & \le |G_{u_1, v}-G_{u_2, v}| + |m_{u_2}-m_{u_1}|
        \\
        & \le  |u_1-u_2| |L_v| + |u_1-u_2| \int_0^1 |L_v| dv,
    \end{align*}
    where the last inequality uses Assumption \ref{ass: G Lipschitz}. Thus, the inequality \eqref{W bar bar bound} becomes
    \begin{equation*}
         m_{{u_1}}m_{{u_2}}
         \E[\Wc_2^2(\bar{\bar{\mu}}_{u_1}(s), \bar{\bar{\mu}}_{u_2}(s))]
        \le 2 |u_1-u_2| \Big(\sup_{u \in [0, 1]} \E \Vert X_u \Vert^2_{*, T} \Big) \int_0^1 |L_v|dv,
    \end{equation*}
    and then there exists $C>0$ that depends on the previous constants $K, \int_0^1|L_v|dv, \int_0^1|L_v|^2 dv$, and $\sup_{u \in [0, 1]} \E \Vert X_u \Vert^2_{*, T}$ satisfying
    \begin{equation}    \label{ineq: Wop u1u2 bound}
        \E[\Wop_2^2(\bar{\mu}_{u_1}(s), \bar{\mu}_{u_2}(s))]
        \le C|u_1-u_2|, \qquad \forall \, s \in [0, T].
    \end{equation}
    Therefore, by combining \eqref{ineq: Wop u1u2 bound} (or \eqref{ineq: Wop u1u2 bound0}) with \eqref{ineq: 4th moment}, the inequality \eqref{ineq: u1 u2 bound} becomes for any $t \in [0, T]$
    \begin{align*}
        \E \left[ \Vert \tilde{X}_{u_1}-\tilde{X}_{u_2} \Vert^{2+\eps}_{*, t} \right]
        \le & C \E \left[ \big| \tilde{X}_{u_1}(0) - \tilde{X}_{u_2}(0) \big|^{2+\eps} \right]
        \\
        & \qquad + C_t \int_0^t \E \left[ \big|\tilde{X}_{u_1}(s) - \tilde{X}_{u_2}(s)\big|^{2+\eps} \right] ds + C_t |u_1-u_2|^{1 + \frac{\eps}{2}},
    \end{align*}
    and Gronwall's inequality yields
    \begin{align*}
        \E \left[ \Wc^{2+\eps}_2(\mu_{u_1},\mu_{u_2}) \right]
        &\le
        \E \left[ \Vert \tilde{X}_{u_1}-\tilde{X}_{u_2} \Vert^{2+\eps}_{*, T} \right]
        \le
        C \E \left[ \big| \tilde{X}_{u_1}(0) - \tilde{X}_{u_2}(0) \big|^{2+\eps} \right] + C|u_1-u_2|^{1 + \frac{\eps}{2}}
        \\
        &= C \E \left[ \E \big| \tilde{X}_{u_1}(0) - \tilde{X}_{u_2}(0) \big|^{2+\eps} \bigg| W\right]  + C|u_1-u_2|^{1 + \frac{\eps}{2}}.
    \end{align*}
    Here, the constant $C$ now depends on $T$. Taking the infimum over the conditional random variables satisfying $\mathcal{L}(X_{u_i}(0)|W) = \mu_{u_i}(0)$ for $i=1, 2$, we obtain
    \begin{equation}   \label{ineq: W^2_2}
        \E \left[ \Wc^{2+\eps}_2(\mu_{u_1},\mu_{u_2}) \right]
        \le C \E \left[ \Wc^{2+\eps}_{2+\eps} \big(\mu_{u_1}(0),\mu_{u_2}(0) \big) \right] + C|u_1-u_2|^{1 + \frac{\eps}{2}} \le C|u_1-u_2|^{1 + \frac{\eps}{2}}.
    \end{equation}
    Here, the last inequality uses Assumption \ref{ass: G Lipschitz}, and note that $\mathcal{P}_2(\mathcal{C}^d)$ is complete and separable. %https://almostsuremath.com/2020/10/20/the-kolmogorov-continuity-theorem/

    For each $n \in \N$, we denote $D_n = \{k/2^n, ~k = 0, \cdots, 2^n\}$ and $D = \bigcup_{n \in \N} D_n$. For $\gamma < \frac{\eps}{2(2+\eps)}$, Markov's inequality gives
    \begin{align*}
        \P \left( \max_{1 \le k \le 2^n} \W_2(\mu_{k/2^n}, \mu_{(k-1)/2^n}) \ge 2^{-\gamma n} \right)
        &= \P \left( \bigcup_{1 \le k \le 2^n} \W_2(\mu_{k/2^n}, \mu_{(k-1)/2^n}) \ge 2^{-\gamma n} \right)
        \\
        &\le \sum_{k=1}^{2^n} \P \left( \W_2(\mu_{k/2^n}, \mu_{(k-1)/2^n}) \ge 2^{-\gamma n} \right)
        \\
        & \le \sum_{k=1}^{2^n} 2^{(2+\eps)\gamma n} \, \E \left[ \W^{2+\eps}_2(\mu_{k/2^n}, \mu_{(k-1)/2^n}) \right].
    \end{align*}      
    From the inequality \eqref{ineq: W^2_2}, 
    \begin{align*}
        \P \left( \max_{1 \le k \le 2^n} \W_2(\mu_{k/2^n}, \mu_{(k-1)/2^n}) \ge 2^{-\gamma n} \right)
        \le C \sum_{k=1}^{2^n} \left(2^{(2+\eps)\gamma n} \times \frac{1}{2^{n(1+\frac{\eps}{2})}} \right) = C 2^{-(\frac{\eps}{2}-(2+\eps)\gamma)n},
    \end{align*}    
    thus, recalling $\gamma < \frac{\eps}{2(2+\eps)}$,
    \begin{align*}
        \sum_{n \in \N} \P \left( \max_{1 \le k \le 2^n} \W_2(\mu_{k/2^n}, \mu_{(k-1)/2^n}) \ge 2^{-\gamma n} \right) < \infty.
    \end{align*}
    The Borel-Cantelli lemma shows that there exists an almost surely finite random variable $Y$ such that
    \begin{align*}
        \P \left( \max_{1 \le k \le 2^n} \W_2(\mu_{k/2^n}, \mu_{(k-1)/2^n}) < Y2^{-\gamma n} \text{ for all } n \in \N \right) = 1.
    \end{align*}
    We now claim that the mapping $u \longmapsto \mu_u$ restricted to the dyadic points $D$ is almost surely $\gamma$-H\"older continuous in $\Wc_2$. For any $u, v \in D$ with $u \neq v$, we can find $n \in \N$ such that
    \[
        2^{-(n+1)} \le |u-v| \le 2^{-n}.
    \]
    We let $u_n \in D_n$ and $v_n \in D_n$ the nearest points from $u$ and $v$, respectively, such that $u_n$ and $v_n$ are consecutive points of $D_n$. Moreover, there exist two finite monotone sequences $\{u_i\}_{i=n}^{\ell_1} \subset D$ and $\{v_i\}_{i=n}^{\ell_2} \subset D$ converging to $u$ and $v$, respectively, such that $u_i, v_i \in D_i$ and
    \[
        |u_{i+1}-u_i| = 2^{-(i+1)} \text{ or } 0, \qquad |v_{i+1}-v_i| = 2^{-(i+1)} \text{ or } 0.
    \]
    The triangle inequality yields
    \begin{align*}
        \Wc_2(\mu_u, \mu_v) &\le \sum_{i=n+1}^{\ell_1} \Wc_2(\mu_{u_{i}}, \mu_{u_{i-1}}) + \Wc_2(\mu_{u_n}, \mu_{v_n}) + \sum_{i=n+1}^{\ell_2} \Wc_2(\mu_{v_{i}}, \mu_{v_{i-1}})
        \\
        &\le 2Y\sum_{i=n+1}^{\infty} 2^{-\gamma i} + Y2^{-\gamma n}
        \le \frac{2Y}{1-2^{-\gamma}}2^{-\gamma n}
        \le \frac{2^{\gamma+1}Y}{1-2^{-\gamma}} |u-v|^{\gamma},
    \end{align*}
    and this proves the claim.

    Consider now an event $A \subset \Omega$ on which $Y < \infty$ with $\P(A)=1$ and choose any fixed $\rho \in \mathcal{P}(\mathcal{C}^d)$ to define the (spatial) modification 
    \begin{align*}
        \tilde{\mu}_u(\omega) = 
        \begin{cases}
            \lim_{\substack{v \to u \\ v \in D}} \mu_v(\omega), \qquad &\text{if } \omega \in A,
            \\
            ~~~~~ \rho, \qquad &\text{otherwise}.
        \end{cases}
    \end{align*}
    By the uniform continuity, the limit over $D$ exists and $u \to \tilde{\mu}_u$ is $\gamma$-H\"older continuous on $[0, 1]$. Furthermore, $\tilde{\mu}$ is indeed a spatial modification of $\mu$; for any $u \in [0, 1]$ and a sequence $\{u_n\}_{n \in \N} \subset D$ converging to $u$, Fatou's lemma and \eqref{ineq: W^2_2} give
    \begin{align*}
        \E [\Wc^{2+\eps}_2(\mu_u, \tilde{\mu}_u)] \le \liminf_{n \to \infty} \E [\Wc^{2+\eps}_2(\mu_u, \mu_{u_n})] \le \lim_{n \to \infty} C|u-u_n|^{1+\frac{\eps}{2}} = 0,
    \end{align*}
    and this shows $\mu_u = \tilde{\mu}_u$ almost surely.
\end{proof}

\medskip

\begin{proof} [Proof of Lemma \ref{lem : W2 joint law conv}]
    The proof consists of 3 parts.

    \textbf{Part 1:} $\{\Lc(\bar{\mu}^n,\bar{\mu})\}_{n \in \N}$ is tight in $\mathcal{P}(\mathcal{P}(\mathcal{C}^d) \x \mathcal{P}(\mathcal{C}^d))$. \\
    The tightness of $\{\Lc(\bar{\mu}^n,\bar{\mu})\}_{n \in \N}$ in $\mathcal{P}(\mathcal{P}(\mathcal{C}^d) \x \mathcal{P}(\mathcal{C}^d))$ is equivalent to the tightness of  $\{\Lc(\bar{\mu}^n)\}_{n \in \N}$ in $\mathcal{P}(\mathcal{P}(\mathcal{C}^d))$, which will hold true if and only if
    $\frac{1}{n}\sum_{i=1}^n \mathcal{L}(X_{i/n})$ is tight in $\mathcal{P}(\mathcal{C}^d)$ from Chapter I (2.5) in \cite{sznitman}.

    To show the latter condition, we first denote $\mathcal{T}$ the collection of all $\mathbb{F} = (\mathcal{F}_t)_{t \in [0, T]}$-stopping times. We obtain that there exists a constant $C>0$, independent of $n$, satisfying for all $i \in [n]$ and $n \in \N$
    \begin{align}
        & ~
        \sup_{\tau \in \mathcal{T}} \E \Big|X_{i/n}\big((\tau + \epsilon) \wedge T \big) - X_{i/n}(\tau) \Big|^2 \nonumber
        \\
        ~ = & ~
        \sup_{\tau \in \mathcal{T}} \E \Big|
            \int_{\tau}^{(\tau + \varepsilon)\wedge T}
            \widetilde{\phi_p}(i/n) dt
            ~ + ~
            \int_{\tau}^{(\tau + \varepsilon)\wedge T} \widetilde{\phi_b}(i/n) dB_{i/n}(t)
            ~ + ~
            \int_{\tau}^{(\tau + \varepsilon)\wedge T} \widetilde{\phi_w}(i/n) dW(t) \Big|^2 \nonumber
        \\
        ~ \le & ~
        C\sup_{\tau \in \mathcal{T}} \E \bigg[ 
            \int_{\tau}^{(\tau + \varepsilon)\wedge T}
            |\widetilde{\phi_p}(i/n)|^2+
            |\widetilde{\phi_b}(i/n)|^2+
            |\widetilde{\phi_w}(i/n)|^2 dt
        \bigg] 
        \le C \epsilon, \label{ineq: bounded sup stopping times}
    \end{align}
    where for each $u \in [0,1]$ and $\alpha = p, b, w$,
    \begin{align*}
        \widetilde{\phi_{\alpha}}(u)
        ~ := ~
        \phi_{\alpha} \bigg(X_u(t), ~ \int_0^1 G_{u, v} \mu_v(t) dv \bigg).
    \end{align*}
    The inequality \eqref{ineq: bounded sup stopping times} is straightforward from the boundedness of $\phi$ and $\psi$'s. Thanks to Markov's inequality, the condition \eqref{ineq: bounded sup stopping times} now implies for any $a >0$ and $n \in \N$
    \begin{equation*}
        \sup_{\tau \in \mathcal{T}} \frac{1}{n} \sum_{i=1}^n \P \bigg[ \Big|X_{i/n}\big((\tau + \epsilon) \wedge T \big) - X_{i/n}(\tau) \Big| \ge a \bigg] \le \frac{C\epsilon}{a^2},
    \end{equation*}
    which provides the tightness of $\frac{1}{n}\sum_{i=1}^n \mathcal{L}(X_{i/n})$ in $\mathcal{P}(\mathcal{C}^d)$ from Aldous's criterion (see, e.g., (16.23) of \cite{billingsley}).

    \smallskip

    \textbf{Part 2:} Weak convergence of 
    $ \Lc(\bar{\mu}^n,\bar{\mu})  \xlongrightarrow{n \to \infty} \Lc(\bar{\mu},\bar{\mu}) $. \\
    For each $m \in \N$, consider $(m + 1)$ many of arbitrary test functions $\{h_i\}_{i \in [m]} \subset C_b(\mathcal{C}^d)$, and $f \subset C_b(\Cc^d)$. We shall show the convergence
    \begin{equation}    \label{conv: test functions}
        \int_{\mathcal{P}(\mathcal{C}^d) \times \mathcal{P}(\mathcal{C}^d)}
            \prod_{i=1}^m \langle h_i, \nu \rangle \langle f,\nu' \rangle
        \Lc(\bar{\mu}^n,\bar{\mu}) (d\nu, d\nu') 
        \xlongrightarrow{n \to \infty} 
        \int_{\mathcal{P}(\mathcal{C}^d) \times \mathcal{P}(\mathcal{C}^d)}
            \prod_{i=1}^m \langle h_i, \nu\rangle  \langle f,\nu' \rangle
        \Lc(\bar{\mu},\bar{\mu}) (d\nu, d\nu')
    \end{equation}
    For simplicity, we consider the case $m = 2$, then the left-hand side of \eqref{conv: test functions} can be expressed as
    \begin{align*}
        & \quad \ \frac{1}{n^2}\sum_{i=1}^n \sum_{j=1}^n \E \Big[h_{1}(X_{i/n}) h_{2}(X_{j/n}) \langle f,\bar{\mu} \rangle\Big] 
        = \frac{1}{n^2} \sum_{i=1}^n \sum_{j=1}^n \E \Bigg[ \E \Big[ h_{1}(X_{i/n}) h_{2}(X_{j/n}) \big| W \Big] 
        \langle f,\bar{\mu} \rangle\Bigg]
        \\
        & = \frac{1}{n^2} \sum_{i=1}^n \E \Bigg[ \E \Big[ h_{1}(X_{i/n}) h_{2}(X_{i/n}) \big| W \Big] \langle f,\bar{\mu} \rangle \Bigg] 
        + 
        \frac{2}{n^2} \sum_{i<j} \E \Bigg[ \E \Big[ h_{1}(X_{i/n}) h_{2}(X_{j/n}) \big| W \Big] \langle f,\bar{\mu} \rangle \Bigg]
        \\
        & = \frac{1}{n^2} \sum_{i=1}^n \E \Bigg[ \E \Big[ h_{1}(X_{i/n}) h_{2}(X_{i/n}) \big| W \Big] \langle f,\bar{\mu} \rangle\Bigg] + \frac{2}{n^2} \sum_{i<j} \E \Bigg[ \E \Big[ h_{1}(X_{i/n}) \big| W \Big] \E \Big[ h_{2}(X_{j/n}) \big| W \Big] \langle f,\bar{\mu} \rangle\Bigg]
        \\
        & = \frac{1}{n^2} \sum_{i=1}^n \E \Bigg[ \E \Big[ h_{1}(X_{i/n}) \big| W \Big] \E \Big[ h_{2}(X_{i/n}) \big| W \Big] \langle f,\bar{\mu} \rangle\Bigg] 
        + \frac{2}{n^2} \sum_{i<j} \E \Bigg[ \E \Big[ h_{1}(X_{i/n}) \big| W \Big] \E \Big[ h_{2}(X_{j/n}) \big| W \Big] \langle f,\bar{\mu} \rangle\Bigg]
        \\
        & \qquad \qquad + \frac{1}{n^2} \sum_{i=1}^n \E \Bigg[ \bigg(\E \Big[ h_{1}(X_{i/n}) h_{2}(X_{i/n}) \big| W \Big] - \E \Big[ h_{1}(X_{i/n}) \big| W \Big] \E \Big[ h_{2}(X_{i/n}) \big| W \Big]\bigg)\langle f,\bar{\mu} \rangle \Bigg]
        \\
        &= \E \Bigg[ \bigg( \frac{1}{n} \sum_{i=1}^n \E \Big[ h_{1}(X_{i/n}) \big| W \Big] \bigg) \bigg( \frac{1}{n} \sum_{j=1}^n \E \Big[ h_{2}(X_{j/n}) \big| W \Big] \bigg) \langle f,\bar{\mu} \rangle \Bigg]
        \\
       & \qquad \qquad + \frac{1}{n^2} \sum_{i=1}^n \E \Bigg[ \bigg(\E \Big[ h_{1}(X_{i/n}) h_{2}(X_{i/n}) \big| W \Big] - \E \Big[ h_{1}(X_{i/n}) \big| W \Big] \E \Big[ h_{2}(X_{i/n}) \big| W \Big]\bigg)\langle f,\bar{\mu} \rangle \Bigg].
    \end{align*}
    Here, the third equality uses the conditional independence of $X^n_i$ and $X^n_j$ given $W$, whenever $i \neq j$. Since the functions $f, h_i$'s are bounded, say, by a constant $C>0$, the last term is bounded by
    \begin{equation*}
        \frac{1}{n^2} \sum_{i=1}^n \E \Bigg[ \bigg(\E \Big[ h_{1}(X_{i/n}) h_{2}(X_{i/n}) \big| W \Big] - \E \Big[ h_{1}(X_{i/n}) \big| W \Big] \E \Big[ h_{2}(X_{i/n}) \big| W \Big]\bigg)\langle f,\bar{\mu} \rangle \Bigg]
        \le 
        \frac{2C^3n}{n^2} = \frac{2C^3}{n}.
    \end{equation*}
    Taking limit $n \to \infty$, we can obtain the following convergence from Lemma \ref{lem: continuity of average measure}
    \begin{equation}    \label{conv into integral}
        \frac{1}{n} \sum_{i=1}^n \E \Big[ h_{1}(X_{i/n}) \big| W \Big] \xlongrightarrow{n \to \infty}  \int_0^1 \E \big[ h_1(X_u) | W \big] du,
        ~\P~\mbox{-a.s.}
    \end{equation}

    Therefore, from the Dominated Convergence Theorem, we obtain the convergence
    \begin{align*}
        \frac{1}{n^2} &\sum_{i=1}^n \sum_{j=1}^n \E \Big[h_{1}(X_{i/n}) h_{2}(X_{j/n})\langle f,\bar{\mu} \rangle\Big] \xlongrightarrow{n \to \infty} \E \bigg[ \langle h_1,\bar{\mu} \rangle\langle h_2,\bar{\mu} \rangle \langle f,\bar{\mu} \rangle \bigg] 
    \end{align*}
    and the last limit is equal to the right-hand side of \eqref{conv: test functions}. The general case $m > 2$ can be proven in a similar manner.
    Then, by Theorem \ref{thm: characterization2}, we can conclude the proof of part 2.

    \smallskip

    \textbf{Part 3:} Uniform integrability of $\Lc(\bar{\mu}^n,\mub)$. \\
    We shall show that
    \begin{align*}
        \lim_{a \to \infty} \sup_{n \in \N} \, 
        \E \bigg[ 
       \Big(\Wc^2_2(\bar{\mu}^n, \delta_0) + \Wc^2_2(\bar{\mu}, \delta_0) \Big)
        \mathbbm{1}_{\big\{\sqrt{\Wc^2_2(\bar{\mu}^n, \delta_0) + \Wc^2_2(\bar{\mu}, \delta_0) } \ge a \big\}} \bigg] = 0.
    \end{align*}
    From Markov's inequality, we derive
    \begin{align*}
        &\E \bigg[ 
        \Big(\Wc^2_2(\bar{\mu}^n, \delta_0) + \Wc^2_2(\bar{\mu}, \delta_0)\Big)
        \mathbbm{1}_{\big\{\sqrt{\Wc^2_2(\bar{\mu}^n, \delta_0) + \Wc^2_2(\bar{\mu}, \delta_0) } \ge a \big\}} \bigg]
        \le \frac{1}{a^{\eps}} \sup_{n \in \N} \, \E \Big[ \big(\Wc^2_2(\bar{\mu}^n, \delta_0) + \Wc^2_2(\bar{\mu}, \delta_0) \big)^{1 + \eps/2}\Big]
        \\
        & \qquad \qquad \qquad \qquad \qquad \qquad \le \frac{C}{a^{\eps}} \sup_{n \in \N} \, \bigg( \frac{1}{n} \sum_{i=1}^n \E \Big[ \sup_{t \in [0, T]} |X_{i/n}(t)|^{2 + \eps} \Big] \bigg)
        + \frac{C}{a^{\eps}} \E \big[\Wc^{2 + \eps}_2(\bar{\mu}, \delta_0) \big].
    \end{align*}
    Similar to \eqref{ineq: bounded sup stopping times}, thanks to the boundedness of $\phi$'s, there exists a constant $C>0$ such that the first term on the right-hand side is bounded by $CT/a$. Sending $a \to \infty$ yields the desired uniform integrability.

    Lemma \ref{lem : villani} (ii) with the results in Parts 2 and 3 proves the result \eqref{conv: W2 ppcd}.
\end{proof}

