\begin{proof} [Proof of Theorem \ref{thm: weighted mean W2 continuity}]
    We first denote the positive measures for any $i \in [n]$ and $n \in \N$
    \begin{align*}
        \bar{\mu}^n_i := \frac{1}{n}\sum_{j = 1}^n G^n_{i,j}\delta_{X_{{j/n}}}, \qquad \bar{\mu}_{{i/n}} := \int_{0}^1 G_{{i/n},v}\mu_vdv,
    \end{align*}
    with their total masses
    \begin{equation*}
        m_{\bar{\mu}^n_i} = \frac{1}{n}\sum_{j=1}^n G^n_{i, j}, \qquad m_{\bar{\mu}_{{i/n}}} = \int_0^1 G_{{i/n}, v}dv.
    \end{equation*}
    Similar to the proof of Theorem \ref{thm: bar mu_n to bar mu} with 
    $X := \Mc_{2,K}(\Cc^d) \x \Mc_{2,K}(\Cc^d)$, $\nu_n := \frac{1}{n}\sum_{i = 1}^n\Lc(\bar{\mu}^n_i,\bar{\mu}_{{i/n}})$,
    $\nu := \int_0^1 \Lc(\bar{\mu}_u,\bar{\mu}_u)du$, 
    $\varphi(\mu) := \varphi(\mu_1,\mu_2) := \Wop^2_2(\mu_1,\mu_2)$,
    it is sufficient to prove that
    \begin{equation}\label{eq: bar bar bar bar}
        \lim_{n \to \infty}\Wc_2\bigg(
        \frac{1}{n}\sum_{i = 1}^n\Lc(\bar{\mu}^n_i,\bar{\mu}_{{i/n}}), 
        \int_0^1 \Lc(\bar{\mu}_u,\bar{\mu}_u)du\bigg)
        ~ = ~ 0.
    \end{equation}
    The proof of \eqref{eq: bar bar bar bar} consists of 3 parts.

    \smallskip

    {\noindent\textbf{Part 1:} Tightness.}

    We shall prove the tightness of $\{\Lc(\bar{\mu}^n_i,\bar{\bar{\mu}}_{{i/n}})\}_{n \in \N, i \in [n]}$ in $\mathcal{P}(\Mc_{2,K}(\Cc^d) \x \Mc_{2,K}(\Cc^d))$, which is equivalent to the tightness of  $\{\Lc(\bar{\mu}^n_i)\}_{n \in \N, i \in [n]}$ and $\{\Lc(\bar{\mu}_{{i/n}})\}_{n \in \N, i \in [n]}$ in $\mathcal{P}(\Mc_{2,K}(\Cc^d))$. From Chapter I (2.5) in \cite{sznitman}, this will hold true if
    \begin{equation}    \label{two tightness}
        \left\{\frac{1}{n}\sum_{j=1}^n G^n_{i,j} \mathcal{L}(X_{{j/n}})\right\}_{n \in \N, i \in [n]} \qquad \text{and} \qquad \left\{ \int_0^1 G_{{i/n},v}\Lc(X_v)dv \right\}_{n \in \N, i \in [n]}
    \end{equation}
    are tight in $\mathcal{M}_{2,K}(\mathcal{C}^d)$.

    To show the latter condition, we first recall $\mathcal{T}$ the collection of all $\mathbb{F} = (\mathcal{F}_t)_{t \in [0, T]}$-stopping times. Similar to \eqref{ineq: bounded sup stopping times}, we obtain that there exists a constant $C>0$, independent of $v \in [0,1]$, satisfying 
    \begin{equation*}
        \sup_{\tau \in \mathcal{T}} \E \Big|X_{v}\big((\tau + \epsilon) \wedge T \big) - X_{v}(\tau) \Big|^2 \le C \epsilon.
    \end{equation*}
    Then, due to Markov's inequality, it follows that for any $a >0$ and $n \in \N$
    \begin{equation*}
        \sup_{\tau \in \mathcal{T}} \P \bigg[ \Big|X_{v}\big((\tau + \epsilon) \wedge T \big) - X_{v}(\tau) \Big| \ge a \bigg] 
        \le 
        \frac{C\epsilon}{a^2},
    \end{equation*}    
    which provides the tightness of $\Lc(X_v)$ in $\mathcal{P}(\mathcal{C}^d)$ from Aldous's criterion (e.g., (16.23) of \cite{billingsley}).
    Then naturally, we have tightness of \eqref{two tightness} in $\Mc_{2,K}(\Cc^d)$, thus tightness of $\{\Lc(\bar{\mu}^n_i,\bar{\bar{\mu}}_{{i/n}})\}_{n \in \N, i \in [n]}$ in $\mathcal{P}(\Mc_{2,K}(\Cc^d) \x \Mc_{2,K}(\Cc^d))$.

    \smallskip

    {\noindent \textbf{Part 2:} Weak convergence of $\frac{1}{n}\sum_{i = 1}^n\Lc({\bar{\mu}}^n_i, \bar{{\mu}}_{{i/n}})$ to
    $\int_0^1 \Lc({\bar{\mu}}_{u},\bar{{\mu}}_{u}) du$.}

    For each $m,\ell \in \N$, consider $(m + \ell)$ many of arbitrary test functions $\{h_j\}_{j \in [m]} \subset C_b(\mathcal{C}^d)$, and $\{f_k\}_{k \in [\ell]} \subset C_b(\Cc^d)$. We shall show the convergence
    \begin{align}    
        \int_{\Mc_K(\mathcal{C}^d) \times \Mc_K(\mathcal{C}^d)} \prod_{j=1}^m \langle h_j, \nu \rangle \prod_{k=1}^\ell &\langle f_k,\nu' \rangle \frac{1}{n}\sum_{i = 1}^n\Lc({\bar{\mu}}^n_i, \bar{{\mu}}_{{i/n}}) (d\nu, d\nu') ~
        \xlongrightarrow{n \to \infty} \nonumber
        \\
        &\int_{\Mc_K(\mathcal{C}^d) \times\Mc_K(\mathcal{C}^d)} \prod_{j=1}^m \langle h_j, \nu \rangle \prod_{k=1}^\ell \langle f_k,\nu' \rangle \int_0^1 \Lc(\bar{{\mu}}_{u},\bar{{\mu}}_{u}) du (d\nu, d\nu').  \label{conv: test functions22}
    \end{align}
    For simplicity, we consider the case $m = \ell = 2$, and obtain the following identity from the conditional independence between $X_{{i/n}}$ and $X_{{j/n}}$ given $W$:
    \begin{align}
        ~ & \frac{1}{n^2}\sum_{i=1}^n \sum_{j=1}^n \frac{1}{n}\sum_{k=1}^n G^n_{k,i}G^n_{k,j}
        \E \Big[h_{1}(X_{{i/n}}) h_{2}(X_{{j/n}}) 
            \int_{0}^{1} G_{\frac{k}{n},v}
                \langle f_1, \mu_v \rangle \langle f_2, \mu_v \rangle dv\Big]   \label{eq : m=l=22}
        \\
         =  & \frac{1}{n}\sum_{k = 1}^n 
        \E \Bigg[ \bigg( \frac{1}{n} \sum_{i=1}^n 
            G^n_{k,i} \E \Big[ h_{1}(X_{{i/n}}) \big| W \Big] \bigg) 
        \bigg( \frac{1}{n} \sum_{j=1}^n 
           G^n_{k,j}\E \Big[ h_{2}(X_{{j/n}}) \big| W \Big] \bigg) 
        \int_{0}^{1}
            G_{\frac{k}{n},v}  \langle f_1, \mu_v \rangle \langle f_2, \mu_v \rangle dv\Bigg]    \nonumber
    \end{align}

    On one hand, by setting $\Gt^n_{i,j} := G_{i/n,j/n}$ for $i,j \in [n]$, we have from Lemma \ref{lem: continuity of average measure} and the fact that the Riemann sum of the corresponding integral will converge to that integral
    \begin{align*}
        \frac{1}{n} \sum_{i=1}^n \Gt^n_{k,i}\E \Big[ h_{1}(X_{{i/n}}) \big| W \Big] 
        \xlongrightarrow{n \to \infty, ~ k/n \to u}  
        \int_0^1 {G_{u,v}}\E \big[ h_1(X_v) | W \big] dv,
        ~\P(d\omega)\otimes du~\mbox{-a.e.,}
    \end{align*}
        Therefore, by the dominated convergence theorem, we obtain the convergence
    \begin{align*}
        \lim_{n \to \infty}
        \frac{1}{n}\sum_{k = 1}^n
        \E
        \bigg|\frac{1}{n} \sum_{i=1}^n \Gt^n_{k,i}\E \Big[ h_{1}(X_{{i/n}}) \big| W \Big] 
        -
        \int_{0}^{1} G_{\frac{k}{n},v}\E \Big[ h_{1}(X_{v}) \big| W \Big]dv
        \bigg|
        ~ = ~
        0,
    \end{align*}
    if we view the following expression as a piecewise constant function on $[0,1]$: 
    \begin{align*}
        H^n(u) := \sum_{k = 1}^n
        \bigg|\frac{1}{n} \sum_{i=1}^n \Gt^n_{k,i}\E \Big[ h_{1}(X_{{i/n}}) \big| W \Big] 
        -
        \int_{0}^{1} G_{\frac{k}{n},v}\E \Big[ h_{1}(X_{v}) \big| W \Big]dv
        \bigg|\mathbbm{1}_{[\frac{k-1}{n},\frac{k}{n})}(u), \qquad \forall \, u \in [0, 1],
    \end{align*}
    which converges pointwise to zero as $n \to \infty$, so that
    \begin{equation*}
        \frac{1}{n}\sum_{k = 1}^n
        \E
        \bigg|\frac{1}{n} \sum_{i=1}^n \Gt^n_{k,i}\E \Big[ h_{1}(X_{{i/n}}) \big| W \Big] 
        -
        \int_{0}^{1} G_{\frac{k}{n},v}\E \Big[ h_{1}(X_{v}) \big| W \Big]dv
        \bigg|
        = \int_0^1\E[H^n(u)]du \xlongrightarrow{n \to \infty} 0.
    \end{equation*}
    On the other hand, the following convergence
    \begin{align*}
        \frac{1}{n}\sum_{k = 1}^n\E\bigg|\frac{1}{n} \sum_{i=1}^n (\Gt^n_{k,i} - G^n_{k,i})\E \Big[ h_{1}(X_{{i/n}}) \big| W \Big]\bigg| 
        ~ = ~ 0,
    \end{align*}
    holds true due to Lemma 8.11 in \cite{lovasz}, i.e., if $\|G - G_n\|_\square \longrightarrow 0$,
    then $\|G - G_n\|_{\infty \to 1} \longrightarrow 0$, where
    for graphon $G$
    \begin{align*}
        \|G\|_{\infty \to 1} := \sup_{\|g\|_\infty \le 1}\int_0^1\bigg|\int_0^1 G_{u, v} g(v)\, dv\bigg|\,du.
    \end{align*}

    Thus, by taking $n \to \infty$, the identity \eqref{eq : m=l=22} becomes 
    \begin{align*}
        & \lim_{n \to \infty}\frac{1}{n^2}\sum_{i=1}^n \sum_{j=1}^n \frac{1}{n}\sum_{k=1}^n G^n_{k,i}G^n_{k,j}
        \E \Big[h_{1}(X_{{i/n}}) h_{2}(X_{{j/n}}) 
        \int_{0}^{1}
            G_{\frac{k}{n},v}\langle f_1, \mu_v \rangle \langle f_2, \mu_v \rangle dv\Big] 
        \\
        = & \lim_{n \to \infty} \frac{1}{n}\sum_{k = 1}^n 
        \E \Bigg[ \prod_{i=1}^2 \bigg( \int_{0}^{1} 
        G_{\frac{k}{n},v}\E \Big[ h_{i}(X_{v}) \big| W \Big]dv \bigg)
        \prod_{j=1}^2 \bigg( \int_{0}^{1} {G_{\frac{k}{n},v}}
            \E \Big[ f_{j}(X_{v}) \big| W \Big]dv \bigg) \Bigg]
        \\
        = & \int_{0}^{1}\E \Bigg[ \prod_{i=1}^2 \bigg( \int_{0}^{1} {G_{u,v}}\E \Big[ h_{i}(X_{v}) \big| W \Big]dv \bigg)
        \prod_{j=1}^2 \bigg( \int_{0}^{1} {G_{u,v}}\E \Big[ f_{j}(X_{v}) \big| W \Big]dv \bigg) \Bigg] du,
    \end{align*}
    and the last expression is equal to the right-hand side of \eqref{conv: test functions22}. The general case $m > 2$ can be proven in a similar manner.
    Then, by Theorem \ref{thm: characterization}, we can conclude the proof of part 2.

    \smallskip

    {\noindent \textbf{Part 3:} Uniform integrability of $\{\frac{1}{n}\sum_{i = 1}^n\Lc(\bar{{\mu}}^n_i, \bar{{\mu}}_{{i/n}})\}_{n \in \N}$.}

    It is sufficient to show the uniform integrability of $\{\Lc({\bar{\mu}}^n_i, \bar{{\mu}}_{{i/n}})\}_{n \in \N, i \in [n]}$, so we shall show that
    \begin{align*}
        \lim_{a \to \infty} \sup_{n \in \N} \, 
        \E \bigg[ 
       \Big(\Wop^2_2(\bar{{\mu}}^n_i, \delta_0) + \Wop^2_2({\bar{\mu}}_{{i/n}}, \delta_0) \Big)
        \mathbbm{1}_{\big\{\sqrt{\Wop^2_2(\bar{{\mu}}^n_i, \delta_0) + \Wop^2_2(\bar{{\mu}}_{{i/n}}, \delta_0) } \ge a \big\}} \bigg] = 0,
    \end{align*}
    whose proof is almost the same as that of Lemma \ref{lem : W2 joint law conv}.

    Finally, Parts 1-3 prove condition (ii) of Lemma \ref{lem : villani}, so the convergence \eqref{eq: bar bar bar bar} follows by condition (i). This completes the proof.
\end{proof}

