\begin{proof} [Proof of Theorem \ref{thm: weighted mean W2 squared}]
        We first denote for any $i \in [n]$ and $n \in \N$
        \begin{align*}
            \bar{\mu}^n_i := \frac{1}{n}\sum_{j = 1}^n G^n_{i,j}\delta_{X^n_j}, \qquad \bar{\mu}_{i/n} := \int_{0}^1 G_{i/n,v}\mu_vdv,
        \end{align*}
        and for any $t \in [0, T]$
        \begin{align*}
            \bar{\mu}^n_i(t) := \frac{1}{n} \sum_{j = 1}^n G^n_{i,j}\delta_{X^n_j(t)}, \qquad \bar{\mu}_{i/n}(t) := \int_{0}^1 G_{i/n,v}\mu_v(t)dv.
        \end{align*}

        Since we have the following bound for any $t \in [0, T]$ and $j \in [n]$
        \begin{align*}
            \big| X^n_j(t) - X_{j/n}(t) \big|^2 & \le C \bigg|\int_0^t \phi_p \big(X^n_j(s), \bar{\mu}^n_j(s) \big)  -  \phi_p \big(X_{{j/n}}(s), \bar{\mu}_{{j/n}}(s)\big) \, ds \bigg|^2
            \\
            & + C \bigg|\int_0^t \phi_b \big(X^n_j(s), \bar{\mu}^n_j(s) \big) - \phi_b \big(X_{{j/n}}(s), \bar{\mu}_{{j/n}}(s)\big)  \, dB_{{j/n}}(s) \bigg|^2
            \\
            & + C\bigg|\int_0^t \phi_w \big(X^n_j(s), \bar{\mu}^n_j(s)\big) -  \phi_w \big(X_{{j/n}}(s), \bar{\mu}_{{j/n}}(s)\big) \, dW(s) \bigg|^2,
        \end{align*}
        we use Burkholder-Davis-Gundy inequality, the triangle inequality, and the Lipschitz property of Assumption \ref{ass:Lipschitz} with the bound $m_{\bar{\mu}^n_j(s)} \le 1$, to derive
        \begin{align*}
        &\E \Big[\sup_{s \in [0,T]} \big| X^n_j(s) - X_{j/n}(s) \big|^2 \Big]
        \\\le &
        C\E\bigg[\int_0^T \sum_{\alpha = p, b, w} \Big| \phi_{\alpha} \big(X^n_j(s), \bar{\mu}^n_j(s)\big)  - \phi_{\alpha} \big(X_{{j/n}}(s), \bar{\mu}_{{j/n}}(s)\big) \Big|^2 \, ds \bigg]
        \\
        \le & ~ C\E\bigg[\int_0^T \sum_{\alpha = p, b, w} \Big| \phi_{\alpha} \big(X^n_j(s), \bar{\mu}^n_j(s)\big) 
        - \phi_{\alpha} \big(X_{{j/n}}(s), \bar{\mu}^n_j(s)\big) \Big|^2
        \\
        & \qquad\qquad\qquad\qquad\qquad\qquad\qquad + \sum_{\alpha = p, b, w} \Big| \phi_{\alpha} \big(X_{{j/n}}(s), \bar{\mu}^n_j(s)\big) 
        - \phi_{\alpha} \big(X_{{j/n}}(s), \bar{\mu}_{{j/n}}(s)\big) \Big|^2 \, ds\bigg]
        \\
        \le & ~ C\E \bigg[\int_0^T \big|X^n_j(s) - X_{j/n}(s) \big|^2 \, ds \bigg] +C\E\bigg[\int_0^T \Wop^2_2 \big(\bar{\mu}^n_j(s), \bar{\mu}_{{j/n}}(s) \big) \, ds \bigg]
        \\
        \le & ~ C\int_0^T \E\bigg[\sup_{s \in [0,t]} \big|X^n_j(s) - X_{j/n}(s)\big|^2\bigg] \, dt +C\E\bigg[\int_0^T\Wop^2_2 \big(\bar{\mu}^n_j(t), \bar{\mu}_{{j/n}}(t)\big) \, dt \bigg].
    \end{align*}
    Then, by Grownwall's inequality, it follows that
    \begin{align}   \label{ineq: W2 bound}
        \E\bigg[\sup_{t \in [0,T]} \big|X^n_j(t) - X_{j/n}(t) \big|^2 \bigg] ~ \le ~ C \E \bigg[\int_0^T \Wop^2_2 \big(\bar{\mu}^n_j(t), \bar{\mu}_{{j/n}}(t)\big) \, dt \bigg].
    \end{align}
    On the other hand, we obtain from the triangle inequality for $\Wop$ between the positive measures of $\mathcal{M}_2(\Cc^d)$
    \begin{align*}
        & ~ \frac{1}{n}\sum_{i = 1}^n \E\bigg[\Wop^2_2(\bar{\mu}^n_i,\bar{\mu}_{{i/n}})\bigg]
        \\
        \le & ~ \frac{2}{n}\sum_{i = 1}^n \E\bigg[ \Wop^2_2\bigg(\frac{1}{n}\sum_{j = 1}^n G^n_{i,j}\delta_{X^n_j}, \frac{1}{n}\sum_{j = 1}^n G^n_{i,j}\delta_{X_{j/n}}\bigg)\bigg]
        + \frac{2}{n}\sum_{i = 1}^n \E \bigg[\Wop^2_2\bigg( \frac{1}{n} \sum_{j = 1}^n G^n_{i,j} \delta_{X_{j/n}}, \bar{\mu}_{{j/n}} \bigg) \bigg].
    \end{align*}
    Writing the common total masses of the two measures as
    \begin{equation*}
        \bar{G}^n_i := \frac{1}{n}\sum_{j=1}^n G^n_{i, j} = m_{\frac{1}{n}\sum_{j = 1}^n G^n_{i,j}\delta_{X^n_j}} = m_{\frac{1}{n}\sum_{j = 1}^n G^n_{i,j}\delta_{X_{j/n}}},
    \end{equation*}
    when $\bar{G}^n_i > 0$,
    the term inside the first expectation can be expressed as
    \begin{align*}
        \Wop^2_2\bigg(\frac{1}{n}\sum_{j = 1}^n G^n_{i,j}\delta_{X^n_j}, \frac{1}{n}\sum_{j = 1}^n G^n_{i,j}\delta_{X_{j/n}}\bigg)
        &= \big( \bar{G}^n_i \big)^2 \Wc^2_2 \bigg( \frac{\frac{1}{n}\sum_{j = 1}^n G^n_{i,j}\delta_{X^n_j}}{\bar{G}^n_i}, \frac{\frac{1}{n}\sum_{j = 1}^n G^n_{i,j}\delta_{X_{j/n}}}{\bar{G}^n_i} \bigg)
        \\
        &\le \big(\bar{G}^n_i\big) \frac{1}{n}\sum_{j=1}^n G^n_{i, j} \sup_{t \in [0, T]} \big|X^n_j(t) - X_{j/n}(t)\big|^2
        \\
        & \le \frac{1}{n}\sum_{j=1}^n G^n_{i, j} \sup_{t \in [0, T]} \big|X^n_j(t) - X_{j/n}(t)\big|^2.
    \end{align*}
    Here, the first equality follows from \eqref{eq: WOP}, the first inequality uses the property of Wasserstein distance between the empirical measures with the coupling $\gamma = \frac{\frac{1}{n}\sum_{j=1}^n G^n_{i, j}\delta_{(x^n_j, X_{j/n})}}{\bar{G}^n_i}$, and the last inequality follows from the bound $\bar{G}^n_{i} \le 1$. 
    When $\bar{G}^n_i = 0$, the inequality still holds since they are all $0$.
    Therefore, we have
    \begin{align}
        & ~ \frac{1}{n}\sum_{i = 1}^n \E\bigg[\Wop^2_2(\bar{\mu}^n_i,\bar{\mu}_{{i/n}})\bigg]     \label{ineq: WOP before Gronwall}
        \\
        \le & ~ \frac{2}{n^2} \sum_{i,j = 1}^n G^n_{i,j} \E\bigg[\sup_{t \in [0,T]}|X^n_j(t) - X_{j/n}(t)|^2\bigg]
        +\frac{2}{n}\sum_{i = 1}^n \E\bigg[\Wop^2_2\bigg(\frac{1}{n}\sum_{j = 1}^n G^n_{i,j} \delta_{X_{j/n}},\bar{\mu}_{{j/n}}\bigg)\bigg]          \nonumber
        \\ \le & ~
        \frac{2C}{n^2}\sum_{i,j = 1}^n G^n_{i,j} \E\bigg[\int_0^T\Wop^2_2(\bar{\mu}^n_j(t),\bar{\mu}_{{j/n}}(t))dt\bigg]
        + \frac{2}{n}\sum_{i = 1}^n \E\bigg[\Wop^2_2\bigg(\frac{1}{n}\sum_{j = 1}^n G^n_{i,j} \delta_{X_{j/n}},\bar{\mu}_{{j/n}}\bigg)\bigg]          \nonumber
        \\ \le & ~
        2C\int_0^T\frac{1}{n}\sum_{j = 1}^n \E\Big[\Wop^2_2(\bar{\mu}^n_j(t),\bar{\mu}_{{j/n}}(t))\Big]dt
        +\frac{2}{n}\sum_{i = 1}^n \E\bigg[\Wop^2_2\bigg(\frac{1}{n}\sum_{j = 1}^n G^n_{i,j} \delta_{X_{j/n}},\bar{\mu}_{{j/n}}\bigg)\bigg],          \nonumber
    \end{align}
    where the second inequality uses \eqref{ineq: W2 bound} and the last one follows from the bound $G^n_{i, j} \le 1$.

    If we again write the common total masses of the two positive measures as
    \begin{equation*}
        \bar{G}^n_i := \frac{1}{n}\sum_{j=1}^n G^n_{i, j} = m_{\bar{\mu}^n_i} = m_{\bar{\mu}^n_i(t)}, \qquad \bar{G}_{{i/n}} := m_{\bar{\mu}_{{i/n}}} = m_{\bar{\mu}_{{i/n}}(t)}, \qquad \forall \, t \in [0, T],
    \end{equation*}
    respectively, and the probability measures
    \begin{equation*}
        \bar{\bar{\mu}}^n_i := \frac{\bar{\mu}^n_i}{\bar{G}^n_i}, \qquad \bar{\bar{\mu}}^n_i(t) := \frac{\bar{\mu}^n_i(t)}{\bar{G}^n_i}, \qquad \bar{\bar{\mu}}_{{i/n}} = \frac{\bar{\mu}_{{i/n}}}{\bar{G}^{{i/n}}}, \qquad \bar{\bar{\mu}}_{{i/n}}(t) = \frac{\bar{\mu}_{{i/n}}(t)}{\bar{G}^{{i/n}}}, \qquad \forall \, i \in [n], ~n \in \N,
    \end{equation*}
    the definition of $\Wop_2$ gives for every $t \in [0, T]$
    \begin{align}
        \Wop^2_2 \big(\bar{\mu}^n_i(t), \bar{\mu}_{{i/n}}(t) \big) &= \big(\bar{G}^n_i - \bar{G}_{{i/n}} \big)^2 + \Wc^2_2 \Big( T_{\bar{G}^n_i}\# \bar{\bar{\mu}}^n_i(t), ~ T_{\bar{G}_{{i/n}}}\#\bar{\bar{\mu}}_{{i/n}}(t)\Big)   \label{ineq: two WOPs}
        \\
        &\le \big(\bar{G}^n_i - \bar{G}_{{i/n}} \big)^2 + \Wc^2_2 \Big( T_{\bar{G}^n_i}\# \bar{\bar{\mu}}^n_i, ~ T_{\bar{G}_{{i/n}}}\#\bar{\bar{\mu}}_{{i/n}}\Big)
        = \Wop^2_2 \big(\bar{\mu}^n_i, \bar{\mu}_{{i/n}} \big),       \nonumber
    \end{align}
    where the notation $T_a\# \nu$ is the pushforward of $\nu$ by $T_a(x) = ax$ for $\nu$ either in $\mathcal{M}_2(\R^d)$ or in $\mathcal{M}_2(\mathcal{C}^d)$. Here, the above inequality follows from
    \begin{align*}
        \sup_{t \in [0, T]}\Wc^2_2 \big(\mu(t), \nu(t) \big) \le \Wc^2_2(\mu, \nu)
    \end{align*}
    for any $\mu, \nu \in \mathcal{P}_2(\mathcal{C}^d)$, since we have a series of inequalities
    \begin{align*}
        \Wc_2^2 \big(\mu(t), \nu(t)\big)
        \le
        \E[|X(t) - Y(t)|^2]
        \le
        \E[\sup_{t \in [0, T]} |X(t) - Y(t)|^2] = \E \Vert X-Y \Vert^2
    \end{align*}
    for arbitrary $\Cc^d$-valued random variables $X, Y$ with $\mu = \Lc(X)$, $\nu = \Lc(Y)$ with $\mu(t) = \Lc(X(t))$, $\nu(t) = \Lc(Y(t))$ for any $t \in [0, T]$, along with the definition of 2-Wasserstein distance and the arbitrariness of $X$, $Y$, and $t$.

    Plugging \eqref{ineq: two WOPs} into \eqref{ineq: WOP before Gronwall} and using Grownwall's inequality, we have
    \begin{align*}
        ~ \frac{1}{n}\sum_{i = 1}^n
        \E\bigg[\Wop^2_2(\bar{\mu}^n_i,\bar{\mu}_{{i/n}})\bigg]
        \le  ~
        \frac{C}{n}\sum_{i = 1}^n \E \bigg[\Wop^2_2\bigg(\frac{1}{n}\sum_{j = 1}^n G^n_{i,j} \delta_{X_{j/n}},\bar{\mu}_{{j/n}}\bigg)\bigg],
    \end{align*}
    where the right-hand side tends to $0$ as $n$ goes to $\infty$ from Theorem \ref{thm: weighted mean W2 continuity}. This proves \eqref{conv: weighted mean W2 squared}.
\end{proof}

\medskip

\begin{proof} [Proof of Theorem \ref{thm: W2 to zero}]
    Using the triangle inequality, the property of Wasserstein distance between two empirical measures, and the bound \eqref{ineq: W2 bound}, we derive
    \begin{align*}
        \E \big[\Wc^2_2(\mu^n,\bar{\mu}) \big]
        \le & ~ 2 \E \big[\Wc^2_2(\mu^n, \bar{\mu}^n)\big]
        + 2 \E\big[\Wc^2_2(\bar{\mu}^n, \bar{\mu})\big]
        \\
        \le & ~ \frac{2}{n} \sum_{i = 1}^n \E\bigg[\sup_{t \in [0,T]} \big|X^n_i(t) - X_{i/n}(t) \big|^2 \bigg]
        + 2 \E\big[\Wc^2_2(\bar{\mu}^n, \bar{\mu})\big]
        \\
        \le & ~ \frac{C}{n}\sum_{i = 1}^n \E\bigg[\int_0^T \Wop^2_2 \big(\bar{\mu}^n_i(t), \bar{\mu}_{{i/n}}(t) \big) dt \bigg] + 2 \E \big[\Wc^2_2(\bar{\mu}^n, \bar{\mu})\big]
        \\
        \le & ~ C\int_0^T\frac{1}{n}\sum_{j = 1}^n\E\Big[\Wop^2_2 \big(\bar{\mu}^n_j(t), \bar{\mu}_{{j/n}}(t) \big) \Big] dt
        + 2\E[\Wc^2_2(\bar{\mu}^n, \bar{\mu})].
    \end{align*}
    Thanks to Theorems \ref{thm: bar mu_n to bar mu} and \ref{thm: weighted mean W2 squared}, the last term tends to $0$, as $n$ goes to $\infty$, which proves \eqref{conv: mean W2 squared}.
\end{proof}

