\begin{proof} [Proof of Lemma \ref{lem:sampling_rate}]
        \textbf{Part 1: Reduction to the probability measure}

        We define $m_{i,n} := \frac{1}{n}\sum_{j = 1}^nG^n_{i,j}$, then
        by (ii) of Lemma \ref{Lem: WOP R^d}, one has that for $m_{i,n} > 0$,
        \begin{align*}
            \E\Bigg[\Wop^2_2\bigg(\frac{1}{n}\sum_{j = 1}^nG^n_{i,j}\delta_{X_{{j/n}}(t)}, 
            &\frac{1}{n}\sum_{j = 1}^nG^n_{i,j} \mu_{j/n}(t) \bigg)\Bigg]
            \\
            ~ &\le ~ m^2_{i, n}
            \E\Bigg[\Wc^2_2\bigg(\frac{1}{n}\sum_{j = 1}^n\frac{G^n_{i,j}}{m_{i,n}} \delta_{X_{{j/n}}(t)}, 
            \frac{1}{n}\sum_{j = 1}^n\frac{G^n_{i,j}}{m_{i, n}} \mu_{j/n}(t) \bigg)\Bigg],
        \end{align*}
        and for $m_{i, n} = 0$,
        \begin{align*}
            \E\Bigg[\Wop^2_2\bigg(\frac{1}{n}\sum_{j = 1}^nG^n_{i,j}\delta_{X_{{j/n}}(t)}, 
            \frac{1}{n}\sum_{j = 1}^nG^n_{i,j} \mu_{j/n}(t) \bigg)\Bigg]
            ~ = ~ 0,
        \end{align*}
        which clearly satisfies the desired inequality \eqref{eq:rate_marginal}.
        Therefore, we only focus on the case $m_{i, n} > 0$ from now on, and for simplicity, we denote
        \begin{equation*}
            \delta^i_n(t) := \frac{1}{n}\sum_{j = 1}^n\frac{G^n_{i,j}}{m_{i, n}}\delta_{X_{{j/n}}(t)} \in \mathcal{P}(\R^d),
            \qquad
            \mu^i_n(t) := \frac{1}{n}\sum_{j = 1}^n\frac{G^n_{i,j}}{m_{i, n}} \mu_{j/n}(t) \in \mathcal{P}(\R^d).
        \end{equation*}

        \noindent \textbf{Part 2: Key estimates}

        By Lemmas 5 and 6 in \cite{FournierGuillin}, one has that for any $\mu,\nu \in \Pc_2(\R^d)$
        \begin{equation}\label{eq:child_estimate}
            \Wc^2_2(\mu,\nu)
            ~ \le ~
            K_d \sum_{k = 0}^\infty 2^{2k}\sum_{l = 0}^\infty 2^{-2l}\sum_{F \in \Pc_l}|\mu(2^kF \cap B_k) - \nu(2^kF \cap B_k)|,
        \end{equation}
        where the constant $K_d$ depends only on dimension $d$, the subsets $B_0 := (-1,1]^d$, $B_k :=  (-2^k,2^k]^d\backslash (-2^{k-1},2^{k-1}]^d$ for $k \in \N$ constitute a partition of $\R^d$, $\Pc_l$ denotes the natural partition of $B_0$ into $2^{dl}$ translations of $(-2^{-l},2^{-l}]^d$ for $l \in \N$, and $2^kF := \{2^k x : x \in F\}$ for $F \subset \R^d$.

        Then, to estimate $\sum_{F \in \Pc_l}|\delta^i_n(t)(2^kF \cap B_k) - \mu^i_n(t)(2^kF \cap B_k)|$ for each $n$, we claim that for each $A \in \mathcal{B}(\R^d)$
        \begin{align}\label{eq:each_child_estimate}
            \E[|\delta^i_n(t)(A) - \mu^i_n(t)(A)|]
            ~ \le ~
            \min\Bigg\{2\E[\mu^i_n(t)(A)], \sqrt{\frac{\E[\mu^i_n(t)(A)]}{nm_{i,n}}} \Bigg\}.
        \end{align}
        and that for some positive constant $C$ independent of $n$ and $i$, 
        \begin{align}\label{eq:partition_estimate}
            m_{i,n}\E[\mu^i_n(t)(B_k)]
            ~ \le ~
            C2^{-(2 + \eps)(k - 1)}.
        \end{align}        
        In fact, we have 
        \begin{align*}
            \E[|\delta^i_n(t)(A) - \mu^i_n(t)(A)|] 
            ~ \le & ~
            \frac{1}{n m_{i,n}}\sum^n_{j = 1}G^n_{i,j}
            \E\bigg[\Big|\delta_{X_{{j/n}}(t)}(A) -  \mu_{j/n}(t)(A)\Big|\bigg]
            \\ ~ \le & ~
            \frac{1}{n m_{i,n}}\sum^n_{j = 1}G^n_{i,j}
            \E\bigg[\delta_{X_{{j/n}}(t)}(A) +  \mu_{j/n}(t)(A)\bigg]
            ~ = ~ 2\E[\mu^i_n(t)(A)],
        \end{align*}
        and
        \begin{align*}
            & \Big(\E\big[|\delta^i_n(t)(A) - \mu^i_n(t)(A)|\big]\Big)^2
             ~ \le ~
            \E \big[|\delta^i_n(t)(A) - \mu^i_n(t)(A)|^2 \big]
            \\ ~ = & ~
            \frac{1}{n^2 m^2_{i,n}}\sum^n_{j,k = 1}G^n_{i,j}G^n_{i,k}
            \E\bigg[\Big(\delta_{X_{{j/n}}(t)}(A) -  \mu_{j/n}(t)(A)\Big)
                    \Big(\delta_{X_{k/n}(t)}(A) -  \mu_{j/n}(t)(A)\Big)\bigg]
            \\ ~ = & ~
            \frac{1}{n^2 m^2_{i,n}}\sum^n_{j = 1} (G^n_{i,j})^2
            \E\bigg[\Big(\delta_{X_{{j/n}}(t)}(A) -  \mu_{j/n}(t)(A)\Big)^2 \bigg]
            \\ ~ = & ~
            \frac{1}{n^2 m^2_{i,n}}\sum^n_{j = 1} (G^n_{i,j})^2
            \E\bigg[\delta_{X_{{j/n}}(t)}(A) + \Big( \mu_{j/n}(t)(A)\Big)^2 - 2\delta_{X_{{j/n}}(t)}(A) \mu_{j/n}(t)(A) \bigg]
            \\ ~ = & ~
            \frac{1}{n^2 m^2_{i,n}}\sum^n_{j = 1} (G^n_{i,j})^2
            \E\bigg[\delta_{X_{{j/n}}(t)}(A) - \Big( \mu_{j/n}(t)(A)\Big)^2
                    \bigg]
            \\ ~ \le & ~
            \frac{1}{n^2 m^2_{i,n}}\sum^n_{j = 1} G^n_{i,j} \E\bigg[\delta_{X_{{j/n}}(t)}(A)\bigg]
            ~ = ~ \frac{\E[\mu^i_n(t)(A)]}{nm_{i,n}},
        \end{align*}
        where the second and fourth equalities hold by the conditional independence of $X_{{j/n}}$ and $X_{\ell/n}$ for $j \neq \ell$, and the tower property of expectation, i.e., for $j\neq \ell$
        \begin{align*}
            &~\E\bigg[\bigg(\delta_{X_{{j/n}}(t)}(A) - \mu_{j/n}(t)(A)\bigg)
                    \bigg(\delta_{X_{\ell/n}(t)}(A) - \mu_{\ell/n}(t)(A)\bigg)\bigg]
            \\
            = &~
            \E\bigg[\Big( \delta_{X_{{j/n}}(t)} \delta_{X_{\ell/n}(t)} - \delta_{X_{{j/n}}(t)}\mu_{\ell/n}(t) 
                    - \mu_{j/n}(t) \delta_{X_{{\ell/n}}(t)} + \mu_{j/n}(t)\mu_{\ell/n}(t)\Big) (A)\bigg]
            \\
            = &~
            \E\bigg[\E\Big[\delta_{X_{{j/n}}(t)}(A)\delta_{X_{\ell/n}(t)}(A)|W\Big] - \E\Big[\delta_{X_{{j/n}}(t)}(A)|W\Big] \mu_{\ell/n}(t)(A) 
            \\ & \qquad \qquad \qquad \qquad \qquad
            - \mu_{j/n}(t)(A) \E\Big[\delta_{X_{{\ell/n}}(t)}(A)|W\Big] + \mu_{j/n}(t)(A)\mu_{\ell/n}(t)(A)\bigg]
            \\
            = & ~
            \E\bigg[ \E\Big[\delta_{X_{{j/n}}(t)}(A)|W\Big] \E\Big[\delta_{X_{\ell/n}(t)}(A)|W\Big] - \mu_{j/n}(t)(A) \mu_{\ell/n}(t)(A)
            \\ & \qquad \qquad \qquad \qquad \qquad - \mu_{j/n}(t)(A)\mu_{\ell/n}(t)(A) + \mu_{j/n}(t)(A)\mu_{\ell/n}(t)(A)\bigg]
            \\
            = & ~ 0.
        \end{align*}
        Finally, we can prove \eqref{eq:partition_estimate}, if we observe that
        \begin{align*}
            m_{i,n}\E[\mu^i_n(t)(B_k)]
            \le & ~ m_{i,n}\E\bigg[\int_{B_k}\bigg(\frac{|x|}{2^{k - 1}}\bigg)^{2 + \eps}\mu^i_n(t)(dx)\bigg]
            \\ ~ \le &~ 
            m_{i,n}\E\bigg[\int_{\R^d}\bigg(\frac{|x|}{2^{k - 1}}\bigg)^{2 + \eps}\mu^i_n(t)(dx)\bigg]
            \\ ~ = & ~
            2^{-(2 + \eps)(k - 1)}
            \frac{1}{n}\sum_{j = 1}^nG^n_{i,j}\E[|X_{{j/n}}(t)|^{2 + \eps}]
            \\ ~ \le & ~
            2^{-(2 + \eps)(k - 1)}\sup_{u \in [0,1]}\E\bigg[\sup_{t \in [0,T]}|X_{u}(t)|^{2 + \eps}\bigg]
            ~ \le ~ C2^{-(2 + \eps)(k - 1)},
        \end{align*}
        since $|x| \ge 2^{k-1}$ in $B_k$, and the last inequality holds by Lemma \ref{lem: unique pathwise solution}.

        \noindent \textbf{Part 3: Application of the key estimates}

        With the estimates \eqref{eq:each_child_estimate} and \eqref{eq:partition_estimate}, we observe that for $F_1, F_2 \in \Pc_l$, with $F_1 \neq F_2$, $F_1 \cap F_2 = \emptyset$:
        \begin{align*}
            &
            \sum_{F \in \Pc_l}\E[|\delta^i_n(t)(2^kF \cap B_k) - \mu^i_n(t)(2^kF \cap B_k)|]
            \\ ~ \le & ~
            \sum_{F \in \Pc_l}\min\Bigg\{2\E[\mu^i_n(t)(2^kF \cap B_k)], \sqrt{\frac{\E[\mu^i_n(t)(2^kF \cap B_k)]}{n m_{i,n}}} \Bigg\}
            \\ ~ \le& ~
            \min\Bigg\{2\sum_{F \in \Pc_l}\E[\mu^i_n(t)(2^kF \cap B_k)], \sum_{F \in \Pc_l}\sqrt{\frac{\E[\mu^i_n(t)(2^kF \cap B_k)]}{n m_{i,n}}} \Bigg\}
            \\ ~ \le& ~
            \min\Bigg\{2\E[\mu^i_n(t)(B_k)], 2^{\frac{dl}{2}}\sqrt{\frac{\E[\mu^i_n(t)(B_k)]}{n m_{i,n}}} \Bigg\}
            \\ ~ \le & ~
            \frac{C}{m_{i,n}}\min\Bigg\{2^{-(2 + \eps)(k - 1) +1}, 2^{\frac{dl}{2}}\sqrt{\frac{2^{-(2 + \eps)(k - 1)}}{n}} \Bigg\}
            \\ ~ \le & ~
            \frac{C2^{3+\eps}}{m_{i,n}}\min\Bigg\{2^{-(2 + \eps)k}, 2^{\frac{dl}{2}}\sqrt{\frac{2^{-(2 + \eps)k}}{n}} \Bigg\}
        \end{align*}
        where the third inequality uses Cauchy-Schwarz inequality and the fact that $\#(\Pc_l) = 2^{dl}$.
        From all the estimates above, we have for some constant $C_d > 0$,
        \begin{align*}
            &
            \E\Bigg[\Wop^2_2\bigg(\frac{1}{n}\sum_{j = 1}^nG^n_{i,j}\delta_{X_{{j/n}}(t)}, 
            \frac{1}{n}\sum_{j = 1}^nG^n_{i,j} \mu_{j/n}(t) \bigg)\Bigg]
            \\~ \le &~ m_{i,n}^2
            \E\Bigg[\Wc^2_2\bigg(\frac{1}{n}\sum_{j = 1}^n\frac{G^n_{i,j}}{m_{i,n}}\delta_{X_{{j/n}}(t)}, 
            \frac{1}{n}\sum_{j = 1}^n\frac{G^n_{i,j}}{m_{i,n}} \mu_{j/n}(t) \bigg)\Bigg]
            \\ ~ \le & ~
            m_{i,n}^2K_d \sum_{k = 0}^\infty 2^{2k}\sum_{l = 0}^\infty 2^{-2l}\frac{C2^{3+\eps}}{m_{i,n}}\min\Bigg\{2^{-(2 + \eps)k}, 2^{\frac{dl}{2}}\sqrt{\frac{2^{-(2 + \eps)k}}{n}} \Bigg\}
            \\ ~ \le & ~
            C_d2^{3+\eps} \sum_{k = 0}^\infty 2^{2k}\sum_{l = 0}^\infty 2^{-2l}\min\Bigg\{2^{-(2 + \eps)k}, 2^{\frac{dl}{2}}\sqrt{\frac{2^{-(2 + \eps)k}}{n}} \Bigg\},
        \end{align*}
        where the last inequality holds by $m_n \le 1$. The rest of the estimate follows exactly by the same argument as in the proof of Theorem 1 in \cite{FournierGuillin} with $q = 2 + \eps$, thus we conclude the proof.
    \end{proof}

    \medskip

    \begin{proof} [Proof of Theorem \ref{thm: convergence rates}]
        From \eqref{ineq: W2 bound} in the proof of Theorem \ref{thm: weighted mean W2 squared}, we have that for some constant $K > 0$, which may vary from line to line throughout the proof
        \begin{align*}
            \E\bigg[\sup_{t \in [0,T]} \big|X^n_i(t) - X_{i/n}(t) \big|^2 \bigg] 
            ~ \le &~ 
            K \E \bigg[\int_0^T \Wop^2_2 \bigg(\frac{1}{n} \sum_{j = 1}^n G^n_{i,j}\delta_{X^n_j(t)}, 
            \int_{0}^1 G_{i/n,v}\mu_v(t)dv\bigg) \, dt \bigg]
            \\ ~ \le & ~
            K\E \bigg[\int_0^T \Wop^2_2 \bigg(\frac{1}{n} \sum_{j = 1}^n G^n_{i,j}\delta_{X^n_j(t)}, 
            \frac{1}{n} \sum_{j = 1}^n G^n_{i,j}\mu_{j/n}(t)\bigg) \, dt \bigg]
                \\ &+
                K\E \bigg[\int_0^T \Wop^2_2 
                \bigg(\frac{1}{n} \sum_{j = 1}^n G^n_{i,j}\mu_{j/n}(t), 
                \int_{0}^1 G_{i/n,v}\mu_v(t)dv\bigg) \, dt \bigg].
        \end{align*}
        For the first term on the right-hand side, by Lemma \ref{lem:sampling_rate}, there exists some positive constant $K_{d,\eps} > 0$, which may vary from line to line,
        \begin{align*}
            &\E \bigg[\Wop^2_2 \bigg(\frac{1}{n} \sum_{j = 1}^n G^n_{i,j}\delta_{X^n_j(t)}, 
            \frac{1}{n} \sum_{j = 1}^n G^n_{i,j}\mu_{j/n}(t)\bigg)\bigg]
            \\~ \le &~
            2\E \bigg[\Wop^2_2 \bigg(\frac{1}{n} \sum_{j = 1}^n G^n_{i,j}\delta_{X^n_j(t)}, 
            \frac{1}{n} \sum_{j = 1}^n G^n_{i,j}\delta_{X_{j/n}(t)}\bigg) \bigg]
                \\ & \qquad   + 
                2\E \bigg[\Wop^2_2 \bigg(\frac{1}{n} \sum_{j = 1}^n G^n_{i,j}\delta_{X_{j/n}(t)}, 
                \frac{1}{n} \sum_{j = 1}^n G^n_{i,j}\mu_{j/n}(t)\bigg)\bigg]
            \\ ~ \le & ~
            \frac{2}{n}\sum_{j = 1}^n G^n_{i,j}\E\bigg[\big|X^n_j(t) - X_{j/n}(t) \big|^2 \bigg] 
            +
            K_{d,\eps}M_n
            \\ ~ \le & ~
            2\sup_{i \in [n]}\E\bigg[\sup_{s \in [0,t]}|X^n_i(s) - X_{{i/n}}(s)|^2\bigg]
            + 
            K_{d,\eps}M_n.
        \end{align*}
        By Gronwall's inequality, it follows that
        \begin{align*}
            \sup_{i \in [n]}\E\bigg[\sup_{t \in [0,T]}|X^n_i(t) - X_{{i/n}}(t)|^2\bigg]
            \le &~
            K\E \bigg[\int_0^T \Wop^2_2 
                \bigg(\frac{1}{n} \sum_{j = 1}^n G^n_{i,j}\mu_{j/n}(t), 
                \int_{0}^1 G_{i/n,v}\mu_v(t)dv\bigg) \, dt \bigg]
            \\ &+ K_{d,\eps}M_n.
        \end{align*}
        Then, it remains to compute the first term on the right-hand side of the above inequality. 
        Let us define 
        \begin{align*}
            \Gt^n_{u,v} := \sum_{i,j = 1}^nG^n_{i,j}\mathds{1}_{(\frac{i - 1}{n},\frac{i}{n}] \x (\frac{j - 1}{n},\frac{j}{n}]}(u,v), \qquad
            ~\mbox{for}~(u,v) \in [0,1]^2
            \\
            \mut^n_{v}(t) := \sum_{j = 1}^n\mu_{j/n}(t)\mathds{1}_{(\frac{j - 1}{n},\frac{j}{n}]}(v), \qquad
            ~\mbox{for}~v \in [0,1], \quad t \in [0,T],
        \end{align*}
        then, by the triangle inequality, 
        \begin{align*}
            \E \bigg[\int_0^T \Wop^2_2 
                \bigg(\frac{1}{n} \sum_{j = 1}^n G^n_{i,j}\mu_{j/n}(t), 
                \int_{0}^1 G_{i/n,v}\mu_v(t)dv\bigg) \, dt \bigg]
                ~ \le ~
                2\Dc^n_i + 2\Gc^n_i,
        \end{align*}
        where for $n \in \N$, $i \in [n]$, $t \in [0,T]$, $\Dc^n_i$ and $\Gc^n_i$ are given by
        \begin{align*}
            \Dc^n_i
             := &~
                \E \bigg[\int_0^T\Wop^2_2 
                \bigg(\frac{1}{n} \sum_{j = 1}^n G^n_{i,j}\mu_{j/n}(t), 
                \int_{0}^1 \Gt^n_{i/n,v}\mu_v(t)dv\bigg)\, dt \bigg],
           \\            
           \Gc^n_i
             := &~
                \E \bigg[\int_0^T          \Wop^2_2 
                \bigg(\int_{0}^1 \Gt^n_{i/n,v}\mu_v(t)dv, 
                \int_{0}^1 G_{i/n,v}\mu_v(t)dv\bigg)\, dt \bigg].
        \end{align*}
        As for $\Dc^n_i$, we observe that
        if $m_{i,n} := \frac{1}{n}\sum_{i = 1}^nG^n_{i,j} = 0$, then $\Dc^n_i = 0$. When $m_{i,n} > 0$, it follow that
        \begin{align*}
            \Dc^n_i
            ~ = &~
            \E\bigg[\int_0^T\Wop^2_2 
                \bigg( \int_{0}^1 \Gt^n_{i/n,v}\mut^n_v(t)dv, 
                \int_{0}^1 \Gt^n_{i/n,v}\mu_v(t)dv\bigg)\, dt\bigg]
            \\~ \le & ~
            m^2_{i,n}
            \E\bigg[\int_0^T\Wc^2_2 
                \bigg( \int_{0}^1 \frac{\Gt^n_{i/n,v}}{m_{i,n}}\mut^n_v(t)dv, 
                \int_{0}^1 \frac{\Gt^n_{i/n,v}}{m_{i,n}}\mu_v(t)dv\bigg)\, dt\bigg]
            \\ ~ \le & ~
            m^2_{i,n}
            \int_0^T\int_{0}^1 \frac{\Gt^n_{i/n,v}}{m_{i,n}}
                \E\big[\Wc_2^2\big(\mut^n_v(t), 
                \mu_v(t)\big)\big]dv\, dt
            \\ ~ \le & ~
            \int_0^T\int_{0}^1 
               \E\big[\Wc_2^2\big(\mut^n_v(t), 
                \mu_v(t)\big)\big]dv\, dt
            ~ \le ~ \frac{K}{n},
        \end{align*}
        where the first inequality holds by $(ii)$ of Lemma \ref{Lem: WOP R^d}, the second one by the continuity estimate from Kantorovitch duality of Wasserstein distance as in the proof of Lemma 3.1 in \cite{nonlinear:graphon},
        and the last one by \eqref{ineq: W^2_2} with $\eps = 0$ for some positive constant $K$.

        As for the term $\Gc^n_i$, when $m_{i,n} = 0$ or $m_{i/n} := \int_0^1 G_{i/n,v}dv = 0$, there exists some positive constant $K$, which may vary from line to line, such that
        \begin{align*}
            \Gc^n_i = ~&\E \bigg[\int_0^T 
            (m_{i,n} - m_{i/n})^2 + 
            (m_{i,n} - m_{i/n})    
            \int_{0}^1  \big(\Gt^n_{i/n,v} - G_{i/n,v}\big)\int_{\R^d}|x|^2\mu_v(t)(dx)dv
            \, dt \bigg]
            \\ \le ~& 
            T\int_0^1 \big(\Gt^n_{i/n,v} - G_{i/n,v}\big)^2 dv
                + T(m_{i,n} - m_{i/n})\int_0^1 \big(\Gt^n_{i/n,v} - G_{i/n,v}\big)\E\bigg[\sup_{t \in [0,T]}|X_v(t)|^2\bigg] dv
            \\ \le ~ &
            K\int_0^1 \big(\Gt^n_{i/n,v} - G_{i/n,v}\big)^2 dv
            ~ \le ~ \frac{K}{n^2}.
        \end{align*}
        Then, for the case $m_{i,n}, m_{i/n} > 0$, by Theorem 6.15 in \cite{villani2016optimal}, there exists some positive constant $K$, which may vary from line to line, satisfying
        \begin{align*}
            \Gc^n_i \le ~&  \frac{K}{n^2} + \E \bigg[\int_0^T 
            2m_{i,n}m_{i/n}\int_{\R^d}|x|^2\bigg|\int_{0}^1 \frac{\Gt^n_{i/n,v}}{m_{i,n}}\mu_v(t)dv - 
                \int_{0}^1 \frac{G_{i/n,v}}{m_{i/n}}\mu_v(t)dv\bigg|(dx)
            \, dt \bigg]
            \\ \le ~ &
            \frac{K}{n^2} + 
            \E \bigg[\int_0^T 
            2m_{i,n}m_{i/n}\int_{0}^{1}\bigg|\frac{\Gt^n_{i/n,v}}{m_{i,n}}- \frac{G_{i/n,v}}{m_{i/n}} \bigg|\int_{\R^d}|x|^2\mu_v(t)(dx)\,dv\, dt\bigg]
            \\ \le ~ &
            \frac{K}{n^2} + 
            K\E \bigg[\int_0^T 
            \int_{0}^{1}\Big|m_{i/n}\Gt^n_{i/n,v}- m_{i/n}G_{i/n,v} + m_{i/n}G_{i/n,v} -
                m_{i,n}G_{i/n,v}\Big|\,dv\,dt\bigg]
            \\ \le ~ &
            \frac{K}{n^2} + K\int_0^T 
            \int_{0}^{1}\big|\Gt^n_{i/n,v}- G_{i/n,v}\big| + \big|m_{i/n} - m_{i,n}\big|\,dv\,dt
            \\ \le ~ &
            \frac{K}{n^2} +  \frac{K}{n}.
        \end{align*}
        Finally, we can conclude that there exists some positive constant $K_{d,\eps}$ satisfying
        \begin{align*}
            \sup_{i \in [n]}\E\bigg[\sup_{t \in [0,T]}|X^n_i(t) - X_{{i/n}}(t)|^2\bigg]
            \le 
            \frac{K}{n^2} + \frac{K}{n}+ K_{d,\eps}M_n
            ~ \le ~
            K_{d,\eps}M_n.
        \end{align*}
    \end{proof}

