\section{Characterization of $\Pc(\Mc_{2,K}(\Cc^d) \x \Mc_{2,K}(\Cc^d))$}

The following two characterization results are inspired by Proposition A.3 in \cite{DTP}. The aim is to find a more feasible way to identify that two probability measures on $\Mc_{2,K}(\Cc^d) \x \Mc_{2,K}(\Cc^d)$ are the same.
\begin{thm}\label{thm: characterization}
    Suppose that $\Gamma_1, \Gamma_2 \in \Pc(\Mc_{2,K}(\Cc^d) \x \Mc_{2,K}(\Cc^d))$ satisfy 
    \begin{align}\label{eq:characterization}
        \int_{\Mc^2_{2,K}(\Cc^d)} \prod_{i = 1}^k\prod_{j = 1}^l \langle\varphi_i,\mu\rangle \langle\phi_j,\nu\rangle \Gamma_1(d\mu,d\nu)
        = 
        \int_{\Mc^2_{2,K}(\Cc^d)} \prod_{i = 1}^k\prod_{j = 1}^l \langle\varphi_i,\mu\rangle \langle\phi_j,\nu\rangle \Gamma_2(d\mu,d\nu)
    \end{align}
    for all $k, l \ge 1$, and $\varphi_i, \phi_j \in C_b(\Cc^d)$ for $i \in [k], j \in [l]$. Then, $\Gamma_1 = \Gamma_2$.
\end{thm}

\begin{proof}
    First, by linearity of integral and arbitrariness of $k$, we can generalize \eqref{eq:characterization} as follows:
    for any polynomials $\Psi_i, \Phi_j$ on $\R$ and $i \in [k]$, $j \in [l]$
    \begin{equation}\label{eq:polynomial_characterization}   
        \int_{\Mc^2_K(\Cc^d)}
            \prod_{i = 1}^k\prod_{j = 1}^l
                \Psi_i(\langle\varphi_i,\mu\rangle)\Phi_j( \langle\phi_j,\nu\rangle)
        \Gamma_1(d\mu,d\nu)
        = 
        \int_{\Mc^2_K(\Cc^d)}
            \prod_{i = 1}^k\prod_{j = 1}^l
                \Psi_i(\langle\varphi_i,\mu\rangle)\Phi_j( \langle\phi_j,\nu\rangle)
        \Gamma_2(d\mu,d\nu).
    \end{equation}
    Since every bounded continuous function on $\R$ can be approximated by polynomials, we can further prove \eqref{eq:polynomial_characterization} for any bounded continuous functions $\Psi_i, \Phi_j$ on $\R$. 
    Again, notice that for any $r \in \R$, the function $\mathds{1}_{(-\infty,r)}$ can be approximated by a sequence of bounded continuous functions, we have for any $r_i, s_j \in \R$, $i \in [k]$, $j \in [l]$,
    \begin{align*}
        \int_{\Mc^2_K(\Cc^d)}
            \prod_{i = 1}^k\prod_{j = 1}^l
                \mathds{1}_{(-\infty,r_i)}(\langle\varphi_i,\mu\rangle)
                \mathds{1}_{(-\infty,s_j)}( \langle\phi_j,\nu\rangle)
        \Gamma_1(d\mu,d\nu)
        \\= 
        \int_{\Mc^2_K(\Cc^d)}
            \prod_{i = 1}^k\prod_{j = 1}^l
                \mathds{1}_{(-\infty,r_i)}(\langle\varphi_i,\mu\rangle)
                \mathds{1}_{(-\infty,s_j)}( \langle\phi_j,\nu\rangle)
        \Gamma_2(d\mu,d\nu).
    \end{align*}
    Consequently, we can say that
    $\Gamma_1 = \Gamma_2$ on $B$, where
    \begin{align*}
        B := \Big\{\{(\mu,\nu) \in \Mc^2_K(\Cc^d): \langle\varphi_i,\mu\rangle < r_i, &
            \langle\phi_j,\nu\rangle < s_j, i \in [k], j \in [l]\}
            \\&: k,l \ge 1,r_i,s_j \in \R, \varphi_i, \phi_j \in C_b(\Cc^d),  i \in [k], j \in [l]\Big\}.
    \end{align*}
    Since the weak convergence topology on $\Mc_{2,K}(\Cc^d)$ can be characterized by bounded continuous functions, the Borel $\sigma$-field on  $\Mc_{2,K}(\Cc^d)$ can be generated by all open sets in $\Mc_{2,K}(\Cc^d)$, and the product of Borel $\sigma$-fields on $\Mc_{2,K}(\Cc^d)$ is equal to Borel $\sigma$-field on the product space $\Mc^2_{2,K}(\Cc^d)$, it follows that $\Bc(\Mc^2_{2,K}(\Cc^d)) = \sigma(B)$. Then, we can conclude the proof by a monotone class argument.
\end{proof}

Similarly, we have the following result.
\begin{thm}\label{thm: characterization2}
    Suppose that $\Gamma_1, \Gamma_2 \in \Pc(\Pc(\Cc^d) \x \Pc(\Cc^d))$ satisfy
    \begin{align}
        \int_{\Pc^2(\Cc^d)} \prod_{i = 1}^k\prod_{j = 1}^l \langle\varphi_i,\mu\rangle \langle\phi_j,\nu\rangle \Gamma_1(d\mu,d\nu)
        = 
        \int_{\Pc^2(\Cc^d)} \prod_{i = 1}^k\prod_{j = 1}^l \langle\varphi_i,\mu\rangle \langle\phi_j,\nu\rangle \Gamma_2(d\mu,d\nu)
    \end{align}
    for all $\varphi_i, \phi_j \in C_b(\Cc^d)$, $i \in [k]$, $j \in [l]$, $k, l \ge 1$. 
    Then, $\Gamma_1 = \Gamma_2$.
\end{thm}

