\section{Linear graphon system}   \label{sec: linear case}
    In the graphon particle system \eqref{eq : graphon particle system with common noise} and the finite $n$-particle system \eqref{eq : finite particle system with common noise}, suppose that the functions $\phi_{\alpha}$ take the specific form
    \begin{equation*}
        \phi_{\alpha}(x, \mu) := \int_{\R^d} \hat{\phi}_{\alpha}(x, y) d\mu(y)
    \end{equation*}
    for some bounded Lipschitz function $\hat{\phi}_{\alpha}$, defined on $\R^d \times \R^d$, for $\alpha = p, b, w$:
    \begin{align*}
        |\hat{\phi}_{\alpha}(x_1, y_1) | \le L, \quad |\hat{\phi}_{\alpha}(x_1, y_1) - \hat{\phi}_{\alpha}(x_2, y_2)| \le L\big( |x_1-x_2|+|y_1-y_2| \big), \quad \forall \, x_1, x_2, y_1, y_2 \in \R^d.
    \end{align*}
    In this case, interactions between the agents are linear in their empirical measures, and the two systems take similar linear forms as in \cite{BCW, Bayraktar_Kim_2024, BW2, BW, BWZ}.

    To show that all the results in this paper apply to the linear graphon systems, we claim that this specific form of $\phi_{\alpha}$ satisfies Assumption \ref{ass:Lipschitz} by establishing for any $x, y \in \R^d$, $\mu, \nu \in \mathcal{M}_{2,K}(\R^d)$, and $\alpha = p, b, w$
    \begin{equation}    \label{angle Lipschitz}
        \big| \phi_{\alpha}(x, \mu) - \phi_{\alpha}(y, \mu) \big| \le L m_{\mu}|x-y|, \quad 
        \big| \phi_{\alpha}(x, \mu) - \phi_{\alpha}(x, \nu) \big|^2 \le L^2 \Wop^2_2(\mu, \nu).
    \end{equation}
    The first inequality of \eqref{angle Lipschitz} is straightforward:
    \begin{align*}
        \big| \phi_{\alpha}(x, \mu) - \phi_{\alpha}(y, \mu) \big|
            \le \int_{\R^d} \Big| \hat{\phi}_{\alpha}(x, z) - \hat{\phi}_{\alpha}(y, z) \Big| d\mu(z)
            \le \int_{\R^d} L |x-y| d\mu(z) = L m_{\mu} |x-y|.
    \end{align*}

    For the second inequality, consider the two probability measures $\bar{\mu}$, $\bar{\nu}$, recalling the notation from Section \ref{subsec: Wop}:
    \begin{equation*}
        \bar{\mu} := 
            \begin{cases}
                \frac{\mu}{m_{\mu}}, \qquad &\text{if } m_{\mu} > 0,
                \\
                \, \delta_0, \qquad &\text{otherwise}.
            \end{cases}
    \end{equation*}
    Let us first assume $m_{\mu} m_{\nu} \neq 0$. Consider an arbitrary probability measure $\bar{\gamma}$ on $\R^d \times \R^d$ with marginals $T_{m_{\mu}\#}\bar{\mu}$ and $T_{m_{\nu}\#}\bar{\nu}$, and use the properties of $\hat{\phi}_{\alpha}$ to derive
    \begin{align}
            &\big| \phi_{\alpha}(x, \mu) - \phi_{\alpha}(x, \nu) \big|^2
            = \bigg| \int_{\R^d} m_{\mu} \hat{\phi}_{\alpha}(x, y) d\bar{\mu}(y) - \int_{\R^d} m_{\nu} \hat{\phi}_{\alpha}(x, z) d\bar{\nu}(z) \bigg|^2             \nonumber
            \\
            & \qquad \le 2\bigg| \int_{\R^d} m_{\mu} \hat{\phi}_{\alpha}(x, y) d\bar{\mu}(y) - \int_{\R^d} m_{\mu} \hat{\phi}_{\alpha}(x, z) d\bar{\nu}(z) \bigg|^2             \label{zero mass}
            \\
            & \qquad \qquad \qquad \qquad \qquad \qquad + 2\bigg| \int_{\R^d} m_{\mu} \hat{\phi}_{\alpha}(x, z) d\bar{\nu}(z) - \int_{\R^d} m_{\nu} \hat{\phi}_{\alpha}(x, z) d\bar{\nu}(z) \bigg|^2             \nonumber
            \\
            & \qquad \le 2\bigg| \int_{\R^d} m_{\mu} \hat{\phi}_{\alpha}(x, \frac{y}{m_{\mu}}) dT_{m_{\mu}\#}\bar{\mu}(y) - \int_{\R^d} m_{\mu} \hat{\phi}_{\alpha}(x, \frac{z}{m_{\nu}}) dT_{m_{\nu}\#}\bar{\nu}(z) \bigg|^2 + 2L^2 (m_{\mu}-m_{\nu})^2             \nonumber
            \\
            & \qquad \le 2 L^2 m_{\mu}^2 \iint_{\R^d \times \R^d} \Big| \frac{y}{m_{\mu}} - \frac{z}{m_{\nu}} \Big|^2 d\bar{\gamma}(y, z) + 2L^2 (m_{\mu}-m_{\nu})^2             \nonumber
            \\
            & \qquad \le 4 L^2 m_{\mu}^2 \iint_{\R^d \times \R^d} \Big| \frac{y}{m_{\mu}} - \frac{z}{m_{\mu}} \Big|^2 d\bar{\gamma}(y, z)               \nonumber
            \\
            & \qquad \qquad \qquad \qquad \qquad \qquad + 4 L^2 m_{\mu}^2 \iint_{\R^d \times \R^d} \Big| \frac{z}{m_{\mu}} - \frac{z}{m_{\nu}} \Big|^2 d\bar{\gamma}(y, z) + 2L^2 (m_{\mu}-m_{\nu})^2             \nonumber
            \\
            & \qquad \le 4L^2 \iint_{\R^d \times \R^d} |y-z|^2 d\bar{\gamma}(y, z) + 4L^2 m_{\mu}^2 \Big(\frac{1}{m_{\mu}}-\frac{1}{m_{\nu}}\Big)^2 M_{0}(T_{m_{\nu}\#}\bar{\nu}) + 2L^2 (m_{\mu}-m_{\nu})^2.             \nonumber
    \end{align}
    By taking the minimum over such probability measures $\bar{\gamma}$ with marginals $T_{m_{\mu}\#}\bar{\mu}$ and $T_{m_{\nu}\#}\bar{\nu}$, we obtain
    \begin{align*}
            \big| \phi_{\alpha}(x, \mu) - \phi_{\alpha}(x, \nu) \big|^2
            &\le 4 L^2 \Wc_2^2(T_{m_{\mu}\#}\bar{\mu}, T_{m_{\nu}\#}\bar{\nu})
            \\
            & \qquad \qquad \qquad+ 4L^2 \frac{(m_{\nu}-m_{\mu})^2}{m_{\nu}^2} M_{0}(T_{m_{\nu}\#}\bar{\nu}) + 2L^2 (m_{\mu}-m_{\nu})^2
            \\
            &\le 4 L^2 \Wc_2^2(T_{m_{\mu}\#}\bar{\mu}, T_{m_{\nu}\#}\bar{\nu}) + (m_{\nu}-m_{\mu})^2 \Big( \frac{4L^2}{m_{\nu}^2} M_{0}(T_{m_{\nu}\#}\bar{\nu}) + 2L^2 \Big)
            \\
            &\le \max\Big\{4L^2, ~\frac{4L^2}{m_{\nu}^2} M_{0}(T_{m_{\nu}\#}\bar{\nu}) + 2L^2 \Big\} \Wop_2^2 (\mu, \nu)
            \\
            & = \max\Big\{4L^2, ~4L^2 M_{0}(\bar{\nu}) + 2L^2 \Big\} \Wop_2^2 (\mu, \nu)
            \\
            & \le \max\Big\{4L^2, ~4L^2 K + 2L^2 \Big\} \Wop_2^2 (\mu, \nu).
    \end{align*}
    Here, the third inequality uses the definition \eqref{def: WOP}, and this proves the second Lipschitz property of \eqref{angle Lipschitz}.

    When one of $\{m_{\mu}, m_{\nu}\}$ is zero, say $m_{\mu} = 0$, the first term of \eqref{zero mass} is zero, so we have $| \phi_{\alpha}(x, \mu) - \phi_{\alpha}(x, \nu)|^2 \le 2L^2(m_{\mu}-m_{\nu})^2$  and the result \eqref{angle Lipschitz} holds.

