    Now, let us restrict to the case where $\alpha_i=1$ and $\theta_i=-1$ for all $1 \leq i \leq n$, and $Q_1$ contains at least one arrow from $x$ to each of $1,\ldots,n$. Assume also that $n \geq 3$ and $m:=\theta_x \in \{1,\ldots, n-1\}$. In this case $\Phi=\{\beta_I: I \subseteq \{1,\ldots,n\} \mid |I|=m\}$, with $\beta_I := e_x + \sum_{i \in I} e_i$. As a result $|\Phi| = {n \choose m}$ and there are precisely $2^{{n \choose m}}$ locally projective crepant resolutions of $\cM_\theta(Q,\alpha)$. We obtain:
    \begin{cor} \label{c:general_nonprojective} 
    Under the preceding assumptions, if $s: \Phi \to \{+,-\}$ has the property that, for some $k \geq 2$ and some subsets $I_1,\ldots, I_k$ and $J_1,\ldots,J_k$ of $\{1,\ldots,n\}$ of size $m$ such that
    \[\sum_{i=1}^k \beta_{I_i} = \sum_{i=1}^k \beta_{J_i}, \]
    i.e., the unions with multiplicity of the $I_i$ and $J_i$ are the same, we have
    \[
    s(\beta_{I_i}) = +, \quad s(\beta_{J_i})= -, \quad \forall i=1,\ldots, k,
    \]
    then the (proper) crepant resolution $U_s/\!/G_\alpha \to \cM_0(Q,\alpha)$ is nonprojective.
    \end{cor}

We next randomly generate a function $s: \Phi \to \{ +, - \}$, and consider the associated resolution of the form $U_s/\!/G_\alpha \to \cM_0(Q,\alpha)$. 

    \begin{cor} \label{cor:probability}
       Continuing with the assumptions of the preceding corollary, a randomly generated resolution of the form $U_s/\!/G_\alpha \to \cM_0(Q,\alpha)$ is nonprojective with probability approaching $1$ as $n$ and $n-m$ tend to infinity.
    \end{cor} 

    \begin{proof}
        %By symmetry, we can assume $n\geq m$. 
        We will analyze the condition of Corollary \ref{c:general_nonprojective} for $k=2$ and partitions $I_1 \sqcup I_2 = \{ 1, \ldots, 2m \} \subset \{1, \ldots, n \}$ with $|I_1| = m = |I_2|$. There are $M :={2m \choose m}/2$ such partitions. Fixing such a partition $I_1, I_2$, the probability that $s$ does not satisfy $s(\beta_{I_1})=+=s(\beta_{I_2})$ is $3/4$. So the probability that $s$ does not satisfy the condition on all partitions is $(3/4)^M$. Similarly, the probability that $s$ does not satisfy $s(\beta_{J_1})=-=s(\beta_{J_2})$ for some choice of partition $J_1, J_2$ is $(3/4)^M$. Therefore, with probability approaching $1$, the hypotheses of the theorem will be satisfied.
    \end{proof}    
