\subsection{Proper crepant resolutions for general quivers}  

Next, let $Q_0=\{x,1,\ldots,n,y\}$  and $Q_1$ be any set of arrows that includes at least one arrow $x \to i$ and $y \to i$ for each $i \in \{1,\ldots,n\}$, and consider dimension vector $\alpha=(1,\ldots,1)$.  (Alternatively, one can consider a framed quiver on $Q_0=\{x,1,\ldots,n\}$, where  $Q_1$ contains a star with arrows from central vertex $x$ to the other vertices. The dimension vector is $(1,\ldots,1)$, and there is a 1-dimensional framing at vertices $\{1,\ldots,n\}$.)

The construction is based on an involution on the collection of upward-closed subsets of $\{1,\ldots,n\}$, which may be of independent interest:
\begin{defn}
A subset $\mathcal{I} \subseteq \mathcal{P}(\{1,\ldots,n\})$ is \emph{upward-closed} if for every $J \subseteq \{1,\ldots,n\}$ such that $J \supseteq I$ for some $I \in \mathcal{I}$, then $J \in \mathcal{I}$ as well.
\end{defn}
To represent $\mathcal{I}$, it is convenient to use a minimal subset $\mathcal{I}_0 \subseteq \mathcal{I}$ such that every element contains one of the sets in $\mathcal{I}_0$.  For example, if $\mathcal{I}$ is the set of all subsets containing $1$, then we can take $\mathcal{I}_0 = \{\{1\}\}$.  Note that $\mathcal{I}_0$ is an \emph{antichain}, i.e., a collection of sets, none of which contains another.  In fact, $\mathcal{I}_0$ is unique: it consists precisely of the sets in $\mathcal{I}$ which do not contain another set. This produces a well-known bijection $\mathcal{I} \leftrightarrow \mathcal{I}_0$ between upward-closed collections and antichains.

Now let $\mathcal{I} \subseteq \mathcal{P}(\{1,\ldots,n\})$ be an upward-closed subset.
We now define, from $\mathcal{I}$, another set $\mathcal{J} \subseteq \mathcal{P}(\{1,\ldots,n\})$, as follows:
\begin{equation}
\mathcal{J} := \{J \subseteq \{1,\ldots,n\} \mid I \cap J \neq \emptyset,  \text{ for all } I \in \mathcal{I} \}.
\end{equation}
Notice  that $\mathcal{J}$ is upward-closed. We have another characterization of $\mathcal{J}$:
\begin{lem} We have the formula
\[
\mathcal{J} = \{I^c: I \subseteq \{1,\ldots,n\}, I \notin \mathcal{I}\}.
\]
\end{lem}
\begin{proof}
If $I \notin \mathcal{I}$, then for every $I' \in \mathcal{I}$, we have $I' \not \subseteq I$, so that $I^c \cap I' \neq \emptyset$. Conversely, if $J \cap I \neq \emptyset$ for all $I \in \mathcal{I}$, then $J^c \not \supseteq I$ for all $I \in \mathcal{I}$, or equivalently $J^c \notin \mathcal{I}$.
\end{proof}
\begin{cor}
This operation is an involution, i.e., define
\begin{equation}\label{e:ij-invol}
 \mathcal{K} := \{I \subseteq \{1,\ldots,n\} \mid \forall J \in \mathcal{J}, I \cap J \neq \emptyset\}.
\end{equation}
Then $\mathcal{K} = \mathcal{I}$.
\end{cor}
\begin{proof}
It is clear that every $I \in \mathcal{I}$ is also in $\mathcal{K}$. For the converse, suppose that $I \notin \mathcal{I}$. Then by the preceding lemma, $I^c \in \mathcal{J}$. But then $I \cap I^c = \emptyset$, so that $I \notin \mathcal{K}$.
\end{proof}

This involution fixes upward-closed subsets with a unique minimal subset. 

\begin{defn} \label{d:good_subset}
    Let $\mathcal{I} \subset \mathcal{P}( \{ 1, \dots, n \} )$ be an upward closed subset with $\mathcal{J}$ defined as above. Define $U \subseteq \mu^{-1}(0)$ to be the open subset of representations such that:
\begin{itemize}
\item[(1)] For some $I \in \mathcal{I}$, there are nonzero paths from $x$ to every vertex of $I$;
\item[(2)] For some $J \in \mathcal{J}$, there are nonzero paths from $y$ to every vertex of $J$;
\item[(3)] For every $i \in \{1,\ldots,n\}$, there is a nonzero path from either $x$ or $y$ to $i$.
\end{itemize}
\end{defn}


\begin{thm}\label{t:stars-git}
Assume that $\mathcal{I}, \mathcal{J}$ are not empty. Let $U \subseteq \mu^{-1}(0)$ be the set defined above. There is a geometric quotient $U/\!/G_{\alpha}$ such that the canonical morphism $U/\!/G_{\alpha} \to \mu^{-1}(0)/\!/G_{\alpha}$ is a (proper) crepant resolution of singularities.
\end{thm}

\begin{exam}
Taking $n=5$ and $\mathcal{I}_0=\{\{1,2\},\{3, 4,5\}\}$, then $\mathcal{J}_0$ consists of all subsets containing exactly one element of each of $\{1,2\}$ and $\{3, 4,5\}$, i.e.,   
\[\mathcal{J}_0=\{\{1,3\},\{1,4 \},\{1,5\},\{2,3\},\{2,4\},\{2,5\}\}.\]
Then, Theorem \ref{t:stars-git} specializes to Theorem \ref{t:five-point-git}(a).
\end{exam}
\begin{exam}
%Working on $Q_0 = \{x,1,\ldots,m+n,y\}$ and 
Taking $\mathcal{I} = \{I \subseteq \{1,\ldots,n\} \mid |I| > m \text{ or }  |I|=m \text{ and } s(\beta_I)=-\}$, then we obtain the example of Section \ref{ss:stars}.
\end{exam}
\begin{rem}
    As in Section \ref{ss:stars}, provided $\alpha \in \Sigma_0$ we can relax our assumptions on $Q$ and $\alpha$. For example, dimensions at the vertices $1,\ldots, n$ can be larger than one and the quiver does not need arrows from $x$ and $y$ to each of $1,\ldots,n$. In this case, instead of the power set of $\{1,\ldots,n\}$, consider the collection $P$ of vectors $v \in \bN^n$ with $v_i \leq \alpha_i$ for all $i$. Then define $\mathcal{I} \subseteq P$ to be upward-closed in the sense that, if $v \in \mathcal{I}$ and $v \leq v' \in P$, then also $v' \in \mathcal{I}$. The involution sends $\mathcal{I}$ to the set of vectors 
    \[
    \mathcal{J} := \{w \in P \mid (\alpha_1-w_1,\ldots,\alpha_n-w_n) \notin \mathcal{I}\}.
    \]
    One can define $U$ as in Definition \ref{d:good_subset} to obtain a proper crepant resolution $U/\!/G_{\alpha}$ of $\cM_0(Q,\alpha)$. However, different choices of $\mathcal{I}$ may yield the same set $U$: this happens when they have the same intersection with the set of vectors $v \in P$
    such that both $v+e_x$ and $\alpha-(v+e_x)$ are roots. One can remove this ambiguity by requiring that the antichain $\mathcal{I}_0$ only contain $v$ satisfying the condition that both $v+e_x$ and $\alpha-(v+e_x)$ are roots.
\end{rem}

\subsection{Proof of Theorem \ref{t:stars-git}}
Let $\pi_U$ be the map $U/\!/G_\alpha \to \mu^{-1}(0)/\!/G_\alpha$. We will show, in order, the following:
\begin{enumerate}
\item[(1)] $U/\!/G_\alpha$ is a smooth prevariety (see definition below), and a geometric quotient of $G_\alpha$; 
\item[(2)] $\pi_U$ is birational and crepant; 
\item[(3)] $U/\!/G_\alpha$ has the $A_2$ property, hence it and  $\pi_U$ are separated;
\item[(4)] $\pi_U$ is proper. 
\end{enumerate}
We will recall the relevant notions before each step.

\subsubsection{Smoothness and the geometric property of the quotient} 
To see that $U/\!/G_{\alpha}$ is geometric, we apply the following lemma.
For technical reasons we will need to slightly relax the definition of variety by not requiring separability. Following \cite[Ch. 5, Definition 1]{Mumford}, a \emph{prevariety} is a reduced scheme of finite type over $\bC$.  We extend the notion of good and geometric quotients to prevarieties, allowing non-separability. 

Let us more generally consider any reductive group $G$ acting on any affine variety $V$. We recall that a character $\chi:G \to \bC^\times$ is called \emph{generic} if every $\chi$-semistable point is $\chi$-stable, i.e., $V^{\chi-ss}=V^{\chi-s}$.
\begin{lem}\label{l:fin-stabilisers}
%Let $G$ be a reductive group acting on an affine variety $V$ and 
Let $U \subseteq V$ be any open, $G$-stable subset.
Suppose that the stabilizers of $G$ on $U$ are finite. Then there is a geometric quotient prevariety $U/\!/G$ and morphism $\pi: U/\!/G \to V/\!/G$.
\end{lem}
\begin{proof}
By \cite[Lemma 1.1]{Proudfoot-GIT-at-once}, when $G$ is a torus, then for every point $v \in V$ where $G$ acts with finite stabilizer, there exists a generic character $\chi: G \to \bC^\times$ such that $v$ is $\chi$-stable.  Now for reductive $G$, we can apply this to a maximal torus $T \leq G$.  Since every one-parameter subgroup is conjugate to a subgroup of $T$, by the Hilbert--Mumford criterion, $v \in V$ is 
$\chi$-stable if and only if it is $\chi|_T$-stable for the restricted action of $T$. 

As a result, $U$ is covered by the $\chi$-stable loci $U^{\chi-s} \subseteq U$ as $\chi$ ranges over generic characters of $G$.  By GIT, there is a geometric quotient $V^{\chi-s}/\!/G = V^{\chi-ss}/\!/G$.  Since the $G$-orbits on $V^{\chi-s}$ are closed, passing to the $G$-stable open subset $U^{\chi-s}$ yields a  geometric quotient $U^{\chi-s}/\!/G$.  
For varying $\chi$, these can be glued together along intersections to obtain a geometric quotient prevariety $U/\!/G$. By functoriality this canonically maps to the categorical quotient $V/\!/G$.
\end{proof}
We now return to $U$ as before, and show that  $U/\!/G_\alpha$ is smooth. 
%It is convenient for this purpose to replace $G_\alpha$ by $PG_{\alpha} := G_\alpha/\bC^\times$ where $\bC^\times$ is the diagonal torus. This is possible because $\bC^\times$ acts trivially on representation space, hence on $U$.
%First, note that the diagonal torus $\bC^\times \subseteq G_\alpha$ acts trivially on representation space, hence also on $U$, so we can replace the group $G_\alpha$ by $PG_\alpha := G_\alpha/\bC^\times$. 
Equivalently, we show that $U/\!/PG_\alpha$ is smooth. It suffices to show that the stabilizer in $PG_\alpha$
%$\Rep(\overline{Q},\alpha)$ This is because 
%the stabilizer in $PG_\alpha$
%$:= \bigl( \prod_{i \in Q_0} \GL(\alpha_i,\bC) \bigr)/\bC^\times$ 
of every point of $U$ is trivial.  Indeed, for $g = (g_i) \in G_\alpha$ to stabilize a nonzero path from vertex $i$ to $j$ (with $i \neq j$), we must have $g_i=g_j$. So $g$ is in the diagonal $\bC^\times$ (meaning $g_i = g_j$ for all $i, j \in Q_0$) if the set of nonzero arrows in $U$, considered as an undirected graph, is connected.
%contains a spanning tree . 
By Definition \ref{d:good_subset} (3) of $U$, there is a nonzero path from $x$ or $y$ to each $i \in \{ 1, \dots, n\}$. And by definition of $\mathcal{J}$, $I \cap J \neq \emptyset$, so there is some $i' \in I \cap J$ receiving nonzero paths from both $x$ and $y$. Put together, the undirected graph of nonzero arrows must be connected.

%obtain a spanning tree by collecting arrows from one of $x$ or $y$ to each of the vertices $1,\ldots,n$ other than $i'$, together with arrows from both of $x$ and $y$ to $i'$.

\subsubsection{Crepancy}
Next, we show that $\pi_U$ is birational and crepant. Note that by our assumptions on $Q$, 
$\alpha \in \Sigma_0$, i.e., 
there exists a simple representation of $\overline{Q}$ in $\mu^{-1}(0)$.
%(i.e., $\alpha \in \Sigma_0$ \cite{CB01}); 
Explicitly, since all dimensions are one, these are the representations for which there is a nonzero path from every vertex to every other vertex. The locus of simple representations $U^s \subseteq U$
%(which are all in $U$, although without knowing this we could consider the simple representations in $U$)
%, $U^{\text{s}} \subseteq U$, 
consists of closed, free orbits of $PG_\alpha$
%$$=G_\alpha/\bC^\times$ 
and the maps $U^{\text{s}}/\!/G_{\alpha} \to U/\!/G_\alpha$ and $U^{\text{s}}/\!/G_{\alpha} \to \mu^{-1}(0)/\!/G_\alpha$ are open embeddings. This implies that $\pi_U$ is birational.

Now we show that $\pi_U$ is crepant. It suffices to show that the source is symplectic, since the target is a symplectic singularity and has trivial canonical bundle.

To see this, note that $U = \mathcal{U} \cap \mu^{-1}(0)$ where $\mathcal{U}$ is an open subset of the symplectic representation space, $\Rep(\overline{Q},\alpha) = \bigoplus_{a \in \overline{Q}} \Hom(\bC^{\alpha_{s(a)}}, \bC^{\alpha_{t(a)}})$, defined again by the same condition that there exist nonzero paths with specified endpoints. Then $\mathcal{U}$ is naturally symplectic.
%with open inclusion $\mathcal{U} \to \Rep(\overline{Q},\alpha)$ Poisson.  

Thus, $U/\!/PG_\alpha$ is a Hamiltonian reduction of a smooth symplectic variety $\mathcal{U}$ by a free Hamiltonian action of a reductive group, $PG_\alpha$. As a result it smooth  symplectic.

\subsubsection{The $A_2$ property and separability}
%Can we use a constructive proof where for any u_1, u_2 in U we produce an explicit quasiprojective open subset U_{12}?
%Alternate proof of $A_2$ property: Let $u_1, u_2 \in U$ be representations. Then there exists some arrow $a \in \overline{Q}_1$ such that $u_1$ and $u_2$ are both non-zero on $a$. Hence $u_1, u_2 \in \{ p \in \mu^{-1}(0) : p(a) \neq 0 \}$. 

%Next we  show that $\pi_U$ is separated.  
We next prove  that $U/\!/PG_\alpha$ has the $A_2$ property: any two points lie in some affine open subset. We prove the equivalent (but \emph{a priori} more general) assertion that they lie in a quasiprojective open subset. Note that the $A_2$ property immediately implies that $U/\!/PG_\alpha$ is separated, and hence a variety. As a consequence, $\pi_U$ is separated (by \url{https://stacks.math.columbia.edu/tag/01KV}).


The argument is similar to \cite{ADHL}[Proposition 3.1.3.8], but we give a direct, self-contained proof. The key notion is that of an \emph{orbit cone}:
\begin{defn}
Let a reductive group $G$ act on an affine variety $V$.
    The \emph{orbit cone} $\omega_v$ of a point $v \in V$ is the $\bR_{\geq 0}$-linear span in $\Hom(G,\bC^\times) \otimes_\bZ \bR$ of all characters $\theta: G \to \bC^\times$ for which $v$ is in the $\theta$-semistable locus.
\end{defn}
Note that $\omega_x$ is a union of GIT equivalence classes. Two points $\theta, \theta' \in  \Hom(G,\bC^\times) \otimes_\bZ \bR$ are equivalent if and only if,  for every root $\beta \leq \alpha$, which in our situation is merely the restriction of $\alpha$ to a connected subset of $Q$, we have that $\theta \cdot \beta$ and $\theta' \cdot \beta$ have the same sign, interpreted as an element in the set $\{-,0,+\}$. 

We consider $PG_\alpha$ acting on $U$. Note that $U$ is covered by $PG_\alpha$-stable affine open subsets: $U' \subseteq U$, defined by the condition that for certain ordered pairs of vertices $(a,b)$, there is a nonzero path from $a$ to $b$. Fix some $U'$ and let $u \in U'$. 
We claim that $\omega_u \subseteq \Hom(PG_\alpha, \bC^\times) \otimes_\bZ \bR$ is a top-dimensional cone, i.e., its interior is open.  This is a consequence of the fact used in the proof of Lemma \ref{l:fin-stabilisers}  that every point with finite (here trivial) stabilizer is in the stable locus for some generic stability parameter.%, which we can then take to be generic (since perturbing the stability condition can only shrink the stable locus). 
\begin{rem}
We can also give a direct argument that $\omega_u$ has open interior:
%, but
%\cite[Lemma 1.1]{Proudfoot-GIT-at-once}, since the stabilizer of $x$ is trivial, but 
%we can also see it explicitly:
$U'$ is defined by the condition that there exist nonzero paths from vertex $x$ to a subset $I \subseteq \{1,\ldots,n\}$ of vertices and from $y$ to a subset $J \subseteq \{1,\ldots,n\}$ of vertices. Moreover, we have $I \cup J = \{1,\ldots,n\}$ and $I \cap J \neq \emptyset$. Then we can consider the stability condition $\theta$ which has $\theta_x = |I|$, $\theta_y = |J|$, and $\theta_i = -\frac{|I|+|J|}{n}$ for all $i \in \{1,\ldots,n\}$. Since $\theta_i < -1$ for all $i \in I$, if $\theta \cdot \beta > 0$ for a root $\beta \leq \alpha$, then $\beta$ is either a root $\beta_{I'}$  or a root $\gamma_{J'}$ for some $|I'| < |I|$ or $|J'| < |J|$, or else $\beta > e_x + e_y$. This implies by the definition of $U'$ that  there must exist a nonzero path from a vertex in the support of $\beta$ to a vertex in the complement of its support. Since this holds for all $\beta \leq \alpha$, 
the representation $u$ is indeed $\theta$-stable. Moreover, the argument works for an open ball around $\theta$, so we find that $\omega_u$ contains an open set and hence an open cone, as desired. 
\end{rem}
 Now, given two points $u_1,u_2 \in U$, we claim that the interiors $\omega_{u_1}^\circ, \omega_{u_1}^\circ$ of the orbit cones $\omega_{u_1}, \omega_{u_2}$ must intersect nontrivially. We use the following basic lemma:
 \begin{lem}
Let $\mathcal{H}$ be a collection of hyperplanes in $\bR^n$, and let $C_1, C_2 \subseteq \bR^n$ be two nonempty open polyhedral cones defined as the intersection of open half-spaces defined by some of the hyperplanes in $\mathcal{H}$. The intersection $C_1 \cap C_2$ is empty if and only if, for some $H \in \mathcal{H}$, $C_1$ and $C_2$ are contained in different half-spaces with boundary $H$.
 \end{lem}
 \begin{proof}
Since the boundaries of $C_1$ and $C_2$ are contained in the union of the hyperplanes in $\mathcal{H}$, the intersection $C_1 \cap C_2$ is empty if and only if they are separated by at least one of the planes $H \in \mathcal{H}$. 
     \end{proof}
     Every pair of points $u_1,u_2 \in U$ lie in $PG_\alpha$-stable open subsets $U_1, U_2$ defined by certain ordered pairs of vertices having nonzero paths.  The orbit cones of $u_1$ and $u_2$ are defined as corresponding intersections of half-spaces defined by the root hyperplanes $\beta^\perp$ for $\beta \leq \alpha$.  By construction, for each hyperplane $\beta^\perp$, only one of the half-spaces is possible, i.e., there is at most one sign $+$ or $-$ for which we can require $\theta \cdot \beta$ has that sign in an orbit cone.  Namely, we can require the sign $-$ for roots $\beta_I$ with $I \in \mathcal{I}$ and for roots $\gamma_J$ with $J \in \mathcal{J}$, and $+$ for the complementary roots $\alpha-\beta_I, \alpha-\gamma_J$.  

     As a result, there exists a stability condition $\theta$ in the intersection $\omega_{u_1}^\circ \cap \omega_{u_2}^\circ$. Since the intersection is open, we can find $\theta$ which is not in any of the root hyperplanes $\beta^\perp$ for $\beta \leq \alpha$. Then $PG_\alpha$ acts freely on the $\theta$-semistable locus, which equals the $\theta$-stable locus. As a result the inclusions $U' := U \cap \mu^{-1}(0)^{\theta-\text{s}}
     \to U$ and $U' \to \mu^{-1}(0)^{\theta-\text{s}}$ induce open inclusions after dividing by $PG_\alpha$.
     Since $\mu^{-1}(0)^{\theta-\text{s}}/\!/PG_\alpha = \cM_\theta(Q,\alpha)$ is quasi-projective, we find that the images of $u_1,u_2$ in $U/\!/PG_\alpha$ are contained in an open subset which is quasi-projective. Hence $U/\!/PG_\alpha$ has the $A_2$ property as desired.


\subsubsection{Properness}
Finally, we come to the main step of the proof: to show that $\pi_U$ is proper. We will apply the valuative criterion of properness together with Hilbert's description of maximal ideals of invariant rings (i.e., Lemma \ref{l:good-quotient}).  We write the valuative criterion as follows:
\begin{lem} Let $V$ be an affine variety, $a: G \times V \to V$ an action of a reductive algebraic group $G$  on $V$, and $U \subseteq V$ a $G$-stable open subset.  Then the morphism $\pi_U: U/\!/G \to V/\!/G$ is proper if it is separated and, for every discrete valuation ring $R$ with fraction field $K$
%with complete fraction field $K$ and algebraically closed residue field $k$, 
and every point $p: \Spec K \to U$ lying over a point $q: \Spec R \to V/\!/G$, there exists an element $g \in G(K)$ and a point $\widetilde q: \Spec R \to U$ making the diagram commutative: \[\begin{tikzcd}
    \Spec K \arrow[r,"g \times p"] \arrow[d] & G \times U \arrow[r,"a"] & U  \arrow[d] \\
    \Spec R \arrow[rru,dashed,"\widetilde q"] \arrow[rr,"q"] & & V/\!/G
\end{tikzcd}
\]
\end{lem}
\begin{proof} Since we assume that $\pi_U$
%$U/\!/G \to V/\!/G$ 
is separated, the usual valuative criterion of properness asks that, for every pair of points $\overline{p}: \Spec K \to U/\!/G$ and $q: \Spec R \to V/\!/G$ fitting into a commutative diagram, there exists a $\hat q: \Spec R \to U/\!/G$ lifting the two, i.e., a dashed arrow completing the following diagram exists:
\[
\begin{tikzcd}
\Spec K \arrow[r,"\overline{p}"] \arrow[d] & U/\!/G \arrow[d,"\pi_U"] \\
\Spec R \arrow[r,"q"] \arrow[ru,"\hat q",dashed] & V/\!/G
\end{tikzcd}
\]

Suppose that we begin with a point $\overline{p}: \Spec K \to U/\!/G$. If there exists a point $p: \Spec K \to U$ whose composition with the quotient morphism is $\overline{p}$, then by the assumption we obtain a point $\widetilde q: \Spec R \to U$ whose composition with the quotient morphism yields a point $\hat q: \Spec R \to U/\!/G$ 
satisfying the usual valuative criterion of properness.

Thus it would suffice to show that the point $p: \Spec K \to U$ exists. However, this point does not have to exist in general. Rather, it is a consequence of Lemma \ref{l:good-quotient}
 that, for some finite extension $K' \supseteq K$, there is a point $p': \Spec K' \to U$ fitting into a commutative diagram:
\[\begin{tikzcd}
  \Spec K' \arrow[r] \arrow[d] & U \arrow[d] \\
  \Spec K \arrow[r] & U/\!/G
\end{tikzcd}
\]
Now we can let $R' \subseteq K'$ be the integral closure of $R$ in $K'$, and by applying the lemma, we find a point $q': \Spec R' \to U$ satisfying the desired hypotheses.  The image $\Spec R' \to U/\!/G$ factors through a $K$ point. Since $R' \cap K =R$, it also factors through an $R$-point $\hat q: \Spec R \to U/\!/G$ verifying the valuative criterion of properness.
%We just note that as stated in \cite[7.3.9]{EGA2}, it is enough to assume that $K$ is complete and $k$ is algebraically closed.
\end{proof}
%% Note: it may not matter when $G$ is a torus, but for more general reductive groups $G$ we will want to apply the Le Bruyn--Procesi theorem to describe the generators of the invariant ring $k[V]^G$ and for that we need $k$ to be algebraically closed.

Next, we explain how to verify the hypotheses of the lemma in the situation at hand. Given a $K$-point $u \in U(K)$, we will apply elements of $G_\alpha(K)$ in a systematic way in order to produce an element of $U(R)$.  We apply the following lemma repeatedly:
\begin{lem} \label{l:proper}
Let $Q$ be a quiver
%, $\alpha = (1,\ldots,1) \in \bN^{Q_0}$, 
and $I \subseteq Q_0$ a subset of the vertices. Let $R$ be a discrete valuation ring with fraction field $K$.
%Suppose that $p \in \Rep(\overline{Q},\alpha)(K)$ lies over a point $q \in \Rep(\overline{Q},\alpha)/\!/G_\alpha (R)$, i.e., we have a commutative diagram 
 Suppose that $p \in \Rep(\overline{Q},\alpha)(K)$ has the properties:
\begin{itemize}
    \item all paths with both endpoints in $I$ are valued in $R$;
    \item %there exists a path and that 
    there is a nonzero path from some vertex in $I$ to some vertex in $I^c \subseteq Q_0$.
\end{itemize} 
Then there is an element in the diagonal subgroup, $g \in K^\times \subseteq (K^\times)^I$, and a vertex $j \in I^c$ such that the representation $g \cdot p$ satisfies:
\begin{itemize}
    \item all paths beginning at vertices in $I \cup \{j\}$ are valued in $R$;
    \item some path from a vertex in $I$ to $j$ is not valued in the maximal ideal $\mathfrak{m} \subseteq R$.
\end{itemize}
If, in the representation $p$, all paths beginning at $I$ are valued in $R$, then $g^{-1} \in R$, so that this operation preserves the condition that any path is valued in $R$.
\end{lem}
\begin{proof}
Let $\Delta_I: K^\times \to (K^\times)^I$ be the diagonal embedding. For $c \in K^\times$, note that applying $\Delta_I(c)$ to a representation rescales paths from $I$ to $I^c$ by $c^{-1}$, those from $I^c$ to $I$ by $c$, and leaves other paths fixed.

Let $t \in R$ be a uniformizer.  In view of the preceding paragraph, there exists a maximum integer $m \in \bZ$ such that $\Delta_I(t^m) \cdot p$ has 
values of all arrows from $I$ to $I^c$ in $R$. Then there exists an arrow from $I$ to $I^c$ which is not in the maximal ideal. We can let $j$ be the target of this arrow.  

We claim that $j$ has the desired properties.  By construction, it satisfies all properties except possibly the condition that all paths beginning at $j$ are valued in $R$. Suppose some such path is not valued in $R$. Then it is in $t^{-m} R$ for some $m \geq 1$.  Composing with a path beginning at a vertex of $I$ and ending at $j$, which is valued in $R$ but not in $tR$, we get a path beginning at $I$ and valued in $t^{-m} R$, a contradiction.

The last statement holds by our choice of $m$, and because we already established that all paths beginning at $I$ will be valued in $R$. \qedhere
%But it does satisfy the condition that all paths beginning at $I$ are valued in $R$. So composing any path beginning at $j$ with a path from some vertex of $I$ to $j$ which is in $R$ but not in the maximal ideal, 
\end{proof} 

Finally, we return to our original quiver with $\alpha=(1,\ldots,1)$. Begin with a representation $p \in \Rep(\overline{Q},\alpha)(K)$ whose image in $\Rep(\overline{Q},\alpha)/\!/G_\alpha$ is an $R$-point. The latter condition means that (the trace of) every closed path is in $R$. 
%diagram as in \eqref{e:p-over-q}. 

Let $I := \{x\}$ so every path beginning and ending at $x$ lies in $R$. %Since the dimension at $x$ is one, by the trace condition, all paths beginning and ending at $x$ are in $R$. 
By Lemma \ref{l:proper}, passing to other representations in the $G_{\alpha}(K)$ orbit of $p$, we can continually expand $I$ until either $I$ contains all vertices, or there are no nonzero paths from $I$ to $I^c$. All paths beginning at $I$ will be valued in $R$, and there will be paths from $x$ to all vertices of $I$ which are not in the maximal ideal (from $x$ to itself, this can be the identity path).  

Next, we set $J := \{y\}$ and apply the same procedure. The first step could create some paths ending at $y$ which are not in $R$, but after this step, by the last statement of the lemma, we will not create any new paths which are not in $R$. Note that every time we replace $J$ with $J \cup \{j\}$ for $j \in \{1,\ldots,n\}$, we have to remove the vertices of $J$ (other than $j$) from $I$. If at some point we add $x$ to $J$, then by Definition \ref{d:good_subset} (3) of $U$, we can continue the procedure until $J$ contains all vertices. If we do not add $x$ to $J$, we can continue the procedure until $I \cup J$ consists of all vertices. 

The end result of the preceding paragraph is that there are subsets $I':=I\setminus\{x\}, J':=J\setminus\{y\} \subseteq \{1,\ldots,n\}$, with $J'$ nonempty, such that:
\begin{itemize} 
\item $I' \cup J' = \{1,\ldots,n\}$;
\item All paths not ending at $y$
%with endpoints in the set $\{x\} \cap I'$ 
are in $R$;
\item For each $i \in I'$ there is a path from $x$ to $i$ which is not in $\mathfrak{m} \subseteq R$;
%\item All paths with endpoints in the set $\{y\} \cap J'$ are in $R$;
\item For each $j \in J'$ there is a path from $y$ to $j$ which is not in $\mathfrak{m} \subseteq R$;
\item $J' \in \mathcal{J}$.
\end{itemize}
Suppose there is a path ending at $y$ which is \emph{not} in $R$. Then composing with a path from $y$ to a vertex of $J'$ in $R \setminus \mathfrak{m}$ would produce a path not ending at $y$ which is not valued in $R$, a contradiction. So all paths are valued in $R$.

%To complete the proof that $\pi_U$ is proper, it suffices to show that $I' \in \mathcal{I}$ so the representation lies in $U(R)$ (see Definition \ref{d:good_subset}).

If $I' \in \mathcal{I}$, then by Definition \ref{d:good_subset}, the representation is in $U(R)$, which completes the proof that $\pi_U$ is proper. 

Otherwise, we again apply the Lemma \ref{l:proper} to $I:= \{x\} \cup I'$, at each stage either adding (a) the vertex $y$, or (b) a vertex $i$ of $\{1,\ldots,n\}$. 
\begin{itemize}
    \item[-] If at any stage we add $y$ to the set $I$ then we can freely add the entire set $J'$ to $I'$. So $I' = \{ 1, \ldots, n \}$. Since $\mathcal{I}$ is nonempty and upward-closed , $I' = \{1, \ldots, n \} \in \mathcal{I}$, completing the proof. 
    \item[-] If we wish to add $i \in \{1 , \ldots, n \}$ to $I$, then we first need to remove all vertices of $I'$ from $J'$; in other words, we set $J':=\{1,\ldots,n\}\setminus I'$ and afterwards add $i$ to $I'$. After this we still have $J' \in \mathcal{J}$, by the defining property of $\mathcal{J}$, because $I' \not \in \mathcal{I}$. We iterate until $I' \in \mathcal{I}$, again completing the proof.
\end{itemize}
