% \longrightarrow d_{\tau}(\Phi(c)))$.

\begin{defn}[{\cite[Definition 6.2]{GP24}}]
     Let $A$ be a C$^*$-algebra. A 1-quasitrace is a function $\tau: A \rightarrow \mathbb{C}$ such that
     \begin{enumerate}
         \item $\tau(a+i b)=\tau(a)+i \tau(b)$ for all $a, b \in A_{sa}$;
         \item $\tau$ is linear on commutative subalgebras of $A$;
         \item $\tau\left(a^* a\right)=\tau\left(a a^*\right) \geq 0$ for all $A$.
     \end{enumerate}
     If $A$ is unital, we require $\tau(1)=1$ as well.
     We say that $\tau$ is a quasitrace if it extends to a 1-quasitrace on $M_n(A)$ for all $n \in \mathbb{N}$. We use $\mathrm{QT}(A)$ to denote the space of all quasitraces on $A$.
\end{defn}


\begin{defn}[{\cite[Definition 6.4]{GP24}}]
    Let $A$ be a unital $\mathrm{C}^*$-algebra. Given $\tau \in \mathrm{QT}(A)$, we define its associated dimension function $d_\tau: \mathrm{Cu}(A) \rightarrow[0, \infty]$ by
    \[d_\tau([a])=\lim _{n \rightarrow \infty} \tau\left(a^{\frac{1}{n}}\right)\]
    for all $a \in M_{\infty}(A)_{+}$, and extended to $(A \otimes \mathcal{K})_{+}$by taking suprema. 

\end{defn}
Implicit in the definition is the fact that $d_\tau([a])$ only depends on $[a]$. As such we will use $d_\tau([a])$ and $d_\tau(a)$ interchangeably.

\begin{prop}[{\cite[Proposition 6.6]{GP24}}]
    Let $A$ be a unital C$^*$-algebra. Given $\tau \in \mathrm{QT}(A)$, the map $d_\tau$ is well-defined on $\mathrm{Cu}(A)$. Moreover, we have:
    \begin{enumerate}
        \item $d_\tau(0)=0$;
        \item $d_\tau([1])=1$;
        \item $d_\tau(s+t)=d_\tau(s)+d_\tau(t)$ for all $s, t \in \mathrm{Cu}(A)$;
        \item $d_\tau(s) \leq d_\tau(t)$ whenever $s \leq t$ in $\mathrm{Cu}(A)$;
        \item $d_\tau$ preserves suprema of increasing sequences.
    \end{enumerate}
\end{prop}

\begin{prop}[{\cite[Proposition 6.7]{GP24}}] \label{rank, measure of suppport}
    Let $X$ be a compact Hausdorff space, let $\mu$ be a regular Borel probability measure, and let $\tau: C(X) \rightarrow \mathbb{C}$ be the trace it induces. Given $a \in$ $C(X)_{+}$, we have
\[d_{\tau}([a])=\mu\left(\operatorname{supp}_{\mathrm{o}}(a)\right).\]
\end{prop}
