\begin{defn}[{\cite[Definition 8.5]{GP24}}]
    Let $A$ be a simple unital $\mathrm{C}^*$-algebra. We say that $A$ has \textit{strict comparison} (of positive elements by quasitraces) if whenever $a, b \in(A \otimes \mathcal{K})_{+}$ are nonzero and satisfy $d_\tau(a)<d_\tau(b)$ for all $\tau \in \operatorname{QT}(A)$, then $a \precsim b$.
\end{defn}


\begin{prop}[{\cite[Proposition 2.23]{APT11}}] \label{0 accum pt for noncompact}
    Let A be a unital C$^*$-algebra with stable rank one. It follows that $[a]$ is compact in $\mathrm{Cu}(A)$ if and only if $0$ is either an isolated point of $\sigma(a)$ or $0 \notin \sigma(a)$.
\end{prop}

\begin{cor}[{\cite[Corollary 2.24]{APT11}}] \label{substraction in Cu(A)}
    Let A be a unital C$^*$-algebra which is either simple or of stable rank one. Then the Murray-von Neumann semigroup $V(A)$ of $A$ can be identified as a subsemigroup of $\mathrm{Cu}(A)$:
    \[\mathrm{V}(A)=\{x \in \mathrm{Cu}(A) \mid \text{if } x\leq y \text{ for } y \in \mathrm{Cu}(A), \text{ then } x+z=y \text{ for some } z\in  \mathrm{Cu}(A)\}.\]
\end{cor}

\begin{prop}[{\cite[Proposition 5.9]{APT11}}] \label{qt: noncompact compact}
    Let A be a simple C$^*$-algebra with strict comparison. Let $[a]$ and $[b]$ be elements in  $\mathrm{Cu}(A)$ such that $[a]$ is noncompact and $[b]$ is compact. If $d_{\tau}(a)\leq d_{\tau}(b)$ for every $\tau \in \mathrm{QT}(A)$, then $a \precsim b$. 
\end{prop}

\begin{prop}[{\cite[Proposition 5.10]{APT11}}] \label{qt: compact noncompact}
    Let A be a simple C$^*$-algebra with strict comparison. Let $[a]$ and $[b]$ be elements in  $\mathrm{Cu}(A)$ such that $[a]$ is compact and $[b]$ is noncompact. Then, $a \precsim b$ if and only if $ d_{\tau}(a)< d_{\tau}(b)$ for every $\tau \in \mathrm{QT}(A)$.
\end{prop}

We summarize some properties of the C$^*$-algebras under consideration, using results in \cite{Cun78} and \cite{Ror04}.
\begin{thm}
    Let $A$ be a simple, separable, unital and $\mathcal{Z}$-stable C$^*$-algebra. 
    \begin{enumerate}
        \item $A$ is stably finite if and only if $QT(A)\neq \emptyset$.
        \item If $\mathrm{QT}(A) \neq \emptyset$, then $A$ has stable rank one and has strict comparison.
    \end{enumerate}
\end{thm}

The following theorem is a special case of Theorem 1.0.1 in \cite{Rob12}, which allows us to lift a $\mathbf{Cu}$-morphism to a $*$-homomorphism.
\begin{thm} \label{Cu-morphism lifts to $*$-homomorphism} Let $A$ be a C$^*$-algebra of stable rank one. 
It follows that for every $\mathbf{Cu}$-morphism $\gamma: \mathrm{Cu}(C[0,1]) \longrightarrow \mathrm{Cu}(A)$ satisfying $\gamma([1_{C[0,1]}]) \leq [1_A]$, there exists a $*$-homomorphism $\Gamma: C[0,1] \longrightarrow A$ such that $\mathrm{Cu}(\Gamma)=\gamma$. Moreover, $\Gamma$ is unique up to approximate unitary equivalence.
\end{thm}



Finally, we need two structure theorems for the Cuntz semigroups of the C$^*$-algebras under consideration. The first of these is a special case of Theorem 1.1 in \cite{Rob13}. 
We denote by $\overline{\N}$ the set of natural numbers with 0 and $\infty$ adjoined, and we denote by $\mathrm{Lsc}([0,1], \overline{\N})$ the lower semicontinuous functions from $[0,1]$ to $\overline{\N}$.
\begin{thm} \label{Cu(C[0,1]) iso}
    The map $\theta: \mathrm{Cu}(C[0,1]) \longrightarrow \mathrm{Lsc}([0,1], \overline{\N})$ defined by \[\theta([a])(t)=\mathrm{rank}(a(t))\] for all $a \in (C[0,1] \otimes K)_{+}$ is a $\mathbf{Cu}$-isomorphism.
\end{thm}

The second isomorphism theorem  was originally obtained in \cite{BPT08} and \cite{BT07} for a version of the Cuntz semigroup based on $\mathrm{M}_\infty(A)$, and was extended in \cite{CEI08} to the version presented below. 

For each element $x=[a] \in \mathrm{Cu}(A)$, we denote by $\widehat{x}: \mathrm{QT}(A) \rightarrow \mathbb{R}_{++}$ the lower semicontinuous function defined by $\widehat{x}(\tau)=d_{\tau}(a)$ for $\tau \in \mathrm{QT}(A)$. We also denote by $\mathrm{LAff}(\mathrm{QT}(A))_{++}$ the semigroup of lower semicontinuous affine functions defined on $\mathrm{QT}(A)$ with values on $(0, \infty]$.

\begin{thm}[{\cite[Theorem 9.7]{GP24}}] \label{Cu(A) iso}
    Let $A$ be a simple, separable, unital, stably finite $\mathcal{Z}$-stable $\mathrm{C}^*$-algebra. Then
\[\mathrm{Cu}(A) \cong \underbrace{\mathrm{V}(A)}_{\text {compacts }} \sqcup  \operatorname{LAff}(\mathrm{QT}(A))_{++},\]
with addition and order defined as follows:

\begin{enumerate}
    \item The addition in $\mathrm{V}(A)$ is the usual addition and in $\operatorname{LAff}(\mathrm{QT}(A))_{++}$is given by pointwise addition of functions. If $x \in \mathrm{~V}(A)$ and $f \in \operatorname{LAff}(\mathrm{QT}(A))_{++}$, then $x+f=\widehat{x}+f \in \operatorname{LAff}(\mathrm{QT}(A))_{++}$.
    \item For $x \in \mathrm{~V}(A)$ and $f \in \operatorname{LAff}(\mathrm{QT}(A))_{++}$, we have
    \begin{enumerate}
        \item $x \leq f$ if $\widehat{x}(\tau)<f(\tau)$ for every $\tau \in \mathrm{QT}(A)$.
        \item $f \leq x$ if $f(\tau) \leq \widehat{x}(\tau)$ for every $\tau \in \mathrm{QT}(A)$.
    \end{enumerate}
\end{enumerate}
\end{thm}

\section{Characterization of compact containment} \label{section: cc}
Here we characterize compact containment in $\mathrm{Cu}(C[0,1])$ in terms of the rank functions appearing in Theorem \ref{Cu(C[0,1]) iso}. This will be used to prove that a map constructed in Section \ref{section: proof of main} preserves compact containment and is therefore a \mbox{$\mathbf{Cu}$-morphism}. We recall first the following general topology result, known as the Katětov–Tong Insertion Theorem \cite{Ton52}.
\begin{thm} \label{continuous btw usc and lsc}
    If $X$ is a normal topological space and $f,g: X \longrightarrow \R$ are functions such that $f$ is upper semicontinuous, $g$ is lower semicontinuous and $f\leq g$, then there exists a continuous function $h: X \longrightarrow \R$ such that $f\leq h\leq g$.
\end{thm}

\begin{lem} \label{cutdown bounded}
    Let $A$ be a C*-algebra. For any $[b]\in \mathrm{Cu}(A)$ and $\epsilon>0$, the function \[t \mapsto \mathrm{rank}((b(t)-\epsilon)_{+})\] is bounded.
    In particular, if $[a]$ and $[b]$ are elements in $\mathrm{Cu}(A)$ such that $[a] \ll [b]$, then the function $t \mapsto \mathrm{rank}((a(t))$ is bounded.
    % $t \mapsto \mathrm{rank}((b(t)-\frac{\epsilon}{2})_{+})$ is bounded, that is, there exists $N \in \N$ such that $\mathrm{rank}((b(t)-\frac{\epsilon}{2})_{+}) \leq N$ for all $t \in [0,1]$.
\end{lem}
\begin{proof}  
    We know $C[0,1] \otimes \mathcal{K}$ is the inductive limit of $C[0,1] \otimes M_n(\C)$ under the inclusion map, meaning that, given $b \in C[0,1] \otimes \mathcal{K}$ and $\epsilon>0$, there exist $N \in \N$ and $c\in C[0,1] \otimes M_N(\C)$ such that $\norm{b-c}<\epsilon$. 
    In fact, if $b$ is positive, we can choose $c$ to be positive, too. By Lemma \ref{norm close subequivalence}, if $\norm{b-c}<\epsilon$ and $b,c\geq0$, then $(b-\epsilon)_{+} \precsim c$. 
    By Theorem \ref{Cu(C[0,1]) iso}, we have \[\mathrm{rank}\left(\left(b(t)-\epsilon\right)_{+}\right) \leq \mathrm{rank}(c(t))\leq N, \ \forall t \in [0,1]\] since each $c(t)$ is an $N \times N$ matrix.

    In particular, if $[a]\ll[b]$ then Proposition \ref{epsilon cc} says there exists $\epsilon>0$ such that $a \precsim (b-\epsilon)_+$, and Theorem \ref{Cu(C[0,1]) iso} gives $\mathrm{rank}(a(t)) \leq \mathrm{rank}\left(\left(b(t)-\epsilon\right)_{+}\right) \leq N$.
\end{proof}
\begin{lem} \label{strict < on open}
    Let $ x$ and $y$ be elements in $\mathrm{Cu}(C[0,1])$, and let $f_x$ and $f_y$ be the rank functions in $\mathrm{Lsc}([0,1], \overline{\N})$ associated with x and y, respectively, (meaning that if $x=[a]$ then $f_x(t)=\theta([a])(t)=\mathrm{rank}(a(t))$. 
    \begin{enumerate}
        \item If $x \ll y$, then there exists a continuous function \[g: [0,1] \longrightarrow [0,\infty)\] such that $f_x(t) \leq g(t) \leq f_y(t)$ for all $t \in [0,1]$.
        \item If, moreover, $y$ is noncompact, then there exists a nonempty open interval $U \subset [0,1]$ such that $f_x(t) \leq g(t) < f_y(t)$ for all $t \in U$.
    \end{enumerate}
\end{lem}
\begin{proof}
    \textbf{(1)}. Let $x=[a]$ and $y=[b]$. Proposition \ref{epsilon cc} says if $[a]\ll[b]$ then there exists $\epsilon>0$ such that $a \precsim (b-\epsilon)_+$, and it is also clear that $(b-\epsilon)_+ \precsim (b-\frac{\epsilon}{2})_+$. Notice that $(b-\epsilon)_{+}(t)=(b(t)-\epsilon)_{+}$, so by Theorem \ref{Cu(C[0,1]) iso} and Lemma \ref{cutdown bounded}, there exists $N \in \N$ such that   
    \[
    \mathrm{rank}(a(t)) \leq \mathrm{rank}((b(t)-\epsilon)_{+})\leq \mathrm{rank}\left(\left(b(t)-\frac{\epsilon}{2}\right)_{+}\right) \leq N, \ \forall t \in [0,1].
    \] 
    In fact, all we need is the following weaker version of Lemma \ref{cutdown bounded} that says
    \[
    \mathrm{rank}\left( \left(b(t)-\frac{\epsilon}{2} \right)_{+} \right) < \infty, \ \forall t \in [0,1],
    \] 
    which follows from the spectral theorem for compact normal operators.

    Define $r_\epsilon(t)$ to be the number of eigenvalues of $b(t)$ that are greater than or equal to $\epsilon$. Notice that $r_\epsilon(t)=N-\mathrm{rank}(s(b(t)))$ where $s: [0,1] \longrightarrow [0,\infty)$ is a continuous function whose open support is $[0,\epsilon)$.
    Since $\mathrm{rank}(s(b(t)))$ is lower semicontinuous, $r_\epsilon$ is upper semicontinuous. Counting eigenvalues with multiplicity we have the following statements: 
    \begin{align*}
        \mathrm{rank}((b(t)-\epsilon)_{+})&=\text{number of eigenvalues of $b(t)$ that are} >\epsilon \\
        r_\epsilon(t)&=\text{number of eigenvalues of $b(t)$ that are} \geq \epsilon, \\
        \text{and } \mathrm{rank}\left(\left(b(t)-\frac{\epsilon}{2}\right)_{+}\right)&=\text{number of eigenvalues of $b(t)$ that are} > \frac{\epsilon}{2}.
    \end{align*} 
    Therefore, for each $t \in [0,1]$, we have
    \begin{align*}
        \mathrm{rank}(a(t)) \leq \mathrm{rank}((b(t)-\epsilon)_{+}) \leq r_\epsilon(t) \leq \mathrm{rank}\left(\left(b(t)-\frac{\epsilon}{2}\right)_{+}\right) \leq \mathrm{rank}(b(t)).
    \end{align*}
    Since $\mathrm{rank}\left( \left(b(t)-\frac{\epsilon}{2} \right)_{+} \right) < \infty, \ \forall t \in [0,1]$, we can apply Theorem \ref{continuous btw usc and lsc} to get a continuous function $g: [0,1] \longrightarrow[0,\infty)$ such that \[r_\epsilon(t) \leq g(t) \leq \mathrm{rank}\left(\left(b(t)-\frac{\epsilon}{2}\right)_{+}\right), \ \forall t\in[0,1].\] Clearly, $\mathrm{rank}(a(t)) \leq g(t) \leq \mathrm{rank}(b(t)) \ \forall t\in[0,1]$, as required.

    \vspace{2mm}
    \noindent
    \textbf{(2)}. Now suppose $y$ is noncompact.

    \vspace{2mm}
    \noindent
    \textbf{Step 1}: Show there exists a nonempty open interval $V \subset [0,1]$ such that for all $t \in[0,1]$, we have $\mathrm{rank}(a(t)) < \mathrm{rank}(b(t))$.

    \vspace{2mm}
    \noindent
    \textbf{Case 1}: If $\mathrm{rank}(b(t))=\infty$ for all $t \in [0,1]$, then by Lemma \ref{cutdown bounded} there exists $N \in \N$ such that $\mathrm{rank}(a(t)) \leq N$ for all $t \in [0,1]$, so $V=[0,1]$ in this case.

    \vspace{2mm}
    \noindent
    \textbf{Case 2}: Suppose $\mathrm{rank}(b(t))<\infty$ for some $t \in [0,1]$.  
    We know from Proposition \ref{epsilon cc} and Theorem \ref{Cu(C[0,1]) iso} that $[a] \ll [b]$ implies there exists some $\epsilon>0$ such that \mbox{$\mathrm{rank}(a(t)) \leq \mathrm{rank}((b-\epsilon)_{+}(t))$} and hence $\mathrm{rank}(a(t)) < \mathrm{rank}(b(t))$ for all $t\in V$. 
    It suffices to show, for all $\epsilon >0$, there exists a nonempty open subset $V$ of $[0,1]$ such that $\mathrm{rank}((b-\epsilon)_{+}(t))<\mathrm{rank}(b(t))$ for all $t \in V$.

    Let $\epsilon>0$ and $n \in \N$ be the lowest possible rank of $b(t)$. 
    Define \[E_n=\{t \in [0,1] \mid \mathrm{rank}(b(t))=n\}.\] 
    Since $y$ is noncompact, $f_y$ is not constant and therefore $E_n$ is not the entire closed interval $[0,1]$ and so $[0,1]-E_n$ is nonempty. We also observe that \[[0,1]-E_n=\{t \in [0,1] \mid \mathrm{rank}(b(t))>n\}\] is open, so $E_n$ is closed. If we pick a boundary point $t_1 \in \partial E_n$, then $t_1 \in E_n$ too, and so $\mathrm{rank}(b(t_1))=n$. 
    Say the spectrum $\sigma(b(t_1) )$ of $b(t_1)$ is a subset of $\{0, \lambda_1, \lambda_2, \cdots, \lambda_n\}$, where $0 < \lambda_1 \leq \lambda_2 \leq \cdots \leq \lambda_n$. (We used subset instead of equal as 0 may or may not be in the spectrum of $b(t_1)$.)
    By continuity of $b(t)$, given $\alpha \in (0,\epsilon)$, there exists a $\delta>0$ such that $|t-t_1|<\delta$ implies $\norm{b(t)-b(t_1)}<\alpha$. 
    Then $\sigma(b(t))$ is at most ``$\alpha$-away" from $\sigma(b(t_1))$, meaning that \[\sigma(b(t)) \subset (\cup_{i=1}^{n}(\lambda_i -\alpha, \lambda_i+\alpha)) \cup [0,\alpha).\] 
    Recall that $(b-\epsilon)_{+}(t)=(b(t)-\epsilon)_{+}$ is defined to be $l_{\epsilon}(b(t))$ via continuous functional calculus, where $l_{\epsilon}: [0,\infty) \longrightarrow [0, \infty)$ is defined by \mbox{$l_{\epsilon}(s)=\max\{0, s-\epsilon\}$}.
    By the spectral mapping theorem, \[\sigma((b-\epsilon)_{+}(t))=\sigma(l_{\epsilon}(b(t)))=l_{\epsilon}(\sigma(b(t))) \subset \cup_{i=1}^{n}(\lambda_i-\epsilon-\alpha, \lambda_i-\epsilon+\alpha).\] 
    Since $\alpha \in (0, \epsilon)$ can be arbitrarily small, this shows 
    $\mathrm{rank}((b-\epsilon)_{+}(t))\leq n$. 
    Now we take $W=(t_1 -\delta, t_1+\delta)$ and $V=W \cap ([0,1]-E_n)$. Since $E_n$ is closed, $V$ is open. $V$ is also nonempty, because $W$ and $[0,1]-E_n$ are both nonempty and $t_1 \in \partial E_n$ means every neighborhood of $t_1$ should intersect both $E_n$ and $[0,1]-E_n$. Since $V \subset [0,1]-E_n$, this shows $\mathrm{rank}((b-\epsilon)_{+}(t)) < n$ for all $t \in V$, and hence $\mathrm{rank}((b-\epsilon)_{+}(t))<\mathrm{rank}(b(t))$ for all $t \in V$. Without loss of generality, we can assume $V$ to be an open interval $(c,d)$.

    \vspace{2mm}
    \noindent
    \textbf{Step 2}: Given the open interval $V$ constructed in Step 1 and the continuous function $g$ on $[0,1]$ constructed in part (1) of the lemma, we show there exists an open interval $U \subset [0,1]$ and a continuous function $\Tilde{g}: [0,1] \longrightarrow \R$ such that $f_x(t) \leq \Tilde{g}(t) < f_y(t)$ for all $t \in U$.

    \vspace{2mm}
    \noindent
    \textbf{Case 1}: Suppose $g$ is identical to $f_x$ on $V$. Let $\varphi$ be a bump function on $V$ bounded by $0$ and $\frac{1}{2}$, that is, $\varphi \in C^{\infty}_{c}([0,1])$, $\operatorname{supp}_{\mathrm{o}}(\varphi)=V=(c,d)$ and \mbox{$0\leq\varphi(t)\leq \frac{1}{2}$} for all $t \in [0,1]$, take $\Tilde{g}=g+\varphi$, then $f_x<\Tilde{g}<f_y$ on $V$. Notice that the strict inequalities come from the fact that $0\leq\varphi\leq \frac{1}{2}$ and $f_y-f_x\geq 1$ on $V$, just take $U$ to be $V$ in this case.

    \vspace{2mm}
    \noindent
    \textbf{Case 2}: Suppose $g$ is identical to $f_y$ on $V$. Using the same $\varphi$ as in Case 1 to define $\Tilde{g}=g-\varphi$, we have $f_x<\Tilde{g}<f_y$ on $V$ similarly, and again we take $U$ to be $V$ in this case.

    \vspace{2mm}
    \noindent
    \textbf{Case 3}: Suppose $g$ is not identical to $f_x$ and $g$ is not identical to $f_y$ on $V$, then there exists a $t_0 \in V$ making $g(t_0)<f_y(t_0)$. Since $f_y-g$ is lower semicontinuous, the set $\{t\in [0,1] \mid  f_y(t)-g(t)>0\}$ is open, which means this set contains some open interval $U$ around $t_0$ such that $f_y(t)>g(t)$ on $U$. We know from part (1) that $f_x(t)\leq g(t)\leq f_y(t)$ for all $t \in [0,1]$, combined with this, we get $f_x(t)\leq g(t)< f_y(t)$ on $U$. Take $\Tilde{g}$ to be $g$ in this case.
\end{proof}

A local characterization of compact containment in $\mathrm{Cu}(C[0,1])$ was given in Proposition 5.5 of \cite{APS11}, and we record it below.  We do not require the definition of a countably based object in $\mathbf{Cu}$ here and instead note simply that every Cuntz semigroup of a separable C$^*$-algebra is countably based (see \cite{GP24}, the remark after Definition 11.16).

\begin{prop} \label{Local Cu(C[0,1]) cc}
    Let $M$ be a countably based semigroup in $\mathbf{Cu}$ and $X$ be a compact Hausdorff space with finite covering dimension. Given two lower semicontinuous functions $f$ and $g$ from $X$ to $M$, we have $g \ll f$ if and only if for every $t \in X$ there are an open neighborhood $U_t$ of $t$, and $c_t \in M$ such that $g(s) \leq c_t \ll f(s)$ for all $s \in U_t$.
\end{prop}

We show now that in $\mathrm{Cu}(C[0,1])$, this local characterization of compact containment is equivalent to a global characterization of compact containment, and in fact, we can say more in the case where both elements are noncompact.

\begin{prop} \label{Cu(C[0,1]) cc}

    Let $x$ and $y$ be elements in $\mathrm{Cu}(C[0,1])$, and let $f_x$ and $f_y$ be the functions in $\mathrm{Lsc}([0,1], \overline{\N})$ associated with x and y, respectively. The following are equivalent
    \begin{enumerate}
        \item $x\ll y$.
        \item For all $t \in [0,1]$, there exist an open interval $U_t$ around $t$ and $c_t \in \overline{\N}$ such that $f_x(s) \leq c_t \leq f_y(s)$ for all $s\in U_t$.
        \item There exists a continuous function $g: [0,1] \longrightarrow [0,\infty)$ such that \[f_x(t) \leq g(t) \leq f_y(t)\] for all $t \in [0,1]$.
    \end{enumerate} If, moreover,  either $x$ or $y$ is compact in $\mathrm{Cu}(C[0,1])$, then 
    \[
    x\ll y \iff f_x \leq f_y.
    \]
    Finally, if $y$ is noncompact, then $x\ll y$ implies that there is a nonempty open interval $U \subset [0,1]$ such that $f_x(t) \leq g(t) < f_y(t)$ for all $t \in U$.
\begin{proof}
    In Proposition \ref{Local Cu(C[0,1]) cc}, take $X=[0,1]$, $M=\overline{\N}$, it is not hard to see in $M=\overline{\N}$, compact containment is equivalent to $\leq$. This proposition says (1) $\iff$ (2).

    % ($\implies$) Suppose that for all $t \in [0,1]$, there exist an open interval $U_t$ around $t$ and $c_t \in \overline{\N}$ such that $f_x(s) \leq c_t \leq f_y(s)$ for all $s\in U_t$, we want to show exists a continuous and bounded function $g: [0,1] \longrightarrow [0,\infty)$ such that $f_x(t) \leq g(t) \leq f_y(t)$ for all $t \in [0,1]$. \textcolor{red}{details}
    Lemma \ref{strict < on open} gives (1) $\implies$ (3), and that if $x$ and $y$ are both noncompact, then \mbox{$x\ll y$} implies there exists a nonempty open interval $U \subset [0,1]$ such that \mbox{$f_x(t) \leq g(t) < f_y(t)$} for all $t \in U$. 

    Let us show (3)$\implies$(2). Suppose there exists a continuous function \[g: [0,1] \longrightarrow [0,\infty)\] such that $f_x(t) \leq g(t) \leq f_y(t)$ for all $t \in [0,1]$. We want to show for any $t \in [0,1]$, there are an open interval $U_t$ around $t$ and a $c_t \in \overline{\N}$ such that $f_x(s) \leq c_t \leq f_y(s)$ for all $s\in U_t$. 
    Pick an arbitrary $t\in[0,1]$, we define $c_t=f_y(t)$.

    \vspace{2mm}
    \noindent
    \textbf{Case 1}: If $f_x(t)<f_y(t)=c_t$, by lower semicontinuity of $f_y$, the set \[\{s\in [0,1] \mid f_y(s)>c_t-\frac{1}{2}\}\] is an open set containing $t$, so it contains an open interval $V_t$ around $t$, this means $f_y(s)>c_t-\frac{1}{2}$ for all $s \in V_t$. 
    We know $f_x$ is integer-valued, so $f_y(s)\geq c_t$ for all $s \in V_t$.
    By continuity of $g$, given $\epsilon=\frac{1}{2}$, there exists an open interval $W_t$ around $t$ such that $g(s) \leq g(t) + \frac{1}{2}$ for all $s \in W_t$, and so
    \begin{align*}
        f_x(s) \leq g(s) \leq g(t) + \frac{1}{2} \leq f_y(t) + \frac{1}{2} = c_t + \frac{1}{2}.
    \end{align*} Again, as $f_x$ is integer-valued, this means $f_x(s) \leq c_t$ for all $s\in W_t$. Set $U_t=V_t \cap W_t$, we have $f_x(s) \leq c_t \leq f_y(s)$ for all $s\in U_t$.

    \vspace{2mm}
    \noindent
    \textbf{Case 2}: If $f_x(t)=g(t)=f_y(t)=c_t$, by continuity of $g$, given $\epsilon=\frac{1}{2}$, there exists $\delta>0$ such that if $s \in U_t=(t-\delta,t+\delta)$ then $|g(s)-g(t)|<\frac{1}{2}$, that is, $c_t-\frac{1}{2}<g(s)<c_t+\frac{1}{2}$. Then $f_x(s)\leq g(s) < c_t+\frac{1}{2}$ and $f_y(s)\geq g(s) > c_t-\frac{1}{2}$. Since $f_x$ and $f_y$ are integer valued, we have $f_x(s)\leq c_t \leq f_y(s)$ for all $s\in U_t$.

    Finally, it follows from Remark \ref{rem: either compact} that if either $x$ or $y$ is compact, then \mbox{$x \ll y \iff x\leq y$}, and Theorem \ref{Cu(C[0,1]) iso} that $x \leq y \iff f_x \leq f_y$.
\end{proof}

\begin{lem} \label{cc lemma}
    Let $X$ be a compact Hausdorff space. Let $r$ and $g$ be functions from $X$ to $\R$ such that  $g$ is lower semicontinuous, $r$ is continuous, and $g(x) > r(x)$ for all $x \in X$. Let $(g_n)_{n \in \N}$ be an increasing sequence of lower semicontinuous functions from $X$ to $\R$ such that $\sup_{n \in \N}g_n(x) \geq g(x)$ for all $x\in X$. Then there exists $n_0 \in \N$ such that $g_{n_0}(x) > r(x)$ for all $x\in X$.
\end{lem}
\begin{proof}
    Since $g-r$ is lower semicontinuous and strictly positive, it achieves a minimum $m>0$ on X. Then $g(x)-r(x) \geq m >\frac{m}{2}>0$ for all $x\in X$. Define $\Tilde{g_n}(x)=\max\{0, r(x)-g_n(x)+\frac{m}{2}\}$, then $(\Tilde{g_n})_{n \in \N}$ is upper semicontinuous, decreasing, non-negative, and converges pointwise to 0. 
    By Dini's theorem for semicontinuous functions, the convergence is uniform. Therefore, given $\epsilon=\frac{m}{2}$, there exists $n_0 \in \N$ such that $0 \leq \Tilde{g_n}(x) <\frac{m}{2}$ for all $x \in X$ and $n \geq n_0$. 
    In particular, $0 \leq r(x)-g_{n_0}(x)+\frac{m}{2} < \frac{m}{2}$, and hence $g_{n_0}(x)>r(x)$ for all $x\in X$.
\end{proof}

{\rm We now give a characterization of compact containment in terms of rank functions.}

\begin{prop}\label{Cu(A) cc}
Let $A$ be a simple, separable, unital, $\mathcal{Z}$-stable C$^*$-algebra with $\mathrm{QT}(A) \neq \emptyset$ and let $x, y$ be elements in $\mathrm{Cu}(A)$. 

\begin{enumerate}
    \item If x and y are both compact and $x\neq y$, then \[x \ll y \iff d_{\tau}(x)<d_{\tau}(y) \quad \forall \tau \in \mathrm{QT}(A).\]
    \item  If x is compact and y is noncompact, then \[x \ll y \iff d_{\tau}(x)<d_{\tau}(y) \quad \forall \tau \in \mathrm{QT}(A).\]
    \item If x is noncompact and y compact, then \[x \ll y \iff d_{\tau}(x)\leq d_{\tau}(y) \quad \forall \tau \in \mathrm{QT}(A).\]
    \item If x and y are both noncompact, then the following are equivalent:
    \begin{enumerate}
        \item $x\ll y$
        \item There exists a continuous and bounded function $r: \mathrm{QT}(A) \longrightarrow (0,\infty)$ such that $\hat{x}(\tau):=d_{\tau}(x) < r(\tau) < d_{\tau}(y)=:\hat{y}(\tau)$ for all $\tau \in \mathrm{QT}(A)$.
        \item There exists a continuous and bounded function $r: \mathrm{QT}(A) \longrightarrow (0,\infty)$ such that $\hat{x}(\tau)=d_{\tau}(x) \leq r(\tau) < d_{\tau}(y)=:\hat{y}(\tau)$ for all $\tau \in \mathrm{QT}(A)$.
    \end{enumerate} 
\end{enumerate}

\end{prop}
\begin{proof}
    \textbf{(1)}. Suppose both $x$ and $y$ are compact and $x\neq y$. By Corollary \ref{substraction in Cu(A)}, \mbox{$x\leq y \implies \exists z \in \mathrm{Cu}(A)$} such that $x+z=y$. Observe that if $x=[p]$ and $y=[q]$ for some projections $p$ and $q$ in $(A \otimes\mathcal{K})_{+}$, then $q-p$ is a representative of $z$, that is, $z=[p-q]$. By dominated convergence theorem $d_{\tau}(z)=\tau(q-p)$, so
    \begin{align*}
        d_{\tau}(y) &= d_{\tau}(x) + d_{\tau}(z) = d_{\tau}(x) + \tau(q-p)
    \end{align*}  We claim that any $\tau \in \mathrm{QT}(A)$ is faithful. Indeed, we know $\mathrm{QT}(A)$ is nonempty, for any nonzero quasitrace $\tau \in \mathrm{QT}(A)$, define $N_{\tau}=\{x \in A \mid \tau(x^*x)=0\}$, then $N_{\tau}$ is an ideal of $A$. 
    Since $1_A$ is not in $N_{\tau}$ and $A$ is simple, $N_{\tau}$ must be the zero ideal, and so $\tau$ is faithful. 
    Since $\tau$ is faithful and $x \neq y$, we have $\tau(q-p)>0$, and so $d_{\tau}(x)<d_{\tau}(y)$ for all $\tau \in \mathrm{QT}(A)$.

    Now suppose $d_{\tau}(x)<d_{\tau}(y)$ for all $\tau \in \mathrm{QT}(A)$.
    Since $A$ is $\mathcal{Z}$-stable, it has strict comparison, this implies $x \leq y$.

    \vspace{2mm}
    \noindent
    \textbf{(2)}. This follows from Proposition \ref{qt: compact noncompact}.

    \vspace{2mm}
    \noindent
    \textbf{(3)}. Suppose $x$ is noncompact and $y$ is compact. Since $d_{\tau}$ is order-preserving, we have \[x \ll y \implies d_{\tau}(x)\leq d_{\tau}(y) \quad \forall \tau \in \mathrm{QT}(A).\] 
    By Proposition \ref{qt: noncompact compact}, \[x \ll y \impliedby d_{\tau}(x)\leq d_{\tau}(y) \quad \forall \tau \in \mathrm{QT}(A).\]

    \vspace{2mm}
    \noindent
    \textbf{(4)}. It is clear that (b) $\implies$ (c).

    Let us show (a) $\implies$ (b). 
    Suppose $x=[a]$ and $y=[b]$ for some $a,b \in (A \otimes\mathcal{K})_{+}$. Let $X=\sigma(b)-\{0\}$, and let us consider the commutative subalgebra $C^*(b)$ generated by $b$, which is isomorphic to $C_0(X)$. 
    Pick an arbitrary $\tau \in \mathrm{QT}(A)$, we know it becomes a tracial state on this commutative subalgebra $C_0(X)$. 
    Let $\mu_\tau$ be the probability measure on $X$ induced by $\tau$ in the Riesz-Markov-Kakutani theorem, that is, for all $f \in C_0(X)$, we have $\tau(f)=\int_{X}fd\mu_{\tau}$. 
    Think of each $f \in C_0(X)$ as a function in $C(\sigma(b))$ such that $f(0)=0$ and apply \mbox{Proposition \ref{rank, measure of suppport}}, we get $d_{\tau}(f(b))=\mu_{\tau}\left(\operatorname{supp}_{\mathrm{o}}(f(b))\right)$ for all $f(b) \in C^*(b)$.
    We have seen in part \textbf{(1)} that $\tau$ is faithful, so the induced measure $\mu_{\tau}$ is also faithful. 
    This is because for any nonempty open set $O \subset X$, $\mu(O)=\int_{X}\chi_{O}d\mu_{\tau}=\tau(\chi_{O})>0$.
    By Proposition \ref{epsilon cc} $x \ll y$ implies there exists $\delta >0$ such that $a \precsim (b-\delta)_+$, and so $d_{\tau}(a) \leq d_{\tau}((b-\delta)_+)$. 
    Since $y=[b]$ is noncompact, we know from  \mbox{Proposition \ref{0 accum pt for noncompact}} that $0\in \sigma(b)$ and $0$ is an accumulation point of $\sigma(b)$. 
    Observe that we can assume $\delta \in X=\sigma(b)-\{0\}$, otherwise we can keep replacing $\delta$ by $\frac{\delta}{2}$ until it is in $X$. 
    Moreover, we can pick two other points $\delta_1$ and $\delta_2$ in $X$ such that \mbox{$0<\delta_2<\delta_1<\delta$}. Then $(\delta_2, \delta_1)$, $(\delta_1, \delta)$, and $(\delta_1, \delta]$ are nonempty  intervals in $X$.
    Now we claim that \[\mu_{\tau}((\delta, \infty) \cap X) < \mu_{\tau}((\delta_1, \infty) \cap X).\] Indeed, as $\mu_{\tau}$ is faithful, we have \[\mu_{\tau}((\delta_1, \infty) \cap X) - \mu_{\tau}((\delta, \infty) \cap X) = \mu_{\tau}(\delta_1, \delta] \geq \mu_{\tau}(\delta_1, \delta) > 0.\]
    Similarly, \[\mu_{\tau}([\delta_1, \infty) \cap X) < \mu_{\tau}((\delta_2, \infty) \cap X).\] 
    Observe that \begin{align*}
        &\tau \mapsto \mu_{\tau}([\delta_1, \infty) \cap X) \quad \text{is upper semicontinuous, while }\\
        &\tau \mapsto \mu_{\tau}((\delta_2, \infty) \cap X)=d_{\tau}((b-\delta_2)_+) \quad \text{is lower semicontinuous.}
    \end{align*}  
    We know when $A$ is unital, $\mathrm{QT}(A)$ is compact in the topology of pointwise convergence.
    By Theorem \ref{continuous btw usc and lsc}, there exists a continuous function  \mbox{$r: QT(A) \longrightarrow (0,\infty]$} such that \[\mu_{\tau}([\delta_1, \infty) \cap X) \leq r(\tau) \leq \mu_{\tau}((\delta_2, \infty) \cap X) \quad \forall \tau \in \mathrm{QT}(A).\] 
    Then we have
    \begin{align*}
        d_{\tau}(a) &\leq d_{\tau}((b-\delta)_+) = \mu_{\tau}((\delta, \infty) \cap X) < \mu_{\tau}((\delta_1, \infty) \cap X) \\ &\leq \mu_{\tau}([\delta_1, \infty) \cap X) \leq r(\tau) \leq \mu_{\tau}((\delta_2, \infty) \cap X) < \mu_{\tau}(X) = d_{\tau}(b) \quad \forall \tau \in \mathrm{QT}(A).
    \end{align*}
    In particular, this shows
    \begin{align*}
        d_{\tau}(a)<r(\tau)<d_{\tau}(b) \quad \forall \tau \in \mathrm{QT}(A).
    \end{align*}

    Now let us show (c) $\implies$ (a). 
    Suppose there exists a continuous function $r: QT(A) \longrightarrow (0,\infty)$ such that \[\hat{x}(\tau)=d_{\tau}(a)\leq r(\tau)<d_{\tau}(b)=\hat{y}(\tau) \quad \forall \tau \in \mathrm{QT}(A)\]
    Let $\{g_n\}_{n \in \N}$ be an increasing sequence of functions from $\mathrm{QT}(A)$ to $(0, \infty]$ such that $\hat{y}(\tau)=\sup_{n \in \N}g_n(\tau)$ for all $\tau \in \mathrm{QT}(A)$. Then by Lemma \ref{cc lemma}, there exists $n_0 \in \N$ such that $g_{n_0}(\tau) > r(\tau) \geq \hat{x}(\tau)$.  and by definition of compact containment, this means $\hat{x} \ll \hat{y}$, and so $x \ll y$.
\end{proof}
\end{prop}



\section{Proof of Theorem \ref{main}}\label{section: proof of main}

In this section we prove our main result, restated here:

\begin{customthm}{1.1}
Let $A$ be unital simple separable $\mathcal{Z}$-stable C$^*$-algebra with nonempty quasitrace simplex $\mathrm{QT}(A)$.  Let $h$ be a continuous affine map from $\mathrm{QT}(A)$ into the set $\mathcal{P}([0,1])^+$ of faithful regular Borel probability measures on $[0,1]$.  It follows that there is a self-adjoint element $a \in A$ with spectrum equal to $[0,1]$ such that $f_a = h$.  
\end{customthm}

Before beginning in earnest let us outline the broad strategy.  We first use the map $h$ to construct a map $\gamma_h:\mathrm{Cu}(C[0,1]) \to \mathrm{Cu}(A)$ and show it is a $\mathbf{Cu}$-morphism. We then use a result of L. Robert to lift $\gamma_h$ to a $*$-homomorphism $\Gamma_h:C[0,1] \to A$ (Theorem \ref{Cu-morphism lifts to $*$-homomorphism}).  Finally, we demonstrate that the image of the identity function under $\Gamma_h$ is a positive operator $a \in A$ such that $f_a = h$.

Recall that 
\[
\mathrm{Cu}(C[0,1]) \cong \mathrm{Lsc}([0,1], \overline{\N})
\]
and
\[
\mathrm{Cu}(A) \cong \mathrm{V}(A) \sqcup \mathrm{LAff(QT}(A){)_{++}}
\]
(see Theorems \ref{Cu(C[0,1]) iso} and \ref{Cu(A) iso}).
Let us define \[\gamma_h: \mathrm{Lsc}([0,1], \overline{\N}) \longrightarrow \mathrm{V}(A) \sqcup \mathrm{LAff(QT}(A){)_{++}}\] as follows:
  \begin{enumerate}
      \item If $f \in \mathrm{Lsc}([0,1], \overline{\N})$ is compact, then we know $f$ is constant with value $n \in \N$ on $[0,1]$ and we define
      \begin{align*}
          \gamma_{h}(f)=n[1_{A}];
      \end{align*}
      \item If $f \in \mathrm{Lsc}([0,1], \overline{\N})$ is noncompact, then we define
      \begin{align*}
          \gamma_{h}(f)(\tau)=\int_{[0,1]}fdh(\tau).
      \end{align*}
  \end{enumerate}
To show $\gamma_h$ is a well-defined $\mathbf{Cu}$-morphism, we need a lemma.

\begin{lem} \label{r(tau) continuous}
    Let $f: [0,1] \longrightarrow [0, \infty]$ be a measurable function, and let $r: \mathrm{QT}(A) \longrightarrow \R$ be defined by $r(\tau)=\int_{[0,1]}fdh(\tau)$. If $f$ is lower semicontinuous, then $r$ is lower semicontinuous; if $f$ is continuous, then $r$ is continuous.
\end{lem}
\begin{proof}
    Let $\{\tau_n\}_{n \in \N}$ be a sequence of points in $\mathrm{QT}(A)$ that converges pointwise to $\tau$ in $\mathrm{QT}(A)$. 
    By continuity of $h$ and Theorem \ref{weak conv equiv to conv in L-P metric}, $h(\tau_n)$ converges to $h(\tau)$ weakly. 
    By the Portmanteau theorem, for every lower semicontinuous function \mbox{$f: [0,1] \longrightarrow [0, \infty]$}, in particular for $f \in \mathrm{Lsc}([0,1], \overline{\N})$, we have \[\liminf \int_{[0,1]}fdh(\tau_n) \geq \int_{[0,1]}fdh(\tau),\] so $r$ is lower semicontinuous. 
    Similarly, if $f$ is continuous, then it is also bounded, and the Portmanteau theorem says $\int_{[0,1]}fdh(\tau_n)$ converges to $\int_{[0,1]}fdh(\tau)$, so $r$ is continuous.
\end{proof}
This shows that when $f \in \mathrm{Lsc}([0,1], \overline{\N})$ is noncompact, $\gamma_{h}(f)$ is indeed lower semicontinuous. It is also easy to see $\gamma_{h}(f)$ is affine when $h$ is affine. Finally, $h(\tau)$ is a faithful measure and so if $f \neq 0$ then there are some $\epsilon>0$ and \mbox{$U \subseteq [0,1]$} open such that $f > \epsilon$ on $U$.  It follows that $\gamma_h(f) > 0$ for every $\tau \in \mathrm{QT}$(A), whence \mbox{$\gamma_{h}(f) \in  \mathrm{LAff(QT}(A){)_{++}}$} and $\gamma_{h}$ is well-defined.

