\begin{prop}
     $\gamma_h$ is a $\mathbf{Cu}$-morphism.
\end{prop}
\begin{proof}
    We need to check that $\gamma_h$ preserves addition, neutral element, order $\leq$, suprema of increasing sequences, and also the compact containment relation $\ll$.

    \vspace{2mm}
    \noindent
    \textbf{(i) Additivity}: If $f$ and $g$ are both compact, say $f=n$ and $g=m$ where $m,n \in \N$, then $\gamma_h(f+g)=(n+m)[1_{A}]=n[1_{A}]+m[1_{A}]=\gamma_h(f)+\gamma_h(g)$.
    If $f$ and $g$ are both noncompact, then for any $\tau \in \mathrm{QT}(A)$, \begin{align*}
        \gamma_h(f+g)(\tau)&=\int_{[0,1]}f+gdh(\tau)\\&=\int_{[0,1]}fdh(\tau)+\int_{[0,1]}gdh(\tau)\\&=\gamma_h(f)(\tau)+\gamma_h(g)(\tau)
    \end{align*}
    If $f$ is compact and $g$ is noncompact, say $f=n\in\N$, then $f+g$ is noncompact, we have \begin{align*}
        \gamma_h(f+g)(\tau)&=\int_{[0,1]}n+gdh(\tau)\\&=\int_{[0,1]}ndh(\tau)+\int_{[0,1]}gdh(\tau)\\&=\widehat{\gamma_h(f)}(\tau)+\gamma_h(g)(\tau)
    \end{align*}
    \vspace{2mm}
    \noindent
    \textbf{(ii) Preservation of zero}: Clearly the zero function on $[0,1]$ is compact, therefore $\gamma_h(0)=0[1_{A}]=0_{\mathrm{Cu}(A)}$.

    \vspace{2mm}
    \noindent
    \textbf{(iii) Preservation of order}: If $f$ and $g$ are both compact, say $f=n$ and $g=m$ where $m,n \in \N$, then $f\leq g$ is equivalent to $n\leq m$, and we have $\gamma_h(f)=n[1{A}]\leq m[1_{A}]=\gamma_h(g)$. If $f$ and $g$ are both noncompact, and $f\leq g$, then for all $\tau \in T(A)$ \begin{align*}
        \gamma_h(f)(\tau)=\int_{[0,1]}fdh(\tau)\leq \int_{[0,1]}gdh(\tau)=\gamma_h(g)(\tau)
    \end{align*} If $f$ is compact and $g$ is noncompact, say $f=n\in\N$. 

    \vspace{2mm}
    \noindent
    \textbf{Case 1}: If $f\leq g$ then $g\geq n$ on $[0,1]$. We know $U=\{t \mid g(t) > n\}$ is an open set by lower semicontinuity of $g$. $U$ is also nonempty, otherwise $g$ would be identically $n$ and hence compact.  Then for all $\tau \in \mathrm{QT}(A)$ we have \begin{align*}
        \widehat{\gamma_h(f)}(\tau)&=\int_{[0,1]}ndh(\tau)
        \\&=\int_{U}ndh(\tau)+\int_{[0,1]-U}ndh(\tau) 
        \\&<\int_{U}gdh(\tau)+\int_{[0,1]-U}gdh(\tau)
        \\&=\int_{[0,1]}gdh(\tau) 
        \\&=\gamma_h(g)(\tau)
    \end{align*} 

    \vspace{2mm}
    \noindent
    \textbf{Case 2}: If $g\leq f=n\in \N$, for all $\tau \in \mathrm{QT}(A)$ \begin{align*}
        \gamma_h(g)(\tau)=\int_{[0,1]}gdh(\tau)\leq\int_{[0,1]}ndh(\tau)=\widehat{\gamma_h(f)}(\tau)
    \end{align*}

    \vspace{2mm}
    \noindent
    \textbf{(iv) Preservation of suprema}:
    Let $\{f_n\}_{n\in\N}$ be an increasing sequence of functions in $\mathrm{Lsc}([0,1], \overline{\N})$ and let $f=\sup_{n\in\N}f_n$. 

    \vspace{2mm}
    \noindent
    \textbf{Case 1}: If $f$ is compact, then by definition of compact containment, there exists $n_0\in\N$ such that $f_n=f$ for all $n\geq n_0$. Therefore, we can just assume $\{f_n\}_{n\in\N}$ to be the constant sequence of this compact element $f=N\in\N$. 
    Then \mbox{$\gamma_h(f)=N[1_{A}]=\gamma_h(f_n)$} for all $n\in\N$, and we have $\gamma_h(f)=\sup_{n\in\N}\gamma_h(f_n)$ trivially.

    \vspace{2mm}
    \noindent
    \textbf{Case 2}: If $f$ is noncompact, and only finitely many $f_n$'s are compact, then without loss of generality, we can assume all $f_n$'s are noncompact, as otherwise we can replace $f_n$ by its tail subsequence. Applying monotone convergence theorem, we have
    \begin{align*}
        \gamma_h(f)(\tau)&=\int_{[0,1]}fdh(\tau)
        \\&=\int_{[0,1]}\sup_{n \in \N}f_n dh(\tau)
        \\&=\sup_{n \in \N}\int_{[0,1]}f_ndh(\tau)
        \\&=\sup_{n \in \N}\gamma_h(f_n)(\tau)
    \end{align*} for all $\tau \in \mathrm{QT}(A)$.

    \vspace{2mm}
    \noindent
    \textbf{Case 3}: If $f$ is noncompact, and there are infinitely many distinct compact elements in the sequence $\{f_n\}_{n\in\N}$, let us denote the subsequence of all compact elements by $\{f_{n_k}\}$, where $f_{n_k}=r_{n_k}[1_{A}]$ and $r_{n_k}\in\N$. Observe that $r_{n_k}$ must go to infinity as $f_{n_k}$'s are distinct. Then $f(t)=\sup_{n\in\N}f_n(t)\geq\sup_{n_k\in\N}f_{n_k}(t)=\infty$ for all $t \in [0,1]$. 
    We have shown that $\gamma_h$ is order-preserving, so 
    \[
    d_{\tau}(\gamma_h(f))\geq d_{\tau}(r_{n_k}[1_{A}])=r_{n_k}. 
    \]
    Since $r_{n_k}$ goes to infinity, we have $d_{\tau}(\gamma_h(f))=\infty$ for all $\tau \in \mathrm{QT}(A)$. We know $\mathcal{Z}$-stability implies strict comparison of positive elements, so $\gamma_h(f)=\infty$ (here $\infty$ denotes the maximal element in $\mathrm{Cu}(A)$). On the other hand, 
    \[
    \sup_{n\in\N}\gamma_h(f_n)\geq\sup_{n_k\in\N}\gamma_h(f_{n_k})=\sup_{n_k\in\N}r_{n_k}[1_{A}]=\infty, 
    \]
    so we have $\gamma_h(f)=\sup_{n\in\N}\gamma_h(f_n)$ in this case too.

    \vspace{2mm}
    \noindent
    \textbf{(v) Preservation of compact containment}:
    Finally, we show that $\gamma_h$ preserves compact containment. Suppose $f \ll g$ in $\mathrm{Lsc}([0,1], \overline{\N})$, then we know in particular $f \leq g$.

    \vspace{2mm}
    \noindent
    \textbf{Case 1}: If either $f$ or $g$ is compact, then either $\gamma_h(f)$ or $\gamma_h(g)$ is compact as $\gamma_h$ sends compact elements to compact elements by construction. 
    By Remark \ref{rem: either compact}, to show $\gamma_h(f) \ll \gamma_h(g)$ it suffices to show $\gamma_h(f) \leq \gamma_h(g)$, and this follows from $f \leq g$ and part \textbf{(iii)} that says $\gamma_h$ is order-preserving.

    \vspace{2mm}
    \noindent
    \textbf{Case 2}: If both $f$ and $g$ are noncompact, then we claim there exists a continuous function $r: [0,1] \longrightarrow [0,\infty)$ such that, $\gamma_h(f)(\tau) \leq r(\tau) < \gamma_h(g)(\tau) \quad \forall \tau \in \mathrm{QT}(A)$. Indeed, we know from Lemma \ref{strict < on open}, there exists a continuous $\phi: [0,1] \longrightarrow [0,\infty)$ such that $f \leq \phi \leq g$ on $[0,1]$, and $f\leq \phi<g$ on a nonempty open interval $U \subset [0,1]$. Define \mbox{$r(\tau):=\int_{[0,1]}\phi dh(\tau)$}, we know from Lemma \ref{r(tau) continuous} that $r$ is continuous. Then
    \begin{align*}
        r(\tau)&=\int_{[0,1]}\phi dh(\tau)
        \\&=\int_{U} \phi dh(\tau)+\int_{[0,1]-U} \phi dh(\tau) 
        \\&<\int_{U}gdh(\tau)+\int_{[0,1]-U}gdh(\tau)
        \\&=\int_{[0,1]}g dh(\tau)
        \\&=\gamma_h(g)(\tau)
    \end{align*}
    Since the Lebesgue integral is order-preserving, $\gamma_h(f)(\tau)\leq r(\tau)$ for all $\tau \in \mathrm{QT}(A)$.
    By Proposition \ref{Cu(A) cc}, this implies that $\gamma_h(f) \ll \gamma_h(g)$.
\end{proof}

Now that we know $\gamma_h: \mathrm{Cu}(C[0,1]) \longrightarrow \mathrm{Cu}(A)$ is a $\mathbf{Cu}$-morphism, Theorem \ref{Cu-morphism lifts to $*$-homomorphism} says it lifts to a $*$-homomorphism $\Gamma_h: C[0,1] \longrightarrow A$, that is, $\mathrm{Cu}(\Gamma_h)=\gamma_h$. We also know a $*$-homomorphism $\Gamma_h: C[0,1] \longrightarrow A$ induces a continuous affine map between the spaces of quasitraces $\Gamma_h^{\#}: \mathrm{QT}(A) \longrightarrow \mathrm{QT}(C[0,1])$ where $\Gamma_h^{\#}(\tau)=\tau \circ \Gamma_h$ for all $\tau \in \mathrm{QT}(A)$.  We will show in the proof of Theorem \ref{main} below that $\Gamma_h^{\#} = h$, so that $\gamma_h$ represents a lifting of $h$ to the level of Cuntz semigroups. 

% \begin{thm}
%     Let $A$ be a simple, separable, unital and $\mathcal{Z}$-stable C$^*$-algebra with a nonempty space of quasitraces $\mathrm{QT}(A)$. Let $\mathcal{P}([0,1])$ be the space of faithful Borel probability measures on $[0,1]$ (note that these measures are automatically regular) equipped with Lévy-Prokhorov metric $d_{LP}$, and $h: \mathrm{QT}(A) \longrightarrow \mathcal{P}([0,1])$ be a continuous and affine map. Then there exists a $*$-homomorphism $\Gamma_h: C[0,1] \longrightarrow A$ whose induced measure $\mu(\tau)$ agrees with $h(\tau)$ for all $\tau \in \mathrm{QT}(A)$. In other words, the map $\Gamma_h^{\#}$ induced by $\Gamma_h$ is exactly $h$.
% \end{thm}
\begin{proof}[Proof of Theorem 1.1]
    Define $a=\Gamma_h(id)$, where $id$ represents the identity function on $[0,1]$. It is clear that $a$ is self-adjoint and $\norm{a}=1$, so the spectrum $\sigma(a)$ is inside $[0,1]$. 
    Pick an arbitrary $\tau \in \mathrm{QT(A)}$. 
    We will show $f_{a}(\tau)=h(\tau)$ by showing they agree on any proper open subset $O$ of $[0,1]$. 
    Pick $b \in C[0,1]$ with $\operatorname{supp}_{\mathrm{o}}(b)=O$. 
    We know from Proposition \ref{<= for elements in C(X)} that the above choice is independent of the representative $b$. 
    Let us denote the quasitrace $\Gamma_h^{\#}(\tau)=\tau \circ \Gamma_h$ on $C[0,1]$ by $\Tilde{\tau}$.  Since $C[0,1]$ is commutative, $\Tilde{\tau}$ is automatically a trace. Note that $f_{a}(\tau)$ is actually the probability measure on $\sigma(a)$ induced by $\Tilde{\tau}$ (which eventually depends on $\tau$), so by Proposition \ref{rank, measure of suppport}, $f_{a}(\tau)(O)=f_{a}(\tau)(\operatorname{supp}_{\mathrm{o}}(b))=d_{\Tilde{\tau}}([b])$. 
    We know by Proposition II.1.8 in \cite{BH81} that quasitraces are norm-continuous. Combining this with the continuity of $\Gamma_{h}$ and $b$, we get
    \begin{align*}
        d_{\Tilde{\tau}}([b])=\lim_{n \rightarrow \infty} \Tilde{\tau}(b^{1/n})=\lim_{n \rightarrow \infty} \tau(\Gamma_h(b^{1/n})) =\lim_{n \rightarrow \infty} \tau(\Gamma_h(b)^{1/n})=d_{\tau}([\Gamma_h(b)]).
    \end{align*}

     We have $\gamma_h=\mathrm{Cu}(\Gamma_h)$, and $\mathrm{Cu}(\Gamma_h)([b])$ is computed as $\mathrm{Cu}([\Gamma_h(b)])$.  Therefore,
    \begin{align*}
        \gamma_h([b])(\tau)=\mathrm{Cu}(\Gamma_h)([b])(\tau)=\mathrm{Cu}([\Gamma_h(b)])(\tau)=d_{\tau}([\Gamma_h(b)]).
    \end{align*}
    Again, by Proposition \ref{<= for elements in C(X)}, $[b]=\chi_{\operatorname{supp}_{\mathrm{o}}(b)}$, so
    \begin{align*}
        \gamma_h([b])(\tau)=\gamma_h(\chi_{\operatorname{supp}_{\mathrm{o}}(b)})(\tau)=\int_{[0,1]}\chi_{\operatorname{supp}_{\mathrm{o}}(b)}dh(\tau) = h(\tau)(\operatorname{supp}_{\mathrm{o}}(b))=h(\tau)(O).
    \end{align*}
    Therefore, $f_{a}(\tau)(O)=d_{\Tilde{\tau}}([b])=d_{\tau}([\Gamma_h(b)])=\gamma_h([b])(\tau)=h(\tau)(O)$, as required.

    Let us show finally that the spectrum $\sigma(a)$ is exactly the closed unit interval $[0,1]$. 
    Suppose it is not, then by compactness of $\sigma(a)$, there is an open interval $U$ inside $[0,1]-\sigma(a)$. 
    Pick two points $\epsilon$ and $\epsilon'$ inside $U$ such that $0<\epsilon<\epsilon'$. It follows that $(\epsilon,1] \cap \sigma(a)=(\epsilon',1] \cap \sigma(a)$.
    Since $f_{a}$ is the induced probability measure on $\sigma(a)$, we have $f_{a}(\tau)((\epsilon,1])=f_{a}(\tau)((\epsilon',1])$. 
    We have shown that $f_{a}=h$, so this means $h(\tau)((\epsilon,1])=h(\tau)((\epsilon',1])$, and hence $h(\tau)((\epsilon,\epsilon'))=0$, which violates the faithfulness of $h(\tau)$.
    Therefore $\sigma(a)=[0,1]$.
\end{proof}

