\subsection{Halo formation}

\begin{figure*}
    \centering
    \includegraphics[ trim={0cm 0cm 0cm 0cm}, clip, width=1\textwidth, keepaspectratio]{figures/SFR.pdf}
    \caption{The SF main sequence of galaxies in \textsc{Phoebos} at $z= 8$, $10$, and $12$, from left to right, shown by the orange hexagrams. The gray diamonds correspond to observations in the redshift range $7.5 \lesssim z \lesssim 8.5$, $9.5 \lesssim z \lesssim 10.5$, and $11.5 \lesssim z \lesssim 12.5$ found by \citet{Morishita:2024aa}. The solid blue line represents the best-fit relation including the full simulated data, following the form  $\rm{SFR} \propto M_{\star}^{\alpha}$. The dashed blue line indicates the best-fit relation restricted to galaxies with stellar masses above the minimum observed by \citet{Morishita:2024aa} at each redshift. For comparison, the purple dotted line shows the relation from the \textsc{Thesan}-1 simulation \citep{Shen:2024aa}, while the solid purple line corresponds to results from the \textsc{Thesan-Zoom} simulations \citep{Kannan:2025aa}.}
    \label{fig:SFR}
