\section{\label{apx:Lagrangian}Lagrangian density}
\vspace{-0.3cm}

Using the geometric condition corresponding to the Minkowski spacetime together with the equivalence principles of scale and mass, the gauge-fixed Lagrangian density of UG in the absence of strong and weak interactions is given by \cite{Partanen2025a}
\begin{align}
 \mathcal{L}&=\frac{i\hbar c}{2}\bar{\psi}_i(\boldsymbol{\gamma}^\nu\vec{\partial}_\nu-\cev{\partial}_\nu\boldsymbol{\gamma}^\nu)\psi_i-m_ic^2\bar{\psi}_i\psi_i
 -\frac{1}{4\mu_0}F_{\mu\nu}F^{\mu\nu}\nonumber\\
 &\hspace{0.4cm}+\frac{1}{8\kappa}(H_{\rho\mu\nu}H^{\rho\mu\nu}+2H_{\rho\mu\nu}H^{\mu\rho\nu}-4H_{\;\,\mu\nu}^\nu H_{\;\;\;\,\rho}^{\rho\mu})\nonumber\\
 &\hspace{0.4cm}-J_\mathrm{e}^\nu A_\nu-T_\mathrm{m}^{\mu\nu}H_{\mu\nu}
 -\frac{1}{2\mu_0\xi_\mathrm{e}}(\partial_{\nu}A^{\nu})^2\nonumber\\
 &\hspace{0.4cm}+\frac{1}{\kappa\xi_\mathrm{g}}\eta_{\gamma\delta}P^{\alpha\beta,\lambda\gamma}P^{\rho\sigma,\eta\delta}\partial_\lambda H_{\alpha\beta}\partial_\eta H_{\rho\sigma}.
 \label{eq:Lagrangian}
\end{align}
The implicit summation over $i$ is over all fermion fields of the theory. In Eq.~\eqref{eq:Lagrangian}, $m_i$ is the mass of the fermion of index $i$, $\xi_\mathrm{e}$ and $\xi_\mathrm{g}$ are the electromagnetic and gravity gauge fixing parameters, $F_{\mu\nu}$ and $H_{\rho\mu\nu}$ are the electromagnetic and gravity field-strength tensors, $J_\mathrm{e}^\nu$ is the electric four-current density, and $T_\mathrm{m}^{\mu\nu}$ is the stress-energy-momentum tensor of the electromagnetic and fermion fields. These quantities are given by \cite{Partanen2025a,Partanen2025b}
\begin{equation}
 F_{\mu\nu}=\partial_\mu A_\nu-\partial_\nu A_\mu,
\end{equation}
\begin{equation}
 H_{\rho\mu\nu}=\partial_\mu H_{\rho\nu}-\partial_\nu H_{\rho\mu},
\end{equation}
\begin{equation}
 J_\mathrm{e}^\nu=q_{\mathrm{e}i}c\bar{\psi}_i\boldsymbol{\gamma}^\nu\psi_i,
 \label{eq:Je}
\end{equation}
\begin{align}
 T_\mathrm{m}^{\mu\nu} &=\frac{c}{2}P^{\mu\nu,\rho\sigma}[i\hbar\bar{\psi}_i(\boldsymbol{\gamma}_\mathrm{\rho}\vec{\partial}_\sigma-\cev{\partial}_\rho\boldsymbol{\gamma}_\mathrm{\sigma})\psi_i\nonumber\\
 &\hspace{0.4cm}-q_\mathrm{e}\bar{\psi}_i(\boldsymbol{\gamma}_\mathrm{\rho}A_\sigma+A_\rho\boldsymbol{\gamma}_\mathrm{\sigma})\psi_i
 -m_\mathrm{e}c\eta_{\rho\sigma}\bar{\psi}_i\psi_i]\nonumber\\
 &\hspace{0.4cm}+\frac{1}{2\mu_0}P^{\mu\nu,\rho\sigma,\eta\lambda}\partial_\rho A_\sigma\partial_\eta A_\lambda.
\end{align}
Here $q_{\mathrm{e}i}$ is the electric charge of the fermion field of index $i$. Note that, in the presence of the gravitational field, $J_\mathrm{e}^\nu$ is not the total electric four-current density of UG as discussed below.
%in Appendix \ref{apx:J}.




\section{\label{apx:J}Electric four-current density}
\vspace{-0.3cm}

The electric four-current density $J_\mathrm{e}^\nu$ in Eq.~\eqref{eq:Je} is not a conserved quantity in UG in the presence of the gravitational field. Instead, the conserved current associated with the electromagnetic gauge field is calculated as presented below.

The unitary transformation associated with the U(1) gauge symmetry of QED is given by
\begin{equation}
 \psi_i\rightarrow U_\mathrm{e}\psi_i,\hspace{0.5cm}\text{where }U_\mathrm{e}=e^{i\theta Q}.
 \label{eq:U1transformation}
\end{equation}
Here $\theta$ is the real-valued symmetry transformation parameter, and $Q$ is the symmetry transformation generator, which has the value of $Q=-1$ for electrons. The infinitesimal variation of the Dirac field $\psi_i$, in the symmetry transformation of Eq.~\eqref{eq:U1transformation} with respect to the symmetry transformation parameter $\theta$ is given by
\begin{equation}
 \delta\psi_i=iQ_i\psi_i\delta\theta.
 \label{eq:deltapsi}
\end{equation}
Here $Q_i$ is the charge quantum number for the fermion field of index $i$.

Using the infinitesimal variation of the Dirac field in Eq.~\eqref{eq:deltapsi} at zero electromagnetic gauge field, $A^\mu=0$, the variation of the Lagrangian density of UG in Eq.~\eqref{eq:Lagrangian} is written as
\begin{align}
 &\delta\mathcal{L}|_{A=0}\nonumber\\
 &=\frac{i\hbar c}{2}(\delta\bar{\psi}_i)(\boldsymbol{\gamma}^\rho\vec{\partial}_\rho-\cev{\partial}_\rho\boldsymbol{\gamma}^\rho)\psi_i
 +\frac{i\hbar c}{2}\bar{\psi}_i(\boldsymbol{\gamma}^\rho\vec{\partial}_\rho-\cev{\partial}_\rho\boldsymbol{\gamma}^\rho)(\delta\psi_i)\nonumber\\
 &\hspace{0.5cm}-m_\mathrm{e}c^2(\delta\bar{\psi}_i)\psi_i
 -m_\mathrm{e}c^2\bar{\psi}_i(\delta\psi_i)
 -\frac{c}{2}P^{\mu\nu,\rho\sigma}\nonumber\\
 &\hspace{0.5cm}\times[i\hbar(\delta\bar{\psi}_i)(\boldsymbol{\gamma}_\mathrm{\rho}\vec{\partial}_\sigma\!-\!\cev{\partial}_\rho\boldsymbol{\gamma}_\sigma)\psi_i
 \!+\!i\hbar\bar{\psi}_i(\boldsymbol{\gamma}_\mathrm{\rho}\vec{\partial}_\sigma\!-\!\cev{\partial}_\rho\boldsymbol{\gamma}_\sigma)(\delta\psi_i)\nonumber\\
 &\hspace{0.5cm}-m_ic\eta_{\rho\sigma}(\delta\bar{\psi}_i)\psi_i-m_ic\eta_{\rho\sigma}\bar{\psi}_i(\delta\psi_i)]H_{\mu\nu}\nonumber\\
 &=-\hbar Q_ic\bar{\psi}_i(\boldsymbol{\gamma}^\rho
 -P^{\mu\nu,\rho\sigma}\boldsymbol{\gamma}_\sigma H_{\mu\nu})\psi_i\partial_\rho\delta\theta\nonumber\\
 &=-\frac{\hbar}{e}J_\mathrm{e,tot}^\rho\partial_\rho\delta\theta.
 \label{eq:Lvariation}
\end{align}
The last equality of Eq.~\eqref{eq:Lvariation} defines the total conserved electric four-current density of UG, given by
\begin{align}
 J_\mathrm{e,tot}^\rho
 &=q_{\mathrm{e}i}c\bar{\psi}_i(\boldsymbol{\gamma}^\rho
 -P^{\mu\nu,\rho\sigma}\boldsymbol{\gamma}_\sigma H_{\mu\nu})\psi_i\nonumber\\
 &=J_\mathrm{e}^\rho-P^{\mu\nu,\rho\sigma}J_\mathrm{e\sigma}H_{\mu\nu}.
 \label{eq:Jtot}
\end{align}
Here $q_{\mathrm{e}i}=Q_ie$ is the electric charge of the particle. In the last equality of Eq.~\eqref{eq:Jtot}, we have used the conventional definition of the electric four-current density in the absence of the gravity gauge field, given in Eq.~\eqref{eq:Je}.

Substituting the gravity gauge field from Eq.~\eqref{eq:H} into Eq.~\eqref{eq:Jtot}, we obtain after technical summation over repeated indices
\begin{equation}
 J_\mathrm{e,tot}^\rho=J_\mathrm{e}^\rho-\frac{2\Phi}{c^2}\delta_0^\rho J_\mathrm{e}^0.
 \label{eq:Jtot2}
\end{equation}
In the classical limit in the rest frame of the particle, the total conserved electric four-current density in Eq.~\eqref{eq:Jtot2} can be approximated by the Dirac delta function as
\begin{equation}
 J_\mathrm{e,tot}^\rho=q_\mathrm{e}c\delta_0^\rho\delta(\mathbf{r}-\mathbf{r}_0).
 \label{eq:Jtot3}
\end{equation}
The conserved charge is then obtained by integration of $J_\mathrm{e,tot}^0$ over the volume as $\int J_\mathrm{e,tot}^0d^3r=q_\mathrm{e}c$. Using Eq.~\eqref{eq:Jtot3}, we can solve Eq.~\eqref{eq:Jtot2} for $J_\mathrm{e}^\rho$ as
\begin{equation}
 J_\mathrm{e}^\rho=\frac{q_\mathrm{e}c}{1-\frac{2\Phi_0}{c^2}}\delta_0^\rho\delta(\mathbf{r}-\mathbf{r}_0).
 \label{eq:Je2}
\end{equation}
The quantity $J_\mathrm{e}^\rho$ is not the conserved current since, for a particle at rest, the integral of $J_\mathrm{e}^0$ over the volume depends on the position through the Newtonian potential $\Phi_0$ in the prefactor of Eq.~\eqref{eq:Je2}.

Next, we derive the conservation law of the total electric four-current density of UG. The variation of the action integral, i.e., the integral of the Lagrangian density in Eq.~\eqref{eq:Lagrangian} over the volume, with respect to $\theta$ is given for zero electromagnetic four-potential, $A^\mu=0$, by
\begin{align}
 \delta S|_{A=0} &=\int\delta\mathcal{L}|_{A=0}d^4x
 =-\int\frac{\,\hbar}{e}J_\mathrm{e,tot}^\nu\partial_\nu\delta\theta d^4x\nonumber\\
 &=-\int\partial_\nu\Big(\frac{\,\hbar}{e}J_\mathrm{e,tot}^\nu\delta\theta\Big)d^4x
 +\int\partial_\nu\Big(\frac{\hbar}{e}J_\mathrm{e,tot}^\nu\Big)\delta\theta d^4x\nonumber\\
 &=\int\frac{\hbar}{e}\partial_\nu J_\mathrm{e,tot}^\nu\delta\theta d^4x.
 \label{eq:Jeconservation}
\end{align}
In the second equality of Eq.~\eqref{eq:Jeconservation}, we have used Eq.~\eqref{eq:Lvariation}. In the third equality, we have applied integration by parts. In the fourth equality, we have dropped out the total divergence term, which is zero when the fields vanish at the distant boundary. The result of Eq.~\eqref{eq:Jeconservation} shows that the variation of the action integral vanishes for arbitrary $\delta\theta$ when
\begin{equation}
 \partial_\nu J_\mathrm{e,tot}^{\nu}=0.
 \label{eq:Jeconservation1}
\end{equation}
This is the well-known form of the conservation law of the total electric four-current density in the Cartesian Minkowski spacetime \cite{Jackson1999}.







\section{\label{apx:representation}Quantum numbers, spherical harmonic spinors, and radial functions}
\vspace{-0.3cm}

In the eigenstates of the Dirac equation in Eq.~\eqref{eq:psi}, the quantity $j=l\pm\frac{1}{2}$ is the total angular momentum quantum number, where $l=0,1,\ldots,n-1$ is the orbital angular momentum quantum number. The magnetic quantum number $m=-j,-j+1,\ldots,j$ is the total angular momentum projection onto the $z$-axis. The relativistic angular quantum number $\kappa_\mathrm{r}=\pm(j+\frac{1}{2})$ takes all integer values except zero. The positive values of $\kappa_\mathrm{r}$ correspond to the case $j=l-\frac{1}{2}$, and the negative values to the case $j=l+\frac{1}{2}$. The principal quantum number is given by $n=n_\mathrm{r}+j+\frac{1}{2}$. The radial quantum number $n_\mathrm{r}$ takes integer values $n_\mathrm{r}=0,1,2,\ldots$ for $\kappa_\mathrm{r}<0$ and $n_\mathrm{r}=1,2,3,\ldots$ for $\kappa_\mathrm{r}>0$.



In the representation of the Dirac equation eigenstates in Eq.~\eqref{eq:psi}, the functions $\Omega_{j,l,m}(\theta,\phi)$ are the spherical harmonic spinors, defined as \cite{Grant2007,Landau1982}
\begin{equation}
 \Omega_{j,l,m}(\theta,\phi)
 =\sum_{q=-\frac{1}{2}}^{\frac{1}{2}}\langle l,m-q,\textstyle\frac{1}{2},q|j,m\rangle 
Y_{l,m-q}(\theta,\phi)u^{(q)}.
\end{equation}
The terms of this series are formed from the well-known Clebsch-Gordan coefficients $\langle j_1,m_1,j_2,m_2|j_3,m_3\rangle$, the scalar spherical harmonic functions $Y_{l,m}(\theta,\phi)$, and the spherical unit spinors $u^{(q)}$. The spherical unit spinors $u^{(q)}$ are defined as $u^{(-1/2)}=(0,1)$ and $u^{(1/2)}=(1,0)$. For the scalar spherical harmonic functions, we use the definition written in terms of the associated Legendre polynomials $P_{l,m}(x)$ as
\begin{equation} 
Y_{l,m}(\theta,\phi)=\sqrt{\frac{2l+1}{4\pi}\frac{
(l-m)!}{(l+m)!}}\,P_{l,m}(\cos\theta)e^{im\phi}.
\end{equation}
For the associated Legendre polynomials, we use the Condon-Shortley phase 
convention. The associated Legendre polynomials $P_{l,m}(x)$ are then given by
\begin{equation}
 P_{l,m}(x)=
\left\{\begin{array}{l}
(-1)^m(1-x^2)^{m/2}\dfrac{d^m}{dx^m}P_l(x),\hspace{0.5cm}m\ge0,\\
(-1)^{-m}\dfrac{(l+m)!}{(l-m)!}P_{l,-m}(x),\hspace{0.5cm}m<0.      
\end{array}\right.
\end{equation}
Here $P_l(x)$ is the conventional Legendre polynomial of degree $l$, given by the Rodrigues formula as
\begin{equation}
 P_l(x)=\frac{1}{2^l l!}\frac{d^l}{dx^l}(x^2-1)^l.
\end{equation}





In the representation of the Dirac equation eigenstates in Eq.~\eqref{eq:psi}, the radial functions $f_{n_\mathrm{r},\kappa_\mathrm{r}}(r)$ and $g_{n_\mathrm{r},\kappa_\mathrm{r}}(r)$ are given by
\begin{align}
 f_{n_\mathrm{r},\kappa_\mathrm{r}}(r) &=\frac{(2\lambda)^{3/2}}{\Gamma(2\gamma+1)}(2\lambda r)^{\gamma-1}e^{-\lambda r}\nonumber\\
 &\hspace{0.3cm}\times\sqrt{\frac{(C_1m_\mathrm{e}c^2+E_{n_\mathrm{r},\kappa_\mathrm{r}})\Gamma(2\gamma+n_\mathrm{r}+1)}{4C_1m_\mathrm{e}c^2\big(\frac{C_1Z\alpha_\mathrm{e} m_\mathrm{e}c^2}{C_2\lambda\hbar c}\big)\big(\frac{C_1Z\alpha_\mathrm{e} m_\mathrm{e}c^2}{C_2\lambda\hbar c}-\kappa\big)n_\mathrm{r}!}}\nonumber\\
 &\hspace{0.3cm}\times\Big[\Big(\frac{C_1Z\alpha_\mathrm{e} m_\mathrm{e}c^2}{C_2\lambda\hbar c}-\kappa\Big)\;F_{\hspace{-1em}1\hspace{0.7em}1}(-n_\mathrm{r};2\gamma+1;2\lambda r)\nonumber\\
 &\hspace{0.3cm}-n_\mathrm{r}\;\;F_{\hspace{-1em}1\hspace{0.7em}1}(1-n_\mathrm{r};2\gamma+1;2\lambda r)\Big],
 \label{eq:f}
\end{align}
%\pagebreak
\begin{align}
 g_{n_\mathrm{r},\kappa_\mathrm{r}}(r) &=\frac{-(2\lambda)^{3/2}}{\Gamma(2\gamma+1)}(2\lambda r)^{\gamma-1}e^{-\lambda r}\nonumber\\
 &\hspace{0.3cm}\times\sqrt{\frac{(C_1m_\mathrm{e}c^2-E_{n_\mathrm{r},\kappa_\mathrm{r}})\Gamma(2\gamma+n_\mathrm{r}+1)}{4C_1m_\mathrm{e}c^2\big(\frac{C_1Z\alpha_\mathrm{e} m_\mathrm{e}c^2}{C_2\lambda\hbar c}\big)\big(\frac{C_1Z\alpha_\mathrm{e} m_\mathrm{e}c^2}{C_2\lambda\hbar c}-\kappa\big)n_\mathrm{r}!}}\nonumber\\
 &\hspace{0.3cm}\times\Big[\Big(\frac{C_1Z\alpha_\mathrm{e} m_\mathrm{e}c^2}{C_2\lambda\hbar c}-\kappa\Big)\;F_{\hspace{-1em}1\hspace{0.7em}1}(-n_\mathrm{r};2\gamma+1;2\lambda r)\nonumber\\
 &\hspace{0.3cm}+n_\mathrm{r}\;\;F_{\hspace{-1em}1\hspace{0.7em}1}(1-n_\mathrm{r};2\gamma+1;2\lambda r)\Big].
 \label{eq:g}
\end{align}
Here $\Gamma(x)$ is the gamma function, and $\;\,F_{\hspace{-1em}1\hspace{0.7em}1}(a;b;x)$ is the Kummer confluent hypergeometric function. The auxiliary quantities $\lambda$ and $\gamma$ used in the definitions of the radial functions in Eqs.~\eqref{eq:f} and \eqref{eq:g} are given by
\begin{equation}
 \lambda=\frac{\sqrt{C_1^2m_\mathrm{e}^2c^4-E_{n_\mathrm{r},\kappa_\mathrm{r}}^2}}{C_2\hbar c},\hspace{0.5cm}
 \gamma=\sqrt{\kappa_\mathrm{r}^2-(Z\alpha_\mathrm{e})^2}.
\end{equation}



