%     \text{s.t.} \quad &\pi(a_t|s_t,\mu_t) = \mathcal{D}^{\lambda}\left(LLM\left(\phi_D^{\lambda}\left(s_t,\mu_t\right)\right)\right) \ \quad \forall t .
% \end{aligned}
