	\section*{Appendix}\appendix

	\section{Homogeneous RanGEF distribution} 

	The cargo dissociation rate $\beta=\beta_0$ is taken as a constant; assuming that NTR--cargo complexes are found in excess throughout the cell. Also, RanGEF is homogeneously distributed within the nucleus: $\alpha=\alpha_0 = a_0 F_0$, where $F_0$ is the concentration of RanGEF, and $a_0$ is a constant. Under such assumptions, the system of equations becomes linear and thus their solutions are analytically tractable.	In the following, we choose for simplicity that nuclear diffusivity of all Ran species is the same, denoted by $d$. The permeability of RanGDP and NTR--RanGTP is chosen to be the same, denoted by $\lambda$.  

	\subsection{Radial solutions in Laplace space} 

	Provided that the initial conditions for the nuclear concentrations are uniform, their steady-state solutions will remain spherically symmetric as the cytoplasmic concentrations are treated as spatially homogeneous. The nuclear concentration of RanGDP can be described by
	\begin{equation}
		\label{eqn:dyn-A-linear}
		T \frac{\partial A_n}{\partial t} = \frac{1}{r^2}\frac{\partial}{\partial r}\!\left[r^2\frac{\partial A_n}{\partial r}\right]\!- k_{\alpha}  A_n(r,t),
	\end{equation} where $T = R^2/d$ is the diffusion time, the dimensionless nucleotide exchange rate $k_{\alpha} = R^2\alpha_0/d$, and $r\in[0,1]$ is the rescaled radial distance from the center of the cell nucleus ($r=0$). Moreover,  Eq.~(\ref{eqn:dyn-A-linear}) satisfies the following flux boundary condition at the NE ($r=1$):
	\begin{equation}
		\label{eqn:flux-A-linear}
		\frac{\partial A_n}{\partial r}(r\!=\!1,t) = \Lambda \left[A_{c}(t) - A_n(1,t)\right]\!,
	\end{equation} where $\Lambda =  \lambda R/d$. Initially, we consider that RanGDP is not present in the nucleus, that is, $A_n(r,t\!=\!0) = 0$.  The cytoplasmic dynamics of $A_c$ is given by
	\begin{equation}
		\label{eqn:dyn-Ac-linear}	
		T\frac{\partial A_{c}}{\partial t} = k_\eta I_c-3\nu{\Lambda}\left[A_{c}(t) - A_n(1,t)\right]\!,
	\end{equation} where the  dimensionless recycling rate $k_\eta = \eta R^2/d$ and $\nu = \mathcal{V}_n/\mathcal{V}_c$. We set $A_c(t\!=\!0)=A_0$, with $A_0$ as the initial concentration of Ran molecules in the cytoplasm.

	Similarly, the nuclear RanGTP is governed by
	\begin{equation}
		\label{eqn:dyn-B-linear}
		T \frac{\partial B_n}{\partial t} = \frac{1}{r^2}\frac{\partial}{\partial r}\!\left[r^2\frac{\partial B_n}{\partial r}\right]\!+ k_{\alpha} A_n-k_{\beta} B_n,
	\end{equation} where $k_{\beta} = R^2\beta_0/d$ is the dimensionless cargo dissociation rate. The RanGTP is initially absent in the nuclues, that is, $B(r,t\!=\!0)=0$. Furthermore, $B_n$ satisfies a no-flux boundary condition at the NE:
	\begin{equation}
		\label{eqn:flux-B-linear}
		\frac{\partial B_n}{\partial r}(r\!=\!1,t) = 0.
	\end{equation} 

	The concentration of NTR--RanGTP complexes in the nucleus is given by
	\begin{equation}
		\label{eqn:dyn-I-linear}
		T \frac{\partial I_n}{\partial t} = \frac{1}{r^2}\frac{\partial}{\partial r}\!\left[r^2\frac{\partial I_n}{\partial r}\right]\!+k_{\beta}  B_n,
	\end{equation} which satisfies the following boundary condition at NE:
	\begin{equation}
		\label{eqn:flux-I-linear}
		\frac{\partial I_n}{\partial r}(r\!=\!1,t) = \Lambda \left[I_{c}(t) - I_n(1,t)\right]\!,
	\end{equation} and the cytoplasmic concentration $I_c$ is governed by
	\begin{equation}
		\label{eqn:dyn-Ic-linear}	
		T\frac{\partial I_{c}}{\partial t} = -k_\eta I_c-3\nu{\Lambda}\left[I_{c}(t) - I_n(1,t)\right]\!.
	\end{equation} Here, we choose $I_n(r,t\!=\!0) = 0$ and $I_c(t\!=\!0)=0$; thus, all of the Ran molecules are initially in the cytoplasm in the RanGDP-form (at concentration $A_0$).

	The set of equations (\ref{eqn:dyn-A-linear}--\ref{eqn:dyn-Ic-linear}) can be solved by a Laplace transform method, where we define that
	\begin{equation}
		\label{eqn:Laplace-transform-def}
		\hat{X}(s)=\hat{\mathcal{L}_s}[{X}] = \frac{1}{T}\int_{0}^{\infty}\!e^{-st/T}\,X(t)\,\mathrm{d}t, 
	\end{equation} where $X$ denotes any of the concentrations ${A}_n$, ${A}_c$, $B_n$, ${I}_n$, and ${I}_c$. By employing Eq.~(\ref{eqn:Laplace-transform-def}), the nuclear RanGDP equation (\ref{eqn:dyn-A-linear}) can be written as 
	\begin{equation}
		\label{eqn:dyn-A-linear-LT}
		\frac{1}{r^2}\frac{\partial}{\partial r}\!\bigg[r^2\frac{\partial \hat{A}_n}{\partial r}\bigg]\!- (s+k_{\alpha})\hspace{1pt}\hat{A}_n(r,s) = 0,
	\end{equation} and the boundary condition in Eq.~(\ref{eqn:flux-A-linear}) becomes
	\begin{equation}
		\label{eqn:flux-A-linear-LT}
		\frac{\partial \hat{A}_n}{\partial r}(r\!=\!1,s) = \Lambda\,[\hat{A}_{c}(t) - \hat{A}_n(1,s)].
	\end{equation} The cytoplasmic RanGDP equation  Eq.~(\ref{eqn:dyn-Ac-linear}) becomes
	\begin{equation}	
		s\hat{A}_{c}(s)-A_0 = k_\eta \hat{I}_c(s)-3\nu{\Lambda}[\hat{A}_{c}(s) - \hat{A}_n(1,s)], 
	\end{equation} which gives
	\begin{equation}
		\label{eqn:hat-A-c}
		\hat{A}_{c}(s) = \frac{A_0 + k_\eta \hat{I}_c(s)+3\nu{\Lambda}\hat{A}_n(1,s)}{s+3\nu{\Lambda}}.
	\end{equation}

	The solution of Eq.~(\ref{eqn:dyn-A-linear-LT}) can be found to be
	\begin{equation}
		\label{eqn:hat-A-n}
		\hat{A}_n(r,s) = \frac{\mathcal{C}_{\alpha}(s)\sinh(r \mathcal{S}_{\alpha})}{r},
	\end{equation} where $\mathcal{S}_{\alpha} = \sqrt{s+k_{\alpha}}$ and $\mathcal{C}_{\alpha}(s)$ is a function to be prescribed by the boundary condition in Eq.~(\ref{eqn:flux-A-linear-LT}); namely,
	\begin{equation}
		\label{eqn:C_alpha}
		\mathcal{C}_{\alpha}(s) = \frac{\hat{A}_c(s)\hspace{1pt}\Lambda}{ \mathcal{S}_{\alpha}\cosh (\mathcal{S}_{\alpha})-(1-\Lambda)\sinh(\mathcal{S}_{\alpha})}.
	\end{equation} 

	By Laplace transforming Eq.~(\ref{eqn:dyn-B-linear}), the equation of  nuclear RanGTP can be written as 
	\begin{equation}
		\label{eqn:dyn-B-linear-LP}
		\frac{1}{r^2}\frac{\partial}{\partial r}\!\bigg[r^2\frac{\partial \hat{B}_n}{\partial r}\bigg]\!+ k_{\alpha}\hat{A}_n-(s+k_{\beta}) \hat{B}_n = 0,
	\end{equation} and its no-flux boundary condition now reads
	\begin{equation}
		\label{eqn:flux-B-linear-LT}
		\frac{\partial }{\partial r}\hat{B}_n(r\!=\!1,t) = 0.
	\end{equation} 

	Using Eq.~(\ref{eqn:hat-A-c}), the solution of Eq.~(\ref{eqn:dyn-B-linear-LP}) is given by
	\begin{equation}
		\label{eqn:hat-B-n}
		\hat{B}_n(r,s) = \frac{\mathcal{C}_{\beta}(s)\sinh(r \mathcal{S}_{\beta})}{r}+\frac{k_{\alpha}\hspace{1pt}\mathcal{C}_{\alpha}(s)\sinh(r \mathcal{S}_{\alpha})}{r\hspace{1pt}(k_{\beta}-k_{\alpha})},
	\end{equation} where we define $\mathcal{S}_{\beta} = \sqrt{s+k_{\beta}}$, and $\mathcal{C}_{\beta}$ is a function to be found from the boundary condition in Eq.~(\ref{eqn:flux-B-linear-LT}):
	\begin{equation}
		\label{eqn:C_beta}
		\mathcal{C}_{\beta}(s) = \frac{\displaystyle \hat{A}_c(s)\left[\mathcal{S}_{\beta} \cosh \left(\mathcal{S}_{\beta}\right)-\sinh \left(\mathcal{S}_{\beta}\right)\right]^{-1} }{\displaystyle\left(1-\frac{k_{\beta}}{k_{\alpha}}\right)\!\! \left[\frac{1}{\Lambda}-\frac{1}{1-\mathcal{S}_{\alpha} \coth \left(\mathcal{S}_{\alpha}\right)}\right]}.
	\end{equation}

	By Laplace transforming the nuclear NTR--RanGTP equation (\ref{eqn:dyn-I-linear}), we obtain that
	\begin{equation}
		\label{eqn:dyn-I-linear-LP}
		\frac{1}{r^2}\frac{\partial}{\partial r}\!\bigg[r^2\frac{\partial \hat{I}_n}{\partial r}\bigg]\!+ k_{\beta}\hat{B}_n-s\,\hat{I}_n = 0,
	\end{equation} while the boundary condition in Eq.~(\ref{eqn:flux-A-linear}) transforms to
	\begin{equation}
		\label{eqn:flux-I-linear-LT}
		\frac{\partial \hat{I}_n}{\partial r}(r\!=\!1,s) = \Lambda\,[\hat{I}_{c}(t) - \hat{I}_n(1,s)].
	\end{equation} The solution to Eq.~(\ref{eqn:dyn-I-linear-LP}) can be found as follows:
	\begin{align}
		\label{eqn:hat-I-n}
		\hat{I}_n(r,s) &= \frac{\mathcal{C}_{\alpha}(s) k_{\beta} \sinh \left(r \mathcal{S}_{\alpha}\right)}{r \left(k_{\alpha}-k_{\beta}\right)}-\frac{\mathcal{C}_{\beta}(s) \sinh \left(r \mathcal{S}_{\beta}\right)}{r}\notag\\[2pt]
		&\quad+\frac{\mathcal{C}_0(s) \sinh
			\left(r \sqrt{s}\right)}{r},
	\end{align} where $\mathcal{C}_0$ is a function to be determined from the boundary condition in Eq.~(\ref{eqn:flux-I-linear-LT}); namely, we find that
	\begin{equation}
		\label{eqn:C_0}
		\mathcal{C}_0(s) = \frac{\displaystyle \hat{I}_c(s)\hspace{1pt}\Lambda + \hat{A}_c(s)\hspace{1pt}\Lambda  \!\left[1-\frac{1-{\mathcal{X}_{\beta}}/{\mathcal{X}_{\alpha}}}{1-{k_{\beta}}/{k_{\alpha}}}\right]}{(\Lambda -1) \sinh
			\left(\sqrt{s}\right)+\sqrt{s} \cosh \left(\sqrt{s}\right)},
	\end{equation} where we define
	\begin{equation}
		\mathcal{X}_j=\frac{1}{\Lambda}-\frac{1}{1-\mathcal{S}_j \coth \left(\mathcal{S}_j\right)},\quad j\in\{\alpha,\beta\}.
	\end{equation}

	From Eq.~(\ref{eqn:dyn-Ic-linear}), the cytoplasmic concentration of the NTR--RanGTP complex in Laplace space is found to be 
	\begin{equation}
		\label{eqn:hat-I-c}
		\hat{I}_{c}(s) =\frac{3\nu{\Lambda}}{s+k_\eta+3\nu{\Lambda}}\,\hat{I}_n(1,s).
	\end{equation} This equation allows us to obtain $\hat{A}_c(s)$ from Eq.~(\ref{eqn:hat-A-c}), which in turn provides us with exact expressions in the Laplace space for the concentrations $\hat{A}_n(r,s)$, $\hat{B}_n(r,s)$, and $\hat{I}_n(r,s)$ in terms of the initial concentration $A_0$ and the dimensionless parameters $\nu$, $k_{\alpha}$, $k_{\beta}$, $k_\eta$, and $\Lambda$.

	\subsection{Steady-state concentration profiles} 

	The steady-state concentration profiles can be derived by final value theorem for the Laplace transform, which tells us that if the steady-state value exists, then $$\lim_{t\rightarrow\infty} f(t) = \lim_{s\rightarrow0}s\hat{F}(s)$$ where $\hat{F}(s)$ is the Laplace transform of the function $f(t)$, provided that all poles of $s\hat{F}(s)$ are strictly stable or lie in the open left half-plane, $\mathrm{Re}(s)<0$.

	We start by assuming that the steady-state value of the cytoplasmic concentration $A_c(\infty)$ exists and we denote it hereinafter by $\bar{A}_c$. Therefore the steady-state nuclear concentration of RanGDP is given by
	\begin{equation}
		\label{eqn:bar-A-n}
		\bar{A}_n(r) = \frac{\bar{\mathcal{C}}_{\alpha}\sinh(r \sqrt{k_\alpha})}{r},
	\end{equation} where the constant $\bar{\mathcal{C}}_{\alpha}$ is found to be 
	\begin{equation}
		\bar{\mathcal{C}}_{\alpha} = \lim_{s\rightarrow0}s\,\mathcal{C}_{\alpha}(s) = \frac{\bar{A}_c\hspace{1pt}\Lambda\,\mathrm{csch}(\sqrt{k_\alpha})}{ \sqrt{k_\alpha}\coth (\sqrt{k_\alpha})-1+\Lambda},
	\end{equation}  through Eqs.~(\ref{eqn:hat-A-n}) and (\ref{eqn:C_alpha}), where $\bar{A}_c = \lim\limits_{s\rightarrow0}s\hat{A}_c(s)$. 

	Similarly, we find the steady-state of RanGTP concentration in the nucleus, $\bar{B}_n(r)$, from Eq.~(\ref{eqn:hat-B-n}), that is
	\begin{equation}
		\label{eqn:bar-B-n}
		\bar{B}_n(r) = \frac{\bar{\mathcal{C}}_{\beta}\sinh(r \sqrt{k_\beta})}{r}+\frac{k_{\alpha}\hspace{1pt}\bar{\mathcal{C}}_{\alpha}\sinh(r \sqrt{k_\alpha})}{r\hspace{1pt}(k_{\beta}-k_{\alpha})},
	\end{equation} where $\bar{\mathcal{C}}_{\beta}$ is readily found from Eq.~(\ref{eqn:C_beta}) as follows
	\begin{equation}
		\bar{\mathcal{C}}_{\beta} = \frac{\displaystyle \bar{A}_c\!\left[\sqrt{k_\beta} \cosh (\sqrt{k_\beta})-\sinh (\sqrt{k_\beta})\right]^{-1} }{\displaystyle\left(1-\frac{k_{\beta}}{k_{\alpha}}\right)\!\! \left[\frac{1}{\Lambda}-\frac{1}{1-\sqrt{k_\alpha} \coth (\sqrt{k_\alpha})}\right]}.
	\end{equation} 

	Also, the steady-state concentration profile of NTR--RanGTP in the nucleus, $\bar{I}_n(r)$, can be found in a similar way. Using Eqs.~(\ref{eqn:hat-I-n}) and (\ref{eqn:C_0}), we have that
	\begin{equation}
		\label{eqn:bar-I-n}
		\bar{I}_n(r) = \bar{\mathcal{C}}_0 + \frac{\bar{\mathcal{C}}_{\alpha} k_{\beta} \sinh (r \sqrt{k_\alpha})}{r \left(k_{\alpha}-k_{\beta}\right)}-\frac{\bar{\mathcal{C}}_{\beta} \sinh (r \sqrt{k_\beta})}{r},
	\end{equation} where the constant $\bar{\mathcal{C}}_0$ is given by
	\begin{equation}
		\label{eqn:bar-C_0}
		\bar{\mathcal{C}}_0 = \bar{I}_c+ \bar{A}_c \!\left[1-\frac{1-{\bar{\mathcal{X}}_{\beta}}/{\bar{\mathcal{X}}_{\alpha}}}{1-{k_{\beta}}/{k_{\alpha}}}\right]\!,
	\end{equation} with $\bar{I}_c = \lim\limits_{s\rightarrow0}s\hat{I}_c(s)$ and the coefficients 
	\begin{equation}
		\bar{\mathcal{X}}_j=\frac{1}{\Lambda}-\frac{1}{1-\sqrt{k_j} \coth (\sqrt{k_j})},\quad j\in\{\alpha,\beta\}.
	\end{equation} To derive the result in Eq.~(\ref{eqn:bar-C_0}), we use the limits
	\begin{align}
		&\lim\limits_{s\rightarrow0}\frac{\sinh(r\sqrt{s})}{\sqrt{s}} = r, \quad\text{and}\\
		&\lim\limits_{s\rightarrow0}\frac{\sqrt{s}}{(\Lambda -1) \sinh
			\left(\sqrt{s}\right)+\sqrt{s} \cosh \left(\sqrt{s}\right)} = \frac{1}{\Lambda}.
	\end{align}

	From Eq.~(\ref{eqn:hat-I-c}), we obtain that
	\begin{equation}
		\label{eqn:bar-I-c}
		\bar{I}_{c} =\frac{3\nu{\Lambda}}{k_\eta+3\nu{\Lambda}}\,\bar{I}_n(1) = \frac{3\nu \bar{A}_c}{k_\eta\bar{\mathcal{X}}_\alpha}.
	\end{equation} where the last equality follows from Eq.~(\ref{eqn:bar-I-n}). Using final value theorem, Eq.~(\ref{eqn:hat-A-c}) becomes
	\begin{equation}
		\label{eqn:bar-A-c}
		\bar{A}_{c} = \frac{k_\eta \bar{I}_c}{3\nu{\Lambda}}+\bar{A}_n(1).
	\end{equation} This also gives us that
	\begin{equation}
		\bar{A}_n(1) = \bar{A}_c\frac{{\Lambda\bar{\mathcal{X}}_\alpha}\!-\!1}{{\Lambda\bar{\mathcal{X}}_\alpha}} = \frac{\Lambda\bar{A}_c}{\sqrt{k_\alpha}\coth(\sqrt{k_\alpha})\hspace{-1pt}+\hspace{-1pt}\Lambda\hspace{-1pt}-\hspace{-1pt}1},
	\end{equation} which is consistent with Eq.~(\ref{eqn:bar-A-n}) at $r=1$. Moreover, the dimensionless flux of RanGDP at steady-state is 
	\begin{equation}
		\bar{\mathcal{J}}_A \equiv \Lambda\!\left[\bar{A}_{c} -\bar{A}_n(1)\right] = \frac{k_\eta \bar{I}_c}{3\nu}>0,
	\end{equation} which means that RanGDP diffuses into nuclues, while the dimensionless flux of NTR--RanGTP is given by
	\begin{equation}
		\bar{\mathcal{J}}_I \equiv \Lambda\!\left[\bar{I}_{c} -\bar{I}_n(1)\right] = -\frac{k_\eta \bar{I}_c}{3\nu}<0,
	\end{equation} which means that NTR--RanGTP diffuses out of the nucleus. Moreover, this shows that the fluxes must balance identically at steady-state:
	\begin{equation}
		\bar{\mathcal{J}}_A + \bar{\mathcal{J}}_I = 0. 
	\end{equation} 

	To obtain $\bar{A}_c$, we make use the number conservation of particles in the system, as described in the next section.

	\subsection{Nuclear-to-cytoplasmic ratio of molecules} 

	The number of cytoplasmic molecules in the form of RanGDP and NTR--RanGTP at time $t$ are given by 
	\begin{equation}
		\label{eqn:def-c}
		c_A(t) = \mathcal{V}_c\hspace{1pt}A_c(t),\quad\mathrm{and}\quad c_I(t) = \mathcal{V}_c\hspace{1pt} I_c(t),
	\end{equation} respectively, whereas the net number of nuclear RanGDP, $n_A(t)$, RanGTP, $n_B(t)$, and NTR--RanGTP, $n_I(t)$ are given by the integral of their corresponding concentration fields over the entire volume of the nucleus. Specifically, 
	\begin{align}
		\label{eqn:def-n-A}
		n_A(t) &= \int_{\mathcal{V}_n}\mathrm{d}V\,A_n(\boldsymbol{r},t),\\[2pt] 
		\label{eqn:def-n-B}
		n_B(t) &= \int_{\mathcal{V}_n}\mathrm{d}V\,B_n(\boldsymbol{r},t),\\[2pt]  
		\label{eqn:def-n-I}
		n_I(t) &= \int_{\mathcal{V}_n}\mathrm{d}V\,I_n(\boldsymbol{r},t).
	\end{align}


	By integrating over the nuclear volume the equations of $A_n$, $B_n$, and $I_n$, as shown in Eqs.~(2), (3), and (5), and using the divergence theorem and their respective boundary conditions given by Eq.~(1), we find that
	\begin{equation}
		\frac{\partial}{\partial t}\!\left(n_A+n_B+n_I\right) = \int_\mathcal{S}\mathrm{d}S\,\left(\mathcal{J}_A+\mathcal{J}_I\right)\!,
	\end{equation} where $\mathcal{S}$ is the NE. From the cytoplasmic concentration equations, see Eqs.~(7) and (8), we find
	\begin{equation}
		\frac{\partial}{\partial t}\!\left(c_A+c_I\right) = -\int_\mathcal{S}\mathrm{d}S\,\left(\mathcal{J}_A+\mathcal{J}_I\right)\!,
	\end{equation} which shows that the total number of molecules in the system is conserved, that is,
	\begin{equation}
		\label{eqn:conservation-0}
		\frac{\partial}{\partial t}\!\left(n_A+n_B+n_I + c_A+c_I\right) = 0.
	\end{equation} Since initially all of Ran molecules are assumed to be only in their GDP-form within the cytoplasm, with concentration $A_0$, we have that 
	\begin{equation}
		\label{eqn:conservation-1}
		n_A(t)+n_B(t)+n_I(t) + c_A(t)+c_I(t) = A_0\mathcal{V}_c,
	\end{equation} must be satisfied for all time $t$. This includes the steady-state, and therefore we require that
	\begin{equation}
		\label{eqn:conservation-2}
		\bar{n}_A + \bar{n}_B + \bar{n}_I  = \left(A_0 -\bar{A}_c-\bar{I}_c\right)\mathcal{V}_c
	\end{equation} where $\bar{n}_A$, $\bar{n}_B$ and $\bar{n}_I$ are the corresponding steady-state numbers. Using the steady-state concentration profile of nuclear RanGDP, as derived in Eq.~(\ref{eqn:bar-A-n}), we obtain
	\begin{equation}
		\label{eqn:bar-n-A}
		\bar{n}_A = 4\pi R^3\!\int^1_{0} \mathrm{d}r\,r^2\bar{A}_n(r) = \frac{3\hspace{1pt}\mathcal{V}_n\bar{A}_c}{k_\alpha\bar{\mathcal{X}}_\alpha},
	\end{equation}  where we use that $\mathcal{V}_n = 4\pi R^3/3$. Similarly, we can determine the number of nuclear RanGTP molecules at steady-state, which through Eq.~(\ref{eqn:bar-B-n}) yields
	\begin{equation}
		\label{eqn:bar-n-B}
		\bar{n}_B = 4\pi R^3\!\int^1_{0} \mathrm{d}r\,r^2\bar{B}_n(r) = \frac{3\hspace{1pt}\mathcal{V}_n\bar{A}_c}{k_\beta\bar{\mathcal{X}}_\alpha}.
	\end{equation} Note that number ratio of nuclear RanGTP to nuclear RanGDP at steady-state simply reduces to
	\begin{equation}
		\frac{\bar{n}_B}{\bar{n}_A} = \frac{k_\alpha}{k_\beta} = \frac{\alpha_0}{\beta_0}.
	\end{equation} 

	\begin{figure}[t!]\includegraphics[width=\columnwidth]{figure_4.pdf}
	\caption{\label{fig:relaxation-times-fast-diffusion}  Relaxation times $\tilde{\tau}$ associated with each eigenvalue $\tilde{s}$ as function of permeability $\lambda$ for the fast diffusion case. The relaxation time is given by $\tilde{\tau} = -1/\mathrm{Re}(\tilde{s})$, while the frequency of underdamped oscillations is given by $\omega = \mathrm{Im}(\tilde{s})$, which is shown in the inset plot against $\lambda$. Here, we choose $\alpha_0=5\,\mathrm{s}^{-1}$, $\beta_0=0.25\,\mathrm{s}^{-1}$, $\eta=10\,\mathrm{s}^{-1}$, $R=10\,\mu\mathrm{m}$, and $\nu=2/3$.}
`	\end{figure}

	By means of Eq.~(\ref{eqn:bar-I-n}), the total number of nuclear NTR--RanGTP complexes is found to be
	\begin{equation}
		\label{eqn:bar-n-I}
		\bar{n}_I = \bar{\mathcal{C}}_0\mathcal{V}_n-\frac{3\hspace{1pt}\mathcal{V}_n(k_\alpha+k_\beta)\bar{A}_c}{k_\beta k_\alpha \bar{\mathcal{X}}_\alpha},
	\end{equation} where $\bar{\mathcal{C}}_0$ is given by Eq.~(\ref{eqn:bar-C_0}). Using Eqs.~(\ref{eqn:conservation-2}), (\ref{eqn:bar-n-A}), (\ref{eqn:bar-n-B}) and (\ref{eqn:bar-n-I}), we have that
	\begin{equation}
		\label{eqn:conservation-3}
		\nu\hspace{1pt}\bar{\mathcal{C}}_0 +\bar{A}_c + \bar{I}_c = A_0,
	\end{equation} which allows us to determine $\bar{A}_c$ in terms of $A_0$.

	Total nuclear-to-cytoplasmic ratio $\Phi$ of Ran molecules, which is defined by
	\begin{equation}
		\label{eqn:Phi-def}
		\Phi(t) = \frac{n_A(t)+n_B(t)+n_I(t)}{c_A(t)+c_I(t)},
	\end{equation} can be rewritten using Eq.~(\ref{eqn:conservation-1}) as follows:
	\begin{equation}
		\Phi(t) = \frac{A_0}{A_c(t)+I_c(t)}-1.
	\end{equation} Its steady-state, $\bar{\Phi}$, is further simplified using Eq.~(\ref{eqn:conservation-3}):
	\begin{equation}
		\label{eqn:Phi}
		\bar{\Phi} = \hspace{-1pt}\frac{\nu\hspace{1pt}\bar{\mathcal{C}}_0}{\bar{A}_c\hspace{-1pt}+\bar{I}_c}\hspace{-1pt}= \nu  \!\left[1\hspace{-1pt}-\hspace{-1pt}\frac{\bar{\mathcal{X}}_\alpha-\bar{\mathcal{X}}_\beta}{\left(1\hspace{-1pt}-\hspace{-1pt}{k_{\beta}}/{k_{\alpha}}\right)\!\left(\bar{\mathcal{X}}_\alpha\hspace{-1pt}+\hspace{-1pt}{3\nu }/{k_\eta}\right)}\right]
	\end{equation} where in the last equality we use Eq.~(\ref{eqn:C_0}) and (\ref{eqn:bar-I-c}). This also gives us a concise way to express in the steady-state value $\bar{A}_c$ in terms of $A_0$, namely
	\begin{equation}
		\bar{A}_c = \frac{A_0\,\bar{\mathcal{X}}_\alpha}{\left(1+\bar{\Phi}\right)\!\left(\bar{\mathcal{X}}_\alpha+{3\nu}/{k_\eta}\right)}.
	\end{equation} The steady-state value $\bar{I}_c$ becomes
	\begin{equation}
		\bar{I}_c = \frac{ A_0}{\left(1+\bar{\Phi}\right)\!\left[1+k_\eta\bar{\mathcal{X}}_\alpha/{(3\nu)}\right]},
	\end{equation} which shows that $\bar{I}_c$ vanishes in the limit $k_\eta\rightarrow\infty$, as expected; meaning the NTR-RanGTP complexes are instantaneously dissociated as they enter the cytoplasm.

	\subsection{Relaxation times to steady-state} 

	\begin{figure}[t!]\includegraphics[width=\columnwidth]{figure_5.pdf}
	\caption{\label{fig:complex-plane}  Plot of $\hat{A}_c(s)$, with $s$ as a complex variable, where the color shows the $\arg(\hat{A}_c)$. Black and white meshes are contour lines of $\arg(\hat{A}_c)$ and $\log_{10}[\mathrm{abs}(\hat{A}_c)]$, respectively. Black shaded regions show the poles, while white shaded regions are the zeros of the function. The red dashed lines correspond to the poles with the smallest negative real part, which in this case also have a nonzero imaginary part. The white thick lines are branch cuts.  Herein, $\beta_0=0.25\,\mathrm{s}^{-1}\!$, $\alpha_0 =5\,\mathrm{s}^{-1}\!$, $\eta =10\,\mathrm{s}^{-1}\!$, $d=10\,\mu\mathrm{m}^2/\mathrm{s}$, $R=10\,\mu\mathrm{m}$, $\nu=2/3$ and $\lambda=50\,\mu\mathrm{m}/\mathrm{s}$.}
	\end{figure}

	Before computing the corresponding relaxation times of the system to steady-state from the Laplace space solutions in Eqs.~(\ref{eqn:hat-A-c}), (\ref{eqn:hat-A-n}), (\ref{eqn:hat-B-n}), (\ref{eqn:hat-I-n}) and (\ref{eqn:hat-I-c}), it is instructive to calculate the relaxation times for the fast diffusion case ($d\!\rightarrow\!\infty$), which leads to rapid homogenization of nuclear concentrations. In this limit of infinite diffusivity the associated equations take the form: 
	\begin{align}
		\label{eqn:fast-eq1}
		\frac{\partial\hspace{-1pt}\tilde{A}_c}{\partial t} &= \eta \tilde{I}_c - \frac{3\nu\lambda}{R}(\tilde{A}_c-\tilde{A}_n), \\[2pt]
		\frac{\partial\hspace{-1pt}\tilde{A}_n}{\partial t} &= -\alpha_0 \tilde{A}_n + \frac{3\lambda}{R}(\tilde{A}_c-\tilde{A}_n), \\[2pt]
		\frac{\partial\hspace{-1pt}\tilde{B}_n}{\partial t} &= -\beta_0 \tilde{B}_n + \alpha_0 \tilde{A}_n, \\[2pt]
		\frac{\partial\hspace{-0.5pt}\tilde{I}_n}{\partial t} &= \beta_0 \tilde{B}_n + \frac{3\lambda}{R}(\tilde{I}_c-\tilde{I}_n),\\[2pt]
		\frac{\partial\hspace{-0.5pt}\tilde{I}_c}{\partial t} &\label{eqn:fast-eq5}
		= -\eta \tilde{I}_c - \frac{3\nu\lambda}{R}(\tilde{I}_c-\tilde{I}_n),
	\end{align} where $\tilde{A}_c$ and $\tilde{A}_n$ denote the cytoplasmic and nuclear RanGDP concentrations; $\tilde{B}_n$ is the nuclear RanGTP concentration; while $\tilde{I}_c$ and $\tilde{I}_n$ denote the cytoplasmic and nuclear NTR--RanGTP concentrations. Notice that $\tilde{A}_n$, $\tilde{B}_n$ and $\tilde{I}_n$ are not functions of space here, representing mean concentrations defined over the whole nucleus. 	

	\begin{figure}[t!]\includegraphics[width=\columnwidth]{figure_6.pdf}
		\caption{\label{fig:error-relaxation-times}  Relative increase of the dominant relaxation time $\tau$ compared to  $\tilde{\tau}$ in the fast diffusion case; namely,  $\mathcal{E}_\tau=\tau/\tilde{\tau}-1$.  We vary $\lambda$ at two values of $\beta_0$, with $\alpha_0 =5\,\mathrm{s}^{-1}\!$, $\eta =10\,\mathrm{s}^{-1}\!$, $\nu=2/3$, $d=10\,\mu\mathrm{m}^2/\mathrm{s}$, and $R=10\,\mu\mathrm{m}$.}
	\end{figure}

	This linear set of equations can be written as follows:
	\begin{equation}
		\frac{\partial\boldsymbol{\tilde{C}}}{\partial t} = \boldsymbol{M} \boldsymbol{\tilde{C}}
	\end{equation} where $\boldsymbol{\tilde{C}} = \hspace{-1pt}\big[\tilde{A}_c,\,\tilde{A}_n,\,\tilde{B}_n, \,\tilde{I}_n,\,\tilde{I}_c\hspace{1pt}\big]^{\mathsf{T}}$ and  $\boldsymbol{M}$ is given by
	\begin{equation}
		\boldsymbol{M}\hspace{-1pt}=\hspace{-2pt}
		\left[
		\begin{array}{ccccc}
			-\frac{3 \lambda  \nu }{R} & \frac{3 \lambda  \nu }{R} & 0 & 0 &
			\eta  \\[5pt]
			\frac{3 \lambda }{R} & -\alpha _0\hspace{-1pt}-\hspace{-1pt}\frac{3 \lambda }{R} & 0 & 0 & 0
			\\[5pt]
			0 & \alpha _0 & -\beta _0 & 0 & 0 \\[5pt]
			0 & 0 & \beta _0 & -\frac{3 \lambda }{R} & \frac{3 \lambda }{R} \\[5pt]
			0 & 0 & 0 & \frac{3 \lambda  \nu }{R} & -\eta\hspace{-1pt}-\hspace{-1pt}\frac{3 \lambda  \nu
			}{R} \\[5pt]
		\end{array}
		\right]\!.
	\end{equation} The relaxation times of the system to steady-state can be computed from the eigenvalues $\tilde{s}$ of matrix $\boldsymbol{M}$; namely, $\det(\boldsymbol{M}-\tilde{s}\boldsymbol{I}) = 0$, which shows that one of the eigenvalues is zero, while the other are given by roots of the following polynomial equation:  
	\begin{equation}
		\label{eqn:eigenvalues-fast-diffusion}
		\tilde{s}^4 + r_3\,\tilde{s}^3+r_2\,\tilde{s}^2+ r_1\,\tilde{s}+r_0 = 0, 
	\end{equation} where $r_j$ are constants ($j\in\{0,1,2,3\}$) that can be  computed in terms of $\alpha_0$, $\beta_0$, $\eta$, $\nu$, $\lambda$, and $R$. The real part of all non-zero eigenvalues are negative, from which the relaxation times $\tilde{\tau} = -1/\mathrm{Re}(\tilde{s})$ can be computed; as shown in Fig~2(a) and Fig.~\ref{fig:relaxation-times-fast-diffusion}. The imaginary part of the dominant eigenvalues can become nonzero as we vary the permeability $\lambda$, as shown in the inset plot of Fig.~\ref{fig:relaxation-times-fast-diffusion}. 

	In the limit of rapid GTP hydrolysis rate ($\eta\rightarrow\infty$) as well as fast nucleotide exchange ($\alpha_0\rightarrow\infty$), the system of Eqs.~(\ref{eqn:fast-eq1}--\ref{eqn:fast-eq5}) reduces to a simpler three-dimensional system in terms of only cytoplasmic RanGDP, nuclear RanGTP, and nuclear NTR--RanGTP; namely,
	\begin{align}
		\label{eqn:reduced-fast-eq1}
		\frac{\partial\hspace{-1pt}\tilde{A}_c}{\partial t} &= \frac{3\nu\lambda}{R}\tilde{I}_n - \frac{3\nu\lambda}{R}(\tilde{A}_c-\tilde{A}_n), \\[2pt]
		\frac{\partial\hspace{-1pt}\tilde{B}_n}{\partial t} &= -\beta_0 \tilde{B}_n + \frac{3\lambda}{R}(\tilde{A}_c-\tilde{A}_n), \\[2pt]
		\frac{\partial\hspace{-0.5pt}\tilde{I}_n}{\partial t} &\label{eqn:reduced-fast-eq3}
		= \beta_0 \tilde{B}_n - \frac{3\lambda}{R}\tilde{I}_n.
	\end{align} The characteristic polynomial equation in Eq.~(\ref{eqn:eigenvalues-fast-diffusion}) now reduces to
	\begin{equation}
		\label{eqn:eigenvalues-fast-diffusion-reduced}
		\tilde{s}^2\! +\tilde{s}\,\frac{3\lambda  (\nu\!+\!1)\!+\!\beta_0 R}{R}\!+\!\frac{3 \lambda\hspace{-1pt}\left[3 \nu \lambda\!+\!\beta_0 R\!\left(\nu\!+\!1\right) \right]}{R^2}\!= 0,
	\end{equation} which allows us to determine in exact form the solution of the eigenvalues $\tilde{s}$. The imaginary part of $\tilde{s}$ is nonzero when the discriminant of Eq.~(\ref{eqn:eigenvalues-fast-diffusion-reduced}) becomes negative, namely we require $\lambda$ to be in the range
	\begin{equation}
		\frac{\beta _0 R}{3 \left(\sqrt{\nu }-1\right)^2}>\lambda >\frac{\beta _0 R}{3
			\left(\sqrt{\nu }+1\right)^2},\;\,\text{with }\nu\neq1,
	\end{equation} or $\lambda>\beta_0R/12$ when ratio $\nu=1$. This shows that the onset of the oscillation occurs at higher values of $\lambda$ as we increase the rate $\beta_0$; see Fig.~\ref{fig:figure_2}(a).


	We now turn back to case when diffusivity $d$ is finite. To obtain the relaxation times in this case from the associated Laplace solutions in Eqs.~(\ref{eqn:hat-A-c}), (\ref{eqn:hat-A-n}), (\ref{eqn:hat-B-n}), (\ref{eqn:hat-I-n}) and (\ref{eqn:hat-I-c}), we need to locate the complex  poles of functions that have negative real part. Note that the pole at $s=0$ corresponds to the steady-state solutions found previously through the final value theorem.  Since the solutions of $\hat{A}_n$, $\hat{B}_n$, $\hat{I}_n$, and $\hat{I}_c$ are all linearly related to $\hat{A}_c$, then the position of their poles is the same for each of them. The dominant relaxation time $\tau$ is given by 
	\begin{equation}
		\tau = -1/\mathrm{Re}(s^{\star}),
	\end{equation} where $s^\star$ is the pole with the smallest and strictly negative real part, as shown in Fig.~\ref{fig:complex-plane}. By numerically tracking the position of the pole $s^\star$ as function of $\lambda$, the transition from an over-damped decay, with $\mathrm{Im}(s^{\star}) = 0$, to an under-damped decay, where $\mathrm{Im}(s^\star) \neq 0$, can be seen as we increase the permeability; see Fig.~\ref{fig:figure_2}(a). By comparing the dominant relaxation time $\tilde{\tau}$ in the fast diffusion case with $\tau$, we find that a significant relative increase, (defined by $\mathcal{E}_\tau = {\tau}/\tilde{\tau}-1$) at large values of the nuclear pore permeability $\lambda$, as shown in Fig.~\ref{fig:error-relaxation-times}.

	\section{Non-homogeneous RanGEF} 

	Here we consider that distribution of the RanGEF is not uniform within the nucleus, with the nucleotide exchange rate $\alpha(r)$ being a function of the radial distance. For simplicity, we  assume that $\alpha$ is a piecewise constant function. We consider two extreme cases; first, all of the RanGEF is distributed within a spherical ball of radius $R\hspace{1pt}\varepsilon$ at the center of the nucleus; and second, all of the RanGEF is localized in a spherical shell at the nuclear envelope of thickness $R\hspace{1pt}(1-\delta)$. We study how the steady-state concentrations of each molecular species, as well as their corresponding total number, is affected by the non-homogeneous distribution of RanGEF.\\
	%
	%
	\indent 
	In the case where all of the RanGEF is located in a spherical ball at the center of the nucleus, the nucleotide exchange rate for Ran is a piecewise constant function: 
	\begin{equation}
		\alpha_\mathrm{ball}(r) = \begin{cases} \,a_0 F_\mathrm{ball} & 0<r\leq\varepsilon, \\[2pt] \,0 & \varepsilon<r< 1,\end{cases}
	\end{equation} where $a_0$ is a constant, and $F_\mathrm{ball}$ is the RanGEF concentration within the ball. Thus, we need to solve the nuclear equations (\ref{eqn:dyn-A-linear}), (\ref{eqn:dyn-B-linear}) and (\ref{eqn:dyn-I-linear}) on two separate domains, using matching boundary conditions at $r=\varepsilon$; namely, we demand that concentration and its derivative are continuous at $r=\varepsilon$.\\
	%
	%
	\indent 
	Similarly, in the case where the RanGEF is distributed only in a shell near the nuclear boundary, the nucleotide exchange rate is given by  
	\begin{equation}
		\alpha_\mathrm{shell}(r) = \begin{cases} \,0 & 0<r\leq 1-\delta, \\[2pt] \,a_0 F_\mathrm{shell} & 1-\delta<r< 1,\end{cases}
	\end{equation} where $F_\mathrm{shell}$ is the RanGEF concentration in the shell. Thus, a continuity boundary condition is imposed at the radial position $r=1-\delta$ where the concentrations and their derivatives are continuous.\\
	%
	%
	\indent  
	To directly compare with the previous case of homogeneous RanGEF throughout the whole nucleus, we demand that the RanGEF number is the same in both cases: 
	$\frac{4}{3}\pi R^3(1 - \delta^3)F_\mathrm{shell} = \frac{4}{3}\pi R^3 F_0$, which gives
	\begin{equation}
		\alpha_\mathrm{shell}(r) = \begin{cases} \,0 & 0<r\leq 1-\delta, \\[2pt] \,\alpha_0/(1-\delta^3) & 1-\delta<r< 1,\end{cases}
	\end{equation} where $\alpha_0=a_0 F_0$, being the same as the rate defined previously in Appendix~A. Similarly, we demand the number of RanGEF to be the same in the ball as in the entirely uniform case:  $\frac{4}{3}\pi R^3\varepsilon^3 F_\mathrm{ball} = \frac{4}{3}\pi R^3 F_0$. Hence,
	\begin{equation}
		\alpha_\mathrm{ball}(r) = \begin{cases} \,\alpha_0 /\varepsilon^3 & 0<r\leq\varepsilon, \\[2pt] \,0 & \varepsilon<r< 1.\end{cases}
	\end{equation}
	%
	Given these two static distributions for RanGEF, the steady-state solutions for the concentrations of RanGDP, RanGTP, and NTR--RanGTP can be determined in exact form and compared against the entirely uniform case; see concentration profiles in Fig.~\ref{fig:figure_2}(b).
	%
	\subsection{Steady-state profiles --- the shell case}
	%
	Using Eq.~(\ref{eqn:dyn-A-linear}), the steady-state equation for nuclear RanGDP can be written as follows:
	\begin{equation}
		\begin{cases} 
			\frac{1}{r^2}\frac{\partial}{\partial r}\!\left[r^2\frac{\partial \bar{A}^{\mathrm{so}}_n}{\partial r}\right]\!=0,
			& 0<r\leq1\!-\!\delta, \\[8pt] 
			\frac{1}{r^2}\frac{\partial}{\partial r}\!\left[r^2\frac{\partial \bar{A}^{\mathrm{si}}_n}{\partial r}\right]\!= k^{\hspace{0.5pt}\mathrm{s}}_{\alpha}  \bar{A}^{\mathrm{si}}_n,
			& 1\!-\!\delta<r\leq 1.\end{cases}
	\end{equation} where $k^{\hspace{0.5pt}\mathrm{s}}_{\alpha} = R^2\alpha_0/[d(1-\delta^3)]$, while $\bar{A}_n^{\mathrm{si}}$ and $\bar{A}_n^{\mathrm{so}}$ denote the concentrations inside and outside the shell, respectively. The nontrivial solution of $\bar{A}_n^{\mathrm{si}}$ is found to be
	\begin{equation}
		\bar{A}_n^{\mathrm{si}}(r) = \frac{c^{\hspace{0.5pt}\mathrm{s}}_1 \cosh(r\sqrt{k^{\hspace{0.5pt}\mathrm{s}}_\alpha})+c^{\hspace{0.5pt}\mathrm{s}}_2 \sinh(r\sqrt{k^{\hspace{0.5pt}\mathrm{s}}_\alpha})}{r},
	\end{equation} while $\bar{A}_n^{\mathrm{so}} = c^{\hspace{0.5pt}\mathrm{s}}_3$, where $c^{\hspace{0.5pt}\mathrm{s}}_1$, $c^{\hspace{0.5pt}\mathrm{s}}_2$ and $c^{\,\mathrm{s}}_3$ are constants to be determined from the boundary conditions; namely,
	\begin{align}
		&\bar{A}_n^{\mathrm{si}}(1-\delta) = \bar{A}_n^{\mathrm{so}}(1-\delta),\\[5pt]	
		&\frac{\partial\hspace{-1pt}\bar{A}_n^{\mathrm{si}}}{\partial r}(1-\delta) = 	\frac{\partial\hspace{-1pt}\bar{A}_n^{\mathrm{so}}}{\partial r}(1-\delta),\\[5pt]	
		& \frac{\partial\hspace{-1pt}\bar{A}^{\mathrm{si}}_n}{\partial r}(1) = \Lambda\! \left[\bar{A}^{\mathrm{s}}_{c} - \bar{A}^{\mathrm{si}}_n(1)\right]\!,
	\end{align} where $\bar{A}^{\mathrm{s}}_{c}$ is the cytoplasmic concentration of RanGDP at steady-state for the shell case. 

	By Eq.~(\ref{eqn:dyn-B-linear}), the steady-state equation for nuclear concentration of RanGTP is given by
	\begin{equation}
		\begin{cases} 
			\frac{1}{r^2}\frac{\partial}{\partial r}\!\left[r^2\frac{\partial \bar{B}^{\mathrm{so}}_n}{\partial r}\right]\!=k_\beta \bar{B}^{\mathrm{so}}_n,
			& 0<r\leq1\!-\!\delta, \\[8pt] 
			\frac{1}{r^2}\frac{\partial}{\partial r}\!\left[r^2\frac{\partial \bar{B}^{\mathrm{si}}_n}{\partial r}\right]\!= k_\beta \bar{B}^{\mathrm{si}}_n\!-k^{\,\mathrm{s}}_{\alpha}  \bar{A}^{\mathrm{si}}_n,
			& 1\!-\!\delta<r\leq 1,\end{cases}
	\end{equation} where $k_{\beta} = R^2\beta_0/d$. Similarly, $\bar{B}^{\mathrm{si}}_n$ and $\bar{B}^{\mathrm{so}}_n$ denote the concentrations of RanGTP inside and outside the shell, respectively. The solution of $\bar{B}^{\mathrm{si}}_n$ is given by
	\begin{align}
		\bar{B}^{\mathrm{si}}_n(r) &=  \frac{c^{\,\mathrm{s}}_1 k_\alpha^{\,\mathrm{s}}\cosh(r\sqrt{k^{\,\mathrm{s}}_\alpha})+c^{\,\mathrm{s}}_2k_\alpha^{\,\mathrm{s}} \sinh(r\sqrt{k^{\,\mathrm{s}}_\alpha})}{r(k_\beta-k^{\,\mathrm{s}}_\alpha)}\notag\\[6pt] 
		&\quad+\frac{c^{\,\mathrm{s}}_4\cosh(r\sqrt{k^{\,\mathrm{s}}_\alpha})+c^{\,\mathrm{s}}_5 \sinh(r\sqrt{k^{\,\mathrm{s}}_\alpha})}{r},
	\end{align} while the solution of $\bar{B}^{\mathrm{so}}_n$ is found to be
	\begin{align}
		\bar{B}^{\mathrm{so}}_n(r) = \frac{c^{\,\mathrm{s}}_6\sinh(r\sqrt{k_\beta})}{r},
	\end{align} where $c^{\,\mathrm{s}}_4$, $c^{\,\mathrm{s}}_5$ and $c^{\,\mathrm{s}}_6$ are constants to be determined from
	\begin{align}
		&\bar{B}_n^{\mathrm{si}}(1-\delta) = \bar{B}_n^{\mathrm{so}}(1-\delta),\\[5pt]	
		&\frac{\partial\hspace{-1pt}\bar{B}_n^{\mathrm{si}}}{\partial r}(1-\delta) = 	\frac{\partial\hspace{-1pt}\bar{B}_n^{\mathrm{so}}}{\partial r}(1-\delta),\\[5pt]	
		& \frac{\partial\hspace{-1pt}\bar{B}^{\mathrm{si}}_n}{\partial r}(1) = 0.
	\end{align}

