	Using Eq.~(\ref{eqn:dyn-I-linear}), the steady-state equation for nuclear NTR--RanGTP concentration becomes
	\begin{equation}
		\begin{cases} 
			\frac{1}{r^2}\frac{\partial}{\partial r}\!\left[r^2\frac{\partial \bar{I}^{\mathrm{so}}_n}{\partial r}\right]\!= -k_\beta \bar{B}^{\mathrm{so}}_n,
			& 0<r\leq1\!-\!\delta, \\[8pt] 
			\frac{1}{r^2}\frac{\partial}{\partial r}\!\left[r^2\frac{\partial \bar{I}^{\mathrm{si}}_n}{\partial r}\right]\!= -k_\beta \bar{B}^{\mathrm{si}}_n,
			& 1\!-\!\delta<r\leq 1,\end{cases}
	\end{equation} where $\bar{I}^{\mathrm{si}}_n$ and $\bar{I}^{\mathrm{so}}_n$ are the nuclear NTR--RanGTP concentrations inside and outside the shell. We find
	\begin{align}
		\!\bar{I}^{\mathrm{si}}_n(r) &=  \frac{c^{\,\mathrm{s}}_7}{r}+c^{\,\mathrm{s}}_8 -\frac{c^{\,\mathrm{s}}_4\cosh(r\sqrt{k^{\,\mathrm{s}}_\alpha})+c^{\,\mathrm{s}}_5 \sinh(r\sqrt{k^{\,\mathrm{s}}_\alpha})}{r} \notag\\[6pt] 
		&\quad+\frac{c^{\,\mathrm{s}}_1 k_\beta\cosh(r\sqrt{k^{\,\mathrm{s}}_\alpha})+c^{\,\mathrm{s}}_2 k_\beta \sinh(r\sqrt{k^{\,\mathrm{s}}_\alpha})}{r(k^{\,\mathrm{s}}_\alpha-k_\beta)},
	\end{align} while the outer solution $\bar{I}^{\mathrm{so}}_n$ is given by
	\begin{equation}
		\bar{I}^{\mathrm{so}}_n(r) = c^{\,\mathrm{s}}_9 - \frac{c^{\,\mathrm{s}}_6\sinh(r\sqrt{k_\beta})}{r},
	\end{equation} where the constants $c^{\,\mathrm{s}}_7$, $c^{\,\mathrm{s}}_8$ and $c^{\,\mathrm{s}}_9$ are found by imposing:
	\begin{align}
		&\bar{I}_n^{\mathrm{si}}(1-\delta) = \bar{I}_n^{\mathrm{so}}(1-\delta),\\[5pt]	
		&\frac{\partial\hspace{-1pt}\bar{I}_n^{\mathrm{si}}}{\partial r}(1-\delta) = 	\frac{\partial\hspace{-1pt}\bar{I}_n^{\mathrm{so}}}{\partial r}(1-\delta),\\[5pt]	
		& \frac{\partial\hspace{-1pt}\bar{I}^{\mathrm{si}}_n}{\partial r}(1) = \Lambda \!\left[\bar{I}^{\mathrm{s}}_{c} - \bar{I}^{\mathrm{si}}_n(1)\right]\!,
	\end{align} where $\bar{I}^{\mathrm{s}}_n$ is the cytoplasmic concentration at steady-state of NTR--RanGTP molecules. From Eq.~(\ref{eqn:dyn-Ic-linear}), the steady-state value of $\bar{I}^{\mathrm{s}}_n$ can be written as follows:
	\begin{equation}
		\bar{I}^{\mathrm{s}}_{c}= \frac{3\nu \Lambda}{k_\eta + 3\nu \Lambda}\,\bar{I}^{\mathrm{si}}_n(1).
	\end{equation} This allows us to find the constants $c^{\,\mathrm{s}}_j$, $j\in\{1,2,\dots,9\}$, in terms of the unknown steady-state value of $\bar{A}^{\mathrm{s}}_c$, and the dimensionless parameters $k_\alpha^{\hspace{0.5pt}\mathrm{s}}$, $k_\beta$, $k_\eta$, $\nu$, $\Lambda$, and $\delta$. The steady-state $\bar{A}^{\mathrm{s}}_c$ is found  by imposing the conservation of the net number of molecules in the cell, as in Eq.~(\ref{eqn:conservation-2}).  


