	\subsection{Steady-state profiles --- the ball case}


	From Eq.~(\ref{eqn:dyn-A-linear}), the steady-state equation for nuclear RanGDP is given by
	\begin{equation}
		\begin{cases} 
			\frac{1}{r^2}\frac{\partial}{\partial r}\!\left[r^2\frac{\partial \bar{A}^{\mathrm{bo}}_n}{\partial r}\right]\!=0,
			& \varepsilon<r\leq1, \\[8pt] 
			\frac{1}{r^2}\frac{\partial}{\partial r}\!\left[r^2\frac{\partial \bar{A}^{\mathrm{bi}}_n}{\partial r}\right]\!= k^{\hspace{0.5pt}\mathrm{b}}_{\alpha}  \bar{A}^{\mathrm{bi}}_n,
			& 0<r\leq\varepsilon.\end{cases}
	\end{equation} where $k^{\hspace{0.5pt}\mathrm{b}}_{\alpha} = R^2\alpha_0/(d\hspace{0.5pt}\varepsilon^3)$, whilst $\bar{A}_n^{\mathrm{bi}}$ and $\bar{A}_n^{\mathrm{bo}}$ are the concentrations inside and outside the spherical ball, respectively. The solution of $\bar{A}_n^{\mathrm{bi}}$ is found to be
	\begin{equation}
		\bar{A}_n^{\mathrm{bi}}(r) = \frac{c^{\hspace{0.5pt}\mathrm{b}}_1 \sinh(r\sqrt{k^{\hspace{0.5pt}\mathrm{b}}_\alpha})}{r},
	\end{equation} while the solution of $\bar{A}_n^{\mathrm{bo}}$ is given by
	\begin{equation}
		\bar{A}_n^{\mathrm{bo}}(r) = \frac{c^{\hspace{0.5pt}\mathrm{b}}_2}{r}+ c^{\hspace{0.5pt}\mathrm{b}}_3,
	\end{equation} where $c^{\hspace{0.5pt}\mathrm{b}}_1$, $c^{\hspace{0.5pt}\mathrm{b}}_2$ and $c^{\,\mathrm{b}}_3$ are constants to be determined from:
	\begin{align}
		&\bar{A}_n^{\mathrm{bi}}(\varepsilon) = \bar{A}_n^{\mathrm{bo}}(\varepsilon),\\[5pt]	
		&\frac{\partial\hspace{-1pt}\bar{A}_n^{\mathrm{bi}}}{\partial r}(\varepsilon) = 	\frac{\partial\hspace{-1pt}\bar{A}_n^{\mathrm{bo}}}{\partial r}(\varepsilon),\\[5pt]	
		& \frac{\partial\hspace{-1pt}\bar{A}^{\mathrm{bo}}_n}{\partial r}(1) = \Lambda\! \left[\bar{A}^{\mathrm{b}}_{c} - \bar{A}^{\mathrm{bo}}_n(1)\right]\!,
	\end{align} where $\bar{A}^{\mathrm{b}}_{c}$ is the steady-state value of the cytoplasmic concentration of RanGDP in the ball case.


	By Eq.~(\ref{eqn:dyn-B-linear}), the steady-state equation for nuclear concentration of RanGTP is given by
	\begin{equation}
		\begin{cases} 
			\frac{1}{r^2}\frac{\partial}{\partial r}\!\left[r^2\frac{\partial \bar{B}^{\mathrm{bo}}_n}{\partial r}\right]\!=k_\beta \bar{B}^{\mathrm{bo}}_n,
			& \varepsilon<r\leq1, \\[8pt] 
			\frac{1}{r^2}\frac{\partial}{\partial r}\!\left[r^2\frac{\partial \bar{B}^{\mathrm{bi}}_n}{\partial r}\right]\!= k_\beta \bar{B}^{\mathrm{bi}}_n\!-k^{\,\mathrm{b}}_{\alpha}  \bar{A}^{\mathrm{bi}}_n,
			& 0<r\leq\varepsilon,\end{cases}
	\end{equation} where $\bar{B}^{\mathrm{bi}}_n$ and $\bar{B}^{\mathrm{bo}}_n$ are the concentrations of RanGTP inside and outside the ball, respectively. We find that
	\begin{align}
		\bar{B}^{\mathrm{bi}}_n(r) &=  \frac{c^{\hspace{0.5pt}\mathrm{b}}_4\sinh(r\sqrt{k_\beta})}{r}+\frac{c^{\hspace{0.5pt}\mathrm{b}}_1 k^{\hspace{0.5pt}\mathrm{b}}_\alpha \sinh(r\sqrt{k^{\hspace{0.5pt}\mathrm{b}}_\alpha})}{r(k_\beta-k^{\hspace{0.5pt}\mathrm{b}}_\alpha)},\\[5pt]
		\bar{B}^{\mathrm{so}}_n(r) &= \frac{c^{\,\mathrm{b}}_5\cosh(r\sqrt{k_\beta})+c^{\,\mathrm{b}}_6\sinh(r\sqrt{k_\beta})}{r},
	\end{align} where $c^{\,\mathrm{b}}_4$, $c^{\,\mathrm{b}}_5$ and $c^{\,\mathrm{b}}_6$ are constants to be determined from
	\begin{align}
		&\bar{B}_n^{\mathrm{bi}}(\varepsilon) = \bar{B}_n^{\mathrm{bo}}(\varepsilon),\\[5pt]	
		&\frac{\partial\hspace{-1pt}\bar{B}_n^{\mathrm{bi}}}{\partial r}(\varepsilon) = 	\frac{\partial\hspace{-1pt}\bar{B}_n^{\mathrm{bo}}}{\partial r}(\varepsilon),\\[5pt]	
		& \frac{\partial\hspace{-1pt}\bar{B}^{\mathrm{bo}}_n}{\partial r}(1) = 0.
	\end{align}

	Using Eq.~(\ref{eqn:dyn-I-linear}), we write 
	\begin{equation}
		\begin{cases} 
			\frac{1}{r^2}\frac{\partial}{\partial r}\!\left[r^2\frac{\partial \bar{I}^{\mathrm{bo}}_n}{\partial r}\right]\!= -k_\beta \bar{B}^{\mathrm{bo}}_n,
			& \varepsilon<r\leq1, \\[8pt] 
			\frac{1}{r^2}\frac{\partial}{\partial r}\!\left[r^2\frac{\partial \bar{I}^{\mathrm{bi}}_n}{\partial r}\right]\!= -k_\beta \bar{B}^{\mathrm{bi}}_n,
			& 0<r\leq\varepsilon,\end{cases}
	\end{equation} where $\bar{I}^{\mathrm{bi}}_n$ and $\bar{I}^{\mathrm{bo}}_n$ are nuclear NTR--RanGTP concentrations inside and outside the ball. Their solutions are
	\begin{align}
		\!\bar{I}^{\mathrm{bi}}_n\!&=  c^{\,\mathrm{b}}_7 -\frac{c^{\hspace{0.5pt}\mathrm{b}}_4\hspace{-1pt}\sinh(r\sqrt{k_\beta})}{r}+\frac{c^{\hspace{0.5pt}\mathrm{b}}_1 k_\beta \hspace{-1pt}\sinh(r\sqrt{k^{\hspace{0.5pt}\mathrm{b}}_\alpha})}{r(k^{\hspace{0.5pt}\mathrm{b}}_\alpha-k_\beta)},\\[5pt]
		\bar{I}^{\mathrm{so}}_n\!&=  c^{\,\mathrm{b}}_9\! -\!\frac{c^{\,\mathrm{b}}_8\! +\!c^{\,\mathrm{b}}_5\hspace{-1pt}\cosh(r\sqrt{k_\beta})\!+\!c^{\,\mathrm{b}}_6\hspace{-1pt}\sinh(r\sqrt{k_\beta})}{r},
	\end{align} where $c^{\,\mathrm{b}}_7$, $c^{\,\mathrm{b}}_8$ and $c^{\,\mathrm{b}}_9$ are found from the conditions:
	\begin{align}
		&\bar{I}_n^{\mathrm{bi}}(\varepsilon) = \bar{I}_n^{\mathrm{bo}}(\varepsilon),\\[5pt]	
		&\frac{\partial\hspace{-1pt}\bar{I}_n^{\mathrm{bi}}}{\partial r}(\varepsilon) = 	\frac{\partial\hspace{-1pt}\bar{I}_n^{\mathrm{bo}}}{\partial r}(\varepsilon),\\[5pt]	
		& \frac{\partial\hspace{-1pt}\bar{I}^{\mathrm{bo}}_n}{\partial r}(1) = \Lambda \!\left[\bar{I}^{\mathrm{b}}_{c} - \bar{I}^{\mathrm{bo}}_n(1)\right]\!,
	\end{align} where $\bar{I}^{\mathrm{b}}_{c}$ is the steady-state cytoplasmic concentration of NTR--RanGTP complexes, which via Eq.~(\ref{eqn:dyn-Ic-linear}) becomes
	\begin{equation}
		\bar{I}^{\mathrm{b}}_{c}= \frac{3\nu \Lambda}{k_\eta + 3\nu \Lambda}\,\bar{I}^{\mathrm{bo}}_n(1).
	\end{equation} This allows us to determine $c^{\,\mathrm{b}}_j$, $j\in\{1,2,\dots,9\}$, in terms of $\bar{A}^{\mathrm{b}}_c$. The latter is found  by imposing the conservation of the net number of molecules in the cell, as in Eq.~(\ref{eqn:conservation-2}). 

