\paragraph{Notation.} Let $X$ be a random variable, then $X_{(k:n)}$ denotes the $k$-th order statistic ($k$-smallest value) of $n$ independent and identically distributed copies of $X$. Note that $X_{(n:n)} = \max \{X_1, \dots, X_n\}$ denotes the highest value amongst $n$ i.i.d draws of $X$. For any $x \in \mathbb{R}$, we have that $(x)_+ \triangleq \max\{x, 0\}$. %The constant $\gamma$ denotes the Euler-Mascheroni constant. 
For any two functions $f(n)$ and $g(n)$, we denote $f(n) \asymp g(n)$ if and only if $\lim_{n \to \infty} f(n) / g(n) = 1$.



\section{Main Results}
\label{sec:welfare-implications}

In this section, we will assume that the common terms $(q_y)$ and the idiosyncratic terms $(\varphi_{xy})$ are drawn i.i.d from distributions $P_q$ and $P_{\varphi}$. In order to illuminate the role of the tail of the distribution $P_q$ and $P_{\varphi}$, we will describe the distributions only in terms of their tails. In particular, we will focus on the Pareto tail (heavy-tailed distribution) which we formally define in Definition \ref{def:Pareto-tail} below. %Since the exponential tail can be considered as a limiting (or special) case of the generalized Pareto tail \citep{arnold2008pareto}, 
We also study the case of exponential tail (defined in Definition \ref{def:Exponential-tail}). % and will informally discuss how the results for the exponential tail can be obtained as corollary of the results for the Pareto tail. The exponential tail is defined in Definition \ref{def:Exponential-tail}.

\begin{definition}[Pareto Tail]
    \label{def:Pareto-tail}
    Fix $c > 0$ and $\alpha > 1$. Let $X$ be a random variable with distribution $F$. We say that $F$ has a Pareto tail with parameters $(c, \alpha)$ if $\lim_{x \to \infty} \frac{\mathbb{P}(X > x)}{(c / x)^\alpha} = 1$.
\end{definition}

\begin{definition}[Exponential Tail]
    \label{def:Exponential-tail}
    Fix $c > 0$ and $\lambda > 0$. Let $X$ be a random variable with distribution $F$.~We say that $F$ has an exponential tail with parameters $(c, \lambda)$ if $\lim_{x \to \infty} \frac{\mathbb{P}(X > x)}{c\exp(-\lambda x)} = 1$.
\end{definition}


\subsection{Uncapacitated supply setting}
\label{subsec:welfare-implications-uncapacitated}

Recall that in the uncapacitated supply setting, we have a single agent with unit demand and $n$ items with unit capacity. Note that agent welfare is simply the expected utility of the item chosen by the agent under different information regimes.

\begin{theorem}[Uncapacitated Supply, Pareto tails]
    \label{thm:uncapacitated-pareto}
    Consider the uncapacitated supply setting. Fix $c_q > 0, \alpha_q > 1, c_\varphi > 0, \alpha_{\varphi} > 1$. Assume that the common terms $(q_{y})$ are drawn i.i.d from a distribution $P_{q}$ with non-negative support, finite mean $\mu_q < \infty$ and has a Pareto tail with parameters $(c_q, \alpha_q)$. Assume that the idiosyncratic terms $(\varphi_{xy})$ are drawn i.i.d from a distribution $P_{\varphi}$ with non-negative support, finite mean $\mu_\varphi < \infty$ and has a Pareto tail with parameters $(c_\varphi, \alpha_\varphi)$. For any $\rho \in [0,1]$, we have that,
    \begin{enumerate}[label = $(\thetheorem.\alph*)$]

        \item \label{thm:uncapacitated-pareto-a} The difference in the agent welfare $\Delta_{\emptyset \to q}^{\sf uncap}(n)$ obtained in the {\sf Only Quality Information} regime and the {\sf No Information} regime scales in the number of items $n$ as 
        \begin{align*}
            \lim_{n \to \infty} \frac{\Delta^{\sf uncap}_{\emptyset \to \varphi}(n)}{ c_q \Gamma(1 - 1 / \alpha_q) \cdot n^{1 / \alpha_q}} = 1 - \rho.
        \end{align*}

        \item \label{thm:uncapacitated-pareto-b} The difference in the agent welfare $\Delta_{\emptyset \to \varphi}^{\sf uncap}(n)$ obtained in the {\sf Full Information} regime and {\sf Only Quality Information} regime depends on the values of tail exponents $\alpha_q$ and $\alpha_{\varphi}$ as follows:
        \begin{enumerate}[label = $(\thetheorem.b.\roman*)$]
            \item \label{thm:uncapacitated-pareto-b-i} \underline{$\alpha_q \neq \alpha_{\varphi}$.} Let $\underline{\alpha} \triangleq \min\{\alpha_q, \alpha_{\varphi}\}$ and $c \triangleq c_{q} \mathbbm{1}\{\alpha_q < \alpha_{\varphi}\} + c_\varphi \mathbbm{1}\{\alpha_q > \alpha_{\varphi} \} $. Then we have that
            \begin{align*}
                \lim_{n \to \infty} \frac{\Delta_{q \to u}^{\sf uncap}(n)}{c\Gamma(1 - 1 / \underline{\alpha}) \cdot  n^{1 / \underline{\alpha}}} =  \rho \cdot \mathbbm{1}\{\alpha_{q} > \alpha_{\varphi} \}.
            \end{align*}

            \item \label{thm:uncapacitated-pareto-b-ii} \underline{$\alpha_{q} = \alpha_{\varphi}$.} Let us denote $\alpha_{q} = \alpha_{\varphi} = \alpha$. Then we have that,
            \begin{align*}
                \lim_{n \to \infty} \frac{\Delta_{q \to u}^{\sf uncap}(n)}{\Gamma(1 - 1 / \alpha) \cdot n^{1 / \alpha}} &= ((1 - \rho)^{\alpha} c_q^\alpha +  \rho^{\alpha} c_{\varphi}^\alpha)^{1 / \alpha} - (1 - \rho) c_{q}.
            \end{align*}
            Furthermore, if $c_{q} = c_\varphi = c$, then we have that
            \begin{align*}
                \lim_{n \to \infty} \frac{\Delta_{q \to u}^{\sf uncap}(n)}{c\Gamma(1 - 1/\alpha) \cdot n^{1 / \alpha}} &= (( 1 - \rho)^{\alpha} + \rho^{\alpha})^{1 / \alpha} - (1 - \rho) .
            \end{align*}
        \end{enumerate}
    \end{enumerate}
\end{theorem}

The proof of Theorem \ref{thm:uncapacitated-pareto} is deferred to Section \ref{subsec:proof-thm-uncapacitated-pareto}. Theorem~\ref{thm:uncapacitated-pareto} captures the marginal welfare gains in the {uncapacitated} setting with Pareto-tailed common and idiosyncratic terms. It is split into two parts:
\begin{itemize}
    \item Theorem \ref{thm:capacitated-pareto-a} quantifies the improvement from \textsf{No Information} to \textsf{Only Quality Information}, showcasing the value of public rankings.
    \item Theorem \ref{thm:uncapacitated-pareto-b} measures the additional gains from \textsf{Only Quality Information} to \textsf{Full Information}, revealing when personalized recommendations are most beneficial.
\end{itemize}
\paragraph{\underline{Discussion of Theorem \ref{thm:uncapacitated-pareto-a}: Value of Public Rankings}}
\begin{itemize}
    \item {\bf Main Insights}: When items have infinite capacity, revealing the common term $(q_y)$, as done by public rankings, can significantly improve welfare if $\rho < 1$ (see Figure \ref{subfig:thm-uncapacitated-pareto-a}). Specifically, Theorem \ref{thm:uncapacitated-pareto-a} shows that $\Delta_{\emptyset \to q}^{\sf uncap}(n)$ grows on the order of $n^{1 / \alpha_q}$, multiplied by $(1 - \rho)$ and a constant factor related to the parameters of the Pareto tail. Since supply is unlimited, the agent can freely pick the highest-$q_y$ item without being blocked. Because $(1 - \rho)$ reflects how much the common term contributes to the agent’s utility, a smaller $\rho$ (i.e., more homogeneous preferences) yields greater benefits from public rankings.

    \item {\bf Proof Sketch}: In the {\sf No Information} regime, the agent’s expected utility is simply $(1 - \rho) \mu_q + \rho \mu_\varphi$. With \textsf{Only Quality Information}, the agent sees the highest $q_y$. Because $q_y$ follows a Pareto tail, its maximum grows like $n^{1/\alpha_q}$. This increase is multiplied by $(1-\rho)$, reflecting the weight of the common term in the total utility.
\end{itemize}


% \paragraph{Discussion of Theorem \ref{thm:uncapacitated-pareto-a}.} To quantify the benefit from public rankings, we consider the difference in agent welfare obtained in the {\sf Only Quality Information} regime and the agent welfare obtained in the {\sf No Information} regime, denoted as $\Delta_{\emptyset \to q}^{\sf cap}(n)$. Theorem \ref{thm:uncapacitated-pareto-a} shows that this difference grows in the number of items $n$ as $\Delta_{\emptyset \to q}^{\sf cap}(n) \asymp (1 - \rho) c_q \Gamma(1 - 1 / \alpha_q) n^{1 / \alpha_q}$ which we verify numerically in Figure \ref{subfig:thm-uncapacitated-pareto-a}. This finding suggests that for $\rho \in [0,1)$, in contrast to the capacitated supply setting as we will see later, public rankings can enhance agent welfare by providing partial information about their utility -- specifically, the common terms associated with each item. The scaling of $\Delta_{\emptyset \to q}^{\sf cap}(n)$ can be intuitively understood: public rankings disclose the common terms, which have a weight of $1 - \rho$ in the total utility. The benefit of revealing this component is $c_q \Gamma(1 - 1 / \alpha_q) n^{1 / \alpha_q}$, representing the expected value of the largest common term, which is the expected value of maximum of $n$ i.i.d samples from a Pareto-tailed distribution with parameters $(c_q, \alpha_q)$ (formalized in Proposition \ref{prop:expected-maximum-n-pareto-tail}). Thus, the total benefit is simply the product of these two terms. More specifically, in the baseline {\sf No Information} regime, the expected agent utility is simply ${\sf AW}_{\emptyset}^{\sf uncap}(n) = (1 - \rho) \mu_q + \rho \mu_{\varphi}$. When public rankings are available (as in the {\sf Only Quality Information} regime), the agent learns the common terms of the items and selects the one with the highest common term, leading to an expected agent utility of ${\sf AW}_q^{\sf uncap}(n) = (1 - \rho) \mathbb{E}[q_{(n:n)}] + \rho \mu_{\varphi}$. Note that the second term $\rho \mu_{\varphi}$ follows from the fact that the idiosyncratic term is independent of the common term. This leads to the result in Theorem \ref{thm:uncapacitated-pareto-a} and we provide a formal argument for the same in Section \ref{subsec:proof-thm-uncapacitated-pareto-a}.


\paragraph{\underline{Discussion of Theorem \ref{thm:uncapacitated-pareto-b}: (Incremental) Value of Personalized Recommendations}}
\begin{itemize}
    \item {\bf Main Insights}: Theorem \ref{thm:uncapacitated-pareto-b} measures how much additional welfare is gained by revealing both the common and the idiosyncratic terms, rather than only the common term. In the \textsf{Full Information} regime, the agent see both $(q_y)$ and $(\varphi_y)$. Thus, the agent chooses the maximum of $n$ i.i.d $Z_y = (1-\rho)\,q_y + \rho\,\varphi_y$. The welfare gain due to personalizing recommendations is measured as $\Delta_{\emptyset \to q}^{\sf uncap}(n) = \mathbb{E}[\max_{y} Z_y] - (1 - \rho) \mathbb{E}[q_{(n:n)}] - \rho \mu_\varphi$.
    Whether this welfare gain is large depends on which distribution, $P_q$ or $P_\varphi$, has the heavier Pareto tail and on the level of heterogeneity $\rho$. If $\alpha_q \neq \alpha_\varphi$, whichever is heavier \textit{dominates} the highest potential utility. 
    When the exponents match, \textit{both} matter; if $\rho$ is small, the common term drives utility, yielding minimal additional benefit from personalization. Conversely, if $\rho$ is large, idiosyncratic term drives utility, making personalized recommendations crucial.
    \begin{itemize}
        \item \underline{Case $\alpha_q < \alpha_\varphi$ (common term heavier):}
        The maximum common term dominates, so revealing the idiosyncratic terms adds negligible extra value (see Theorem \ref{thm:uncapacitated-pareto-b-i}).  

        \item \underline{Case $\alpha_q > \alpha_\varphi$ (idiosyncratic term heavier):} The maximum idiosyncratic term dominates, so revealing the idiosyncratic terms significantly boosts agent welfare (see Theorem \ref{thm:uncapacitated-pareto-b-i}).

        \item \underline{Case $\alpha_q = \alpha_\varphi$ (both terms are equally heavy):}
        Here, $Z_y = (1-\rho)\,q_y + \rho\,\varphi_y$ follows a combined Pareto tail that depends on $c_q$, $c_\varphi$, $\alpha$ and $\rho$. The incremental gain of personalization depends on how strongly $\rho$ weights $\varphi_y$. When $\rho$ is small, personalization adds minimal value; when $\rho$ is large, it is crucial (Figures~\ref{subfig:uncap-alpha-2}, \ref{fig:uncap-alpha-5}). To see this clearly, consider the case when $c_q = c_\varphi = c$. We have that $\Delta_{q \to u}^{\sf uncap}(n) \asymp g(\rho; \alpha) \cdot C \cdot n^{1 / \alpha}$, where $C$ depends on $c$ and $\alpha$ and $g(\rho; \alpha) = ((1 - \rho)^\alpha + \rho^\alpha)^{1 / \alpha} - (1 - \rho)$. For large values of $\alpha$, we see in Figure \ref{subfig:rho-function-formula} that $g(\rho; \alpha)$ is nearly flat for small values of $\rho$ ($\rho \in (0,1/2)$) and increases linearly for large values of $\rho$ ($\rho \in (1/2,1)$). Note that as $\alpha \to \infty$, we have that $g(\rho; \alpha) \to \max\{2\rho - 1, 0\}$ -- for $\rho \in (0,1/2)$, we have that $g(\rho; \alpha) = 0$ and for $\rho \in (1/2,1)$, we have that $g(\rho; \alpha) = 2\alpha - 1 > 0$. This is the same phase transition we observe in the case of exponential-tailed distributions (discussed later; also see Appendix \ref{app:connection-pareto-exponential} for a brief discussion).
        %The maximum of $n$ i.i.d draws of $Z_y = (1-\rho)\,q_y + \rho\,\varphi_y$ depends on tail parameters of both the common and the idiosyncratic terms, i.e, $c_q, c_\varphi$ and $\alpha$, as well as, on the level of heterogeneity $\rho$. To illuminate the impact of $\rho$, we consider the case where $c_q = c_\varphi$: in this case, we show that the incremental welfare gain by personalizing recommendations scales as $\Delta_{q \to u}^{\sf uncap}(n) \asymp g(\alpha, \rho) \cdot C \cdot n^{1 / \alpha}$, where $C$ depends on $c$ and $\alpha$ and $g(\alpha, \rho) = ((1 - \rho)^\alpha + \rho^\alpha)^{1 / \alpha} - (1 - \rho)$. Figure \ref{subfig:rho-function-formula} plots the function $g(\rho, \alpha)$ for different values of $\alpha$. $g(\alpha, \rho)$ captures the interplay of $\rho$ and the incremental benefit of personalizing recommendations: when $\rho$ is small, personalizing recommendations provides negligible benefit over public rankings while when $\rho$ is large, personalizing recommendations unlock substantially more value than public rankings (see Figures \ref{subfig:uncap-alpha-2} and \ref{fig:uncap-alpha-5}).
    \end{itemize}
    \item {\bf Proof Sketch}: In the {\sf Only Quality Information} regime, the agent's expected utility is $(1 - \rho) \mathbb{E}[q_{(n:n)}] + \rho \mu_q$. In the {\sf Full Information} regime, the agent's expected utility depends on $\alpha_q, \alpha_\varphi, c_q, c_\varphi$ and $\rho$ as
    \begin{itemize}
        \item \underline{Case $\alpha_q < \alpha_\varphi$ (common term heavier):} Since the common term dominates, we have that $\mathbb{E}[\max_y Z_y] \asymp (1 - \rho) \mathbb{E}[q_{(n:n)}]$ which implies the result since $\lim_{n \to \infty} \rho \mu_q / \mathbb{E}[q_{(n:n)}] = 0$.
        \item \underline{Case $\alpha_q > \alpha_\varphi$ (idiosyncratic term heavier):} Since the idiosyncratic term dominates, we have that $\mathbb{E}[\max_y Z_y] \asymp \rho \mathbb{E}[\varphi_{(n:n)}]$ and $\lim_{n \to \infty} \mathbb{E}[q_{(n:n)}] / \mathbb{E}[\varphi_{(n:n)}] = 0$. Combining the two gives the result.
        \item \underline{Case $\alpha_q = \alpha_\varphi$ (both terms are equally heavy):} We show that the random variable $Z_y$ has a Pareto tail with parameters $(c_Z, \alpha)$ where $c_Z = (((1 - \rho)c_q)^\alpha + (\rho c_\varphi)^\alpha)^{1 / \alpha}$. This allows us to show that $\mathbb{E}[\max_y Z_y] \asymp (c_Z / c_q) \mathbb{E}[q_{(n:n)}]$ and the result follows.
    \end{itemize}
\end{itemize}



