\begin{theorem}[Uncapacitated supply, Exponential tails]
    \label{thm:uncapacitated-exponential}
    Consider the uncapacitated supply setting. Fix $c_q > 0, \lambda_q > 0, c_\varphi > 0, \lambda_\varphi > 0$. Assume that the common terms $(q_y)$ are drawn i.i.d from a distribution $P_q$ with non-negative support, finite mean $\mu_{q} < \infty$ and an exponential tail with parameters $(c_q, \lambda_q)$. Assume that the idiosyncratic terms $(\varphi_{xy})$ are drawn i.i.d from a distribution $P_\varphi$ with non-negative support, finite mean $\mu_{\varphi} < \infty$ and an exponential tail with parameters $(c_\varphi, \lambda_\varphi)$. For any $\rho \in (0,1)$, we have that 

    \begin{enumerate}[label = $(\thetheorem.\alph*)$]
        \item \label{thm:uncapacitated-exponential-a} The difference in the agent welfare $\Delta_{\emptyset \to q}^{\sf uncap}(n)$ obtained in the {\sf Only Quality Information} regime and {\sf No Information} regime increases in the number of items $n$. In particular, we have that
        \begin{align*}
            \lim_{n \to \infty} \frac{\Delta^{\sf uncap}_{\emptyset \to q}(n)}{ \ln n / \lambda_{q} } = 1 - \rho.
        \end{align*}


        \item \label{thm:uncapacitated-exponential-b} The difference in the agent welfare $\Delta_{q \to u}^{\sf uncap}(n)$ obtained in the {\sf Full Information} regime and {\sf Only Quality Information} regime depends on the values of rate parameters $\lambda_{q}, \lambda_{\varphi}$ and parameter $\rho$. In particular, we have that
        \begin{align*}
            \lim_{n \to \infty} \frac{\Delta_{q \to u}^{\sf uncap}(n)}{ \ln n } = \max\bigg\{\frac{1 - \rho}{\lambda_{q}}, \frac{\rho}{\lambda_{\varphi}} \bigg\} - \frac{1 - \rho}{\lambda_{q}}.
        \end{align*}
        Furthermore, if $\lambda_{q} = \lambda_{\varphi} = \lambda$, we have that 
        \begin{align*}
            \lim_{n \to \infty} \frac{\Delta_{q \to u}^{\sf uncap}(n)}{ \ln n / \lambda } = (2\rho - 1)_+ .
        \end{align*}
    \end{enumerate}
\end{theorem}

The proof of Theorem \ref{thm:uncapacitated-exponential} is deferred to Section \ref{app:proof-thm-uncapacitated-exponential}. Theorem~\ref{thm:uncapacitated-exponential} parallels our Pareto-tail results, but now the tail parameters $\lambda_q$ and $\lambda_\varphi$ drives the marginal welfare of public rankings and personalized recommendations.
\paragraph{\underline{Discussion of Theorem~\ref{thm:uncapacitated-exponential-a}: Value of Public Rankings}}
\begin{itemize}
    \item \textbf{Main Insights}: 
    In the uncapacitated setting, revealing the common term $(q_y)$ again yields a substantial welfare boost if $\rho < 1$. 
    Specifically, Theorem~\ref{thm:uncapacitated-exponential-a} shows $\Delta_{\emptyset \to q}^{\sf uncap}(n)$ grows asymptotically like ${\ln n} / {\lambda_q}$, multiplied by $(1-\rho)$ (see Figure \ref{subfig:uncapacitated-exponential-a}). %As with Pareto tails, the agent can pick the item with the largest $q_y$ without being blocked, so the common term alone (weighted by $(1-\rho)$) drives the main benefit. 
    %A smaller $\rho$ means publicrankings are more effective, since the common term is more influential.

    \item \textbf{Proof Sketch}: The proof follows the same recipe as in the case of Pareto-tailed distribution with the key distinction being that maximum of common terms scales as $\ln n / \lambda_q$.
\end{itemize}


\paragraph{\underline{Discussion of Theorem~\ref{thm:uncapacitated-exponential-b}: (Incremental) Value of Personalized Recommendations}}
\begin{itemize}
    \item \textbf{Main Insights}:
    In the \textsf{Full Information} regime, the agent observes both the common terms $q_y$ and the idiosyncratic terms $\varphi_y$ and chooses the maximum of $n$ draws of $Z_y = (1-\rho) q_y + \rho \varphi_y$.
    Theorem \ref{thm:uncapacitated-exponential-b} characterizes $\Delta_{q \to u}^{\sf uncap}(n)$ showing the dominant rate (either $\lambda_q / (1 - \rho)$ or $\lambda_{\varphi} / \rho$) determines how much extra value personalization provides.

    \begin{itemize}
        \item \underline{$\lambda_q / (1 - \rho) < \lambda_{\varphi} / \rho$}: There is limited benefit to revealing the idiosyncratic terms.
        \item \underline{$\lambda_q / (1 - \rho) > \lambda_{\varphi} / \rho$ }:
        Revealing the idiosyncratic terms significantly increases utility.
        \item \underline{$\lambda_q = \lambda_{\varphi}$ }:
        There is a knife edge transition at $\rho = 1/2$ (see Theorem~\ref{thm:uncapacitated-exponential-b} and Figure~\ref{fig:exponential-uncapacitated}): for $\rho \in (0,1/2)$, personalizing recommendations provide no asymptotic gain over public rankings, whereas for $\rho \in (1/2,1)$, personalization offers substantial additional value.
    \end{itemize}

    \item \textbf{Proof Sketch}: The proof follows the same recipe as in the case of Pareto-tailed distributions. The key distinction is that we show that random variable $Z_y$ {\it approximately} has an exponential tail with rate $\lambda_Z = \min\{\lambda_q / (1 - \rho), \lambda_{\varphi} / \rho\}$. This result allows us characterize the scaling of $\mathbb{E}[\max_y Z_y]$ which in turn leads to the result.
\end{itemize}


