\section{Proof of intermediate results}

\subsection{Proof of Proposition \ref{prop:expected-maximum-n-pareto-tail}}
\label{app:proof-expected-maximum-n-pareto-tail}
\begin{proof}[\underline{Proof of Proposition \ref{prop:expected-maximum-n-pareto-tail}}]
Fix $\epsilon > 0$. Since $X$ has a pareto tail with parameters $c > 0$ and $\alpha > 1$, there exists a constant $x_0 > 0$ such that for all $x \geq x_0$, we have that
\begin{align}
    \label{eq:pareto-tail-upper-lower-bound}
    (1 - \epsilon) (c / x)^{\alpha} \leq \mathbb{P}(X > x) \leq (1 + \epsilon) (c / x)^{\alpha}.
\end{align}
Next we want to bound the tail distribution for $X_{(n:n)}$ which is maximum of $n$ i.i.d copies of $X$. We have that for all $x \geq x_0$, we have that 
\begin{align}
    \label{eq:maximum-tail-expression}
    \mathbb{P}(X_{(n:n)} > x) = 1 - \mathbb{P}(X_{(n:n)} \leq x) = 1 - (\mathbb{P}(X \leq x))^n = 1 - (1 - \mathbb{P}(X > x))^n .
\end{align}
Using \eqref{eq:pareto-tail-upper-lower-bound} and \eqref{eq:maximum-tail-expression}, we have that for $x \geq x_0$,
\begin{align}
    \label{eq:maximum-tail-pareto-upper-lower-bound}
    1 - (1 - (1 - \epsilon)(c / x)^\alpha)^n \leq \mathbb{P}(X_{(n:n)} > x) \leq 1 - (1 - (1 + \epsilon)(c / x)^\alpha)^n.
\end{align}
Since $X \geq 0$, we have that $X_{(n:n)} \geq 0$ and therefore, we will make use of the tail sum formula for the expectation to provide upper and lower bounds on $\mathbb{E}[X_{(n:n)}]$. Define $\bar{c} \triangleq (1 + \epsilon)^{1/\alpha} c$ and $\underline{c} \triangleq (1 - \epsilon)^{1 / \alpha} c$. We will begin by providing the upper bound on $\mathbb{E}[X_{(n:n)}]$.
\begin{align}
    \label{eq:pareto-tail-max-expectation-upper-bound}
    \mathbb{E}[X_{(n:n)}] &\stackrel{(a)}= \int_{0}^{\infty} \mathbb{P}(X_{(n:n)} > x) dx 
    \stackrel{(b)}\leq \max\{x_0, \bar{c}\} + \int_{\bar{c}}^{\infty} 1 - (1 - (\bar{c} / x)^\alpha)^n dx,
\end{align}
where $(a)$ follows from the tail sum formula for the expectation \citep{durrett2019probability} and $(b)$ follows from the fact that in the interval $[0, \max\{x_0, \bar{c}\}]$, we have that $\mathbb{P}(X_{(n:n)} > x) \leq 1$ and $\int_{\max\{x_0, \bar{c}\}}^\infty 1 - (1 - (c / x)^\alpha)^n dx \leq \int_{\bar{c}}^\infty 1 - (1 - (\bar{c} / x)^\alpha)^n dx$. 

Next we will compute the integral $\int_{\bar{c}}^{\infty} 1 - (1 - (\bar{c} / x)^\alpha)^n dx$. Let $U(x) = x$ and $V(x) = 1 - (1 - (\bar{c} / x)^\alpha)^n$. Therefore $dU(x) = dx$ and $dV(x) = - n \alpha \bar{c}^\alpha (1 - (\bar{c} / x)^\alpha)^{n - 1} x^{-\alpha - 1} dx$.
\begin{align}
    \nonumber
    \int_{\bar{c}}^\infty 1 - (1 - (\bar{c} / x)^\alpha)^n dx &\stackrel{(a)}= \int_{\bar{c}}^\infty V(x) dU(x), \\
    \nonumber
    &\stackrel{(b)}= \left[ U(x) V(x) \right]_{\bar{c}}^\infty - \int_{\bar{c}}^\infty U(x) dV(x), \\
    \nonumber
    &\stackrel{(c)}= -\bar{c} -  \int_{\bar{c}}^\infty x \cdot (- n \alpha \bar{c}^\alpha (1 - (\bar{c} / x)^\alpha)^{n - 1} x^{-\alpha - 1}) dx, \\
    \nonumber
    &\stackrel{(d)}= -\bar{c} + n  \alpha \int_c^\infty (1 - (\bar{c} / x)^\alpha)^{n - 1} (\bar{c} / x)^\alpha dx, \\
    \nonumber
    &\stackrel{(e)}= -\bar{c} + n \bar{c} \int_0^1 (1 - u)^{n - 1} u^{-\frac{1}{\alpha} + 1 - 1} du, \\
    \label{eq:integral-pareto-upper-bound-gamma-function}
    &\stackrel{(f)}= - \bar{c} + n \bar{c} \frac{\Gamma(1 - 1/ \alpha) \Gamma(n)}{\Gamma(n + 1 - 1/\alpha)},
\end{align}
where $(a)$ follows from the definition of $U(x)$ and $V(x)$, $(b)$ follows from integration by parts, $(c)$ follows from $dV(x)$ , $(d)$ follows from rearrangment, $(e)$ follows from change of variable where $(\bar{c} / x)^\alpha = u$ and simplification, $(f)$ from the the definition of Beta function $B(t_1, t_2) = \int_{0}^1 u^{t_1 - 1} (1 - u)^{t_2 - 1} du = \Gamma(t_1) \Gamma(t_2) / \Gamma(t_1 + t_2)$ where $t_1 = 1 - 1 /\alpha$ and $t_2 = n$. Combining \eqref{eq:pareto-tail-max-expectation-upper-bound} and \eqref{eq:integral-pareto-upper-bound-gamma-function}, we have that
\begin{align}
    \label{eq:pareto-tail-max-expectation-upper-bound-2}
    \mathbb{E}[X_{(n:n)}] \leq (x_0 - \bar{c})_+ + n \bar{c} \frac{\Gamma(1 - 1/ \alpha) \Gamma(n)}{\Gamma(n + 1 - 1/\alpha)}.
\end{align}
Using Stirlings' approximation, we have that 
\begin{align}
    \label{eq:stirlings-approximation}
    \lim_{n \to \infty} \frac{n \Gamma(n)}{\Gamma(n + 1 - 1 / \alpha) n^{1 / \alpha}} = 1
\end{align}
Combining \eqref{eq:pareto-tail-max-expectation-upper-bound-2} and \eqref{eq:stirlings-approximation}, we have that
\begin{align*}
    \limsup_{n \to \infty} \frac{\mathbb{E}[X_{(n:n)}]}{\Gamma(1 - 1 / \alpha) n^{1 / \alpha}} \leq \limsup_{n \to \infty} \bigg\{\frac{1}{\Gamma(1 - 1 / \alpha) n^{1 / \alpha}} \cdot n \bar{c} \frac{\Gamma(1 - 1/ \alpha) \Gamma(n)}{\Gamma(n + 1 - 1/\alpha)} \bigg\} = \bar{c}.
\end{align*}
Using similar arguments as provided for the upper bound, we can easily show the following lower bound, 
\begin{align*}
    \underline{c} = \liminf_{n \to \infty } \bigg\{\frac{1}{\Gamma(1 - 1 / \alpha) n^{1 / \alpha}} \cdot n \underline{c} \frac{\Gamma(1 - 1/ \alpha) \Gamma(n)}{\Gamma(n + 1 - 1/\alpha)} \bigg\} \leq \liminf_{n \to \infty} \frac{\mathbb{E}[X_{(n:n)}]}{\Gamma(1 - 1 / \alpha) n^{1 / \alpha}}.
\end{align*}
Combining these two results along with the definition of $\underline{c} = (1 - \epsilon)^{1 / \alpha} c$ and $\bar{c} = (1 + \epsilon)^{1 / \alpha} c$, we have that 
\begin{align*}
    (1 - \epsilon)^{1 / \alpha} \leq \liminf_{n \to \infty} \frac{\mathbb{E}[X_{(n:n)}]}{c\Gamma(1 - 1 / \alpha) \cdot n^{1 / \alpha}} \leq \limsup_{n \to \infty} \frac{\mathbb{E}[X_{(n:n)}]}{c\Gamma(1 - 1 / \alpha) \cdot n^{1 / \alpha}} \leq (1 + \epsilon)^{1 / \alpha}
\end{align*}
Note that since the above set of inequalities hold for every $\epsilon > 0$, we have that 
\begin{align*}
    \lim_{n \to \infty} \frac{\mathbb{E}[X_{(n:n)}]}{c\Gamma(1 - 1 / \alpha) \cdot n^{1 / \alpha}} = 1.
\end{align*}
This completes the proof. 
\end{proof}

