\subsection{Proof of Lemma \ref{lem:tail-convex-combination-pareto-tails}}
\label{app:proof-tail-convex-combination-pareto-tails}
\begin{proof}[\underline{Proof of Lemma \ref{lem:tail-convex-combination-pareto-tails}}]
    Since $X \geq 0$ and $Y \geq 0$, it trivially follows that $Z \geq 0$ and from linearity of expectations we have that $\mathbb{E}[Z] = (1 - \rho) \mu_X + \rho \mu_Y < \infty$. 

    Since $X$ has Pareto tail with parameters $c_X > 0$ and $\alpha_X > 1$, we have that $(1 - \rho) X$ has a pareto tail with parameters $(1 - \rho) c_X > 0$ and $\alpha_{x} > 1$. This is because
    \begin{align*}
        1 = \lim_{x \to \infty } \frac{\mathbb{P}(X > x)}{(c_X / x)^\alpha} = \lim_{x \to \infty} \frac{\mathbb{P}(X > x / (1 - \rho))}{(c_X / (x / (1 - \rho)))^\alpha} = \lim_{x \to \infty} \frac{\mathbb{P}((1 - \rho) X > x)}{((1 - \rho) c_X / x)^\alpha}
    \end{align*}
    Similarly we have that $\rho Y$ has a pareto tail with parameters $\rho c_Y > 0 $ and $\alpha_Y > 1$. Let us denote $\tilde{X} = (1 - \rho) X$ and $\tilde{Y} = \rho Y$, then $Z = \tilde{X} + \tilde{Y}$ and we want to characterize the tail behavior of $Z$.

    We will begin by providing a lower bound on the tail of $Z$. We have that 
    \begin{align}
        \nonumber
        \mathbb{P}(Z > t) &\stackrel{(a)}= \mathbb{P}(\tilde{X} + \tilde{Y} > t), \\
        \nonumber
        &\stackrel{(b)}\geq \mathbb{P}(\max\{\tilde{X}, \tilde{Y}\} > t), \\
        \nonumber
        &\stackrel{(c)}= 1 - (1 - \mathbb{P}(\tilde{X} > t)) ( 1- \mathbb{P}(\tilde{Y} > t)), \\
        \label{eq:tail-Z-lower-bound}
        &\stackrel{(d)}= \mathbb{P}(\tilde{X} > t) + \mathbb{P}(\tilde{Y} > t) - \mathbb{P}(\tilde{X} > t) \mathbb{P}(\tilde{Y} > t),
    \end{align}
    where $(a)$ follows from the definition of $Z$, $(b)$ follows from the fact that $\{\max\{\tilde{X}, \tilde{Y}\} > t\} \implies \{Z > t\}$, $(c)$ follows from the fact that $\mathbb{P}(\max\{\tilde{X}, \tilde{Y}\} > t) = 1 - \mathbb{P}(\tilde{X} < t) \mathbb{P}(\tilde{Y} < t)$ since $\tilde{X}$ and $\tilde{Y}$ are independent, $(d)$ follows trivially. Next we will provide an upper bound on the tail of $Z$. Fix a $\delta \in (0,1/2)$. We have that 
    \begin{align}
        \label{eq:tail-Z-upper-bound}
        \mathbb{P}(Z > t) &= \mathbb{P}(\tilde{X} + \tilde{Y} > t)
        \stackrel{(a)}\leq \mathbb{P}(\tilde{X} > (1 - \delta) t) + \mathbb{P}(\tilde{Y} > (1 - \delta) t) + \mathbb{P}(\tilde{X} > \delta t) \mathbb{P}(\tilde{Y} > \delta t),
    \end{align}
    where $(a)$ follows from the fact that the event $\{\tilde{X} + \tilde{Y} > t\}$ implies the event $\{\tilde{X} > (1 - \delta)t \} \cup \{\tilde{Y} > (1 - \delta) t\} \cup \{\tilde{X} > \delta t, \tilde{Y} > \delta t\}$.

    Next we will consider following cases:
    \begin{enumerate}[label = $(\alph*)$]
        \item \underline{$\alpha_X < \alpha_Y$.} Using \eqref{eq:tail-Z-lower-bound}, we have that $\liminf_{t \to \infty} \mathbb{P}(Z > t) / \mathbb{P}(\tilde{X} > t) \geq 1$ and using \eqref{eq:tail-Z-upper-bound}, we have that $\limsup_{t  \to \infty} \mathbb{P}(Z > t) / \mathbb{P}(\tilde{X} > t) \leq \limsup_{t \to \infty} \mathbb{P}(\tilde{X} > (1 - \delta)t) / \mathbb{P}(\tilde{X} > t) = (1 - \delta)^{-\alpha_X}$. Since the upper bound holds for all $\delta \in (0,1/2)$, we have that $\lim_{t \to \infty} \mathbb{P}(Z > t) / \mathbb{P}(\tilde{X} > t) = 1$. Therefore we have that $Z$ has a pareto tail with parameters $c_Z = (1 - \rho) c_X$ and $\alpha_Z  = \alpha_X$.
        \item \underline{$\alpha_X > \alpha_Y$.} This is completely analogous to the case above.
        \item \underline{$\alpha_X = \alpha_Y = \alpha$.} Note that 
        \begin{align*}
            \lim_{t \to \infty } \frac{\mathbb{P}(\tilde{X} > t) + \mathbb{P}(\tilde{Y} > t)}{(c_Z / t)^\alpha} = 1, \quad \text{where } c_Z = (((1 - \rho) c_X)^\alpha + (\rho c_Y)^{\alpha})^{1 / \alpha}
        \end{align*}
        Using \eqref{eq:tail-Z-lower-bound}, we have that $\liminf_{t \to \infty} \mathbb{P}(Z > t) / (\mathbb{P}(\tilde{X} > t) + \mathbb{P}(\tilde{Y} > t)) \geq 1$ and using \eqref{eq:tail-Z-upper-bound}, we have that $\limsup_{t  \to \infty} \mathbb{P}(Z > t) / (\mathbb{P}(\tilde{X} > t) + \mathbb{P}(\tilde{Y} > t)) \leq \limsup_{t \to \infty} \mathbb{P}(\tilde{X} > (1 - \delta)t) / (\mathbb{P}(\tilde{X} > t) + \mathbb{P}(\tilde{Y} > t)) = (1 - \delta)^{-\alpha}$. Since the upper bound holds for all $\delta \in (0,1/2)$, we have that $\lim_{t \to \infty} \mathbb{P}(Z > t) / (\mathbb{P}(\tilde{X} > t) + \mathbb{P}(\tilde{Y} > t)) = 1$. Therefore we have that $Z$ has a pareto tail with parameters $c_Z = (((1 - \rho) c_X)^\alpha + (\rho c_Y)^{\alpha})^{1 / \alpha}$ and $\alpha_Z  = \alpha$.
    \end{enumerate}
    This completes the proof.
\end{proof}


\subsection{Proof of Lemma \ref{lem:upper-lower-bound-capacitated-quality-full-info-diff}}
\label{app:proof-upper-lower-bound-capacitated-quality-full-info-diff}
\begin{proof}[\underline{Proof of Lemma \ref{lem:upper-lower-bound-capacitated-quality-full-info-diff}}]
Note that $\Delta_{q \to u}^{\sf cap}(n) = {\sf AW}_{u}^{\sf cap}(n) - {\sf AW}_{q}^{\sf cap}(n)$. We will begin by characterizing the social welfare in the {\sf Only Quality Information} regime. In the {\sf Only Quality Information} regime, the agents base their decisions solely on the common term $(q_y)$. Therefore, we have that the agent $k$ will choose the item with common term value $q_{(k:n)}$ (recall that $X_{(k:n)}$ denotes the $k$-th smallest value of $n$ i.i.d copies of $X$). 
Recall that $\sigma_{q}(k)$ denotes the index of the item chosen by agent $k$ in the {\sf Only Quality Information} regime. This means that $q_{\sigma_q(k)} = q_{(k:n)}$. Therefore we have that,
\begin{align}
    \nonumber
    {\sf AW}_{q}^{\sf cap}(n) &\stackrel{(a)}= \frac{1}{n}\mathbb{E}\left[\sum_{k = 1}^n (1 - \rho) q_{\sigma_{q}(k)} + \rho \varphi_{k \sigma_{q}(k)} \right] \\
    \nonumber
    & \stackrel{(b)}= (1 - \rho) \frac{1}{n} \mathbb{E}\left[ \sum_{k = 1}^n q_{k} \right] + \rho \frac{1}{n} \sum_{k = 1}^n \mathbb{E}[\varphi_{k \sigma_{q}(k)}], \\
    \label{eq:sw-cap-quality-info-app}
    &\stackrel{(c)}= (1 - \rho) \mu_q + \rho \mu_{\varphi},
\end{align}
where $(a)$ follows from definition of $u_{k\sigma_{q}(k)}$, $(b)$ follows from the fact that $\sum_{k = 1}^n q_{\sigma_{\emptyset}(k)} = \sum_{k = 1}^n q_{(k:n)} = \sum_{k = 1}^n q_k$, $(c)$ follows from the fact that $\mathbb{E}[q_k] = \mu_{q}$ and $\mathbb{E}[\varphi_{k \sigma_{\emptyset}(k)}] = \mu_{\varphi}$ since the index $\sigma_{q}(k)$ is random and hence we have that $\varphi_{k \sigma_{\emptyset}(k)}$ is a random sample drawn from the distribution $P_\varphi$.

Next we will provide an upper and lower bound on the social welfare in the {\sf Full Information} regime. In the model description in Section \ref{sec:model}, every agent in $\mathcal{X}$ observes the common terms $(q_y)$ and the idiosyncratic terms $(\varphi_{xy})$ {\it for all} items. However from an equivalent description is to have the agent $k$ observe the idiosynratic terms $(\varphi_{xy})$ only for the {\it remaining} items. Since $\varphi_{ky}$ are drawn i.i.d across agents, it is equivalent to assume that the idiosyncratic term $\varphi_{ky}$ is drawn i.i.d for $n - k$ items when it is agent $k$'s turn make the choice. This equivalence follows from the so-called ``Principle of Deferred Decisions" \citep{mitzenmacher2017probability}. 

We will first provide an upper bound on the social welfare ${\sf AW}_{u}^{\sf cap}(n)$. Recall that the $\sigma_{u}(k)$ denotes the index of the item chosen by agent $k$. We have that 
\begin{align}
    \nonumber
    {\sf AW}_{u}^{\sf cap}(n) &\stackrel{(a)}= \frac{1}{n} \mathbb{E}\left[ \sum_{k = 1}^n (1 - \rho) q_{\sigma_{u}(k)} + \rho \varphi_{k\sigma_{u}(k)} \right], \\
    \nonumber
    &\stackrel{(b)}= (1 - \rho) \frac{1}{n} \mathbb{E}\left[ \sum_{k = 1}^n q_k \right] + \rho \frac{1}{n} \sum_{k = 1}^n \mathbb{E}\left[ \varphi_{k \sigma_{u}(k)} \right], \\
    \nonumber
    &\stackrel{(c)}\leq (1 - \rho) \mu_q + \rho n^{-1} \sum_{k = 1}^n \mathbb{E}[\varphi_{k, (n - k : n- k)}], \\
    \label{eq:sw-cap-full-info-upper-bound}
    &\stackrel{(d)}= (1 - \rho) \mu_q + \rho \Phi_n,
\end{align}
where $(a)$ follows from definition of $u_{k\sigma_{u}(k)}$, $(b)$ follows from the fact that $\sum_{k = 1}^n q_{\sigma_{u}(k)} = \sum_{k = 1}^n q_k$, $(c)$ follows from the fact that $\mathbb{E}[q_k] = \mu_{q}$ and $\varphi_{k \sigma_{u}(k)} \leq \varphi_{k, (n -k : n- k)}$ where $\varphi_{k, (n -k : n- k)}$ denotes the maximum of $n - k$ i.i.d draws from $P_\varphi$ for agent $k$ and $(d)$ follows from the definition of $\Phi_n$.

We will now present a lower bound on the social welfare ${\sf AW}_{u}^{\sf cap}(n)$. We have that
\begin{align}
    \label{eq:sw-cap-full-info-lower-bound}
    {\sf AW}_{u}^{\sf cap}(n) &= \frac{1}{n} \mathbb{E}\left[ \sum_{k = 1}^n u_{k\sigma_{u}(k)} \right]
    \stackrel{(a)}\geq  \frac{1}{n} \mathbb{E}\left[ \sum_{k = 1}^n \rho \varphi_{k, (n - k: n - k)} \right] \stackrel{(b)}= \rho \Phi_n,
\end{align}
where $(a)$ follows from the fact that $u_{k \sigma_u(k)} = \max_{y \in \mathcal{Y}_k^{\text{rem}}} (1 - \rho) q_y + \rho \varphi_{ky} \geq \rho \varphi_{k, (n - k : n- k)}$ since $q_k \geq 0$ for all $k$, $(b)$ follows from the definition of $\Phi_n$. Combining \eqref{eq:sw-cap-quality-info-app}, \eqref{eq:sw-cap-full-info-upper-bound} and \eqref{eq:sw-cap-full-info-lower-bound} provides the required result.
\end{proof}


\section{Proof of Theorems for utility distributions with Exponential tail}
\label{app:proof-exponential}

The result in Theorems \ref{thm:uncapacitated-exponential} and \ref{thm:capacitated-exponential} can be viewed as following from Theorems \ref{thm:uncapacitated-pareto} and \ref{thm:capacitated-pareto} respectively. See the informal discussion in \ref{app:connection-pareto-exponential}. For completeness, we provide a proof in Appendix \ref{app:proof-thm-uncapacitated-exponential} and \ref{app:proof-thm-capacitated-exponential} from first principles.

\subsection{Connection between Pareto and Exponential tail}
    \label{app:connection-pareto-exponential}
    It is well known that the exponential distribution is a special case of the generalized Pareto distribution \cite{arnold2008pareto}. In this section, we briefly discuss how the results in Theorem \ref{thm:uncapacitated-pareto} and \ref{thm:capacitated-pareto} can be used to derive the result in Theorem \ref{thm:uncapacitated-exponential} and \ref{thm:capacitated-exponential} under some appropriate joint scaling of the parameters and the market size $n$. First,
    it is useful to re-state the Pareto tail definition as $\lim_{x \to \infty} \mathbb{P}(X > x) / (1 + x/c)^{-\alpha} = 1$, this is because $\lim_{x \to \infty} (1 + x / c)^{-\alpha} / (c/x)^\alpha = 1$. Now, define $\alpha = \ln n, c = \ln n / \lambda$ and consider the double limit $x \to \infty$ and $n \to \infty$. Now we have that 
    \begin{align*}
        1 = \lim_{x \to \infty} \frac{\mathbb{P}(X > x)}{\exp(-\lambda x)} = \lim_{x \to \infty} \lim_{n \to \infty} \frac{\mathbb{P}(X > x)}{(1 + \lambda x / \ln n )^{-\ln n}} = 
        \lim_{x \to \infty} \lim_{n \to \infty} \frac{\mathbb{P}(X > x)}{(1 + x / c)^{-\alpha}} = \lim_{n \to \infty} \lim_{x \to \infty} \frac{\mathbb{P}(X > x)}{(1 + x / c)^{-\alpha}}, 
    \end{align*}
    where the interchange of limit follows from the Moore-Osgood theorem \citep{taylor1985general}. 

    As an illustration, we briefly explain how the result in Theorem \ref{thm:capacitated-pareto-b} implies Theorem \ref{thm:capacitated-exponential-b}.
    Note that the denominator in Theorem \ref{thm:capacitated-pareto-b} is actually $C_{\varphi} \Gamma(n + 1) / \Gamma (n + 1 - 1 /\alpha_\varphi)$ which simplifies to $C_{\varphi} n^{1 / \alpha_\varphi}$ using the Stirlings approximation. Note that constant $C_\varphi = c_\varphi (\alpha_\varphi / (\alpha_\varphi + 1)) \Gamma(1 - 1 / \alpha_\varphi)$. Now plugging in $\alpha_\varphi = \ln n$ and $c_\varphi = \ln n / \lambda$ gives the result in Theorem \ref{thm:capacitated-exponential-b} since $\Gamma(1 - 1 / \ln n) \stackrel{n \to \infty}\to \Gamma(1) = 1$, $\ln n / (\ln n + 1) \stackrel{n \to \infty}\to 1$ and $\Gamma(n + 1) / \Gamma(n + 1 - 1/ \ln n) \stackrel{n \to \infty}\to 1$. Similar idea can be use to derive Theorem \ref{thm:uncapacitated-exponential} from Theorem \ref{thm:uncapacitated-pareto}.

\subsection{Useful Intermediate Results}
The proof of Theorems \ref{thm:uncapacitated-exponential} and \ref{thm:capacitated-exponential} will make use of the following proposition which we state and prove below.

\begin{proposition}
    \label{prop:expected-maximum-n-exponential-tail}
    Let $X$ be a random variable with distribution $P$. Assume that $X \geq 0$ and $\mathbb{E}[X] < \infty$. Assume that $X$ has an exponential tail with parameters $c > 0$ and $\lambda > 0$. Let $X_1, X_2, \dots, X_n$ be i.i.d copies of $X$ and define $X_{(n:n)} \triangleq \max_{1 \leq k \leq n }X_k$. We have that
    \begin{align*}
        \lim_{n \to \infty} \frac{\mathbb{E}[X_{(n:n)}]}{\ln n / \lambda} = 1.
    \end{align*}
\end{proposition}
%The proof of Proposition \ref{prop:expected-maximum-n-exponential-tail} is deferred to Appendix \ref{app:proof-expected-maximum-n-exponential-tail}.

\begin{proof}[\underline{Proof of Proposition \ref{prop:expected-maximum-n-exponential-tail}}]
Fix $\epsilon > 0$. Since $X$ has an exponential tail with parameters $c > 0$ and $\lambda > 0$, there exists a constant $x_0 \geq 0$ such that for all $x \geq x_0$, we have that
\begin{align}
    \label{eq:exponential-tail-upper-lower-bound}
    (1 - \epsilon) c\exp(-\lambda x) \leq \mathbb{P}(X > x) \leq (1 + \epsilon) c \exp(-\lambda x)
\end{align}
Next we want to bound the tail distribution for $X_{(n:n)}$ which is maximum of $n$ i.i.d copies of $X$. Define $\bar{c} = (1 + \epsilon) c$ and $\underline{c} = (1 - \epsilon) c$. Using \eqref{eq:maximum-tail-expression} and \eqref{eq:exponential-tail-upper-lower-bound}, we have that for $x \geq x_0$, 
\begin{align*}
    1 - (1 - \underline{c} \exp(- \lambda x))^n \leq \mathbb{P}(X_{(n:n)} > x) \leq 1 - (1 - \bar{c} \exp(- \lambda x))^n
\end{align*}
Since $X \geq 0$, we have that $M \geq 0$ and therefore, we will make use of the tail sum formula for the expectation to provide upper and lower bounds on $\mathbb{E}[X_{(n:n)}]$. Define $s \triangleq \ln \bar{c} / \lambda$. We will begin by providing the upper bound on $\mathbb{E}[X_{(n:n)}]$.
\begin{align}
    \label{eq:exponential-tail-max-expectation-upper-bound}
    \mathbb{E}[X_{(n:n)}] &\stackrel{(a)}= \int_{0}^{\infty} \mathbb{P}(X_{(n:n)} > x) dx 
    \stackrel{(b)}\leq \max\{x_0, s\} + \int_{s}^{\infty} 1 - (1 - \bar{c}\exp(- \lambda x))^n dx,
\end{align}
where $(a)$ follows from the tail sum formula for expectation \citep{durrett2019probability}, $(b)$ follows from the fact that in the interval $[0, \max\{x_0, s\}]$, we have that $\mathbb{P}(X_{(n:n)} > x) \leq 1$ and $\int_{\max\{x_0, s\}}^\infty 1 - (1 - \bar{c}\exp(-\lambda x))^n dx \leq \int_{s}^\infty 1 - (1 - \bar{c}\exp(-\lambda x))^n dx$.

We want to compute the integral $\int_{s}^{\infty} 1 - (1 - \bar{c}\exp(- \lambda x))^n dx$. Therefore, we have that,
\begin{align}
    \nonumber
    \int_{s}^{\infty} 1 - (1 - \bar{c}\exp(- \lambda x))^n dx &\stackrel{(a)}= \frac{1}{\lambda} \int_{0}^1 \frac{1 - (1 - u)^n}{u} du, \\
    \nonumber
    &\stackrel{(b)}= \frac{1}{\lambda} \int_{0}^1 \sum_{k = 0}^{n - 1} (1 - u)^k du, \\
    \nonumber
    &\stackrel{(c)}= \frac{1}{\lambda} \sum_{k = 0}^{n - 1} \int_{0}^{1} (1 - u)^k du, \\
    \nonumber
    &\stackrel{(d)}= \frac{1}{\lambda} \sum_{k = 0}^{n - 1} \frac{1}{k + 1}, \\
    \label{eq:integral-exponential-upper-bound-harmonic-number}
    &\stackrel{(e)}= H_n / \lambda, 
\end{align}
where $(a)$ follows from the change of variable argument where $u = \bar{c}\exp(-\lambda x)$ and some simplification, $(b)$ follows from the fact that $\frac{1 - (1 - u)^n}{u} = \sum_{k = 0}^{n - 1} (1 - u)^k$, $(c)$ follows from the interchange between integral and summation, $(d)$ follows from the fact that $\int_{0}^1 (1 - u)^k du = \frac{1}{k + 1}$, $(e)$ follows from definition of harmonic number $H_n = \sum_{k = 1}^n \frac{1}{k} = \sum_{k = 0}^{n - 1} \frac{1}{k + 1}$.

It is easy to show that $\lim_{n \to \infty} H_{n} / \ln n = 1$. Therefore using \eqref{eq:exponential-tail-max-expectation-upper-bound} and \eqref{eq:integral-exponential-upper-bound-harmonic-number}, we have that 
\begin{align*}
    \limsup_{n \to \infty} \frac{\mathbb{E}[X_{(n:n)}]}{\ln n / \lambda} \leq 1
\end{align*}
Using similar arguments as provided for the upper bound, we can easily show that the following lower bound as well,
\begin{align*}
    1 \leq \liminf_{n \to \infty} \frac{\mathbb{E}[X_{(n:n)}]}{\ln n / \lambda}
\end{align*}
Combining these two results, we have that $\lim_{n \to \infty} \frac{\mathbb{E}[X_{(n:n)}]}{ \ln n / \lambda} = 1$ and this completes the proof.
\end{proof}

\begin{proposition}
    \label{prop:convex-comb-exponential-tails-bound}
    Fix $\rho \in (0,1)$. Let $X$ be a random variable with non-negative support, finite mean $\mu_X < \infty$ and has an exponential tail with parameters $c_X > 0$ and $\lambda_{X} > 0$. Let $Y$ be another random variable with non-negative support, finite mean $\mu_Y < \infty$ and has an exponential tail with parameters $c_Y > 0$ and $\lambda_Y > 0$. Define $Z = (1 - \rho) X + \rho Y$. Let $Z_{(n:n)} = \max\{Z_1, Z_2, \dots, Z_n\}$ where $Z_1, Z_2, \dots, Z_n$ are i.i.d copies of $Z$. Then we have that 
    \begin{align*}
        \lim_{n \to \infty} \frac{\mathbb{E}[Z_{(n:n)}]}{\ln n } = \max\bigg\{ \frac{1 - \rho}{\lambda_q}, \frac{\rho}{\lambda_\varphi} \bigg\}
    \end{align*}
\end{proposition}

\begin{proof}[\underline{Proof of Proposition \ref{prop:convex-comb-exponential-tails-bound}}]
    Fix $\epsilon > 0$ and let $\rho \in (0,1)$. Define $\tilde{X} \triangleq (1 - \rho) X$ and $\tilde{Y} \triangleq \rho Y$. We have that $\tilde{X}$ and $\Tilde{Y}$ have exponential tails with parameters $(c_X, \lambda_X / (1 - \rho))$ and $(c_Y, \lambda_Y / \rho)$ respectively. This is because
    \begin{align*}
        1 &= \lim_{x \to \infty} \frac{\mathbb{P}(X > x)}{c_X \exp(-\lambda_X x)} = \lim_{x \to \infty} \frac{\mathbb{P}(X > x /(1 - \rho))}{c_X \exp(-\lambda_X (x / (1 - \rho)))} =  \lim_{x \to \infty} \frac{\mathbb{P}(\tilde{X} > x)}{c_X \exp(-(\lambda_X / (1 - \rho)) x)} \\
        1 &= \lim_{y \to \infty} \frac{\mathbb{P}(Y > y)}{c_Y \exp(-\lambda_Y y)} = \lim_{y \to \infty} \frac{\mathbb{P}(Y > y / \rho)}{c_Y \exp(-\lambda_Y (y / \rho))} =  \lim_{y \to \infty} \frac{\mathbb{P}(\tilde{Y} > y)}{c_Y \exp(-(\lambda_Y / \rho) y)}
    \end{align*}
    Since $\tilde{X}$ and $\tilde{Y}$ have an exponential tail with parameters $(c_X, \lambda_{X} / (1 - \rho))$ and $(c_Y, \lambda_Y / \rho)$ respectively, there exists constants $\tilde{x}_0, \tilde{y}_0$ such that for all $t \geq t_0 = \max\{\tilde{x}_0, \tilde{y}_0\}$, we have that 
    \begin{align}
        \label{eq:tail-bound-exponential-X}
        (1 - \epsilon) c_X \exp(-(\lambda_X / (1 - \rho)) t) &\leq \mathbb{P}(X > t) \leq (1 + \epsilon) c_X \exp( - (\lambda_X / (1 - \rho)) t) \\
        \label{eq:tail-bound-exponential-Y}
        (1 - \epsilon) c_Y \exp( -(\lambda_Y /\rho) t) &\leq \mathbb{P}(Y > t) \leq (1 + \epsilon) c_Y \exp(- (\lambda_Y /\rho) t)
    \end{align}
    Define $\lambda_{\tilde{X}} \triangleq \lambda_X / (1 - \rho)$ and $\lambda_{\tilde{Y}} \triangleq \lambda_Y / \rho$. Furthermore, we define $\underline{\lambda} \triangleq \min\{\lambda_{\tilde{X}}, \lambda_{\tilde{Y}}\}$ and $\bar{\lambda} \triangleq \max\{\lambda_{\tilde{X}}, \lambda_{\tilde{Y}}\}$. 

    \paragraph{\underline{Upper Bound on $\mathbb{P}(Z > t)$}}
    Next we want to provide an upper bound on the tail of $Z$. Choose an $s \in (0, \underline{\lambda})$. We will optimize for $s$ later. Then we have that for $t > 1$,
    \begin{align*}
        \mathbb{P}(Z > t) &\stackrel{(a)}= \mathbb{P}(\exp(sZ) > \exp(st)) \stackrel{(b)}\leq \mathbb{E}[\exp(s Z)] \cdot \exp(-st) \stackrel{(c)}= \mathbb{E}[\exp(s\Tilde{X})] \mathbb{E}[\exp(s\Tilde{Y}) ] \exp(- st),
    \end{align*}
    where $(a)$ follows from the fact that $\exp(sx)$ is strictly increasing, $(b)$ follows from Markov's inequality and $(c)$ follows from the fact that $Z = \tilde{X} + \tilde{Y}$ and  $\tilde{X}$ and $\tilde{Y}$ are independent.

    We will now show that there exists constants $c^\prime_X = c(\epsilon, t_0, c_X)$ and $c^\prime_Y = c(\epsilon, t_0, c_Y)$ such that 
    \begin{align}
        \label{eq:mgf-upper-bound}
        \mathbb{E}\left[ \exp(s \tilde{X})\right] \leq c_X^\prime \left(1 - \frac{s}{\lambda_{\tilde{X}}} \right)^{-1}, \ \ \mathbb{E}\left[ \exp(s \tilde{Y}) \right] \leq c_Y^\prime \left( 1 - \frac{s}{\lambda_{\tilde{Y}}}\right)^{-1}.
    \end{align}
    We will show this for $\mathbb{E}[\exp(s \tilde{X})]$ and the steps for $\mathbb{E}[\exp(s \tilde{Y})]$ will follow analogously. Further, we will assume that $t_0 > \max\{1, (1 + \epsilon)c_X\}$. If $t_0 < \max\{1, (1 + \epsilon) c_X\}$, the analysis will require trivial modifications. We have that 

    \begin{align*}
        \mathbb{E}[\exp(s\tilde{X})] &\stackrel{(a)}= \int_{0}^\infty \mathbb{P}(\exp(s \tilde{X}) > t) dt, \\
        &\stackrel{(b)}= 1 + \int_{1}^\infty \mathbb{P}( \tilde{X} > \ln t / s) dt, \\
        &\stackrel{(c)}\leq 1 + \int_{1}^{t_0} 1 dt + \int_{t_0}^\infty (1 + \epsilon) c_{X} \exp( - (\lambda_{X} / s(1 - \rho)) \ln t) dt , \\
        &\stackrel{(d)}\leq  t_0 + (1 + \epsilon) c_{X} \int_{1}^\infty \exp(- (\lambda_X / s(1 - \rho)) \ln t) dt, \\
        &\stackrel{(e)}=  t_0 + (1 + \epsilon) c_X \frac{1}{(\lambda_X / (s (1 - \rho))) - 1}, \\
        &\stackrel{(f)}\leq \frac{c^\prime}{(\lambda_X / (s (1 - \rho))) - 1},
    \end{align*}
    where $(a)$ follows from tail sum formula for expectation \citep{durrett2019probability}, $(b)$ follows from the fact that $\mathbb{P}(\exp(s\Tilde{X}) > t) = \mathbb{P}(\tilde{X} > \ln t / s)$, $(c)$ follows from \ref{eq:tail-bound-exponential-X}, $(d)$ follows trivally, $(e)$ follows from the fact that $\int_{1}^\infty \exp(- (\lambda_X / s(1 - \rho)) \ln t) dt = \frac{s(1 - \rho)}{\lambda_X - s(1 - \rho)}$, $(f)$ follows from an appropriate choice of $c^\prime$.

    Therefore, we have that
    \begin{align*}
        \mathbb{P}(Z > t) &\stackrel{(a)}\leq c_{X}^\prime c_{Y}^\prime \exp\left(-st - \ln \left(1 - \frac{s }{\lambda_{\tilde{X}}} \right) - \ln \left( 1 - \frac{s}{\lambda_{\tilde{Y}}} \right) \right), \\
        &\stackrel{(b)}\leq c_X^\prime c_Y^\prime \exp\left( -st - \left( \frac{\underline{\lambda}}{\lambda_{\tilde{X}}} + \frac{\underline{\lambda}}{\lambda_{\tilde{Y}}} \right) \ln \left( 1 - \frac{s}{\underline{\lambda}}\right)\right), \\
        &\stackrel{(c)}= \exp(\underline{\lambda}) c_X^\prime c_Y^\prime t^{1 + (\bar{\lambda} / \underline{\lambda})} \exp(-\underline{\lambda} t),
    \end{align*}
    where $(a)$ follows from \eqref{eq:mgf-upper-bound}, $(b)$ follows from the fact that $-\ln\left(1 - \frac{s}{\lambda_{\tilde{X}}} \right) \leq - \frac{\underline{\lambda}}{\lambda_{\tilde{X}}} \ln \left( 1 - \frac{s}{\underline{\lambda}}\right)$ and $-\ln\left(1 - \frac{s}{\lambda_{\tilde{Y}}} \right) \leq - \frac{\underline{\lambda}}{\lambda_{\tilde{Y}}} \ln \left( 1 - \frac{s}{\underline{\lambda}}\right)$ and $(c)$ follows from choosing $s = (1 - 1/t) \underline{\lambda}$. Define $C = \exp(\underline{\lambda}) c_X^\prime c_Y^\prime$. Then we have that $\mathbb{P}(Z > t) \leq C t^{1 + (\bar{\lambda} / \underline{\lambda})} \exp(-\underline{\lambda} t)$. 


    \paragraph{\underline{Lower Bound on $\mathbb{P}(Z > t)$}}
    Next we want to provide a lower bound on the tail of $Z$. 
    Define $L = \tilde{X} \mathbbm{1}\{\lambda_{\tilde{X}} < \lambda_{\tilde{Y}}\} + \tilde{Y} \mathbbm{1}\{\lambda_{\tilde{X}} > \lambda_{\tilde{Y}}\}$. Let $\underline{c} = \min\{c_X, c_Y\}$.
    For all $t \geq t_0$, we have that, 
    \begin{align*}
        \mathbb{P}(Z > t) &\stackrel{(a)}\geq \mathbb{P}(L > t) \stackrel{(b)}\geq (1 - \epsilon) \underline{c} \exp(- \underline{\lambda} t) := c \exp(-\underline{\lambda} t)
    \end{align*}

    Using \ref{eq:maximum-tail-expression}, for all $t \geq t_0$, we have that 
    \begin{align}
        \label{eq:maximum-tail-upper-lower-bound-exponential-tail}
        1 - (1 - c \exp(-\underline{\lambda}t))^n \leq \mathbb{P}(Z_{(n:n)} > t) \leq 1 - (1 - Ct^{1 + (\bar{\lambda} / \underline{\lambda})} \exp(-\underline{\lambda}t ))^n 
    \end{align}
    Choose a $\delta \in (0, \underline{\lambda})$. There exists $t_0^\prime$ such for all $t \geq t_0^\prime$, we have that $t^{1 + \bar{\lambda} / \underline{\lambda}} \leq \exp(\delta t)$. Therefore, we have that 
    \begin{align}
        \label{eq:maximum-tail-upper-lower-bound-exponential-tail-2}
        1 - (1 - c \exp(-\underline{\lambda}t))^n \leq \mathbb{P}(Z_{(n:n)} > t) \leq 1 - (1 - C \exp(-(\underline{\lambda} - \delta) t))^n 
    \end{align}
    Using the analysis in the proof of Proposition \ref{prop:expected-maximum-n-exponential-tail}, we have that
    \begin{align*}
        \frac{1}{\underline{\lambda}} \leq \liminf_{n \to \infty} \frac{\mathbb{E}[Z_{(n:n)}]}{\ln n} \leq \limsup_{n \to \infty} \frac{\mathbb{E}[Z_{(n:n)}]}{\ln n} \leq \frac{1}{\underline{\lambda} - \delta}
    \end{align*}
    Since this set of inequalities is true for all $\delta \in (0,\underline{\lambda})$, we have that $\lim_{n \to \infty} \frac{\mathbb{E}[Z_{(n:n)}]}{\ln n} = \frac{1}{\underline{\lambda}} = \max\{\lambda_X / (1 -  \rho), \lambda_Y / \rho \}$. This completes the proof.
\end{proof}


\subsection{Proof of Theorem \ref{thm:uncapacitated-exponential}}
\label{app:proof-thm-uncapacitated-exponential}

\begin{proof}[\underline{Proof of Theorem \ref{thm:uncapacitated-exponential-a}}]
    Recall from the proof of Theorem \ref{thm:uncapacitated-pareto-a}, we have that $\Delta^{\sf uncap}_{ \emptyset \to q}(n) = ( 1 - \rho) \mathbb{E}[q_{(n:n)}] - (1 - \rho) \mu_q$.
    Now using Proposition \ref{prop:expected-maximum-n-exponential-tail}, the result follows.
\end{proof}


\begin{proof}[\underline{Proof of Theorem \ref{thm:uncapacitated-exponential-b}}]
 Define $Z_k = (1 - \rho) q_{k} + \rho \varphi_{k}$. We have that 
 \begin{align*}
     \frac{\Delta_{q \to u}^{\sf uncap}(n)}{\ln n } &= \frac{\mathbb{E}[Z_{(n:n)}]}{ \ln n} - \frac{(1 - \rho) \mathbb{E}[q_{(n:n)}]}{\ln n} - \frac{\rho \mu_\varphi}{\ln n}
 \end{align*}
 Now using Propositions \ref{prop:expected-maximum-n-exponential-tail} and \ref{prop:convex-comb-exponential-tails-bound}, the result follows.
\end{proof}

\subsection{Proof of Theorem \ref{thm:capacitated-exponential}}
\label{app:proof-thm-capacitated-exponential}
\begin{proof}[\underline{Proof of Theorem \ref{thm:capacitated-exponential-a}}]
    The proof of Theorem \ref{thm:capacitated-exponential-a} mimics the proof of Theorem \ref{thm:capacitated-pareto-a} and hence is omitted. 
\end{proof}

\begin{proof}[\underline{Proof of Theorem \ref{thm:capacitated-exponential-b}}]   
    The proof of Theorem \ref{thm:capacitated-exponential-b} will make use of Lemma \ref{lem:upper-lower-bound-capacitated-quality-full-info-diff} and Proposition \ref{prop:expected-maximum-n-exponential-tail}. Let us denote $\varphi_{k,(n -k : n - k)} := \varphi_{(n - k: n - k)}$. Fix $\epsilon > 0$. There exists an $k_0 \in \mathbb{N}$ such that for all $k \geq k_0$, we have that 
    \begin{align}
        \label{eq:upper-lower-bound-max-exponential}
        (1 - \epsilon) \ln k / \lambda \leq \mathbb{E}[\varphi_{(k:k)}] \leq (1 + \epsilon) \ln k / \lambda
    \end{align}
    Recall that $\Phi_n \triangleq n^{-1} \sum_{k = 1}^n \mathbb{E}[\varphi_{(k:k)}]$. We can upper bound $\Phi_n$ as follows:
    \begin{align*}
        \Phi_n &\stackrel{(a)}= \frac{1}{n} \sum_{k = 1}^{k_0} \mathbb{E}[\varphi_{(k:k)}] + \frac{1}{n} \sum_{k = k_0}^{n} \mathbb{E}[\varphi_{(k:k)}], \\
        &\stackrel{(b)}\leq \mu_{\varphi} \frac{k_0(k_0 + 1)}{2n} + \frac{1}{n} (1 + \epsilon) / \lambda \sum_{k = k_0}^n \ln k , \\
        &\stackrel{(c)}\leq \mu_{\varphi} \frac{k_0 (k_0 + 1)}{2n} + \frac{1}{n} (1 + \epsilon) / \lambda \int_{1}^n \ln x \, dx, \\
        &\stackrel{(d)}\leq \mu_{\varphi} \frac{k_0 (k_0 + 1)}{2n} + (1 + \epsilon) \ln n / \lambda,
    \end{align*}
    where $(a)$ follows trivially, $(b)$ follows from \eqref{eq:upper-lower-bound-max-exponential} and the fact that $\mathbb{E}[\varphi_{(k:k)}] \leq k \mu_\varphi$ for all $k \leq k_0$ since $\mathbb{E}[\max\{X_1, X_2, \dots, X_k\}] \leq \mathbb{E}\left[ \sum_{j = 1}^k X_j \right] = k \mu_{\varphi}$, $(c)$ follows trivially and $(d)$ follows from the fact that $\int \ln x dx = x \ln x - x$. Using this, we have that 
    \begin{align*}
        \limsup_{n \to \infty} \frac{\Phi_n}{\ln n / \lambda} \leq 1 + \epsilon. 
    \end{align*}
    Using similar arguments as above, we can easily show that 
    \begin{align*}
        \liminf_{n \to \infty} \frac{\Phi_n}{\ln / \lambda} \geq 1 - \epsilon.
    \end{align*}
    Since this holds for all $\epsilon > 0$, combining the two, we have that $\lim_{n \to \infty} \frac{\Phi_n}{\ln n / \lambda} = 1$ and this completes the proof. 
\end{proof}

\section{(Partial) Results for bounded utility distributions}
\label{app:bdd-distribution}
In this section, we discuss the case where the common and the idiosyncratic terms are drawn from bounded distributions $P_q$ and $P_\varphi$. For simplicity we will assume that both the distributions $P_q$ and $P_{\varphi}$ are continuous distributions with density bounded below and above over the interval $[a,b]$, where $a \geq 0$ and $b < \infty$.



\begin{theorem}[Capacitated Supply, Bounded Distribution]
    \label{thm:capacitated-bdd-distribution}
     Consider the capacitated supply setting. Assume that the common terms $(q_y)$ are drawn i.i.d from a continuous distribution $P_q$ with support $[a,b]$, finite mean $\mu_q < \infty$. Assume that the idiosyncratic terms $(\varphi_{xy})$ are drawn i.i.d from a continuous distribution $P_\varphi$ with support $[a,b]$, finite mean $\mu_\varphi < \infty$. For any $\rho \in [0,1]$, we have that,
     \begin{enumerate}[label = $(\thetheorem.\alph*)$]
        \item \label{thm:capacitated-bdd-a} The difference in the agent welfare $\Delta_{\emptyset \to q}^{\sf cap}(n)$ obtained in the {\sf Only Quality Information} regime and the {\sf No Information} regime is given as  
        \begin{align*}
            \lim_{n \to \infty} {\Delta^{\sf cap}_{\emptyset \to q}(n)} = 0.
        \end{align*}

        \item \label{thm:capacitated-bdd-b} The difference in the agent welfare $\Delta_{q \to u}^{\sf cap}(n)$ obtained in the {\sf Full Information} regime and {\sf Only Quality Information} regime is
        \begin{align*}
           \lim_{n \to \infty} {\Delta^{\sf cap}_{q \to u}(n)} = \rho \cdot (b - \mu_\varphi).
        \end{align*}
    \end{enumerate}
\end{theorem}

\begin{proof}
    \underline{Proof of Theorem \ref{thm:capacitated-bdd-a}.} The proof follows the same argument as the proof of Theorem \ref{thm:capacitated-pareto-a}.

    \underline{Proof of Theorem \ref{thm:capacitated-bdd-b}.}The proof follows from Lemma \ref{lem:upper-lower-bound-capacitated-quality-full-info-diff} and the fact that $\lim_{n \to \infty} \Phi_n = b$.
\end{proof}

\begin{remark}
    In Theorem \ref{thm:capacitated-bdd-b}, we provide an upper and lower bound on the asymptotic marginal welfare gain of personalizing recommendations. From Figure \ref{fig:uniform-capacitated-b}, we observe that there is a gap between the upper and lower bounds for the case of bounded distribution. In general, it is a challenging problem to provide a crisp characterization for the marginal welfare gains of personalizing recommendations and as such we defer this question for future research.
\end{remark}

