It is interesting to compare our conjecture with the work of Kowalski \cite{MR3144176}, where he proves explicit very small bounds for the spectral gap of families of Cayley graphs of $\operatorname{SL}_2 \mathbb{F}_p$. See \cite{MR4418463} for more recent results.

There is also a direct link between Selberg's conjecture and spectra of Cayley graphs of $\operatorname{SL}_2 \mathbb{F}_p$, see Helfgott \cite{MR3348442} section 5.5 for a discussion and references for this connection.

We now describe our main result.

Let $\mathcal{L}$ be the (normalized) Laplacian on $\Gamma$, which is a self-adjoint bounded linear operator in the Hilbert space $\ell^2(G)$ defined by

\begin{equation}\label{Laplacian_G}
(\mathcal{L} f)(x)=f(x)-\frac{1}{2}f(xa)-\frac{1}{4}f(xb)-\frac{1}{4}f(xb^{-1}),\quad \forall x\in G.
\end{equation}
The heat kernel of $\Gamma$ is the exponential of the Laplacian, $h_t=e^{-t\mathcal{L}}$. The invariance of $\Gamma$ under left translations implies that
the heat kernel is described in terms of a function $k_t\colon G\to \R$ through the formula
\begin{equation}\label{heat_kernel_det}
(h_tf)(x)=\sum_{y\in G}k_t(y^{-1}x)f(y),\quad f\in \ell^2(G).
\end{equation}
Denote by $|x|$  the shortest word length of $x\in G$, and define the map
$\pi\colon G\to\Z$
by 
\begin{equation}\label{CY_proj}
 \pi(x)=
\begin{cases} 
0 & \text{if $x=e$} \\
 |x| & \text{if the reduced form of $x$ starts with letters $b^{\pm1}$} \\
 -|x| & \text{if the reduced form of $x$ starts with letter $a$}.
\end{cases}
\end{equation}

\begin{theorem} \label{K1}
The function $k_t$ determining the heat kernel in~\eqref{heat_kernel_det} is given by
${k}_t(x)=K_t(\pi(x))$, where, for $n\in\Z$,
\begin{equation} \label{eqK1}
 K_t(n)= e^{-t\frac{3}{4}} \alpha_n +e^{-t\frac{7}{4}} \beta_n + \int_0^\pi e^{-t(\frac{7}{8}-\frac{R_s}{2})}\gamma_n^-(s) \mathrm{d}s + \int_0^\pi e^{-t(\frac{7}{8}+\frac{R_s}{2})}\gamma_n^+(s) \mathrm{d}s,
\end{equation}
where the coefficients $\alpha_n,\beta_n$ and $\gamma^{\pm}_n(s)$ are defined depending on the sign and the parity of $n$. In the formulas with double lines below, the first line corresponds to even $n=2m$, and the second line to odd $n=2m+1$.

For $n\ge0$,
$$
\alpha_n= \frac{(-1)^{\left\lceil\frac{n}{2}\right\rceil}2^{- \left\lceil\frac{n}{2}\right\rceil }}{6},
\quad
\beta_n=\frac{(-1)^n 2^{- \left\lceil\frac{n}{2}\right\rceil }}{6},
$$
%$$
%\gamma_n^{\pm}(s) = \frac{\sqrt{2}^{-\left\lceil\frac{n}{2}\right\rceil} \sin s}{\pi (1+8\sin^2 s)}
%\begin{cases}
%\big(\mp\frac{1}{R_s}(\sqrt{2}+\cos s)-4\cos s\big) \sin ms + 4\sin (m+1)s \\ 
%\pm\frac{2}{R_s}(2+\sqrt{2}\cos s) \sin ms + \big(\sqrt{2}\mp\frac{1}{R_s}(\frac{9\sqrt{2}}{4}+4\cos s)\big) \sin (m+1)s, 
%\end{cases}
%$$
$$
\gamma_n^{\pm}(s) = \frac{\sqrt{2}^{-\left\lceil\frac{n}{2}\right\rceil} \sin(s)}{\pi R_s(1+8\sin^2(s))}
\begin{cases}
\mp(\sqrt{2}+\cos(s)) \sin(ms) + 4R_s\sin(s) \cos(ms) \\ 
\pm(4+2\sqrt{2}\cos(s)) \sin(ms) + \big(\sqrt{2}R_s\mp(\frac{9\sqrt{2}}{4}+4\cos(s))\big) \sin((m+1)s), 
\end{cases}
$$
and, for $n<0$,
$$
\alpha_n= \frac{(-1)^{\left\lceil\frac{n}{2}\right\rceil}}{6},
\quad
\beta_n=\frac{(-1)^n }{6},
$$
$$
\gamma_n^{\pm}(s)=\frac{\sqrt{2}^{-\left\lceil\frac{n}{2}\right\rceil} \sin(s)}{\pi R_s (1+8\sin^2(s))} 
\begin{cases}
\pm(\sqrt{2}+\cos(s)) \sin(ms) + 4R_s\sin(s)\cos(ms) \\
\pm(4+2\sqrt{2}\cos(s)) \sin(ms) - \big(\sqrt{2}R_s\pm(\frac{9\sqrt{2}}{4}+4\cos(s))\big) \sin((m+1)s), 
\end{cases} 
$$
where 
\begin{equation}\label{R_s}
R_s=\sqrt{\frac{25}{16}+\sqrt{2}\cos(s)}.
\end{equation}
\end{theorem}
Note that expression \eqref{eqK1} simplifies greatly for $n=0$.
Using the limiting values $s=0$ and $s=\pi$ in the formula for $R_s$, we can describe the spectrum of the Laplacian on $\Gamma$.
\begin{corollary}
 The spectrum of the Laplacian $\mathcal{L}$ on $\Gamma$ is the following closed subset of $\R$, see Fig.~\ref{fig:specL}:
$$
\operatorname{Sp}(\mathcal{L})=\Big[\lambda_0,\frac74-\lambda_1\Big]\sqcup\Big\{\frac{3}{4}\Big\}\sqcup\Big[\lambda_1,\frac74-\lambda_0\Big]\sqcup\Big\{\frac{7}{4}\Big\} 
$$
where
$$
\lambda_0=\frac78-\frac12\sqrt{\frac{25}{16}+\sqrt{2}}=0.01234\dots,\quad \lambda_1=\frac78+\frac12\sqrt{\frac{25}{16}-\sqrt{2}}=1.0675\dots.
$$
\end{corollary}

This corollary should be compared with Theorem 1 from Cartwright--Soardi in \cite{MR820357}, where they treat the general free product of two cyclic groups. However, note that our Laplacian is somewhat different, as we consider double edges for the generator $a=a^{-1}$. The nature of the methods is very different; unlike their work, our technique is through spectral problem resolution. Magee pointed out to us that the use of the $R$-transform and free probability provides another approach to determining the spectrum.

{\bf Outline.} 
Section~\ref{sec2} contains basics of weighted graphs: their definition, their morphisms etc. 
In Section~\ref{sec3}, we give the definition of a covering of weighted graphs and provide a geometric insight into this notion by defining quotient weighted graphs on the basis of groups of automorphisms of graphs. Then, we prove Proposition~\ref{Prop2}, the main contribution of this section, that reduces the verification of a map to be a covering to a group theoretical problem. 
In Section~4, we describe Chung--Yau's result on the relations between the heat kernels of two weighted graphs if one covers another strongly and regularly, with finite fibers.
Finally, in section~5, we present our explicit formula for the heat kernel of the Cayley graph of $\operatorname{PSL}_2\Z$, given by the presentation $\langle a,b\mid a^2=1,  b^3=1\rangle$, that we have obtained through Chung--Yau covering approach.

\section{Basics of weighted graphs}\label{sec2}
We start by defining the basics of weighted graphs.
\begin{definition}
 A \textit{weighted graph} is a set of \textit{vertices} $V$ provided with a non-negative symmetric \textit{weight function} 
 $$
 w\colon V\times V\to \R_{\geq 0},\quad w(u,v)=w(v,u)\quad \forall u,v \in V.
 $$
 By abuse of notation, sometimes we will not distinguish between a weighted graph $(V,w)$ and its underlying set of vertices $V$ when the weight function $w$ is clear from the context, so that we simply write $V$ instead of $(V,w)$.

 In a weighted graph, an \textit{edge} is a pair of vertices with strictly positive weight. 

 The \textit{degree} of a vertex $u\in V$ is defined as 
 $$
 d_u=\sum_{v\in V}w(u,v).
 $$

 We say that a graph $V$ is \textit{$k$-regular} if $d_u=k$, $\forall u\in V$.
\end{definition}
\begin{remark}
 Any usual unoriented graph is a weighted graph where $w(u,v)$ is the number of edges joining $u$ and $v$.
\end{remark}

\begin{remark}
 Any metric space is a weighted graph, where the weight function is the distance. 
\end{remark}


\begin{remark}
 In this work, unless otherwise specified, we assume that all graphs are connected, which means that for all $u,v\in V$, there exists a sequence of edges connecting $u$ and $v$. Consequently, this means that for all $u\in V$, $d_u\neq0$.
\end{remark}


Now that we have defined the objects, we proceed to define their morphisms.
\begin{definition}
 A \textit{morphism} from a weighted graph $(V_1,w_1)$ to a weighted graph $(V_2,w_2)$, is a map $f\colon V_1\to V_2$ such that $f^{-1}(v)$ is a finite set for any $v\in V_2$ and which is compatible with the weight functions, in the sense that
 $$
 w_2(a,b)=\sum_{\substack{u\in f^{-1}(a)\\ v\in f^{-1}(b)}}w_1(u,v), \quad  \forall a,b \in V_2.
 $$
\end{definition}

\begin{definition}
 An \textit{automorphism} of a weighted graph $V$ is a morphism $f\colon V\to V$ which is a bijection. 
 The set of all automorphisms of a weighted graph $(V,w)$ is a group, denoted by $\operatorname{Aut}(V,w)$. 
\end{definition}

\begin{remark}
The assumption that all graphs are connected implies that all morphisms of weighted graphs are surjective.
\end{remark}

\section{Coverings of weighted graphs}\label{sec3}
In this section, we rework some of the results from~\cite{MR1667452} for coverings with finite fibers and present a general group theoretical approach to quotient graphs.
\subsection{Definition and properties}
We start by defining coverings of weighted graphs.
\begin{definition}
A morphism of weighted graphs $\pi \colon (\tilde{V},\tilde{w})\to (V,w)$ is called a \textit{covering of weighted graphs} 
if,  for all $x,y\in \tilde{V}$, such that $\pi(x)=\pi(y)$ and for all $u\in V$,
 \begin{equation}\label{equiv-covering}
\sum_{z\in \pi^{-1}(u)}\tilde{w}(z,x)=\sum_{z'\in \pi^{-1}(u)}\tilde{w}(z',y).
\end{equation}
  If such a covering exists, we say that $(\tilde{V},\tilde{w})$ \textit{covers} $(V,w)$. 
\end{definition} 

\begin{remark}
 This definition is a special case of a more general definition given in~\cite{MR1667452}.
\end{remark}
We note that this is not a covering in the topological sense since the preimages (fibers) of vertices can have different sizes. However, a topological covering with finite fibers is a special case of this more general notion of covering.

We also define a more specific class of coverings, which will exhibit useful properties in the subsequent analysis.

\begin{definition}
Given two weighted graphs $(\tilde{V},\tilde{w})$ and $(V,w)$. We say $(\tilde{V},\tilde{w})$ \textit{covers} $(V,w)$ \textit{strongly} and \textit{regularly} if there exists a vertex $u_0\in V$, called \textit{distinguished vertex}, such that, for any vertex $x\in \tilde{V}$ there exists a covering of weighted graphs  $\pi \colon (\tilde{V},\tilde{w})\to (V,w)$ such that $\pi^{-1}(u_0)=\{x\}$.
\end{definition}

The following proposition provides an equivalent definition of the notion of a covering of weighted graphs.
\begin{proposition} 
\label{Prop1}
 A morphism of weighted graphs $\pi\colon(\tilde{V},\tilde{w})\to(V,w)$ is a covering of weighted graphs  
 if and only if
 \begin{equation}
   \label{eq1}
   \sum_{z\in \pi^{-1}(u)}\tilde{w}(z,x)=\frac{1}{\vert\pi^{-1}(\pi(x))\vert}w(u,\pi(x)) \quad \forall x\in\tilde{V},\  \forall u\in V.
  \end{equation}


\end{proposition}

\begin{proof}
Suppose that $\pi$ is a covering of weighted graphs. 
 Property~\eqref{equiv-covering} is equivalent to say that the sum $\sum_{z\in \pi^{-1}(u)}\tilde{w}(z,x)$, as a function of $x$, only depends on $\pi(x)$.
This implies that in the equality (corresponding to the fact that $\pi$ is a morphism of weighted graphs)
 $$
 \sum_{x\in \pi^{-1}(v)} \sum_{z\in \pi^{-1}(u)}\tilde{w}(z,x)=w(u,v),
 $$
the internal sum, as a function of $x$, only depends on $\pi(x)=v$. Thus, we can replace $x$ in the argument of $\tilde{w}$ by any fixed element $x_0$ in $\pi^{-1}(v)$. Therefore, the effect of the outer sum is the multiplication by the number of terms which is $\vert\pi^{-1}(v)\vert$:
 $$
  \quad \vert\pi^{-1}(v)\vert\sum_{z\in \pi^{-1}(u)}\tilde{w} (z,x_0)=w(u,v) 
 $$
 which coincides with formula \eqref{eq1} if we identify $x$ with $x_0$ and take into account the fact that $v=\pi(x_0)$.

 Conversely, property \eqref{equiv-covering} follows from the fact that the left-hand side of equation \eqref{eq1} depends on $x$ only through $\pi(x)$. 
\end{proof}

We note that the degrees of the vertices of a graph $V$ and a covering graph $\tilde V$ are not necessarily equal. However, the following lemma illustrates how they are related.
\begin{lemma}
 Let $(\tilde{V},\tilde{w})$ and $(V,w)$ be two weighted graphs such that $(\tilde{V},\tilde{w})$ covers $(V,w)$.
 Then, the following relation between degrees in $\tilde{V}$ and $V$ holds
 \begin{equation}\label{degree}
 \tilde{d}_x=\frac{1}{\vert\pi^{-1}(\pi(x))\vert}d_{\pi(x)}, \quad\forall x\in \tilde{V}.
 \end{equation}
 In particular, $\tilde{d}_x=\tilde{d}_y$ if $\pi(x)=\pi(y)$.
\end{lemma}

\begin{proof}
Let $x\in\tilde{V}$. Using the definition of degree of a vertex and equation~\eqref{eq1} we have 
$$
\tilde{d}_x  =\sum_{y\in\tilde{V}}\tilde{w}(x,y) = \sum_{u\in V}\sum_{y\in\pi^{-1}(u)}\tilde{w}(x,y) = \sum_{u\in V}\frac{1}{\vert\pi^{-1}(\pi(x))\vert}w(\pi(x),u) = \frac{1}{\vert\pi^{-1}(\pi(x))\vert}d_{\pi(x)}.
$$
\end{proof}

\subsection{Quotient weighted graphs}
Here we establish a result which allows to reduce the verification of the property of a covering to a group theoretical problem, which can often facilitate verifications by using a geometrical argument.

\begin{definition}
 Let $(\tilde{V},\tilde{w})$ be a weighted graph and $G\subset \operatorname{Aut}(\tilde{V},\tilde{w})$ a subgroup such that the orbit $Gx$ of $x$ is a finite set for any $x\in\tilde{V}$. The \textit{quotient weighted graph} of the weighted graph $(\tilde{V},\tilde{w})$ with respect to the group $G$ is a weighted graph $(V,w)$  defined as

\begin{equation} \label{qgraph}
 V=\tilde{V}/G, \quad w(u,v)=\sum_{\substack{x\in u\\ y\in v}}\tilde{w}(x,y) \quad \forall u,v\in V.
\end{equation}
\end{definition}

 Before stating our result, we recall the following group theoretical fact, which will be needed in the proof.
\begin{lemma}[Orbit-stabilizer theorem]
Let a group $G$ act on a set $X$. Then, for any $x\in X$, the orbit $Gx=\{gx\mid g\in G\}$ is in bijection with the set of cosets for the stabilizer subgroup $G/H_x:=\{gH_x\mid g\in G\}$, where $H_x:=\{h\in G\mid hx=x\}\subset G$ is the stabilizer subgroup of $x$.
\end{lemma}

\begin{proposition}
\label{Prop2}
 Let $(\tilde{V},\tilde{w})$ be a weighted graph, $G\subset \operatorname{Aut}(\tilde{V})$ a subgroup such that the orbit $Gx$ of $x$ is a finite set for any $x\in\tilde{V}$ and $(V,w)$ the \textit{quotient weighted graph} of the weighted graph $(\tilde{V},\tilde{w})$ with respect to the group $G$. Then, the canonical projection map to the quotient space $\pi\colon\tilde{V}\to V$ is a covering of weighted graphs.
\end{proposition}

\begin{proof}
 Let $x\in\tilde{V}$, $H_x:=\{h\in G\mid hx=x\}\subset G$ the \textit{stabilizer} subgroup of $x$, $v=\pi(x)$, $u\in V$ and $s\colon G/H_x\to G$ a map such that $s(\alpha)H_x=\alpha$, $\forall\alpha\in G/H_x$ (this means that a representative $s(\alpha)$ is chosen in each coset $\alpha=gH_x$).

 Then,
\begin{align*}
    w(u,v) & =\sum_{\substack{z\in u\\ x'\in v}}\tilde{w}(z,x') & \text{by def. of $w$}  \\
    & =\sum_{\substack{z\in u \\ \alpha\in G/H_x}}\tilde{w}(z,s(\alpha)x) & \text{using the bijection $G/H_x\to Gx=v$} \\
    & = \sum_{\substack{z\in u \\ \alpha\in G/H_x}}\tilde{w}({s(\alpha)}^{-1}z,x) & \text{since $s(\alpha)$ is an automorphism of $\tilde{V}$} \\
    & =\sum_{\alpha\in G/H_x}\sum_{z'\in u}\tilde{w}(z',x) & \text{substituting $s(\alpha)^{-1}z$ by $z'$} \\ 
    & =\vert G/H_x\vert \sum_{z'\in u}\tilde{w}(z',x) & \text{since the internal sum is independent of $\alpha$} \\
    & =\vert v\vert\sum_{z\in u}\tilde{w}(z,x) & \text{using $\vert G/H_x\vert=\vert v \vert$ and substituting $z'$ by $z$}\\ 
\end{align*}
 which, by taking into account the tautological equalities $u=\pi^{-1}(u)$ and $v=\pi^{-1}(v)$, is exactly formula~\eqref{eq1}.
\end{proof}


\section{Spectrum of the Laplacian and coverings}
\subsection{The Laplacian matrix}
In this section, we describe a result from~\cite{MR1667452} that allows us to determine the eigenvalues of a covering graph through the eigenvalues of the graph it covers, provided the covering is strong and regular. 

The \emph{matrix coefficients} $A(u,v)$ of a linear map (operator) $A\colon \C^V \to \C^V$ are defined by 
$$
(Af)(u)=\sum_{v\in V}A(u,v)f(v).
$$

\begin{definition} 
 Given a weighted graph $(V,w)$ the \textit{combinatorial Laplacian} of $(V,w)$ is a linear map $\Delta \colon \C^V \to \C^V$ defined by 
  \begin{equation}\label{laplacian}
(\Delta f)(v)=\sum_{u\in V}(f(v)-f(u))w(u,v).
\end{equation}
Its matrix coefficients $\Delta(u,v)$ are given by 
 $$
 \Delta(u,v)=d_v\delta_{u,v}-w(u,v).
 $$

The \textit{normalized Laplacian} $\mathcal{L}$ of $(V,w)$ is an operator with the matrix coefficients  
\begin{equation}\label{normLaplacian}
  \mathcal{L}(u,v)=\frac{\Delta(u,v)}{\sqrt{d_ud_v}}=\delta_{u,v}-\frac{w(u,v)}{\sqrt{d_ud_v}}.
\end{equation}
 \end{definition}

\begin{remark}\label{rem_norm_lapl}
 We make the following observations:
\begin{itemize}
 \item The normalized Laplacian can be written as $\mathcal{L}=I-M$ where $I$ is the identity operator and $M$ has matrix coefficients 
\begin{equation} \label{mat_coeff_M}
 M(u,v)=\frac{w(u,v)}{\sqrt{d_ud_v}}.
\end{equation}
 \item  In the case of a $k$-regular graph $V$, we have
 $
 \Delta=k\mathcal{L}.
 $
\end{itemize}
\end{remark}

\subsection{The heat kernel}
We start by defining the heat kernel of a graph. 

\begin{definition}\label{ht}
 Given a weighted graph $(V,w)$, the \textit{heat kernel} $h_t$ of $(V,w)$ is an operator defined for $t\geq 0$ as 
 $$
 h_t=e^{-t\mathcal{L}}=\sum_{k=0}^{\infty}\frac{(-t)^k}{k!}\mathcal{L}^k.
 $$
\end{definition}
The basic problem is to determine the matrix coefficients $h_t(x,y)$ of the heat kernel.
\begin{remark}
For a Cayley graph $\Gamma(G)$ of a group $G$, the invariance of $\Gamma(G)$ under left translations implies that $h_t(x,y)=k_t(y^{-1}x)$, where $k_t(x):=h_t(x,e)$. In this case, the problem of determining the matrix coefficients of the heat kernel is reduced to the problem of determining the function $k_t(x)$.

 The function $k_t\colon G\to\C$ 
is the unique solution of the following differential equation with initial condition
\begin{equation}\label{hk}
 \begin{cases} 
      \frac{\partial}{\partial{t}}k_t=-\mathcal{L}k_t \\
      k_0(x)=\delta_{e,x}.
\end{cases}
\end{equation}

\end{remark}

By Remark~\ref{rem_norm_lapl}, we write $\mathcal{L}=I-M$, where $I$ is the identity operator and $M$ is the operator $M$ having matrix coefficients given in \eqref{mat_coeff_M}, so that
 $$
 h_t=e^{-t\mathcal{L}}=e^{-t(I-M)}=e^{-t}e^{tM}=e^{-t}\sum_{k=0}^{\infty}\frac{t^k}{k!}M^k.
 $$


\begin{lemma}\label{M} Assume  that $(\tilde{V},\tilde{w})$ covers $(V,w)$.
Then, for any $k\in\Z_{\ge0}$, any $u,v\in V$ and any $y\in\pi^{-1}(v)$, one has the equality
 \begin{equation}\label{meq}
\sum_{x\in\pi^{-1}(u)}\tilde M^k(x,y)=\sqrt{\frac{\vert\pi^{-1}(u)\vert}{\vert\pi^{-1}(v)\vert}}M^k(u,v).
\end{equation}
\end{lemma}
\begin{proof}
By taking into account the fact that $\tilde M^0$ and $M^0$ are the identity operators, equality~\eqref{meq} with $k=0$ is verified as follows
\begin{align*}
 \sum_{x\in\pi^{-1}(u)}\tilde M^0(x,y) & = \sum_{x\in\pi^{-1}(u)}\delta_{x,y}=\delta_{u,\pi(y)}=\delta_{u,v}\\
 & =\sqrt{\frac{\vert\pi^{-1}(u)\vert}{\vert\pi^{-1}(v)\vert}}\delta_{u,v}=\sqrt{\frac{\vert\pi^{-1}(u)\vert}{\vert\pi^{-1}(v)\vert}}M^0(u,v).
\end{align*}
Let us show that the case  $k=1$ follows from equation~\eqref{eq1}
$$
\sum_{z\in\pi^{-1}(u)}\tilde w(z,x)=\frac{1}{|\pi^{-1}(\pi(x))|}w(u,\pi(x)),\quad \forall u\in V,\ \forall x\in\tilde V
$$
and equation~\eqref{degree}
$$
\tilde d_x=\frac{1}{\vert\pi^{-1}(\pi(x))\vert}d_{\pi(x)},\quad \forall x\in\tilde V.
$$
Indeed,
\begin{align*}
 \sum_{x\in\pi^{-1}(u)}\tilde M(x,y) & = \sum_{x\in\pi^{-1}(u)}\frac{\tilde w(x,y)}{\sqrt{\tilde d_x\tilde d_y}} & \text{by def. of $\tilde{M}$}\\
 & = \frac{\sqrt{|\pi^{-1}(u)||\pi^{-1}(v)|}}{\sqrt{d_ud_v}}\sum_{x\in\pi^{-1}(u)}\tilde w(x,y) & \text{by \eqref{degree}}\\
 & = \frac{\sqrt{|\pi^{-1}(u)||\pi^{-1}(v)|}}{\sqrt{d_ud_v}}\frac{1}{|\pi^{-1}(v)|}w(u,v) & \text{by \eqref{eq1}}\\
 & = \sqrt{\frac{\vert\pi^{-1}(u)\vert}{\vert\pi^{-1}(v)\vert}}M(u,v).\\
\end{align*}
Now, we proceed by induction. Assume that equality~\eqref{meq} is satisfied for all $k\in\{0,1,\dots,r\}$ for $r\ge1$. Then, we have
\begin{align*}
 \sum_{x\in\pi^{-1}(u)}\tilde M^{r+1}(x,y) & = \sum_{x\in\pi^{-1}(u)}\sum_{z\in\tilde V}\tilde M^{r}(x,z)\tilde M(z,y) 
  = \sum_{z\in\tilde V}\Big(\sum_{x\in\pi^{-1}(u)}\tilde M^{r}(x,z)\Big)\tilde M(z,y)\\
 & = \sum_{z\in\tilde V}\sqrt{\frac{\vert\pi^{-1}(u)\vert}{\vert\pi^{-1}(\pi(z))\vert}}M^r(u,\pi(z))\tilde M(z,y) \\
 & = \sum_{a\in V}\sqrt{\frac{\vert\pi^{-1}(u)\vert}{\vert\pi^{-1}(a)\vert}}M^r(u,a)\sum_{z\in\pi^{-1}(a)}\tilde M(z,y) \\
 & = \sum_{a\in V}\sqrt{\frac{\vert\pi^{-1}(u)\vert}{\vert\pi^{-1}(a)\vert}}M^r(u,a)\sqrt{\frac{\vert\pi^{-1}(a)\vert}{\vert\pi^{-1}(v)\vert}}M(a,v)\\
 & = \sqrt{\frac{\vert\pi^{-1}(u)\vert}{\vert\pi^{-1}(v)\vert}}\sum_{a\in V}M^r(u,a)M(a,v)
  = \sqrt{\frac{\vert\pi^{-1}(u)\vert}{\vert\pi^{-1}(v)\vert}}M^{r+1}(u,v)
\end{align*}
where, 
in the third equality, we used the induction hypothesis for $k=r$,
and in the fifth equality, we used formula~\eqref{meq} for $k=1$.
\end{proof}
\begin{proposition} \label{rel_covering_heat_kernel}
Assume that $(\tilde{V},\tilde{w})$ covers $(V,w)$ and let $\tilde{h}_t$ and $h_t$ denote the corresponding heat kernels. Then, the following holds for any $u,v\in V$ and $y\in\pi^{-1}(v)$
\begin{equation}\label{eq5}
\sum_{x\in\pi^{-1}(u)}\tilde{h}_t(x,y)=\sqrt{\frac{\vert\pi^{-1}(u)\vert}{\vert\pi^{-1}(v)\vert}}h_t(u,v).
\end{equation}
In particular, suppose that the covering is strong and regular. Choose a distinguished vertex $u_0\in V$ and a covering $\pi\colon\tilde{V}\to V$ such that $\pi(x)=u_0$ and $\pi^{-1}(u_0)=\{x\}$ (so that $\vert\pi^{-1}(u_0)\vert=1$). Then, we have, for any $v\in V$ and $y\in\pi^{-1}(v)$,
 \begin{equation}\label{eq6}
 \tilde{h}_t(x,y)=\frac{1}{\sqrt{\vert\pi^{-1}(v)\vert}}h_t(u_0,v)=\frac{1}{\sqrt{\vert\pi^{-1}(\pi(y))\vert}}h_t(\pi(x),\pi(y)).
 \end{equation}
\end{proposition}

\begin{proof}
Let $u,v\in V$ and $y\in\pi^{-1}(v)$. Then, using $h_t=e^{-t}\sum_{k=0}^{\infty}\frac{t^k}{k!}M^k$, we have 
\begin{align*}
 & \sum_{x\in\pi^{-1}(u)}\tilde{h}_t(x,y) \, = \, \sum_{x\in\pi^{-1}(u)}e^{-t}\sum_{k=0}^{\infty}\frac{t^k}{k!}\tilde{M}^k(x,y) \, = \, e^{-t}\sum_{k=0}^{\infty}\frac{t^k}{k!}\sum_{x\in\pi^{-1}(u)}\tilde{M}^k(x,y) \\
 & \quad \quad \quad = \, e^{-t}\sum_{k=0}^{\infty}\frac{t^k}{k!}\sqrt{\frac{\vert\pi^{-1}(u)\vert}{\vert\pi^{-1}(v)\vert}}M^k(u,v) \, = \, \sqrt{\frac{\vert\pi^{-1}(u)\vert}{\vert\pi^{-1}(v)\vert}}e^{-t}\sum_{k=0}^{\infty}\frac{t^k}{k!}M^k(u,v) \\
 & \quad \quad \quad = \, \sqrt{\frac{\vert\pi^{-1}(u)\vert}{\vert\pi^{-1}(v)\vert}}h_t(u,v)
\end{align*}
where, in the third equality we used Lemma \ref{M}.
\end{proof}

\section{The heat kernel of the Cayley graph $\Gamma(C_2*C_3)$}
In this section, we establish a formula for the heat kernel of the Cayley graph $\Gamma:=\Gamma(G)$ of the group $G=\operatorname{PSL}_2\Z\simeq C_2*C_3$ of the presentation $\langle a,b\mid a^2=1,  b^3=1\rangle$.
In identification with $\operatorname{PSL}_2\Z$, we can represent the generators by the matrices
$a=\left(\begin{smallmatrix} 0 & -1 \\ 1 & 0 \end{smallmatrix}\right)$ and $b=\left(\begin{smallmatrix} 0 & -1 \\ 1 & 1 \end{smallmatrix}\right)$.


